INSERT INTO public.reglas SELECT * FROM json_populate_record(NULL::public.reglas, '{"id":"objections.regla_de_los_no","paso":0,"tipo":"principio","canal":"universal","procedencia":"CAMPO","resumen":"La Regla de los No: tres ''no'' CONSECUTIVOS son luz roja (la fuente dice dos; Emilio usa tres, porque hay quien deja ir un sí solo porque el cliente tuvo objeciones). Con la luz roja, el vendedor sale rápido y bien: sin insistir, cuidando la relación y dejando una siguiente cita. Tienen que ser seguidos: si la conversación avanzó entre un no y otro, la racha se rompe. Salir así es la ejecución correcta, no una falta.","cita_cerebro":"dos no seguidos, luz roja, sigue adelante","severidad_default":null,"created_at":"2026-10-01T15:54:26.848512+00:00","updated_at":"2026-10-01T15:54:26.848512+00:00"}');
