INSERT INTO public.reglas SELECT * FROM json_populate_record(NULL::public.reglas, '{"id":"opening.ice_breaker","paso":1,"tipo":"requisito","canal":"universal","procedencia":"FUENTE","resumen":"Cumplido genuino, chiste sencillo o comentario ligero sobre la persona, el lugar o algo en común. Entregarlo como pregunta es la forma que permite al cliente responder y relajarse. La ligereza se juzga en lo que dice el vendedor —humor suave, un guiño o calidez en las palabras—, nunca por la reacción del cliente: un buen chiste que no le hace gracia a un cliente rojo o de mal humor se hizo bien. Especificidad y ligereza son cosas distintas: esta regla mide la ligereza; la especificidad la mide opening.especificidad.","cita_cerebro":"Cumplido genuino, chiste sencillo o comentario ligero. Puede ser sobre la persona, el lugar, o algo en común","severidad_default":null,"created_at":"2026-09-05T17:18:35.52861+00:00","updated_at":"2026-09-26T18:59:12.294819+00:00"}');
