INSERT INTO public.skills SELECT * FROM json_populate_record(NULL::public.skills, '{"id":"consolidation.rehash","code":"S-064","name":"El Rehash","short_description":"Despues del si, el impulso cae y aparece el arrepentimiento. Se disuelve manteniendo la misma postura de antes: indiferente sobre la compra, amigable sobre la relacion, disponible para lo que necesite. Nunca volviendo a vender.","category":"consolidation","world_id_introduced":6,"level_required":"rookie","parent_skill_id":null,"mastery_threshold":80,"reinforcement_threshold":50,"default_allowed_concepts":[],"default_forbidden_concepts":[],"success_signals":[],"failure_signals":[],"created_at":"2026-08-10T19:32:41.829451+00:00","skill_type":"tecnica","decay_half_life_days":180,"requires_audio":false,"status":"active","regla_id":"consolidation.rehash"}');
