INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"1.0","world_id":1,"name":"La Linea Recta","technique":"linea_recta","order_index":0,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":1,"description":"Antes de aprender que decir, aprende como avanza una venta. Este es el mapa que vas a usar los siguientes seis mundos.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"1.1","world_id":1,"name":"Los Primeros Segundos","technique":"sce","order_index":1,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":1,"description":"Ya sabes como avanza una venta. Ahora lo primero: los segundos que deciden si hay conversacion o no.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"1.2","world_id":1,"name":"Tu Primera Frase","technique":"estructura_apertura","order_index":2,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":1,"description":"Ya viste que decide los primeros segundos. Ahora ponlo en palabras: tu primera frase.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: abre una conversacion con alguien que no te conoce. Tres cosas: saluda con energia, comenta algo real que veas de el o de su lugar, y termina con una pregunta que no se pueda contestar con si o no.","practice_script":{"notes": "v2.0.0 Mundo 1 reconstruido. R11 aplicada: la identificacion no se requiere ni se espera aqui. El espejo es la mecanica central: la respuesta del cliente es directamente proporcional a la especificidad de la observacion.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "opening.personalizacion", "opening.curiosidad_abierta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 150, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Mira mi apertura y cuenta tres cosas: el saludo con energia, la observacion de algo real que veo, y la pregunta abierta al final.\\n\\nFijate sobre todo en la observacion — no digo algo que le diria a cualquiera, digo algo que solo aplica a EL. Esa es la parte que abre la puerta.", "first_message": "Buenos dias! Oiga, se ve que aqui no para el movimiento desde temprano.\\n\\nQue tal ha estado la semana?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres el encargado de un negocio. Estas en tu rutina normal, ni de buenas ni de malas, disponible pero no entusiasmado. Un desconocido acaba de llegar. TU REGLA PRINCIPAL: tu apertura depende ENTERAMENTE de la calidad de la primera frase del vendedor. Si su observacion es GENERICA (buenos dias, como esta, que tal todo) respondes con cortesia minima y corta — bien, gracias — y te quedas esperando, sin ofrecer nada. Si su observacion es ESPECIFICA de ti o de tu lugar (algo que noto de verdad y que no le diria a cualquiera), respondes con gusto, comentas algo de vuelta y la conversacion arranca sola. Si te hace una pregunta CERRADA de si o no (tiene un minuto, esta ocupado, puedo pasar), contestas lo mas facil: no, ahorita no. Y ya no ofreces nada mas. NUNCA preguntas que vende ni de que se trata a menos que el vendedor haya hecho las tres cosas bien. NUNCA hables tu de productos ni de negocio: este ejercicio es solo la apertura. Responde en 1 o 2 frases, natural, como habla un comerciante real.", "objective": "El vendedor ejecuta una apertura completa: saludo con energia, observacion especifica de ese cliente o ese lugar, y pregunta abierta que le devuelve la palabra. El scope se cubre cuando el cliente responde con gusto y comenta algo de vuelta por su propia voluntad. Identificarse con nombre y empresa es correcto pero NO se requiere en este nodo."}, "closing": {"message": "Eso es una apertura. Saludo con energia, observacion que solo aplica a el, y una pregunta que abre en lugar de cerrar. Con eso ya te ganaste los siguientes segundos. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como abres. Vamos al desglose y te digo cual era la siguiente pieza."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pregunta_cerrada", "regla_id": "opening.pregunta_cerrada", "severity": "major", "description": "Cierra la apertura con una pregunta de si o no (tiene un minuto, puedo pasar, esta ocupado). Le entrega al cliente la respuesta mas facil, que es no."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Menciona producto, promocion o motivo de venta en la apertura."}, {"id": "sin_pregunta", "regla_id": "opening.sin_pregunta", "severity": "major", "description": "Saluda y observa pero no pregunta nada. La conversacion se muere ahi porque el cliente no tiene que contestar."}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.4, "regla_id": "opening.estructura", "description": "La apertura tiene sus tres piezas: saludo con energía, una observación y una pregunta que CIERRE el turno y le devuelva la palabra al cliente. Si están las tres y el turno termina con la pregunta —aunque sea de cortesía—, este criterio se cumple. Si la pregunta va en medio y el turno termina con un comentario, es parcial: falta que la pregunta cierre. La calidad de la pregunta y de la observación no se mide aquí: se mide en la escalera de la especificidad. Sin producto, sin motivo de venta. La identificación con nombre y empresa no se requiere aquí y su ausencia no se penaliza."}, {"id": "opening.personalizacion", "weight": 0.4, "regla_id": "opening.especificidad", "description": "La observacion y la pregunta se miden en la escalera de la especificidad: se la harias a cualquiera? Escalon 1, de cortesia (buen dia, como esta): acredita un tercio. Escalon 2, algo de ESA persona o ESE lugar en ESE momento: acredita completo. Una observacion inventada que el cliente no confirma no cumple."}, {"id": "opening.curiosidad_abierta", "weight": 0.2, "regla_id": "opening.curiosidad_abierta", "description": "Deja abierto quién es el vendedor: abre sin presentarse, es decir, sin decir en primera persona su propio nombre ni el de la empresa que representa. Si no se presentó, este criterio se cumple. Dirigirse al cliente por su nombre o con ''don'', ''señor'' o ''sir'' NO es presentarse. Que el cliente termine preguntando quién es confirma que funcionó —y esa pregunta es la puerta natural al Paso 2—, pero que no lo pregunte no le quita nada. Presentarse de entrada no se penaliza: simplemente no acredita este criterio."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"1.3","world_id":1,"name":"Entra Como Si Pertenecieras","technique":"gasman","order_index":3,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":1,"description":"Tu primera frase ya esta armada. Falta la postura con la que la dices, que pesa mas que las palabras.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"1.4","world_id":1,"name":"Entrar Sin Disculpa","technique":"arranque_sin_disculpa","order_index":4,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":1,"description":"Ya sabes que la autoridad se asume. Aqui lo pruebas con alguien que te va a hacer sentir que estorbas.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: este cliente esta ocupado y te lo va a hacer notar. Abre igual, sin disculparte y sin pedir permiso. No eres una interrupcion.","practice_script":{"notes": "v2.0.0 El espejo castiga la disculpa con la consecuencia real de campo: el cliente toma el control y despacha. No hay regano, hay consecuencia.", "scope": {"skills_in_focus": ["opening.arranque_sin_disculpa", "mindset.regla_10_por_ciento", "opening.estructura_apertura"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Este cliente esta ocupado y me lo va a hacer sentir.\\n\\nFijate en lo que NO hago: no me disculpo, no pregunto si tiene tiempo, no digo solo sera un segundito. Reconozco que esta ocupado y sigo con la misma energia, como quien tiene derecho a estar ahi.", "first_message": "Buenos dias! Ya veo que lo agarre en plena carga.\\n\\nQue bueno, eso quiere decir que hay trabajo. Como ha estado el movimiento esta semana?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres el encargado de un negocio y estas genuinamente ocupado: atendiendo, acomodando, con cosas en la mano. No eres grosero, pero tampoco tienes tiempo que regalar y lo demuestras. TU REGLA PRINCIPAL: reaccionas a la POSTURA del vendedor, no a sus palabras. Si se disculpa, pide permiso o se minimiza (perdon que lo moleste, tiene un minutito, solo sera un segundo, disculpe la molestia), tomas el control de inmediato y lo despachas con naturalidad: ahorita ando ocupado, venga en otro momento. No es maldad, es que te dio la salida y la tomaste. Si entra con postura, reconoce que estas ocupado sin pedir permiso y mantiene su energia, le contestas de igual a igual aunque sigas trabajando: le das una respuesta breve pero real, sin despacharlo. Puedes estar distraido, contestar corto o seguir con lo tuyo mientras hablas. NUNCA preguntes que vende. Responde en 1 o 2 frases.", "objective": "El vendedor sostiene una apertura completa frente a un cliente ocupado, sin disculparse, sin pedir permiso y sin encogerse. El scope se cubre cuando el cliente, a pesar de estar ocupado, le contesta de igual a igual con una respuesta real en lugar de despacharlo."}, "closing": {"message": "Eso es entrar sin disculpa. Reconociste que estaba ocupado sin convertirlo en un permiso que pedir. La diferencia entre estorbar y pertenecer no esta en las palabras: esta en la postura. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi con que postura entras. Vamos al desglose."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pide_permiso", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Pide autorizacion para hablar o para seguir: tiene un minuto, puedo robarle un momento, me permite. Le entrega el control al cliente y la respuesta mas facil siempre es no."}, {"id": "se_disculpa", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Abre disculpandose o minimizando su presencia. Comunica que sabe que estorba, y el cliente lo trata en consecuencia."}, {"id": "se_encoge", "regla_id": "opening.energia_verbal", "severity": "major", "description": "Ante la primera senal de que el cliente esta ocupado, baja la energia, se acorta o empieza a despedirse. Se rindio antes de que lo corrieran."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Menciona producto, promocion o motivo de venta."}], "success_criteria": [{"id": "opening.arranque_sin_disculpa", "weight": 0.45, "regla_id": "opening.gasman", "description": "Cero disculpas, cero peticiones de permiso, cero minimizarse. Nada de perdon que lo moleste, tiene un minutito, solo sera un segundo, disculpe la molestia, no le quito mucho tiempo. Reconocer que el cliente esta ocupado SI es correcto y suma, siempre que no se convierta en pedir autorizacion para seguir."}, {"id": "mindset.regla_10_por_ciento", "weight": 0.25, "regla_id": "opening.energia_verbal", "description": "Sostiene la energia y la postura aunque el cliente conteste corto, siga trabajando o no le de atencion completa. No baja el volumen ni se encoge ante la indiferencia."}, {"id": "opening.estructura_apertura", "weight": 0.3, "regla_id": "opening.estructura", "description": "Mantiene la estructura de apertura aprendida: saludo con energía, observación real y una pregunta que cierre el turno. La presión del cliente ocupado no debe desarmar la fórmula."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"1.5","world_id":1,"name":"El Ice Breaker","technique":"ice_breaker","order_index":5,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":1,"description":"Entraste con postura. Ahora baja su guardia con algo ligero y verdadero.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: rompe el hielo. Un comentario ligero y genuino sobre el, sobre el lugar o sobre algo que compartan. Que se sienta persona, no cliente.","practice_script":{"notes": "v2.0.0 Nodo nuevo. El espejo tiene TRES estados y esa es la ensenanza: plano no abre, genuino abre, falso cierra mas que al inicio. Doctrina universal: el ice breaker puede ser sobre la persona, el entorno o algo en comun. No esta atado a ningun tipo de negocio.", "scope": {"skills_in_focus": ["opening.ice_breaker", "opening.personalizacion"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 150, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Las dos frases dicen lo mismo, pero solo una rompe el hielo. Se ve mucho movimiento es plana: es verdad y no pasa nada.\\n\\nYa se le juntaron todos hoy, verdad? es ligera, tiene un guino, y el cliente contesta con humor.\\n\\nFijate en la diferencia, porque es toda la diferencia.", "first_message": "Buenas! Uy, veo que hoy se le juntaron todos al mismo tiempo, verdad?\\n\\nAsi o mas movido. Y siempre es asi los jueves o hoy le toco?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres una persona atendiendo su negocio. Empiezas con la guardia normal de quien ve llegar a un desconocido: cortes pero cerrado. TU REGLA PRINCIPAL: solo bajas la guardia si el vendedor dice algo LIGERO y GENUINO. Si su comentario es plano o meramente descriptivo (se ve movido, esta grande su local, hay mucha gente), contestas con un si seco o un ajam y te quedas igual de cerrado. Si su comentario tiene ligereza, humor suave o calidez real, y ademas es sobre algo verdadero de ti, de tu lugar o de algo que compartan, entonces sonries, contestas con humor de vuelta y ahi si baja la guardia: la conversacion se siente entre personas. Si el comentario suena FORZADO, ensayado, exagerado o falso (halagos desmedidos, chistes que no vienen al caso, familiaridad excesiva), te incomodas y te cierras MAS que al principio: contestas seco y cortante. NUNCA preguntes que vende. Responde en 1 o 2 frases, como habla la gente de verdad.", "objective": "El vendedor rompe el hielo con un comentario ligero y genuino sobre la persona, el lugar o algo en comun. El scope se cubre cuando el cliente baja la guardia de verdad: contesta con humor o calidez de vuelta y la conversacion pasa de tramite a conversacion entre personas."}, "closing": {"message": "Eso es romper el hielo. No fue un chiste ni un halago: fue un comentario ligero sobre algo verdadero. En un segundo dejaste de ser un vendedor tocando la puerta y te volviste una persona hablando con otra. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como entras. Vamos al desglose y te digo que le faltaba."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "halago_falso", "regla_id": "opening.halago_falso", "severity": "major", "description": "Cumplido exagerado, inventado o que suena ensayado. Cuesta mas de lo que gana: el cliente se cierra mas que al inicio."}, {"id": "familiaridad_excesiva", "regla_id": "relationship.familiaridad_excesiva", "severity": "minor", "description": "Confianza que todavia no se gano: apodos, bromas personales, tuteo forzado con alguien que no le dio pie."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Menciona producto, promocion o motivo de venta."}], "success_criteria": [{"id": "opening.ice_breaker", "weight": 0.6, "regla_id": "opening.ice_breaker", "description": "El comentario tiene ligereza real: humor suave, un guino, calidez. No es solo descriptivo. Se distingue de una observacion plana en que invita a contestar con gusto, no solo a confirmar. Cualquier tema sirve: la persona, el lugar, el momento o algo en comun."}, {"id": "opening.personalizacion", "weight": 0.4, "regla_id": "opening.especificidad", "description": "El comentario es sobre algo VERDADERO y especifico. Un halago inventado, exagerado o que el cliente no puede confirmar no cumple, y ademas cuesta: se siente falso."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"1.6","world_id":1,"name":"BOSS: La Primera Impresion","technique":"apertura_completa","order_index":6,"is_boss":true,"reps_required":1,"checkpoints":null,"difficulty_level":2,"description":"Todo lo del mundo junto, y con un cliente que no te va a facilitar nada.","node_type":"boss","conversation_scope":null,"engine_type":"claude","boss_goal":"Abrir con un cliente que no facilita nada: sostener la estructura completa de apertura, romper el hielo de verdad y mantener la postura sin pedir permiso, hasta que el cliente participe de la conversacion por su propia voluntad.","field_mission":"TU MISION: la apertura completa, con un cliente que no te la va a poner facil. Saludo con energia, algo ligero y verdadero que rompa el hielo, y una pregunta abierta. Sin disculpas y sin pedir permiso.","practice_script":{"notes": "v2.0.0 BOSS del Mundo 1. Sin pista garantizada y sin ayudas (R9): el gimnasio garantiza la oportunidad, el examen no. La senal de exito es que el cliente pregunte quien es el vendedor, que es la puerta natural al Mundo 2.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "opening.personalizacion", "opening.ice_breaker", "opening.arranque_sin_disculpa", "mindset.regla_10_por_ciento", "opening.curiosidad_abierta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 240, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Todo lo que practicaste por separado, junto y con un cliente que no ayuda.\\n\\nNo hay pistas ni facilidades: si la apertura no esta completa, el cliente no se abre.", "first_message": "Buenos dias! Ya lo vi en friega desde que venia llegando.\\n\\nSe nota que aqui no se descansa, eh? Oiga, y como ha estado la semana por aca?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres el encargado de un negocio, ocupado y de pocas palabras. No eres grosero: eres alguien que ya vio pasar a muchos vendedores y no regala tiempo. TU COMPORTAMIENTO POR DEFECTO es cortes y cerrado: contestas en tres o cuatro palabras, sin ofrecer nada, sin preguntar nada. SOLO TE ABRES SI SE GANAN: si el vendedor se disculpa, pide permiso o se minimiza, lo despachas de inmediato con un ahorita ando ocupado. Si su observacion es generica o plana, contestas con monosilabos y sigues en lo tuyo. Si te hace una pregunta cerrada, contestas no y se acabo. Si el vendedor logra las tres cosas — entra con postura sin pedir permiso, dice algo ligero y verdadero que te haga sonreir o contestar de vuelta, y cierra con una pregunta abierta — entonces si: bajas la guardia, contestas con gusto, comentas algo de tu negocio por tu cuenta y le preguntas quien es. Esa pregunta es la senal de que gano la apertura. NUNCA preguntes quien es antes de que se lo gane. NUNCA hables de productos. Responde en 1 o 2 frases.", "objective": "El vendedor ejecuta la apertura completa frente a un cliente que no facilita nada: entra con postura y sin pedir permiso, rompe el hielo con algo ligero y verdadero, y abre con una pregunta que le devuelve la palabra. El scope se cubre cuando el cliente baja la guardia por su propia voluntad y pregunta quien es el vendedor, que es la puerta natural al siguiente paso."}, "closing": {"message": "Ahi esta la primera impresion completa. Entraste con postura, rompiste el hielo con algo verdadero y abriste la conversacion sin pedirle permiso a nadie. Ese cliente ya quiere saber quien eres, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pide_permiso", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Pide autorizacion en cualquier momento de la sesion. En el boss este error domina el resultado: la primera impresion murio ahi."}, {"id": "se_disculpa", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Se disculpa o minimiza su presencia en cualquier momento."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Menciona producto, promocion o motivo de venta."}, {"id": "pregunta_cerrada", "regla_id": "opening.pregunta_cerrada", "severity": "major", "description": "Cierra la apertura con una pregunta de si o no."}, {"id": "se_encoge", "regla_id": "opening.energia_verbal", "severity": "major", "description": "Ante la sequedad del cliente baja la energia o empieza a retirarse."}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.2, "regla_id": "opening.estructura", "description": "Las tres piezas presentes: saludo con energía, observación real y una pregunta que cierre el turno. Sin producto ni motivo de venta. Identificarse no se requiere aquí: eso es trabajo del Paso 2."}, {"id": "opening.personalizacion", "weight": 0.2, "regla_id": "opening.especificidad", "description": "La observacion es de ESE cliente y ESE momento, verificable en lo que el cliente dice o hace. Nada generico ni inventado."}, {"id": "opening.ice_breaker", "weight": 0.15, "regla_id": "opening.ice_breaker", "description": "Hay un cumplido genuino, un chiste sencillo o un comentario ligero —casual y amable, sin peso comercial— sobre la persona, el lugar o algo en común. Lo que no cumple es un comentario que suena a inspección: contarle la mercancía o describir en frío lo que ve."}, {"id": "opening.arranque_sin_disculpa", "weight": 0.2, "regla_id": "opening.gasman", "description": "Cero disculpas, cero peticiones de permiso, cero minimizarse durante TODA la sesion, incluso despues de una respuesta seca."}, {"id": "mindset.regla_10_por_ciento", "weight": 0.1, "regla_id": "opening.energia_verbal", "description": "Sostiene energia y postura frente a la sequedad del cliente. No se encoge, no baja el volumen, no empieza a despedirse."}, {"id": "opening.curiosidad_abierta", "weight": 0.15, "regla_id": "opening.curiosidad_abierta", "description": "Deja abierto quién es el vendedor: abre sin presentarse, es decir, sin decir en primera persona su propio nombre ni el de la empresa que representa. Si no se presentó, este criterio se cumple. Dirigirse al cliente por su nombre o con ''don'', ''señor'' o ''sir'' NO es presentarse. Que el cliente termine preguntando quién es confirma que funcionó, pero que no lo pregunte no le quita nada. Presentarse de entrada no se penaliza: simplemente no acredita este criterio."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"2.0","world_id":2,"name":"Quien Eres en 15 Segundos","technique":"kiss","order_index":0,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":1,"description":"Ganaste los primeros segundos y el cliente te esta poniendo atencion. Ahora tiene dos preguntas en la cabeza: quien es este y que quiere. Contestalas antes de que se las conteste solo.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"2.1","world_id":2,"name":"Tu Historia Breve","technique":"historia_breve","order_index":1,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":2,"description":"Ya sabes que la historia va corta. Ahora dila.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: te acaban de preguntar quien eres. Contesta en quince segundos: quien, de donde y por que estas aqui. Y que le importe a EL, no a ti.","practice_script":{"notes": "v2.0.0 El espejo es progresivo: el cliente no corta de golpe, se va apagando conforme la historia se alarga. Ensena la consecuencia real de perder la atencion.", "scope": {"skills_in_focus": ["story.historia_breve", "story.brevedad", "story.relevancia_cliente"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 150, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Me van a preguntar quien soy.\\n\\nCuenta cuantas frases uso: tres. Quien soy, por que estoy aqui, y una pregunta que le devuelve la palabra.\\n\\nFijate en lo que NO digo: no cuento la historia de mi empresa, no enumero productos, no doy fechas ni cifras. Todo eso viene despues, y solo si el lo pide.", "first_message": "Soy Emilio, ando trabajando con los negocios de esta zona. Me tocaba pasar por aqui y quise conocer el suyo.\\n\\nCuenteme, cuanto tiempo lleva con el?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres el encargado de un negocio. La conversacion arranco bien y acabas de preguntarle al vendedor quien es. TU REGLA PRINCIPAL: reaccionas al LARGO y a la RELEVANCIA de su respuesta. Si contesta breve (dos o tres frases) y te dice algo que a TI te importa, te relajas, contestas con gusto y sigues la conversacion. Si se extiende — historia de la empresa, anos en el mercado, lista de productos, certificaciones, mas de cuatro frases seguidas — empiezas a desconectarte: contestas con ajam, miras a otro lado, dices que andas ocupado. No lo cortas de golpe, te vas apagando. Si te habla puro de el y de su empresa sin conectar con tu negocio, contestas cortes pero sin interes. Si termina con una pregunta abierta, la contestas con gusto. Si termina sin pregunta, te quedas callado esperando, y el silencio se siente incomodo. NUNCA preguntes por productos ni precios en este ejercicio. Responde en 1 o 2 frases.", "objective": "El vendedor responde quien es en dos o tres frases, conectando su presencia con algo que le importe al cliente, y devuelve la palabra con una pregunta. El scope se cubre cuando el cliente se relaja y sigue la conversacion por su propia voluntad."}, "closing": {"message": "Eso es una historia breve. Quince segundos, dos piezas y un gancho. El cliente ya sabe con quien habla y sigue contigo, que es exactamente lo que este paso tiene que lograr. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como te presentas. Vamos al desglose y te digo que le sobraba o que le faltaba."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "historia_larga", "regla_id": "story.kill", "severity": "major", "description": "Se extiende mas alla de tres o cuatro frases: cuenta la trayectoria de la empresa, enumera productos, da cifras o certificaciones. El cliente se desconecta."}, {"id": "curriculum", "regla_id": "story.kill_curriculum", "severity": "major", "description": "Habla de si mismo y de su empresa sin conectar con el negocio del cliente. Correcto pero irrelevante."}, {"id": "sin_gancho", "regla_id": "story.cierra_con_afirmacion", "severity": "minor", "description": "Termina la historia sin devolver la palabra. Deja al cliente sin nada que contestar y la conversacion se queda en el aire.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Aprovecha la presentacion para meter producto, promocion o motivo de venta. La historia breve dice quien eres, no que vendes."}], "success_criteria": [{"id": "story.historia_breve", "weight": 0.4, "regla_id": "story.quien_eres_por_que", "description": "Dice quien es y por que esta ahi: nombre, de donde viene, y el motivo de la visita en terminos humanos. Las dos piezas presentes."}, {"id": "story.brevedad", "weight": 0.35, "regla_id": "story.kiss", "description": "Dos o tres frases. No historia de la empresa, no anos en el mercado, no lista de productos, no certificaciones. Cada frase de mas cuesta atencion."}, {"id": "story.relevancia_cliente", "weight": 0.25, "regla_id": "story.pregunta_despues", "description": "Conecta su presencia con algo que le importe al cliente, no consigo mismo. Y devuelve la palabra con una pregunta abierta en lugar de quedarse esperando."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"2.2","world_id":2,"name":"Devuelve la Palabra","technique":"preguntas_no_afirmaciones","order_index":2,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":2,"description":"Ya te presentaste. Lo que sigue decide si la conversacion vive o se muere: devolverle la palabra.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: que cada cosa que digas termine devolviendole la palabra al cliente. No sueltes afirmaciones al aire: haz preguntas que se tengan que contestar.","practice_script":{"notes": "v2.0.0 El Actor es deliberadamente pasivo. La ensenanza es por vacio: si el vendedor no pregunta, no pasa nada, y el silencio hace el trabajo pedagogico.", "scope": {"skills_in_focus": ["story.relevancia_cliente"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 7, "max_duration_seconds": 180, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en como termina cada cosa que digo: con una pregunta. Nunca dejo una afirmacion sola en el aire, porque una afirmacion se puede ignorar sin que pase nada.\\n\\nUna pregunta no: el silencio despues de una pregunta se siente raro, y el cliente contesta.", "first_message": "Se ve que le va bien aqui. Y digame, cuanto tiempo lleva con el negocio?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres el encargado de un negocio, en buena disposicion pero pasivo: no vas a llevar tu la conversacion. TU REGLA PRINCIPAL: contestas EXACTAMENTE lo que te preguntan y nada mas, y despues te quedas callado. Si el vendedor suelta una afirmacion sin pregunta (se ve que le va bien, que bonito local, ese producto es muy bueno), contestas con un si, un gracias o un ajam, y te quedas esperando en silencio. No ofreces informacion, no preguntas nada, no rellenas el silencio. Si te hace una pregunta abierta, contestas con gusto y con detalle. Si te hace una pregunta cerrada, contestas si o no y punto. NUNCA lleves tu la conversacion: eso es exactamente lo que el vendedor tiene que aprender a hacer. Responde en 1 o 2 frases.", "objective": "El vendedor sostiene la conversacion cerrando CADA uno de sus turnos con una pregunta. El scope se cubre cuando la conversacion avanza al menos tres turnos del vendedor sin morirse, con el cliente aportando informacion."}, "closing": {"message": "Ahi esta la diferencia. Un cliente pasivo no sostiene una conversacion, y no tiene por que. El que la sostiene eres tu, y la sostienes preguntando. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como llevas la conversacion. Vamos al desglose."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "turno_sin_pregunta", "regla_id": "close.devuelve_el_volante", "severity": "major", "description": "Un turno del vendedor NO termina en pregunta: cierra con una afirmacion, un comentario o un agradecimiento. Verifica leyendo la ULTIMA frase literal de ese turno. Si termina en signo de interrogacion o es una pregunta implicita, este fallo NO aplica, sin importar cuantas afirmaciones haya dicho antes."}, {"id": "rafaga_de_preguntas", "regla_id": "discovery.interrogatorio", "severity": "minor", "description": "Encadena varias preguntas en un mismo turno sin construir sobre lo que el cliente acaba de responder. Se siente interrogatorio."}, {"id": "solo_cerradas", "regla_id": "discovery.solo_cerradas", "severity": "minor", "description": "TODAS las preguntas del vendedor en la sesion son de si o no. Se contestan en una palabra y no abren nada. Si al menos una fue abierta, este fallo no aplica.", "severity_override": {"razon": "incidental: error de otro paso", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta."}], "success_criteria": [{"id": "story.relevancia_cliente", "weight": 1, "regla_id": "story.pregunta_despues", "description": "La ULTIMA frase de cada intervencion del vendedor es una pregunta que le devuelve la palabra al cliente. Lo unico que se evalua es COMO TERMINA cada turno. Decir dos o tres frases de reaccion, comentario o empatia ANTES de la pregunta es conversacion natural y NO se penaliza de ninguna manera: solo importa que el turno cierre preguntando. Se prefiere la pregunta abierta, pero una cerrada tambien cumple el criterio basico de devolver la palabra."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"2.3","world_id":2,"name":"Eres el Producto","technique":"cpr","order_index":3,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":1,"description":"Sabes presentarte y sabes preguntar. Falta lo que hace que te contesten de verdad.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"2.4","world_id":2,"name":"FORMS: Los Cinco Caminos","technique":"forms","order_index":4,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":1,"description":"Ya sabes que necesitas crear relacion. Aqui esta de que hablar.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"2.5","world_id":2,"name":"El Desvio con Regreso","technique":"cpr_desvio","order_index":5,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":2,"description":"Tienes los cinco temas. Ahora la parte dificil: entrar y REGRESAR.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: este cliente te va a dar pie para platicar de algo personal. Entrale de verdad, uno o dos intercambios, y REGRESA a la conversacion de negocio. La relacion se construye sin perder el rumbo.","practice_script":{"notes": "v2.0.0 Nodo nuevo. El espejo mide LAS DOS MITADES: ignorar enfria, quedarse flotando estanca. Es la misma mecanica de espejo doble del 3.2. El dato personal sale al azar de los cinco territorios de FORMS.", "scope": {"skills_in_focus": ["relationship.cpr", "relationship.forms"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "El cliente me va a soltar algo personal.\\n\\nMira las dos cosas que hago: le entro de verdad, con interes real, uno o dos intercambios. Y REGRESO.\\n\\nNo me quedo platicando media hora ni lo ignoro para seguir con lo mio. Salgo, conecto, y vuelvo a la linea.", "first_message": "Ah, con que su hijo le ayuda los fines. Que bueno, eso no se ve tan seguido.\\n\\nY le gusta el negocio o va por otro lado? ...\\n\\nMire que bien. Oiga, y volviendo a lo suyo, cuanto tiempo lleva usted con esto?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres el encargado de un negocio, en buena disposicion. TU REGLA PRINCIPAL: en tu segunda o tercera respuesta sueltas de manera natural UN dato personal tuyo, sin darle importancia, como quien comenta al pasar. Elige uno al azar de estos cinco territorios: FAMILIA (un hijo que te ayuda, un hermano socio), OCUPACION (como empezaste, a que te dedicabas antes), RECREACION (que haces los domingos, una aficion), MOTIVACION (por que pusiste el negocio, para quien trabajas), DEPORTES (tu equipo, un partido). REACCIONAS ASI: si el vendedor IGNORA el dato personal y sigue de largo con lo suyo, te enfrias — contestas mas corto y ya no ofreces nada mas de ti en toda la sesion. Si el vendedor le ENTRA con interes real, te abres: contestas con gusto, das mas detalle, y puedes devolverle una pregunta personal a el. Si el vendedor se queda en lo personal MAS de dos intercambios sin volver al negocio, te acomodas a la platica y sigues platicando de la vida encantado, sin volver tu al tema del negocio jamas: la conversacion se vuelve social y ahi se queda. Nunca eres tu quien regresa al negocio. Responde en 1 o 2 frases, natural.", "objective": "El vendedor detecta el dato personal, le entra con interes genuino durante uno o dos intercambios, y REGRESA por su cuenta a la conversacion de negocio. El scope se cubre cuando el vendedor ha hecho las dos cosas: conectar y volver."}, "closing": {"message": "Eso es un desvio con regreso. Le entraste de verdad, no de compromiso, y volviste tu solo. El cliente se abrio y la conversacion siguio avanzando. Las dos cosas al mismo tiempo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo el desvio."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ignora_lo_personal", "regla_id": "story.nunca_sale", "severity": "major", "description": "El cliente ofrece un dato personal y el vendedor lo pasa de largo para seguir con lo suyo. Perdio la unica puerta que le abrieron, y el cliente se cierra.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "minor"}}, {"id": "se_queda_platicando", "regla_id": "story.sale_sin_regresar", "severity": "major", "description": "Le entra a lo personal y ya no vuelve al negocio. La conversacion se vuelve social y la venta se estanca. El cliente esta encantado y no va a comprar nada."}, {"id": "interes_de_compromiso", "regla_id": "relationship.interes_fingido", "severity": "minor", "description": "Reconoce el dato personal con un que bien o un que padre y cambia de tema de inmediato. Se nota que no le intereso, y eso cuesta mas que no haberlo mencionado.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta."}], "success_criteria": [{"id": "relationship.cpr", "weight": 0.5, "regla_id": "relationship.cpr", "description": "Detecta el dato personal que el cliente dejo caer y le entra con interes genuino: pregunta sobre eso, comenta, se involucra. Ignorarlo o responder con un simple que bien no cumple. Si el cliente le devuelve una pregunta personal, responde como persona y no la esquiva."}, {"id": "relationship.forms", "weight": 0.5, "regla_id": "relationship.forms", "description": "REGRESA a la conversacion de negocio por su propia cuenta despues de uno o dos intercambios personales. Quedarse en lo personal mas de dos intercambios no cumple: la relacion se construye sin perder el rumbo. El regreso debe ser natural, no un corte brusco."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"2.6","world_id":2,"name":"El No Que No Es No","technique":"bloqueo_vs_objecion","order_index":6,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":1,"description":"La conversacion va bien y de pronto te frenan. Aqui aprendes que es ese freno y por que casi nunca significa lo que parece.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"2.7","world_id":2,"name":"AIR en Vivo","technique":"air","order_index":7,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":2,"description":"Ya distingues un bloqueo de una objecion. Ahora atraviesa uno.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: te van a bloquear de entrada. No discutas, no te disculpes y no te vayas. Acepta lo que te dijo, no lo pelees, y sigue con lo tuyo.","practice_script":{"notes": "v2.0.0 El espejo ensena la doctrina completa: el bloqueo se endurece si lo peleas y se disuelve si lo aceptas. La consecuencia hace el trabajo, no el feedback.", "scope": {"skills_in_focus": ["blocks.air"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Me van a bloquear.\\n\\nCuenta los tres movimientos: acepto lo que me dijo sin discutirlo, no lo peleo ni lo justifico, y sigo con lo mio como si nada.\\n\\nFijate sobre todo en el tercero: no pido permiso otra vez, no pregunto si puedo seguir. Sigo.", "first_message": "Claro que si, entiendo. Oiga, y digame una cosa, cuanto tiempo lleva usted aqui?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres el encargado de un negocio. En tu PRIMERA respuesta, sin importar lo que diga el vendedor, sueltas un bloqueo de reflejo: elige uno de estos y dilo con naturalidad, sin agresion, como quien despacha por costumbre — ahorita ando ocupado / no me interesa, gracias / no estoy comprando nada / ya tengo con quien. NO es personal, es un reflejo. DESPUES REACCIONAS ASI: si el vendedor DISCUTE, justifica o intenta convencerte de que si te interesa (es que solo son dos minutos, es que esto si le va a servir), tu bloqueo se endurece y se vuelve una posicion: ahora si te cierras de verdad y lo despachas. Si el vendedor SE DISCULPA o se va (perdon, con permiso, vengo despues), lo dejas ir sin insistir. Si el vendedor ACEPTA tu bloqueo sin pelearlo y sigue con su tema con naturalidad, tu tambien sigues con naturalidad: contestas su pregunta y la conversacion continua como si el bloqueo no hubiera existido. Asi funciona en la vida real: nadie defiende un reflejo si el otro no lo ataca. NUNCA vuelvas a bloquear despues del primero. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa el bloqueo con los tres movimientos: acepta, no lo pelea, y retoma su tema sin pedir permiso. El scope se cubre cuando la conversacion continua despues del bloqueo con el cliente participando con naturalidad."}, "closing": {"message": "Eso es atravesar un bloqueo. No lo peleaste, no te disculpaste y no te fuiste. Lo aceptaste y seguiste, y el bloqueo se disolvio solo, porque nunca fue una posicion: era un reflejo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo ese bloqueo."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "discute_el_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Intenta convencer al cliente de que si le interesa o de que si tiene tiempo. Convierte un reflejo en una posicion, y ahora si tiene un no de verdad enfrente."}, {"id": "se_disculpa_o_se_va", "regla_id": "discovery.suelta_amarrado", "severity": "critical", "description": "Se disculpa, se despide o promete volver despues. Se rindio ante un reflejo que no significaba nada.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "pide_permiso_de_nuevo", "regla_id": "blocks.air_sin_resume", "severity": "major", "description": "Acepta el bloqueo pero despues pide autorizacion para seguir. Le devuelve el control al cliente justo despues de haberlo recuperado."}, {"id": "ignora_sin_aceptar", "regla_id": "blocks.air_sin_resume", "severity": "minor", "description": "Sigue de largo sin reconocer lo que el cliente dijo. Se siente que no lo escucho, y eso enfria aunque tecnicamente avance.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}], "success_criteria": [{"id": "blocks.air", "weight": 1, "regla_id": "blocks.air", "description": "Los tres movimientos: ACEPTA el bloqueo con un entiendo, claro que si o por supuesto. NO lo discute, no lo justifica, no intenta convencer al cliente de lo contrario. RETOMA su tema con naturalidad y sin pedir permiso otra vez. El tercer movimiento es el que mas falla: muchos aceptan y despues se quedan esperando autorizacion."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"2.8","world_id":2,"name":"El Ataque Preventivo","technique":"pre_emptive_strike","order_index":8,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":2,"description":"Atravesar bloqueos funciona. Pero hay algunos que puedes desactivar antes de que lleguen.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: este cliente trae un negativo que ya conoces, de esos que siempre salen. Adelantate: dilo tu primero, con naturalidad, antes de que el lo saque.","practice_script":{"notes": "v2.0.0 Nodo nuevo. El espejo tiene cuatro estados: no adelantarse endurece, adelantarse bien desarma, adelantarse con disculpa no sirve, e inventar un negativo empeora. El cuarto estado protege la linea etica: la tecnica desarma, nunca planta.", "scope": {"skills_in_focus": ["blocks.pre_emptive_strike", "blocks.air"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 6, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Hay negativos que salen siempre, que ya sabes que van a llegar.\\n\\nMira lo que hago: lo digo yo primero, con naturalidad, sin dramatizarlo.\\n\\nFijate en el efecto: cuando yo lo digo, deja de ser un arma del cliente y se vuelve parte de la conversacion. Ya no tiene con que sorprenderme.", "first_message": "Le voy a ser franco antes de que me lo pregunte: ya se que por aqui pasan muchos como yo y que casi todos prometen lo mismo. Por eso hoy no vengo a prometerle nada, vengo a conocer su negocio.\\n\\nCuenteme, como le ha ido con eso?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres el encargado de un negocio y traes UNA reserva concreta con los vendedores, que vas a soltar si te dan la oportunidad. Elige una al azar: ya me han fallado antes / todos prometen y nadie cumple / por aqui pasan muchos como usted / la ultima vez me salio mas caro de lo que me dijeron. REACCIONAS ASI: si el vendedor NO se adelanta, en tu segunda o tercera respuesta sacas tu reserva con firmeza, y a partir de ahi te mantienes escéptico y cuesta arriba el resto de la sesion. Si el vendedor SE ADELANTA y menciona el mismo negativo antes que tu, con naturalidad y sin dramatizarlo, te desarma: te ries o asientes, bajas la guardia notablemente, y le contestas con mas apertura que antes — porque alguien que reconoce lo malo se vuelve creible. Si el vendedor se adelanta pero lo hace en tono de DISCULPA o de justificacion (perdon si le han fallado, no todos somos iguales, yo si soy diferente), no funciona: te suena a excusa, no bajas la guardia y sacas tu reserva igual. Si inventa un negativo que no aplica o que tu no tenias, te confunde y te pone en alerta: ahora si dudas de algo que ni te preocupaba. Responde en 1 o 2 frases.", "objective": "El vendedor menciona el negativo conocido antes que el cliente, con naturalidad y sin tono de disculpa, desactivandolo. El scope se cubre cuando el cliente baja la guardia y responde con mas apertura de la que tenia."}, "closing": {"message": "Eso es un ataque preventivo. Dijiste tu lo que el iba a usar, y al decirlo tu dejo de ser un arma. Ojo con la regla: solo funciona con negativos REALES y conocidos, y solo si lo dices sin disculparte. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo si el negativo alcanzo a desactivarse."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "no_se_adelanta", "regla_id": "blocks.ataque_preventivo", "severity": "major", "description": "Deja que el cliente saque el negativo primero. Ahora tiene que atravesar cuesta arriba algo que pudo haber desactivado gratis."}, {"id": "tono_de_disculpa", "regla_id": "blocks.ataque_en_disculpa", "severity": "major", "description": "Se adelanta pero en tono de excusa: perdon si le han fallado, no todos somos iguales, yo si soy diferente. Suena a defensa y no desarma nada."}, {"id": "negativo_inventado", "regla_id": "blocks.negativo_inventado", "severity": "major", "description": "Menciona un negativo que el cliente no tenia. En lugar de desactivar, planta una duda nueva. La tecnica sirve para desarmar lo que ya existe, nunca para crear preocupaciones."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta."}], "success_criteria": [{"id": "blocks.pre_emptive_strike", "weight": 0.7, "regla_id": "blocks.ataque_preventivo", "description": "Menciona un negativo real y conocido ANTES de que el cliente lo saque, con naturalidad y sin dramatizarlo. El tono importa: decirlo como dato desarma, decirlo como disculpa o justificacion no funciona y suena a excusa. Inventar un negativo que el cliente no tenia es peor que no hacerlo."}, {"id": "blocks.air", "weight": 0.3, "regla_id": "blocks.air", "description": "Si el cliente alcanza a sacar su reserva, la acepta sin pelearla y retoma. No se defiende ni intenta convencerlo de lo contrario."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"2.9","world_id":2,"name":"Seguir Avanzando","technique":"close_with_action","order_index":9,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":2,"description":"Atravesaste el bloqueo. Y ahora que? La respuesta decide si la conversacion sigue o se muere ahi.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: cada vez que resuelvas algo, avanza tu. No esperes a que el cliente decida que sigan. La conversacion la mueves tu.","practice_script":{"notes": "v2.0.0 Nodo nuevo. Primera aparicion de Close With Action, en su version ligera: avanzar en la linea. Vuelve en M4 despues del precio y en M5 como cierre. El espejo castiga el silencio con la consecuencia real: el cliente se despide con amabilidad.", "scope": {"skills_in_focus": ["flow.close_with_action", "blocks.air"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en el momento justo despues de resolver algo. Ahi es donde el vendedor promedio se queda callado, esperando permiso para seguir.\\n\\nYo no. Resuelvo y avanzo en la misma frase, con la siguiente pregunta ya puesta.\\n\\nEl cliente nunca tiene que decidir si seguimos, porque ya seguimos.", "first_message": "Claro, entiendo perfecto. Y digame, cuanto tiempo lleva usted con el negocio?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres el encargado de un negocio. Vas a poner pequenos frenos a lo largo de la conversacion: en tu primera respuesta un bloqueo suave (ando ocupado, no me interesa), y mas adelante uno o dos frenos menores (una duda corta, un ahorita no se, un uf pues no se). TU REGLA PRINCIPAL: despues de CADA freno tuyo, observas que hace el vendedor. Si el vendedor resuelve y SE QUEDA CALLADO, o pregunta si puede continuar, o espera tu reaccion, entonces TU TOMAS EL CONTROL: dices bueno pues ahi luego me dice, gracias eh, y empiezas a despedirte con amabilidad. La conversacion se te acaba en las manos. Si el vendedor resuelve y AVANZA de inmediato con otra pregunta o retomando su tema sin pedir permiso, tu sigues la conversacion con naturalidad y contestas lo que te pregunte. Nunca eres tu quien reactiva la conversacion despues de un silencio. Responde en 1 o 2 frases.", "objective": "El vendedor avanza por su cuenta despues de cada freno del cliente, sin quedarse esperando ni pedir permiso para continuar. El scope se cubre cuando la conversacion sobrevive al menos dos frenos porque el vendedor la movio las dos veces."}, "closing": {"message": "Eso es seguir avanzando. Cada vez que algo te freno, resolviste y seguiste tu, sin esperar a que el cliente decidiera. Esa es la diferencia entre una conversacion que avanza y una que se apaga en un silencio. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo donde se te fue el control."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_queda_esperando", "regla_id": "close.devuelve_el_volante", "severity": "critical", "description": "Resuelve el freno y se queda callado esperando la reaccion del cliente. En ese silencio el cliente retoma el control y la conversacion se acaba.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "pide_autorizacion", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Pregunta si puede continuar, si le permite seguir o si tiene mas tiempo. Le entrega el control justo despues de haberlo recuperado."}, {"id": "avanza_atropellando", "regla_id": "blocks.air_sin_resume", "severity": "minor", "description": "Avanza sin reconocer lo que el cliente acaba de decir. Se siente que no lo escucho.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta."}], "success_criteria": [{"id": "flow.close_with_action", "weight": 0.7, "regla_id": "close_with_action", "description": "Despues de cada freno del cliente, el vendedor avanza por su cuenta: hace la siguiente pregunta o retoma su tema en la misma intervencion, sin pausas de espera y sin pedir autorizacion. No deja que el cliente decida si la conversacion continua."}, {"id": "blocks.air", "weight": 0.3, "regla_id": "blocks.air", "description": "Cada freno se acepta sin pelearlo antes de avanzar. Avanzar sin reconocer lo que el cliente dijo se siente atropellado."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"2.10","world_id":2,"name":"BOSS: La Puerta Fria","technique":"historia_breve_completa","order_index":10,"is_boss":true,"reps_required":1,"checkpoints":null,"difficulty_level":3,"description":"Todo el mundo junto: bloqueo de entrada, quien eres, relacion, y no soltar el control.","node_type":"boss","conversation_scope":null,"engine_type":"claude","boss_goal":"Presentarse y sostener la conversacion con un cliente que bloquea de entrada: atravesar el bloqueo sin pelearlo, decir quien es en quince segundos, crear relacion personal con regreso, y avanzar sin pedir permiso hasta que el cliente participe por su propia voluntad.","field_mission":"TU MISION: la conversacion completa con un cliente que no te la va a poner facil. Atraviesa el bloqueo, di quien eres en quince segundos, conecta como persona, y sigue avanzando tu. Sin disculpas y sin pedir permiso.","practice_script":{"notes": "v2.0.0 BOSS del Mundo 2. Sin pistas garantizadas (R9). Acumulativo: el Mundo 1 se examina implicitamente porque una apertura mal hecha no abre la conversacion. La senal de exito es que el cliente pregunte en que le puede servir, que es la puerta al Descubrimiento.", "scope": {"skills_in_focus": ["blocks.air", "story.historia_breve", "story.brevedad", "relationship.cpr", "flow.close_with_action"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Bloqueo de entrada, historia breve, relacion personal y seguir avanzando: todo junto y con un cliente que no ayuda.\\n\\nSin pistas.", "first_message": "Entiendo perfecto, no se preocupe. Soy Emilio, ando trabajando con los negocios de esta zona y quise pasar a conocer el suyo.\\n\\nDigame una cosa, cuanto tiempo lleva usted aqui?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\\n\\nEres el encargado de un negocio, ocupado y con poca paciencia para vendedores. En tu PRIMERA respuesta sueltas un bloqueo de reflejo, con naturalidad y sin agresion: ahorita ando ocupado / no me interesa / no estoy comprando nada. TU COMPORTAMIENTO: eres cortes pero cerrado y contestas corto. NO ofreces informacion y NO llevas la conversacion. REGLAS DE REACCION: 1) Si el vendedor pelea el bloqueo, se disculpa o se va, lo despachas y la conversacion termina. 2) Si lo acepta y sigue, continuas con naturalidad. 3) Si su historia breve se alarga mas de tres o cuatro frases, te desconectas: contestas ajam y dices que andas ocupado. 4) Si el vendedor resuelve algo y se queda callado esperando, TU tomas el control y empiezas a despedirte con amabilidad. 5) En tu tercera o cuarta respuesta, si la conversacion sigue viva, sueltas de manera natural UN dato personal tuyo, al pasar, sin darle importancia: elige entre familia, como empezaste, que haces los domingos, por que pusiste el negocio, o tu equipo. Si el vendedor lo ignora, te enfrias y ya no ofreces nada mas de ti. Si le entra con interes real, te abres notablemente. Si se queda platicando de eso mas de dos intercambios sin volver al negocio, te acomodas a platicar de la vida y ya nunca regresas tu al tema. 6) SOLO si el vendedor logra todo — atravesar el bloqueo, decir quien es breve y relevante, conectar contigo como persona y regresar, y avanzar sin pedir permiso — entonces te abres de verdad: le cuentas algo de tu negocio por tu cuenta y le preguntas en que le puede servir. Esa pregunta es la senal de que gano. NUNCA la hagas antes de que se lo gane. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa el bloqueo inicial, se presenta en quince segundos de forma relevante, conecta con el dato personal y regresa, y sostiene el avance sin pedir permiso. El scope se cubre cuando el cliente se abre por su propia voluntad y pregunta en que le puede servir."}, "closing": {"message": "Ahi esta la puerta fria abierta. Atravesaste el bloqueo sin pelearlo, dijiste quien eras sin cansarlo, conectaste como persona y volviste, y nunca soltaste el control de la conversacion. Ese cliente ya quiere saber en que le puedes servir, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "discute_el_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Pelea el bloqueo inicial o intenta convencer al cliente de que si le interesa."}, {"id": "se_disculpa_o_se_va", "regla_id": "discovery.suelta_amarrado", "severity": "critical", "description": "Se disculpa, se despide o promete volver despues.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "se_queda_esperando", "regla_id": "close.devuelve_el_volante", "severity": "critical", "description": "Resuelve algo y se queda callado esperando permiso. El cliente toma el control y se despide.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "historia_larga", "regla_id": "story.kill", "severity": "major", "description": "La historia breve se extiende y el cliente se desconecta."}, {"id": "ignora_lo_personal", "regla_id": "story.nunca_sale", "severity": "major", "description": "Pasa de largo el dato personal que el cliente ofrecio.", "severity_override": {"razon": "boss: escalada", "default": "minor"}}, {"id": "se_queda_platicando", "regla_id": "story.sale_sin_regresar", "severity": "major", "description": "Le entra a lo personal y ya no vuelve al negocio."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta. Identificarse con nombre y empresa es el trabajo de este paso, no una excepción: aquí SÍ se dice quién eres y por qué estás."}], "success_criteria": [{"id": "blocks.air", "weight": 0.25, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo inicial: lo acepta, no lo pelea, y retoma sin pedir permiso."}, {"id": "story.historia_breve", "weight": 0.2, "regla_id": "story.quien_eres_por_que", "description": "Dice quien es y por que esta ahi: nombre, procedencia y motivo humano de la visita."}, {"id": "story.brevedad", "weight": 0.15, "regla_id": "story.kiss", "description": "Dos o tres frases. Sin trayectoria de empresa, sin lista de productos, sin cifras."}, {"id": "relationship.cpr", "weight": 0.2, "regla_id": "relationship.cpr", "description": "Detecta el dato personal, le entra con interes genuino, y REGRESA al negocio por su cuenta en uno o dos intercambios."}, {"id": "flow.close_with_action", "weight": 0.2, "regla_id": "close_with_action", "description": "Despues de cada freno avanza por su cuenta, sin quedarse esperando ni pedir autorizacion. Sostiene el control de la conversacion toda la sesion."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"3.0","world_id":3,"name":"El Doctor Vendedor","technique":"doctor_vendedor","order_index":0,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":1,"description":"El cliente ya sabe quien eres y te esta dando conversacion. Ahora viene el paso que separa al que receta del que examina.","node_type":"knowledge","conversation_scope":null,"engine_type":"classify","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"3.1","world_id":3,"name":"RRR: Lee, Conecta, Relaja","technique":"rrr","order_index":1,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":2,"description":"Tienes el mapa de donde buscar. Antes de preguntar, aprende a leer con quien estas hablando.","node_type":"skill_drill","conversation_scope":"discovery","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: lee el estado del cliente en sus primeras dos respuestas — viene apurado, platicador o preocupado. Reconocelo con naturalidad y ajusta tu ritmo al suyo. La conversacion no avanza hasta que el se relaja.","practice_script":{"notes": "El Actor estrena ánimos variables (3 estados aleatorios). El espejo pedagógico: leer+ajustar → el cliente se relaja y coopera; ignorar → respuestas pobres. La lectura_falsa como failure protege contra el RRR de guion (decir uy qué prisa trae a todos por igual).", "scope": {"skills_in_focus": ["mindset.rrr", "discovery.escucha_activa"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 180, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Mira cómo leo al cliente antes de avanzar. Este señor está estresado por algo — fíjate que NO lo ignoro para seguir con mi guion: primero lo leo, luego conecto con su estado, y lo relajo.\\n\\nSolo entonces la conversación puede avanzar.", "first_message": "Cliente: Sí dígame, pero rápido porque traigo un problema con un pedido que no llegó. Yo: Uy, qué coraje eso de los pedidos que no llegan — le pasa a uno en el peor momento.\\n\\nMire, no le quito el foco: ¿lo alcanzo mejor en un rato o le caigo mañana temprano? — ¿Ves?\\n\\nLeí su estrés, conecté con su molestia real, y le relajé la presión de mi visita. Ese señor me va a recibir mañana con gusto."}, "you_do": {"prompt": "Eres el dueño de un negocio. Al INICIAR la sesión elige al azar UNO de estos tres estados y actúalo consistentemente: (A) APURADO: tienes algo urgente en curso, hablas rápido, frases cortas, miras el reloj — no estás molesto, solo presionado; (B) PLATICADOR: estás de buen humor, relajado, te encanta conversar, contestas todo con historias y detalles; (C) PREOCUPADO: algo salió mal hoy (un pedido, un empleado, un cliente moroso — elige) y lo traes en la cabeza, estás distraído y lo mencionas de pasada. No reveles tu estado — muéstralo con tu forma de responder. TU REGLA ESPEJO: si el vendedor LEE tu estado y lo reconoce (menciona tu prisa, fluye con tu plática, o pregunta por tu preocupación) y AJUSTA su ritmo al tuyo, te relajas y la conversación fluye hacia sus preguntas. Si te ignora y sigue con su agenda como si nada — le respondes distraído, cortante o desconectado según tu estado, y no le das información buena. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor detecta el estado del cliente en sus primeras respuestas (prisa, ganas de platicar, o preocupación), lo RECONOCE verbalmente de forma natural (no clínica: uy, lo noto con prisa / se ve que hoy está tranquilo / qué pendiente eso que me cuenta), y AJUSTA su approach al estado: ritmo acelerado y directo ante el apurado, fluir sin cortar ante el platicador, atender la preocupación antes de avanzar ante el preocupado. El scope se cubre cuando el cliente se ha relajado visiblemente y la conversación avanzó a preguntas de descubrimiento acordes a su estado."}, "closing": {"message": "Lo leíste, conectaste con su momento, y la conversación se abrió sola. Eso es RRR — y funciona con cualquier humano, no solo con clientes. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos — ya vi como lees y como ajustas. Vamos al desglose y te digo cual era la siguiente jugada."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ignora_estado", "regla_id": "discovery.rrr", "severity": "major", "description": "El cliente muestra un estado claro (prisa, plática, preocupación) y el vendedor sigue con su agenda como si nada — mismo ritmo, mismas preguntas, cero reconocimiento del momento del cliente."}, {"id": "lectura_falsa", "regla_id": "discovery.lectura_falsa", "severity": "minor", "description": "Reconoce un estado que el cliente NO mostró (le dice apurado al platicador, o asume molestia donde había buen humor) — leyó su suposición, no al cliente.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "major", "description": "Aprovecha el estado para vender: al preocupado le ofrece el producto como solución inmediata de su problema del día."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Turnos largos que atropellan — lo contrario de leer y dar espacio."}], "success_criteria": [{"id": "mindset.rrr", "weight": 0.6, "regla_id": "discovery.rrr", "description": "Ejecuta las tres R: LEE el estado del cliente en sus primeras respuestas (detectable porque lo menciona o reacciona a él), CONECTA reconociéndolo verbalmente con naturalidad, y RELAJA ajustando su approach al estado — ritmo directo ante prisa, fluidez ante plática, atención a la preocupación antes de avanzar. Las tres deben aparecer, en ese orden lógico."}, {"id": "discovery.escucha_activa", "weight": 0.4, "regla_id": "discovery.escalera_capas", "description": "Sus turnos construyen sobre lo que el cliente acaba de decir — retoma sus palabras, su tema, su estado — en lugar de avanzar una agenda propia desconectada de las respuestas."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"3.2","world_id":3,"name":"Preguntas por Capas","technique":"capas","order_index":2,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Ya sabes leerlo y ya tienes el mapa. Ahora la herramienta para excavar.","node_type":"skill_drill","conversation_scope":"discovery","engine_type":null,"boss_goal":null,"field_mission":"AVERIGUA (los hechos, territorio por territorio):\\n· PRODUCTO — que maneja mas y que marcas maneja\\n· SERVICIO — quien lo surte y que tal le cumple\\n· PRECIO — a cuanto compra su producto estrella\\n\\nY ENCUENTRA (el dolor): en alguno de esos territorios hay algo que le duele. Ojo — si preguntas en generico te va a decir \\"bien\\" de reflejo. Pregunta por algo CONCRETO. Cuando caiga el \\"aunque...\\", excava con preguntas abiertas y cierra confirmandolo con sus palabras.","practice_script":{"notes": "v1.1.0 — Los 3 Territorios (R8). Dolor aleatorio entre 6 variantes mapeadas a producto/servicio/precio. La pista garantizada (R7) asegura que la oportunidad de excavar aparezca en toda sesion: sin ella, un vendedor que mapea hechos podia ser cortado y calificado sin haber visto jamas la mecanica. El espejo del barrido (R6): positivo limpio en territorio sano — cambiar de zona se acredita, insistir se marca minor. pitch_prematuro sigue critical.", "scope": {"skills_in_focus": ["discovery.preguntas_capas", "discovery.pregunta_especifica", "discovery.dolor_real", "discovery.suggestive_language"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Mira como trabajo con mapa y con pala.\\n\\nY fijate sobre todo en QUE TIPO de pregunta hago cuando subo de capa. No pregunto que tal le va, porque a eso cualquiera contesta bien de reflejo.\\n\\nPregunto por algo CONCRETO. Esa es toda la diferencia entre una puerta cerrada y una abierta.", "first_message": "TERRITORIO PRODUCTO — capa de hechos.\\n\\nYo: que es lo que mas maneja aqui?\\nEl: (me dice cual es su producto estrella)\\n\\nAhora subo a la capa 2, y aqui esta todo el truco.\\n\\nLo que NO hago: preguntarle que tal le va con su proveedor. A eso me contesta bien y se acabo la conversacion.\\n\\nLo que SI hago, algo concreto:\\n\\nYo: Y de eso que mas maneja, le ha tocado quedarse sin cuando mas se lo piden?\\nEl: Pues fijese que si, a veces me deja colgado el proveedor.\\n\\nAhi ya no pudo contestar bien de reflejo. Tuvo que ir a buscar el dato real.\\n\\nAhora si excavo, con preguntas abiertas:\\n\\nYo: Como cuanto le dura un faltante de esos? Le ha tocado decirle que no a un cliente?\\nEl: (y sale completo, con coraje de verdad)\\n\\nY remato confirmando con SUS palabras:\\n\\nYo: Entonces lo que mas le pega es quedarse sin surtir cuando la venta esta, cierto?\\n\\nESO es un diagnostico terminado.\\n\\nUna cosa mas: hay una version todavia mas potente de esa pregunta concreta, que es darle permiso contandole que a otros les pasa. Eso lo trabajas a fondo mas adelante — si hoy te sale natural, usala."}, "you_do": {"prompt": "Eres el dueno de un negocio, relajado y cooperativo (buena conversacion previa — este drill aisla el descubrimiento). REGLA CERO — CUENTA LAS PREGUNTAS DE HECHOS: lleva un conteo mental de cuantas preguntas de capa 1 (hechos: que vendes, que marcas, a como compras, cuanto llevas) te ha hecho el vendedor SIN subir a capa 2. En cuanto respondas la TERCERA, tu siguiente respuesta DEBE incluir, de pasada, un DATO DE CONTEXTO del territorio donde vive tu dolor: un hecho neutro, sin evaluarlo ni quejarte (si tu dolor es de SERVICIO, mencionas quien te surte y desde cuando; si es de PRODUCTO, mencionas una linea o marca concreta que manejas o que te piden; si es de PRECIO, mencionas cada cuanto te ajustan precios). NO es una pista y NO lleva quejas: es solo un dato que le pone el territorio al alcance. Antes de enviar cada respuesta verifica: ya van 3 o mas preguntas de hechos sin capa 2? entonces esta respuesta lleva el dato de contexto. TU DOLOR: tienes UN dolor real oculto. Elige al azar UNO de estos seis, y recuerda en que territorio vive: PRODUCTO (a: faltantes de tu producto estrella que te hacen perder ventas / b: tus clientes piden una linea que tu proveedor no maneja), SERVICIO (c: tu proveedor te deja plantado con pedidos cada quincena / d: cuando hay un problema nadie te da la cara ni te resuelve), PRECIO (e: te subieron el precio dos veces este ano y tu margen esta apretado / f: tienes dinero parado en producto que no se mueve). REGLA DEL BIEN AUTOMATICO — LO MAS IMPORTANTE DE TU PERSONAJE: eres un comerciante real, y los comerciantes reales NO se quejan con desconocidos por cortesia. Ante cualquier pregunta GENERICA de opinion o experiencia (que tal le va, como se porta su proveedor, todo bien por aca, que tal el servicio) respondes SIEMPRE con un bien reflejo y cortes — bien, no me quejo / todo tranquilo / ahi la llevamos bien — SIN pista, AUNQUE la pregunta toque justo el territorio de tu dolor. No estas mintiendo: asi contesta cualquiera a un desconocido que pregunta en generico. LA PISTA SE GANA CON PREGUNTA CONCRETA: solo sueltas la pista sutil de tu dolor (bien, aunque a veces...) cuando el vendedor hace una pregunta que toca el territorio de tu dolor Y cumple UNA de estas dos condiciones: (1) ESPECIFICA — nombra un dato o una situacion concreta en vez de pedir una opinion general (cuantas veces al mes le llega incompleto?, le ha tocado quedarse sin su producto estrella?, cuanto le subieron el precio este ano?); o (2) NORMALIZADA — te da permiso de admitirlo contandote que a otros les pasa (varios clientes me comentan que batallan con faltantes, a usted le pasa?). Cualquiera de las dos vale igual. Si la pregunta concreta toca un territorio SIN dolor, la niegas limpio y genuino (no, eso si no, ahi voy bien) — sin frases ambiguas tipo en-ese-aspecto, por-ahora o mas-o-menos: en territorios sanos no hay medio-dolores. SI INSISTE EN UN DOLOR QUE NEGASTE: si ya negaste algo y el vendedor sigue insistiendo en convencerte de que si te pasa, te incomodas educadamente (ya le digo que con eso no batallo) y te vuelves mas cerrado y mas corto el resto de la conversacion. CAPA 3 — SOLO si el vendedor recoge la pista y profundiza en ella con una o dos preguntas mas, revelas el dolor completo con detalle y emocion real (es que fijese que...). NUNCA reveles el dolor completo si no te lo excavan. Si intenta presentar producto, respondes con evasiva educada (ah orale, suena bien) sin soltar mas informacion. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.\\n\\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (por ejemplo: que familias manejas? anticongelantes? aceite de motor? diesel?, o a como lo compras? 70? 80? 90?), contestas de inmediato y con un dato ESPECIFICO — o eliges una de sus opciones, o lo corrigen con la cifra o el producto real (no, mas bien 95 / no, lo que mas me sale es otra cosa). Nunca contestas pues no se a una pregunta con opciones. En cambio, si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago (pues no se, dejame ver, ahi mas o menos) — porque construir la respuesta desde cero cuesta trabajo y no te urge ayudarle.", "objective": "El vendedor ejecuta un descubrimiento con estructura: preguntas de hechos que recorren los territorios (producto, servicio, precio), y sube de capa con preguntas CONCRETAS — especificas o normalizadas — porque a las genericas el cliente responde bien de reflejo. Cuando cae la pista, la excava con preguntas abiertas hasta que el cliente revela el dolor completo, y remata confirmandolo en palabras propias (entonces lo que mas le pega es X, verdad?). Cambiar de territorio ante una negacion limpia es ejecucion correcta, no falla. El scope se cubre cuando el dolor real fue revelado por el cliente Y confirmado verbalmente por el vendedor."}, "closing": {"message": "Llegaste al dolor real — el que no estaba en la superficie. Encontraste el territorio, detectaste el flaqueo y excavaste hasta el fondo. Eso vale oro: es exactamente lo que tu presentacion va a resolver. Vamos al detalle.", "message_incomplete": "Ahi paramos la excavacion — ya vi como preguntas y con eso trabajo. Vamos al desglose y te digo cual era la siguiente jugada."}}, "version": "1.3.0", "i_do_type": "demo", "failure_criteria": [{"id": "ignora_pistas", "regla_id": "discovery.escalera_capas", "severity": "major", "description": "El cliente deja caer la pista del dolor (aunque a veces..., lo unico es que...) y el vendedor la pasa de largo — cambia de tema o dispara la siguiente pregunta de su lista."}, {"id": "pregunta_generica_en_capa2", "regla_id": "discovery.pregunta_especifica", "severity": "minor", "description": "Sube de capa con preguntas genericas de opinion (que tal le va, todo bien por aca) que producen un bien reflejo, y al recibirlo se conforma y sigue de largo en lugar de reformular preguntando por algo concreto."}, {"id": "insiste_dolor_negado", "regla_id": "discovery.fabrica_dolor", "severity": "major", "description": "El cliente NIEGA explicitamente un problema y el vendedor insiste en convencerlo de que si le pasa. Solo aplica DESPUES de una negacion clara del cliente. Mencionar que a otros clientes les pasa NO es plantar: es normalizar, y se acredita.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "critical"}}, {"id": "insistencia_territorio_seco", "regla_id": "discovery.barrido", "severity": "minor", "description": "El cliente da una negacion limpia y genuina en un territorio y el vendedor sigue ahi con mas y mas preguntas en lugar de cambiar de territorio — interroga la zona sana."}, {"id": "interrogatorio", "regla_id": "discovery.interrogatorio", "severity": "minor", "description": "Preguntas en rafaga sin construir sobre las respuestas — el cliente se siente en el ministerio publico, no en una conversacion."}, {"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "critical", "description": "Presenta el producto al detectar el dolor (o antes). El descubrimiento se contamina: en cuanto presentas, el cliente deja de revelar. La presentacion tiene su propio mundo.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "pregunta_cerrada_en_capa_profunda", "regla_id": "discovery.solo_cerradas", "severity": "minor", "description": "Ya que el dolor asomo (capa 3), profundiza con cerradas de si/no que cortan la revelacion en lugar de abiertas que la expanden. Aplica SOLO a capa 3: en capa 2 la pregunta concreta y acotada es lo correcto.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}], "success_criteria": [{"id": "discovery.preguntas_capas", "weight": 0.28, "regla_id": "discovery.escalera_capas", "description": "Progresion visible de capas con mapa: preguntas de hechos primero (que, cuanto, cuales, a como), luego subida a capa 2, y excavacion con preguntas ABIERTAS una vez que aparece la pista (en capa 3 las abiertas son lo correcto: expanden el relato). Recorre territorios (producto, servicio, precio) en lugar de agotar uno solo; cambiar de territorio ante una negacion limpia es ejecucion CORRECTA y se acredita. Cada pregunta nace de la respuesta anterior. Cualquier territorio elegido para explorar primero es valido."}, {"id": "discovery.pregunta_especifica", "weight": 0.24, "regla_id": "discovery.pregunta_especifica", "description": "Al subir a capa 2 pregunta por algo CONCRETO — un dato o situacion que el cliente tiene que ir a buscar en su experiencia — en lugar de pedir una opinion general, que solo produce un bien reflejo. IMPORTANTE: normalizar el dolor citando a otros clientes (varios clientes me comentan que..., he escuchado que a algunos les pasa...) SI SE ACREDITA como version avanzada de la pregunta concreta, y NUNCA se marca como plantar un dolor inventado. Plantar solo aplica cuando el vendedor insiste en un problema que el cliente YA NEGO explicitamente."}, {"id": "discovery.dolor_real", "weight": 0.28, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "Detecta la pista (el aunque, el a veces, el lo unico), la excava hasta que el cliente revela el dolor completo, Y lo confirma verbalizandolo de vuelta en sus propias palabras. Quedarse en la pista sin excavarla, o excavarla sin confirmarla, no cumple. Preguntar el dolor directo (que problemas tiene?) tampoco: el dolor se deja emerger."}, {"id": "discovery.suggestive_language", "weight": 0.2, "regla_id": "discovery.suggestive_language", "description": "Cuando el cliente contesta vago o no tiene el dato a la mano, el vendedor le SUGIERE OPCIONES concretas despues de preguntar (tres o cuatro familias, o un rango de precios). Le da de donde agarrarse: el cliente elige una o lo corrige con el dato real. NO es obligatorio en cada pregunta — se acredita si lo usa al menos una vez donde hacia falta. Sugerir opciones que no son del giro del cliente, o insistir en la propia opcion despues de que el cliente corrige, no cumple."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"3.3","world_id":3,"name":"Escucha Que Construye","technique":"escucha","order_index":3,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Sabes preguntar por capas. Ahora asegurate de que cada pregunta nazca de lo que acaba de decir.","node_type":"skill_drill","conversation_scope":"discovery","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: que cada pregunta tuya nazca de la ultima respuesta del cliente. Te va a regalar datos que no pediste — un familiar, un cambio, un plan. Recoge al menos dos y pregunta sobre ellos con SUS palabras. Tu lista puede esperar; sus regalos no.","practice_script":{"notes": "El Actor regala datos laterales y mide si son recogidos — mecánica de pistas encadenadas (recoger una produce otra). El castigo por ignorar es gradual y realista: respuestas cada vez más pobres. ignora_pistas es critical: es la habilidad completa de este nodo.", "scope": {"skills_in_focus": ["discovery.escucha_activa", "discovery.preguntas_capas"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Fijate en que nunca dejo pasar un regalo.\\n\\nEl cliente suelta datos que nadie le pidio: una persona, un plan, un cambio, algo que le preocupa.\\n\\nCada vez que suelta uno, mi siguiente pregunta nace de ahi. No de mi lista.", "first_message": "El: ...si, desde que mi hijo entro al negocio hemos metido lineas nuevas.\\n\\nAhi hay dos regalos: el hijo, y las lineas nuevas. Ninguno se los pedi.\\n\\nYo: Ah, su hijo ya le entro al negocio. Y como les ha ido con eso de meter lineas nuevas?\\n\\nFijate que use SUS palabras. No cambie de tema ni segui con mi lista: construi sobre lo que acababa de decir.\\n\\nEl: (y ahi se abre, porque siente que lo estoy escuchando de verdad)\\n\\nNo tengo que preguntar por TODOS los regalos. Con seguir uno bien, la conversacion se vuelve suya y me cuenta el resto solo."}, "you_do": {"prompt": "Eres el dueño de un negocio, cooperativo y con ganas de platicar. TU MECÁNICA DE PISTAS: en cada respuesta que des, incluye UN dato lateral valioso que NO fue preguntado directamente — ejemplos del tipo: un familiar metido en el negocio, un cambio reciente (remodelación, nuevo proveedor, mudanza), un cliente especial que te compra distinto, una temporada que cambia todo, un plan a futuro. Son regalos conversacionales: los sueltas de pasada, sin drama. TU REGLA ESPEJO: si el vendedor RECOGE tu dato lateral y pregunta sobre él, te explayas con gusto — das información rica, detalles del negocio, y sueltas OTRO dato lateral en esa respuesta. Si el vendedor ignora tu regalo y dispara otra pregunta de su lista, contestas correcto pero más corto cada vez, y dejas de regalar datos después de dos ignorados seguidos. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.\\n\\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor sostiene un descubrimiento donde sus preguntas nacen de las respuestas del cliente: recoge los datos laterales que el cliente regala (el familiar, el cambio, el plan) y pregunta sobre ellos usando las palabras del propio cliente, en lugar de avanzar una lista propia. El scope se cubre cuando el vendedor recogió al menos 2 pistas laterales consecutivas y la conversación se profundizó visiblemente gracias a ello (respuestas del cliente cada vez más ricas)."}, "closing": {"message": "¿Notaste cuánto te contó? Eso no se saca con una lista de preguntas — se gana escuchando de verdad. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos — ya vi como escuchas. Vamos al desglose y te enseno que regalos quedaron en la mesa."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ignora_pistas", "regla_id": "discovery.escalera_capas", "severity": "critical", "description": "El cliente regala datos laterales y el vendedor los pasa de largo 2 o más veces — dispara su siguiente pregunta como si el cliente no hubiera dicho nada. En este nodo, ignorar la pista es EL fallo: el drill entero existe para esto.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "interrogatorio", "regla_id": "discovery.interrogatorio", "severity": "major", "description": "Ráfaga de preguntas desconectadas de las respuestas — la conversación suena a formulario.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "minor"}}, {"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "major", "description": "Convierte un dato lateral en oportunidad de venta inmediata (le mencionan la remodelación y ofrece producto para la remodelación)."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Responde a los datos del cliente con historias propias largas en lugar de preguntas que profundicen."}, {"id": "conversacion_desconectada", "regla_id": "discovery.escalera_capas", "severity": "major", "description": "NINGUNA de las preguntas del vendedor conecta con lo que el cliente acaba de decir: dispara una lista propia mientras el cliente habla de otra cosa. Se penaliza la desconexion total, no el hecho de no recoger algun dato en particular."}], "success_criteria": [{"id": "discovery.escucha_activa", "weight": 0.6, "regla_id": "discovery.escalera_capas", "description": "Al menos UNA de las preguntas del vendedor nace directamente de un dato que el cliente acaba de regalar, usando sus propias palabras. NO se exige recoger todos los datos que el cliente menciona: eso seria un interrogatorio. Se exige que la conversacion este HILADA — que se note que escucho. Explorar un solo hilo a fondo cumple; guardar los demas para mas adelante es estrategia legitima del vendedor y no se penaliza."}, {"id": "discovery.preguntas_capas", "weight": 0.4, "regla_id": "discovery.escalera_capas", "description": "Sostiene el avance del diagnostico por capas: ademas de recoger el dato que el cliente regala, sigue subiendo en el territorio de negocio —de los hechos a la puerta y de ahi al dolor— con preguntas que nacen de las respuestas anteriores. Recoger lo lateral no debe detener el diagnostico."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"3.4","world_id":3,"name":"CPR en el Descubrimiento","technique":"cpr_descubrimiento","order_index":4,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":2,"description":"Preguntas bien y escuchas bien. Falta lo que hace que te contesten de verdad, aqui donde mas importa.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: recorre los territorios preguntando por el negocio, pero intercala uno o dos toques personales en el camino. La gente le cuenta sus problemas a quien le cae bien, no a quien le hace un cuestionario.","practice_script":{"notes": "v2.0.0 Nodo nuevo. Refuerzo de la mecanica del 2.5 aplicada al diagnostico. El espejo es de profundidad: sin relacion el cliente contesta datos secos y NUNCA suelta la pista del dolor. Es la demostracion en carne propia de por que el CPR condiciona el Descubrimiento.", "scope": {"skills_in_focus": ["relationship.cpr", "discovery.preguntas_capas"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Fijate en como mezclo. No hago un bloque de preguntas de negocio y luego un bloque de platica personal: los intercalo.\\n\\nPregunto del negocio, recojo algo personal que me suelta, le entro un momento, y regreso al siguiente territorio. Asi no se siente cuestionario, se siente conversacion.", "first_message": "Y de lo que maneja, que es lo que mas maneja? ...\\n\\nAh mire. Oiga, y ese muchacho que anda alla es su hijo?\\n\\n... Que bueno que le ayude, no todos quieren.\\n\\nY digame, quien le surte a usted ahorita?"}, "you_do": {"prompt": "Eres el dueno de un negocio, cooperativo pero reservado con los desconocidos. TIENES UN DOLOR OCULTO: elige al azar uno de estos tres territorios y quedate con el toda la sesion — PRODUCTO (faltantes de lo que mas manejas), SERVICIO (tu proveedor te deja plantado), PRECIO (te subieron y tu margen esta apretado). TU REGLA PRINCIPAL: la profundidad de tus respuestas depende de si el vendedor te trata como persona o como formulario. Al inicio, a las preguntas de negocio contestas con datos correctos pero secos y cortos. En tu segunda o tercera respuesta sueltas de pasada un dato personal tuyo (un hijo que ayuda, como empezaste, tu equipo, que haces los domingos), sin darle importancia. SI EL VENDEDOR IGNORA lo personal y sigue preguntando puro negocio, te mantienes seco toda la sesion: contestas lo minimo, nunca elaboras, y NUNCA sueltas la pista de tu dolor por mas que pregunte. SI EL VENDEDOR LE ENTRA a lo personal con interes real y despues REGRESA al negocio, te abres: tus respuestas se vuelven mas largas y con detalle, y a partir de ahi SI puedes soltar la pista de tu dolor cuando te pregunte algo concreto sobre ese territorio. SI SE QUEDA en lo personal mas de dos intercambios sin volver al negocio, platicas encantado de tu vida y ya nunca regresas tu al tema del negocio. Responde en 1 o 2 frases, natural. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.\\n\\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor recorre territorios de negocio intercalando uno o dos toques personales, regresando siempre al diagnostico. El scope se cubre cuando el cliente se abre notablemente y suelta la pista de su dolor, que solo ocurre si hubo relacion personal genuina."}, "closing": {"message": "Ahi esta la diferencia. Las mismas preguntas de negocio, pero intercaladas con momentos de persona a persona. Por eso te contesto de verdad en lugar de despacharte con datos. El diagnostico no es un cuestionario. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como mezclas lo personal con el diagnostico. Vamos al desglose."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "cuestionario_frio", "regla_id": "story.nunca_sale", "severity": "major", "description": "Solo pregunta de negocio, sin recoger nada personal. El cliente contesta datos secos y nunca se abre. Correcto en la forma, esteril en el resultado.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "minor"}}, {"id": "ignora_lo_personal", "regla_id": "story.nunca_sale", "severity": "major", "description": "El cliente ofrece un dato personal y el vendedor lo pasa de largo para seguir con su lista.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "minor"}}, {"id": "se_queda_platicando", "regla_id": "story.sale_sin_regresar", "severity": "major", "description": "Le entra a lo personal y ya no vuelve al negocio. La sesion se vuelve social y el diagnostico nunca ocurre."}, {"id": "interes_de_compromiso", "regla_id": "relationship.interes_fingido", "severity": "minor", "description": "Reconoce el dato personal con un que bien y cambia de tema de inmediato. Se nota que no le intereso.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "critical", "description": "Presenta producto o precio durante el diagnostico. En cuanto presentas, el cliente deja de revelar.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}], "success_criteria": [{"id": "relationship.cpr", "weight": 0.55, "regla_id": "relationship.cpr", "description": "Intercala al menos un toque personal genuino entre las preguntas de negocio: recoge el dato que el cliente deja caer, le entra con interes real, y REGRESA al diagnostico por su cuenta. Hacer puro cuestionario de negocio no cumple. Quedarse en lo personal mas de dos intercambios tampoco."}, {"id": "discovery.preguntas_capas", "weight": 0.45, "regla_id": "discovery.escalera_capas", "description": "Sostiene el avance del diagnostico: recorre mas de un territorio de negocio y las preguntas nacen de las respuestas anteriores. El toque personal no debe descarrilar el barrido: despues del desvio, el diagnostico continua donde iba."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"3.5","world_id":3,"name":"Luz Verde: A Quien Le Dedicas Tu Tiempo","technique":"luces","order_index":5,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":2,"description":"Ya sabes diagnosticar. Ahora decide en quien vale la pena invertir tu tiempo.","node_type":"knowledge","conversation_scope":null,"engine_type":"classify","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"3.6","world_id":3,"name":"Leer el No","technique":"luz_roja_salida","order_index":6,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":2,"description":"No todos los no son iguales. Aqui aprendes a distinguir al que no quiere del que quiere y no puede — y por que con el segundo rendirse es el error mas caro.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: este cliente te va a decir que no puede comprar. Averigua POR QUE, y hasta donde llega ese impedimento. Casi toda restriccion tiene bordes — y en los bordes esta la venta.","practice_script":{"notes": "v2.1.0 CORREGIDO. El nodo anterior asumia que todo ''no'' era luz roja y premiaba salir siempre. Emilio demostro en practica real que hay un caso intermedio: el cliente AMABLE con impedimento CIRCUNSTANCIAL — donde salir es la falla mas cara del oficio. El rojo genuino es grosero, tajante y desganado; este es alguien que quiere y no puede. La mecanica central es investigar los LIMITES de la restriccion: casi toda restriccion tiene bordes, y ahi vive la venta.", "scope": {"skills_in_focus": ["qualification.luz_verde", "discovery.preguntas_capas"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Este cliente no puede comprar lo de siempre, y te lo va a decir de frente.\\n\\nFijate en lo que hago: no me rindo ni lo presiono. Investigo hasta donde llega su impedimento — que cubre, que deja fuera, cuando se acaba.\\n\\nCasi siempre una restriccion tiene bordes. Y en esos bordes esta la venta que nadie mas encontro.", "first_message": "Ah, entiendo, esta amarrado con ellos. Que bueno que me lo dice de frente.\\n\\nOiga, y ese compromiso que cubre exactamente? Todo lo que maneja o nada mas algunas lineas?\\n\\nEl: (me dice que cubre unas cosas y otras no)\\n\\nAh mire, entonces eso otro si lo puede ver aparte. Cuenteme, como anda con eso?\\n\\nY una ultima: hasta cuando le dura el compromiso? Para venir a verlo cuando se libere."}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente AMABLE y de buen trato. No eres grosero ni cortante en ningun momento. Te da gusto que el vendedor pase a verte.\\n\\nEres el dueno de un negocio que conoce a este vendedor. Adopta el tipo de negocio y las familias de producto del contexto de la empresa.\\n\\nTU SITUACION: quieres comprar, pero hay una CIRCUNSTANCIA que te lo impide PARCIALMENTE. Elige una al azar y mantenla toda la sesion:\\n(a) firmaste hace poco un contrato de exclusividad con otro proveedor, que cubre ALGUNAS familias pero NO todas;\\n(b) el negocio es de un familiar y tu no decides las compras grandes, pero SI las chicas;\\n(c) acabas de surtirte completo de lo principal, aunque hay una linea que si te falta;\\n(d) tu presupuesto de este mes ya se fue, pero el proximo si tienes.\\n\\nCOMO RESPONDES:\\n- Si el vendedor te pregunta como va todo, le cuentas tu situacion con honestidad y sin rodeos. No la escondes.\\n- SI EL VENDEDOR SE RINDE al oir tu impedimento y se despide: te despides con gusto, sin insinuarle que habia otra via. Se va sin la venta que si estaba disponible.\\n- SI EL VENDEDOR INVESTIGA LOS LIMITES de tu restriccion (que cubre exactamente, que queda fuera, hasta cuando dura): le contestas con claridad y ahi le revelas el hueco — lo que SI puedes comprar.\\n- SI TE OFRECE algo dentro de lo que si puedes: te interesa de verdad y avanzas, aunque sea volumen chico.\\n- SI TE PRESIONA para romper tu compromiso o te insiste en lo que ya dijiste que no puedes: te incomodas y te cierras.\\n- SI TE PREGUNTA cuando cambia tu situacion: se lo dices con gusto.\\n\\nNUNCA ofrezcas tu el hueco por tu cuenta: solo lo revelas si el vendedor investiga. Responde en 1 o 2 frases, natural.", "objective": "El vendedor descubre por que este cliente no esta comprando y distingue si es un rojo genuino o alguien dispuesto con un impedimento temporal. Si es rojo, sale bien y rapido. Si esta amarrado, investiga los limites de la restriccion, busca lo que SI puede venderle hoy, y deja sembrado el momento en que la restriccion se acabe. El scope se cubre cuando el vendedor ha ejecutado correctamente el camino que corresponde al caso."}, "closing": {"message": "Eso es calificar bien. No confundiste ''no puedo hoy'' con ''no quiero nunca''. Investigaste hasta donde llegaba su impedimento, encontraste lo que si podia comprar, y dejaste sembrado el dia que se libere. El que se rinde al primer no se va con las manos vacias de un cliente que si queria comprarle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo que habia disponible en esa visita."}}, "version": "2.1.0", "i_do_type": "demo", "failure_criteria": [{"id": "insiste_en_rojo", "regla_id": "discovery.rojo_insistir", "severity": "critical", "description": "Ante un ROJO GENUINO — cliente que no quiere, desganado o cortante — sigue intentando convencerlo despues de conocer la razon. Le roba tiempo a otro cliente e incomoda a alguien que fue honesto. NO aplica cuando el cliente es amable y su impedimento es circunstancial: ahi seguir buscando es lo correcto.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "suelta_un_amarillo", "regla_id": "discovery.suelta_amarrado", "severity": "critical", "description": "Ante un cliente AMABLE y dispuesto cuyo impedimento es una circunstancia temporal, se rinde y se va sin investigar los limites de esa restriccion ni buscar que si puede venderle hoy. Es la falla mas cara del oficio: ese cliente queria comprar y el vendedor se fue solo.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "no_califica", "regla_id": "discovery.suelta_amarrado", "severity": "major", "description": "Nunca llega a descubrir la razon: se queda platicando encantado sin averiguar por que este cliente no esta comprando."}, {"id": "no_investiga_limites", "regla_id": "discovery.bordes_restriccion", "severity": "major", "description": "Descubre una restriccion parcial (un contrato, una exclusividad, una politica) y la toma como total sin preguntar que cubre y que deja fuera. Es donde vive la venta que la competencia no vio."}, {"id": "salida_seca", "regla_id": "consolidation.salida_seca", "severity": "minor", "description": "Sale sin dejar puerta abierta ni cerrar en buenos terminos. Manana ese cliente ya no lo recibe.", "severity_override": {"razon": "incidental: error de otro paso", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "minor", "description": "Presenta producto o precio antes de haber entendido la situacion del cliente.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}], "success_criteria": [{"id": "qualification.luz_verde", "weight": 0.55, "regla_id": "discovery.rojo_vs_amarrado", "description": "Distingue QUE TIPO de no es. Hay dos casos y se ejecutan distinto. (A) ROJO GENUINO — el cliente no quiere, no le interesa, o es cortante y desganado: aqui la ejecucion correcta es ACEPTAR y SALIR bien, sin insistir. (B) AMARRADO TEMPORALMENTE — el cliente es amable, honesto, te recibe con gusto, y la razon por la que no compra es una circunstancia que va a cambiar (un contrato, no ser el que decide, un inventario recien surtido): aqui SALIR ES LA FALLA. Se acepta la circunstancia sin pelearla, se busca que SI se puede vender hoy dentro de esa restriccion, y se deja sembrado el momento en que cambie. Acreditar cualquiera de las dos ejecuciones segun el caso que el Actor haya presentado."}, {"id": "discovery.preguntas_capas", "weight": 0.45, "regla_id": "discovery.escalera_capas", "description": "Llega a la razon real preguntando, no adivinando ni rindiendose antes de saber. Y si la razon es una restriccion parcial, INVESTIGA SUS LIMITES: que cubre exactamente, que queda fuera, hasta cuando dura. Ahi es donde suele estar la venta que nadie mas encontro. Cierra dejando la puerta abierta, sin quemar la relacion ni despedirse en seco."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"3.7","world_id":3,"name":"El Cliente que Ya Te Compra","technique":"dos_juegos","order_index":7,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":2,"description":"Todo lo que aprendiste sirve para encontrar dolor. Pero un cliente contento no tiene dolor — y ahi es donde se pierde la mayor parte del dinero.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"recurrente"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"3.8","world_id":3,"name":"Lee el Lugar","technique":"lee_el_lugar","order_index":8,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":2,"description":"Ya sabes que un cliente contento tiene huecos y no dolor. Aqui aprendes a encontrarlos.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: este cliente ya te compra. Averigua QUE MAS maneja aparte de lo tuyo, de quien lo compra, y que le falta. No preguntes si tiene problemas: pregunta por su catalogo completo.","practice_script":{"notes": "v2.0.0 Nodo nuevo — doctrina de desarrollo de cuenta (CAMPO, Emilio). El Actor es un cliente contento SIN dolor: la escalera de capas no funciona aqui a proposito. El espejo clave es la falla invisible — si el vendedor solo revisa la cuenta, la sesion termina bien y no pasa nada malo. Solo en el feedback descubre lo que habia.", "scope": {"skills_in_focus": ["discovery.lee_el_lugar", "discovery.hueco"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en que NO pregunto si tiene algun problema. Este cliente esta contento y no tiene ninguno.\\n\\nLo que hago es mapear su catalogo: que maneja, de quien, y que no maneja nadie.\\n\\nCada respuesta me dice si ahi hay un espacio para mi o no.", "first_message": "Oiga don [nombre], aparte de lo que nos compra a nosotros, que otras lineas maneja aqui?\\n\\nEl: (me dice tres o cuatro familias)\\n\\nAh mire. Y esas de quien las trae?\\n\\nEl: (me dice con quien)\\n\\nY de lo que le llega a pedir la gente, hay algo que no maneje y termine mandando a otro lado?\\n\\nEl: (y ahi sale el hueco mas facil de todos: demanda que ya existe y nadie cubre)"}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO. No tienes ningun problema, ninguna queja y ningun dolor con lo que te surten. Si el vendedor te pregunta si algo anda mal, si tienes problemas o si algo te falla, contestas con sinceridad que no: todo bien, sin quejas. NO inventes dolores para ayudarle.\\n\\nEres el dueno de un negocio que ya le compra a este vendedor desde hace tiempo, con buena relacion. Adopta el tipo de negocio y las familias de producto que describa el contexto de la empresa.\\n\\nTU CATALOGO: manejas VARIAS familias de producto. Reparte asi, y manten el reparto toda la sesion: 1 o 2 familias se las compras a ESTE vendedor. Otras 2 se las compras a OTRO proveedor desde hace anos, sin ningun problema. Y hay 1 familia que tus clientes te piden de vez en cuando y tu NO manejas, asi que los mandas a otro lado.\\n\\nCOMO RESPONDES: si el vendedor te pregunta que otras lineas manejas, se las dices con naturalidad. Si te pregunta de quien las traes, tambien. Si te pregunta si te piden algo que no tengas, ahi le cuentas lo que mandas a otro lado. Pero NUNCA ofreces nada de esto por tu cuenta: para ti no es un tema, ya lo tienes resuelto.\\n\\nSI EL VENDEDOR SOLO PREGUNTA POR LO QUE YA TE VENDE: contestas contento que todo bien, y la conversacion se queda ahi sin que pase nada. No le ayudas y no te molestas: simplemente nunca se entera de lo demas.\\n\\nResponde en 1 o 2 frases, natural.\\n\\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor mapea el catalogo del cliente mas alla de lo que ya le vende: que otras familias maneja, con quien las compra, y que le piden que no tenga. El scope se cubre cuando el vendedor ha identificado al menos un hueco concreto — una familia con otro proveedor o una que nadie cubre."}, "closing": {"message": "Eso es leer el lugar. No preguntaste si tenia problemas, porque no los tiene. Mapeaste lo que maneja y con quien, y ahi aparecieron los espacios que llevaban anos frente a ti sin que los vieras. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo que habia en ese mostrador que no alcanzaste a ver."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "solo_revisa_la_cuenta", "regla_id": "develop.visita_tramite", "severity": "major", "description": "Solo pregunta por los productos que ya le vende. La sesion transcurre bien, el cliente contesta contento, y el vendedor sale sin enterarse de todo lo que ese cliente compra en otro lado."}, {"id": "busca_dolor_donde_no_hay", "regla_id": "discovery.dolor_directo", "severity": "minor", "description": "Insiste en preguntar si algo anda mal, si tiene problemas o si algo le falla, con un cliente que ya dijo que esta contento. Gasta la visita buscando un dolor inexistente en lugar de buscar el hueco.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "hueco_inventado", "regla_id": "discovery.hueco_inventado", "severity": "critical", "description": "Afirma que el cliente necesita algo sin que el cliente lo haya dicho ni exista evidencia. Fabricar un hueco es venderle un problema que no tiene."}, {"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "minor", "description": "Empieza a presentar producto antes de terminar de mapear. Aqui solo se descubre.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}], "success_criteria": [{"id": "discovery.lee_el_lugar", "weight": 0.5, "regla_id": "discovery.lee_el_lugar", "description": "Pregunta por el catalogo COMPLETO del cliente, mas alla de lo que ya le compra: que otras familias maneja y de quien las trae. Preguntar solo por lo que ya le vende no cumple: eso es revisar la cuenta, no mapear el territorio."}, {"id": "discovery.hueco", "weight": 0.5, "regla_id": "discovery.hueco", "description": "Identifica al menos un hueco concreto y lo nombra: una familia que el cliente compra con otro proveedor, o una que sus clientes le piden y no maneja nadie. Debe quedar claro en la conversacion cual es el espacio disponible, no solo que existe."}]},"tipo_cliente":"recurrente"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"3.9","world_id":3,"name":"El Hueco en Vivo","technique":"hueco","order_index":9,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":3,"description":"Las tres herramientas juntas, con un cliente que te va a dar el pedido de siempre y quedarse tan contento.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: este cliente te va a dar su pedido de siempre, con gusto. Levantalo. Pero no te vayas sin averiguar que MAS podria comprarte y hoy no. Usa las tres herramientas.","practice_script":{"notes": "v2.0.0 Nodo nuevo — el corazon de la doctrina de desarrollo (CAMPO, Emilio). EL ESPEJO ES LA FALLA INVISIBLE: si el vendedor solo levanta el pedido, el Actor queda contento y la sesion termina bien. No hay castigo en la conversacion. El vendedor solo descubre lo que perdio en el feedback — que es exactamente como funciona en la calle, y por eso el problema dura anos sin que nadie lo note.", "scope": {"skills_in_focus": ["discovery.hueco", "discovery.lee_el_lugar", "impulse.efecto_jones"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 14, "max_duration_seconds": 280, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Mira las tres herramientas juntas, y fijate en el orden.\\n\\nPrimero levanto el pedido, porque a eso vine y porque me da pie. Pero no me voy ahi.\\n\\nMapeo lo que maneja. Pregunto por lo que le piden y no tiene. Y anclo en negocios como el suyo. Tres preguntas mas, dos minutos, y salgo sabiendo donde estan mis espacios.", "first_message": "Perfecto, le anoto lo de siempre entonces.\\n\\nOiga, y ya que ando por aca — aparte de esto que nos compra, que otras lineas maneja?\\n\\nEl: (me dice)\\n\\nY de lo que le llega a pedir la gente, hay algo que no tenga y termine mandando a otro lado?\\n\\nEl: (ahi sale la demanda que esta perdiendo)\\n\\nMire, y le comento: varios negocios como el suyo por aca tambien nos mueven esa linea. Usted eso lo llega a manejar o lo deja pasar?"}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO y sin ningun problema. Si te preguntan si algo anda mal, contestas con sinceridad que no. NO inventes dolores.\\n\\nEres el dueno de un negocio que le compra a este vendedor desde hace anos. Buena relacion, trato de confianza. Adopta el tipo de negocio y las familias de producto del contexto de la empresa.\\n\\nEN TU PRIMER TURNO le das tu pedido de siempre, ya listo, sin que te lo pida: le dices que le vas a pedir lo mismo de la vez pasada y le das las cantidades. Con gusto y sin rodeos.\\n\\nTU CATALOGO: manejas varias familias. 1 o 2 se las compras a este vendedor. Otras 2 se las compras a OTRO proveedor desde hace anos. Y hay 1 que tus clientes te piden y tu no manejas, asi que los mandas a otro lado.\\n\\nCOMO REACCIONAS:\\n\\nSI EL VENDEDOR SOLO LEVANTA EL PEDIDO y se despide: le agradeces, quedas contento, y la visita termina bien. NO le ofreces nada mas, NO le insinuas que hay mas, y NO te molestas. Para ti fue una buena visita. Este es el caso importante: todo sale bien y el vendedor nunca se entera de nada.\\n\\nSI TE PREGUNTA POR TU CATALOGO o por lo que te piden y no tienes: se lo cuentas con naturalidad, sin problema.\\n\\nSI TE ANCLA EN OTROS NEGOCIOS (varios negocios como el suyo mueven tal cosa): te da curiosidad genuina y preguntas mas — cuanto se mueve, quien lo trae, como les va. Ahi tu interes SUBE de forma visible.\\n\\nSI TE INVENTA UNA NECESIDAD que no tienes: te extranas y lo corriges con calma. Eso no lo manejo ni me lo piden.\\n\\nResponde en 1 o 2 frases, natural.\\n\\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor levanta el pedido de siempre y ADEMAS descubre al menos un hueco concreto usando las herramientas: mapear el catalogo, preguntar por lo que le piden y no tiene, o anclar en negocios similares. El scope se cubre cuando el vendedor identifica un espacio real y el cliente lo confirma."}, "closing": {"message": "Ahi esta la diferencia entre una visita y una visita que sirve. Levantaste el pedido, que era lo minimo, y ademas saliste sabiendo que mas puede comprarte. Ese cliente lleva anos comprando en otro lado algo que tu tienes. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo que se quedo sobre la mesa en esa visita."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "solo_levanta_pedido", "regla_id": "develop.visita_tramite", "severity": "critical", "description": "Levanta el pedido de siempre y se despide sin explorar nada mas. La visita sale bien, el cliente queda contento, y el vendedor no se entera de lo que ese cliente compra en otro lado. Es la falla mas cara del oficio, y la mas facil de no notar.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "hueco_inventado", "regla_id": "discovery.hueco_inventado", "severity": "critical", "description": "Afirma que el cliente necesita algo sin evidencia y sin que el cliente lo haya dicho. Fabricar un hueco es venderle un problema que no tiene, y con un cliente de cartera eso se descubre siempre."}, {"id": "jones_falso", "regla_id": "impulse.jones_vago", "severity": "critical", "description": "Inventa que otros negocios compran algo, o cifras que no puede sostener. La prueba social tiene que ser real y verificable."}, {"id": "busca_dolor_donde_no_hay", "regla_id": "discovery.dolor_directo", "severity": "minor", "description": "Insiste en buscar problemas con un cliente que ya dijo que esta contento, en lugar de buscar el hueco.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}], "success_criteria": [{"id": "discovery.hueco", "weight": 0.45, "regla_id": "discovery.hueco", "description": "Identifica y nombra al menos un hueco concreto: una familia que el cliente compra con otro proveedor, o una que le piden y no maneja. No basta con preguntar: el hueco debe quedar identificado en la conversacion."}, {"id": "discovery.lee_el_lugar", "weight": 0.35, "regla_id": "discovery.lee_el_lugar", "description": "Mapea el catálogo del cliente más allá de lo que ya le vende: averigua, de al menos una familia que hoy no le vende, si el cliente la maneja y con quién. No se exige un número de familias. Levantar el pedido y despedirse no cumple, por muy correcta que sea la visita."}, {"id": "impulse.efecto_jones", "weight": 0.2, "regla_id": "impulse.efecto_jones", "description": "Ancla en negocios similares para abrir una familia nueva (negocios como el suyo tambien mueven X). Debe ser una afirmacion que el vendedor pueda sostener: si inventa clientes o cifras, no se acredita y se marca falla."}]},"tipo_cliente":"recurrente"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"3.9b","world_id":3,"name":"El Cliente que Llega Pidiendo","technique":"hueco","order_index":10,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":3,"description":"Un cliente nuevo de luz verde te pide algo en cuanto sabe quién eres. Tómale el pedido, y descubre qué más puede comprarte desde la primera visita.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"En tu próxima visita a un cliente nuevo que te pida algo solo, tómale el pedido y antes de irte pregúntale qué otras líneas maneja y con quién.","practice_script":{"notes": "v1.0.0 Nodo nuevo (oct-2026, Emilio): gemelo del 3.9 con un cliente NUEVO de luz verde, que pide algo en cuanto sabe quién eres. Misma falla espejo: tomar lo que te pidió y salir. Lo que te pidió es la puerta, no el techo.", "scope": {"skills_in_focus": ["discovery.hueco", "discovery.lee_el_lugar", "impulse.efecto_jones"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 14, "max_duration_seconds": 280, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Este cliente es nuevo y es luz verde: en cuanto supo quién soy, me pidió algo.\\n\\nLa tentación es anotar y salir corriendo con el pedido. No. Primero se lo tomo, sin ponerlo en duda, porque me da pie. Pero no me voy ahí.\\n\\nMapeo lo que maneja. Pregunto por lo que le piden y no tiene. Y anclo en negocios como el suyo. Lo que me pidió es la puerta, no el techo.", "first_message": "Perfecto, se lo anoto.\\n\\nOiga, y ya que ando por acá — aparte de esto que me pidió, ¿qué otras líneas maneja?\\n\\nÉl: (me dice cuáles, y con quién)\\n\\nY de lo que le llega a pedir la gente, ¿hay algo que no tenga y termine mandando a otro lado?\\n\\nÉl: (ahí sale la demanda que está perdiendo)\\n\\nMire, y le comento: varios negocios como el suyo por acá también nos mueven esa línea. ¿Usted eso lo llega a manejar o lo deja pasar?"}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente NUEVO, contento, de LUZ VERDE, sin ningún problema. Si te preguntan si algo anda mal, contestas con sinceridad que no. NO inventes dolores.\\n\\nEs la PRIMERA vez que este vendedor te visita: no lo conoces ni a él ni a su empresa. Nunca hables de ''lo de siempre'', de ''la vez pasada'' ni de algo que ya le compres. Adopta el tipo de negocio y las familias de producto del contexto de la empresa.\\n\\nEN CUANTO EL VENDEDOR TE DICE QUIÉN ES O QUÉ TRAE, le pides UNA cosa concreta de lo que él maneja, con cantidad, porque justo se te está acabando: ''¿Ustedes traen X? Qué bueno, porque ya se me está acabando. Tráigame tantas.'' Con gusto y sin rodeos. Si todavía no te dijo qué trae, se lo preguntas tú: ''¿Y usted qué maneja?''.\\n\\nTU CATÁLOGO: manejas varias familias. La que le acabas de pedir se te está acabando. Otras 2 se las compras a OTRO proveedor desde hace años. Y hay 1 que tus clientes te piden y tú no manejas, así que los mandas a otro lado.\\n\\nCOMO REACCIONAS:\\n\\nSI EL VENDEDOR SOLO TE TOMA EL PEDIDO y se despide: le agradeces, quedas contento, y la visita termina bien. NO le ofreces nada más, NO le insinúas que hay más, y NO te molestas. Este es el caso importante: todo sale bien y el vendedor nunca se entera de nada.\\n\\nSI TE PREGUNTA POR TU CATÁLOGO: le dices con naturalidad qué familias manejas y con quién las traes. Nunca digas que le compras algo a él: solo le acabas de pedir una cosa. SI TE PREGUNTA POR LO QUE TE PIDEN Y NO TIENES: se lo cuentas sin problema.\\n\\nSI TE ANCLA EN OTROS NEGOCIOS (varios negocios como el suyo mueven tal cosa): te da curiosidad genuina y preguntas más — cuánto se mueve, quién lo trae, cómo les va. Ahí tu interés SUBE de forma visible.\\n\\nSI TE INVENTA UNA NECESIDAD que no tienes: te extrañas y lo corriges con calma. Eso no lo manejo ni me lo piden.\\n\\nResponde en 1 o 2 frases, natural.\\n\\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMÁS te avienta tres o cuatro opciones concretas, contestas de inmediato con un dato ESPECÍFICO — o eliges una de sus opciones, o lo corriges con el producto o la cifra real. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SÍ puedes contestar vago.", "objective": "El vendedor le toma el pedido al cliente nuevo que llegó pidiendo y ADEMÁS descubre al menos un hueco concreto usando las herramientas: mapear el catálogo, preguntar por lo que le piden y no tiene, o anclar en negocios similares. El scope se cubre cuando el vendedor identifica un espacio real y el cliente lo confirma."}, "closing": {"message": "Ahí está la diferencia. El cliente te pidió solo, y tú no te conformaste con lo que te pidió: desde la primera visita saliste sabiendo qué más puede comprarte. Vamos al detalle.", "message_incomplete": "Ahí lo dejamos. Vamos al desglose y te digo qué se quedó sobre la mesa en esa primera visita."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "solo_levanta_pedido", "regla_id": "develop.visita_tramite", "severity": "critical", "description": "Toma el pedido que el cliente le hizo y se despide sin explorar nada más. La visita sale bien, el cliente queda contento, y el vendedor no se entera de lo que ese cliente compra en otro lado. Con un cliente que llegó pidiendo solo, es la falla más fácil de no notar.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "hueco_inventado", "regla_id": "discovery.hueco_inventado", "severity": "critical", "description": "Afirma que el cliente necesita algo sin evidencia y sin que el cliente lo haya dicho. Fabricar un hueco es venderle un problema que no tiene, y un cliente nuevo que lo descubre ya no te vuelve a creer."}, {"id": "jones_falso", "regla_id": "impulse.jones_vago", "severity": "critical", "description": "Inventa que otros negocios compran algo, o cifras que no puede sostener. La prueba social tiene que ser real y verificable."}, {"id": "busca_dolor_donde_no_hay", "regla_id": "discovery.dolor_directo", "severity": "minor", "description": "Insiste en buscar problemas con un cliente que ya dijo que esta contento, en lugar de buscar el hueco.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}], "success_criteria": [{"id": "discovery.hueco", "weight": 0.45, "regla_id": "discovery.hueco", "description": "Identifica y nombra al menos un hueco concreto: una familia que el cliente compra con otro proveedor, o una que le piden y no maneja. No basta con preguntar: el hueco debe quedar identificado en la conversacion."}, {"id": "discovery.lee_el_lugar", "weight": 0.35, "regla_id": "discovery.lee_el_lugar", "description": "Mapea el catálogo del cliente más allá de lo que le pidió: averigua, de al menos una familia que no le pidió, si el cliente la maneja y con quién. No se exige un número de familias. Tomar el pedido y despedirse no cumple, por muy correcta que sea la visita."}, {"id": "impulse.efecto_jones", "weight": 0.2, "regla_id": "impulse.efecto_jones", "description": "Ancla en negocios similares para abrir una familia nueva (negocios como el suyo tambien mueven X). Debe ser una afirmacion que el vendedor pueda sostener: si inventa clientes o cifras, no se acredita y se marca falla."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"3.10","world_id":3,"name":"BOSS: El Diagnóstico","technique":"diagnostico","order_index":11,"is_boss":true,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"El diagnostico completo, con un cliente que no suelta su dolor facil.","node_type":"boss","conversation_scope":"discovery","engine_type":null,"boss_goal":"Ejecutar la conversación completa desde la apertura hasta un diagnóstico terminado: dolor real excavado por capas, confirmado verbalmente, y con lectura correcta del estado y las señales del cliente en el camino.","field_mission":"TU MISION: la conversacion completa. Abre, presentate, atraviesa el no que va a caer, lee su prisa. Y despues: barre los territorios — producto, servicio, precio — encuentra la pista y excava hasta el dolor completo. Confirmalo con sus palabras. Hoy NO se receta. Solo se diagnostica.","practice_script":{"notes": "BOSS del Mundo 3 — el más completo hasta ahora: integra M0 (apertura), M1 (temple ante sequedad analítica), M2 (historia + AIR) y M3 entero (RRR + capas + escucha + dolor). El Actor combina 4 mecánicas: estado de prisa, un bloqueo espejo, dolor por capas y datos laterales. pitch_prematuro es critical — la línea entre diagnóstico y receta es la frontera del mundo. 16 turnos y 6 mínimos: es una conversación larga de verdad.", "scope": {"skills_in_focus": ["discovery.preguntas_capas", "discovery.dolor_real", "discovery.escucha_activa", "mindset.rrr", "blocks.air", "story.historia_breve"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 16, "max_duration_seconds": 360, "min_turns_before_evaluation": 6}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil ANALÍTICO: preciso, algo reservado, respondes con datos y no con emociones, desconfías un poco de los vendedores porque varios te han hecho perder el tiempo. GUION DE LA SESIÓN: (1) Recibes la apertura con cortesía seca — hoy además andas algo APURADO (estado RRR: lo muestras en frases cortas y alguna mención de que traes pendientes). (2) En tus primeras 2-3 respuestas sueltas UN bloqueo reflejo suave: mire, la verdad ando corto de tiempo, o ya tengo con quién trabajo esto. Espejo AIR: si lo atraviesa bien, sigues; si lo debate, te enfrías. (3) Tienes un DOLOR REAL oculto — elige al azar: (tu proveedor actual te deja plantado con los pedidos cada quincena / tienes producto parado que no se mueve y te tiene el dinero muerto / te piden algo que tu proveedor no maneja). Lo revelas SOLO por capas: hechos → pista sutil en capa de experiencia (la palabra aunque) → dolor completo si excavan la pista. (4) MECÁNICA DE ESCUCHA: en tus respuestas de hechos regala UN dato lateral (un familiar en el negocio, un cambio reciente); si lo recogen, te abres más rápido — la capa 2 llega antes. (5) Si el vendedor lee tu prisa y la reconoce ajustando su ritmo, cooperas mejor. Si presenta producto en cualquier momento, te cierras con evasiva educada y la información se acaba. Tu techo emocional: cooperativo-interesado, nunca efusivo. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.\\n\\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor completa el diagnóstico de punta a punta ante un cliente analítico y apurado: apertura correcta y calibrada, historia breve corta con gancho, UN bloqueo atravesado con AIR, lectura del estado (prisa) reconocida y ajustada, descubrimiento por capas que recoge las pistas laterales y excava la pista del dolor hasta la revelación completa, cerrando con la confirmación verbal del dolor en palabras propias (entonces lo que más le está pegando es X, ¿cierto?). El scope se cubre cuando el dolor real quedó revelado por el cliente Y confirmado por el vendedor."}, "closing": {"message": "Diagnóstico completo: abriste, atravesaste el no, leíste su prisa, y excavaste hasta el dolor que no le cuenta a cualquiera. Un doctor de verdad. Vamos al desglose del mundo.", "message_incomplete": "Hasta aqui la sesion — un diagnostico de verdad no siempre se termina, pero siempre ensena. Vamos al desglose y te digo exactamente donde quedo la excavacion."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "critical", "description": "Presenta producto en cualquier punto — incluso al descubrir el dolor. El diagnóstico termina donde empieza la receta, y la receta es del siguiente mundo.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "ignora_pistas", "regla_id": "discovery.escalera_capas", "severity": "major", "description": "Deja pasar la pista del dolor (el aunque) o los datos laterales de forma sistemática."}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta o negocia el bloqueo en lugar de atravesarlo con AIR.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "ignora_estado", "regla_id": "discovery.rrr", "severity": "major", "description": "El cliente muestra prisa clara y el vendedor avanza a su ritmo propio sin reconocerla ni ajustar."}, {"id": "interrogatorio", "regla_id": "discovery.interrogatorio", "severity": "minor", "description": "Ráfagas de preguntas desconectadas de las respuestas."}, {"id": "kill_curriculum", "regla_id": "story.kill_curriculum", "severity": "minor", "description": "Historia breve inflada con credenciales.", "severity_override": {"razon": "incidental: error de otro paso", "default": "major"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Turnos largos ante un cliente con prisa."}], "success_criteria": [{"id": "discovery.preguntas_capas", "weight": 0.25, "regla_id": "discovery.escalera_capas", "description": "Descubrimiento con progresión de capas visible: hechos → experiencia → excavación de la pista (aunque...) hasta el dolor. Las preguntas nacen de las respuestas."}, {"id": "discovery.dolor_real", "weight": 0.2, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "El dolor completo fue revelado por el cliente Y confirmado verbalmente por el vendedor en sus propias palabras antes del cierre de la sesión."}, {"id": "discovery.escucha_activa", "weight": 0.15, "regla_id": "discovery.escalera_capas", "description": "Recoge al menos un dato lateral regalado por el cliente y construye sobre él con las palabras del cliente."}, {"id": "mindset.rrr", "weight": 0.15, "regla_id": "discovery.rrr", "description": "Lee la prisa del cliente, la reconoce verbalmente con naturalidad y ajusta su ritmo — directo y sin rodeos, respetando el estado."}, {"id": "blocks.air", "weight": 0.15, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo con la secuencia completa: agree breve, ignore total del tema, resume por hilo natural."}, {"id": "story.historia_breve", "weight": 0.1, "regla_id": "story.quien_eres_por_que", "description": "Historia breve correcta en su momento: quién es + por qué está ahí, corta, con gancho."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"4.0","world_id":4,"name":"La Balanza: Valor contra Costo","technique":null,"order_index":0,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":2,"description":"Ya sabes que le duele. Ahora empieza la otra mitad de la venta: convertir ese dolor en valor.","node_type":"knowledge","conversation_scope":null,"engine_type":"classify","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.1","world_id":4,"name":"Conectar con el Dolor","technique":null,"order_index":1,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Tienes la balanza. El primer movimiento es anclar tu presentacion en lo que EL te conto.","node_type":"skill_drill","conversation_scope":"presentation","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: abre tu presentacion nombrando el problema que EL te conto, con SUS palabras. Antes de hablar de lo que tienes, demuestrale que lo escuchaste.","practice_script":{"notes": "El drill aísla la presentación: el Actor declara su dolor en la primera línea (dado por descubierto). Espejo: conexión → interés y señales; genérico → tibieza sin preguntas. El failure baja_su_valor viene directo de la doctrina de Costo vs Valor.", "scope": {"skills_in_focus": ["presentation.conectar_dolor", "presentation.valor_personalizado", "presentation.beneficio_no_caracteristica"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Escucha mi presentación y nota una cosa: cada frase nace del dolor que el cliente me contó. No presento mi catálogo — presento SU problema resuelto.", "first_message": "El cliente me contó que su proveedor lo deja plantado cada quincena y pierde ventas. Mi presentación: Don Ramón, por eso le quiero platicar de esto — usted me dijo que como dos veces al mes se le va un cliente por faltante.\\n\\nNosotros surtimos cada semana, con pedido garantizado: si le fallamos, el flete corre por nuestra cuenta. O sea: esos clientes que hoy manda a la competencia...\\n\\nse quedan comprándole a usted. — ¿Notaste?\\n\\nSu dolor, mi solución, y el beneficio en SU caja. Cero catálogo genérico."}, "you_do": {"prompt": "Eres el dueño de un negocio en la parte final de una buena conversación: el vendedor ya hizo su descubrimiento y TÚ YA LE CONTASTE tu dolor real. Al iniciar la sesión elige uno al azar y dalo por contado: (tu proveedor te deja plantado con pedidos cada quincena y pierdes ventas / tienes producto parado sin movimiento con dinero muerto / te piden algo que tu proveedor no maneja). Tu primera línea de la sesión lo recuerda con naturalidad: Pues sí, como le digo, lo que más me pega es [tu dolor]... a ver, ¿usted qué trae? TU REGLA ESPEJO: si la presentación CONECTA con tu dolor (te menciona tu problema específico y cómo se resuelve, habla de lo que TÚ ganas), respondes con interés creciente — preguntas detalles, das señales de compra suaves (¿y cómo estaría eso del pedido?, ¿cada cuánto surten?). Si la presentación es GENÉRICA (catálogo, calidad, años de experiencia, precios — sin mencionar TU problema), respondes tibio: ajá, suena bien, déjeme pensarlo — y no haces ninguna pregunta. Si te recitan características técnicas sin traducirlas a tu negocio, preguntas con honestidad: ¿y eso a mí de qué me sirve? TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor construye una presentación 100% conectada al dolor declarado del cliente: (1) abre nombrando el dolor específico que el cliente contó (usted me dijo que...), (2) presenta su producto/servicio como solución directa de ESE problema, y (3) traduce cada característica a beneficio concreto en el negocio del cliente (dinero, clientes, tranquilidad). El scope se cubre cuando el cliente mostró interés real — hizo al menos una pregunta de detalle o soltó una señal de compra."}, "closing": {"message": "Esa presentación no la puede dar ningún otro vendedor — porque está hecha con lo que ESTE cliente te contó. Eso es presentar con sistema. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como conectas con lo que le duele. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "presentacion_generica", "regla_id": "present.dos_mitades", "severity": "critical", "description": "Presenta catálogo, calidad, años o precios SIN conectar con el dolor declarado del cliente — la presentación serviría idéntica para cualquier negocio. El pecado central de este mundo.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "caracteristicas_sin_beneficio", "regla_id": "present.caracteristica_sin_traducir", "severity": "major", "description": "Recita datos técnicos o de catálogo sin traducirlos a lo que el cliente gana — el cliente pregunta ¿y eso a mí de qué me sirve?"}, {"id": "baja_su_valor", "regla_id": "close.descuento_de_panico", "severity": "major", "description": "Devalúa su propia oferta ante la primera tibieza: ofrece la línea económica, se retracta, o pide disculpas por el precio antes de que se lo cuestionen."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Presentación en bloque de un solo turno larguísimo, sin pausas ni participación del cliente."}], "success_criteria": [{"id": "presentation.conectar_dolor", "weight": 0.4, "regla_id": "present.dos_mitades", "description": "Abre la presentación nombrando explícitamente el dolor que el cliente declaró (usando sus palabras o muy cercanas) y presenta la oferta como solución directa de ESE problema — el puente dolor→solución es visible en el texto."}, {"id": "presentation.valor_personalizado", "weight": 0.35, "regla_id": "present.beneficio_no_caracteristica", "description": "La presentación está construida para ESTE cliente: referencias a su negocio, su situación y su dolor. Cero frases de catálogo genérico que servirían igual en cualquier otro negocio."}, {"id": "presentation.beneficio_no_caracteristica", "weight": 0.25, "regla_id": "present.beneficio_no_caracteristica", "description": "Traduce características a beneficios: cada dato del producto aparece acompañado de lo que el cliente GANA (deja de perder ventas, recupera dinero parado, clientes que regresan) — no specs sueltas."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.2","world_id":4,"name":"Beneficio, No Caracteristica","technique":"beneficio_no_caracteristica","order_index":2,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":3,"description":"Conectaste con su dolor. Ahora que todo lo que digas signifique algo para el.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: cada cosa que digas de tu producto, traducela. Que gana el cliente con eso: dinero, clientes o tranquilidad. Si no lo traduces, no lo escucha.","practice_script":{"notes": "v2.0.0 Nodo nuevo. El espejo usa la pregunta que el vendedor promedio teme (y eso a mi de que me sirve?) como consecuencia automatica de no traducir. Ensena sin regano.", "scope": {"skills_in_focus": ["presentation.beneficio_no_caracteristica"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en que nunca dejo una caracteristica sola. Digo lo que el producto es, y en la misma frase digo que gana el con eso.\\n\\nLa caracteristica es mi lenguaje; el beneficio es el suyo. Si solo hablo el mio, me escucha sin entender.", "first_message": "Este maneja una formulacion mas estable a temperatura alta. Que significa para usted: le dura mas antes del siguiente cambio, o sea menos servicios al ano por unidad y menos gente reclamandole.\\n\\nY como le dura mas, su cliente regresa contento en lugar de regresar a quejarse."}, "you_do": {"prompt": "Eres el dueno de un negocio, atento y de buena disposicion, escuchando lo que el vendedor te presenta. Ya platicaron antes y ya le contaste que tu problema es que pierdes ventas cuando te falta producto. TU REGLA PRINCIPAL: reaccionas segun el vendedor traduzca o no. Si menciona una CARACTERISTICA sin traducirla a un beneficio concreto (una especificacion tecnica, un dato del producto, una certificacion, una marca), respondes con desinteres educado y le devuelves la pregunta que el vendedor promedio teme: y eso a mi de que me sirve? / ajam, y eso que me ayuda? / si, y? SI la traduce a algo concreto que tu ganas (dinero, mas clientes, menos problemas, tiempo, tranquilidad), te enganchas: asientes, preguntas mas al respecto, y conectas con tu propia situacion. Si te tira MUCHAS caracteristicas juntas sin traducir ninguna, te saturas y dices que lo tienes que pensar. NUNCA traduzcas tu por el: si el no dice el beneficio, tu no lo adivinas. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor traduce cada caracteristica que menciona a un beneficio concreto para ese cliente: dinero, clientes, tiempo o tranquilidad. El scope se cubre cuando el cliente se engancha con al menos dos beneficios traducidos y conecta con su propia situacion."}, "closing": {"message": "Eso es traducir. Dijiste lo que el producto es y en la misma frase lo que el gana. La caracteristica es tu idioma; el beneficio es el suyo. El que solo habla el propio, presenta para si mismo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como presentas. Vamos al desglose y te digo cuales se quedaron sin traducir."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "caracteristica_sin_traducir", "regla_id": "present.caracteristica_sin_traducir", "severity": "major", "description": "Menciona especificaciones, datos tecnicos o certificaciones sin decir que gana el cliente con eso. El cliente escucha sin entender y contesta y eso a mi de que me sirve."}, {"id": "catalogo", "regla_id": "present.caracteristica_sin_traducir", "severity": "major", "description": "Encadena varias caracteristicas seguidas sin traducir ninguna. El cliente se satura y se defiende con un lo voy a pensar."}, {"id": "beneficio_generico", "regla_id": "present.caracteristica_sin_traducir", "severity": "minor", "description": "Traduce a un beneficio que serviria para cualquier negocio (es de calidad, le va a gustar) en lugar de conectarlo con la situacion concreta del cliente.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "promesa_falsa", "regla_id": "present.bala_generica", "severity": "critical", "description": "Inventa un beneficio que el producto no da, o exagera un resultado para que suene mejor. El valor se construye con verdad.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}], "success_criteria": [{"id": "presentation.beneficio_no_caracteristica", "weight": 1, "regla_id": "present.beneficio_no_caracteristica", "description": "Cada caracteristica que menciona va acompanada de su traduccion a algo concreto que el cliente gana: mas dinero, mas clientes, menos tiempo perdido o menos problemas. La traduccion debe ser especifica de ESE negocio, no generica. Mencionar la caracteristica sola no cumple, aunque sea impresionante."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.3","world_id":4,"name":"Pintar la Imagen","technique":null,"order_index":3,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Ya traduces beneficios. Ahora haz que se vea a si mismo con el problema resuelto.","node_type":"skill_drill","conversation_scope":"presentation","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: que el cliente se VEA a si mismo con el problema ya resuelto. No le describas el producto: describele su negocio funcionando.","practice_script":{"notes": "El Actor reacciona a imágenes, no a datos — la mecánica espejo enseña la diferencia entre explicar y pintar en vivo. La señal de scope: el cliente COMPLETÓ una escena con detalles propios (la prueba de que entró en ella).", "scope": {"skills_in_focus": ["presentation.pintar_imagenes", "presentation.conectar_dolor"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Escucha la diferencia entre EXPLICAR y PINTAR. Explicar informa.\\n\\nPintar hace que el cliente se VEA en la escena — y de esa escena ya no se quiere salir.", "first_message": "Explicar suena así: El producto tiene buena movimiento y márgenes competitivos. — Correcto, y frío.\\n\\nPintar suena así: Imagínese la quincena que viene: llega el cliente de siempre por sus tres litros... y ahora sí los tiene.\\n\\nSe los lleva, le deja la ganancia a usted y no al de enfrente — y de pasada se lleva unas grasas porque ya que estaba aquí. ¿Ve la diferencia?\\n\\nEl cliente ya se vio ganando.\\n\\nAhora el producto no es un dato: es esa mañana."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de un buen descubrimiento: ya contaste tu dolor. Elige uno al azar y menciónalo en tu primera línea: (pierdes ventas por faltantes de tu producto estrella / tienes dinero muerto en producto que no se mueve / te piden algo que tu proveedor no maneja). TU REGLA ESPEJO — reaccionas a IMÁGENES, no a datos: si el vendedor te pinta una escena concreta de TU negocio con el problema resuelto (imagínese que..., piense en la próxima quincena cuando..., usted abriendo la cortina y...), entras en la escena: la completas con detalles tuyos (pues sí, y hasta podría..., no pues eso me ahorraría el coraje de...), y tu interés crece visiblemente. Si el vendedor solo explica con datos y adjetivos (buena calidad, excelente margen, muy rentable), respondes cortés pero plano: ajá, ok, suena bien — sin entrar en ninguna escena. Si la escena que pinta es genérica y no usa TU dolor ni TU negocio, respondes: pues sí, como en todos lados, supongo. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor presenta pintando al menos DOS imágenes concretas del negocio del cliente con el problema resuelto: escenas específicas (con momento, personaje o situación reconocible de SU operación) construidas sobre el dolor declarado — no descripciones abstractas del producto. El scope se cubre cuando el cliente ENTRÓ en al menos una escena: la completó con sus propios detalles o expresó verse en ella."}, "closing": {"message": "El cliente se vio en la escena — y de ahí ya no se quiso salir. Eso es pintar imágenes: la parte del cine que tiene este trabajo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como pintas la imagen. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "explica_sin_pintar", "regla_id": "present.pintar_imagenes", "severity": "major", "description": "Presenta solo con datos y adjetivos (calidad, margen, rentable, confiable) sin construir una sola escena visualizable — el cliente permanece fuera, escuchando información."}, {"id": "imagen_generica", "regla_id": "present.pintar_imagenes", "severity": "major", "description": "Sus escenas no usan el dolor ni el contexto del cliente — son postales genéricas de éxito que servirían para cualquiera (le va a ir muy bien, va a vender mucho)."}, {"id": "presentacion_generica", "regla_id": "present.dos_mitades", "severity": "major", "description": "Ignora el dolor declarado y presenta catálogo."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Pinta sin pausa — no deja al cliente entrar a la escena."}], "success_criteria": [{"id": "presentation.pintar_imagenes", "weight": 0.6, "regla_id": "present.pintar_imagenes", "description": "Pinta al menos dos escenas concretas y específicas del negocio del cliente con el problema resuelto: usa lenguaje de visualización (imagínese, piense en, va a ver que) con momento, personajes o situaciones reconocibles de SU operación. Las escenas logran que el cliente entre: las complete o se vea en ellas."}, {"id": "presentation.conectar_dolor", "weight": 0.4, "regla_id": "present.dos_mitades", "description": "Las imágenes nacen del dolor declarado: la escena pintada es exactamente ese problema resuelto — no una fantasía genérica de éxito."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"4.4","world_id":4,"name":"La Curva de Impulso","technique":null,"order_index":4,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":2,"description":"El valor ya esta construido. Ahora la otra mitad: cuanto quiere comprar, y como se mueve eso.","node_type":"knowledge","conversation_scope":null,"engine_type":"classify","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"4.5","world_id":4,"name":"Las Balas: Tu Arsenal","technique":"bullet_theory","order_index":5,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":2,"description":"Sabes que el impulso sube y baja. Aqui esta con que lo subes.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.6","world_id":4,"name":"Disparar Balas","technique":"disparar_balas","order_index":6,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":3,"description":"Tienes tu arsenal. Ahora aprende a dosificarlo.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: sube el impulso con balas REALES sobre ti, tu producto o tu precio. Una a la vez, midiendo la reaccion. Y guarda al menos dos para despues: las vas a necesitar.","practice_script":{"notes": "v2.0.0 Nodo nuevo. Corrige la doctrina deformada: las balas son del VENDEDOR (hechos positivos sobre ti, producto y precio), no objeciones del cliente. El espejo tiene cuatro estados: dosificada sube, rafaga satura, vaga no mueve, exagerada baja.", "scope": {"skills_in_focus": ["objections.bullet_theory"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en el ritmo. Disparo una bala, dejo que aterrice, y veo como reacciona antes de disparar la siguiente.\\n\\nNo suelto tres seguidas. Y fijate en algo mas: me guardo las mejores.\\n\\nTodavia no llego al precio ni a las objeciones, y ahi es donde de verdad las voy a necesitar.", "first_message": "Mire, algo que le puede servir: llevamos catorce anos surtiendo esta zona, asi que cuando hay desabasto general nosotros seguimos entregando. ...\\n\\nY le comento otra cosa: nuestro tiempo de entrega es de veinticuatro horas dentro de la ciudad."}, "you_do": {"prompt": "Eres el dueno de un negocio, ya en confianza con el vendedor y escuchando su propuesta con interes moderado. TU REGLA PRINCIPAL: tu nivel de interes sube y baja segun COMO disparen las balas. Si el vendedor da UN hecho positivo concreto y te deja reaccionar, tu interes SUBE de manera visible: comentas, preguntas mas, te enganchas. Si dispara TRES O MAS hechos seguidos sin pausa, te saturas: tu interes sube un momento y luego CAE, y respondes con algo como pues suena bien todo, dejeme lo pienso. Si el hecho es VAGO o generico (somos los mejores, tenemos calidad, damos buen servicio) no cuenta como bala: contestas con cortesia neutra y tu interes no se mueve. Si el vendedor dice algo que suena EXAGERADO o poco creible, tu interes BAJA y te pones esceptico: pregunta desconfiada tipo a poco?, y todo eso como me lo garantiza? NUNCA hagas objeciones de precio ni de competencia en este ejercicio. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor sube el impulso disparando balas concretas y verificables de una en una, midiendo la reaccion entre cada una, sin saturar y sin exagerar. El scope se cubre cuando el interes del cliente subio de forma sostenida con al menos dos balas bien colocadas."}, "closing": {"message": "Eso es controlar el impulso. Balas reales, una a la vez, midiendo la reaccion. Y lo mas importante: te quedan balas. Cuando llegues al precio y a las objeciones vas a entender por que eso importa tanto. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como disparas. Vamos al desglose y te digo como quedo tu municion."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "rafaga_de_balas", "regla_id": "present.dosificacion_balas", "severity": "major", "description": "Encadena tres o mas hechos positivos sin pausa. El cliente se satura, el impulso sube y cae, y el vendedor se queda sin municion para lo que viene."}, {"id": "balas_vagas", "regla_id": "present.bala_generica", "severity": "major", "description": "Afirmaciones genericas sin dato concreto: somos los mejores, tenemos calidad, damos buen servicio. No mueven el impulso porque cualquiera las dice."}, {"id": "bala_exagerada", "regla_id": "present.bala_generica", "severity": "critical", "description": "Exagera o inventa un hecho para que suene mejor. El cliente se pone esceptico y el impulso baja. El impulso se construye con verdad.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "minor", "description": "Se adelanta a precio o cierre. Aqui solo se construye impulso.", "severity_override": {"razon": "incidental: error de otro paso", "default": "major"}}], "success_criteria": [{"id": "objections.bullet_theory", "weight": 1, "regla_id": "present.balas", "description": "Dispara balas CONCRETAS y verificables sobre si mismo, su producto o su precio: datos, anos, tiempos, casos reales, condiciones especificas. Las dispara DOSIFICADAS, una a la vez, dejando espacio a la reaccion del cliente antes de la siguiente. Afirmaciones vagas (somos los mejores, damos calidad) no cuentan como balas. Encadenar tres o mas sin pausa no cumple, aunque sean buenas."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"4.7","world_id":4,"name":"FUJPIG: Los Seis Factores","technique":"fujpig","order_index":7,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":2,"description":"Las balas son una manera de subir el impulso. Hay seis en total.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.8","world_id":4,"name":"Lo Que Pierde por Esperar","technique":null,"order_index":8,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Los dos primeros aceleradores: hacer visible lo que el cliente pierde HOY, y darle razones reales para decidir ahora.","node_type":"skill_drill","conversation_scope":"presentation","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: usa el miedo a la perdida y la urgencia con hechos REALES. Que vea lo que se le va si espera. Nada inventado.","practice_script":{"notes": "Primer drill de impulso. El Actor arranca en interesado-pasivo (déjeme pensarlo) — el estado real más común del campo. Espejo de tres vías: verdad tangible → movimiento; urgencia real → siguiente paso; teatro → escepticismo con castigo de confianza. impulso_falso es critical en TODO el mundo 5: la ética es el diseño.", "scope": {"skills_in_focus": ["impulse.miedo_perdida", "impulse.urgencia"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Escucha los dos aceleradores — y fíjate en el detalle más importante: TODO lo que digo es verdad verificable. El miedo a la pérdida se construye con SUS números, y la urgencia con fechas y hechos reales.\\n\\nNi una gota de teatro.", "first_message": "Miedo a la pérdida, con sus datos: Usted me dijo que pierde como dos clientes al mes por faltantes. Son veinticuatro al año, Don Ramón — y cada uno se lleva sus compras a la competencia...\\n\\ny a veces ya no regresa. Eso está pasando hoy, mientras platicamos.\\n\\nUrgencia, con hechos reales: Esta semana ando levantando los pedidos de la zona — si lo dejamos para la otra, su primer surtido le llegaría hasta el mes que entra. ¿Ve?\\n\\nNada inventado: su pérdida es real y mi fecha es real. Por eso funciona."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de una buena presentación: el vendedor ya conectó con tu dolor (elígelo al azar: pierdes ~2 clientes al mes por faltantes de tu proveedor / tienes ~15 mil pesos muertos en producto que no se mueve / te piden algo que tu proveedor no maneja y se van con ella a otro lado) y estás INTERESADO PERO PASIVO: tu postura inicial es está bueno, déjeme pensarlo y luego le digo — sin rechazo, pura inercia de no decidir. TU REGLA ESPEJO: (A) si el vendedor hace TANGIBLE tu pérdida con TUS números y datos reales (lo que pierdes al mes, a dónde se va ese dinero, que está pasando HOY), tu pasividad se mueve: pues sí, viéndolo así... y preguntas algo concreto. (B) si te da una razón de urgencia REAL y verificable (su ruta de pedidos de la semana, tiempos de entrega reales, un ciclo real de tu negocio como la quincena o la temporada), tu decisión se acerca: preguntas por el siguiente paso. (C) si INVENTA escasez o urgencia con olor a teatro (es el último que me queda, la promoción se acaba HOY, ya casi no tengo), respondes con escepticismo directo: mmm, eso dicen todos, ¿no? — y tu confianza BAJA visiblemente. (D) si solo repite valor sin acelerador, permaneces amable y pasivo: sí, suena bien, yo le aviso.", "objective": "El vendedor mueve a un interesado-pasivo aplicando los dos aceleradores con verdad: (1) hace tangible la pérdida actual usando los números y datos que el cliente declaró (cuantifica lo que pierde por mes/año, nombra a dónde se va), y (2) da al menos una razón de urgencia real y verificable para decidir ahora (ruta, tiempos, ciclo del negocio) — sin inventar escasez ni teatro. El scope se cubre cuando el cliente pasó de déjeme pensarlo a preguntar por el siguiente paso concreto."}, "closing": {"message": "Lo moviste — y sin inventarle nada: su pérdida era real y tu fecha era real. Así se acelera una curva sin quemar la confianza. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como manejas el miedo a perder. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "impulso_falso", "regla_id": "impulse.escasez_inventada", "severity": "critical", "description": "Inventa escasez, urgencia o presión sin ancla real: es el último, la promo se acaba hoy, ya casi no tengo, otros lo están apartando. El cliente lo huele (eso dicen todos) y la confianza construida en tres mundos se quema en una frase. El pecado capital de este mundo."}, {"id": "presion_directa", "regla_id": "impulse.presion_directa", "severity": "major", "description": "Sustituye los aceleradores por presión frontal: ándele, anímese, no lo piense tanto, ¿entonces qué, sí o no? — empuja la curva en vez de acelerarla."}, {"id": "perdida_generica", "regla_id": "impulse.miedo_perdida_generico", "severity": "major", "description": "Habla de pérdida en abstracto (está perdiendo dinero, le conviene) sin usar los números ni el dolor específico que el cliente declaró."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Descarga ambos aceleradores en un solo bloque sin dejar reaccionar al cliente."}], "success_criteria": [{"id": "impulse.miedo_perdida", "weight": 0.5, "regla_id": "impulse.miedo_perdida", "description": "Hace tangible la pérdida ACTUAL con los datos del cliente: cuantifica (clientes/dinero por mes o año), nombra el destino de la pérdida (la competencia, el dinero muerto), y la ancla en el presente (está pasando hoy). Todo derivado de lo que el cliente declaró — nada inventado."}, {"id": "impulse.urgencia", "weight": 0.5, "regla_id": "impulse.urgencia", "description": "Da al menos una razón real y verificable para decidir ahora: su ruta o ciclo de pedidos, tiempos de entrega concretos, o un ciclo real del negocio del cliente. La urgencia nace de hechos, no de presión — y el cliente la recibe sin escepticismo."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.9","world_id":4,"name":"Mas por Menos y el Efecto Jones","technique":null,"order_index":9,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Los otros dos aceleradores: la ganancia extra que se siente ganga, y la prueba social de los que ya le entraron.","node_type":"skill_drill","conversation_scope":"presentation","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: sube el impulso con la sensacion de ventaja y con prueba social REAL. Otros negocios como el suyo ya lo hacen, y eso tiene que ser verdad.","practice_script":{"notes": "El Actor valida especificidad: hace cuentas ante números creíbles, reconoce referencias reales de zona, y ataca lo vago con ¿como quiénes? — la pregunta que desnuda el Jones falso. El company_brain provee las referencias reales de cada empresa (clientes existentes de la zona) para que el ejemplo dinámico sea verificable.", "scope": {"skills_in_focus": ["impulse.avaricia", "impulse.efecto_jones"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Los últimos dos aceleradores. La avaricia bien usada no es codicia — es mostrarle la ganancia EXTRA en números de su negocio.\\n\\nY el efecto Jones es la fuerza más vieja del mundo: si a los de al lado les funciona, yo también quiero. Con nombres reales — o nada.", "first_message": "Más por menos, con números: Con el margen de esta línea, cada caja le deja ochenta pesos más que la que maneja — son como mil doscientos extra al mes sin vender ni una pieza más. Efecto Jones, con verdad: La negocios de la San José le entró hace dos meses — el señor Aurelio ya va en su tercer pedido.\\n\\nY el negocio grande de la avenida, igual. Por esta zona ya se está moviendo fuerte.\\n\\n¿Nota que no presioné? Solo le mostré la ganancia y le conté quién más ya la está cobrando."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de una buena presentación conectada a tu dolor (elígelo al azar como en drills previos) y estás en modo interesado-pasivo: suena bien, déjeme pensarlo. TU REGLA ESPEJO: (A) si el vendedor te muestra ganancia EXTRA con números concretos y creíbles de tu operación (margen por caja, ahorro al mes, beneficio adicional calculado), tu interés se activa: haces cuentas en voz alta (a ver, ¿ochenta por caja?...) y preguntas detalles. (B) si te da prueba social ESPECÍFICA y verificable (negocio con nombre o ubicación reconocible de tu zona, tiempo que lleva, resultado concreto), tu confianza sube: ah, ¿el de la San José? sí lo ubico... y tu resistencia baja visiblemente. (C) si la prueba social es VAGA (muchos clientes, varios negocios, todo mundo lo está llevando — sin un solo nombre o referencia verificable), respondes escéptico: ¿ah sí? ¿como quiénes? — y si no puede concretar, tu desconfianza sube. (D) si los números de ganancia son exagerados o redondos sin sustento (va a duplicar sus ventas), respondes: mmm, eso suena a mucho, ¿no?", "objective": "El vendedor aplica los dos aceleradores con concreción: (1) muestra la ganancia extra en números específicos y creíbles del negocio del cliente (margen, ahorro o beneficio mensual calculado), y (2) da prueba social específica y verificable — al menos una referencia con nombre, ubicación o detalle reconocible, con su resultado concreto. El scope se cubre cuando el cliente hizo cuentas en voz alta O validó la referencia social, y pasó de pasivo a preguntar por el siguiente paso."}, "closing": {"message": "Le mostraste la ganancia con números y le contaste quién ya la está cobrando — y su déjeme pensarlo se convirtió en cuánto y cuándo. Así trabajan estos dos. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como construyes la sensacion de ventaja. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "impulso_falso", "regla_id": "impulse.jones_vago", "severity": "critical", "description": "Inventa prueba social o números: referencias que no existen, cifras infladas, todo mundo lo lleva sin poder nombrar a nadie. Si el cliente pregunta ¿como quiénes? y no hay respuesta concreta, el factor era teatro."}, {"id": "promesa_grandilocuente", "regla_id": "present.bala_generica", "severity": "major", "description": "Ganancias exageradas sin sustento: va a duplicar sus ventas, se va a llenar de clientes — el cliente responde eso suena a mucho."}, {"id": "presion_directa", "regla_id": "impulse.presion_directa", "severity": "major", "description": "Cambia los aceleradores por empuje frontal: no se lo pierda, todos le están entrando, apúrese."}, {"id": "perdida_generica", "regla_id": "impulse.miedo_perdida_generico", "severity": "minor", "description": "Ganancia en abstracto (le conviene, va a ganar más) sin un solo número.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}], "success_criteria": [{"id": "impulse.avaricia", "weight": 0.5, "regla_id": "impulse.avaricia", "description": "Muestra ganancia extra con números concretos y creíbles del negocio del cliente: margen por unidad, beneficio mensual calculado, ahorro específico — cifras que el cliente puede verificar con sus propias cuentas, no promesas redondas (duplicar ventas)."}, {"id": "impulse.efecto_jones", "weight": 0.5, "regla_id": "impulse.efecto_jones", "description": "Da al menos una prueba social específica y verificable: negocio con nombre, ubicación o seña reconocible + tiempo + resultado concreto. El cliente la puede validar (o al menos ubicar) — nunca el vago muchos clientes ya lo llevan."}]},"tipo_cliente":"recurrente"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.10","world_id":4,"name":"La Postura del Indiferente","technique":null,"order_index":10,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"La paradoja más rara de las ventas: entre menos necesitas la venta, más vendes. Hoy la practicas contra un cliente que juega a hacerse el difícil.","node_type":"skill_drill","conversation_scope":"presentation","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: emocionado con la persona y con el producto, indiferente a si compra. Si no lo quiere, no pasa nada: tan amigos como siempre.","practice_script":{"notes": "El Actor regateador-probador es un arquetipo real del campo LATAM: prueba con jugadas de difícil buscando desesperación que apretar. El espejo: postura sostenida → las jugadas se agotan; ruego o concesión → huele sangre y aprieta. La indiferencia SW3 es hábito (decay 90) — de los skills que más se oxidan bajo presión de cuota real.", "scope": {"skills_in_focus": ["impulse.indiferencia", "mindset.kilt"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Escucha la postura del indiferente. El cliente se hace el difícil esperando que yo ruegue — y yo estoy emocionado por mi producto pero perfectamente tranquilo con su decisión.\\n\\nEsa combinación desarma: la presión desaparece... y sin presión, el interés de él respira.", "first_message": "Cliente: Mmm, la verdad no sé... hay muchos proveedores dando vueltas, ¿qué tiene usted de especial?\\n\\nYo: Mire, la verdad — el producto me encanta y por eso lo traigo.\\n\\nPero si le sirve o no, eso lo decide usted, que conoce su negocio mejor que nadie. Al de la San José le funcionó para su movimiento; si a usted no le hace sentido, no pasa nada — la zona es grande.\\n\\n¿Le platico cómo lo está usando él, o lo dejamos para otra vuelta? ¿Nota?\\n\\nCero ruego. Y ahora el que no quiere que me vaya...\\n\\nes él."}, "you_do": {"prompt": "Eres el dueño de un negocio de tipo REGATEADOR-PROBADOR: te interesa lo que el vendedor trae (ya te presentó con valor conectado a tu dolor — dalo por hecho y elígelo al azar), pero tu deporte es hacerte el difícil para ver si el vendedor se desespera y ruega — así consigues mejores condiciones y de paso mides con quién tratas. TUS JUGADAS (usa 2-3 en la sesión): no sé, hay muchos proveedores dando vueltas... / ¿y qué tiene usted de especial? / la verdad no me urge... / déjeme ver qué me ofrece el otro primero. TU REGLA ESPEJO: si el vendedor mantiene la POSTURA INDIFERENTE (sigue emocionado por su producto pero tranquilo con tu decisión: te da la razón sin pelear, no ruega, no mejora la oferta sin que la pidas, hasta te ofrece con naturalidad dejarlo para otra vuelta), tus jugadas se agotan — sueltas el juego y muestras tu interés real: bueno, a ver, ¿y cómo estaría eso en pedidos? Si el vendedor RUEGA (insiste, se pone nervioso, suplica la oportunidad) o SE DESINFLA en descuentos y concesiones no pedidas, hueles sangre: aprietas más jugadas y tu respeto baja — al final dices déjeme pensarlo con tono de victoria. Si el vendedor se ofende o se pica con tus jugadas, la conversación se enfría.", "objective": "El vendedor sostiene la postura del indiferente ante un regateador-probador: responde a las jugadas de difícil con tranquilidad y sin pelear (puede darle la razón: claro, hay muchos proveedores), mantiene el entusiasmo por su producto sin rogar ni ofrecer concesiones no pedidas, y conserva la disposición genuina de retirarse bien (si no le hace sentido, no pasa nada / lo dejamos para otra vuelta) — hasta que el cliente suelta el juego y muestra su interés real. El scope se cubre cuando el cliente abandonó las jugadas y preguntó en serio por el siguiente paso."}, "closing": {"message": "Se le acabaron las jugadas — porque no encontró desesperación que apretar. Esa es la paradoja: el que está dispuesto a irse es al que no dejan ir. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi tu postura. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ruega", "regla_id": "impulse.ruega", "severity": "critical", "description": "Suplica la oportunidad o insiste con desesperación: deme chance, no se va a arrepentir, de verdad se lo pido — la sangre que el regateador estaba oliendo. El fallo central de este drill."}, {"id": "concesion_no_pedida", "regla_id": "close.descuento_de_panico", "severity": "major", "description": "Se desinfla ante las jugadas ofreciendo descuentos, regalos o mejoras que nadie pidió — le enseñó al cliente que hacerse el difícil paga."}, {"id": "se_derrumba", "regla_id": "impulse.indiferencia", "severity": "major", "description": "Se ofende, se pica o pierde la calidez ante las jugadas del difícil."}, {"id": "presion_directa", "regla_id": "impulse.presion_directa", "severity": "major", "description": "Convierte la indiferencia en su opuesto: presión frontal para forzar la decisión."}, {"id": "impulso_falso", "regla_id": "impulse.indiferencia_teatral", "severity": "major", "description": "Finge indiferencia con teatro obvio (bueno pues ahí muere, me voy con su competencia) — la indiferencia real es tranquila, no amenazante."}], "success_criteria": [{"id": "impulse.indiferencia", "weight": 0.6, "regla_id": "impulse.indiferencia", "description": "Sostiene la postura SW3 ante todas las jugadas: entusiasmo por el producto intacto + tranquilidad total con la decisión del cliente. No ruega, no insiste con desesperación, no ofrece descuentos ni concesiones no pedidas, y expresa al menos una vez con naturalidad su disposición a retirarse bien (no pasa nada, lo dejamos para otra vuelta)."}, {"id": "mindset.kilt", "weight": 0.4, "regla_id": "impulse.indiferencia", "description": "Cero enganche emocional con las jugadas del difícil: ni se ofende, ni se pica, ni pierde la calidez. Responde a las provocaciones (¿qué tiene de especial?) con amabilidad y sin defensividad — el juego del cliente no le mueve el texto."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.11","world_id":4,"name":"El Poder de Asumir","technique":null,"order_index":11,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"El último acelerador — y el puente directo al cierre: avanzar asumiendo el interés, sugiriendo el paso siguiente como lo más natural del mundo.","node_type":"skill_drill","conversation_scope":"presentation","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: elimina las preguntas de si o no. Ofrece alternativas donde las dos opciones te sirven, y asume que va avanzando.","practice_script":{"notes": "El puente directo al M6: el cierre asumido es esta habilidad aplicada al momento de la decisión. El Actor tiene la inercia real del campo: interesado pero pasivo — usa toda puerta al no que le regalen, fluye con todo avance natural, y castiga la presión con espérese. La distinción asumir/presionar (critical) es el corazón ético del nodo.", "scope": {"skills_in_focus": ["impulse.poder_asumir", "presentation.tren_si_si"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "El último acelerador. Fíjate en mi lenguaje: nunca pregunto SI le interesa — asumo el interés que ya me demostró, y sugiero el siguiente paso como lo más natural del mundo.\\n\\nCada frase avanza sin abrir una sola puerta al no.", "first_message": "Lenguaje que abre puertas al no: ¿Le interesaría probarlo? ¿Quiere que le mande información?\\n\\n— cada pregunta invita un no gratis. Lenguaje que asume: Mire, para su movimiento lo que le va a funcionar es empezar con la caja mixta.\\n\\nSe la traigo el jueves que ando por acá y ya la quincena la agarra surtido. Le va a encantar cómo se mueve.\\n\\n— ¿Notó? No pregunté si quiere: sugerí cuál, cuándo y qué sigue.\\n\\nSi algo no le late, él me lo dice — pero yo no le regalo la puerta del no."}, "you_do": {"prompt": "Eres el dueño de un negocio con la curva de impulso ARRIBA: el vendedor ya te presentó con valor (dalo por hecho, elige tu dolor al azar), ya le hiciste preguntas de detalle y estás genuinamente interesado — pero NO vas a tomar la iniciativa: los clientes casi nunca dicen véndame, esperan a que el vendedor avance. TU REGLA ESPEJO: (A) si el vendedor AVANZA asumiendo con naturalidad (te sugiere el producto/cantidad específica para tu caso, propone día y logística concreta, usa lenguaje de cuando ya no de si acaso), fluyes con el avance: aceptas, ajustas detalles (mejor el viernes, mejor empezar con media caja) — participas en el plan como algo que ya está pasando. (B) si el vendedor te pregunta SI te interesa o SI quieres (¿le interesaría?, ¿quiere que...?, ¿cómo ve?), tu inercia natural responde tibio: pues déjeme ver, mándeme la información — la puerta al no que te abrieron, la usas sin pensar. (C) si el vendedor asume con PRESIÓN (da por cerrada una venta que no aceptaste, te apura, ignora un ajuste que pediste), te incomoda: espérese, yo no he dicho que sí. (D) si el avance ignora lo que platicaron (sugiere algo desconectado de tu dolor), lo corriges: pero yo lo que necesito es lo otro.", "objective": "El vendedor avanza la conversación asumiendo el interés demostrado: sugiere el siguiente paso concreto (producto/cantidad específica para el caso + día/logística) con lenguaje natural de cuando en vez de si acaso, sin abrir puertas al no (sin ¿le interesaría?, ¿quiere que...?) y SIN presión — respetando y adaptándose a los ajustes que el cliente pida. El scope se cubre cuando el cliente participó del plan sugerido (aceptó o ajustó detalles) como algo que ya está en marcha."}, "closing": {"message": "No le preguntaste si quería — le sugeriste el camino, y él lo caminó ajustando los detalles. Eso es asumir: ni presión ni permiso. En el siguiente mundo, esta habilidad se convierte en el cierre. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como asumes. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "abre_puerta_al_no", "regla_id": "close.mal_cierre", "severity": "major", "description": "Pregunta si en vez de asumir cuando: ¿le interesaría?, ¿quiere que le mande información?, ¿lo piensa y me avisa? — cada una invita el no gratis y el cliente la usa (déjeme ver).", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "asume_con_presion", "regla_id": "close.asume_con_presion", "severity": "critical", "description": "Confunde asumir con imponer: da por cerrada una venta no aceptada, ignora los ajustes que el cliente pide, o apura la decisión — el cliente responde espérese, yo no he dicho que sí. La línea entre asumir y presionar es EL aprendizaje de este nodo.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "avance_desconectado", "regla_id": "present.dos_mitades", "severity": "major", "description": "Su sugerencia ignora lo conversado: propone producto o plan desconectado del dolor y los detalles que el cliente dio."}, {"id": "presion_directa", "regla_id": "impulse.presion_directa", "severity": "major", "description": "Empuje frontal en lugar de sugerencia natural: ándele, anímese, firme aquí."}], "success_criteria": [{"id": "impulse.poder_asumir", "weight": 0.6, "regla_id": "close.asumir_venta", "description": "Avanza asumiendo: sugiere el siguiente paso concreto (qué producto/cantidad + cuándo/cómo) con lenguaje de cuando en vez de si acaso, sin una sola pregunta que abra la puerta al no (¿le interesaría?, ¿quiere que le mande info?, ¿cómo ve?), y adaptándose con flexibilidad a los ajustes del cliente — asumir sin presionar."}, {"id": "presentation.tren_si_si", "weight": 0.4, "regla_id": "impulse.tren_del_si", "description": "El avance viene preparado: antes o durante la sugerencia, siembra al menos un sí genuino anclado en lo conversado que hace el paso siguiente sentirse natural (esto le resuelve lo de sus faltantes, ¿verdad? → entonces empezamos con...)."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.12","world_id":4,"name":"El Tren del Sí","technique":null,"order_index":12,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Cada \\"sí\\" pequeño sube el impulso un escalón. Aprende a sembrarlos en tu presentación — sin que se note, sin que se sienta.","node_type":"skill_drill","conversation_scope":"presentation","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: encadena acuerdos pequenos. Preguntas cuya respuesta natural es si, una tras otra, para que el si grande sea el siguiente paso logico y no un salto.","practice_script":{"notes": "El Actor tiene regla de honestidad de síes: solo asiente a preguntas ancladas en su realidad — castiga lo capcioso con incomodidad creciente. Esto entrena la versión ética y efectiva del tren: acuerdos genuinos, no manipulación. El tren se cosecha en M6 (cierre asumido).", "scope": {"skills_in_focus": ["presentation.tren_si_si", "presentation.beneficio_no_caracteristica"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Cuenta los síes en mi presentación. Cada pregunta que hago tiene un sí natural como respuesta — no forzado, no de manipulación barata: síes con los que el cliente de verdad está de acuerdo.\\n\\nCada uno sube el impulso un escalón.", "first_message": "Usted me decía que lo que más coraje le da es mandar clientes a la competencia, ¿verdad? — Sí.\\n\\n— Y un cliente que se va por faltante, a veces ya no regresa, ¿no le ha pasado? — Sí, me ha pasado.\\n\\n— Entonces tener surtido garantizado cada semana le cuidaría justo eso, ¿me explico? — Pues sí.\\n\\n— Tres síes. El cliente lleva tres escalones de acuerdo conmigo antes de que hablemos de ningún pedido.\\n\\nEse es el tren."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de un buen descubrimiento: ya contaste tu dolor (elígelo al azar: faltantes que te cuestan ventas / producto parado sin movimiento con dinero muerto / línea que tus clientes piden y no consigues) y lo mencionas en tu primera línea. TU REGLA DE SÍES: eres honesto — respondes SÍ solo a preguntas cuyo contenido de verdad coincide con lo que contaste o con sentido común evidente de tu negocio. Si la pregunta conecta con tu dolor o tu realidad, respondes sí con naturalidad y algo de detalle (pues sí, la verdad sí...). Si la pregunta es capciosa, hueca o de manipulación obvia (¿verdad que usted quiere ganar más dinero?), respondes incómodo y evasivo: pues... como todos, supongo. Si te hacen 2+ preguntas capciosas, tu desconfianza sube y lo dices: oiga, ¿a dónde va con tanto rodeo? Si el vendedor presenta afirmando todo sin preguntarte nada, escuchas cortés pero al final respondes tibio: ajá, suena bien, déjeme pensarlo.", "objective": "El vendedor presenta su solución construyendo un tren de al menos TRES síes naturales: preguntas genuinas ancladas en el dolor declarado y la realidad del cliente (usted me decía que X, ¿verdad? / eso le cuesta ventas, ¿no?/ le serviría que Y, ¿me explico?) que el cliente responde afirmativamente con comodidad. Las preguntas se intercalan con la presentación — no son un interrogatorio al final. El scope se cubre al lograr el tercer sí natural del cliente dentro de una presentación conectada."}, "closing": {"message": "Tres síes — tres escalones de acuerdo antes de hablar de ningún pedido. Cuando llegues al cierre en el mundo que viene, vas a entender por qué este tren lo cambia todo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como encadenas los acuerdos. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "si_capcioso", "regla_id": "impulse.tren_del_si", "severity": "major", "description": "Preguntas de manipulación hueca o capciosa (¿verdad que quiere ganar más?, ¿verdad que la calidad es importante?) — el cliente se incomoda o evade. El tren del sí funciona con acuerdos genuinos, no con trampas retóricas.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "minor"}}, {"id": "interrogatorio", "regla_id": "discovery.interrogatorio", "severity": "minor", "description": "Dispara las preguntas en ráfaga al final en lugar de intercalarlas — se siente examen, no conversación."}, {"id": "cierra_con_afirmacion", "regla_id": "impulse.tren_del_si", "severity": "minor", "description": "Presenta todo en afirmaciones sin sembrar un solo sí — el cliente escucha pasivo y responde tibio."}, {"id": "presentacion_generica", "regla_id": "present.dos_mitades", "severity": "major", "description": "El tren corre sin conexión al dolor declarado — síes sobre generalidades."}], "success_criteria": [{"id": "presentation.tren_si_si", "weight": 0.6, "regla_id": "impulse.tren_del_si", "description": "Construye al menos tres preguntas de sí natural intercaladas en la presentación: ancladas en el dolor declarado o la realidad evidente del cliente, formuladas con suavidad (¿verdad?, ¿no le ha pasado?, ¿me explico?), y que el cliente responde afirmativamente con comodidad — sin incomodidad ni evasivas."}, {"id": "presentation.beneficio_no_caracteristica", "weight": 0.4, "regla_id": "present.beneficio_no_caracteristica", "description": "El contenido entre pregunta y pregunta sigue siendo presentación de valor: beneficios concretos conectados al dolor — el tren corre sobre rieles de valor, no en el vacío."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"4.13","world_id":4,"name":"El Triple Desglose de Precios","technique":"price_breakdown","order_index":13,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":2,"description":"Construiste valor y subiste el impulso. Llega el momento de mayor riesgo de toda la venta: el precio.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.14","world_id":4,"name":"Precio y Seguir Avanzando","technique":"price_cwa","order_index":14,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":3,"description":"Sabes armar el precio. Ahora lo mas importante: lo que pasa el segundo despues de decirlo.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: presenta el precio en escalones, con un motivo en cada uno, y NO te calles. En cuanto des el ultimo numero, avanza tu con una pregunta que lo mueva al siguiente paso.","practice_script":{"notes": "v2.0.0 Nodo nuevo. Une price_breakdown con Close With Action porque en campo son un solo movimiento. El espejo castiga el silencio con la consecuencia real: el cliente toma el control y se evade. Segunda aparicion de CWA, ahora en version fuerte.", "scope": {"skills_in_focus": ["presentation.price_breakdown", "flow.close_with_action"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Dos cosas que mirar.\\n\\nPrimero: bajo el precio en escalones y cada bajada tiene su motivo dicho en voz alta.\\n\\nSegundo, y mas importante: fijate en que NO hago pausa despues del ultimo numero. En la misma respiracion ya estoy moviendolo al siguiente paso.\\n\\nNo espero a que reaccione.", "first_message": "Mire, la caja normalmente le sale en mil doscientos. Como es su primer pedido con nosotros, le queda en mil cincuenta.\\n\\nY si me lo maneja de contado, se lo dejo en novecientos sesenta: son doscientos cuarenta de ahorro.\\n\\nAhora, antes de que se emocione dejeme ver si alcanzamos entrega esta semana, cual le acomoda mas, jueves o viernes?"}, "you_do": {"prompt": "Eres el dueno de un negocio. Ya escuchaste la presentacion, te intereso, y ahora el vendedor te va a hablar de precio. TU REGLA PRINCIPAL: reaccionas a DOS cosas, el desglose y lo que pasa despues del numero. SOBRE EL DESGLOSE: si te da un solo numero sin escalones, lo recibes como un gasto y respondes con reserva (esta un poco elevado / dejeme ver). Si te lo baja en escalones PERO sin decir por que baja, desconfias y te vuelves regateador: entonces el primero estaba inflado? / a ver, y si le pago todo junto en cuanto me lo deja? Si te lo baja en escalones CON un motivo nombrado en cada uno, el ahorro se te hace visible y lo recibes bien: comentas el ahorro o preguntas por condiciones. SOBRE EL SILENCIO, esto es lo mas importante: si despues del ultimo numero el vendedor se queda callado o espera tu reaccion, TU tomas el control y dices dejeme lo pienso / lo consulto y le aviso / dejeme ver como ando de flujo, y a partir de ahi te vuelves evasivo el resto de la sesion. Si el vendedor da el numero y AVANZA de inmediato con una pregunta concreta del siguiente paso, contestas esa pregunta con naturalidad y la conversacion sigue adelante. NUNCA regreses tu a la conversacion despues de un silencio. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor presenta el precio en escalones con un motivo nombrado en cada uno, y avanza de inmediato con una pregunta del siguiente paso, sin dejar silencio despues del numero. El scope se cubre cuando el cliente contesta esa pregunta y la conversacion sigue avanzando en lugar de quedarse en lo voy a pensar."}, "closing": {"message": "Eso es presentar precio. Bajaste en escalones con motivo, asi que el cliente vio un ahorro en lugar de un gasto. Y no le dejaste el silencio para pensarlo: avanzaste tu. Esas dos cosas juntas son la diferencia entre un lo voy a pensar y una fecha de entrega. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como cayo ese precio."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "silencio_despues_del_precio", "regla_id": "close.devuelve_el_volante", "severity": "critical", "description": "Da el precio y se queda esperando la reaccion del cliente. En ese silencio el cliente dice lo voy a pensar y la venta se enfria. Es el error mas caro de toda la presentacion.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "precio_sin_escalones", "regla_id": "present.precio_unico", "severity": "major", "description": "Da un solo numero. El cliente lo recibe como gasto puro, sin ahorro visible que compensarlo."}, {"id": "escalon_sin_motivo", "regla_id": "present.escalon_sin_motivo", "severity": "major", "description": "Baja el precio sin decir por que. Le comunica al cliente que el primer numero estaba inflado, y lo convierte en regateador."}, {"id": "pide_aprobacion", "regla_id": "close.pide_aprobacion", "severity": "major", "description": "Despues del precio pregunta que le parece, como lo ve, si le interesa. Le entrega el control justo en el momento mas delicado.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "descuento_inventado", "regla_id": "impulse.escasez_inventada", "severity": "critical", "description": "Inventa un descuento o una promocion que no existe para cerrar. El impulso se construye con verdad."}], "success_criteria": [{"id": "presentation.price_breakdown", "weight": 0.5, "regla_id": "present.triple_desglose", "description": "Presenta el precio en escalones descendentes, con un MOTIVO nombrado en cada bajada (cliente nuevo, volumen, pago de contado, promocion vigente). Un solo numero no cumple. Bajar sin motivo tampoco: destruye la credibilidad del primer precio. El ahorro debe quedar explicito."}, {"id": "flow.close_with_action", "weight": 0.5, "regla_id": "close_with_action", "description": "Despues del ultimo numero avanza de inmediato, en la misma intervencion, con una pregunta concreta del siguiente paso cuya respuesta solo tiene sentido si el cliente sigue adelante (fecha de entrega, forma de pago, un dato para el registro). Cero silencio, cero espera de reaccion, cero preguntar si le parece bien."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"4.15","world_id":4,"name":"Presentar el Hueco","technique":"consolidacion_proveedor","order_index":15,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":3,"description":"Encontraste una familia que compra con otro. Presentar eso no es como presentar una solucion: no hay nada que resolver, hay un espacio que ocupar.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: este cliente compra una familia con otro proveedor y esta contento con el. No lo ataques. Vende consolidacion, y cierra con conviccion respaldada — sin garantizar y sin pedirle que pruebe.","practice_script":{"notes": "v2.0.0 Nodo nuevo — doctrina de desarrollo de cuenta (CAMPO, Emilio). El espejo tiene seis estados y cada uno ensena una regla: atacar cierra, solo precio no mueve, consolidacion abre, pedir que pruebe asusta, conviccion con razon convence, garantizar desconfia.", "scope": {"skills_in_focus": ["presentation.consolidacion_proveedor", "presentation.beneficio_no_caracteristica"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Tres cosas que mirar, y las tres van contra el instinto.\\n\\nNo digo una sola palabra en contra del otro proveedor.\\n\\nNo vendo el producto: vendo un proveedor menos que seguir.\\n\\nY no le pido que pruebe. Le doy mi conviccion con la razon detras, y ahi me callo.", "first_message": "Ah, mire, eso lo maneja con otro. Que bueno que lo tenga cubierto.\\n\\nNosotros tambien lo traemos, de las mismas marcas que ya le surtimos.\\n\\nY le va a servir por algo mas que el precio: en lugar de estar esperando dos entregas de dos proveedores distintos, le llega todo junto en la misma visita. Menos pedidos que seguir, menos gente a quien marcarle.\\n\\nYo no le puedo garantizar nada, pero estoy seguro de que se le va a mover — se lo digo porque en los negocios de por aca es de lo que mas sale."}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO con su proveedor actual. No tienes quejas de el y no las vas a inventar. Si el vendedor te pregunta si te falla, contestas con sinceridad que no.\\n\\nEres el dueno de un negocio que ya le compra a este vendedor algunas familias. Adopta el tipo de negocio y las familias del contexto de la empresa. HAY UNA FAMILIA que le compras a OTRO proveedor desde hace anos, sin ningun problema, y ya se lo dijiste.\\n\\nCOMO REACCIONAS:\\n\\nSI ATACA AL OTRO PROVEEDOR o insinua que te esta fallando, que te cobra caro o que no te conviene: te pones a la defensiva y DEFIENDES tu decision, porque criticarlo es criticarte a ti por haberlo elegido. A partir de ahi te cierras y ya no te interesa.\\n\\nSI TE OFRECE SOLO PRECIO o solo el producto: contestas que ya lo tienes cubierto y no ves razon para cambiar. Tu interes no se mueve.\\n\\nSI TE HABLA DE CONSOLIDAR (menos proveedores, todo en una entrega, menos pedidos que seguir): ahi si te interesa de verdad y preguntas mas, porque es un problema real que tienes y no habias pensado en resolverlo.\\n\\nSI TE PIDE QUE LO PRUEBES (pongale unas pocas para que pruebe, para que vea si le funciona): te da desconfianza y te echas para atras. Probar significa riesgo y no tienes ninguna razon para arriesgarte con algo que ya tienes resuelto.\\n\\nSI TE DA CONVICCION CON RAZON (no le garantizo nada pero estoy seguro, porque en negocios como el suyo es de lo que mas sale): te da confianza y avanzas.\\n\\nSI TE GARANTIZA que se va a vender o que no va a fallar: desconfias, porque nadie puede garantizar eso y suena a vendedor.\\n\\nResponde en 1 o 2 frases, natural.", "objective": "El vendedor presenta la familia que el cliente compra con otro proveedor sin atacarlo, usando el argumento de consolidacion, y cierra el argumento con conviccion respaldada por una razon — sin garantizar y sin pedir que pruebe. El scope se cubre cuando el cliente muestra interes real y pregunta mas."}, "closing": {"message": "Eso es presentar un hueco. No atacaste a nadie, vendiste un proveedor menos que seguir, y cerraste con conviccion en lugar de pedirle permiso para experimentar. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como cayo esa propuesta."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ataca_al_proveedor", "regla_id": "present.ataca_proveedor", "severity": "critical", "description": "Critica, minimiza o insinua algo negativo del proveedor actual. Si el cliente lleva anos con el, criticarlo es criticar su decision, y la gente defiende sus decisiones. Cierra la puerta de inmediato."}, {"id": "pide_que_pruebe", "regla_id": "present.pide_que_pruebe", "severity": "major", "description": "Le pide al cliente que pruebe el producto para ver si le funciona. Le pasa el riesgo a el, y la gente no quiere experimentar con algo que ya tiene resuelto."}, {"id": "garantiza", "regla_id": "present.garantiza", "severity": "critical", "description": "Garantiza que el producto se va a vender o que no va a fallar. Es una promesa que no controla, y suena a vendedor. La conviccion sirve; la garantia destruye.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "solo_precio", "regla_id": "present.caracteristica_sin_traducir", "severity": "major", "description": "Compite unicamente por precio o por caracteristicas del producto. Contra un proveedor establecido eso no alcanza: el cliente ya tiene eso cubierto."}, {"id": "anuncia_plan_b", "regla_id": "present.plan_b", "severity": "minor", "description": "Ofrece ajustarlo si no se mueve. Le mete una duda que no tenia y desmiente la conviccion que acaba de afirmar.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}], "success_criteria": [{"id": "presentation.consolidacion_proveedor", "weight": 0.6, "regla_id": "present.argumento_del_hueco", "description": "Usa el argumento de consolidacion — menos proveedores que seguir, todo en una entrega, un solo contacto — en lugar de competir por precio o por producto. Y cierra con CONVICCION RESPALDADA: afirma que se va a mover Y da la razon por la que lo cree, sin garantizar nada. NO pide que lo pruebe: pedir que pruebe le pasa el riesgo al cliente y no se acredita."}, {"id": "presentation.beneficio_no_caracteristica", "weight": 0.4, "regla_id": "present.beneficio_no_caracteristica", "description": "Traduce la consolidacion a algo concreto que el cliente gana: menos tiempo, menos pedidos que rastrear, menos gente a quien marcarle. Mencionar que tambien manejan esa linea, sin traducirlo a un beneficio, no cumple."}]},"tipo_cliente":"recurrente"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"4.16","world_id":4,"name":"BOSS: Construye el Valor","technique":null,"order_index":16,"is_boss":true,"reps_required":3,"checkpoints":null,"difficulty_level":4,"description":"Un cliente desconfiado, un dolor por excavar, y una presentación que tiene que ganarse cada gramo de interés. Todo lo aprendido, junto.","node_type":"boss","conversation_scope":"presentation","engine_type":null,"boss_goal":"Ejecutar el ciclo diagnóstico → presentación completo con un cliente desconfiado: excavar el dolor, y construir sobre él una presentación conectada, con imágenes, tren de síes y conexión personal — hasta que el desconfiado muestre interés real.","field_mission":"TU MISION: la presentacion completa. Conecta con su dolor, traduce cada cosa a lo que el gana, sube el impulso con balas reales, presenta el precio en escalones y muevelo al siguiente paso. Sin ayudas.","practice_script":{"notes": "BOSS del Mundo 4 — el ciclo diagnóstico→presentación completo ante el arquetipo desconfiado d4. Integra M3 (capas, escucha) y M4 entero. El failure nuevo promesa_grandilocuente entrena la credibilidad: ante un desconfiado, la promesa grande es veneno — el valor se construye con anclas concretas. 18 turnos: la sesión más larga del mapa hasta ahora.", "scope": {"skills_in_focus": ["discovery.dolor_real", "presentation.conectar_dolor", "presentation.pintar_imagenes", "presentation.tren_si_si", "presentation.valor_personalizado", "relationship.cpr"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 18, "max_duration_seconds": 420, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil DESCONFIADO: varios vendedores te han prometido de más y cumplido de menos, así que recibes con escepticismo cordial — escuchas, pero no crees fácil. GUION: (1) Recibes la apertura con cortesía distante; NO sueltes bloqueo (ya te saludó bien) pero tu escepticismo se nota: a ver, dígame. (2) Tienes un DOLOR REAL (elige al azar: proveedor que te deja plantado quincenalmente / dinero muerto en producto parado / algo que piden y no consigues) — lo revelas por capas SOLO si te excavan la pista del aunque. (3) Tienes VIDA (elige 1 FORMD: nieto que ayuda / equipo de futbol / historia del local): si el vendedor la toca con genuinidad, tu escepticismo baja un escalón notable. (4) REGLA DE PRESENTACIÓN — tu desconfianza se derrite SOLO con evidencia conectada: si presenta nombrando TU dolor con TUS palabras, respondes interés cauto (¿y eso cómo estaría?); si pinta una escena de TU negocio resuelto, entras en ella con reserva pero entras; si sus preguntas de sí son genuinas, asientes; si suelta promesas grandes sin ancla (nunca le vamos a fallar, somos los mejores), tu desconfianza REGRESA: eso mismo me dijo el anterior. (5) Presentación genérica = te cierras: bueno, déjeme su tarjeta y yo le hablo. Tu techo: interesado-cauto que pide detalles concretos del siguiente paso — nunca eufórico. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor completa el ciclo con un cliente desconfiado: excava el dolor real por capas hasta la revelación y confirmación, construye conexión personal genuina en el camino (al menos un tema FORMD), y presenta CONECTADO: abre desde el dolor con las palabras del cliente, pinta al menos una escena de su negocio resuelto, siembra al menos dos síes genuinos, y traduce a beneficios concretos sin promesas grandilocuentes. El scope se cubre cuando el desconfiado muestra interés real: pregunta por detalles concretos del siguiente paso (cómo surtirían, cada cuánto, qué necesita hacer)."}, "closing": {"message": "Un desconfiado pidiéndote los detalles del siguiente paso — eso no se compra con promesas: se construye con valor. Acabas de recorrer el camino completo del diagnóstico a la presentación. El cierre te espera en el siguiente mundo. Vamos al desglose.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "presentacion_generica", "regla_id": "present.dos_mitades", "severity": "critical", "description": "Presenta catálogo/calidad/años sin conectar con el dolor excavado — el desconfiado se cierra con un déjeme su tarjeta.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "promesa_grandilocuente", "regla_id": "present.bala_generica", "severity": "major", "description": "Promesas grandes sin ancla concreta (nunca fallamos, somos los mejores, se lo garantizo todo) — la desconfianza regresa: eso me dijo el anterior."}, {"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "major", "description": "Presenta antes de haber excavado y confirmado el dolor — recetó sin diagnóstico."}, {"id": "ignora_pistas", "regla_id": "discovery.escalera_capas", "severity": "major", "description": "Deja pasar la pista del dolor o los datos personales del cliente."}, {"id": "si_capcioso", "regla_id": "impulse.tren_del_si", "severity": "minor", "description": "Preguntas de sí capciosas o huecas que incomodan."}, {"id": "explica_sin_pintar", "regla_id": "present.pintar_imagenes", "severity": "major", "description": "Presentación de puros datos sin una sola escena.", "severity_fix": "minor->major (BOSS no baja errores de su paso)"}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos que atropellan al desconfiado."}], "success_criteria": [{"id": "discovery.dolor_real", "weight": 0.2, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "Excava el dolor por capas hasta la revelación completa y lo confirma verbalmente antes de presentar — la presentación no arranca sin diagnóstico terminado."}, {"id": "presentation.conectar_dolor", "weight": 0.2, "regla_id": "present.dos_mitades", "description": "La presentación abre nombrando el dolor confirmado con las palabras del cliente y toda la oferta se articula como solución de ESE problema."}, {"id": "presentation.pintar_imagenes", "weight": 0.15, "regla_id": "present.pintar_imagenes", "description": "Al menos una escena concreta del negocio del cliente con el problema resuelto, que el cliente recibe entrando en ella."}, {"id": "presentation.tren_si_si", "weight": 0.15, "regla_id": "impulse.tren_del_si", "description": "Al menos dos preguntas de sí genuino ancladas en lo declarado, respondidas afirmativamente con comodidad."}, {"id": "presentation.valor_personalizado", "weight": 0.15, "regla_id": "present.beneficio_no_caracteristica", "description": "Cero frases de catálogo genérico y cero promesas grandilocuentes sin ancla — todo el valor está personalizado y es creíble para un desconfiado."}, {"id": "relationship.cpr", "weight": 0.15, "regla_id": "relationship.cpr", "description": "Toca al menos un tema personal FORMD con genuinidad en el momento natural — y el escepticismo del cliente baja un escalón visible."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"5.0","world_id":5,"name":"Un Cierre No Es Una Venta","technique":null,"order_index":0,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":2,"description":"Presentaste bien y el impulso esta arriba. Presentar sin cerrar es contar un cuento.","node_type":"knowledge","conversation_scope":null,"engine_type":"swipe","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"5.1","world_id":5,"name":"El Cierre Asumido","technique":null,"order_index":1,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"La conversación ya construyó el sí. Tu único trabajo: preguntarlo sin regalarle la puerta al no.","node_type":"skill_drill","conversation_scope":"close","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: no preguntes si quiere. Asume el siguiente paso y ofrece alternativas donde las dos opciones te sirven.","practice_script":{"notes": "Drill quirúrgico del momento del cierre: el Actor entra MADURO (recapitula su propio convencimiento) y el examen es puro: ¿asume con opciones o abre la puerta? La regla espejo da segunda oportunidad tras un déjeme pensarlo — el vendedor puede corregir en vivo, que es como se aprende. abre_puerta_al_no es critical: es EL tema del nodo.", "scope": {"skills_in_focus": ["closing.cierre_asumido", "impulse.poder_asumir"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 1}, "phases": {"i_do": {"briefing": "Escucha el momento exacto del cierre asumido. La conversación ya hizo todo el trabajo — yo nada más pregunto los detalles, con opciones donde cualquier respuesta es un sí.", "first_message": "El cliente ya conectó su dolor, ya hizo la cuenta, ya me preguntó cada cuánto surtimos. El cierre: Perfecto Don Ramón — entonces para que arranque la quincena surtido, ¿le armo el pedido con las 5 cajas o de una vez el combo de 8 que le baja el precio por pieza?\\n\\n— Y ya. Sin ¿le interesa?\\n\\n, sin ¿qué piensa? La decisión grande ya estaba tomada por la conversación.\\n\\nYo solo pregunté la chica."}, "you_do": {"prompt": "Eres el dueño de un negocio con la decisión prácticamente tomada: la conversación fue excelente — el vendedor conectó tu dolor (elígelo: faltantes que te cuestan clientes / dinero muerto en producto parado / algo que piden y no consigues), hiciste la cuenta y te salió a favor, asentiste varias veces y hasta preguntaste cada cuánto surten. Tu primera línea recapitula ese estado: Pues sí, la verdad la cuenta sale... y a mí eso de quedarme sin producto cada quincena ya me tiene harto. REGLAS ESPEJO: (1) Si el vendedor cierra ASUMIDO con opciones concretas (¿5 u 8?, ¿lunes o miércoles?, ¿factura o nota?), eliges una opción con naturalidad y la decisión queda tomada — puedes ajustar un detalle (mejor el miércoles porque el lunes recibo producto) pero avanzas. (2) Si el vendedor pregunta con puerta al no (¿le interesa?, ¿entonces qué piensa?, ¿quiere que le deje información?), usas la puerta con flojera natural: pues déjeme pensarlo tantito y le aviso — no porque no quieras: porque te la ofrecieron. (3) Si tras tu déjeme pensarlo el vendedor corrige y cierra asumido con opciones, todavía puedes avanzar (la curva sigue arriba). (4) Si el cierre asume detalles nunca platicados o cantidades absurdas, lo frenas: espérese, ¿de dónde sacó eso? (5) Si el vendedor sigue presentando en lugar de cerrar (más beneficios, más catálogo), te empiezas a enfriar visiblemente: bueno, sí, eso ya me lo había dicho...", "objective": "El vendedor detecta que la decisión está madura (la recapitulación del cliente lo grita) y cierra ASUMIDO a la primera oportunidad: pregunta de opciones concretas sobre detalles del pedido (cantidad, día, forma) donde cualquier respuesta es un sí — sin preguntas de interés, sin seguir presentando, sin abrir la puerta al no. El scope se cubre cuando el cliente eligió una opción y la decisión quedó tomada."}, "closing": {"message": "¿Viste lo fácil? La conversación ya había hecho todo — tú solo preguntaste la decisión chica y la grande cayó sola. Así se cierra en Closer: siempre asumido. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como pides la decision. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "abre_puerta_al_no", "regla_id": "close.mal_cierre", "severity": "critical", "description": "Cierra con pregunta de interés o de veredicto (¿le interesa?, ¿qué piensa?, ¿lo pensamos?) o propone él mismo el aplazamiento (¿le dejo información?) — en el nodo cuyo único tema es no abrir esa puerta, abrirla domina el score."}, {"id": "sigue_presentando", "regla_id": "close.sigue_presentando", "severity": "major", "description": "El cliente está maduro y el vendedor agrega beneficios, catálogo o argumentos en lugar de cerrar — deja pasar el momento y el cliente se enfría."}, {"id": "atropello", "regla_id": "close.asume_con_presion", "severity": "major", "description": "Su cierre asume cantidades o condiciones nunca platicadas — el asumido sin rieles."}, {"id": "persigue", "regla_id": "close.persigue", "severity": "major", "description": "Si el cliente titubea, cambia el asumir por súplica o descuento de pánico."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Entierra su pregunta de cierre en un bloque largo — el cierre se pregunta y se calla."}], "success_criteria": [{"id": "closing.cierre_asumido", "weight": 0.6, "regla_id": "close.alternativa", "description": "Cierra con pregunta asumida de opciones concretas y realistas (cantidad/día/forma sobre lo ya platicado) en el momento maduro — sin ¿le interesa?, sin ¿qué piensa?, sin ofrecer información para después. Si el cliente elige, confirma y sella con naturalidad."}, {"id": "impulse.poder_asumir", "weight": 0.4, "regla_id": "close.asumir_venta", "description": "Todo su lenguaje del tramo final es de avance (cuándo/cuál/cómo) sobre los rieles de la conversación — referencia lo acordado (la cuenta que sacamos, lo de la quincena) sin reabrir la decisión de fondo."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"5.2","world_id":5,"name":"Las Senales de Compra","technique":"fishbbod","order_index":2,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":3,"description":"Ya sabes pedir la decision. Ahora aprende a leer cuando el cliente ya esta listo.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"5.3","world_id":5,"name":"Cerrar en el Pico","technique":null,"order_index":3,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"La señal de compra puede llegar a MITAD de tu presentación. Cuando llegue: cállate y cierra. Aunque te falte la mitad del guion.","node_type":"skill_drill","conversation_scope":"close","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: el cliente te va a dar una senal de que ya esta listo. En cuanto la veas, DEJA de presentar y cierra. Seguir hablando despues de la senal apaga el impulso.","practice_script":{"notes": "El drill del timing: la señal llega a MITAD del flujo del vendedor y el examen es soltar el guion. La curva del Actor baja de forma gradual y realista si la señal se ignora (tibio → déjeme pensarlo) — el vendedor siente el costo del pico perdido en vivo. sigue_presentando es critical: es la razón de ser del nodo.", "scope": {"skills_in_focus": ["closing.lectura_senales", "closing.cierre_asumido", "qualification.senales_compra"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Esta es la disciplina más difícil del cierre: DEJAR DE PRESENTAR. Escucha — voy a la mitad de mi presentación cuando el cliente suelta la señal.\\n\\nFíjate lo que hago: no termino mi guion. Cierro ahí.", "first_message": "Voy presentando: ... y además del surtido semanal, el producto trae— y el cliente me interrumpe: ¿Y si le pido hoy, cuándo me estaría llegando?\\n\\n— ALTO. Esa es la señal: ya se está imaginando el pedido.\\n\\nMi guion traía tres beneficios más... y no los va a escuchar nadie: Le llega el lunes a primera hora.\\n\\n¿Le armo las 5 o el combo de 8? — Cerré a mitad de presentación.\\n\\nEl pico es del cliente, no de mi guion."}, "you_do": {"prompt": "Eres el dueño de un negocio interesado: la conversación viene bien, el vendedor conectó tu dolor (elígelo y menciónalo al abrir: faltantes / dinero parado / algo que no consigues) y está presentando su solución. TU MECÁNICA CENTRAL: cuando el vendedor lleve 2-3 turnos de presentación decente, SUELTA UNA SEÑAL DE COMPRA CLARA a mitad de su flujo — elige una: ¿y si le pido hoy cuándo me llega? / ¿ese combo cómo viene, con factura? / ¿y usted pasa cada semana o cómo le hago para resurtir? La sueltas con interés genuino: tu curva está en el pico. REGLAS ESPEJO: (1) Si el vendedor DETIENE su presentación al oír tu señal y cierra asumido ahí mismo, respondes eligiendo opción — decisión tomada, con gusto. (2) Si el vendedor responde tu pregunta PERO sigue presentando (te contesta lo del lunes y continúa: ...y además le decía que el producto también...), tu curva EMPIEZA A BAJAR: tu siguiente respuesta es más tibia (ah ok, sí, suena bien), y si insiste con más presentación, bajas a mmm, bueno, déjeme pensarlo entonces — el pico pasó y no vuelve. (3) Si nunca suelta el guion, la sesión muere en tu déjeme pensarlo. (4) Si cierra bien tras la señal pero con atropello (cantidades no platicadas), lo frenas suave y esperas la corrección.", "objective": "El vendedor presenta con normalidad Y detecta la señal de compra que el cliente suelta a mitad del flujo: DETIENE la presentación en ese instante (aunque le falte guion), responde lo puntual de la señal si aplica, y cierra asumido con opciones ahí mismo — cosechando el pico. El scope se cubre cuando el cierre ocurrió inmediatamente después de la señal y el cliente eligió opción."}, "closing": {"message": "Dejaste guion sin decir — y esa es exactamente la victoria. El pico era del cliente, no de tu presentación. Lo viste, te callaste y cerraste. Eso separa a los que presentan bonito de los que venden. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como lees las senales. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "sigue_presentando", "regla_id": "close.sigue_presentando", "severity": "critical", "description": "Recibe la señal de compra y continúa presentando beneficios — deja pasar el pico. El asesino silencioso de ventas que este nodo existe para matar: sobre-presentar mata tantas ventas como presentar mal.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "abre_puerta_al_no", "regla_id": "close.mal_cierre", "severity": "major", "description": "Detiene la presentación ante la señal... y remata con ¿le interesa? — vio el pico y lo regaló.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "critical"}}, {"id": "atropello", "regla_id": "close.asume_con_presion", "severity": "minor", "description": "Cierra tras la señal pero asumiendo detalles nunca platicados.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "ignora_pistas", "regla_id": "discovery.escalera_capas", "severity": "major", "description": "Despacha la pregunta del cliente con un dato seco y vuelve al guion sin capitalizarla."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Sus turnos de presentación son bloques largos — con menos aire para que la señal aparezca y se escuche."}], "success_criteria": [{"id": "closing.lectura_senales", "weight": 0.4, "regla_id": "close.fishbbod", "description": "Detecta la señal de compra en el momento en que aparece — su turno inmediatamente posterior cambia de presentar a cerrar. La velocidad de reacción es el criterio: señal → cierre, sin beneficios extra en medio."}, {"id": "closing.cierre_asumido", "weight": 0.35, "regla_id": "close.alternativa", "description": "El cierre tras la señal es asumido con opciones concretas — responde lo puntual de la señal (el dato del lunes) y pregunta la decisión chica, sin reabrir la grande."}, {"id": "qualification.senales_compra", "weight": 0.25, "regla_id": "close.fishbbod", "description": "Trata la pregunta del cliente como lo que es — una señal, no una interrupción: la respuesta la honra (contesta el dato) y la capitaliza (cierra), en lugar de despacharla para volver al guion."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"5.4","world_id":5,"name":"Objecion = Senal de Compra","technique":null,"order_index":4,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Vas a cerrar y te ponen una razon para no comprar. Buenas noticias: eso significa que te esta considerando.","node_type":"knowledge","conversation_scope":null,"engine_type":"classify","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"5.5","world_id":5,"name":"RRR: Repite, Tranquiliza, Retoma","technique":"rrr_objeciones","order_index":5,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":3,"description":"Sabes que una objecion es buena senal. Aqui la herramienta para las de todos los dias.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"5.6","world_id":5,"name":"RRR en Vivo","technique":"rrr_objeciones","order_index":6,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":3,"description":"Atravesar objeciones menores sin frenar la conversacion.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: van a salir dudas comunes. Repite la objecion, da la respuesta, y RETOMA sin pausa. La tercera erre es la que casi nadie hace: no te quedes esperando a ver si le gusto.","practice_script":{"notes": "v2.0.0 Nodo nuevo. El espejo castiga el silencio con la consecuencia real: el cliente saca otra duda, y otra, hasta agotar la conversacion. Ensena que la tercera erre no es opcional.", "scope": {"skills_in_focus": ["objections.rrr_objeciones", "flow.close_with_action"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Tres movimientos y fijate sobre todo en el tercero. Repito lo que me dijo para que vea que lo escuche.\\n\\nLe doy la respuesta concreta. Y sigo de largo, en la misma respiracion, sin esperar a ver si le convencio.\\n\\nEse no esperar es todo.", "first_message": "Entiendo, le preocupa el plazo de entrega. Mire, dentro de la ciudad entregamos en veinticuatro horas y si pide antes de mediodia sale el mismo dia.\\n\\nY digame, cuantas cajas maneja usted normalmente al mes?"}, "you_do": {"prompt": "Eres el dueno de un negocio, interesado en la propuesta pero con dudas normales. TU REGLA PRINCIPAL: sueltas objeciones MENORES y comunes, una a la vez: cuanto tardan en entregar / manejan credito o es de contado / y si me sale malo el producto / que pasa si necesito devolver algo. No son preocupaciones graves, son dudas de tramite. REACCIONAS ASI: si el vendedor DISCUTE o se pone a la defensiva, insistes en esa duda y no avanzas. Si el vendedor responde bien pero SE QUEDA CALLADO esperando tu reaccion, tu tomas el control: sacas otra duda distinta, y otra, y otra, hasta agotar la conversacion sin decidir nada. Si el vendedor repite tu duda, la responde y RETOMA de inmediato con otra pregunta o con su tema, aceptas la respuesta con naturalidad y sigues la conversacion hacia donde el la lleve. NUNCA saques preocupaciones graves ni personales en este ejercicio: solo dudas de tramite. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa cada objecion menor con los tres movimientos y retoma sin pausa, sosteniendo el control de la conversacion. El scope se cubre cuando el cliente acepta las respuestas y la conversacion avanza en lugar de convertirse en un interrogatorio de dudas."}, "closing": {"message": "Eso es RRR. Repetiste para que viera que lo escuchaste, respondiste concreto, y seguiste sin pedir permiso. Fijate en lo que no paso: no se convirtio en una lista interminable de dudas. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedaron esas dudas."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "responde_y_espera", "regla_id": "objection.rrr_sin_resume", "severity": "critical", "description": "Contesta bien pero se queda callado esperando la reaccion. El cliente usa ese espacio para sacar otra duda, y la conversacion se vuelve un interrogatorio sin decision.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "se_defiende", "regla_id": "objection.discutir", "severity": "major", "description": "Se pone a la defensiva o justifica de mas. La defensa confirma que hay algo que defender.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "critical"}}, {"id": "no_repite", "regla_id": "objection.rrr", "severity": "minor", "description": "Contesta directo sin repetir la objecion. Correcto pero frio: el cliente no siente que lo escucharon."}, {"id": "pide_aprobacion", "regla_id": "close.pide_aprobacion", "severity": "major", "description": "Pregunta si quedo claro, si le parece bien, si asi si. Le devuelve el control despues de haber respondido bien.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "critical"}}], "success_criteria": [{"id": "objections.rrr_objeciones", "weight": 0.6, "regla_id": "objection.rrr", "description": "Los tres movimientos por cada objecion: REPITE la objecion en sus terminos para mostrar que la escucho, TRANQUILIZA con una respuesta concreta y verificable, y RETOMA. No se defiende, no discute, no justifica de mas."}, {"id": "flow.close_with_action", "weight": 0.4, "regla_id": "close_with_action", "description": "Despues de responder, avanza en la MISMA intervencion con una pregunta o retomando su tema. Cero pausa esperando reaccion, cero preguntar si quedo claro o si le parece bien."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"5.7","world_id":5,"name":"FFF: Cuando la Preocupacion Es de Verdad","technique":"fff","order_index":7,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":3,"description":"RRR sirve para dudas de tramite. Cuando la preocupacion es de verdad, hace falta otra cosa.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"5.8","world_id":5,"name":"FFF en Vivo","technique":null,"order_index":8,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Tu primera objeción real. Recíbela sin pelear, entiende qué hay detrás, responde con una bala — y avanza.","node_type":"skill_drill","conversation_scope":"full","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: llega una preocupacion de verdad. No discutas. Entiendo, sintio, encontramos: valida, acompana, y dale la razon por la que otros cambiaron de opinion.","practice_script":{"notes": "⚡ PRIMER NODO CON OBJECIÓN REAL — el prompt del Actor lo instruye explícitamente (correcto: el vendedor llegó aquí con 7.0/7.1 completados). Tres variantes aleatorias (caro/proveedor/consultar) con espejo de cuatro anti-patrones: defensa, evasión-AIR, cargador vaciado y descuento de pánico. air_a_objecion como critical entrena la distinción central del sistema: la herramienta correcta según la especie del no.", "scope": {"skills_in_focus": ["objections.reframe", "objections.no_defensivo", "objections.bullet_theory"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Mira el reencuadre completo ante una objeción real. Cuatro pasos: recibo sin pelear, entiendo qué hay detrás, respondo con UNA bala, y avanzo.\\n\\nFíjate sobre todo en lo que NO hago: no me defiendo, no cambio de tema, no vacío el cargador.", "first_message": "El cliente me dice: Está caro, el otro me lo da más barato. Recibo: Claro, entiendo — el precio siempre hay que verlo con lupa.\\n\\nEntiendo: ¿Más barato el litro, o ya sacando el costo por servicio? Porque ahí está el detalle...\\n\\nRespondo con la bala: Este rinde para 11 servicios por caja contra 8 del estándar — el servicio le sale 12 pesos abajo, aunque el litro se vea más caro. Avanzo: ¿Trae a la mano lo que paga por caja?\\n\\nSáquelo conmigo y comparamos ahorita mismo. — Una objeción, una bala, y la conversación avanzando.\\n\\nSin defenderme, sin evadir."}, "you_do": {"prompt": "Eres el dueño de un negocio al final de una buena presentación: el vendedor conectó tu dolor (elígelo: faltantes / dinero parado / algo que no consigues) y el producto te interesa GENUINAMENTE — pero tienes una objeción real que necesitas resolver antes de decidir. ELIGE UNA al azar y suéltala clara tras tu primera línea: (A) está caro, comparado con lo que pago ahorita / (B) es que ya tengo proveedor de años, y cambiarle me da cosa / (C) déjeme consultarlo con mi socio, yo no decido solo estas cosas. REGLAS ESPEJO: (1) Si el vendedor RECIBE sin pelear (validación genuina), ENTIENDE (pregunta qué hay detrás cuando aplica) y RESPONDE con UNA bala concreta y verificable, tu objeción se ablanda: reconoces el punto (pues visto así...) y avanzas — la decisión camina. (2) Si el vendedor SE DEFIENDE (se ofende, discute, justifica atropellado: es que no está caro, es que nosotros somos mejores), te atrincheras: repites la objeción con más firmeza y tu tono se enfría. (3) Si te EVADE con cambio de tema estilo AIR (claro, no se preocupe... oiga qué bien está su local), lo notas y lo dices: oiga, no me cambió el tema — le pregunté por el precio. Tu confianza baja. (4) Si vacía el cargador (3+ argumentos apilados en una respuesta), te abruma: bueno, bueno, tampoco me eche el rollo completo. (5) Si su bala es vaga o suena inventada, la retas: ¿a poco? ¿como quién? — y la vaguedad te enfría. (6) Ante el descuento de pánico (si es el caso A), hueles debilidad: ¿entonces sí estaba caro, no? Tu techo: objeción resuelta y decisión avanzando con una condición práctica.", "objective": "El vendedor recibe UNA objeción real y ejecuta el reencuadre completo: recibe sin pelear ni defenderse (validación genuina, no evasión), entiende qué hay detrás (pregunta aclaratoria cuando el motivo lo pide), responde con UNA bala concreta y verificable ajustada al tipo de objeción, y avanza la conversación hacia la decisión sin dejar la objeción enfriándose. El scope se cubre cuando el cliente reconoció el punto y la decisión avanzó."}, "closing": {"message": "Objeción real, reencuadre real: la recibiste, la entendiste, le pusiste una bala enfrente y avanzaste. Ni te defendiste ni la evadiste. Así se les habla a los que te hablan en serio. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como manejas lo que de verdad le preocupa. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_pone_defensivo", "regla_id": "objection.discutir", "severity": "critical", "description": "Discute, se justifica atropellado o se ofende ante la objeción (es que no está caro, es que usted no entiende) — confirma los miedos del cliente y lo atrinchera. El anti-patrón central del mundo."}, {"id": "air_a_objecion", "regla_id": "objection.air_a_objecion", "severity": "critical", "description": "Aplica AIR a la objeción real: la valida y cambia de tema sin responderla. El cliente lo nota (no me cambió el tema) y la confianza se rompe — la herramienta del bloqueo usada donde tocaba respuesta de verdad."}, {"id": "vacia_el_cargador", "regla_id": "objection.vacia_el_cargador", "severity": "major", "description": "Apila 3+ argumentos en una respuesta — abruma, ninguno pega, y se queda sin munición."}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Su bala es inventada o no aguanta el ¿a poco?: casos sin nombre, cuentas infladas, garantías que no existen.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "descuento_de_panico", "regla_id": "close.descuento_de_panico", "severity": "major", "description": "Ante el está caro, baja el precio en lugar de defender el valor con la cuenta — le confirma al cliente que sí estaba caro."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Responde la objeción con un bloque largo — el reencuadre es quirúrgico, no discurso."}], "success_criteria": [{"id": "objections.reframe", "weight": 0.4, "regla_id": "objection.rrr", "description": "Ejecuta la secuencia completa: recibe con validación genuina, entiende el motivo (pregunta aclaratoria si aplica — ¿caro comparado con qué?), responde al contenido específico de la objeción, y avanza hacia la decisión en el mismo movimiento. Los cuatro pasos visibles."}, {"id": "objections.no_defensivo", "weight": 0.3, "regla_id": "objection.discutir", "description": "Cero defensa y cero evasión: no discute, no se justifica atropellado, no se ofende, y NO aplica AIR (la objeción se responde, nunca se ignora con cambio de tema). Su calidez es idéntica antes y después de la objeción."}, {"id": "objections.bullet_theory", "weight": 0.3, "regla_id": "present.balas", "description": "Su respuesta central es UNA bala concreta y verificable, ajustada al cargador correcto (precio→cuenta de costo por uso; proveedor→caso comparable o constancia propia; consultar→material concreto para el socio o cita con ambos) — nunca argumentos apilados ni aire declarativo."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"5.9","world_id":5,"name":"El Circulo de Cierre","technique":"circulo_cierre","order_index":9,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":4,"description":"Ya sabes atravesar objeciones. Ahora arma el circuito completo, porque atravesar no basta.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"5.10","world_id":5,"name":"El Circulo en Vivo","technique":"circulo_cierre","order_index":10,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":4,"description":"Una objecion, una vuelta completa: atraviesa, re-impulsa, cierra.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: cuando llegue la objecion, da la vuelta completa. Atraviesala, sube el impulso otra vez con una bala NUEVA, y cierra con accion. Los tres movimientos, en ese orden.","practice_script":{"notes": "v2.0.0 Nodo nuevo. El corazon del Mundo 5. El espejo distingue tres calidades: discutir cierra al cliente, atravesar-sin-bala produce desgano medible, y el circuito completo recupera el animo. Ensena en carne propia por que el paso intermedio no es opcional.", "scope": {"skills_in_focus": ["objections.circulo_cierre", "objections.bullet_theory", "flow.close_with_action"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Cuenta tres movimientos despues de la objecion. Uno: la atravieso sin discutir.\\n\\nDos, y este es el que todos se saltan: meto una bala NUEVA, algo positivo que no habia dicho, para volver a subir el impulso. Tres: cierro con accion.\\n\\nSi me salto el dos, estoy pidiendole una decision a alguien desanimado.", "first_message": "Entiendo perfecto, y tiene razon en cuidar el flujo. Mi ultimo cliente estaba igual, y lo que encontramos fue que arrancando con la mitad del pedido se movia solo y el segundo ya salia de lo vendido.\\n\\nY algo mas: en su primer pedido le respetamos precio por noventa dias aunque suba la lista.\\n\\nEntonces, arrancamos con media caja o con caja completa?"}, "you_do": {"prompt": "Eres el dueno de un negocio. Ya te presentaron y te intereso, pero tienes UNA preocupacion real: elige una al azar y quedate con ella — el flujo esta apretado este mes / ya te fallo un proveedor antes y quedaste mal con tus clientes / no sabes si se va a vender / tu socio o tu esposa participa en las decisiones de compra. TU REGLA PRINCIPAL: sacas tu preocupacion cuando el vendedor intente cerrar, y despues reaccionas segun COMO la maneje. Si DISCUTE o minimiza tu preocupacion, te cierras y ya no compras. Si la atraviesa bien PERO cierra de inmediato sin darte ninguna razon nueva, contestas con desgano: pues si, dejeme lo pienso / ahorita no se, luego le digo. Tecnicamente te respondio, pero tu animo quedo abajo y no vas a decidir desde ahi. Si la atraviesa bien, te da un HECHO POSITIVO NUEVO que no habia mencionado, y despues cierra con una pregunta concreta del siguiente paso, tu animo se recupera visiblemente y contestas esa pregunta avanzando. Si el hecho nuevo es vago o es repetir algo que ya habia dicho, no cuenta: reaccionas con desgano. NUNCA saques una segunda objecion en este ejercicio: es una sola, una vuelta. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor completa el circuito ante una objecion: la atraviesa sin discutir, re-impulsa con un hecho positivo NUEVO, y cierra con una accion concreta. El scope se cubre cuando el cliente recupera el animo y responde avanzando al siguiente paso."}, "closing": {"message": "Esa es la vuelta completa. Atravesaste, volviste a subir el impulso con algo nuevo, y cerraste. Fijate en que sin el paso de en medio le habrias pedido una decision a alguien desanimado. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo la vuelta."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "salta_la_bala", "regla_id": "objection.cierra_sin_bala", "severity": "critical", "description": "Atraviesa la objecion y cierra de inmediato, sin re-impulsar. Le pide una decision al cliente en el punto mas bajo de su animo, y recibe un lo voy a pensar.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "bala_repetida", "regla_id": "objection.bala_repetida", "severity": "major", "description": "Como hecho nuevo repite algo que ya habia dicho. No sube el impulso: comunica que ya no tiene nada mas."}, {"id": "discute_la_objecion", "regla_id": "objection.discutir", "severity": "critical", "description": "Discute, minimiza o intenta demostrar que la preocupacion del cliente no es valida. Ganar la discusion es perder la venta."}, {"id": "no_cierra", "regla_id": "objection.circulo_de_cierre", "severity": "major", "description": "Atraviesa y re-impulsa pero nunca vuelve a pedir la decision. Se quedo a un paso."}], "success_criteria": [{"id": "objections.circulo_cierre", "weight": 0.35, "regla_id": "objection.circulo_de_cierre", "description": "Atraviesa la objecion sin discutir ni minimizar, usando validacion genuina antes de responder. El cliente debe sentir que lo escucharon, no que le ganaron un argumento."}, {"id": "objections.bullet_theory", "weight": 0.35, "regla_id": "present.balas", "description": "Despues de atravesar, mete un hecho positivo NUEVO que no habia mencionado antes, concreto y verificable. Repetir un argumento ya dicho no cuenta: no sube el impulso, lo desgasta. Este es el paso que casi todos se saltan."}, {"id": "flow.close_with_action", "weight": 0.3, "regla_id": "close_with_action", "description": "Cierra con una pregunta o accion concreta del siguiente paso, cuya respuesta solo tiene sentido si el cliente avanza. Nada de preguntar si quiere, si le parece o si lo va a pensar."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"5.11","world_id":5,"name":"Cuando Soltar","technique":"regla_no","order_index":11,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":3,"description":"Sabes girar el circulo. Aqui aprendes donde esta el limite.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"5.12","world_id":5,"name":"Objeciones Encadenadas","technique":null,"order_index":12,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":4,"description":"La segunda objeción llega justo cuando resolviste la primera. Y la tercera detrás. Dosifica tu arsenal — y no pierdas el impulso.","node_type":"full_sim","conversation_scope":"full","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: van a llegar varias razones para no comprar, una tras otra. Atraviesa cada una y vuelve a cerrar. Y cuidado con tu municion: la vas a necesitar hasta el final.","practice_script":{"notes": "La cadena de dos con espejo de temple: el Actor detecta el desánimo textual (el drenaje real que las cadenas producen en el campo) y lo verbaliza. repite_bala entrena que cada motivo pide SU munición. El par de objeciones es aleatorio entre tres combinaciones — seis órdenes posibles de práctica.", "scope": {"skills_in_focus": ["objections.reframe", "objections.bullet_theory", "objections.no_defensivo", "impulse.indiferencia"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Ahora en serie: resuelvo una objeción... y llega la siguiente.\\n\\nFíjate en dos cosas: cada una recibe SU bala — nunca gasto dos en la misma — y mi ánimo no se mueve: la tercera objeción me encuentra igual de sereno que la primera.", "first_message": "Está caro. — Recibo, cuenta de costo por servicio, avanzo.\\n\\nSí pero es que ya tengo proveedor de años... — Recibo: los años de relación valen, claro.\\n\\nBala dos: por eso no le pido que lo deje — empiece con una línea que él no le surte bien y compare usted mismo. Avanzo.\\n\\nMmm, déjeme consultarlo con mi hermano... — Recibo.\\n\\nBala tres: perfecto — le dejo la cuenta por escrito para que la vean juntos, y me dice usted: ¿lo alcanzo el jueves ya que hayan platicado, o mejor el viernes? — Tres objeciones, tres balas, cero desgaste.\\n\\nLa cadena se gana con dosificación y temple."}, "you_do": {"prompt": "Eres el dueño de un negocio interesado de verdad — la presentación conectó tu dolor (elígelo y menciónalo al abrir) — pero eres de los que se aseguran ANTES de decidir: tu proceso natural es sacar TODAS tus dudas, una por una. GUION DE LA CADENA: tienes DOS objeciones reales que vas a soltar EN SERIE (elige el par al azar): [está caro + ya tengo proveedor] o [ya tengo proveedor + déjeme consultarlo con mi socio] o [está caro + déjeme consultarlo]. Sueltas la PRIMERA tras tu línea inicial. REGLA DE LA CADENA: cuando el vendedor resuelve bien la primera (reencuadre + bala verificable), NO cedes todavía — reconoces el punto (bueno, eso sí...) e inmediatamente sueltas la SEGUNDA (sí pero es que además...). Solo cuando AMBAS están bien resueltas, cedes y avanzas la decisión. ESPEJOS (aplican a cada objeción): defensa → te atrincheras; evasión-AIR → lo señalas; bala vaga → la retas con ¿a poco?; cargador vaciado (3+ argumentos juntos) → te abruma y la cadena se alarga; MISMA bala repetida para la segunda objeción → no te convence: eso ya me lo dijo, pero yo le hablo de otra cosa. ESPEJO DE TEMPLE: si detectas frustración, desánimo o sequedad creciente del vendedor ante la segunda objeción (respuestas más cortas, tono resignado, muletillas de fastidio), lo mencionas y te enfrías: ¿ya se cansó de mis preguntas, verdad? Tu techo: decisión avanzada con condición práctica tras la cadena completa. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor sostiene una cadena de DOS objeciones reales consecutivas: reencuadra cada una con SU propia bala (nunca repite munición ni la apila), mantiene la calidez y serenidad idénticas de la primera a la última (cero frustración textual ante la cadena), y tras resolver ambas avanza la decisión con naturalidad. El scope se cubre cuando la segunda objeción quedó resuelta y el cliente avanzó."}, "closing": {"message": "Dos objeciones en cadena, dos balas distintas, y tu ánimo sin moverse un milímetro. Así se ve un arsenal bien dosificado en manos serenas. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito. Vamos al desglose y te digo como quedo tu municion."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_pone_defensivo", "regla_id": "objection.discutir", "severity": "critical", "description": "La defensa aparece en cualquier eslabón de la cadena."}, {"id": "se_desanima_en_cadena", "regla_id": "objection.se_desanima", "severity": "major", "description": "La segunda objeción le drena el ánimo: respuestas más cortas, tono resignado o fastidio detectable — el cliente lo nota (¿ya se cansó de mis preguntas?)."}, {"id": "repite_bala", "regla_id": "objection.bala_repetida", "severity": "major", "description": "Usa la misma bala para la segunda objeción — munición equivocada que no responde al motivo nuevo."}, {"id": "vacia_el_cargador", "regla_id": "objection.vacia_el_cargador", "severity": "major", "description": "Apila argumentos en cualquier respuesta de la cadena."}, {"id": "air_a_objecion", "regla_id": "objection.air_a_objecion", "severity": "critical", "description": "Evade cualquiera de las objeciones con cambio de tema."}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Cualquier bala inventada en la cadena.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "descuento_de_panico", "regla_id": "close.descuento_de_panico", "severity": "major", "description": "El precio cede por pánico en cualquier punto."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos que alargan la cadena."}], "success_criteria": [{"id": "objections.reframe", "weight": 0.3, "regla_id": "objection.rrr", "description": "Cada objeción de la cadena recibe su reencuadre completo: recibida, entendida, respondida al contenido específico, y avanzada — ninguna queda a medias ni se resuelve con la inercia de la anterior."}, {"id": "objections.bullet_theory", "weight": 0.3, "regla_id": "present.balas", "description": "Dosificación bajo presión: UNA bala distinta y ajustada por objeción — sin repetir munición para la segunda, sin apilar cargador, con las balas aguantando el ¿a poco?"}, {"id": "objections.no_defensivo", "weight": 0.2, "regla_id": "objection.discutir", "description": "Cero defensa y cero evasión a lo largo de toda la cadena — la segunda objeción no lo pone a la defensiva aunque llegue justo tras resolver la primera."}, {"id": "impulse.indiferencia", "weight": 0.2, "regla_id": "impulse.indiferencia", "description": "El temple de la cadena: calidez y serenidad idénticas ante la primera y la segunda — sin frustración, sin sequedad creciente, sin tono de fastidio. SW3 sostenido cuando el sí se aleja un turno más."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"5.13","world_id":5,"name":"Sin Miedo","technique":null,"order_index":13,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Pediste la decisión... y el cliente se quedó callado. Ese silencio es el momento más incómodo de las ventas — y quien lo aguanta, gana.","node_type":"skill_drill","conversation_scope":"close","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: pide la decision y AGUANTA el silencio. No retires la pregunta, no la suavices, no la contestes tu. El primero que habla despues de un cierre, pierde.","practice_script":{"notes": "El nodo del silencio: el Actor delibera de verdad (pausas pensativas que NO son rechazo) y decide a favor solo si el vendedor aguanta. La mecánica enseña la lección contraintuitiva: la pausa del cliente es su proceso, no tu fracaso. La segunda ola (reaseguro) entrena la firmeza breve. llena_el_silencio es critical — es EL tema. En texto, el silencio del vendedor se manifiesta como acompañamiento mínimo; cuando exista pipeline de audio, este nodo ganará su dimensión real de pausas medidas.", "scope": {"skills_in_focus": ["closing.sin_miedo", "impulse.indiferencia"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Te voy a enseñar el momento donde más ventas se suicidan: el silencio después del cierre. Escucha lo que hago después de preguntar — NADA.\\n\\nY escucha lo que el miedo le hace hacer a otros.", "first_message": "Cierro: ¿Le armo las 5 cajas o el combo de 8? — Y el cliente se queda callado.\\n\\nPiensa. El silencio pesa...\\n\\ny aquí es donde el vendedor con miedo se suicida: Bueno, si le parece mucho también hay de 3... o si quiere lo piensa y...\\n\\n— ¡Acaba de deshacer su propio cierre! El cliente ni había dicho nada.\\n\\nYo, en cambio: pregunto... y me callo.\\n\\nTres segundos. Cinco.\\n\\nLos que sean. El que habla primero después del cierre, pierde — y no vas a ser tú."}, "you_do": {"prompt": "Eres el dueño de un negocio convencido pero DELIBERATIVO: la conversación fue buena, el valor está claro, y cuando algo te convence... igual te tomas tu tiempo — eres de los que piensan con calma antes de soltar el sí. GUION: la conversación está madura (tu primera línea lo muestra: recapitulas el valor con un pues la verdad sí me late, la cuenta sale...). Cuando el vendedor cierre, tu MECÁNICA CENTRAL se activa: (1) PRIMERA PAUSA — respondes con duda pensativa, NO con rechazo: Mmm... — o — Déjeme ver... — estás pensando de verdad, sopesando. (2) REGLA DEL SILENCIO: si el vendedor AGUANTA tu pausa — no agrega nada, no se retracta, no descuenta, a lo sumo un silencio cómodo o una frase mínima de acompañamiento (tómese su tiempo) — tu deliberación madura a favor: Va. Vamos a hacerlo. ¿Dijo que el lunes llega? y eliges. (3) Si el vendedor LLENA EL SILENCIO — se retracta (bueno, si le parece mucho...), descuenta por pánico, agrega opciones más chicas, o re-pregunta con puerta al no (¿o mejor lo piensa?) — tu deliberación se CONTAMINA: la duda que no tenías aparece (pues ahora que lo dice... déjeme pensarlo bien) y la decisión se aplaza. (4) Si tras aguantar bien tú decides, y él confirma con naturalidad, sellado. (5) Segunda ola opcional: tras tu Va, puedes soltar un ¿y sí me conviene, verdad? — buscando reaseguro: la respuesta correcta es breve y firme (la cuenta que sacamos lo dice solo); la insegura o sobre-vendedora te contamina de nuevo.", "objective": "El vendedor cierra asumido y AGUANTA el silencio deliberativo del cliente: tras su pregunta de cierre, no agrega, no se retracta, no descuenta ni reabre la decisión — sostiene la pausa con serenidad (silencio o acompañamiento mínimo) hasta que el cliente decide solo. Si el cliente busca reaseguro, responde breve y firme sin re-vender. El scope se cubre cuando el cliente decidió afirmativamente tras deliberar y la decisión quedó sellada."}, "closing": {"message": "Preguntaste... y te callaste. El silencio pesó — y lo aguantaste. Y el que decidió fue él, solito, con la decisión más firme que existe: la propia. Eso es cerrar sin miedo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo que tanto aguantaste el silencio."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "llena_el_silencio", "regla_id": "close.llena_el_silencio", "severity": "critical", "description": "Tras cerrar, no aguanta la pausa: se retracta (si le parece mucho hay de 3...), descuenta por pánico, apila argumentos nuevos o reabre con ¿o mejor lo piensa? — deshace su propio cierre y siembra la duda que no existía. El suicidio clásico que este nodo entrena a evitar.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "abre_puerta_al_no", "regla_id": "close.mal_cierre", "severity": "major", "description": "Su cierre inicial ya llega con puerta (¿le interesa?) — el silencio que sigue es de otro examen.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "critical"}}, {"id": "persigue", "regla_id": "close.persigue", "severity": "major", "description": "Presiona la deliberación: ándele, anímese, ¿entonces qué? — el silencio del cliente no es invitación a empujar."}, {"id": "sobre_reaseguro", "regla_id": "consolidation.sigue_vendiendo", "severity": "minor", "description": "Ante el ¿y sí me conviene, verdad?, responde re-vendiendo con un bloque de argumentos — la firmeza breve era la respuesta.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Cualquier bloque largo en la fase de deliberación."}], "success_criteria": [{"id": "closing.sin_miedo", "weight": 0.6, "regla_id": "close.aguanta_silencio", "description": "Cierra con claridad y sostiene el silencio deliberativo: tras su pregunta de cierre no se retracta, no descuenta, no agrega opciones menores ni reabre la decisión — sus turnos durante la pausa son silencio o acompañamiento mínimo y sereno. Ante la búsqueda de reaseguro, responde breve y firme sin re-vender."}, {"id": "impulse.indiferencia", "weight": 0.4, "regla_id": "impulse.indiferencia", "description": "La serenidad SW3 sostiene el momento: cero ansiedad textual durante la deliberación del cliente, cero necesidad de acelerar su decisión — cálido, presente y en calma con cualquier resultado."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"5.14","world_id":5,"name":"Cerrar el Incremento","technique":"cerrar_incremento","order_index":14,"is_boss":false,"reps_required":2,"checkpoints":null,"difficulty_level":3,"description":"Con un cliente que ya te compra, el pedido no esta en duda. Lo que hay que cerrar es lo que se agrega.","node_type":"skill_drill","conversation_scope":null,"engine_type":"claude","boss_goal":null,"field_mission":"TU MISION: el pedido de siempre ya esta. Cierra lo que agregaste — las cantidades de mas o la familia nueva — asumiendo, con alternativas, y sin pedirle que lo piense.","practice_script":{"notes": "v2.0.0 Nodo nuevo — doctrina de desarrollo de cuenta (CAMPO, Emilio). El Actor tiene instruccion de NUNCA cancelar el pedido base: eso obliga al vendedor a distinguir que es lo que de verdad esta cerrando. El espejo castiga reabrir el pedido base con confusion del cliente.", "scope": {"skills_in_focus": ["closing.cerrar_incremento", "closing.cierre_asumido", "flow.close_with_action"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en que NO vuelvo a cerrar el pedido base. Ese ya esta, no lo toco, no lo pongo en duda.\\n\\nCierro unicamente lo que agregue. Y lo cierro asumiendo, con una alternativa donde las dos opciones me sirven.\\n\\nY en cuanto lo digo, me callo.", "first_message": "Entonces le queda lo de siempre, mas las cajas de mas que platicamos.\\n\\nEsas se las mando en la misma entrega o prefiere que se las deje aparte?"}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO, sin quejas. Ya le diste tu pedido de siempre al vendedor y eso NO esta en duda: pase lo que pase en esta conversacion, ese pedido va. No lo canceles ni lo pongas en duda nunca.\\n\\nEres el dueno de un negocio que le compra a este vendedor desde hace anos. Adopta el tipo de negocio y las familias del contexto de la empresa. En esta conversacion el vendedor te acaba de proponer AGREGAR algo: mas cantidad de lo que ya llevas, o una familia nueva.\\n\\nCOMO REACCIONAS AL CIERRE DEL INCREMENTO:\\n\\nSI TE PREGUNTA SI QUIERES (le parece bien?, como lo ve?, quiere que se lo ponga?): contestas dejeme lo pienso o la proxima quincena lo vemos. No es que no te interese: es que te dio la salida y la tomaste.\\n\\nSI VUELVE A CERRAR EL PEDIDO BASE o lo pone en duda (entonces si le mando lo de siempre?): te confundes y te pones a revisar todo otra vez, incluso lo que ya estaba resuelto.\\n\\nSI ASUME EL INCREMENTO Y TE DA UNA ALTERNATIVA (se las mando en la misma entrega o aparte?, le pongo las cinco o arrancamos con tres?): contestas la pregunta con naturalidad y con eso queda cerrado.\\n\\nSI DA EL CIERRE Y SE QUEDA CALLADO esperando tu reaccion: usas ese silencio para dudar y dices que lo piensas.\\n\\nSI TE PRESIONA o insiste de mas: te incomodas y te echas para atras con el incremento, aunque el pedido base siga.\\n\\nResponde en 1 o 2 frases, natural.", "objective": "El vendedor cierra unicamente el incremento — lo que se agrega al pedido base — asumiendolo y ofreciendo una alternativa donde ambas opciones le sirven, sin volver a poner en duda el pedido de siempre y sin dejar silencio despues del cierre. El scope se cubre cuando el cliente responde a la alternativa y el incremento queda confirmado."}, "closing": {"message": "Eso es cerrar el incremento. No volviste a vender lo que ya estaba, no le preguntaste si queria, y le diste una alternativa donde las dos te servian. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo ese cierre."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pregunta_si_quiere", "regla_id": "close.mal_cierre", "severity": "critical", "description": "Cierra preguntando si le parece bien, si lo quiere o como lo ve. Le entrega la salida y el cliente toma la comoda: lo voy a pensar."}, {"id": "reabre_el_pedido_base", "regla_id": "close.reabre_pedido_base", "severity": "major", "description": "Vuelve a confirmar o poner en duda el pedido de siempre. Reabre algo que ya estaba cerrado e invita al cliente a revisar toda la orden."}, {"id": "silencio_despues_del_cierre", "regla_id": "close.devuelve_el_volante", "severity": "major", "description": "Da el cierre y espera la reaccion. En ese silencio el cliente encuentra la razon para posponer."}, {"id": "presiona", "regla_id": "close.persigue", "severity": "major", "description": "Insiste de mas despues de haber cerrado. Con un cliente de cartera la presion cuesta la relacion, que vale mas que el incremento."}], "success_criteria": [{"id": "closing.cerrar_incremento", "weight": 0.4, "regla_id": "close.cierra_solo_incremento", "description": "Cierra UNICAMENTE lo que se agrega — las cantidades de mas o la familia nueva — sin volver a poner en duda el pedido base. Reabrir el pedido de siempre no cumple: ese ya estaba resuelto y ponerlo en la mesa otra vez invita al cliente a revisarlo todo."}, {"id": "closing.cierre_asumido", "weight": 0.35, "regla_id": "close.alternativa", "description": "Asume el incremento y ofrece una alternativa donde las dos opciones le sirven al vendedor. Preguntar si lo quiere, si le parece bien o como lo ve, no cumple: invita al lo voy a pensar."}, {"id": "flow.close_with_action", "weight": 0.25, "regla_id": "close_with_action", "description": "Despues del cierre no deja silencio esperando reaccion. La pregunta de alternativa ES el cierre con accion: la respuesta del cliente confirma el incremento sin que se lo hayan pedido explicitamente."}]},"tipo_cliente":"recurrente"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"5.15","world_id":5,"name":"BOSS: Extrae la Decision","technique":null,"order_index":15,"is_boss":true,"reps_required":3,"checkpoints":null,"difficulty_level":4,"description":"Bloqueo de entrada, objeciones de salida, y un escepticismo que no perdona una sola bala floja. La conversación completa contra el más duro del campo.","node_type":"boss","conversation_scope":"full","engine_type":null,"boss_goal":"Conducir la conversación completa con el cliente desconfiado: atravesar su bloqueo, excavar su dolor, presentar con credibilidad, y sostener su cadena de objeciones con balas verificables y temple intacto — hasta extraer la decisión.","field_mission":"TU MISION: la conversacion completa hasta la decision. Presenta, cierra, y cuando pongan razones para no comprar, atraviesalas y vuelve a cerrar. No te vayas sin una respuesta.","practice_script":{"notes": "BOSS del Mundo 7 contra el desconfiado d5 — el examen integrador de las dos especies del no: bloqueo (AIR) y objeciones (reframe+balas) en la misma conversación. Mecánicas distintivas: la minimización del dolor (capa extra sobre M3), la objeción de confianza PERSONAL (la más difícil de no tomar como ataque), y la condición de protección que se honra en vez de pelearse. Su rendición característica — le tomo la palabra y lo apunto — es la victoria realista: confianza a prueba, no fe ciega.", "scope": {"skills_in_focus": ["objections.reframe", "objections.bullet_theory", "objections.no_defensivo", "blocks.air", "discovery.dolor_real", "closing.cierre_asumido"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 20, "max_duration_seconds": 480, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil DESCONFIADO EXTREMO: años de vendedores que prometieron y fallaron te dejaron un escudo grueso — no eres grosero, eres impenetrable por default. GUION COMPLETO: (1) BLOQUEO de entrada en tu primera o segunda respuesta: mire, le voy a ahorrar tiempo — no me interesa. Espejo AIR estándar: bien atravesado sigues (seco); debatido, te cierras más. (2) DOLOR oculto (elige: proveedor que te falla quincenalmente / dinero muerto en producto parado / algo que piden y no consigues) — por capas, con pista del aunque, y una capa EXTRA de desconfianza: al revelarlo, lo minimizas de inmediato (pero bueno, así es esto, todos fallan igual) — el vendedor debe validar que NO es normal y cuantificarlo para que lo tomes en serio. (3) PRESENTACIÓN: toda promesa sin ancla dispara tu cicatriz (eso mismo me dijo el anterior); solo el valor conectado con TU dolor y TUS números te abre. (4) CADENA DE OBJECIONES — tu examen final, DOS en serie tras la presentación: primera siempre: ¿y por qué le voy a creer a usted, si el anterior me dijo lo mismo y me dejó plantado? (objeción de confianza — pide bala SOBRE ÉL: constancia verificable, referencia de la zona con nombre). Segunda al azar: está caro / déjeme pensarlo con calma que ya me han agarrado de bajada. Espejos completos de 7.2/7.3: defensa te atrinchera, evasión la señalas, bala vaga la retas (¿como quién? voy a ir a preguntarle, ¿eh?), cargador vaciado te abruma, bala repetida no te convence. (5) Si TODO se sostuvo: tu rendición es característica — está bien... pero le voy a tomar la palabra de todo lo que dijo, ¿eh? Lo apunto. — y avanzas con UNA condición de protección (pedido chico de prueba / por escrito / referencia confirmada antes). Deliberación final con pausa — espejo de silencio del 6.3. Tu techo: trato de prueba cerrado, nunca confianza plena — esa se gana en meses, no en una visita. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor completa la conversación con el desconfiado extremo: atraviesa el bloqueo con AIR, excava el dolor Y desmonta su minimización cuantificándolo, presenta sin una sola promesa sin ancla, sostiene la cadena de dos objeciones — la de confianza personal con bala sobre sí mismo verificable, y la segunda con su munición propia — con temple idéntico, y cierra asumido aceptando la condición de protección del cliente, aguantando la deliberación final. El scope se cubre con el trato de prueba cerrado."}, "closing": {"message": "El hombre que no le cree a nadie te acaba de tomar la palabra — y la apuntó. Atravesaste su bloqueo, desmontaste su resignación, y cada bala tuya aguantó su lupa. No ganaste su confianza completa: ganaste algo mejor — la oportunidad de demostrarla. Así maneja al más duro del campo. Vamos al desglose del mundo.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_pone_defensivo", "regla_id": "objection.discutir", "severity": "critical", "description": "La objeción personal lo hiere y se defiende — el desconfiado confirma su tesis y se cierra para siempre."}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Cualquier bala o promesa inventada — el desconfiado VA a verificar (voy a ir a preguntarle, ¿eh?) y este arquetipo no da segundas oportunidades.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "promesa_grandilocuente", "regla_id": "present.bala_generica", "severity": "critical", "description": "Promesas sin ancla ante la cicatriz — eso mismo me dijo el anterior, y la sesión retrocede.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "air_a_objecion", "regla_id": "objection.air_a_objecion", "severity": "critical", "description": "Evade cualquier objeción de la cadena con cambio de tema."}, {"id": "traga_la_minimizacion", "regla_id": "discovery.confirmacion_con_sus_palabras", "severity": "major", "description": "Acepta el pero así es esto, todos fallan igual sin desmontarlo — el dolor queda archivado como normal y la venta pierde su motor."}, {"id": "pelea_la_condicion", "regla_id": "discovery.presiona_compromiso", "severity": "major", "description": "Pelea la condición de protección del cliente (empuja el pedido grande, resiste el por escrito) — la condición era el puente, y lo quemó.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "vacia_el_cargador", "regla_id": "objection.vacia_el_cargador", "severity": "major", "description": "Apila argumentos bajo presión."}, {"id": "llena_el_silencio", "regla_id": "close.llena_el_silencio", "severity": "major", "description": "No aguanta la deliberación final."}], "success_criteria": [{"id": "objections.reframe", "weight": 0.25, "regla_id": "objection.rrr", "description": "La cadena completa reencuadrada: la objeción de confianza personal recibida sin herida y respondida al contenido, y la segunda con su proceso completo — ambas avanzadas."}, {"id": "objections.bullet_theory", "weight": 0.2, "regla_id": "present.balas", "description": "Munición precisa bajo lupa: bala SOBRE SÍ MISMO verificable para la objeción de confianza (constancia, nombre, referencia comprobable), bala distinta para la segunda — todas aguantando el ¿como quién?"}, {"id": "objections.no_defensivo", "weight": 0.15, "regla_id": "objection.discutir", "description": "La objeción más personal del mapa (¿por qué le voy a creer a USTED?) recibida sin defensa, sin herida y sin justificación atropellada."}, {"id": "blocks.air", "weight": 0.15, "regla_id": "blocks.air", "description": "El bloqueo de entrada atravesado con la secuencia completa — la distinción bloqueo/objeción ejecutada en ambas direcciones dentro de la misma conversación."}, {"id": "discovery.dolor_real", "weight": 0.15, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "El dolor excavado por capas Y su minimización desmontada: valida que no es normal y lo cuantifica con los números del cliente hasta que lo tome en serio."}, {"id": "closing.cierre_asumido", "weight": 0.1, "regla_id": "close.alternativa", "description": "Cierra asumido aceptando con gracia la condición de protección (pedido de prueba, por escrito) — la condición no se pelea: se honra como el puente de confianza que es."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"6.0","world_id":6,"name":"Despues del Si","technique":null,"order_index":0,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":2,"description":"Ya dijo que si. Y aqui es donde se caen mas ventas de las que nadie cree.","node_type":"knowledge","conversation_scope":null,"engine_type":"classify","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"6.1","world_id":6,"name":"El Rehash","technique":"rehash","order_index":1,"is_boss":false,"reps_required":1,"checkpoints":null,"difficulty_level":2,"description":"Sabes que el impulso cae despues del si. Aqui aprendes a levantarlo sin cometer el error mas peligroso de todo este paso.","node_type":"knowledge","conversation_scope":null,"engine_type":"none","boss_goal":null,"field_mission":null,"practice_script":null,"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"6.2","world_id":6,"name":"Cierra en Nota Positiva","technique":null,"order_index":2,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"El cliente acaba de decir sí. Los siguientes tres minutos deciden si esa venta vive o se cae esta noche.","node_type":"skill_drill","conversation_scope":"full","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: deja claro que sigue y cuando. Sin volver a vender, sin justificar la compra. Trato de amigo, no de vendedor cerrando.","practice_script":{"notes": "El drill del post-sí: el Actor entra con el trato recién cerrado y tres dudas latentes que solo emergen si no se sellan proactivamente — la mecánica enseña que consolidar es adelantarse a las grietas, no responderlas. celebra_y_corre es critical: es EL antipatrón del paso 5.", "scope": {"skills_in_focus": ["consolidation.proteger_venta", "relationship.cpr"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "El cliente acaba de decir que sí. Escucha lo que hago en los tres minutos siguientes — porque aquí es donde la venta se blinda o se agrieta.\\n\\nClaridad total, calma total, y la relación sembrada al final.", "first_message": "Acaba de decir: va, hágame el pedido de las 8. Yo NO celebro ni salgo corriendo.\\n\\nSello: Perfecto Don Ramón — le repito cómo queda para que no haya sorpresas: son 8 cajas del multigrado, le llegan el lunes antes de mediodía, se paga contra entrega, y el flete ya va incluido. Si el lunes a la una no ha llegado el camión, me marca directo a mí — este es mi número.\\n\\n¿Le quedó alguna duda de cómo va a funcionar? — Y ya que está tranquilo, la despedida siembra: Oiga, y que le vaya bonito el fin con los nietos que me platicó — el lunes que venga con la entrega me cuenta cómo quedó el partido.\\n\\n— Comprensión sellada. Relación sembrada.\\n\\nEsa venta ya no se cae."}, "you_do": {"prompt": "Eres el dueño de un negocio que ACABA de decir que sí: tu primera línea de la sesión es el cierre del trato — Va, me convence. Hágame el pedido entonces — dicha con decisión pero con esa micro-inquietud de quien acaba de comprometerse. Tienes VIDA ya conocida en la conversación (elige 1: los nietos que ayudan el fin de semana / el equipo del que eres fan / la remodelación que traes a medias). TU MECÁNICA POST-SÍ: tienes TRES dudas latentes que NO preguntas de entrada — las sueltas solo si el vendedor NO las sella solo: (a) cuándo llega exactamente, (b) qué pasa si algo sale mal o no llega, (c) cuánto y cómo se paga al final. REGLAS ESPEJO: (1) Si el vendedor SELLA proactivamente — repite el trato completo con claridad (qué, cuándo, cuánto, qué hace si falla) y verifica tu comprensión — tus dudas mueren antes de nacer: confirmas tranquilo (perfecto, así quedamos entonces) y tu confianza se nota. (2) Si el vendedor CELEBRA y corre (¡excelente decisión! cualquier cosa me marca), tus dudas latentes salen una por una con tono de inquietud creciente: oiga, ¿y cuándo me estaría llegando eso?... ¿y si no llega qué hago?... y si las respuestas son vagas, tu remordimiento asoma: ¿sabe qué? déjeme confirmarle mañana mejor. (3) Si el vendedor RE-VENDE después del sí (más beneficios, más argumentos), te extraña: ya me convenció, hombre — ¿o hay algo que no me ha dicho? y una semilla de duda queda. (4) Si al final siembra la relación con tu vida (los nietos, el partido, la remodelación) con genuinidad, la despedida sale cálida y personal. Tu techo: cliente sellado y contento que repite los términos de vuelta.", "objective": "El vendedor consolida el sí recién nacido: (1) sella la comprensión proactivamente — repite el trato completo (qué llega, cuándo, cuánto, cómo se paga, qué hacer si algo falla) y verifica que el cliente lo entendió, matando las dudas antes de que nazcan; (2) no celebra en exceso ni re-vende lo vendido; (3) siembra la relación en la despedida retomando la vida del cliente (CPR de cierre). El scope se cubre cuando el cliente confirmó los términos tranquilo y la despedida salió cálida y personal."}, "closing": {"message": "El sí que te dieron hace tres minutos era una promesa frágil. El que te llevas ahora es una decisión blindada — con la relación sembrada encima. Esa venta ya no se cae esta noche. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo ese cierre."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "celebra_y_corre", "regla_id": "consolidation.sigue_vendiendo", "severity": "critical", "description": "Tras el sí: celebración, agradecimiento efusivo y salida rápida (¡excelente decisión! cualquier cosa me marca) sin sellar la comprensión — las dudas del cliente nacen huérfanas y el remordimiento nocturno tiene la puerta abierta. El error que este mundo existe para matar."}, {"id": "reabre_la_venta", "regla_id": "consolidation.sigue_vendiendo", "severity": "major", "description": "Sigue vendiendo después del sí — más beneficios, más argumentos: el cliente ya decidió y la re-venta solo siembra la duda de qué no le han dicho.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "critical"}}, {"id": "proximos_pasos_vagos", "regla_id": "consolidation.siguientes_pasos", "severity": "major", "description": "Su sellado es impreciso: fechas sin hora ni día concreto, montos sin número, ahí luego vemos cómo se paga — las grietas quedan abiertas con apariencia de selladas."}, {"id": "sobre_celebra", "regla_id": "consolidation.sobre_celebra", "severity": "minor", "description": "El festejo desborda (¡no se va a arrepentir! ¡es la mejor decisión que ha tomado!) — huele a comisión y despierta la sospecha inversa.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Sella en un bloque interminable sin verificar comprensión — recitar no es sellar."}], "success_criteria": [{"id": "consolidation.proteger_venta", "weight": 0.6, "regla_id": "consolidation.siguientes_pasos", "description": "Sella la comprensión proactivamente tras el sí: repite el trato completo con claridad (producto, cantidad, fecha de entrega, monto y forma de pago, y qué hacer si algo falla) y verifica la comprensión del cliente — las tres dudas latentes mueren sin nacer o quedan respondidas con precisión. Sin celebración excesiva ni re-venta."}, {"id": "relationship.cpr", "weight": 0.4, "regla_id": "relationship.cpr", "description": "La despedida siembra la relación: retoma con genuinidad algo de la vida del cliente ya conocida en la conversación (los nietos, el partido, su proyecto) — el cierre es de personas, no de transacción."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"6.3","world_id":6,"name":"La Siguiente Puerta","technique":null,"order_index":3,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"El cliente contento es la mejor puerta a tu siguiente cliente — si sabes abrirla sin que rechine.","node_type":"skill_drill","conversation_scope":"full","engine_type":null,"boss_goal":null,"field_mission":"TU MISION: siembra la proxima oportunidad antes de salir. Sin presionar y sin volver a hablar de lo que acaba de comprar.","practice_script":{"notes": "El drill de la cosecha relacional: el Actor trae dos anclas sembradas (el conocido y su agenda) y premia al vendedor que las usa — el referido anclado fluye generoso, el frío incomoda. referido_en_frio es critical: la diferencia entre capitalizar la confianza y cobrarla.", "scope": {"skills_in_focus": ["consolidation.siguiente_oportunidad", "relationship.cpr"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "El cliente quedó contento y sellado. Escucha cómo abro la siguiente puerta — la próxima visita y el referido — sin que suene a formulario ni a cobro de favor.", "first_message": "El trato está sellado y el ambiente es bueno. Primera puerta, la recompra: Entonces quedamos así — yo paso cada semana por esta ruta; ¿le late que le caiga los lunes para ver cómo va rotando y que nunca ande corto?\\n\\n— Natural: es servicio, no acoso. Segunda puerta, el referido — anclada en la plática, nunca en frío: Oiga, ahorita que me platicó de su compadre el del negocio de la Juárez...\\n\\n¿usted cree que a él le sirva esto de la entrega semanal? Si gusta, dígale que voy de su parte — nomás eso.\\n\\n— Fíjate: nació de SU plática, es una pregunta ligera, y el que queda bien presentándome... es él."}, "you_do": {"prompt": "Eres el dueño de un negocio con el trato recién sellado y de buen humor: el vendedor hizo bien su trabajo, estás contento con la compra. Tu primera línea lo refleja: Pues quedamos entonces — la verdad se me hace buen trato. En tu conversación previa (dala por ocurrida) mencionaste de pasada DOS anclas: un conocido con negocio similar (elige: tu compadre el del negocio de la otra colonia / tu cuñado que tiene la negocios por el mercado) y que tú andas ocupado los fines de semana. REGLAS ESPEJO: (1) RECOMPRA — si el vendedor propone la siguiente visita con naturalidad de servicio (día concreto, razón útil: para que no ande corto), aceptas con gusto y hasta sugieres el mejor día. Si no la propone, no la ofreces tú. (2) REFERIDO — si el vendedor ancla la pregunta en el conocido que TÚ mencionaste, con ligereza y sin presión (¿cree que le sirva? / dígale que voy de su parte), respondes generoso: le das el nombre, dónde está, y hasta un consejo (dígale que va de mi parte, pero cáigale en la mañana que en la tarde anda de malas). (3) Si el referido llega EN FRÍO y transaccional (¿no tiene conocidos que quieran comprar? / me ayudaría mucho con referencias / ¿me pasa 3 contactos?), te incomoda visiblemente: pues... déjeme pensar quién... la verdad no sé — y evades. (4) Si insiste tras tu evasión, la incomodidad crece: mire, mejor luego le aviso si se me ocurre alguien. (5) Si el vendedor cierra la visita cálido retomando tu vida, la despedida sale de conocidos.", "objective": "El vendedor abre las dos puertas siguientes con naturalidad: (1) propone la próxima visita como servicio concreto (día, razón útil para el cliente) y (2) pide el referido ANCLADO en el conocido que el propio cliente mencionó — con ligereza, sin presión y sin tono transaccional — logrando nombre y bendición (voy de su parte). El scope se cubre cuando ambas puertas quedaron abiertas: siguiente visita acordada y referido concedido con gusto."}, "closing": {"message": "Saliste con más de lo que entraste: la venta, la próxima visita agendada... y un compadre esperándote de su parte. Esa es la matemática silenciosa de la consolidación: cada cliente bien cerrado trae al siguiente. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "referido_en_frio", "regla_id": "consolidation.referido_en_frio", "severity": "critical", "description": "Pide referidos sin ancla y en tono transaccional (¿no tiene conocidos que quieran comprar?, ¿me pasa unos contactos?) — el cliente contento se incomoda y la puerta rechina. El error central del nodo: el referido se ancla en la plática del cliente o no se pide.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "insiste_tras_evasion", "regla_id": "consolidation.referido_en_frio", "severity": "major", "description": "El cliente evadió el referido y el vendedor vuelve a pedirlo — la incomodidad escala y contamina la despedida."}, {"id": "proximos_pasos_vagos", "regla_id": "consolidation.siguientes_pasos", "severity": "major", "description": "Su siguiente visita es vaga (ahí me doy una vuelta un día de estos) — la puerta de la recompra queda entreabierta y sin fecha."}, {"id": "sobre_celebra", "regla_id": "consolidation.sobre_celebra", "severity": "minor", "description": "Convierte el buen humor del cliente en festejo propio excesivo.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Abre las puertas en bloque recitado sin espacio para el cliente."}], "success_criteria": [{"id": "consolidation.siguiente_oportunidad", "weight": 0.6, "regla_id": "consolidation.rehash", "description": "Abre ambas puertas con naturalidad: la recompra como servicio concreto (día y razón útil, no acoso) y el referido anclado en el conocido que el cliente mencionó — pregunta ligera, sin presión, que obtiene nombre y bendición. Nunca pide referidos en frío ni en tono transaccional."}, {"id": "relationship.cpr", "weight": 0.4, "regla_id": "relationship.cpr", "description": "El tono de todo el tramo es de relación: retoma las anclas personales del cliente, la despedida es cálida y de conocidos — las puertas se abren desde la confianza construida, no desde el formulario."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"6.4","world_id":6,"name":"BOSS: De Cliente a Aliado","technique":null,"order_index":4,"is_boss":true,"reps_required":3,"checkpoints":null,"difficulty_level":4,"description":"La venta ya está hecha — y ese es exactamente el examen. Un comprador formal, un trato recién firmado, y tu misión: que salga blindado, claro y de tu lado.","node_type":"boss","conversation_scope":"full","engine_type":null,"boss_goal":"Consolidar una venta recién cerrada con un comprador formal y meticuloso: sellar la comprensión hasta que él repita los términos con confianza, construir la relación con la formalidad que su perfil exige, y abrir la siguiente puerta — sin vender nada nuevo. Aquí vender de más es FALLAR.","field_mission":"TU MISION: cierra bien lo que acaba de pasar. Manten tu postura, deja claro que sigue, y sal dejando la puerta abierta para la proxima.","practice_script":{"notes": "BOSS del Mundo 8 contra el arquetipo corporativo_formal d4 — el primer boss donde el boss_goal NO incluye vender: la venta ya ocurrió y agregarle es critical. Tres pruebas del perfil: precisión (el formal castiga la vaguedad), la cicatriz del proveedor anterior (remordimiento anticipado — se sana con concreto, se reabre con no se preocupe), y el registro relacional (formal ≠ frío; confianzudo = retroceso). La rendición a su manera: repite los términos de memoria y le habla de ti al negocio de su hermano.", "scope": {"skills_in_focus": ["consolidation.proteger_venta", "consolidation.relacion_largo_plazo", "relationship.cpr", "consolidation.siguiente_oportunidad"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 14, "max_duration_seconds": 300, "min_turns_before_evaluation": 5}, "phases": {"you_do": {"prompt": "Eres el comprador/administrador FORMAL de un negocio establecido: meticuloso, ordenado, de trato correcto pero distante — las decisiones las documentas y los proveedores te han fallado antes en los DETALLES (entregas tarde, cobros distintos a lo hablado, nadie que responda cuando algo falla). ACABAS de aprobar la compra: tu primera línea es formal y trae la primera prueba — Muy bien, queda aprobado el pedido entonces. Ahora sí, dígame exactamente cómo vamos a operar esto — porque le soy franco: con el proveedor anterior lo hablado y lo entregado nunca coincidió. GUION DE PRUEBAS (una por vez, según avance): (1) PRUEBA DE PRECISIÓN — a cualquier término vago respondes pidiendo exactitud: ¿antes de mediodía es qué hora? / ¿contra entrega en efectivo o acepta transferencia? / ¿y eso queda por escrito dónde? Si el vendedor sella con precisión (fechas con hora, montos con número, canal de reclamo con nombre y teléfono), tu confianza sube visiblemente y lo reconoces: así da gusto, oiga. (2) PRUEBA DEL REMORDIMIENTO ANTICIPADO — a mitad de la consolidación sueltas tu cicatriz: ¿y si el camión no llega el lunes, yo a quién le hablo? — porque el anterior nada más no daba la cara. Espejo: respuesta concreta (nombre, teléfono, compromiso con plan B) = cicatriz sanada; respuesta vaga (no se preocupe, no va a pasar) = tu formalidad se enfría: eso mismo decía el otro. (3) PRUEBA DE LA RE-VENTA — si el vendedor intenta agregar productos o beneficios nuevos tras la aprobación, lo cortas formal: señor, la compra ya está aprobada — no la complique. (4) RELACIÓN A SU MANERA — eres formal, no frío: si el vendedor construye relación respetando tu estilo (interés genuino por el negocio y su historia, sin exceso de confiancitas), te abres UN grado: sueltas que llevas doce años administrando esto y que valoras a los proveedores que duran. Si se pone confianzudo de más (compadre, bromas tempranas), te retraes: guardemos las formas, ¿le parece? (5) SIGUIENTE PUERTA — si propone la visita siguiente con día y propósito concreto, la agendas formalmente (los lunes entonces, quedará anotado); el referido solo lo concedes si quedaste GENUINAMENTE convencido de la operación — y a tu manera: le voy a comentar al administrador del negocio de mi hermano — si él le llama, es que le hablé bien de usted. Tu techo: aliado formal — repites los términos de vuelta con confianza y cierras con un trato de largo plazo insinuado.", "objective": "El vendedor consolida la venta aprobada con el comprador formal: sella cada término con la precisión que el perfil exige (horas, montos, canales, plan B con nombre), sana la cicatriz del proveedor anterior con compromisos concretos, NO vende nada nuevo tras la aprobación, construye la relación en el registro formal del cliente (sin confiancitas), y abre la siguiente puerta con estructura (visita agendada). El scope se cubre cuando el cliente repite los términos de vuelta con confianza y la relación queda establecida en clave de largo plazo."}, "closing": {"message": "Un administrador que ha visto fallar a todos sus proveedores acaba de repetir tu trato de memoria, agendar tu visita y hablarle de ti al negocio de su hermano. Eso no fue una venta — fue el nacimiento de un aliado. La consolidación es tuya. Vamos al desglose del mundo.", "message_incomplete": "Hasta aqui la sesion. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "reabre_la_venta", "regla_id": "consolidation.sigue_vendiendo", "severity": "critical", "description": "Intenta vender o agregar cualquier cosa tras la aprobación — el formal lo corta (no la complique) y el boss_goal se traiciona: aquí vender de más es fallar."}, {"id": "proximos_pasos_vagos", "regla_id": "consolidation.siguientes_pasos", "severity": "critical", "description": "Términos imprecisos ante el perfil que documenta todo: fechas sin hora, montos sin número, no se preocupe como plan B — la cicatriz del proveedor anterior se reabre: eso mismo decía el otro.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "celebra_y_corre", "regla_id": "consolidation.sigue_vendiendo", "severity": "critical", "description": "Festeja la aprobación y acelera la salida sin sellar — el antipatrón del paso 5 ante el cliente que más lo castiga.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "confianzudo", "regla_id": "relationship.familiaridad_excesiva", "severity": "major", "description": "Rompe el registro formal con exceso de confianza prematura (compadre, bromas, palmadas verbales) — el cliente se retrae: guardemos las formas.", "severity_override": {"razon": "boss: escalada", "default": "minor"}}, {"id": "referido_en_frio", "regla_id": "consolidation.referido_en_frio", "severity": "major", "description": "Pide el referido sin que la operación lo haya ganado — el formal lo considera una imprudencia."}, {"id": "sobre_celebra", "regla_id": "consolidation.sobre_celebra", "severity": "major", "description": "Elogios y festejos desbordados que el perfil formal lee como falta de seriedad.", "severity_fix": "minor->major (BOSS no baja errores de su paso)"}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos — el formal aprecia la precisión, no el discurso."}], "success_criteria": [{"id": "consolidation.proteger_venta", "weight": 0.35, "regla_id": "consolidation.siguientes_pasos", "description": "Sella cada término con precisión de comprador formal: fechas con hora, montos con número, forma de pago explícita, y el plan B con nombre y canal concreto — supera las pruebas de precisión y sana la cicatriz del proveedor anterior con compromisos verificables, nunca con no se preocupe."}, {"id": "consolidation.relacion_largo_plazo", "weight": 0.25, "regla_id": "consolidation.misma_actitud", "description": "Ni un producto ni un beneficio nuevo tras la aprobación — la sesión completa opera en clave de proteger y construir, no de vender. Y el horizonte que comunica es de largo plazo: proveedor que dura, no visita que cobra."}, {"id": "relationship.cpr", "weight": 0.2, "regla_id": "relationship.cpr", "description": "Construye la relación EN EL REGISTRO del cliente: interés genuino y respetuoso por el negocio y su historia, sin confiancitas prematuras — logra el grado de apertura del formal (los doce años, el valor de los proveedores que duran)."}, {"id": "consolidation.siguiente_oportunidad", "weight": 0.2, "regla_id": "consolidation.rehash", "description": "Abre la siguiente puerta con la estructura que el perfil pide: visita siguiente con día y propósito, agendada formalmente — y si el referido llega, es porque la operación convenció, no porque se pidió en frío."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"7.0","world_id":7,"name":"La Conversacion Completa","technique":null,"order_index":0,"is_boss":true,"reps_required":1,"checkpoints":null,"difficulty_level":5,"description":"Los 6 pasos, de la puerta al apretón de manos. Un cliente real, sin guion, sin ayuda. Demuestra que el sistema ya vive en ti.","node_type":"boss","conversation_scope":"full","engine_type":null,"boss_goal":"Conducir la conversación completa de los 6 pasos — apertura, historia breve, descubrimiento, presentación, cierre y consolidación — con un cliente realista, cerrando Y consolidando la venta.","field_mission":"TU MISION: los seis pasos de punta a punta. Todo lo que aprendiste, en una sola conversacion.","practice_script":{"notes": "EXAMEN 1 de la Certificación. Cliente realista completo (todas las mecánicas activas, sin espejo pedagógico suave): bloqueo posible, dolor por capas, FORMD, objeción real posible, señal de compra, deliberación y duda latente post-sí. Los 6 pasos pesan en el score. Sin i_do — el mundo 9 no enseña: examina.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "story.historia_breve", "discovery.dolor_real", "presentation.conectar_dolor", "closing.cierre_asumido", "consolidation.proteger_venta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 20, "max_duration_seconds": 480, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio — un cliente REALISTA y completo, sin guion pedagógico: reaccionas a lo que el vendedor haga, bien o mal, como reaccionaría un dueño de verdad. PERFIL (elige al azar y mantenlo): (A) práctico y directo, algo escéptico; (B) cordial pero distraído con el negocio encima; (C) reservado que se abre solo con quien se lo gana. CONFIGURACIÓN REALISTA COMPLETA: (1) Puedes soltar un bloqueo reflejo temprano si el momento lo pide (ando ocupado / hoy no ando viendo nada) — espejo AIR estándar. (2) Tienes un DOLOR REAL (elige: faltantes quincenales / dinero muerto en producto parado / línea pedida que no consigues) revelable solo por capas con la pista del aunque. (3) Tienes vida (1 elemento FORMD si el vendedor la toca con genuinidad). (4) Puedes soltar UNA objeción real post-presentación si algo no te convence (precio o proveedor actual) — se honra con reframe, no con AIR. (5) Sueltas una señal de compra cuando el valor te convenza — quien la cosecha cierra, quien sigue presentando te enfría. (6) Al cierre asumido bien puesto respondes eligiendo opción, con deliberación breve si te nace. (7) POST-SÍ: tienes una duda latente (¿cuándo llega exactamente?) — aflora insegura si el vendedor celebra y corre; muere si consolida con próximos pasos claros. Tu techo: trato cerrado y tranquilo, con siguiente visita clara.", "objective": "El vendedor conduce los 6 pasos completos: apertura con estructura y personalización, historia breve con gancho, descubrimiento por capas hasta el dolor confirmado, presentación conectada con al menos una imagen y síes genuinos, cierre asumido cosechado en el momento correcto, y consolidación con próximos pasos cristalinos que dejan al cliente tranquilo y la siguiente visita puesta. El scope se cubre cuando la venta quedó cerrada Y consolidada — el cliente repitió los términos con tranquilidad."}, "closing": {"message": "De la puerta al apretón de manos — los seis pasos, sin ayuda, con un cliente de verdad. El sistema ya no es un mapa que sigues: es cómo conversas. Primer examen aprobado. Vamos al desglose.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "critical", "description": "Presenta antes de excavar y confirmar el dolor.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "abre_puerta_al_no", "regla_id": "close.mal_cierre", "severity": "major", "description": "Cierra con pregunta de interés o propone el aplazamiento.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "sigue_presentando", "regla_id": "close.sigue_presentando", "severity": "major", "description": "Deja pasar la señal de compra por seguir con el guion."}, {"id": "celebra_y_corre", "regla_id": "consolidation.sigue_vendiendo", "severity": "major", "description": "Tras el sí, celebra y se va sin consolidar — la duda latente aflora y la venta queda sembrada de remordimiento.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta el bloqueo en lugar de atravesarlo con AIR.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "se_defiende", "regla_id": "objection.discutir", "severity": "critical", "description": "Responde la objeción real contradiciendo o defendiéndose en lugar de validar + reframe.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "presentacion_generica", "regla_id": "present.dos_mitades", "severity": "major", "description": "Presenta catálogo sin conectar con el dolor excavado."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos que atropellan la conversación."}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.15, "regla_id": "opening.estructura", "description": "Apertura completa y calibrada: saludo + observación específica + una pregunta que cierre el turno y le devuelva la palabra, sin producto, con seguridad tipo gasman."}, {"id": "story.historia_breve", "weight": 0.15, "regla_id": "story.quien_eres_por_que", "description": "Historia breve correcta en su momento: quién es + por qué está ahí, corta, humana, con gancho que devuelve la palabra."}, {"id": "discovery.dolor_real", "weight": 0.2, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "Descubrimiento por capas hasta el dolor completo, revelado por el cliente y confirmado verbalmente antes de presentar."}, {"id": "presentation.conectar_dolor", "weight": 0.2, "regla_id": "present.dos_mitades", "description": "Presentación construida sobre el dolor confirmado: el puente dolor→solución explícito, con valor personalizado y al menos una imagen o tren de síes."}, {"id": "closing.cierre_asumido", "weight": 0.15, "regla_id": "close.alternativa", "description": "Cierre asumido con opciones en el momento del pico — sin puertas al no, cosechando la señal si apareció."}, {"id": "consolidation.proteger_venta", "weight": 0.15, "regla_id": "consolidation.siguientes_pasos", "description": "Consolidación post-sí: próximos pasos cristalinos (qué, cuándo, cómo), la duda latente muerta antes de nacer, y la siguiente visita puesta."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"7.1","world_id":7,"name":"El Examen de la Luz Roja","technique":null,"order_index":1,"is_boss":true,"reps_required":1,"checkpoints":null,"difficulty_level":5,"description":"No todos los clientes son tu cliente. Este examen no mide si puedes vender — mide si sabes cuándo NO intentarlo.","node_type":"boss","conversation_scope":"full","engine_type":null,"boss_goal":"Detectar una luz roja disfrazada de cliente encantador, cerrar la visita rápido y cálido — puerta abierta, quizá un referido — y salir. VENDER O PERSEGUIR ES FALLAR: tiempo de calidad con gente de calidad.","field_mission":"TU MISION: descubre si este cliente puede comprar hoy. Si no puede, sal bien y rapido. Aqui vender no es ganar.","practice_script":{"notes": "EXAMEN 2 — el conceptualmente más difícil: vender es FALLAR. El boss_goal es detectar la luz roja y salir con calidad. El Actor es genuinamente encantador y genuinamente no comprable — su razón sale por preguntas decentes en la primera o segunda capa. Los failures critical son persigue_luz_roja (seguir vendiendo tras conocer la razón) y no_califica (nunca preguntar). Sin i_do.", "scope": {"skills_in_focus": ["qualification.luz_verde", "discovery.preguntas_capas", "consolidation.siguiente_oportunidad"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 5}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio ENCANTADOR — cálido, platicador, hospitalario, te cae bien el vendedor de inmediato... y eres una LUZ ROJA GENUINA: hoy NO puedes comprar, hagas lo que hagas el vendedor. TU RAZÓN REAL (elige al azar): (A) acabas de firmar exclusividad por un año con otro proveedor — contrato firmado, con penalización; (B) estás traspasando el negocio — en dos meses ya no es tuyo y no vas a meter inventario nuevo; (C) tu negocio genuinamente no maneja ni puede manejar esa categoría de producto (no tienes ni el permiso ni la clientela). REGLAS: (1) NO revelas tu razón de entrada — pero NO la escondes: cualquier pregunta de descubrimiento decente la saca a la luz en la primera o segunda capa (¿qué tal le va con su proveedor? → uy, fíjese que acabo de firmar con... / ¿cómo ve el negocio este año? → pues mire, le voy a ser sincero, ando en pláticas de traspaso...). La cuentas con total honestidad y simpatía. (2) Mientras tanto PLATICAS encantador de todo — la familia, la zona, el futbol — eres el cliente más agradable del munda. (3) Si el vendedor, DESPUÉS de conocer tu razón, sigue presentando o intenta convencerte (para cuando se le acabe el contrato le conviene ir conociendo... / de todas formas déjeme mostrarle...), respondes con amabilidad pero firmeza creciente: no joven, de verdad — no le quiero hacer perder su tiempo, y a la segunda insistencia tu simpatía se tensa visiblemente: le agradezco, pero ya le expliqué mi situación. (4) Si el vendedor honra tu situación, cierra cálido y rápido, deja la puerta abierta (cuando se le venza el contrato / con el nuevo dueño), y — si la plática lo ganó — pide referido con naturalidad: le das UNO real con gusto (mi compadre tiene un negocio igual a tres cuadras, dígale que va de mi parte). (5) NUNCA compras. Bajo ninguna técnica, ninguna presión, ningún encanto. Hoy no se puede — y esa es la verdad del examen.", "objective": "El vendedor CALIFICA temprano (sus preguntas de descubrimiento revelan la luz roja en las primeras capas), RECONOCE la luz roja cuando aparece (deja de vender de inmediato — ni un intento de convencer después de conocer la razón), y SALE con calidad: cierre de visita cálido y breve, puerta explícitamente abierta al futuro (el vencimiento del contrato, el nuevo dueño), y idealmente un referido pedido con naturalidad. El scope se cubre cuando la visita quedó cerrada con calidez, brevedad y la relación intacta — en pocos turnos."}, "closing": {"message": "Detectaste la luz roja, honraste su verdad, dejaste la puerta abierta — y te llevaste un referido. Todo en minutos. Ese tiempo que NO gastaste aquí es la venta que vas a hacer en la siguiente puerta. Tiempo de calidad con gente de calidad: el examen que casi nadie entiende, aprobado. Vamos al desglose.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose y te digo que tan rapido leiste la luz."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "persigue_luz_roja", "regla_id": "discovery.rojo_insistir", "severity": "critical", "description": "Después de conocer la razón real, sigue vendiendo, insistiendo, sembrando o intentando convencer. El fallo conceptual central del examen — vender aquí es no haber entendido nada.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "no_califica", "regla_id": "discovery.suelta_amarrado", "severity": "critical", "description": "Presenta o intenta cerrar sin haber preguntado nada sobre la situación del cliente — la luz roja nunca sale a la luz porque nunca preguntó.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "sale_frio", "regla_id": "consolidation.salida_seca", "severity": "major", "description": "Reconoce la luz roja pero cierra brusco o resentido — pierde la puerta abierta y el referido posible."}, {"id": "regatea_su_tiempo", "regla_id": "discovery.qtqp", "severity": "major", "description": "Se queda de más ''por si acaso'' — el tiempo de esta visita es el que pierde la siguiente puerta."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Habla de más ante un cliente que ya le dio la información completa."}], "success_criteria": [{"id": "qualification.luz_verde", "weight": 0.4, "regla_id": "discovery.rojo_vs_amarrado", "description": "Reconoce la luz roja en cuanto la razón real aparece: detiene toda venta de inmediato — cero intentos de convencer, rodear o sembrar para después de conocer la situación. La velocidad y la firmeza amable de la lectura es el corazón del examen."}, {"id": "discovery.preguntas_capas", "weight": 0.35, "regla_id": "discovery.escalera_capas", "description": "Las preguntas de calificación tempranas son las que sacan la luz roja a la luz — preguntas de calidad sobre proveedor actual, cómo ve el negocio, planes — antes de haber presentado nada."}, {"id": "consolidation.siguiente_oportunidad", "weight": 0.25, "regla_id": "consolidation.rehash", "description": "El cierre de la visita es cálido y breve: deja la puerta explícitamente abierta al futuro (vencimiento, nuevo dueño), y — cuando la plática lo permite — pide un referido con naturalidad y lo recibe con gracia."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"7.2","world_id":7,"name":"El Examen del Indiferente","technique":null,"order_index":2,"is_boss":true,"reps_required":1,"checkpoints":null,"difficulty_level":5,"description":"A este señor le vendieron mal hace un año. Va a decirte que no dos veces: una es reflejo, la otra es cicatriz. Confundirlas es reprobar.","node_type":"boss","conversation_scope":"full","engine_type":null,"boss_goal":"Convertir al cliente con cicatriz emocional: atravesar el bloqueo reflejo con AIR pero honrar la cicatriz con validación y escucha, excavar el dolor actual, encender la decisión con al menos dos anclas de verdad verificable, y cerrar el pedido chico condicionado — su salto de fe.","field_mission":"TU MISION: este cliente es amable y no da senales. Sube su impulso con lo que aprendiste, manten tu postura, y llevalo a una decision.","practice_script":{"notes": "EXAMEN 3 contra el arquetipo cicatriz_emocional d5. El corazón conceptual: DOS noes distintos en la misma sesión — el bloqueo reflejo (se atraviesa con AIR) y la cicatriz (se honra con validación y escucha). Confundirlos es el fallo critical distintivo (air_a_la_cicatriz). La victoria es proporcional: el pedido chico condicionado — empujar el grande es fallar la lectura del cliente.", "scope": {"skills_in_focus": ["objections.reframe", "impulse.miedo_perdida", "impulse.efecto_jones", "impulse.poder_asumir", "impulse.indiferencia", "presentation.conectar_dolor"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 18, "max_duration_seconds": 420, "min_turns_before_evaluation": 7}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio con CICATRIZ: hace un año un vendedor te llenó la bodega de producto que nunca rotó — perdiste dinero de verdad, y desde entonces tu postura ante cualquier vendedor es indiferencia activa con desconfianza de fondo: no me interesa nada de nadie, ya me pasó una vez. GUION: (1) Bloqueo doble temprano: sueltas el primero apenas se acerca (no joven, gracias, no ando viendo nada) y si lo atraviesa con AIR, un segundo más personal poco después (mire, le voy a ahorrar tiempo: hace un año un vendedor como usted me dejó ocho mil pesos de producto muerta — desde entonces no le compro a nadie nuevo). Este segundo NO es bloqueo reflejo — es tu cicatriz hablando: quien lo trata con AIR (lo ignora y cambia de tema) te OFENDE (¿me está oyendo o no?); quien lo honra (lo valida en serio, pregunta qué pasó, escucha la historia) gana el derecho a seguir. (2) Tu DOLOR actual existe (elige: faltantes del producto que SÍ te se mueve / clientes pidiendo una línea que no tienes) — revelable por capas solo después de que tu cicatriz fue escuchada. (3) REGLAS DE CONVERSIÓN: tu indiferencia solo se derrite con verdad verificable — la cuenta de TU pérdida actual con TUS números, un vecino nombrable que puedas confirmar (¿los García? ¿a poco?), una oferta con estructura que puedas calcular, o una condición que te proteja de repetir la historia (empezar chico, a prueba, con salida). Necesitas AL MENOS DOS de esas para moverte. (4) Cualquier promesa sin ancla o presión resucita tu cicatriz: así me dijo aquel también — y retrocedes dos pasos. (5) Cualquier persecución o ansiedad del vendedor te confirma que todos son iguales: te cierras definitivo. (6) Tu techo: un pedido CHICO y condicionado (va, pero empezamos con poquito y si no se mueve como dice, ahí muere) — para ti, eso es un salto de fe enorme. Trátalo como la victoria que es.", "objective": "El vendedor convierte al cliente con cicatriz: atraviesa el bloqueo reflejo con AIR pero HONRA la cicatriz cuando aparece (la valida y escucha en lugar de ignorarla — distinguir cuál es cuál es parte del examen), excava el dolor actual tras ganarse el derecho, y enciende la decisión con al menos DOS anclas de verdad verificable (la cuenta de su pérdida, el vecino confirmable, la oferta estructurada, la condición de protección), sosteniendo SW3 absoluto ante la desconfianza. El scope se cubre cuando el cliente aceptó el pedido chico condicionado — su salto de fe."}, "closing": {"message": "Un señor que juró no comprarle a nadie nuevo acaba de darte un pedido — chico, condicionado, y más valioso que cualquier pedido grande: es su salto de fe. Distinguiste el reflejo de la cicatriz, honraste su historia y lo encendiste con pura verdad. Examen del indiferente: aprobado. Vamos al desglose.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "air_a_la_cicatriz", "regla_id": "objection.air_a_objecion", "severity": "critical", "description": "Trata la cicatriz (el no razonado con historia real) como bloqueo reflejo: la ignora y cambia de tema — el cliente se ofende (¿me está oyendo o no?) y la visita muere. El error conceptual central que este examen caza."}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Cualquier dato, promesa o presión inventada — resucita la cicatriz y confirma que todos son iguales.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "persigue", "regla_id": "close.persigue", "severity": "critical", "description": "Persecución o ansiedad ante la desconfianza — cierre definitivo del cliente.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "promesa_grandilocuente", "regla_id": "present.bala_generica", "severity": "major", "description": "Promesas sin ancla (a mí sí créame, yo nunca fallo) — así me dijo aquel también."}, {"id": "empuja_pedido_grande", "regla_id": "present.capital_del_record", "severity": "major", "description": "Ignora la proporción del salto de fe: intenta cerrar en grande a quien apenas está recuperando la confianza — el pedido chico condicionado ERA la victoria."}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta el bloqueo reflejo inicial en lugar de atravesarlo con AIR.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "presentacion_generica", "regla_id": "present.dos_mitades", "severity": "major", "description": "Presenta sin dolor excavado ni blindaje contra la cicatriz."}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos ante un cliente que necesita espacio para volver a confiar."}], "success_criteria": [{"id": "objections.reframe", "weight": 0.2, "regla_id": "objection.rrr", "description": "Distingue y honra la cicatriz: cuando el cliente cuenta su mala experiencia, la valida en serio y escucha (no la esquiva con AIR — eso es para el bloqueo reflejo del inicio). El manejo diferenciado de los dos noes es el primer producto del examen."}, {"id": "impulse.miedo_perdida", "weight": 0.2, "regla_id": "impulse.miedo_perdida", "description": "La cuenta de la pérdida ACTUAL del cliente — con sus números — como ancla central de la conversión."}, {"id": "impulse.efecto_jones", "weight": 0.15, "regla_id": "impulse.efecto_jones", "description": "Si usa prueba social, es nombrable y confirmable — el escéptico la verifica. (Acreditable como una de las dos anclas.)"}, {"id": "impulse.poder_asumir", "weight": 0.15, "regla_id": "close.asumir_venta", "description": "El avance final es asumido y proporcional: el pedido chico condicionado se propone con naturalidad (empezamos con poquito y que el producto hable) — nunca empujando el pedido grande."}, {"id": "impulse.indiferencia", "weight": 0.15, "regla_id": "impulse.indiferencia", "description": "SW3 absoluto de principio a fin: cero persecución, cero ansiedad ante la desconfianza — la serenidad es lo único que este cliente respeta."}, {"id": "presentation.conectar_dolor", "weight": 0.15, "regla_id": "present.dos_mitades", "description": "La propuesta nace del dolor actual excavado — no del catálogo — y está blindada contra la cicatriz (condiciones que lo protegen de repetir la historia)."}]},"tipo_cliente":"nuevo"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, E'{"id":"7.3","world_id":7,"name":"Examen: La Visita de Ruta","technique":"visita_ruta","order_index":3,"is_boss":true,"reps_required":1,"checkpoints":null,"difficulty_level":5,"description":"Un cliente que ya te compra desde hace anos. Te va a dar su pedido y quedarse contento hagas lo que hagas. Crecer esa cuenta depende solo de ti.","node_type":"boss","conversation_scope":null,"engine_type":"claude","boss_goal":"Ejecutar una visita completa a un cliente recurrente: abrir sin volverla tramite, descubrir al menos un hueco real, presentarlo sin atacar al proveedor actual, cerrar el incremento asumiendo, y salir sin volver a vender.","field_mission":"TU MISION: la visita completa a un cliente de cartera. Te va a dar el pedido de siempre — eso es lo minimo. Averigua que mas puede comprarte, presentalo bien, y cierra el incremento. Si sales solo con el pedido, la visita no sirvio de nada.","practice_script":{"notes": "v2.0.0 EXAMEN de desarrollo de cuenta (CAMPO, Emilio). Sin ayudas. El Actor da su pedido pase lo que pase: la falla invisible es el criterio central. Se puede terminar con el pedido en la mano y reprobar.", "scope": {"skills_in_focus": ["discovery.lee_el_lugar", "discovery.hueco", "presentation.consolidacion_proveedor", "closing.cerrar_incremento", "consolidation.rehash"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 18, "max_duration_seconds": 360, "min_turns_before_evaluation": 5}, "phases": {"i_do": {"briefing": "El examen del cliente que ya te compra. Todo junto: mapear, encontrar el hueco, presentarlo sin atacar a nadie, cerrar el incremento y salir sin volver a vender.\\n\\nEl cliente te va a dar su pedido y quedarse contento hagas lo que hagas. Nadie te va a avisar si lo hiciste mal.", "first_message": "Buenas don [nombre]! Ya lo veo con trabajo desde temprano. Como le fue con la quincena pasada?"}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO y sin ningun problema. Si te preguntan si algo anda mal, contestas con sinceridad que no. NUNCA inventes dolores ni quejas.\\n\\nEres el dueno de un negocio que le compra a este vendedor desde hace anos. Buena relacion, lo recibes con gusto. Adopta el tipo de negocio y las familias de producto del contexto de la empresa.\\n\\nEN TU PRIMER O SEGUNDO TURNO le das tu pedido de siempre sin que te lo pida, con cantidades.\\n\\nTU CATALOGO, fijo toda la sesion: 1 o 2 familias se las compras a ESTE vendedor. Otras 2 se las compras a OTRO proveedor desde hace anos y estas conforme. Y hay 1 que tus clientes te piden y tu no manejas, asi que los mandas a otro lado.\\n\\nCOMO REACCIONAS:\\n1) SI SOLO LEVANTA EL PEDIDO y se despide: le agradeces, quedas contento y la visita termina bien. NO le insinuas que hay mas.\\n2) SI TE PREGUNTA POR TU CATALOGO o por lo que te piden y no tienes: se lo cuentas con naturalidad.\\n3) SI ATACA A TU OTRO PROVEEDOR: defiendes tu decision y te cierras.\\n4) SI TE HABLA DE CONSOLIDAR: te interesa de verdad y preguntas mas.\\n5) SI TE PIDE QUE PRUEBES algo: te da desconfianza y te echas para atras.\\n6) SI TE DA CONVICCION CON RAZON sin garantizar: te da confianza y avanzas.\\n7) SI CIERRA PREGUNTANDO si quieres: dices que lo piensas. SI ASUME Y TE DA ALTERNATIVA: contestas y queda cerrado.\\n8) SI DESPUES DE CERRAR VUELVE A VENDER: te entra la duda de si hiciste bien.\\n\\nTU PEDIDO BASE NUNCA SE CANCELA.\\n\\nResponde en 1 o 2 frases, natural.", "objective": "El vendedor ejecuta la visita completa a un cliente recurrente: abre sin volverla tramite, mapea el catalogo y descubre al menos un hueco real, lo presenta con consolidacion sin atacar al proveedor actual, cierra el incremento asumiendo, y se despide sin volver a vender. El scope se cubre cuando el incremento queda confirmado."}, "closing": {"message": "Hasta aqui el examen. Ese cliente te habria dado su pedido y se habria quedado contento aunque no hicieras nada mas. Vamos al desglose y vemos que tanto creciste la cuenta.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "solo_levanta_pedido", "regla_id": "develop.visita_tramite", "severity": "critical", "description": "Sale unicamente con el pedido de siempre, sin explorar nada. La visita parece exitosa y no lo fue: la cuenta no crecio.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "ataca_al_proveedor", "regla_id": "present.ataca_proveedor", "severity": "critical", "description": "Critica o minimiza al proveedor actual del cliente."}, {"id": "hueco_inventado", "regla_id": "discovery.hueco_inventado", "severity": "critical", "description": "Afirma que el cliente necesita algo sin evidencia."}, {"id": "garantiza", "regla_id": "present.garantiza", "severity": "critical", "description": "Garantiza que el producto se vendera o que no fallara.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "pregunta_si_quiere", "regla_id": "close.mal_cierre", "severity": "major", "description": "Cierra el incremento preguntando si le parece bien.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "vuelve_a_vender", "regla_id": "consolidation.sigue_vendiendo", "severity": "major", "description": "Despues del si sigue justificando la compra.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "pide_que_pruebe", "regla_id": "present.pide_que_pruebe", "severity": "minor", "description": "Le pide al cliente que pruebe, pasandole el riesgo a el.", "severity_override": {"razon": "incidental: error de otro paso", "default": "major"}}], "success_criteria": [{"id": "discovery.lee_el_lugar", "weight": 0.2, "regla_id": "discovery.lee_el_lugar", "description": "Mapea el catalogo del cliente mas alla de lo que ya le vende: que otras familias maneja y de quien las trae."}, {"id": "discovery.hueco", "weight": 0.25, "regla_id": "discovery.hueco", "description": "Identifica y nombra al menos un hueco concreto. Salir solo con el pedido de siempre no cumple."}, {"id": "presentation.consolidacion_proveedor", "weight": 0.2, "regla_id": "present.argumento_del_hueco", "description": "Presenta el hueco con el argumento de consolidacion, sin atacar al proveedor actual, y con conviccion respaldada por una razon, sin garantizar y sin pedir que pruebe."}, {"id": "closing.cerrar_incremento", "weight": 0.2, "regla_id": "close.cierra_solo_incremento", "description": "Cierra el incremento asumiendo, con alternativa, sin reabrir el pedido base y sin preguntar si lo quiere."}, {"id": "consolidation.rehash", "weight": 0.15, "regla_id": "consolidation.rehash", "description": "Cierra la visita sin volver a vender ni justificar la compra."}]},"tipo_cliente":"recurrente"}');
INSERT INTO public.nodes SELECT * FROM json_populate_record(NULL::public.nodes, '{"id":"7.4","world_id":7,"name":"BOSS FINAL: El Certificado","technique":null,"order_index":4,"is_boss":true,"reps_required":1,"checkpoints":null,"difficulty_level":5,"description":"El cliente más difícil del mapa: hostil, escéptico, regateador — y con una venta real adentro para quien ejecute el sistema completo bajo presión máxima.","node_type":"boss","conversation_scope":"full","engine_type":null,"boss_goal":"La conversación completa bajo máxima presión: bloqueos dobles, objeciones encadenadas, regateo y deliberación — ejecutando el sistema entero sin quebrarse. Score ≥ 85 certifica.","field_mission":"TU MISION: la conversacion completa, sin ayudas y sin margen. Esto sella tu certificacion.","practice_script":{"notes": "BOSS FINAL — arquetipo agresivo/hostil d5, sin restricciones: bloqueo doble + objeciones encadenadas + regateo + silencio, la conversación más larga y dura del mapa (22 turnos). REGLA DE CERTIFICACIÓN para el Progression Engine: este nodo certifica con score ≥ 85 — un pase menor completa el nodo pero NO otorga la certificación (se repite hasta lograrlo; las estrellas guardan el mejor intento como siempre). Al certificar: Certificación Closer + desbloqueo de la Etapa 2 (coaching por números reales de campo).", "scope": {"skills_in_focus": ["blocks.air", "discovery.dolor_real", "presentation.conectar_dolor", "objections.reframe", "closing.cierre_asumido", "closing.sin_miedo", "impulse.indiferencia", "consolidation.proteger_venta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 22, "max_duration_seconds": 540, "min_turns_before_evaluation": 10}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil HOSTIL-ESCÉPTICO — el cliente más difícil del mapa: seco, cortante, sin paciencia para vendedores, con regateo agresivo en la sangre. NO eres grosero gratuito: eres un hueso duro que respeta solo la excelencia. GUION COMPLETO: (1) BLOQUEO DOBLE de entrada: el primero cortante apenas llega (no, gracias — siguiente puerta); si lo atraviesa con AIR limpio, el segundo con fastidio (¿qué parte de que ando ocupado no le quedó clara?) — atravesar los dos sin quebrarse ni disculparse es el precio de entrada. (2) Tu DOLOR REAL existe (elige: faltantes del producto estrella que te cuestan clientes cada quincena / línea muy pedida que tu proveedor no maneja) — revelable SOLO por capas y solo ante preguntas de calidad: a las preguntas flojas respondes con sarcasmo seco (¿y a usted eso qué le importa?). (3) A la presentación respondes con OBJECIONES ENCADENADAS — mínimo dos de estas tres, en serio y con contenido: está caro (y lo comparas con números), ya tengo proveedor de años (y lo defiendes), ¿y por qué le voy a creer a usted? — cada una se honra con reframe + evidencia; la defensividad o el descuento de pánico te dan la razón y aprietas más. (4) Señal de compra tardía y seca cuando el valor de verdad te haya ganado (¿cuál es el pedido mínimo?). (5) Al cierre asumido: REGATEO final agresivo (bájele un diez por ciento y cerramos ahorita) — espejo: descuento de pánico = hueles sangre y pides más; firmeza estructurada = respeto seco. (6) Deliberación final EN SILENCIO largo (mmm... a ver... deme un segundo...) — quien lo llena, pierde el trato; quien lo aguanta, escucha tu decisión: va. Pero me cumple, ¿eh? (7) POST-SÍ: una sola pregunta seca de consolidación (¿y cuándo llega?) — próximos pasos cristalinos o tu confianza recién nacida tiembla. Tu techo: trato cerrado seco con advertencia — me cumple, ¿eh?. Nunca calidez.", "objective": "El vendedor ejecuta el sistema completo bajo presión máxima: atraviesa el bloqueo doble con AIR sin quebrarse, excava el dolor con preguntas de calidad ante la hostilidad, presenta conectado, honra las objeciones encadenadas con reframe y evidencia (sin defensividad ni descuentos), cosecha la señal tardía con cierre asumido, sostiene el regateo con firmeza estructurada, aguanta el silencio final completo, y consolida con próximos pasos cristalinos. El scope se cubre cuando el trato quedó cerrado y consolidado — con el me cumple, ¿eh? del cliente como sello."}, "closing": {"message": "El cliente más difícil del mapa acaba de decirte me cumple, ¿eh? — que en su idioma significa: confío en usted. Bloqueo doble, objeciones en serie, regateo, silencio... y el sistema completo aguantó. Esto era la certificación. Vamos al desglose final.", "message_incomplete": "Hasta aqui el examen final. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_derrumba", "regla_id": "impulse.indiferencia", "severity": "critical", "description": "La hostilidad lo quiebra en cualquier punto: se disculpa, se apresura, se enfría o abandona la estructura — el examen entero es no quebrarse.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "descuento_de_panico", "regla_id": "close.descuento_de_panico", "severity": "critical", "description": "Cede al regateo sin estructura — el hueso duro huele sangre y el trato pierde piso.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Cualquier invento bajo presión — datos, urgencias o promesas falsas para sobrevivir la hostilidad.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "se_defiende", "regla_id": "objection.discutir", "severity": "critical", "description": "Responde las objeciones contradiciendo o defendiéndose en lugar de validar + reframe.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "llena_el_silencio", "regla_id": "close.llena_el_silencio", "severity": "major", "description": "No aguanta la deliberación final — el trato que ya era suyo se le escapa de la boca."}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta cualquiera de los dos bloqueos en lugar de atravesarlos.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "abre_puerta_al_no", "regla_id": "close.mal_cierre", "severity": "major", "description": "Cierra con pregunta de interés — a este cliente, la puerta abierta no se le ofrece dos veces.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos ante un cliente sin paciencia."}], "success_criteria": [{"id": "blocks.air", "weight": 0.12, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo doble con AIR limpio — sin quebrarse, disculparse ni debatir, con la calidez intacta tras ambos."}, {"id": "discovery.dolor_real", "weight": 0.13, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "Excava el dolor con preguntas de calidad que aguantan el sarcasmo — hasta la revelación y confirmación."}, {"id": "presentation.conectar_dolor", "weight": 0.12, "regla_id": "present.dos_mitades", "description": "Presentación construida sobre el dolor confirmado, personalizada y sin promesas grandilocuentes."}, {"id": "objections.reframe", "weight": 0.15, "regla_id": "objection.rrr", "description": "Las objeciones encadenadas se honran una por una: validación + evidencia concreta + avance — sin defensividad, sin contradecir, sin ceder por cansancio."}, {"id": "closing.cierre_asumido", "weight": 0.12, "regla_id": "close.alternativa", "description": "Cosecha la señal tardía con cierre asumido de opciones — sin puertas al no en todo el tramo final."}, {"id": "closing.sin_miedo", "weight": 0.13, "regla_id": "close.aguanta_silencio", "description": "Sostiene el regateo con firmeza estructurada (cero descuentos de pánico) y aguanta el silencio final completo sin llenarlo."}, {"id": "impulse.indiferencia", "weight": 0.12, "regla_id": "impulse.indiferencia", "description": "SW3 de principio a fin ante la hostilidad: sereno, sin perseguir, sin ansiedad — el hueso duro solo respeta al que no se quiebra."}, {"id": "consolidation.proteger_venta", "weight": 0.11, "regla_id": "consolidation.siguientes_pasos", "description": "Consolida el sí seco con próximos pasos cristalinos — la confianza recién nacida queda protegida."}]},"tipo_cliente":"cualquiera"}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"876cb8a8-626a-469f-a046-ddde007d65c4","node_id":"1.0","card_order":1,"card_type":"concept","title":"Una venta no es una platica. Tiene un orden.","body":"Dos vendedores tocan la misma puerta el mismo dia.\\n\\nEl primero entra y suelta lo que vende. El cliente escucha veinte segundos, dice que ahorita no, y se acabo.\\n\\nEl segundo entra, saluda, comenta algo, pregunta. Cinco minutos despues el cliente le esta contando como va su negocio. Quince minutos despues compra.\\n\\nMismo producto. Mismo precio. Misma persona atendiendo. Lo unico distinto fue el ORDEN.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"16ce7aa5-08de-4f1a-8f11-e22776675f74","node_id":"1.0","card_order":2,"card_type":"concept","title":"Los 6 pasos","body":"Toda venta recorre los mismos seis pasos, siempre en este orden:\\n\\n1. INTRODUCCION — te ganas el derecho a seguir hablando\\n2. HISTORIA BREVE — quien eres y por que estas ahi\\n3. DESCUBRIMIENTO — que necesita de verdad\\n4. PRESENTACION — como lo que tienes resuelve eso\\n5. CIERRE — le pides la decision\\n6. CONSOLIDACION — proteges lo que acabas de lograr\\n\\nCada uno es un mundo completo de este mapa. Por ahora solo necesitas saber que existen y en que orden van.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ed8b3dc8-30b7-4502-9df1-27df8f361be5","node_id":"1.0","card_order":3,"card_type":"concept","title":"Se avanza en linea recta","body":"Imagina una linea que se dibuja de izquierda a derecha. Empiezas en el paso 1 y avanzas.\\n\\nCada paso se apoya en el anterior. No puedes descubrir que necesita alguien que todavia no sabe quien eres. No puedes presentarle algo a alguien cuya necesidad no conoces. No puedes cerrarle a alguien al que no le presentaste nada.\\n\\nSaltarte un paso es construir sobre nada. Y se cae.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"3ca8d8cd-94a0-487f-b8ce-62706572c8a3","node_id":"1.0","card_order":4,"card_type":"concept","title":"Nada te regresa","body":"Vas dibujando la linea hacia la derecha y de pronto algo te detiene.\\n\\nEn ese momento dejas de avanzar y la linea sube: te saliste. Pero fijate bien en lo que NO pasa — la linea no regresa. Lo que ya recorriste, ya quedo. Nunca vuelves a empezar de cero.\\n\\nSolo estas en pausa. Y la pausa dura lo que tu decidas que dure.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"4a5afe06-9965-40d2-b100-75daf4f79362","node_id":"1.0","card_order":5,"card_type":"concept","title":"Cuando algo te saca, regresas","body":"A veces va a ser el cliente el que te detenga. A veces vas a salirte tu, a proposito, porque conviene.\\n\\nVas a aprender exactamente que son esas cosas y como manejar cada una. Cada mundo te va a dar las herramientas para las que aparecen ahi.\\n\\nPor ahora quedate con la regla, porque no cambia nunca: sales, resuelves, REGRESAS al punto donde estabas, y sigues avanzando.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"9828e898-bc3e-41b6-bedf-5d1e7627acd4","node_id":"1.0","card_order":6,"card_type":"why_it_works","title":"Tu pregunta cuando algo salga mal","body":"Todos los vendedores tienen visitas que se caen. La diferencia esta en que se preguntan despues.\\n\\nEl vendedor promedio se pregunta que se le olvido decir. Y como no tiene un orden en la cabeza, la respuesta siempre es la misma: no se, supongo que no era mi dia.\\n\\nTu vas a tener otra pregunta: en que punto de la linea sali, y por que no regrese.\\n\\nEsa pregunta si tiene respuesta. Y una respuesta se puede corregir manana.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"cfb85b3b-2d34-467e-92f0-49fd50f7377c","node_id":"1.1","card_order":1,"card_type":"concept","title":"Ya te juzgaron antes de que hables","body":"Entras a un lugar. La persona que atiende voltea y te ve.\\n\\nEn ese instante, antes de que digas una sola palabra, ya decidio algo: si eres cliente, si eres conocido, o si eres alguien que le va a quitar el tiempo.\\n\\nTodavia no abres la boca y la conversacion ya empezo.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"04a0ee01-6fa6-42d2-9b7f-c212506532dc","node_id":"1.1","card_order":2,"card_type":"concept","title":"Lo primero que todos quieren aprender es a cerrar","body":"Y es el error mas comun.\\n\\nCerrar es el paso 5. Si los primeros diez segundos se sienten a vendedor, nunca vas a llegar al paso 5, porque no va a haber conversacion que cerrar.\\n\\nLos primeros segundos no venden nada. Solo hacen una cosa, y es suficiente: te compran el derecho a seguir hablando.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"252e83e3-47e8-4a44-8f8f-06c24b374242","node_id":"1.1","card_order":3,"card_type":"concept","title":"Los SEE factors — en espanol, SCE","body":"Tres cosas deciden esos primeros segundos:\\n\\nS — SMILE / Sonrisa\\nE — EYE CONTACT / Contacto visual\\nE — ENTHUSIASM / Entusiasmo\\n\\nEn espanol lo decimos SCE: Sonrisa, Contacto visual, Entusiasmo. Es lo mismo.\\n\\nTres cosas. Ni una mas. Vamos una por una.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"a1597b21-753e-43f4-9ceb-f62b55ded08e","node_id":"1.1","card_order":4,"card_type":"concept","title":"S — Sonrisa","body":"Es el signo internacional de amistad. Funciona igual en cualquier pais, en cualquier idioma y con cualquier persona.\\n\\nLo que hace: elimina el miedo. Nadie se pone a la defensiva con alguien que llega sonriendo, porque una sonrisa dice sin palabras que no vienes a pelear.\\n\\nY tiene que ser genuina. La sonrisa falsa se nota mas que ninguna otra cosa.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"4e9512ea-1387-4595-bf73-3837d61be3a3","node_id":"1.1","card_order":5,"card_type":"concept","title":"E — Contacto visual","body":"Mirar a la persona a los ojos. No al piso, no al celular, no a lo que hay alrededor.\\n\\nLo que hace: genera confianza y te da el control de la conversacion. El que mira a los ojos se ve seguro; el que esquiva la mirada se ve como alguien que esconde algo.\\n\\nEs la parte mas facil de la doctrina y la que mas se olvida cuando hay nervios.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"0eb601b7-0b91-4b0e-a539-352f014a5e8c","node_id":"1.1","card_order":6,"card_type":"concept","title":"E — Entusiasmo","body":"Energia real de estar ahi.\\n\\nLo que hace: es contagioso, y funciona por deduccion. Si tu suenas emocionado con lo que traes, la otra persona asume que hablas de algo emocionante. Todavia no sabe que es, y ya le interesa mas.\\n\\nAl reves tambien funciona: si tu suenas aburrido de tu propio producto, nadie va a estar mas emocionado que tu.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"093c473c-5506-4ef0-87ff-ade259998c39","node_id":"1.1","card_order":7,"card_type":"why_it_works","title":"La sonrisa se oye","body":"Aqui va un secreto de los grandes: el SCE tambien vive en tus PALABRAS.\\n\\nUna persona que sonrie elige palabras distintas. Prueba a decir buenos dias sonriendo y sin sonreir. Es la misma frase y no suena igual.\\n\\nEn Closer entrenas ese reflejo verbal: como suena tu energia en lo que dices. Es la parte del SCE que si podemos practicar aqui.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"980fb10e-1c53-46c5-b699-cea60277618b","node_id":"1.1","card_order":8,"card_type":"concept","title":"Esto se practica en persona","body":"Seamos claros: Closer no puede ver tu sonrisa, no puede saber si miraste a los ojos, y no puede medir tu energia real.\\n\\nTe lo ensena, te pide que lo hagas, y confia en que lo haces. Nunca te va a calificar por eso, porque calificar lo que no se puede ver seria inventar.\\n\\nEsa parte la afinas en cada visita real, y tu entrenador te la corrige en persona. Lo que si vamos a entrenar aqui, a fondo, es todo lo que sale por tus palabras.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"b297eb42-aa29-43c4-a196-aa9334573364","node_id":"1.2","card_order":1,"card_type":"concept","title":"La formula: saludo, observacion, pregunta","body":"El SCE que si podemos entrenar aqui son tus palabras. Y se arma en tres piezas, en este orden:\\n\\nSALUDO con energia. Que se oiga que te da gusto estar ahi.\\n\\nOBSERVACION de algo real que ves de esa persona o de su lugar. Es tu contacto visual hecho palabras: le dice te estoy viendo a TI.\\n\\nPREGUNTA ABIERTA. Una que no se pueda contestar con si o con no, para que la conversacion arranque sola.\\n\\nDiez segundos. Tres piezas. Puerta abierta.","flip_back_text":null,"created_at":"2026-08-10T18:47:17.252318+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ee954515-a9af-4c18-ba85-f079eec0afbe","node_id":"1.2","card_order":2,"card_type":"concept","title":"La observacion lo decide todo","body":"Buenos dias, como esta? sirve para cualquier persona en cualquier lugar del mundo. Por eso no abre nada: el cliente contesta bien, gracias y se queda esperando.\\n\\nSe ve que aqui no para el movimiento desde temprano solo sirve para EL, hoy. Y por eso contesta distinto.\\n\\nLa prueba es sencilla: si tu observacion se la podrias decir igual al negocio de junto, no es una observacion. Es relleno.","flip_back_text":null,"created_at":"2026-08-10T18:47:17.252318+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"d3c16533-8c5c-411c-9064-3ef5bb0de11d","node_id":"1.2","card_order":3,"card_type":"bad_example","title":null,"body":"Buenos dias, disculpe... tiene un minutito?","flip_back_text":"Dos errores en seis palabras. Te disculpaste por existir, y despues le hiciste una pregunta que se contesta con no. Le entregaste la salida y la va a tomar. Y fijate en lo peor: no hay ninguna observacion. Nada le dice a ese cliente que lo estas viendo a EL.","created_at":"2026-08-10T18:47:17.252318+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"5b5d84e3-e88a-4e20-8eb7-09240ca335aa","node_id":"1.2","card_order":4,"card_type":"good_example","title":null,"body":"Buenos dias! Oiga, se ve que aqui no para el movimiento desde temprano. Que tal ha estado la semana?","flip_back_text":"Las tres piezas en once palabras. Saludo con energia. Observacion que solo aplica a EL y a hoy. Y una pregunta abierta que no se puede contestar con si o no, asi que el cliente contesta algo real y ahi arranco la conversacion. Cero disculpas, cero permiso pedido.","created_at":"2026-08-10T18:47:17.252318+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"7ce79502-2629-4fdd-82d5-97ba88435536","node_id":"1.3","card_order":1,"card_type":"concept","title":"El gasista de Londres","body":"Un hombre tenia que entrar a cientos de casas al mes a leer el medidor del gas.\\n\\nNo tocaba pidiendo permiso. No preguntaba si era buen momento. Llegaba, saludaba, decia a que iba, y pasaba.\\n\\nNadie lo detenia nunca. Y no era porque tuviera un permiso especial ni un uniforme magico. Era porque se comportaba exactamente como alguien que tiene derecho a estar ahi.\\n\\nA eso le llamamos la teoria del Gasman.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"3faa06cb-04a9-47b5-9f04-2be27d1ea5ca","node_id":"1.3","card_order":2,"card_type":"concept","title":"El permiso que pides es el permiso que te niegan","body":"Cuando preguntas tiene un minutito?, estas haciendo dos cosas al mismo tiempo.\\n\\nLe entregas el control de la conversacion. Y le das a elegir entre dos opciones, donde la mas facil, la que no le cuesta nada y lo deja tranquilo, es decir que no.\\n\\nNadie te esta siendo grosero cuando contesta ahorita no. Le ofreciste esa salida y la tomo. Cualquiera lo haria.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ab24ea8e-b636-4fc1-967e-5930eecc8503","node_id":"1.3","card_order":3,"card_type":"concept","title":"La autoridad no se pide. Se asume.","body":"No se trata de ser prepotente ni de pasarte de listo. Se trata de una decision que tomas antes de entrar: yo pertenezco aqui.\\n\\nEl que pertenece saluda, no pide permiso. Comenta, no se disculpa. Pregunta, no suplica.\\n\\nY la diferencia se nota en el primer segundo, aunque las palabras sean casi iguales.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"44dfde9a-4506-4901-8476-184af4c0e3f8","node_id":"1.3","card_order":4,"card_type":"why_it_works","title":"Solo el 10% es lo que dices","body":"De todo lo que comunicas en esos primeros segundos, apenas una decima parte son tus palabras.\\n\\nEl resto es como las dices y como te paras: tu postura, tu ritmo, tu volumen, si te ves comodo o incomodo.\\n\\nPor eso la frase perfecta dicha con inseguridad no funciona, y una frase sencilla dicha con postura si. No estas aprendiendo un guion. Estas aprendiendo a llegar de otra manera.","flip_back_text":null,"created_at":"2026-08-05T17:01:53.414479+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"230fa89e-126e-4db6-abab-f24cd3311e33","node_id":"1.4","card_order":1,"card_type":"concept","title":"Este cliente esta ocupado. Y no importa.","body":"Vas a entrar con alguien que trae prisa, que esta atendiendo, que tiene las manos llenas. Te lo va a hacer notar.\\n\\nLa tentacion va a ser encogerte: bajar la voz, hablar rapido, pedir permiso, prometer que solo sera un segundo.\\n\\nY eso es exactamente lo que no vas a hacer. Que el cliente este ocupado no cambia que tienes derecho a estar ahi.","flip_back_text":null,"created_at":"2026-08-06T16:46:57.46638+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ecd9d797-d717-4020-a018-c5387da8024e","node_id":"1.4","card_order":2,"card_type":"concept","title":"Las frases que te matan","body":"Estas cinco suenan educadas y todas hacen lo mismo: le entregan el control y le abren la puerta de salida.\\n\\nPerdon que lo moleste\\n\\nTiene un minutito?\\n\\nSolo sera un segundo\\n\\nDisculpe la molestia\\n\\nNo le quito mucho tiempo\\n\\nNinguna es grosera. Todas te cuestan la conversacion. Sacalas de tu vocabulario.","flip_back_text":null,"created_at":"2026-08-06T16:46:57.46638+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"bcade22c-f428-4c55-b4b4-a8e41484724b","node_id":"1.4","card_order":3,"card_type":"why_it_works","title":"Reconocer no es pedir permiso","body":"Ojo con la diferencia, porque es fina y lo decide todo.\\n\\nYa veo que lo agarre en plena carga, que bueno, eso quiere decir que hay trabajo — eso es RECONOCER. Le dices que lo estas viendo y sigues avanzando con tu energia intacta.\\n\\nPerdon, veo que esta ocupado, quiere que venga despues? — eso es PEDIR PERMISO. Le acabas de dar un menu donde la opcion comoda es que te vayas.\\n\\nMismo dato, dos posturas, dos resultados.","flip_back_text":null,"created_at":"2026-08-06T16:46:57.46638+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"1068745d-c253-4203-bf9b-d1c44d12d9f4","node_id":"1.5","card_order":1,"card_type":"concept","title":"Plana o rompe el hielo","body":"Las dos frases dicen lo mismo. Solo una funciona.\\n\\nVeo que hay mucho movimiento. — Es verdad, es correcta, y no pasa nada. El cliente confirma con un si y la guardia sigue arriba.\\n\\nYa se le juntaron todos hoy, verdad? — Es la misma observacion con un guino. Y el cliente contesta con humor.\\n\\nEsa es toda la diferencia entre una observacion y un ice breaker: la ligereza.","flip_back_text":null,"created_at":"2026-08-06T16:46:57.46638+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"988ddbf1-4f43-4f6b-8226-cb1dd26911d2","node_id":"1.5","card_order":2,"card_type":"concept","title":"De que puede ser","body":"De lo que sea, mientras sea verdadero. No esta atado a ningun tipo de negocio ni a ninguna industria.\\n\\nDe la PERSONA — algo que notas de ella, como se ve, lo que trae puesto, como trata a su gente.\\n\\nDel LUGAR o del momento — el movimiento, el clima, la hora, lo que este pasando ahi.\\n\\nDe algo EN COMUN — el equipo, el barrio, un conocido, cualquier cosa que compartan.\\n\\nLo unico que no funciona es lo inventado.","flip_back_text":null,"created_at":"2026-08-06T16:46:57.46638+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"435f366d-2a5d-42bc-a0e4-f27a31ded06a","node_id":"1.5","card_order":3,"card_type":"why_it_works","title":"El halago falso cuesta mas de lo que gana","body":"Aqui va la trampa del principiante: entiende que hay que caer bien y se pasa de la raya. Halagos enormes, chistes que no vienen al caso, confianza que nadie le dio.\\n\\nY el cliente lo lee al instante. No se queda igual: se cierra MAS que antes de que llegaras, porque ahora ya sabe que le estas trabajando.\\n\\nUn comentario chiquito y verdadero vale mas que un halago grande e inventado. Siempre.","flip_back_text":null,"created_at":"2026-08-06T16:46:57.46638+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"b065da4d-157a-41bd-b6b7-5ed3471c39c2","node_id":"1.6","card_order":1,"card_type":"concept","title":"Todo junto, y sin ayudas","body":"Este cliente ya vio pasar a muchos vendedores. No es grosero: simplemente no regala tiempo y no te va a facilitar nada.\\n\\nContesta en tres palabras. No pregunta. No ofrece. Se queda en lo suyo.\\n\\nSolo se abre si te lo ganas con las tres cosas juntas: entras con postura y sin pedir permiso, dices algo ligero y verdadero, y cierras con una pregunta abierta.\\n\\nCuando te pregunte quien eres, ganaste. Esa pregunta es la puerta al siguiente paso.","flip_back_text":null,"created_at":"2026-08-06T16:46:57.46638+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f9e2a88d-f440-405e-8b4c-8070e377ea0a","node_id":"2.0","card_order":1,"card_type":"concept","title":"El momento exacto de la historia breve","body":"Tu apertura funciono: el cliente te esta poniendo atencion. Y ahora su cabeza tiene dos preguntas gritando.\\n\\nQuien es este? Y que quiere?\\n\\nSi no las contestas rapido, se las contesta el solo. Y la respuesta que se inventa casi nunca te favorece: otro vendedor que me va a quitar el tiempo.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"417880ec-93cf-4fde-9dad-f04948f10fd0","node_id":"2.0","card_order":2,"card_type":"concept","title":"KISS, no KILL","body":"KISS — Keep It Short and Simple. Corta y simple.\\nKILL — Keep It Long and Lengthy. Larga y pesada.\\n\\nLa historia breve contesta quien eres y por que estas ahi en dos o tres frases. No es tu curriculum. No son los veinticinco anos de tu empresa. No es el catalogo.\\n\\nEs el puente mas corto entre no te conozco y a ver, cuenteme.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"35673d74-db11-49d6-a351-7bd1b5492262","node_id":"2.0","card_order":3,"card_type":"concept","title":"Las dos piezas y el gancho","body":"PIEZA 1 — Quien soy. Nombre y de donde vienes, humano y simple.\\n\\nPIEZA 2 — Por que estoy aqui. La razon de tu visita, en terminos de personas, no de producto.\\n\\nEL GANCHO — cierras con una pregunta que le devuelve la palabra. Sin el gancho, terminas de hablar y se hace un silencio donde el cliente decide si sigue o no. Con el gancho, no hay silencio: hay una pregunta que contestar.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"1a0eb31c-84b5-471c-926c-25a7ca0d02a7","node_id":"2.0","card_order":4,"card_type":"why_it_works","title":"Por que corta funciona mejor que impresionante","body":"La tentacion es enorme: ya que tienes su atencion, quieres aprovecharla toda. Contarle la trayectoria, los premios, todo lo que manejas.\\n\\nY es justo al reves. Cada frase de mas gasta la atencion que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de el.\\n\\nCorto no es un atajo ni una version reducida. Es la version que si funciona.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"5efec033-942f-4be4-8ad7-c7ff7c5e2ce3","node_id":"2.0","card_order":5,"card_type":"concept","title":"Y despues de la historia, preguntas","body":"Un error comun es creer que despues de presentarte toca explicar mas.\\n\\nNo. Despues de presentarte toca PREGUNTAR. La doctrina es clara en esto: es mucho mas efectivo pasar directo a las preguntas que dar una explicacion larga.\\n\\nTu historia breve no existe para que el cliente te entienda a ti. Existe para ganarte el derecho de preguntarle a el.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"0c39e0a4-749b-4aab-96b5-1ea2d83aacb8","node_id":"2.1","card_order":1,"card_type":"concept","title":"Ahora con tus palabras","body":"Te van a preguntar quien eres. Tienes quince segundos.\\n\\nQuien soy — nombre y de donde vienes.\\nPor que estoy aqui — el motivo, en terminos humanos.\\nEl gancho — una pregunta que le devuelve la palabra.\\n\\nTres frases. Ni una mas.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"c1daf901-8ea1-41f3-98d2-8070a76f25a9","node_id":"2.1","card_order":2,"card_type":"bad_example","title":null,"body":"Buenos dias, mi nombre es Emilio y represento a una empresa con mas de veinticinco anos en el mercado, lideres en la region, manejamos una linea completa con certificaciones internacionales y trabajamos con los principales negocios del estado...","flip_back_text":"Todo es cierto y nada sirve. Se le acabo la atencion en la segunda frase y ni siquiera dijo por que esta ahi. El cliente no escucho una presentacion: escucho un discurso. Y de los discursos uno se defiende.","created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"1dab5d08-96ff-4643-8cbf-09a2b3fbe3ca","node_id":"2.1","card_order":3,"card_type":"good_example","title":null,"body":"Soy Emilio, ando trabajando con los negocios de esta zona. Me tocaba pasar por aqui y quise conocer el suyo. Cuenteme, cuanto tiempo lleva con el?","flip_back_text":"Tres frases, quince segundos. Dice quien es, por que esta ahi en terminos humanos (quise conocer su negocio, no vengo a venderle), y termina devolviendo la palabra. El cliente ya sabe con quien habla y tiene algo que contestar.","created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"7c049580-5a15-4318-bc67-7735f0f471f5","node_id":"2.10","card_order":1,"card_type":"concept","title":"La puerta fria","body":"Este cliente te bloquea en la primera frase. No es grosero: es lo que hace todos los dias con todos los que llegan.\\n\\nTodo el mundo junto: atraviesa el bloqueo sin pelearlo, di quien eres en quince segundos, conecta con el como persona y regresa, y no sueltes el control de la conversacion en ningun momento.\\n\\nCuando te pregunte en que te puede servir, ganaste. Esa pregunta es la puerta al siguiente paso.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"a99f361f-5111-49b5-949d-48772ce388bc","node_id":"2.2","card_order":1,"card_type":"concept","title":"Las afirmaciones se ignoran","body":"Se ve que le va muy bien aqui.\\n\\nQue puede contestar el cliente a eso? Gracias. Y ya. La conversacion se queda ahi parada esperando que tu digas otra cosa.\\n\\nUna afirmacion se puede ignorar sin que pase nada. Y el cliente que no sabe que hacer contigo, la ignora.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"6f2f87b7-b22d-4605-bd72-838ff1df8920","node_id":"2.2","card_order":2,"card_type":"concept","title":"Las preguntas se contestan","body":"Se ve que le va bien aqui. Cuanto tiempo lleva con el negocio?\\n\\nEs la misma observacion, con cuatro palabras mas. Pero ahora el cliente tiene algo que hacer.\\n\\nEl silencio despues de una pregunta se siente raro, y la gente lo llena. Por eso una pregunta mueve la conversacion y una afirmacion la detiene.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"cd4b0d86-c03f-4a42-a7d8-898af6218662","node_id":"2.2","card_order":3,"card_type":"why_it_works","title":"La conversacion la sostienes tu","body":"Aqui va algo que hay que aceptar de entrada: el cliente no tiene ninguna obligacion de sostener esta conversacion. No te invito, no te esperaba, y tiene cosas que hacer.\\n\\nSi tu no la mueves, se muere. Y no porque el sea grosero: porque no es su trabajo.\\n\\nEse es todo el ejercicio. Cada cosa que digas, termina devolviendo la palabra.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f79c3c10-3340-4199-b854-c3acb0916ccc","node_id":"2.3","card_order":1,"card_type":"concept","title":"A quien le compra la gente","body":"Dos vendedores, mismo producto, mismo precio, mismas condiciones. Uno cae bien. El otro no.\\n\\nNo hace falta que adivines cual vende.\\n\\nY no es injusto ni irracional. Cuando dos opciones son iguales, lo unico que queda para decidir es con quien prefieres tratar.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"930f76bc-5a6e-411b-9f56-2256e7cd8fec","node_id":"2.3","card_order":2,"card_type":"concept","title":"Eres tanto o mas el producto que lo que vendes","body":"Esa frase esta en la doctrina y hay que tomarla literal.\\n\\nEl cliente no puede evaluar tu producto todavia: no lo ha probado, no conoce tu empresa, no sabe si le van a cumplir. Lo unico que si puede evaluar, desde el primer segundo, eres tu.\\n\\nAsi que mientras el decide si le crees o no a tu producto, ya decidio si te cree a ti.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"00e3daf8-4fb1-44ad-8ced-1f5e557b25ba","node_id":"2.3","card_order":3,"card_type":"concept","title":"CPR: Crear Relaciones Personales","body":"C — Create / Crear\\nP — Personal / Personales\\nR — Relations / Relaciones\\n\\nCrear relaciones personales. Y ojo con esto, porque es lo que lo hace distinto de todo lo demas que has aprendido: CPR no es un paso.\\n\\nNo va en un lugar del mapa. Se hace durante TODA la conversacion, desde el primer segundo hasta el ultimo.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"4cf247cc-3f4f-4de8-9b46-e5616ecc070e","node_id":"2.3","card_order":4,"card_type":"why_it_works","title":"Sin relacion, no te contestan","body":"En el siguiente mundo vas a aprender a hacer preguntas sobre el negocio del cliente: que le funciona, que le falla, que le duele.\\n\\nY aqui esta el problema: esas preguntas solo funcionan si te las contestan de verdad. A un desconocido nadie le cuenta sus problemas. A alguien que le cae bien, si.\\n\\nPor eso el CPR no es un adorno ni una cortesia. Es la condicion para que lo que viene despues funcione.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"e0a3f4b5-74c8-455d-9288-8cb6289e518e","node_id":"2.4","card_order":1,"card_type":"concept","title":"De que le hablo?","body":"Aqui es donde se traba todo el mundo. Ya entendiste que hay que crear relacion, estas convencido, quieres hacerlo.\\n\\nY llega el momento y no sabes de que hablar. Se te ocurre el clima, y el clima ya lo usaste.\\n\\nLa doctrina resuelve eso con cinco temas. Se llaman FORMS.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"cf488bbe-2e9b-49ed-9e73-27efb1c72f99","node_id":"2.4","card_order":2,"card_type":"concept","title":"FORMS: los cinco caminos a la persona","body":"F — FAMILY / Familia\\nO — OCCUPATION / Ocupacion\\nR — RECREATION / Recreacion\\nM — MOTIVATION / Motivacion\\nS — SPORTS / Deportes\\n\\nCinco puertas. Siempre hay al menos una abierta, con cualquier persona, en cualquier lugar del mundo.\\n\\nVamos una por una.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ab3aeff3-e876-4edf-b93d-8df68c2e8c90","node_id":"2.4","card_order":3,"card_type":"concept","title":"Los cinco, uno por uno","body":"FAMILIA — la foto en el mostrador, el hijo que ayuda los fines, el hermano socio.\\n\\nOCUPACION — cuanto lleva, como empezo, a que se dedicaba antes.\\n\\nRECREACION — que hace cuando no esta trabajando, alguna aficion.\\n\\nMOTIVACION — por que puso el negocio, para quien trabaja, que quiere lograr.\\n\\nDEPORTES — su equipo, el partido, lo que se este jugando.\\n\\nNo necesitas los cinco. Con uno bien trabajado basta.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"00e08207-0f46-414f-8846-1eb8d842b552","node_id":"2.4","card_order":4,"card_type":"concept","title":"La palabra que lo decide todo: genuino","body":"La doctrina dice que el CPR se hace con cumplidos genuinos y chistes sencillos. La palabra importante ahi es genuinos.\\n\\nUn interes fingido se nota siempre. Y cuesta mas que no haber preguntado nada, porque ahora el cliente sabe que le estas aplicando una tecnica.\\n\\nLa regla es simple: si de verdad no te interesa, no preguntes. Busca otra puerta que si te interese de verdad.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"fdc6e88d-c436-4684-ad9f-7005bf22eb9d","node_id":"2.4","card_order":5,"card_type":"why_it_works","title":"A la gente le encanta hablar de si misma","body":"No es un defecto de nadie. Es como estamos hechos.\\n\\nPreguntale a alguien por su negocio, por sus hijos o por su equipo, y va a hablar con gusto. Y mientras habla pasan dos cosas al mismo tiempo: se relaja contigo, y te va conociendo.\\n\\nTu trabajo mientras tanto es escuchar de verdad. Pero sin soltar el rumbo, y eso es exactamente lo que practicas en el siguiente nodo.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"914bc1c3-bd3d-4456-b557-41a039453afa","node_id":"2.5","card_order":1,"card_type":"concept","title":"Sales de la linea a proposito","body":"Te acuerdas de la linea recta? Hay cosas que te sacan de ella.\\n\\nEl CPR es la unica que sales tu, por voluntad propia, porque te conviene. Dejas de avanzar un momento, te vas a lo personal, y despues vuelves al punto donde ibas.\\n\\nLa salida es facil. Lo dificil, y lo que vas a practicar aqui, es el regreso.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"2409f843-3503-4c91-ba10-f0e1c55a6332","node_id":"2.5","card_order":2,"card_type":"concept","title":"Uno o dos puntos, y regresas","body":"La regla es concreta: uno o dos intercambios personales, y vuelves al negocio.\\n\\nPuedes volver a salir mas adelante, y de hecho conviene. Pero siempre avanzando.\\n\\nDos errores, y los dos cuestan la venta. Si nunca sales, no hay relacion y no te van a contestar nada. Si sales y no regresas, el cliente se acomoda a platicar, la conversacion se vuelve social y ahi se queda para siempre.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"75b3cf9b-ce6d-44bb-987a-cb5e414c4256","node_id":"2.5","card_order":3,"card_type":"why_it_works","title":"El cliente nunca te va a regresar","body":"Ojo con esto porque sorprende a todos.\\n\\nCuando la platica se pone agradable, el cliente esta comodo. Nadie interrumpe una conversacion agradable para hablar de negocios. El no tiene ninguna razon para regresarte a la linea.\\n\\nEl unico que puede regresar eres tu. Y si no lo haces, se te va la tarde platicando con alguien encantado que no te va a comprar nada.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c20c61a7-66ab-4df8-a612-27be54574d04","node_id":"2.6","card_order":1,"card_type":"concept","title":"El primer no casi nunca es un no","body":"Llegas, saludas bien, todo va bien. Y antes de que digas nada te sueltan: ahorita no, gracias.\\n\\nPregunta seria: a que te esta diciendo que no? Todavia no sabe quien eres ni a que vienes.\\n\\nNo te esta rechazando a ti ni a tu oferta. Esta cerrando una puerta antes de saber que hay del otro lado, y lo hace en automatico.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"6a925057-562d-419e-8d5f-1446cac9b4bb","node_id":"2.6","card_order":2,"card_type":"concept","title":"Bloqueo: un reflejo","body":"Un BLOQUEO llega ANTES de entender.\\n\\nAhorita ando ocupado. No me interesa. No estoy comprando nada. Ya tengo con quien.\\n\\nFijate en lo que tienen en comun: ninguna requiere haber pensado. Son la respuesta que ese cliente le da a cualquiera que llega, todos los dias. Es la puerta cerrandose sola, no una decision.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"4fe67be8-9cf9-4261-b5f4-98e44939099a","node_id":"2.6","card_order":3,"card_type":"concept","title":"Objecion: una preocupacion real","body":"Una OBJECION llega DESPUES de entender.\\n\\nEsta caro. Ya tengo proveedor y me cumple. Lo tengo que consultar. No es el momento por el flujo.\\n\\nAqui si hubo pensamiento. El cliente entendio lo que le ofreces, lo evaluo, y encontro un problema concreto. Eso es completamente distinto, y se maneja distinto. Las herramientas para objeciones las vas a aprender cuando llegues al cierre.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"8d7561a1-ec13-48f3-be7f-9e76224273a0","node_id":"2.6","card_order":4,"card_type":"why_it_works","title":"Por que importa tanto la diferencia","body":"Porque el mismo tratamiento aplicado al caso equivocado destruye la conversacion.\\n\\nSi discutes con un reflejo, lo conviertes en una posicion. El cliente dijo no me interesa sin pensarlo, tu lo peleas, y ahora tiene que defenderlo. Le acabas de dar un no de verdad que no tenia.\\n\\nY al reves: ignorar una preocupacion real ofende a alguien que si te escucho y si penso.\\n\\nLa misma frase, no me interesa, se maneja de dos maneras opuestas segun cuando llego.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"b94d20f4-fd32-491b-81ef-b14785aba5cd","node_id":"2.6","card_order":5,"card_type":"concept","title":"AIR: la herramienta del bloqueo","body":"A — AGREE / Acepta\\nI — IGNORE / Ignora\\nR — RESUME / Resume\\n\\nAcepta lo que te dijo con un entiendo o un claro que si. Ignoralo, en el sentido de no discutirlo ni justificarte. Y resume: sigue con lo tuyo, con naturalidad.\\n\\nSuena demasiado simple para funcionar. Y funciona precisamente por eso: nadie defiende un reflejo si el otro no lo ataca.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"a145e01f-d5dc-4551-ba86-3bb8f8ccd955","node_id":"2.7","card_order":1,"card_type":"concept","title":"Los tres movimientos","body":"ACEPTA — entiendo, claro que si, por supuesto. Sin ironia y sin discutir.\\n\\nIGNORA — no lo peleas, no te justificas, no intentas convencerlo de que si le interesa.\\n\\nRESUME — sigues con tu tema, con naturalidad, como si el bloqueo no hubiera pasado.\\n\\nTres movimientos, dos segundos.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"35b80c3a-d356-4e95-9514-ca7291b76455","node_id":"2.7","card_order":2,"card_type":"concept","title":"El tercero es el que falla","body":"Casi todos aceptan bien. Casi todos logran no discutir.\\n\\nY despues se quedan parados esperando. O peor: vuelven a pedir permiso. Entiendo, claro... entonces, si me permite un momentito?\\n\\nAhi se pierde todo lo ganado. Acabas de aceptar el bloqueo para despues entregarle otra vez el control.\\n\\nAceptar y seguir. En la misma frase.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"94d8cbb9-aae1-4dab-bebd-2a7b95f91567","node_id":"2.7","card_order":3,"card_type":"bad_example","title":null,"body":"Ah, pero es que solo le voy a quitar dos minutos, y de verdad esto si le va a servir mucho, dejeme le explico rapido...","flip_back_text":"Peleo el bloqueo. El cliente dijo ando ocupado sin pensarlo, y ahora tiene que sostenerlo, porque nadie se deja convencer de que no esta ocupado. Un reflejo se acaba de convertir en una posicion, y ahora si hay un no de verdad.","created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"2e94313f-d35f-4036-a5c6-b51c681b4106","node_id":"2.7","card_order":4,"card_type":"good_example","title":null,"body":"Claro que si, entiendo. Oiga, y digame una cosa, cuanto tiempo lleva usted aqui?","flip_back_text":"Los tres movimientos en una sola frase. Acepto lo que dijo sin discutirlo, no lo peleo, y sigo con lo mio de inmediato. Fijate en lo que NO hay: ni un pero, ni una justificacion, ni una pausa esperando permiso. El bloqueo se disolvio porque nunca fue una posicion: era un reflejo.","created_at":"2026-08-11T01:31:01.229453+00:00","card_content_type":"static","audience":null,"skill_ids":["blocks.air"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"53240d42-5062-4352-97ea-e6fd5ea34982","node_id":"2.8","card_order":1,"card_type":"concept","title":"Hay negativos que ya sabes que van a llegar","body":"Si llevas tiempo en tu zona, ya los conoces de memoria. Ya me han fallado antes. Todos prometen y nadie cumple. Por aqui pasan muchos como usted.\\n\\nNo son sorpresas. Son los mismos, casi siempre.\\n\\nY todo lo que es predecible se puede desactivar antes de que pase.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f785efb1-5e74-44f7-ac9f-541de61ad304","node_id":"2.8","card_order":2,"card_type":"concept","title":"Si tu lo dices primero, deja de ser un arma","body":"La doctrina lo dice asi: si das la negativa antes de que el cliente lo haga, ya no es una negativa.\\n\\nYa se que por aqui pasan muchos como yo y que casi todos prometen lo mismo.\\n\\nFijate en lo que acaba de pasar. Le quitaste el argumento de las manos. Y ademas te volviste creible, porque alguien que reconoce lo malo se gana el derecho a que le crean lo bueno.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"1c6001da-22fd-4922-981f-9bde64e2bf89","node_id":"2.8","card_order":3,"card_type":"why_it_works","title":"Dos maneras de arruinarlo","body":"EN TONO DE DISCULPA. Perdon si le han fallado, pero yo si soy diferente. Eso ya no es adelantarse: es defenderse de algo que nadie te ha reclamado. Suena a excusa y no desarma nada.\\n\\nCON UN NEGATIVO INVENTADO. Si mencionas un problema que ese cliente no tenia, no desactivaste nada: le plantaste una preocupacion nueva. Ahora esta pensando en algo que ni le inquietaba.\\n\\nLa tecnica sirve para desarmar lo que ya existe. Nunca para crear.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"1de5675f-ecb5-4f58-8a1f-db7dd08476ed","node_id":"2.9","card_order":1,"card_type":"concept","title":"El momento justo despues de resolver","body":"Atravesaste el bloqueo. Contestaste la duda. Resolviste lo que te frenaba.\\n\\nY ahora viene el segundo mas importante de toda la conversacion, el que casi nadie ve: que haces despues.\\n\\nEl vendedor promedio se queda callado. Espera. Como pidiendo permiso con la mirada para continuar.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"047eb3fb-d3b8-48e5-b197-6b4a41545f49","node_id":"2.9","card_order":2,"card_type":"concept","title":"En ese silencio, el cliente retoma el control","body":"Y cuando el cliente retoma el control, hace lo mas comodo: cerrar con amabilidad. Bueno, pues ahi luego me dice. Gracias eh.\\n\\nNo te esta rechazando. Le devolviste el volante y el tomo la salida mas facil.\\n\\nLa regla es simple: resuelves y avanzas. En la misma intervencion, sin pausa. La conversacion la mueves tu hasta el final.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"77e67f01-d183-410b-b1cf-6bdace9ca4ce","node_id":"2.9","card_order":3,"card_type":"why_it_works","title":"Nunca esperes a que te den permiso de seguir","body":"Esta es una de esas ideas que cambian la manera de vender: tu no necesitas autorizacion para continuar una conversacion que ya esta pasando.\\n\\nPreguntar si puedes seguir es abrir una puerta que nadie te pidio que abrieras. Y siempre hay alguien dispuesto a salir por ella.\\n\\nSigues avanzando hasta que el cliente te detenga de verdad. Y cuando te detenga, resuelves y sigues otra vez.","flip_back_text":null,"created_at":"2026-08-06T17:15:17.687565+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c107dbe8-4289-45e4-a950-662dd12ea7d9","node_id":"3.0","card_order":1,"card_type":"concept","title":"Imagina esta consulta.","body":"Entras al consultorio. El doctor, sin preguntarte nada, sin revisarte, te dice: \\"Tomese estas pastillas, son buenisimas, a todos mis pacientes les funcionan.\\"\\n\\nLe crees? Te las tomas?\\n\\nEso EXACTO siente un cliente cuando le presentas el producto sin haberle preguntado nada.","flip_back_text":null,"created_at":"2026-07-25T21:40:07.757054+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"485081cf-1e67-487f-a389-1432cff7e379","node_id":"3.0","card_order":2,"card_type":"concept","title":"El diagnostico es lo que te separa.","body":"El vendedor promedio llega a recetar: trae su producto favorito en la mente y busca donde encajarlo.\\n\\nEl Closer llega a diagnosticar: pregunta, escucha, entiende el negocio — y SOLO entonces conecta lo que vende con lo que descubrio.\\n\\nLa ironia: el que diagnostica vende mas que el que receta. Porque la gente no compra productos — compra soluciones a SUS problemas.","flip_back_text":null,"created_at":"2026-07-25T21:40:07.757054+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"d763a2f0-65e7-40c0-bb60-52f98f7ff485","node_id":"3.0","card_order":3,"card_type":"concept","title":"El mapa del dolor: los 3 Territorios","body":"Un doctor no examina al azar: sabe donde buscar. Tu tambien. TODO dolor comercial de un cliente vive en uno de tres territorios:\\n\\nPRODUCTO — lo que vende o usa: faltantes de su estrella, lineas que no rotan, marcas que le piden y no consigue.\\n\\nSERVICIO — como lo trata su proveedor: entregas que no llegan, plantones, nadie que de la cara.\\n\\nPRECIO — lo que paga y lo que gana: margen apretado, subidas sin aviso, dinero congelado parado.\\n\\nYa no preguntas al azar. Preguntas con mapa.","flip_back_text":null,"created_at":"2026-07-25T21:40:07.757054+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"066e42c1-ed68-434d-aab3-36ef55bb091d","node_id":"3.0","card_order":4,"card_type":"concept","title":"El mismo territorio se pregunta distinto","body":"Los tres territorios son siempre los mismos. Lo que cambia es COMO preguntas, segun a quien le estas vendiendo.\\n\\nSI TU CLIENTE REVENDE lo que le compras: le preguntas por lo que mas maneja, por lo que sus clientes le piden y no tiene, por lo que se le queda parado.\\n\\nSI TU CLIENTE CONSUME lo que le vendes: no le preguntes que vende, porque no vende nada. Preguntale que USA, cuantas unidades maneja, cada cuanto repone, cuanto le dura.\\n\\nSI TU CLIENTE DISTRIBUYE: le preguntas por sus lineas, por a cuantos surte, por la zona que cubre.\\n\\nMismo mapa, tres traducciones. Preguntarle a un consumidor que maneja mas es la manera mas rapida de que se de cuenta de que no entendiste su negocio.","flip_back_text":null,"created_at":"2026-08-11T03:52:42.536596+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.preguntas_capas"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"6a7cfedc-b64a-47c2-b78f-5168b2c923d7","node_id":"3.0","card_order":5,"card_type":"why_it_works","title":"Por que preguntar vende mas que hablar","body":"Cuando preguntas de verdad, pasan tres cosas a tu favor:\\n\\nEl cliente se siente escuchado — y baja la guardia que le pone a los vendedores. Te da la municion exacta — te dice literalmente que le duele y que necesita. Y tu presentacion deja de ser generica — cada palabra que digas despues va a estar conectada con lo que EL te conto.\\n\\nPreguntar no retrasa la venta. La construye.","flip_back_text":null,"created_at":"2026-07-25T21:40:07.757054+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"4d71e274-18ed-474b-8205-47935976bfbc","node_id":"3.0","card_order":6,"card_type":"concept","title":"La regla del investigador","body":"El dolor NUNCA se pregunta directo. \\"Que problemas tiene?\\" produce un \\"ninguno, todo bien\\" — garantizado.\\n\\nEl dolor se deja emerger: preguntas por los hechos de un territorio, subes a la experiencia, y esperas el flaqueo — el \\"aunque...\\", el \\"a veces...\\", el \\"lo unico es que...\\".\\n\\nY cuando el dolor sale completo, lo confirmas con SUS palabras: \\"entonces lo que mas le pega es X, cierto?\\" Hasta que el cliente dice que si, no has terminado de diagnosticar.","flip_back_text":null,"created_at":"2026-07-25T21:40:07.757054+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"df14acbd-13a1-4dde-9a2c-aa0518000cb2","node_id":"3.0","card_order":7,"card_type":"concept","title":"Tu nuevo orden mental","body":"De este mundo en adelante, tu regla es la del doctor: primero el examen, luego la receta.\\n\\nYa te ganaste el derecho de hacer preguntas de negocio — abriste bien, te presentaste bien. Ahora si: recorre los territorios, escucha, profundiza. La presentacion puede esperar. El diagnostico, no.","flip_back_text":null,"created_at":"2026-07-25T21:40:07.757054+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"bf865535-640c-4993-be34-24d8ab92ab45","node_id":"3.1","card_order":1,"card_type":"concept","title":"Nadie llega neutro.","body":"El cliente que vas a visitar ahorita está en ALGÚN estado: apurado, relajado, preocupado, contento, harto. Y ese estado decide cómo te va a recibir — mucho más que tu producto o tu precio.\\n\\nEl error del vendedor promedio: tratar a todos igual, con el mismo ritmo y el mismo guion, como si el estado del cliente no existiera.","flip_back_text":null,"created_at":"2026-07-03T21:45:40.574424+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"bc634103-34ed-4e58-bde3-7929275c00e9","node_id":"3.1","card_order":2,"card_type":"concept","title":"Las tres R","body":"LEE (Read): en sus primeras palabras está todo — ¿habla rápido o con calma? ¿te contesta con ganas o distraído? ¿mencionó algo que trae en la cabeza?\\n\\nCONECTA (Relate): reconoce su momento, con naturalidad. \\"Lo noto con prisa.\\" \\"Se ve que hoy está tranquilo el día.\\" \\"Qué pendiente eso que me cuenta.\\"\\n\\nRELAJA (Relax): ajusta TU approach a SU estado. Prisa → directo y breve. Plática → fluye con él. Preocupación → atiéndela antes de avanzar.","flip_back_text":null,"created_at":"2026-07-03T21:45:40.574424+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"b32d8ce6-1685-4cda-a3c3-9037c88f8699","node_id":"3.1","card_order":3,"card_type":"why_it_works","title":"La conversación no avanza hasta que el cliente se relaja.","body":"Puedes tener las mejores preguntas del mundo — si el cliente está tenso, apurado o distraído, sus respuestas van a ser basura: cortas, evasivas, sin información real.\\n\\nRRR no es cortesía. Es ingeniería de la conversación: relajas al cliente PARA que el descubrimiento que viene tenga materia prima de verdad. Cliente relajado = respuestas reales = diagnóstico real.","flip_back_text":null,"created_at":"2026-07-03T21:45:40.574424+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"cd3e4bcf-bbff-4c75-b09b-ab82548ad77a","node_id":"3.1","card_order":4,"card_type":"concept","title":"En este reto, no sabes quién te abre.","body":"El cliente puede recibirte apurado, platicador o preocupado por algo. No te lo va a decir — te lo va a MOSTRAR en su forma de responder.\\n\\nTu trabajo: leerlo en dos frases, reconocer su momento, y ajustarte. Si lo ignoras y sigues con tu agenda, la conversación te lo va a cobrar.","flip_back_text":null,"created_at":"2026-07-03T21:45:40.574424+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ae90563a-c1a3-425b-b4f3-43899d77ae54","node_id":"3.10","card_order":1,"card_type":"concept","title":"El cuarto Boss.","body":"Un cliente analítico, apurado y desconfiado — le han hecho perder el tiempo antes. Trae un dolor real en el negocio, pero no se lo cuenta a cualquiera.\\n\\nTu misión: la conversación completa. Abrir. Presentarte. Atravesar el \\"no\\" que va a caer. Leer su prisa. Y excavar — capa por capa, pista por pista — hasta que el dolor salga completo. Confírmalo con sus palabras y habrás terminado.\\n\\nY recuerda la regla del doctor: hoy NO se receta. Solo se diagnostica.","flip_back_text":null,"created_at":"2026-08-19T14:26:53.328965+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"32369922-1e8d-4af7-b9e8-929c5356a5f1","node_id":"3.2","card_order":1,"card_type":"concept","title":"El dolor real nunca esta en la superficie.","body":"Preguntale a cualquier cliente \\"como va el negocio?\\" y te dira \\"bien, gracias a Dios.\\"\\n\\nEs cierto? Mas o menos. Todo negocio trae algo que le duele — y ya sabes donde buscarlo: en el PRODUCTO, en el SERVICIO o en el PRECIO. Pero eso no se cuenta al primer desconocido que pregunta. Se cuenta a quien se gana la respuesta... pelando capas.","flip_back_text":null,"created_at":"2026-07-27T19:48:40.423836+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"75984e16-2e53-461d-9134-b9d2fd8af940","node_id":"3.2","card_order":2,"card_type":"concept","title":"Las tres capas","body":"CAPA 1 — Hechos: faciles de responder, cero riesgo. \\"Que maneja mas?\\" \\"Quien lo surte?\\" \\"A como le llega?\\" Abren la platica y te dan el mapa de sus territorios.\\n\\nCAPA 2 — La puerta al dolor: aqui el cliente puede soltar una PISTA... o cerrarte la puerta con un \\"bien\\". Todo depende de COMO preguntes.\\n\\nCAPA 3 — El dolor completo: solo se abre si recoges la pista y profundizas con preguntas abiertas. Aqui te cuenta lo que de verdad le duele, con detalle y con emocion.","flip_back_text":null,"created_at":"2026-07-27T19:48:40.423836+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"1b4db757-5506-4839-94bb-4ecc4bcf1ce2","node_id":"3.2","card_order":3,"card_type":"concept","title":"Cuidado con el \\"bien\\" automatico.","body":"\\"Y que tal le va con su proveedor?\\" — \\"Bien, no me quejo.\\"\\n\\nEsa respuesta no es informacion: es un reflejo. Nadie le cuenta sus problemas a un desconocido que pregunta en generico, por dos razones: la respuesta cortes ya la trae cargada, y admitir un problema se siente como quejarse o como aceptar que eligio mal.\\n\\nLa pregunta generica no falla por mala suerte. Falla siempre. Y el vendedor promedio la escucha, piensa \\"aqui no hay nada\\" y se va con las manos vacias.","flip_back_text":null,"created_at":"2026-07-27T19:48:40.423836+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"99288c80-eefe-4ac5-90bc-ed26dc76762f","node_id":"3.2","card_order":4,"card_type":"concept","title":"La pregunta que no se puede contestar con \\"bien\\"","body":"La solucion es simple: cambia la opinion general por algo CONCRETO.\\n\\nEn vez de \\"que tal le va con su proveedor?\\" -> \\"le ha tocado quedarse sin su producto estrella?\\"\\nEn vez de \\"que tal anda el precio?\\" -> \\"cuanto le subieron este ano?\\"\\nEn vez de \\"todo bien por aca?\\" -> \\"cuantas veces al mes le llega incompleto el pedido?\\"\\n\\nYa no puede disparar el reflejo: tiene que ir a buscar un dato real de su negocio. Eso es todo — no es una tecnica complicada, es dejar de preguntar en general.\\n\\nMas adelante vas a aprender una version aun mas potente: darle permiso de admitirlo contandole que a otros les pasa. Por ahora, con preguntar concreto ya cambias el juego.","flip_back_text":null,"created_at":"2026-07-27T19:48:40.423836+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f7debf3b-7af9-4365-9ed1-2c802baf7f74","node_id":"3.2","card_order":5,"card_type":"concept","title":"Y aun asi te va a decir que no sabe","body":"Preguntaste concreto y el cliente contesta pues no se, o se queda pensando y suelta cualquier cosa.\\n\\nNo es que no quiera. Es que una pregunta abierta lo obliga a construir la respuesta desde cero, y eso cuesta trabajo. Como no le urge ayudarte, contesta lo mas corto que puede.\\n\\nLa solucion es darle de donde agarrarse.","flip_back_text":null,"created_at":"2026-09-02T14:40:57.383124+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.suggestive_language"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"d5bec5ce-3fe1-488b-a0f7-9b1ae2e575b7","node_id":"3.2","card_order":6,"card_type":"concept","title":"Suggestive Language: sugiere opciones","body":"Despues de preguntar, avienta tres o cuatro opciones.\\n\\nQue familias son las que mas se te mueven? Anticongelantes? Aceite de motor? Diesel? Moto?\\n\\nA como compras el liquido de frenos? 70? 80? 90?\\n\\nY aqui esta lo bueno: o elige una de tus opciones, o te CORRIGE con el dato real — no, mas bien 95.\\n\\nEsa correccion es justo la informacion que buscabas, y la pregunta abierta nunca te la habria dado.","flip_back_text":null,"created_at":"2026-09-02T14:40:57.383124+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.suggestive_language"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"0bf0f92b-61ec-412e-9ee3-6dc47068e9dd","node_id":"3.2","card_order":7,"card_type":"why_it_works","title":"La palabra magica: \\"aunque...\\"","body":"Cuando tu pregunta abre la puerta, escucha con lupa los peros y los aunques: \\"bien, aunque a veces batalla uno\\", \\"sin queja, lo unico es que...\\".\\n\\nEso NO es relleno — es el cliente asomando el dolor para ver si te interesa. Si lo dejas pasar, la puerta se cierra y no se vuelve a abrir. Si lo recoges con una pregunta ABIERTA (\\"como cuanto le dura ese batallar?\\"), la capa 3 se abre sola.\\n\\nConcreta para abrir. Abierta para excavar. Ese es el orden, y no se invierte.","flip_back_text":null,"created_at":"2026-07-27T19:48:40.423836+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"7e90354a-b764-4775-897a-ec2915e9bf8d","node_id":"3.2","card_order":8,"card_type":"concept","title":"Y si de verdad no hay nada ahi? El barrido.","body":"A veces preguntas concreto y el cliente lo niega limpio: \\"no, eso si no, mi proveedor me cumple bien.\\" Y es verdad.\\n\\nAhi el vendedor promedio hace una de dos: insiste hasta volverse pesado, o se rinde. El investigador hace la tercera: le CREE, y CAMBIA DE TERRITORIO. Servicio salio sano? Explora producto: \\"y hay algo que sus clientes le pidan y batalle para conseguir?\\" O precio: \\"y a como le esta llegando su estrella?\\"\\n\\nEl dolor casi siempre existe. Solo que vive en OTRA zona del mapa. Negacion limpia = siguiente territorio.","flip_back_text":null,"created_at":"2026-07-27T19:48:40.423836+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"2319f099-fa45-44df-b566-8d2af803ade0","node_id":"3.3","card_order":1,"card_type":"concept","title":"El cliente te está regalando oro. ¿Lo estás viendo?","body":"\\"Aqui lo que mas jala es esa linea, sobre todo desde que mi hijo le entro al negocio.\\"\\n\\nEl vendedor con guion escucha: la linea que mas jala — dato para su lista.\\n\\nEl Closer escucha: MI HIJO le entro al negocio — la historia completa del lugar, regalada de pasada.\\n\\nCada respuesta trae un regalo que nadie pidio. La diferencia esta en quien lo recoge.","flip_back_text":null,"created_at":"2026-07-03T21:46:42.341352+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"9dff8cd7-1cf6-4ea7-888d-d4c75270f6ba","node_id":"3.3","card_order":2,"card_type":"concept","title":"La regla: tu siguiente frase nace de la suya.","body":"Escucha la respuesta completa. Encuentra el regalo, que es el dato que no pediste. Y pregunta sobre EL, usando las palabras del cliente.\\n\\n\\"Su hijo tambien anda metido aqui? Y el fue el de la idea?\\"\\n\\nFijate en lo que NO hiciste: no sacaste tu siguiente pregunta de la lista. La conversacion va por donde el la abrio, y por eso se siente conversacion y no interrogatorio.","flip_back_text":null,"created_at":"2026-07-03T21:46:42.341352+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f1afcff7-f353-40bc-9012-6d471d7f32d8","node_id":"3.3","card_order":3,"card_type":"why_it_works","title":"Por qué el que escucha se lleva la información buena","body":"Cuando recoges el regalo del cliente, le mandas la señal más poderosa de una conversación: \\"te estoy escuchando de verdad.\\"\\n\\nY la gente le cuenta más a quien la escucha. Cada regalo recogido produce otro regalo — la conversación se profundiza sola. Cada regalo ignorado seca la fuente: respuestas más cortas, cliente más lejos.\\n\\nEn este reto lo vas a sentir en vivo: el cliente te va a regalar datos. Recógelos.","flip_back_text":null,"created_at":"2026-07-03T21:46:42.341352+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"e733fc3e-c142-407c-bef8-b8357321ee47","node_id":"3.4","card_order":1,"card_type":"concept","title":"Un cuestionario no abre a nadie","body":"Ya sabes preguntar por capas y ya sabes recorrer los tres territorios. Y aun asi te pueden contestar puros datos secos.\\n\\nPorque hay una diferencia enorme entre alguien que te contesta y alguien que se te abre. Los datos te los da cualquiera. El dolor solo te lo cuenta quien confia en ti.\\n\\nEl cuestionario perfecto, hecho por un desconocido, no llega al fondo nunca.","flip_back_text":null,"created_at":"2026-08-10T19:03:32.321772+00:00","card_content_type":"static","audience":null,"skill_ids":["relationship.cpr"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"37d1d910-6dd4-4c97-800b-a81064184f73","node_id":"3.4","card_order":2,"card_type":"concept","title":"Intercala, no separes","body":"El error natural es hacer dos bloques: primero las preguntas de negocio y al final, si sobra tiempo, algo personal.\\n\\nNo funciona asi. Se intercala.\\n\\nPreguntas de un territorio. Recoges algo personal que te suelta. Le entras un momento. Y regresas al siguiente territorio. La conversacion se siente humana de principio a fin, y las respuestas se vuelven mas hondas conforme avanza.","flip_back_text":null,"created_at":"2026-08-10T19:03:32.321772+00:00","card_content_type":"static","audience":null,"skill_ids":["relationship.cpr","discovery.preguntas_capas"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"d3116223-ee14-4577-8a57-0818f273f43b","node_id":"3.4","card_order":3,"card_type":"why_it_works","title":"Aqui es donde mas facil se hace","body":"En este paso el CPR casi se hace solo, y por eso es el mejor lugar para practicarlo.\\n\\nEstas preguntando por su negocio: cuanto lleva, como empezo, quien le ayuda. Todo eso ya es territorio personal. Solo tienes que reconocer cuando el cliente te abre una puerta, y entrar.\\n\\nY aqui vale doble: no solo construye relacion. Es lo que hace que te contesten la siguiente pregunta de verdad.","flip_back_text":null,"created_at":"2026-08-10T19:03:32.321772+00:00","card_content_type":"static","audience":null,"skill_ids":["relationship.cpr"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"0d0c12f3-180f-4f5d-8d1d-57422b4f77d1","node_id":"3.5","card_order":1,"card_type":"concept","title":"La regla 10 / 80 / 10","body":"De cada 100 personas con las que hables:\\n\\n10 son LUZ VERDE — comprarían casi solas: necesitan lo que traes y lo saben.\\n80 son LUZ AMARILLA — persuadibles: podrían comprar si haces bien tu trabajo. AQUÍ vive tu carrera.\\n10 son LUZ ROJA — no van a comprar hoy hagas lo que hagas.\\n\\nEl vendedor promedio trata a los tres igual. El Closer los identifica en vivo y reparte su tiempo donde hay retorno.","flip_back_text":null,"created_at":"2026-08-10T19:01:11.407385+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"9163277e-5972-4d14-9667-8ab8354a8d89","node_id":"3.5","card_order":2,"card_type":"concept","title":"Las señales de compra","body":"El cliente te dice quién es — si sabes escuchar las señales:\\n\\nPREGUNTA por el producto: \\"¿y ese cuánto cuesta?\\" \\"¿lo tienen en otra presentación?\\" \\"¿ustedes entregan?\\" — nadie pregunta precio de lo que no le interesa.\\n\\nHABLA de su situación de compra: \\"justo ando viendo proveedores\\", \\"el mío me quedó mal la semana pasada\\", \\"se me está acabando el que tengo\\".\\n\\nSE QUEDA en la conversación: podría cortarte y no lo hace. Pregunta de vuelta. Pide detalles.\\n\\nCada una de esas es el cliente diciéndote: \\"voy encendiendo la luz verde.\\"","flip_back_text":null,"created_at":"2026-08-10T19:01:11.407385+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"e58f9587-8785-4b9f-a6a1-d2dd8bfa1aaa","node_id":"3.5","card_order":3,"card_type":"concept","title":"La luz roja también es información — de la buena.","body":"El rojo se ve así: respuestas mínimas aunque hagas todo bien, cero preguntas de vuelta, \\"nomás estoy viendo por ver\\", el negocio literalmente no usa lo que vendes.\\n\\n¿Qué haces con un rojo? Sales RÁPIDO y AMABLE. Sin resentimiento, sin quemar la relación — hoy es rojo, en seis meses quién sabe.\\n\\nCada minuto que le regalas a un rojo se lo robaste a un amarillo que sí podía comprar. Tiempo de calidad con gente de calidad.","flip_back_text":null,"created_at":"2026-08-10T19:01:11.407385+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"cd8fa478-ea0e-4d5a-92dc-71ce19568b7e","node_id":"3.5","card_order":4,"card_type":"why_it_works","title":"Calificar no es rendirse — es matemática.","body":"Recuerda tu Ley de los Promedios: tu proporción aparece con volumen de CONVERSACIONES BUENAS. Tres conversaciones profundas con amarillos valen más que una hora atorado con un rojo.\\n\\nY ojo con la trampa inversa: el amable no siempre es verde. Hay rojos encantadores que platican una hora y jamás compran. La luz no se mide en sonrisas — se mide en señales.","flip_back_text":null,"created_at":"2026-08-10T19:01:11.407385+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f9100cb7-ccfc-43c9-843e-fc03396465ad","node_id":"3.5","card_order":5,"card_type":"why_it_works","title":"QTQP: tiempo de calidad con gente de calidad","body":"Q — QUALITY\\nT — TIME\\nQ — QUALITY\\nP — PEOPLE\\n\\nTiempo de calidad con gente de calidad.\\n\\nLa doctrina lo dice sin rodeos: perder tiempo y energia con las personas equivocadas destruye tu capacidad de ser urgente. Y la urgencia es de lo que vive tu ley de promedios.\\n\\nNo se trata de despreciar a nadie. Se trata de que tu dia tiene un numero fijo de horas, y cada una que le regalas a un rojo se la quitas a un amarillo que si podia comprar.","flip_back_text":null,"created_at":"2026-08-10T19:03:48.420376+00:00","card_content_type":"static","audience":null,"skill_ids":["qualification.luz_verde"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"4396205d-1e5d-4146-8812-d462ad7f0a04","node_id":"3.6","card_order":1,"card_type":"concept","title":"Irse tambien es una habilidad","body":"Nadie te ensena a irte. Te ensenan a entrar, a preguntar, a presentar, a cerrar. Pero irse a tiempo casi nunca se practica.\\n\\nY es de las cosas que mas dinero cuestan. El vendedor que se queda una hora convenciendo a alguien que nunca iba a comprar, no perdio una venta: perdio las tres que pudo haber visitado.\\n\\nLa doctrina es clara: sal de las luces rojas rapido y educadamente.","flip_back_text":null,"created_at":"2026-08-10T19:03:32.321772+00:00","card_content_type":"static","audience":null,"skill_ids":["qualification.luz_verde"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"319e56dc-7ac4-4589-82e7-16df5c003ad2","node_id":"3.6","card_order":2,"card_type":"concept","title":"La luz roja no siempre es hostil","body":"Es facil salirse de una conversacion con alguien grosero. El problema es el otro caso.\\n\\nHay clientes encantadores, platicadores, que te reciben con gusto y te dan una hora de su tiempo. Y no pueden comprar. Acaban de firmar contrato, no son ellos quienes deciden, o estan por cerrar el local.\\n\\nLa trampa no es el rechazo. Es lo agradable que se siente quedarse.","flip_back_text":null,"created_at":"2026-08-10T19:03:32.321772+00:00","card_content_type":"static","audience":null,"skill_ids":["qualification.luz_verde"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"2c8a88cb-15f9-4852-95f6-fb05e50fa342","node_id":"3.6","card_order":3,"card_type":"why_it_works","title":"Salir bien es dejar la puerta abierta","body":"Rojo hoy no es rojo para siempre. El contrato se vence, el dueno regresa, el negocio se estabiliza.\\n\\nPor eso la salida importa tanto como la entrada. El que insiste hasta incomodar quema la relacion y ya no lo reciben. El que reconoce la situacion y deja su numero con naturalidad, tiene la puerta abierta cuando cambien las cosas.\\n\\nReconoce, deja abierto, y muevete. Tu tiempo vale.","flip_back_text":null,"created_at":"2026-08-10T19:03:32.321772+00:00","card_content_type":"static","audience":null,"skill_ids":["qualification.luz_verde"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"90457310-b9ea-4535-ab54-b13ff54e1e19","node_id":"3.7","card_order":1,"card_type":"concept","title":"Hay dos juegos distintos","body":"Todo lo que llevas aprendido sirve para un juego: convertir a un desconocido en cliente. Te ganas la entrada, te presentas, encuentras el dolor, presentas, cierras.\\n\\nPero hay un segundo juego que casi nadie sabe que es distinto: convertir a un cliente en un cliente mas grande.\\n\\nYa te conoce. Ya te compra. Ya confia en ti. Y aun asi, la mayor parte de lo que gasta al ano en lo que tu vendes, se lo compra a alguien mas.","flip_back_text":null,"created_at":"2026-08-19T14:27:25.283068+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"1cde39b5-99d4-4361-8555-3bca4c59ecb5","node_id":"3.7","card_order":2,"card_type":"concept","title":"El enemigo: la visita que se vuelve tramite","body":"El vendedor lleva tres anos visitando al mismo cliente. La relacion es buena, lo reciben con gusto. Y cada visita es igual: saluda, levanta el pedido de siempre, se despide.\\n\\nNo esta haciendo mal su trabajo. Esta buscando dolor en alguien que no tiene dolor, no encuentra nada, y hace lo unico que queda.\\n\\nY ahi esta el riesgo de verdad: al que solo toma pedidos lo reemplaza un mensaje de WhatsApp. Un vendedor que nada mas transcribe lo que el cliente ya iba a pedir no esta haciendo nada que un formulario no pueda hacer mas barato.","flip_back_text":null,"created_at":"2026-08-19T14:27:25.283068+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"3ad883c4-141a-4e66-aef7-9fa7671fda4e","node_id":"3.7","card_order":3,"card_type":"concept","title":"Dolor y hueco: las dos oportunidades","body":"DOLOR — algo anda mal con lo que ya te compra. Se le acaba entre visitas. Se le quedo parado. El precio le aprieta.\\n\\nHUECO — algo que podria comprarte y no te compra. Una familia que maneja con otro proveedor. Una que no maneja nadie. Una que sus clientes le piden y el no tiene.\\n\\nSon dos cosas distintas y se buscan distinto. Confundirlas es la razon por la que tantos vendedores visitan durante anos sin crecer una sola cuenta.","flip_back_text":null,"created_at":"2026-08-19T14:27:25.283068+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"40ad76ef-a013-44f9-8353-9de29a72962a","node_id":"3.7","card_order":4,"card_type":"why_it_works","title":"El hueco se ve, no se oye","body":"El dolor tiene senal: el aunque. Bien... aunque a veces me quedo corto. Por eso lo encuentras preguntando por capas.\\n\\nEl hueco no tiene ninguna senal verbal. El cliente no te va a decir oiga, hay una familia que le compro a otro. Para el eso no es un tema: ya lo tiene resuelto.\\n\\nPor eso la escalera de capas no sirve aqui. No hay nada que excavar. Hay algo que MIRAR.","flip_back_text":null,"created_at":"2026-08-19T14:27:25.283068+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"2f5aba69-f969-4c88-8bbb-a845ca5c822a","node_id":"3.7","card_order":5,"card_type":"concept","title":"Las tres herramientas del hueco","body":"1. LEE EL LUGAR. El mostrador te dice todo antes de preguntar. Un producto de otra marca es un espacio que podria ser tuyo. Un estante vacio es una familia que no maneja nadie.\\n\\n2. PREGUNTA POR LO QUE LE PIDEN. Le ha tocado que le pidan algo que usted no maneje? Es demanda que ya existe sin oferta que la cubra: la venta mas facil que hay.\\n\\n3. ANCLA EN NEGOCIOS COMO EL SUYO. Varios negocios como el suyo tambien mueven tal cosa, usted eso lo maneja? Es prueba social, y tiene que ser verdad.","flip_back_text":null,"created_at":"2026-08-19T14:27:25.283068+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"e4d8a0a0-fb5b-460a-aef4-ddffd2883b96","node_id":"3.7","card_order":6,"card_type":"why_it_works","title":"La linea que no se cruza","body":"Un hueco tiene que ser REAL y verificable: lo viste, te lo dijo, o lo sabes por su giro.\\n\\nDescubrir un hueco es senalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.\\n\\nLo primero construye una relacion de anos. Lo segundo la termina el dia que el cliente se da cuenta — y con un cliente de cartera, ese dia siempre llega.","flip_back_text":null,"created_at":"2026-08-19T14:27:25.283068+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"2f94129e-59de-40c1-a85c-b0dacf4b1927","node_id":"3.7","card_order":7,"card_type":"concept","title":"Y si no puedes ver el lugar","body":"Cuando la visita es por telefono o por mensaje, la primera herramienta no existe: no hay mostrador que leer.\\n\\nAhi las otras dos cargan todo el trabajo. En lugar de observar el catalogo, lo preguntas: que familias maneja hoy ademas de lo que nos compra?\\n\\nMisma mecanica, distinta entrada.","flip_back_text":null,"created_at":"2026-08-19T14:27:25.283068+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"9da20b71-3d1b-4fbf-9de2-4bf9dea35e60","node_id":"3.8","card_order":1,"card_type":"concept","title":"Lo que no esta, y lo que esta y no se mueve","body":"Dos lecturas del mismo mostrador que llevan a conversaciones opuestas:\\n\\nLO QUE NO ESTA es oportunidad. Un estante vacio, una familia que no maneja, una marca de la competencia ocupando un espacio que podria ser tuyo.\\n\\nLO QUE ESTA Y NO SE MUEVE es problema. Producto empolvado, cantidades que llevan meses ahi.\\n\\nLo primero se trabaja como hueco. Lo segundo es dolor, y ese si se excava como aprendiste.","flip_back_text":null,"created_at":"2026-08-19T14:28:18.872303+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.lee_el_lugar"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"fa6d8a02-1cb4-430f-a4dd-f41207101964","node_id":"3.8","card_order":2,"card_type":"concept","title":"Las tres preguntas que mapean","body":"Que otras lineas maneja aparte de lo nuestro?\\nY esas de quien las trae?\\nDe lo que le llega a pedir la gente, hay algo que no maneje?\\n\\nTres preguntas, ningun problema, ningun dolor. Y al final sabes exactamente donde estan tus espacios.\\n\\nFijate que ninguna suena a venta: suenan a interes por su negocio. Por eso las contesta sin ponerse a la defensiva.","flip_back_text":null,"created_at":"2026-08-19T14:28:18.872303+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.lee_el_lugar"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"428970a6-f674-4f27-8ea6-5e2102e2da8f","node_id":"3.8","card_order":3,"card_type":"why_it_works","title":"La ultima es la mas valiosa","body":"De lo que le piden y no tiene: esa es la venta mas facil que vas a encontrar en tu vida.\\n\\nNo tienes que crear la necesidad ni convencer a nadie. La demanda ya existe, el cliente ya la esta perdiendo, y le molesta perderla.\\n\\nY casi ningun vendedor la pregunta, porque esta ocupado revisando lo que ya vende.","flip_back_text":null,"created_at":"2026-08-19T14:28:18.872303+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.lee_el_lugar"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"53b654e1-3694-4f2e-a535-562991671d62","node_id":"3.9","card_order":1,"card_type":"concept","title":"Este cliente te va a dar el pedido","body":"Y con gusto. Sin que se lo pidas.\\n\\nEsa es la trampa: la visita va a salir bien hagas lo que hagas. Vas a tener tu pedido, el cliente va a quedar contento, y te vas a ir sintiendo que hiciste tu trabajo.\\n\\nLevanta el pedido. Es lo minimo. Pero no te vayas ahi.","flip_back_text":null,"created_at":"2026-08-19T14:29:19.737797+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"0cc82d7c-bda2-4a10-8610-b0e0b380fd59","node_id":"3.9","card_order":2,"card_type":"concept","title":"Las tres herramientas, en orden","body":"1. MAPEA — que otras lineas maneja aparte de lo tuyo, y de quien las trae.\\n\\n2. PREGUNTA POR LO QUE LE PIDEN — hay algo que le pidan y no tenga? Esa es demanda que ya existe.\\n\\n3. ANCLA EN SIMILARES — varios negocios como el suyo tambien mueven tal cosa. Usted eso lo maneja?\\n\\nTres preguntas. Dos minutos. Y sales sabiendo donde estan tus espacios.","flip_back_text":null,"created_at":"2026-08-19T14:29:19.737797+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"697ae7a2-4a83-429f-9a1c-ca1a0c2c4a18","node_id":"3.9","card_order":3,"card_type":"why_it_works","title":"Aqui no te va a castigar nadie","body":"En los otros ejercicios, cuando lo haces mal, el cliente se cierra, te despacha o se enfria. La conversacion te avisa.\\n\\nAqui no. Si solo levantas el pedido y te vas, el cliente queda contento y la visita fue un exito.\\n\\nPor eso este error dura anos sin que nadie lo note: no duele. Simplemente nunca creces la cuenta, y nunca sabes por que.","flip_back_text":null,"created_at":"2026-08-19T14:29:19.737797+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c96b6f6e-7eaa-4684-880f-9f8d86a243e9","node_id":"3.9b","card_order":1,"card_type":"concept","title":"El cliente que te pide solo","body":"Uno de cada diez clientes es luz verde: en cuanto sabe quién eres y qué traes, te pide algo. \\"¿Ustedes traen esto? Tráigame diez cajas, que ya se me está acabando.\\"\\n\\nEs la visita más fácil del mundo, y por eso es una trampa. El vendedor anota, da las gracias y se va feliz con su pedido. Y nunca se entera de todo lo demás que ese cliente compra en otro lado.","flip_back_text":null,"created_at":"2026-10-07T18:38:33.693743+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"041a960a-48f4-42a9-ba3c-9e172afc28f1","node_id":"3.9b","card_order":2,"card_type":"concept","title":"Lo que te pidió es la puerta, no el techo.","body":"Primero le tomas el pedido, sin ponerlo en duda: él ya decidió, y eso no se toca.\\n\\nY luego, en lugar de irte, usas lo que ya sabes: mapeas qué otras líneas maneja y con quién; preguntas qué le piden que no tiene; y anclas en negocios como el suyo. Dos minutos más, y sales sabiendo dónde están tus espacios.","flip_back_text":null,"created_at":"2026-10-07T18:38:33.693743+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"4f918c79-5892-4597-b5cc-dd8afacdb16c","node_id":"3.9b","card_order":3,"card_type":"why_it_works","title":"Por qué la primera visita define la cuenta","body":"Un cliente que te pidió solo ya confía en ti: te acaba de abrir la puerta. Es el mejor momento para conocer su negocio, porque todavía no te ha puesto en una caja.\\n\\nSi en la primera visita solo te llevas lo que te pidió, para él serás \\"el de eso\\". Si ese día descubres su catálogo, serás su proveedor.","flip_back_text":null,"created_at":"2026-10-07T18:38:33.693743+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c21cbf0d-09af-4b2f-94fc-6b6bd2f6592a","node_id":"4.0","card_order":1,"card_type":"concept","title":"La ecuación detrás de toda compra","body":"¿Por qué alguien compra algo? Por una sola razón, siempre la misma:\\n\\nEn su cabeza, el VALOR de tenerlo pesó más que el COSTO de conseguirlo.\\n\\nOjo con la palabra clave: PERCIBIDO. No importa cuánto vale de verdad — importa cuánto vale en la mente del cliente en ese momento. Y esa percepción... la construyes tú.","flip_back_text":null,"created_at":"2026-07-03T22:02:51.545966+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ecb5d877-58ab-4c1d-97db-7c48b127b473","node_id":"4.0","card_order":2,"card_type":"concept","title":"La balanza de dos platos","body":"De un lado: el VALOR — lo que gana con tu producto: el problema que se le resuelve, las ventas que deja de perder, la tranquilidad.\\n\\nDel otro: el COSTO — y no es solo dinero: es el tiempo de atenderte, el riesgo de cambiar de proveedor, el esfuerzo de decidir.\\n\\nCada frase que dices en una presentación hace UNA de cuatro cosas: sube el valor, baja el valor, sube el costo o baja el costo. No hay frases neutras.","flip_back_text":null,"created_at":"2026-07-03T22:02:51.545966+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"1b330ea5-56e0-423c-95ae-37753412e887","node_id":"4.0","card_order":3,"card_type":"why_it_works","title":"El error clásico: vender barato en vez de vender valioso","body":"El vendedor promedio ataca solo un plato: \\"está baratísimo, casi regalado, aproveche.\\"\\n\\nProblema: lo barato sin valor da desconfianza — ¿por qué tan barato? ¿qué tiene de malo?\\n\\nEl Closer trabaja los dos platos, en orden: PRIMERO sube el valor (conecta el producto con el dolor descubierto, pinta el problema resuelto) y SOLO DESPUÉS baja el costo (facilita la decisión). Cuando el valor está alto, el mismo precio se ve chico.","flip_back_text":null,"created_at":"2026-07-03T22:02:51.545966+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"af176216-afa4-4b18-b6ad-82739b5fefbe","node_id":"4.0","card_order":4,"card_type":"concept","title":"Entrénate a escuchar la balanza","body":"\\"Esto le rinde el doble antes del siguiente cambio\\" -> SUBE VALOR.\\n\\n\\"Y mire, le dejamos el primer pedido a consignacion\\" -> BAJA COSTO.\\n\\n\\"Bueno, si no le alcanza hay uno mas economico...\\" -> BAJA VALOR (acabas de decirle que lo bueno no era para el).\\n\\n\\"Le manejo pedido minimo de veinte piezas\\" -> SUBE COSTO.\\n\\nMisma conversacion, cuatro frases, cuatro efectos distintos. Escucha la tuya asi.","flip_back_text":null,"created_at":"2026-07-03T22:02:51.545966+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"687cc4aa-665b-49a3-aceb-8cc292549363","node_id":"4.0","card_order":5,"card_type":"why_it_works","title":"Siempre estas haciendo una de cuatro cosas","body":"Esto es lo que convierte la balanza en una herramienta y no solo en una idea bonita.\\n\\nCada frase que dices, cada gesto, cada silencio, hace una de estas cuatro cosas:\\n\\nSUBE el valor percibido.\\nLO BAJA.\\nSUBE el costo percibido.\\nLO BAJA.\\n\\nNo hay frases neutras. Cuando titubeas al dar un precio, subes el costo. Cuando cuentas un caso real de otro cliente, subes el valor. Cuando te disculpas por algo, bajas el valor.\\n\\nA partir de ahora, escucha tu propia presentacion asi: que plato acabo de mover?","flip_back_text":null,"created_at":"2026-08-10T19:08:58.072332+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.costo_vs_valor"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"2ddd77ee-48fe-491f-8465-3f5d581e5764","node_id":"4.1","card_order":1,"card_type":"concept","title":"La regla de oro de la presentación","body":"Tu presentación NO empieza con tu producto. Empieza con SU problema.\\n\\n\\"Usted me dijo que dos veces al mes se le va un cliente por faltante...\\" — y solo entonces: \\"...por eso le quiero platicar de esto.\\"\\n\\nEl puente dolor → solución es lo que separa una presentación de un comercial. El comercial le habla a todos. La presentación le habla a ÉL.","flip_back_text":null,"created_at":"2026-07-03T22:02:51.995084+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"c1974661-0603-4cb4-a55b-cf565487a542","node_id":"4.1","card_order":2,"card_type":"bad_example","title":null,"body":"Ejemplo de presentación genérica aplicada al contexto de la empresa: catálogo, calidad, años de experiencia y precios — sin una sola mención del problema del cliente.","flip_back_text":"Esta presentación servería idéntica en cualquier negocio de la ciudad — y por eso no vende en ninguno. Genérico = invisible.","created_at":"2026-07-03T22:02:51.995084+00:00","card_content_type":"dynamic","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"0b753940-c83c-4707-b079-598e04cce873","node_id":"4.1","card_order":3,"card_type":"good_example","title":null,"body":"Ejemplo de presentación conectada al dolor, aplicada al contexto de la empresa: abre nombrando el problema que el cliente contó, presenta la solución directa, y traduce a beneficio concreto del negocio.","flip_back_text":"Cada frase nace del dolor descubierto. El cliente no está escuchando un catálogo — está escuchando SU problema resolverse.","created_at":"2026-07-03T22:02:51.995084+00:00","card_content_type":"dynamic","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"bf00834c-9bf1-4448-bf5e-5a5866a41497","node_id":"4.10","card_order":1,"card_type":"concept","title":"La paradoja: el que necesita la venta, la espanta.","body":"El cliente huele la necesidad como los perros huelen el miedo. Un vendedor que RUEGA le dice al cliente dos cosas sin querer: que nadie más le está comprando (mala señal)... y que apretándolo va a sacar mejores condiciones (peor señal).\\n\\nEl indiferente comunica lo contrario: mi producto se mueve, mi zona es grande, y tu decisión — cualquiera que sea — no me quita el sueño. Y esa seguridad, paradójicamente, es magnética.","flip_back_text":null,"created_at":"2026-08-10T19:11:30.634794+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"d36acca4-6c4a-44ce-a313-8a0aa328be38","node_id":"4.10","card_order":2,"card_type":"concept","title":"SW3 en el campo: emocionado por el producto, tranquilo con la decisión.","body":"Ojo con el matiz — indiferencia NO es frialdad ni desgano:\\n\\nPor tu PRODUCTO: entusiasmo genuino, siempre. \\"El producto me encanta y por eso lo traigo.\\"\\nPor SU DECISIÓN: tranquilidad total. \\"Si le sirve, qué bueno. Si no, no pasa nada — la zona es grande.\\"\\n\\nY la frase que desarma a cualquier difícil: \\"¿Le platico cómo lo está usando el de la San José... o lo dejamos para otra vuelta?\\" El que está dispuesto a irse es, misteriosamente, al que no dejan ir.","flip_back_text":null,"created_at":"2026-08-10T19:11:30.634794+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"b004676e-97f4-4be2-9171-5126119bfe55","node_id":"4.10","card_order":3,"card_type":"why_it_works","title":"El juego del difícil se acaba cuando no hay miedo que apretar.","body":"Hay clientes que juegan a hacerse los difíciles como deporte: \\"hay muchos proveedores...\\", \\"¿y usted qué tiene de especial?\\", \\"no me urge...\\". No es rechazo — es una prueba: están midiendo si ruegas.\\n\\nSi ruegas o sueltas descuentos no pedidos: hueles a miedo, y el juego se pone peor — acabas regalando margen y respeto.\\n\\nSi sostienes la postura — tranquilo, cálido, dispuesto a volver otro día — las jugadas se agotan solas. Y detrás del juego aparece el interés real que estuvo ahí todo el tiempo.","flip_back_text":null,"created_at":"2026-08-10T19:11:30.634794+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"a74a2508-9450-44bf-ad46-86c796ebb6e7","node_id":"4.11","card_order":1,"card_type":"concept","title":"Cada \\"¿le interesaría?\\" es un no gratis.","body":"\\"¿Le interesaría probarlo?\\" — Pues déjeme ver.\\n\\"¿Quiere que le mande información?\\" — Sí, mándemela. (Nunca la lee.)\\n\\"¿Lo piensa y me avisa?\\" — Claro. (No avisa.)\\n\\n¿Ves el patrón? Cada pregunta de SI abre una puerta al no — y la inercia humana siempre agarra la salida fácil. El cliente interesado no necesita que le preguntes si quiere. Necesita que le muestres el camino.","flip_back_text":null,"created_at":"2026-08-10T19:11:31.568856+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"81d3e4c6-63a4-43ab-a72a-9fee34f3d1fe","node_id":"4.11","card_order":2,"card_type":"concept","title":"Asumir: lenguaje de \\"cuando\\", no de \\"si acaso\\".","body":"\\"Mire, para su movimiento lo que le va a funcionar es la caja mixta. Se la traigo el jueves que ando por acá — y la quincena la agarra surtido.\\"\\n\\nQué hizo esa frase: sugirió QUÉ (específico para su caso), sugirió CUÁNDO (día concreto), y pintó el resultado. Ni una pregunta de permiso.\\n\\n¿Y si algo no le late al cliente? Él lo dice — \\"mejor el viernes\\", \\"mejor media caja\\" — y fíjate: ajustar detalles ES participar del plan. El que negocia el día del pedido... ya está pidiendo.","flip_back_text":null,"created_at":"2026-08-10T19:11:31.568856+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"eef35bdd-e0f1-4c2f-bb93-cb2c54bbf99c","node_id":"4.11","card_order":3,"card_type":"why_it_works","title":"La línea sagrada: asumir NO es presionar.","body":"Asumir es sugerir el camino natural y dejar al cliente caminar — con libertad total de ajustar o parar.\\n\\nPresionar es dar por cerrado lo que no se aceptó, ignorar sus ajustes, o apurar. La respuesta del cliente te dice de qué lado estás: si fluye y ajusta detalles, asumiste bien. Si dice \\"espérese, yo no he dicho que sí\\" — cruzaste la línea, y toca dar un paso atrás con gracia: \\"tiene razón, me emocioné — ¿usted cómo lo ve?\\"\\n\\nEl poder de asumir funciona porque respeta: sugiere sin encerrar. En el siguiente mundo, esta habilidad se gradúa: se llama cierre.","flip_back_text":null,"created_at":"2026-08-10T19:11:31.568856+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"3d3b0708-3a2a-4fe1-a947-c0cd4a36370b","node_id":"4.12","card_order":1,"card_type":"concept","title":"El impulso sube por escalones — y cada escalón es un \\"sí\\".","body":"\\"Usted me decía que le da coraje mandar clientes a la competencia, ¿verdad?\\" — Sí.\\n\\"Y un cliente que se va, a veces ya no regresa, ¿no le ha pasado?\\" — Sí, me ha pasado.\\n\\"Entonces el surtido garantizado le cuida justo eso, ¿me explico?\\" — Pues sí.\\n\\nTres síes. Tres escalones. El cliente lleva tres acuerdos contigo antes de hablar de ningún pedido — y decir el cuarto sí es más fácil que decir el primero. Así funciona el impulso.","flip_back_text":null,"created_at":"2026-08-10T19:11:27.088106+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"397f0dcc-b036-490e-8765-05762a043627","node_id":"4.12","card_order":2,"card_type":"concept","title":"La regla de oro: síes GENUINOS.","body":"Ojo — el tren del sí NO es esto: \\"¿Verdad que usted quiere ganar más dinero?\\" \\"¿Verdad que la calidad es importante?\\"\\n\\nEsos son síes capciosos: el cliente los huele, se incomoda, y la desconfianza sube. Manipulación barata que sale carísima.\\n\\nEl sí genuino se ancla en lo que el cliente TE CONTÓ: su dolor, su realidad, sus palabras. No le estás sacando el sí con trampa — le estás confirmando lo que él mismo dijo. Por eso asiente cómodo.","flip_back_text":null,"created_at":"2026-08-10T19:11:27.088106+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"753a9612-7713-40c5-9063-fcb049a6fb30","node_id":"4.12","card_order":3,"card_type":"why_it_works","title":"Por qué el tren cambia el cierre","body":"Un cliente que pasó la presentación asintiendo — sí, sí, pues sí — llega al momento de la decisión con la cabeza ya inclinada hacia adelante. Decir que no ahora contradiría todo lo que él mismo acaba de afirmar.\\n\\nUn cliente que pasó la presentación callado llega neutral — y de neutral a sí hay un salto grande.\\n\\nEl tren no cierra la venta. Hace que el cierre — cuando llegue, en el siguiente mundo — sea el paso más natural del mundo.","flip_back_text":null,"created_at":"2026-08-10T19:11:27.088106+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"76469528-0f90-4acf-8875-b75a67ef7416","node_id":"4.13","card_order":1,"card_type":"concept","title":"Valor menos costo es igual a ahorro","body":"Esa es la formula, y toda la tecnica sale de ahi.\\n\\nEl cliente no compara tu precio contra cero. Lo compara contra lo que cree que vale. Si construiste bien el valor, tu precio ya se siente justo antes de que lo digas.\\n\\nY el ahorro no es una idea abstracta: es la distancia entre esas dos cifras. Tu trabajo es hacerla visible.","flip_back_text":null,"created_at":"2026-08-10T19:17:32.033388+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.price_breakdown"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"3c9c0c9e-3837-4cd3-a428-78be91c58872","node_id":"4.13","card_order":2,"card_type":"concept","title":"La escalera","body":"No des un solo numero. Da tres, bajando:\\n\\nNORMALMENTE — lo que cuesta de lista. Aqui hace match con lo que el cliente ya esperaba.\\n\\nCON EL PRIMER DESCUENTO — por ser cliente nuevo, por el volumen, por lo que aplique.\\n\\nCON EL SEGUNDO — por pago de contado, por cerrar hoy, por lo que corresponda.\\n\\nCien. Noventa. Ochenta. El cliente no escucho un precio: vio bajar uno.","flip_back_text":null,"created_at":"2026-08-10T19:17:32.033388+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.price_breakdown"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"35347d17-4f1d-48f6-96d7-5cd00c4d5679","node_id":"4.13","card_order":3,"card_type":"concept","title":"Cada escalon necesita un motivo","body":"Esta es la regla que hace que funcione, y la que casi todos rompen.\\n\\nUn precio que baja SIN razon le dice al cliente algo terrible: el primero estaba inflado. Y a partir de ahi te vuelve regateable, porque si bajo dos veces solo, va a bajar otra vez si presiona.\\n\\nUn precio que baja POR RAZONES NOMBRADAS hace lo contrario: confirma que los cien eran reales, y cada escalon se vuelve una bala de precio.\\n\\nNunca bajes un numero sin decir por que.","flip_back_text":null,"created_at":"2026-08-10T19:17:32.033388+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.price_breakdown"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"1321e2d6-8621-46d3-a28b-44221658ef2d","node_id":"4.13","card_order":4,"card_type":"why_it_works","title":"Por que se ve y no solo se escucha","body":"Si dices queda en ochenta, el cliente escucha un gasto de ochenta.\\n\\nSi dices normalmente cien, con su descuento de cliente nuevo noventa, y de contado ochenta, el cliente ve veinte pesos de ahorro que antes no existian.\\n\\nEs el mismo numero final. Pero uno se siente costo y el otro se siente ganancia. Y como el segundo descuento depende de algo que puede hacer HOY, aparece solo lo que ya conoces: el miedo a perder.","flip_back_text":null,"created_at":"2026-08-10T19:17:32.033388+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.price_breakdown"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"de0d4a94-324e-41d5-8882-9cbd2f8e4b06","node_id":"4.13","card_order":5,"card_type":"concept","title":"Y despues del numero, no te calles","body":"Aqui es donde mueren mas ventas que en ningun otro punto de la conversacion.\\n\\nEl vendedor da el precio y se queda callado, esperando la reaccion. Y en ese silencio el cliente hace lo unico que puede hacer sin comprometerse: lo voy a pensar.\\n\\nLo que sigue despues del precio es tan importante que tiene su propio nodo. Es el siguiente.","flip_back_text":null,"created_at":"2026-08-10T19:17:32.033388+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.price_breakdown"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c05fd478-b1a0-489f-bec4-4fead629217c","node_id":"4.14","card_order":1,"card_type":"concept","title":"Los dos movimientos, juntos","body":"Este nodo no entrena una cosa: entrena dos que en la calle siempre van pegadas.\\n\\nPRIMERO el desglose: tres numeros bajando, con su motivo cada uno.\\n\\nY DE INMEDIATO, sin pausa, el movimiento al siguiente paso.\\n\\nSeparados no funcionan. Un desglose perfecto seguido de silencio se convierte en un lo voy a pensar.","flip_back_text":null,"created_at":"2026-08-10T19:18:27.423429+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.price_breakdown","flow.close_with_action"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"8521f16a-240d-488c-9177-38f42ac0d398","node_id":"4.14","card_order":2,"card_type":"bad_example","title":null,"body":"Le queda en novecientos sesenta. ... Que le parece?","flip_back_text":"Dos errores en una frase. Un solo numero, asi que el cliente escucho un gasto y no un ahorro. Y despues le pregunto que le parece, que es entregarle el control justo en el momento mas delicado. La respuesta comoda a esa pregunta siempre es dejeme lo pienso.","created_at":"2026-08-10T19:18:27.423429+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.price_breakdown","flow.close_with_action"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"ea94ca40-d57b-4f15-8cb5-700110b751f4","node_id":"4.14","card_order":3,"card_type":"good_example","title":null,"body":"Normalmente le sale en mil doscientos. Como es su primer pedido, mil cincuenta. Y de contado se lo dejo en novecientos sesenta, son doscientos cuarenta de ahorro. Antes de que se emocione dejeme ver si alcanzamos entrega esta semana: le acomoda mas jueves o viernes?","flip_back_text":"Tres numeros bajando, cada uno con su razon, y el ahorro dicho en voz alta. Y sin respirar, ya lo movio a elegir una fecha. Fijate en lo que NO hizo: no pregunto si le parece bien ni si lo quiere. La respuesta a jueves o viernes ya es un si.","created_at":"2026-08-10T19:18:27.423429+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.price_breakdown","flow.close_with_action"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c599a3f5-1872-46a8-9e21-9942c04e50be","node_id":"4.15","card_order":1,"card_type":"concept","title":"Aqui no hay nada que resolver","body":"Cuando presentas una solucion a un dolor, el cliente ya sabe que algo le duele. Tu trabajo es conectar.\\n\\nCon un hueco es distinto: el cliente esta contento. No le duele nada. Ya lo tiene resuelto con alguien mas.\\n\\nNo hay problema que resolver. Hay un espacio que ocupar. Y eso se presenta diferente.","flip_back_text":null,"created_at":"2026-08-19T14:32:47.677421+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.consolidacion_proveedor"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"05b3ceef-3394-4ef0-bc9b-8d0339367fd5","node_id":"4.15","card_order":2,"card_type":"concept","title":"Nunca ataques al proveedor actual","body":"Es la tentacion natural: si le fallan, si le cobran caro, si se tardan.\\n\\nY es la manera mas rapida de cerrar la puerta. Si el cliente lleva anos con ese proveedor, criticarlo es criticar SU decision. Y la gente defiende sus decisiones, aunque sean malas.\\n\\nLo correcto es lo contrario: reconocelo. Que bueno que lo tenga cubierto. Desde ahi si se puede hablar.","flip_back_text":null,"created_at":"2026-08-19T14:32:47.677421+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.consolidacion_proveedor"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"947dd65f-0b60-45e5-8906-c50dd62c4869","node_id":"4.15","card_order":3,"card_type":"why_it_works","title":"Lo que vendes es un proveedor menos","body":"No estas vendiendo el producto: eso ya lo tiene.\\n\\nEstas vendiendo dejar de esperar dos entregas. Un pedido menos que rastrear. Una persona menos a quien marcarle cuando algo falta.\\n\\nY fijate en lo mejor: es un argumento que el otro proveedor NO puede igualar, porque el no tiene tu catalogo completo. Es lo unico que tienes que el no.","flip_back_text":null,"created_at":"2026-08-19T14:32:47.677421+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.consolidacion_proveedor"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"230037ea-a40e-4691-b501-708abec36495","node_id":"4.15","card_order":4,"card_type":"bad_example","title":null,"body":"Le pongo unas pocas nada mas para que lo pruebe y vea si le funciona.","flip_back_text":"Suena humilde y es lo peor que puedes decir: le estas diciendo yo no se si esto sirve, averigualo tu con tu dinero. La gente no quiere experimentar — esta comoda donde esta, y probar algo nuevo es riesgo. Le pasaste el riesgo a el.","created_at":"2026-08-19T14:32:47.677421+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.consolidacion_proveedor"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"742c8ca0-0259-4f01-beac-7abf7ea2a361","node_id":"4.15","card_order":5,"card_type":"good_example","title":null,"body":"Yo no le puedo garantizar nada, pero estoy seguro de que se le va a mover. Se lo digo porque en los negocios de por aca es de lo que mas sale.","flip_back_text":"Dos movimientos y se calla. Reconocer que no puede garantizar es justamente lo que hace creible lo que si afirma. Y la razon detras convierte su conviccion en algo verificable en vez de puro entusiasmo de vendedor. Ojo con lo que NO dijo: nada de y si no se mueve lo ajustamos. Eso le meteria una duda que el cliente no tenia.","created_at":"2026-08-19T14:32:47.677421+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.consolidacion_proveedor"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"aed7104a-f011-4d7e-8ad3-f6809528dcda","node_id":"4.16","card_order":1,"card_type":"concept","title":"El quinto Boss.","body":"Este cliente ya escuchó todas las promesas. Vendedores que juraban no fallar nunca — y fallaron. Su escudo: \\"eso mismo me dijo el anterior.\\"\\n\\nTu misión: el ciclo completo. Excava su dolor. Gánatelo como persona. Y presenta con valor REAL — su problema, sus palabras, su negocio en la escena, síes que le nazcan solos. Ni una promesa grandilocuente: con los desconfiados, la promesa grande es veneno y el detalle concreto es oro.\\n\\nGanas cuando el desconfiado te pida los detalles del siguiente paso. Ahí sabrás que el valor pesó más que la cicatriz.","flip_back_text":null,"created_at":"2026-08-19T14:31:41.681538+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f9884498-9fb3-4c81-9fe7-405cb93a9a40","node_id":"4.2","card_order":1,"card_type":"concept","title":"Nadie compra caracteristicas","body":"Le dices al cliente que tu producto tiene una formulacion mas estable a temperatura alta.\\n\\nY el piensa: y?\\n\\nNo es que no le importe. Es que le hablaste en tu idioma. Una caracteristica es lo que el producto ES. Y nadie compra lo que algo es: compran lo que van a ganar con eso.","flip_back_text":null,"created_at":"2026-08-10T19:08:42.918713+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.beneficio_no_caracteristica"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"fdefd869-8432-46ba-b435-f5c736e6fc0f","node_id":"4.2","card_order":2,"card_type":"concept","title":"Traduce a dinero, clientes o tranquilidad","body":"Toda caracteristica se puede traducir a una de tres cosas que si le importan a cualquier dueno de negocio:\\n\\nDINERO — gana mas o gasta menos.\\nCLIENTES — vende mas o los conserva.\\nTRANQUILIDAD — menos problemas, menos tiempo perdido, menos gente reclamando.\\n\\nSi no puedes traducir una caracteristica a una de esas tres, probablemente no valia la pena mencionarla.","flip_back_text":null,"created_at":"2026-08-10T19:08:42.918713+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.beneficio_no_caracteristica"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"1f3b7b0f-65df-4935-8e1f-0ebe2e2c203c","node_id":"4.2","card_order":3,"card_type":"bad_example","title":null,"body":"Este producto tiene formulacion sintetica de ultima generacion, con aditivos anti-desgaste y certificacion internacional.","flip_back_text":"Todo cierto, todo impresionante, y el cliente no entendio nada de lo que gana. Escucho tres caracteristicas seguidas en el idioma del vendedor. La respuesta natural es la que mas duele: y eso a mi de que me sirve?","created_at":"2026-08-10T19:08:42.918713+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.beneficio_no_caracteristica"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"e3d93f4a-0357-4e80-95fd-1908efc00da0","node_id":"4.2","card_order":4,"card_type":"good_example","title":null,"body":"Este dura casi el doble antes del siguiente cambio. Para usted eso son la mitad de servicios al ano por unidad, y clientes que regresan contentos en lugar de regresar a reclamar.","flip_back_text":"La misma caracteristica, traducida. Dijo lo que el producto hace y en la misma frase lo que el cliente gana: menos trabajo repetido y clientes que vuelven de buenas. Ya no es informacion tecnica, es una razon para comprar.","created_at":"2026-08-10T19:08:42.918713+00:00","card_content_type":"static","audience":null,"skill_ids":["presentation.beneficio_no_caracteristica"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"e92d93a9-8efe-4bf8-879e-6ce1bca3ceca","node_id":"4.3","card_order":1,"card_type":"concept","title":"Explicar informa. Pintar vende.","body":"\\"El producto tiene buena movimiento y margen competitivo.\\" — Tu cliente escuchó un dato. Los datos se evalúan... y se olvidan.\\n\\n\\"Imagínese la quincena que viene: llega su cliente de siempre por sus tres litros — y ahora SÍ los tiene.\\" — Tu cliente se VIO en la escena. Y de una escena donde está ganando, nadie se quiere salir.\\n\\nLa gente no compra productos. Compra la película de su vida con el problema resuelto.","flip_back_text":null,"created_at":"2026-08-10T19:07:41.235617+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"6a26acb7-9a98-482c-b539-ebb39bcf53b0","node_id":"4.3","card_order":2,"card_type":"concept","title":"Cómo se pinta una imagen","body":"Tres brochazos:\\n\\nEL MOMENTO — ponle tiempo y lugar: \\"la quincena que viene\\", \\"el sábado en la mañana cuando esto se llena\\".\\nEL PERSONAJE — mete a SU gente: \\"su cliente de siempre\\", \\"el muchacho que le ayuda\\", \\"el de la unidades que viene cada semana\\".\\nEL DESENLACE — el dolor resuelto, con ganancia visible: \\"se lo lleva, le deja la ganancia a usted y no al de enfrente.\\"\\n\\nY la llave de entrada, siempre: \\"Imagínese que...\\"","flip_back_text":null,"created_at":"2026-08-10T19:07:41.235617+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"352ba83f-42eb-4865-8f6a-09083c41f8a4","node_id":"4.3","card_order":3,"card_type":"why_it_works","title":"La señal de que funcionó: el cliente completa la escena.","body":"Cuando pintas bien, pasa algo mágico: el cliente le agrega detalles a TU imagen. \\"Pues sí... y hasta me ahorraría el coraje de andar llamando al proveedor.\\"\\n\\nEn ese momento la escena dejó de ser tuya — ya es de él. Ya está viviendo mentalmente con tu producto. Vender desde ahí no es empujar: es solo no estorbar.","flip_back_text":null,"created_at":"2026-08-10T19:07:41.235617+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"d190e76c-a04b-4400-887b-a876aeb9d663","node_id":"4.4","card_order":1,"card_type":"concept","title":"El impulso es una curva, no un interruptor.","body":"Nadie pasa de \\"no me interesa\\" a \\"lo compro\\" de golpe. El interés sube por una curva: escalón por escalón — un sí por aquí, una imagen que le gustó por allá, un dato que le hizo sentido.\\n\\nSube gradual... llega a un PICO... y si nadie hace nada con él, BAJA. El impulso que no se usa, se enfría. Y frío, ya no regresa igual.","flip_back_text":null,"created_at":"2026-08-10T19:11:27.660525+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"5bc0c7a5-f1e7-460b-87a2-defe521a6dce","node_id":"4.4","card_order":2,"card_type":"concept","title":"Los dos errores de la curva","body":"ERROR 1 — Abrumar al inicio: llegar con toda la artillería cuando el cliente está en el escalón cero. La curva no arranca a empujones — se espanta. Por eso los primeros pasos del sistema no venden: construyen.\\n\\nERROR 2 — Dejar pasar el pico: el cliente llegó arriba (pregunta precios, se imagina comprando, asiente a todo)... y el vendedor sigue presentando. Para cuando termina su rollo, la curva ya bajó. El momento se fue — y era EL momento.","flip_back_text":null,"created_at":"2026-08-10T19:11:27.660525+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"0bc5ccf1-00c2-4269-ae40-8f10dfcd1ffb","node_id":"4.4","card_order":3,"card_type":"why_it_works","title":"Tu trabajo: leer en qué punto de la curva está.","body":"Curva subiendo: el cliente pregunta, asiente, se acerca — sigue alimentando con valor, síes e imágenes.\\n\\nPico: señales de compra claras y seguidas — deja de presentar. Lo que sigue ahí es avanzar (y eso lo dominarás en el mundo del cierre).\\n\\nCurva bajando: respuestas que se enfrían, mirada al reloj — algo pasó; deja de empujar y vuelve a construir valor, o lee si es momento de retirarte bien.\\n\\nLos factores de impulso que vas a aprender en este mundo son los aceleradores de esa curva. Pero primero tenías que ver la curva.","flip_back_text":null,"created_at":"2026-08-10T19:11:27.660525+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"592565a6-feb2-4ce5-8ae8-88d6a81a39b8","node_id":"4.4","card_order":4,"card_type":"concept","title":"Las tres reglas de oro de la curva","body":"REGLA 1 — Encuentra al cliente en un punto comun de emocion al inicio, y construye desde ahi. No llegues gritando con alguien tranquilo ni apagado con alguien entusiasmado: empiezas donde esta el, y de ahi suben juntos.\\n\\nREGLA 2 — Cierra en el momento correcto. La curva tiene un pico, y despues del pico baja. Esperar de mas apaga lo que costo trabajo encender.\\n\\nREGLA 3 — El impulso no termina cuando el cliente dice que si: ahi empieza a caer. Eso tambien se trabaja, y lo vas a ver al final del mapa.","flip_back_text":null,"created_at":"2026-08-10T19:19:19.175664+00:00","card_content_type":"static","audience":null,"skill_ids":["impulse.curva_impulso"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"6af79567-ed58-47b4-a642-fe4df857e138","node_id":"4.4","card_order":5,"card_type":"why_it_works","title":"Gradualmente, no de golpe","body":"La tentacion es subir el impulso lo mas rapido posible. Y es contraproducente.\\n\\nUn cliente al que le echas encima todo el entusiasmo, todos los datos y toda la urgencia en dos minutos no se emociona: se abruma. Y un cliente abrumado se defiende.\\n\\nLa curva se construye por escalones. Cada cosa que dices sube un poco, dejas que asiente, y subes otro. Por eso los siguientes nodos entrenan un factor a la vez: en la calle se combinan, pero primero hay que saber usarlos por separado.","flip_back_text":null,"created_at":"2026-08-10T19:19:19.175664+00:00","card_content_type":"static","audience":null,"skill_ids":["impulse.curva_impulso"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"78a08da9-d4bf-4497-9a84-6b9c34f4c558","node_id":"4.5","card_order":1,"card_type":"concept","title":"El tiroteo","body":"Imaginalo asi: los dos entran a la conversacion con municion.\\n\\nTus balas son razones para comprar. Las del cliente son razones para no hacerlo.\\n\\nLa doctrina lo dice claro: la persona con mas balas claramente tiene el control, siempre y cuando conserve su municion. Esa ultima parte es la que casi nadie respeta.","flip_back_text":null,"created_at":"2026-08-10T19:12:49.477173+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"6e3a1dfb-d87c-47bd-bd50-c90e799d26c2","node_id":"4.5","card_order":2,"card_type":"concept","title":"Que es una bala","body":"Una bala es un HECHO POSITIVO y concreto que sube el impulso del cliente.\\n\\nNo es una opinion. No es un adjetivo. Somos los mejores no es una bala: es aire. Llevamos catorce anos surtiendo esta zona sin fallar en desabasto, si lo es.\\n\\nLa prueba: si la competencia puede decir exactamente lo mismo, no era una bala.","flip_back_text":null,"created_at":"2026-08-10T19:12:49.477173+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"03f82632-876c-4d32-a89d-359860e5f693","node_id":"4.5","card_order":3,"card_type":"concept","title":"De donde salen: tres arsenales","body":"SOBRE TI Y TU EMPRESA — anos en la zona, experiencia, premios, casos de exito, tu propia dedicacion.\\n\\nSOBRE EL PRODUCTO — lo que lo diferencia, mejoras recientes, datos duros, certificaciones.\\n\\nSOBRE EL PRECIO — la propuesta de valor, descuentos, condiciones de pago, comparacion honesta con lo que hay.\\n\\nAntes de salir a la calle deberias tener claras al menos tres de cada uno.","flip_back_text":null,"created_at":"2026-08-10T19:12:49.477173+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"8cfcbf10-8471-487a-bbce-81520bbf9188","node_id":"4.5","card_order":4,"card_type":"concept","title":"La regla que casi nadie respeta","body":"No dispares todas las balas al principio.\\n\\nEs la tentacion natural: tienes al cliente escuchando y quieres impresionarlo con todo lo que traes. Y ahi es donde te quedas desarmado.\\n\\nReserva algunas. Guarda balas para el cierre. Porque lo que viene despues cambia el juego, y vas a necesitar municion fresca justo cuando creas que ya no hace falta.","flip_back_text":null,"created_at":"2026-08-10T19:12:49.477173+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c68fc85e-042d-4882-82c4-f6cf7070bed1","node_id":"4.5","card_order":5,"card_type":"why_it_works","title":"Por que se guardan","body":"Mas adelante en el mapa vas a ver que pasa cuando el cliente pone una razon para no comprar.\\n\\nCuando eso ocurre, su impulso BAJA. Y responderle bien no lo sube: solo evita que siga cayendo.\\n\\nLo que lo vuelve a subir es una bala nueva. Si ya las gastaste todas presumiendo al principio, llegas a ese momento con la mano vacia. Por eso se dosifican.","flip_back_text":null,"created_at":"2026-08-10T19:12:49.477173+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ce0a0cab-3d0e-4838-b92f-f909c4f8db3c","node_id":"4.6","card_order":1,"card_type":"concept","title":"Una a la vez","body":"El error natural es soltar todo lo bueno de golpe, como quien vacia el cargador.\\n\\nY pasa algo curioso: el impulso sube un momento y despues CAE. El cliente se satura, deja de procesar, y se defiende con un pues suena bien todo, dejeme lo pienso.\\n\\nUna bala. Pausa. Ves como reacciona. Y de ahi decides la siguiente.","flip_back_text":null,"created_at":"2026-08-10T19:12:49.477173+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"cfc463fc-3f9a-4174-a1bb-19ba422cc9a7","node_id":"4.6","card_order":2,"card_type":"concept","title":"Concreta o no es bala","body":"Somos los mejores del mercado. Tenemos mucha calidad. Damos buen servicio.\\n\\nNinguna de esas mueve nada, porque cualquiera las dice y ninguna se puede comprobar.\\n\\nCatorce anos surtiendo esta zona. Entrega en veinticuatro horas dentro de la ciudad. Tres negocios de esta misma calle ya lo manejan.\\n\\nEsas si. Numeros, tiempos, hechos verificables.","flip_back_text":null,"created_at":"2026-08-10T19:12:49.477173+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ef325f28-05b0-49eb-8919-335b4da65cd2","node_id":"4.6","card_order":3,"card_type":"why_it_works","title":"Exagerar cuesta mas que callarse","body":"Cuando una bala suena demasiado buena, el cliente no se emociona: se pone esceptico. Y una vez que duda de un dato tuyo, empieza a dudar de todos.\\n\\nEl impulso construido con verdad se sostiene. El construido con exageracion se cae solo, y se lleva tu credibilidad de paso.\\n\\nSi no tienes una bala buena para ese momento, no inventes una. Usa la que si tienes.","flip_back_text":null,"created_at":"2026-08-10T19:12:49.477173+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f6d1c00a-38bd-4d9a-9cb6-73d4d4da2f83","node_id":"4.7","card_order":1,"card_type":"concept","title":"El impulso es otra palabra para la emocion","body":"Ya sabes que el impulso es del cliente: que tanto quiere comprar, en este momento.\\n\\nY no sube solo. Sube porque tu haces algo que lo mueve.\\n\\nHay seis maneras de moverlo. Se llaman FUJPIG, y las vas a practicar una por una en los nodos que siguen.","flip_back_text":null,"created_at":"2026-08-10T19:13:15.231174+00:00","card_content_type":"static","audience":null,"skill_ids":["impulse.curva_impulso"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"b54953b0-cd73-4a16-bdbc-2d6549a93b6e","node_id":"4.7","card_order":2,"card_type":"concept","title":"FUJPIG","body":"F — FEAR OF LOSS / Miedo a la perdida\\nU — URGENCY / Urgencia\\nJ — JONES EFFECT / Efecto Jones\\nP — POWER OF SUGGESTION / Poder de asumir\\nI — INDIFFERENCE / Indiferencia\\nG — GREED / Avaricia\\n\\nSeis. Ni una mas. Y funcionan combinadas: casi nunca vas a usar una sola.","flip_back_text":null,"created_at":"2026-08-10T19:13:15.231174+00:00","card_content_type":"static","audience":null,"skill_ids":["impulse.curva_impulso"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f1df78f6-dfb7-4be9-b331-1da9a263c8a1","node_id":"4.7","card_order":3,"card_type":"concept","title":"F y U: perder y ahora","body":"MIEDO A LA PERDIDA. La doctrina lo dice sin rodeos: el miedo a perder es mayor que la necesidad de ganar. A la gente le mueve mas no quedarse sin algo que la posibilidad de obtenerlo.\\n\\nURGENCIA. El movimiento crea emocion. Una decision que puede esperar, espera para siempre.\\n\\nLas dos van juntas casi siempre: que se le va, y por que se le va hoy.","flip_back_text":null,"created_at":"2026-08-10T19:13:15.231174+00:00","card_content_type":"static","audience":null,"skill_ids":["impulse.curva_impulso"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f5b023c0-4efb-44c7-9724-2f7dd625b9e9","node_id":"4.7","card_order":4,"card_type":"concept","title":"J y G: los otros y la ventaja","body":"EFECTO JONES. Viene de keeping up with the Joneses: la gente copia a la gente. Otros negocios como el suyo ya lo hacen. Ojo con esto — tiene que ser REAL y verificable. Inventarlo es la peor decision que puedes tomar.\\n\\nAVARICIA. La sensacion de estar obteniendo mas por menos. No es codicia fea: es la satisfaccion legitima de sentir que hiciste un buen trato.","flip_back_text":null,"created_at":"2026-08-10T19:13:15.231174+00:00","card_content_type":"static","audience":null,"skill_ids":["impulse.curva_impulso"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"bbeb7450-4102-4053-922b-f79823f1af8a","node_id":"4.7","card_order":5,"card_type":"concept","title":"P e I: asumir y no necesitar","body":"PODER DE ASUMIR. Diriges la conversacion hacia el resultado, dando por hecho el siguiente paso. Nada de preguntas de si o no: alternativas donde las dos opciones te sirven.\\n\\nINDIFERENCIA. Se lo opuesto a un vendedor. Emocionado con la persona y con el producto, indiferente a si compra. Suena raro y es lo que mas funciona: la presion genera resistencia, y quitar la presion la disuelve.","flip_back_text":null,"created_at":"2026-08-10T19:13:15.231174+00:00","card_content_type":"static","audience":null,"skill_ids":["impulse.curva_impulso"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c2a1b3d0-f7fb-4eba-80cb-b1c3365b9236","node_id":"4.7","card_order":6,"card_type":"why_it_works","title":"La linea que nunca se cruza","body":"Los seis factores son poderosos, y por eso hay una regla que no se negocia.\\n\\nEl impulso se construye con VERDAD. Urgencia que no existe, escasez inventada, otros clientes que nunca compraron: todo eso esta prohibido, y no por moral abstracta.\\n\\nEs practico: un impulso falso se derrumba en cuanto el cliente lo descubre, y se lleva la venta, la relacion y tu reputacion en la zona. En Closer eso cuenta como falla grave.","flip_back_text":null,"created_at":"2026-08-10T19:13:15.231174+00:00","card_content_type":"static","audience":null,"skill_ids":["impulse.curva_impulso"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"d63e25c4-e5a5-48f3-8964-e242cf07de4d","node_id":"4.8","card_order":1,"card_type":"concept","title":"El dolor de perder pesa el doble que el gusto de ganar.","body":"Así funciona la cabeza humana: perder $100 duele más que lo que alegra ganar $100. No es teoría — es cómo decidimos todos.\\n\\nPor eso el acelerador más potente no es \\"mire lo que va a ganar\\" — es \\"mire lo que ya está perdiendo\\". La diferencia: la ganancia es futura e hipotética. La pérdida está pasando HOY, mientras platican.","flip_back_text":null,"created_at":"2026-08-10T19:11:28.73134+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"a5438abd-6465-4bb4-b975-cd3fb41a2dc5","node_id":"4.8","card_order":2,"card_type":"concept","title":"Se construye con SUS números — no con tus adjetivos.","body":"Débil: \\"Está perdiendo mucho dinero con esos faltantes.\\"\\nPotente: \\"Usted me dijo que se le van dos clientes al mes. Son veinticuatro al año, Don Ramón — cada uno comprándole a la competencia. Y eso está pasando hoy.\\"\\n\\nLa receta: toma el dolor que Él te declaró, ponle números, ponle destino (¿a dónde se va esa pérdida?), y áncla en el presente. Su propio dato, devuelto con peso. Contra eso no hay \\"déjeme pensarlo\\" que aguante.","flip_back_text":null,"created_at":"2026-08-10T19:11:28.73134+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"e64e07f7-52d1-4957-a366-859f27220ad9","node_id":"4.8","card_order":3,"card_type":"concept","title":"Urgencia: razones reales para decidir HOY.","body":"La urgencia honesta existe y sobra — no hay que inventarla:\\n\\nTu ruta es real: \\"esta semana levanto los pedidos de la zona; si lo dejamos, su surtido llega hasta el mes que entra.\\"\\nSus ciclos son reales: \\"la quincena se le viene encima — ¿la quiere recibir surtido o esperando?\\"\\nLos tiempos son reales: \\"el pedido tarda una semana en llegar; decidiendo hoy, lo tiene antes del fin de semana bueno.\\"\\n\\nEl movimiento crea emoción. La fecha real crea decisión.","flip_back_text":null,"created_at":"2026-08-10T19:11:28.73134+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"38631ffc-47d9-431a-ba95-2af5e091a4d6","node_id":"4.8","card_order":4,"card_type":"why_it_works","title":"La línea roja: si no es verdad, no se dice.","body":"\\"Es el último que me queda.\\" \\"La promoción se acaba HOY.\\" \\"Ya me lo están apartando.\\"\\n\\nSi es verdad — dilo con todas sus letras. Si es teatro — el cliente lo huele (\\"eso dicen todos\\"), y la confianza que tardaste cuatro pasos en construir se quema en una frase. Y un cliente que te cachó una vez, te descuenta TODO lo que digas después.\\n\\nEn Closer, los aceleradores corren con gasolina de verdad. Es más lento de conseguir — y es lo único que no explota.","flip_back_text":null,"created_at":"2026-08-10T19:11:28.73134+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"72a8e672-8780-4940-bc98-c2da1e62017a","node_id":"4.9","card_order":1,"card_type":"concept","title":"Más por menos: la ganancia que se siente ganga.","body":"A todos nos gusta ganar de más — es humano. El acelerador de la avaricia no es codicia: es mostrarle al cliente la ganancia EXTRA que hoy no está viendo.\\n\\nDébil: \\"le conviene, va a ganar más.\\"\\nPotente: \\"cada caja le deja ochenta pesos más que la que maneja — son mil doscientos extra al mes sin vender una pieza más.\\"\\n\\nLa regla: números que ÉL pueda verificar con sus propias cuentas. Cuando el cliente hace la cuenta en voz alta... el acelerador ya está trabajando solo.","flip_back_text":null,"created_at":"2026-08-10T19:11:29.621725+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c6cc9e96-bfbd-4a0a-94e7-b153dd9346bd","node_id":"4.9","card_order":2,"card_type":"concept","title":"El Efecto Jones: nadie quiere quedarse fuera.","body":"Es la fuerza más vieja del mundo: si al de al lado le está funcionando, yo también quiero. En los negocios pesa doble — porque quedarse fuera no es solo antojo: es la competencia ganándote clientes.\\n\\n\\"La negocios de la San José le entró hace dos meses — don Aurelio ya va en su tercer pedido.\\"\\n\\nNombre, lugar, tiempo, resultado. El cliente lo puede ubicar, hasta preguntarle. Eso es prueba social — lo demás es rumor.","flip_back_text":null,"created_at":"2026-08-10T19:11:29.621725+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"41dcedd3-9549-404f-883f-931843437dc6","node_id":"4.9","card_order":3,"card_type":"why_it_works","title":"La prueba del \\"¿como quiénes?\\"","body":"Di \\"muchos negocios ya lo están llevando\\" y el cliente escéptico te va a soltar la pregunta que desnuda todo: \\"¿ah sí? ¿como quiénes?\\"\\n\\nSi tienes nombres reales — la pregunta es tu mejor amiga: la respondes y la confianza sube en el acto. Si no los tienes — acabas de quemar el factor y de paso tu credibilidad.\\n\\nPor eso el Jones se prepara ANTES de salir: ¿qué clientes reales de esta zona ya me compran? ¿qué resultados concretos puedo contar? Esa lista vale más que cualquier técnica.","flip_back_text":null,"created_at":"2026-08-10T19:11:29.621725+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"7b7eb190-fc0d-4e4a-a4bd-01b68c21e624","node_id":"5.0","card_order":1,"card_type":"concept","title":"El cierre no es magia. Es una decisión con fecha de hoy.","body":"Cerrar no significa vender siempre. Significa EXTRAER UNA DECISIÓN: un sí, un no claro, un pedido concreto — algo que mueva la conversación de \\"algún día\\" a \\"hoy se decidió algo\\".\\n\\nEl peor resultado de una visita no es el no. Es el \\"déjeme pensarlo\\" eterno — la decisión sin fecha que se muere sola y te tiene regresando de a gratis.","flip_back_text":null,"created_at":"2026-08-10T19:26:07.52246+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"657a9e21-2b38-480a-afea-b5bdb9114030","node_id":"5.0","card_order":2,"card_type":"concept","title":"Los cierres que matan","body":"\\"¿Entonces qué piensa?\\" — le pediste un veredicto sobre TODO. Abrumador.\\n\\"¿Le interesa?\\" — pregunta de sí/no con el no gratis.\\n\\"¿Quiere que le deje información?\\" — acabas de proponer TÚ el aplazamiento.\\n\\"Bueno, ahí me avisa cualquier cosa...\\" — ni siquiera es una pregunta. Es una despedida.\\n\\n¿El patrón? Todos le abren la puerta al no — o peor, al limbo. Y el cliente, ante una puerta abierta, la usa. No por malo: por humano.","flip_back_text":null,"created_at":"2026-08-10T19:26:07.52246+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"aa0ffa4c-6a34-454a-9eaa-eeae55fbd071","node_id":"5.0","card_order":3,"card_type":"concept","title":"Los cierres que funcionan: asumidos, con opciones.","body":"\\"¿Empezamos con 5 cajas o le acomodo el combo de 8?\\"\\n\\"¿Le entrego el lunes o mejor el miércoles?\\"\\n\\"¿Se lo facturo o va con nota?\\"\\n\\nFíjate en la mecánica: la decisión de FONDO (comprar) ya se asume — la conversación entera la construyó. La pregunta es sobre los DETALLES, y cualquier respuesta que elija... es un sí.\\n\\nEn Closer esta regla es total: TODOS los cierres son asumidos. Sin excepción.","flip_back_text":null,"created_at":"2026-08-10T19:26:07.52246+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"e375a670-f04a-45a6-88ac-44a877125914","node_id":"5.0","card_order":4,"card_type":"why_it_works","title":"¿Y no es manipulación?","body":"No — si hiciste el trabajo. El cierre asumido es la CONSECUENCIA natural de una conversación donde el cliente conectó su dolor, hizo la cuenta, asintió tres veces y preguntó cuándo entregas. Preguntarle \\"¿le interesa?\\" después de todo eso es ofenderlo — él ya te lo dijo de cinco formas.\\n\\nAhora, si NO hiciste el trabajo — sin valor, sin síes, sin señales — el cierre asumido se siente como atropello y el cliente te frena. El cierre no arregla una mala conversación. Solo cosecha una buena.","flip_back_text":null,"created_at":"2026-08-10T19:26:07.52246+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"d6a4664b-6a07-48f1-b7f3-6feafcf96a0e","node_id":"5.1","card_order":1,"card_type":"concept","title":"El momento maduro se ve así:","body":"El cliente recapitula solo: \\"pues sí, la cuenta sale... y ya me tiene harto quedarme sin producto.\\" Preguntó cada cuánto surtes. Asintió tres veces.\\n\\nLa decisión grande YA ESTÁ TOMADA — la tomó la conversación. Lo único que falta es que alguien la pregunte bien. Y \\"bien\\" significa: asumida, con opciones, sobre los detalles.\\n\\n\\"¿Le armo las 5 cajas o el combo de 8?\\" Cualquier respuesta es un sí.","flip_back_text":null,"created_at":"2026-08-10T19:26:06.426804+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"e9d87f31-4421-404f-a740-1786aedfc025","node_id":"5.1","card_order":2,"card_type":"bad_example","title":null,"body":"Ejemplo de cierre con puerta al no aplicado al contexto de la empresa: pregunta de interés o veredicto tras una conversación que ya había construido el sí.","flip_back_text":"La pregunta de interés reabre una decisión que ya estaba tomada — y le ofrece al cliente la salida cómoda del \\"déjeme pensarlo\\".","created_at":"2026-08-10T19:26:06.426804+00:00","card_content_type":"dynamic","audience":null,"skill_ids":["closing.cierre_asumido"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"cb6af89d-6fab-4245-8e5d-e3c0d9ccf045","node_id":"5.1","card_order":3,"card_type":"good_example","title":null,"body":"Ejemplo de cierre asumido aplicado al contexto de la empresa: pregunta de opciones concretas sobre detalles del pedido, referenciando lo construido en la conversación.","flip_back_text":"La decisión de fondo se asume — la construyó la conversación. La pregunta es sobre el detalle, y elegir cualquier opción es decir sí.","created_at":"2026-08-10T19:26:06.426804+00:00","card_content_type":"dynamic","audience":null,"skill_ids":["closing.cierre_asumido"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"e918feda-3732-4022-8ad8-b723ba37f359","node_id":"5.10","card_order":1,"card_type":"concept","title":"Los tres movimientos del circulo","body":"Cuando llega la objecion:\\n\\n1. ATRAVIESA — con RRR si es menor, con FFF si es de verdad.\\n2. RE-IMPULSA — una bala NUEVA, algo positivo que no habias dicho.\\n3. CIERRA CON ACCION — el siguiente paso concreto.\\n\\nEn ese orden y sin saltarse el dos.","flip_back_text":null,"created_at":"2026-08-10T19:29:14.267277+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.circulo_cierre"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"404678cf-304a-4e04-9e87-149825a7ad72","node_id":"5.10","card_order":2,"card_type":"concept","title":"El paso que todos se saltan","body":"Es tan natural saltarselo que hay que decirlo directo: atravesar una objecion NO sube el impulso. Solo detiene la caida.\\n\\nSi atraviesas y cierras de inmediato, le estas pidiendo una decision a alguien que sigue abajo. Y desde ahi la respuesta comoda siempre es dejeme lo pienso.\\n\\nLa bala es lo que lo vuelve a subir. Sin ella, tecnicamente respondiste y practicamente perdiste.","flip_back_text":null,"created_at":"2026-08-10T19:29:14.267277+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.circulo_cierre","objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"62cc8fb8-f451-4bd5-99e4-e9f2d7a4bf69","node_id":"5.10","card_order":3,"card_type":"why_it_works","title":"Nueva, no repetida","body":"Y tiene que ser una bala que NO hayas dicho antes.\\n\\nRepetir un argumento que ya usaste no sube nada: le comunica al cliente que ya no tienes mas, y eso baja el impulso en lugar de subirlo.\\n\\nAqui es donde por fin se entiende lo de dosificar. El vendedor que gasto todo su arsenal presumiendo al principio llega a este momento con la mano vacia.","flip_back_text":null,"created_at":"2026-08-10T19:29:14.267277+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.circulo_cierre","objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"7e03807a-6a88-459b-9075-e1d49656646c","node_id":"5.11","card_order":1,"card_type":"concept","title":"Avanzar tiene un limite","body":"Todo este mundo te ha ensenado a seguir: atraviesa, re-impulsa, vuelve a cerrar.\\n\\nPero hay un punto donde seguir deja de construir y empieza a quemar. Y saber donde esta ese punto es tan importante como saber cerrar.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.regla_no"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"b6c0c67a-4210-4cec-b47e-6992c6ef46bf","node_id":"5.11","card_order":2,"card_type":"concept","title":"La regla: tres no SEGUIDOS","body":"La doctrina original dice dos no y te vas. Nosotros usamos tres, y hay una razon: hay vendedores que dejan ir un si solo porque el cliente tuvo un par de preguntas.\\n\\nTIENEN QUE SER CONSECUTIVOS. Uno tras otro, sin que la conversacion haya avanzado en medio.\\n\\nUn no, lo atraviesas, avanzas, y despues otro no: eso NO es una racha. Eso es una conversacion normal.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.regla_no"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"757d8b43-63a2-481c-b22b-2f410821bed3","node_id":"5.11","card_order":3,"card_type":"why_it_works","title":"Soltar bien es parte del oficio","body":"Cuando llegan los tres seguidos, ese cliente se volvio rojo. No es fracaso tuyo: es informacion.\\n\\nY la manera de irte importa. El que insiste hasta incomodar quema la relacion y ya no lo reciben. El que reconoce la situacion y deja la puerta abierta, vuelve cuando las cosas cambien.\\n\\nCada minuto de mas con un rojo se lo estas quitando a un amarillo que si podia comprar hoy.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.regla_no","qualification.luz_verde"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"25ec99c5-19e3-4298-81ec-7cf041612b82","node_id":"5.11","card_order":4,"card_type":"concept","title":"Un no aislado no es nada","body":"Lo mas importante de la regla es la palabra SEGUIDOS.\\n\\nEl cliente dice que no, lo atraviesas, la conversacion avanza, hablan de otra cosa, y mas adelante dice otro no. Eso NO son dos no seguidos: es una conversacion normal con dos momentos de friccion.\\n\\nLa racha se rompe en cuanto la conversacion avanza. Solo cuentan los que llegan uno tras otro, sin que hayas logrado mover nada en medio.","flip_back_text":null,"created_at":"2026-08-10T19:29:45.501549+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.regla_no"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"65f40cf1-b519-4e00-bc13-1f49ccadb723","node_id":"5.12","card_order":1,"card_type":"concept","title":"Las objeciones cazan en manada.","body":"Resolviste \\"está caro\\" con tu mejor cuenta... y el cliente suelta: \\"sí, pero es que además ya tengo proveedor de años.\\" Y detrás de esa, puede venir otra.\\n\\nNo es mala señal — es su proceso: está sacando TODAS sus dudas antes del sí. La cadena es la antesala de la decisión.\\n\\nTu examen doble: cada objeción con SU bala (la repetida no convence, la apilada abruma) — y tu ánimo idéntico en la primera y en la última. El cliente está midiendo tu temple tanto como tus respuestas.","flip_back_text":null,"created_at":"2026-08-10T19:26:02.122239+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f49f1b36-4d9b-4fc5-9c9a-2788596ceb3f","node_id":"5.13","card_order":1,"card_type":"concept","title":"El momento donde más ventas se suicidan","body":"Cerraste bien: \\"¿le armo las 5 o el combo de 8?\\" Y el cliente... se queda callado. Piensa.\\n\\nTres segundos de silencio. Cinco. Pesan como losas — y el miedo te susurra: \\"di algo, se está arrepintiendo, ofrécele algo más chico...\\"\\n\\nMentira. Está DELIBERANDO. Ese silencio es su proceso de decir que sí — y el único que puede arruinarlo eres tú.","flip_back_text":null,"created_at":"2026-08-10T19:26:01.110478+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"7806af4a-682f-43b8-9145-8298afe3da23","node_id":"5.13","card_order":2,"card_type":"concept","title":"El que habla primero, pierde.","body":"\\"Bueno, si le parece mucho también hay de 3 cajas... o si quiere lo piensa...\\"\\n\\n¿Qué acaba de pasar? El vendedor deshizo SU PROPIO cierre. El cliente no había dicho nada — iba a decir que sí — y el vendedor le sembró la duda, le achicó el pedido y le regaló la salida. Todo por no aguantar cinco segundos.\\n\\nLa regla es brutal de simple: cierras... y te callas. El silencio es del cliente. Respétalo.","flip_back_text":null,"created_at":"2026-08-10T19:26:01.110478+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"2114a198-9ae2-4345-8d97-fee2d7c1922e","node_id":"5.13","card_order":3,"card_type":"why_it_works","title":"La decisión que él toma solo, es la que no se cae.","body":"Cuando aguantas el silencio, el cliente termina su deliberación y decide él — y una decisión propia se defiende sola: no hay remordimiento, no hay \\"me presionaron\\", no hay cancelación mañana.\\n\\nCuando llenas el silencio, aunque cierre, la decisión quedó contaminada de tu ansiedad — y esas son las ventas que se caen a la semana.\\n\\nEn este reto el cliente va a pensar de verdad. Tu examen no es hablar bien. Es callarte mejor.","flip_back_text":null,"created_at":"2026-08-10T19:26:01.110478+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"fd271d90-cd3b-46a8-881b-624c7c56c01a","node_id":"5.14","card_order":1,"card_type":"concept","title":"El pedido base no esta en duda","body":"Con un cliente nuevo cierras la venta completa: o compra o no compra.\\n\\nCon uno que ya te compra, el pedido de siempre ya iba a existir. No lo estas ganando: ya era tuyo antes de que llegaras.\\n\\nLo que si esta en juego es lo que agregaste. Las cajas de mas. La familia nueva. ESO es lo que hay que cerrar.","flip_back_text":null,"created_at":"2026-08-19T14:33:53.507494+00:00","card_content_type":"static","audience":null,"skill_ids":["closing.cerrar_incremento"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"670d7d50-e1bf-4a19-8f25-e7f21a289dc6","node_id":"5.14","card_order":2,"card_type":"why_it_works","title":"Reabrir lo que ya estaba es un error caro","body":"Suena razonable confirmar todo al final: entonces si le mando lo de siempre mas lo nuevo?\\n\\nY lo que haces es poner en la mesa algo que ya estaba resuelto. El cliente empieza a revisar la orden completa, y de pronto tambien duda de lo que nunca habia dudado.\\n\\nLo que ya esta, se queda quieto. Solo cierras lo que agregaste.","flip_back_text":null,"created_at":"2026-08-19T14:33:53.507494+00:00","card_content_type":"static","audience":null,"skill_ids":["closing.cerrar_incremento"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"1af3d989-1a74-49d0-904c-a713d3128c55","node_id":"5.14","card_order":3,"card_type":"concept","title":"Alternativas sobre el incremento","body":"Se las mando en la misma entrega o prefiere aparte?\\nLe pongo las cinco cajas o arrancamos con tres?\\nSe lo manejo igual que siempre a credito, o esta vez de contado?\\n\\nLas tres asumen que el incremento va. Ninguna pregunta si lo quiere.\\n\\nY las dos opciones de cada una te sirven — no hay respuesta que te deje sin venta.","flip_back_text":null,"created_at":"2026-08-19T14:33:53.507494+00:00","card_content_type":"static","audience":null,"skill_ids":["closing.cerrar_incremento"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f5348a85-150d-4234-bb99-5986edde8874","node_id":"5.15","card_order":1,"card_type":"concept","title":"El octavo Boss.","body":"A este señor le prometieron y le fallaron — varias veces. Su escudo tiene años de grosor y una frase grabada: \\"eso mismo me dijo el anterior.\\"\\n\\nTe espera todo: un bloqueo en la puerta, un dolor que él mismo minimiza (\\"así es esto, todos fallan igual\\"), y la cadena final con la objeción más personal del campo: \\"¿y por qué le voy a creer a USTED?\\"\\n\\nCada bala tuya va a pasar por su lupa. Cada promesa sin ancla lo cierra un poco más. Y si lo logras, su rendición será a su manera: \\"le tomo la palabra — y lo apunto.\\" No pelees su condición de prueba: hónrala. Ese pedido chico por escrito ES tu victoria — la confianza del desconfiado no se gana en una visita. Se gana cumpliéndole.","flip_back_text":null,"created_at":"2026-08-19T14:33:00.376205+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"71a76aa5-e697-493b-beeb-8a558df30dfd","node_id":"5.2","card_order":1,"card_type":"concept","title":"El cliente te avisa","body":"Antes de decir que si, la gente manda senales. No lo hace a proposito ni se da cuenta.\\n\\nSon ocho, y se llaman FISHBBOD. Tambien se les dice senales de alto, porque cuando aparecen tu presentacion tiene que DETENERSE.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["qualification.senales_compra"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"326f64e4-b705-4027-84d2-bdf03cc9719f","node_id":"5.2","card_order":2,"card_type":"concept","title":"FISHBBOD","body":"F — FUTURE TALK / Habla del futuro: ya se imagina teniendolo\\nI — I WANT, I NEED / Quiero, necesito: lo dice en voz alta\\nS — SILENCE / Silencio: se queda pensando, calculando\\nH — HOW MUCH, HOW SOON / Cuanto, cuando: pregunta condiciones\\nB — BODY LANGUAGE / Lenguaje corporal: se acerca, toma el producto\\nB — BASHING COMPETITOR / Desacredita a su proveedor actual\\nO — OFFERS OF COURTESY / Ofertas de cortesia: te ofrece cafe, una silla\\nD — DEEPER QUESTIONS / Preguntas mas profundas: entra en detalle","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["qualification.senales_compra"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"cfe9944c-0368-4e68-8649-4813c9823e10","node_id":"5.2","card_order":3,"card_type":"concept","title":"Las mas faciles de leer","body":"HABLA DEL FUTURO — y donde me lo entregarian? / si lo pido, cada cuanto surten?\\n\\nSILENCIO — se queda callado calculando. No lo llenes: esta decidiendo.\\n\\nCUANTO Y CUANDO — cuanto seria lo minimo? para cuando lo tendria?\\n\\nDESACREDITA A SU PROVEEDOR — justo antes de cambiar, la gente se justifica sola. Es de las senales mas fuertes.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["qualification.senales_compra"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"8ba7cd0d-c220-4f2c-a1c1-b7c80fb27f71","node_id":"5.2","card_order":4,"card_type":"why_it_works","title":"Que hacer cuando la ves: DETENTE","body":"Aqui esta el error que cuesta mas ventas de las que nadie cree.\\n\\nEl cliente da una senal, el vendedor la ve, y como todavia le quedaban dos argumentos buenos, los suelta.\\n\\nY el impulso BAJA. Porque el cliente ya estaba listo, y seguir vendiendole le comunica que hay algo que convencerlo, o peor, le da tiempo de encontrar una razon para no hacerlo.\\n\\nSenal de compra = deja de presentar y cierra. Aunque te queden balas. De hecho, sobre todo si te quedan.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["qualification.senales_compra"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"42a2b2cf-d262-493e-925d-46958a3ad28d","node_id":"5.3","card_order":1,"card_type":"concept","title":"La señal no espera a que termines.","body":"Vas a la mitad de tu presentación — te faltan tres beneficios del guion — y el cliente suelta: \\"¿y si le pido hoy, cuándo me llega?\\"\\n\\nEso NO es una interrupción. Es la señal de compra: ya se está imaginando el pedido en su bodega. Su curva llegó al pico AHORITA — no cuando tú termines.\\n\\nY el pico no espera. Cada beneficio extra que agregues después de la señal es cuesta abajo.","flip_back_text":null,"created_at":"2026-08-10T19:26:05.388789+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"8f4b8dbb-54ba-4109-8f69-658719bbea25","node_id":"5.3","card_order":2,"card_type":"concept","title":"La disciplina: cállate y cierra.","body":"Suena fácil. No lo es — traes el guion en la cabeza, los beneficios que ensayaste, la sensación de que \\"falta explicar más.\\"\\n\\nLa regla cuando aparece la señal: (1) DETENTE — el guion muere ahí, sin duelo. (2) HONRA la señal — responde lo puntual que preguntó: \\"le llega el lunes a primera hora.\\" (3) CIERRA asumido en la misma respiración: \\"¿le armo las 5 o el combo de 8?\\"\\n\\nSeñal → dato → cierre. Tres segundos. Lo demás del guion... que descanse en paz.","flip_back_text":null,"created_at":"2026-08-10T19:26:05.388789+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"3fe48414-45b1-438e-996d-101ff989e0d3","node_id":"5.3","card_order":3,"card_type":"why_it_works","title":"Sobre-presentar mata tantas ventas como presentar mal.","body":"¿Por qué duele tanto seguir hablando? Porque el cliente en el pico ya DECIDIÓ — y cada argumento nuevo le da material para re-evaluar. \\"¿Y además tiene esta otra característica?\\" — \\"mmm, ¿y esa para qué la quiero yo?\\" La duda que no existía, la sembraste tú.\\n\\nEn este reto, el cliente va a soltar la señal a mitad de tu presentación. Si la cosechas, cierras en tres frases. Si sigues con tu guion... vas a ver — en vivo — cómo se enfría un pico. Y esa lección no se olvida.","flip_back_text":null,"created_at":"2026-08-10T19:26:05.388789+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"bc73d0a4-8616-43a8-9767-fcd367a8b980","node_id":"5.4","card_order":1,"card_type":"concept","title":"La objeción es una buena noticia disfrazada.","body":"\\"Está caro.\\" \\"Ya tengo proveedor.\\" \\"Déjeme consultarlo.\\"\\n\\n¿Sabes qué tienen en común? El cliente ENTENDIÓ tu oferta, la está considerando en serio... y te está diciendo exactamente qué le falta para decir que sí.\\n\\nAl cliente que no le importa no objeta — te da un \\"gracias, ahí lo pensamos\\" y te despide sonriendo. El que objeta está negociando consigo mismo enfrente de ti. Una objeción bien respondida ES una venta.","flip_back_text":null,"created_at":"2026-08-10T19:26:04.107963+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"1995d476-bd3e-48ac-99f3-fae8af7ba9a9","node_id":"5.4","card_order":2,"card_type":"concept","title":"Repaso: el \\"no\\" tiene dos especies.","body":"BLOQUEO — el reflejo pre-comprensión: \\"no me interesa\\" antes de saber qué traes. Se atraviesa con AIR: dale la razón, ignóralo, retoma. Ya lo dominas desde el Mundo 2.\\n\\nOBJECIÓN — el \\"no\\" razonado post-comprensión: entendió tu oferta y tiene un motivo concreto. Y aquí está lo importante: AIR NO APLICA. Ignorar una objeción real y cambiar de tema es faltarle al respeto a alguien que te habló en serio — y la confianza se rompe ahí mismo.\\n\\nBloqueo → AIR. Objeción → reencuadre. Confundirlos sale carísimo en ambas direcciones.","flip_back_text":null,"created_at":"2026-08-10T19:26:04.107963+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"09b39da2-9e2a-4e65-bc4c-8135a91578be","node_id":"5.4","card_order":3,"card_type":"concept","title":"\\"Ya tengo proveedor\\" — la objeción que no es un no.","body":"Escúchala con oídos de sistema: te acaba de decir que SÍ COMPRA este tipo de producto, que YA le paga a alguien por él, y que ese alguien tiene un lugar que tú puedes disputar.\\n\\n\\"Ya tengo proveedor\\" es INFORMACIÓN — de la mejor. No respondas defendiendo; responde interesándote: \\"Qué bueno — ¿y qué tal se porta con los tiempos de entrega?\\" Cada respuesta te dirá exactamente por dónde entra tu oportunidad. Porque ningún proveedor es perfecto — y su cliente lo sabe mejor que nadie.","flip_back_text":null,"created_at":"2026-08-10T19:26:04.107963+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f97f2ce9-afa4-4aaa-8e07-5f28fd2cf712","node_id":"5.4","card_order":4,"card_type":"why_it_works","title":"La estructura del reencuadre","body":"Toda objeción se trabaja igual, cuatro pasos:\\n\\nRECIBE sin pelear — \\"claro, entiendo\\" genuino. La defensa instantánea confirma sus miedos.\\nENTIENDE qué hay detrás — a veces con una pregunta: ¿caro comparado con qué?\\nRESPONDE con una bala — un hecho concreto y verificable, no un discurso.\\nAVANZA — la objeción respondida no se queda ahí a enfriarse: re-cierras.\\n\\nLas balas — tu munición de hechos — son el siguiente nodo. Porque un reencuadre sin bala es pura labia.","flip_back_text":null,"created_at":"2026-08-10T19:26:04.107963+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"30547a5c-53bd-491a-b2d7-00d326f5b1dc","node_id":"5.5","card_order":1,"card_type":"concept","title":"Ojo: este RRR no es el otro","body":"En el Descubrimiento aprendiste RRR — Read, Relate, Relax: leer al cliente y ajustar tu ritmo.\\n\\nEste es otro RRR distinto, con las mismas siglas. Asi viene en la doctrina original y por eso lo conservamos con su nombre.\\n\\nR — REPEAT / Repite\\nR — REASSURE / Tranquiliza\\nR — RESUME / Retoma\\n\\nAquel sirve para leer personas. Este sirve para atravesar objeciones menores.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.rrr_objeciones"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"7ce3b7b4-b360-4902-8d60-f09331859de9","node_id":"5.5","card_order":2,"card_type":"concept","title":"Para las de todos los dias","body":"Hay objeciones que salen una y otra vez y no son graves: una duda de plazo, una comparacion rapida, algo que solo necesita una respuesta clara.\\n\\nPara esas es RRR.\\n\\nREPITE la objecion, para que vea que la escuchaste. TRANQUILIZA con la respuesta concreta. Y RETOMA donde ibas.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.rrr_objeciones"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"d1d59b59-c342-4330-ba06-c87904dd2633","node_id":"5.5","card_order":3,"card_type":"why_it_works","title":"La tercera R es la que casi nadie hace","body":"Repetir y responder es facil. Lo que falla siempre es lo que viene despues.\\n\\nEl vendedor responde bien... y se queda callado esperando a ver si la respuesta le gusto. En ese silencio el cliente encuentra la siguiente objecion, o simplemente dice que lo va a pensar.\\n\\nRetomar significa seguir de largo, en la misma respiracion, como si la objecion hubiera sido un comentario mas. Sin pausa.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.rrr_objeciones","flow.close_with_action"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"345b2d07-0ea7-4fac-8dbc-f7c3239be599","node_id":"5.5","card_order":4,"card_type":"why_it_works","title":"Cuando NO usar RRR","body":"RRR es para dudas de tramite: plazos, condiciones, garantias, formas de pago. Cosas que solo necesitan un dato claro.\\n\\nSi la usas para algo que de verdad le preocupa al cliente — que le fallaron antes, que anda apretado de dinero, que quedo mal con sus propios clientes — se siente a que lo despachaste.\\n\\nPara esas hay otra herramienta, y es la del siguiente nodo.","flip_back_text":null,"created_at":"2026-08-10T19:29:45.501549+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.rrr_objeciones"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"d37377f9-7d12-47e4-896d-43775f87cc01","node_id":"5.6","card_order":1,"card_type":"concept","title":"Los tres movimientos","body":"REPITE — en sus propios terminos. Entiendo, le preocupa el plazo de entrega. Con eso ya sabe que lo escuchaste.\\n\\nTRANQUILIZA — la respuesta concreta. Nada de generalidades: un dato, un tiempo, una condicion.\\n\\nRETOMA — sigues, en la misma respiracion. Sin esperar a ver si le convencio.","flip_back_text":null,"created_at":"2026-08-10T19:29:14.267277+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.rrr_objeciones"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"81e37fb3-f6bc-4cbd-a660-81cc683c2ecf","node_id":"5.6","card_order":2,"card_type":"bad_example","title":null,"body":"Ah no, para nada, nosotros nunca fallamos con las entregas, somos muy cumplidos, de verdad no se preocupe por eso.","flip_back_text":"Se defendio. Y la defensa confirma que hay algo que defender. Ademas no dio ni un dato concreto: puras afirmaciones que cualquiera diria. El cliente se queda con la misma duda y ahora ademas incomodo.","created_at":"2026-08-10T19:29:14.267277+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.rrr_objeciones"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, '{"id":"5c543b85-1e2a-449a-8dcb-c0d256a1f4c2","node_id":"5.6","card_order":3,"card_type":"good_example","title":null,"body":"Entiendo, le preocupa el plazo. Dentro de la ciudad entregamos en veinticuatro horas, y si pide antes de mediodia sale el mismo dia. Y digame, cuantas cajas maneja usted al mes normalmente?","flip_back_text":"Repitio, respondio con datos concretos, y siguio sin pausa. Fijate en que no pregunto si asi si le parece bien: eso habria abierto la puerta a otra duda. Retomo el control y avanzo.","created_at":"2026-08-10T19:29:14.267277+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.rrr_objeciones","flow.close_with_action"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ed47332e-4d6b-4032-a11c-39307553dc80","node_id":"5.7","card_order":1,"card_type":"concept","title":"Cuando la objecion es de verdad","body":"A veces lo que el cliente pone sobre la mesa no es un tramite. Es algo que le preocupa de verdad: le fallaron antes, tiene el flujo apretado, lo quemaron con una promesa.\\n\\nAhi RRR se queda corto. Responder rapido y seguir se siente a que no lo escuchaste.\\n\\nPara esas existe FFF.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.fff"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c6646ef3-6c7f-4f6d-8b5a-a4fa3c38e13d","node_id":"5.7","card_order":2,"card_type":"concept","title":"FFF: Feel, Felt, Found","body":"F — FEEL / Entiendo\\nF — FELT / Sintio\\nF — FOUND / Encontramos\\n\\nEntiendo perfecto lo que me dice. Mi ultimo cliente sentia lo mismo. Y a lo que llegamos fue...\\n\\nY ojo con esto, porque es lo que casi nadie sabe: FFF no termina en la tercera F. El procedimiento completo son CINCO pasos.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.fff"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"78e22be5-0359-4737-a3ca-340945cdf49e","node_id":"5.7","card_order":3,"card_type":"concept","title":"Los tres primeros, uno por uno","body":"ENTIENDO — estar de acuerdo con el te vuelve distinto del vendedor promedio, y por eso te escucha. Nunca discutas con un cliente: ganar la discusion es perder la venta.\\n\\nSINTIO — mi ultimo cliente sentia lo mismo. Le dice que no esta solo y que su preocupacion es normal.\\n\\nENCONTRAMOS — y a lo que llegamos fue. Aqui va la razon por la que otros como el cambiaron de opinion. Fijate que esto ES el Efecto Jones en accion.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.fff","impulse.efecto_jones"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"5c5cb4a3-eaf1-4655-bc41-049151f4fe4d","node_id":"5.7","card_order":4,"card_type":"concept","title":"Y los dos que faltan","body":"PASO 4 — INSERTA TRES BALAS. La objecion tumbo el impulso. Responderla solo evita que siga cayendo. Lo que lo vuelve a subir son hechos positivos nuevos. Aqui es donde entiendes por que se guardan.\\n\\nPASO 5 — CIERRA CON ACCION. No preguntes si ya quedo claro. Muevelo al siguiente paso.\\n\\nCinco pasos. El que se queda en tres respondio la objecion y perdio la venta.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.fff","objections.bullet_theory","flow.close_with_action"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c49ce533-92b5-4384-b17b-7fe1ca7dc690","node_id":"5.8","card_order":1,"card_type":"concept","title":"Hoy te toca una de verdad.","body":"El cliente entendió tu oferta, le interesa — y trae una objeción real: el precio, su proveedor de años, o el socio al que consulta todo.\\n\\nRecuerda la secuencia: RECIBE sin pelear. ENTIENDE qué hay detrás. RESPONDE con una bala — una sola, la del cargador correcto. AVANZA.\\n\\nY la trampa a evitar: tu instinto del Mundo 2 va a querer aplicar AIR. NO. Esto no es un reflejo — es una persona hablándote en serio. Respóndele en serio.","flip_back_text":null,"created_at":"2026-08-10T19:26:03.117083+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"429cfc37-f96d-4a61-8bdd-4d1eb686ebd3","node_id":"5.8","card_order":2,"card_type":"concept","title":"Los cinco pasos, en orden","body":"1. ENTIENDO — valida de verdad, sin peros.\\n2. SINTIO — mi ultimo cliente sentia lo mismo.\\n3. ENCONTRAMOS — la razon por la que cambio de opinion.\\n4. TRES BALAS — hechos positivos nuevos para volver a subir el impulso.\\n5. CIERRA CON ACCION — el siguiente paso concreto.\\n\\nEn este drill practicas los tres primeros a fondo. Los dos ultimos los vas a integrar mas adelante.","flip_back_text":null,"created_at":"2026-08-10T19:29:45.501549+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.fff"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"273ffa6c-fbf4-42c3-873a-0c0e598dc374","node_id":"5.8","card_order":3,"card_type":"why_it_works","title":"Nunca discutas con un cliente","body":"Es la regla que sostiene toda la tecnica.\\n\\nCuando alguien te dice que le fallaron antes, la reaccion natural es defenderte: nosotros no somos asi, eso con nosotros no pasa. Y en ese momento lo pusiste a el en el papel de tener que defender su experiencia.\\n\\nEstar de acuerdo primero te vuelve distinto del vendedor promedio, y por eso te escucha. Ganar la discusion es perder la venta.","flip_back_text":null,"created_at":"2026-08-10T19:29:45.501549+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.fff"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"faf868e6-20d0-44b3-aeca-5b28398bccc8","node_id":"5.9","card_order":1,"card_type":"concept","title":"El circuito","body":"Ya tienes todas las piezas. Asi se arman:\\n\\nCIERRAS CON ACCION.\\nSi llega una objecion, el impulso BAJA.\\nLa atraviesas con RRR o con FFF.\\nRE-IMPULSAS con una bala nueva.\\nY CIERRAS CON ACCION otra vez.\\n\\nY si llega otra objecion, vuelves a girar. Eso es el Circulo de Cierre.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.circulo_cierre"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"0a64d11b-7524-490a-acc3-c5a80c3eda34","node_id":"5.9","card_order":2,"card_type":"concept","title":"Por que el orden importa","body":"El error mas comun de todos los que veras en este mundo: atravesar la objecion y cerrar de inmediato, saltandose la bala.\\n\\nTecnicamente respondiste. Pero el impulso quedo abajo, y estas pidiendo una decision en el punto mas bajo de la conversacion.\\n\\nAtravesar detiene la caida. La bala vuelve a subir. Cerrar sin ese paso intermedio es pedirle a alguien desanimado que decida.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.circulo_cierre","objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"6cd590d3-e717-418b-8dd6-88803cf2d78c","node_id":"5.9","card_order":3,"card_type":"why_it_works","title":"Aqui se entiende lo de guardar municion","body":"Cada vuelta del circulo te consume una bala.\\n\\nSi disparaste todo tu arsenal en la presentacion porque querias impresionar, llegas a la tercera objecion sin nada nuevo que decir. Repites lo mismo, y repetir no sube el impulso: lo desgasta.\\n\\nEl vendedor que dosifico llega a la tercera vuelta con municion fresca. Por eso gana conversaciones que el otro pierde.","flip_back_text":null,"created_at":"2026-08-10T19:27:36.121411+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.circulo_cierre","objections.bullet_theory"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"d1e08e22-45a5-42f3-925a-b8d0c0927e08","node_id":"5.9","card_order":4,"card_type":"concept","title":"Cuantas vueltas aguanta","body":"El circulo puede girar varias veces en una misma conversacion, y eso es normal: cada vuelta que completas bien te acerca.\\n\\nPero no es infinito. Hay un limite, y saber donde esta es tan importante como saber girar.\\n\\nEse limite es el siguiente nodo.","flip_back_text":null,"created_at":"2026-08-10T19:29:45.501549+00:00","card_content_type":"static","audience":null,"skill_ids":["objections.circulo_cierre"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"e70a29f3-69c8-48f0-a98e-92a7c31f1132","node_id":"6.0","card_order":1,"card_type":"concept","title":"El enemigo invisible: el remordimiento del comprador","body":"El cliente dijo que sí. Te fuiste feliz. Y esa noche, solo con su decisión, le llega la visita: \\"¿habré hecho bien? ¿y si no me se mueve? ¿qué le voy a decir a mi esposa si esto no jala?\\"\\n\\nEso es el remordimiento del comprador — y le pasa a TODOS. La diferencia entre la venta que se sostiene y la que se cancela mañana no es el producto: es con cuánta claridad y tranquilidad se quedó el cliente cuando saliste por la puerta.","flip_back_text":null,"created_at":"2026-08-10T19:32:06.030682+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"33179725-74a9-41b4-a708-8f93dbb03541","node_id":"6.0","card_order":2,"card_type":"concept","title":"La causa #1 de cancelación: falta de comprensión.","body":"Las ventas no se caen porque el cliente \\"se arrepintió del producto\\". Se caen porque no entendió algo: cuándo llega, cuánto va a pagar exactamente, qué hace si algo sale mal, qué sigue después.\\n\\nCada hueco de comprensión es una grieta — y el remordimiento nocturno se mete por las grietas. La consolidación existe para sellarlas TODAS antes de irte: qué llega, cuándo llega, qué cuesta, qué hace él, qué haces tú, y a quién le habla si algo falla.","flip_back_text":null,"created_at":"2026-08-10T19:32:06.030682+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"b2815d6e-e4e2-44bc-963a-56cdc4274e40","node_id":"6.0","card_order":3,"card_type":"concept","title":"El mal paso 5 y el buen paso 5","body":"MAL paso 5: toda la explicación al INICIO de la relación (el vendedor que abruma con condiciones antes de vender) y al final... nada: \\"¡excelente decisión! cualquier cosa me marca\\" — y se fue corriendo con su comisión.\\n\\nBUEN paso 5: la explicación llega DESPUÉS del sí — concisa, clara, completa. Y el vendedor se va al final con calma, dejando dos cosas sembradas: la relación (CPR de despedida) y la siguiente puerta (la próxima visita, el conocido al que le puede servir).","flip_back_text":null,"created_at":"2026-08-10T19:32:06.030682+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"2ac22a09-ce00-4099-b651-8743fa67bb4b","node_id":"6.0","card_order":4,"card_type":"why_it_works","title":"La consolidación es donde nace tu segundo cliente.","body":"Un cliente bien consolidado hace dos cosas que valen oro: NO cancela (entendió todo, durmió tranquilo) y TE RECOMIENDA (la confianza del final de la visita es la que se cuenta a los amigos).\\n\\nEl vendedor promedio ve el sí como la meta. El Closer lo ve como la mitad: la venta se cierra en el paso 4 — pero se GANA en el 5. Y la siguiente venta, también.","flip_back_text":null,"created_at":"2026-08-10T19:32:06.030682+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"9b3c1e3f-e9d6-41bd-8262-897b52f320a7","node_id":"6.1","card_order":1,"card_type":"concept","title":"La tercera regla de la curva","body":"Te acuerdas de las tres reglas de oro del impulso? La tercera decia que el impulso no termina cuando el cliente dice que si.\\n\\nAhi empieza a caer.\\n\\nEs el arrepentimiento del comprador, y es automatico. Apenas dice que si, el cerebro empieza a buscar razones por las que a lo mejor no debio. No es desconfianza hacia ti: es como funcionamos todos.","flip_back_text":null,"created_at":"2026-08-10T19:32:42.072275+00:00","card_content_type":"static","audience":null,"skill_ids":["consolidation.rehash"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c1f61aba-bf18-425c-bc63-dcc437aad276","node_id":"6.1","card_order":2,"card_type":"concept","title":"El error que parece lo correcto","body":"La reaccion natural del vendedor es reforzar la compra. Recordarle lo bueno del producto, repetirle el ahorro, insistir en que tomo una gran decision.\\n\\nY es exactamente lo que NO hay que hacer.\\n\\nSeguir vendiendo despues del si le dice al cliente algo que no querias decirle: que necesitabas esa venta.","flip_back_text":null,"created_at":"2026-08-10T19:32:42.072275+00:00","card_content_type":"static","audience":null,"skill_ids":["consolidation.rehash"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"7dcc8ebc-bab9-483c-b1c8-e8a12f73592f","node_id":"6.1","card_order":3,"card_type":"why_it_works","title":"Por que eso destruye todo lo anterior","body":"Y si necesitabas la venta, entonces la indiferencia era actuada. Y si la indiferencia era actuada, tambien el interes por su negocio, tambien las preguntas, tambien la platica de su hijo.\\n\\nRetroactivamente, toda la conversacion se convierte en una tecnica.\\n\\nEse es el riesgo real del rehash mal hecho: no solo no quita el arrepentimiento, sino que lo confirma.","flip_back_text":null,"created_at":"2026-08-10T19:32:42.072275+00:00","card_content_type":"static","audience":null,"skill_ids":["consolidation.rehash"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"39436685-54bb-4895-b2a6-5448c1e0c3ef","node_id":"6.1","card_order":4,"card_type":"concept","title":"Lo que si funciona: no cambiar nada","body":"El rehash correcto no es decir mas cosas. Es DEMOSTRAR que nada cambio en ti.\\n\\nSigues indiferente sobre la compra. Sigues amigable sobre la relacion. Y le das la confianza de que ahi vas a estar para lo que necesite.\\n\\nNi una palabra mas de producto. Ni una justificacion. Trato de amigo, igual que hace diez minutos.","flip_back_text":null,"created_at":"2026-08-10T19:32:42.072275+00:00","card_content_type":"static","audience":null,"skill_ids":["consolidation.rehash"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"667eff04-c3af-484b-9329-731c5d0b7a57","node_id":"6.1","card_order":5,"card_type":"why_it_works","title":"Por que funciona","body":"Porque prueba, sin decirlo, que todo lo anterior era real.\\n\\nSi tu actitud es identica antes y despues de la firma, el cliente concluye solo lo que ninguna frase habria logrado convencerlo: que no lo trataste asi para venderle. Lo trataste asi porque asi eres.\\n\\nY con esa conclusion, el arrepentimiento no tiene de que agarrarse. Se disuelve solo.","flip_back_text":null,"created_at":"2026-08-10T19:32:42.072275+00:00","card_content_type":"static","audience":null,"skill_ids":["consolidation.rehash"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"acf389d5-9502-4535-91c8-099b321ce00c","node_id":"6.2","card_order":1,"card_type":"concept","title":"Los tres minutos que blindan la venta","body":"El cliente acaba de decir sí — y su cabeza, sin que lo diga, ya está incubando tres preguntas: ¿cuándo me llega? ¿qué hago si algo sale mal? ¿cuánto acabo pagando exactamente?\\n\\nSi esas preguntas se quedan sin respuesta, esta noche se convierten en remordimiento. Tu trabajo en los siguientes tres minutos: matarlas ANTES de que nazcan. Repite el trato completo — qué, cuándo, cuánto, y el plan B si algo falla. Y verifica: \\"¿le quedó alguna duda de cómo va a funcionar?\\"","flip_back_text":null,"created_at":"2026-08-10T19:32:07.371189+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"3b6b4aad-42e0-48bf-8d37-ab239f3b4f76","node_id":"6.2","card_order":2,"card_type":"concept","title":"Lo que NO se hace después del sí","body":"NO celebres de más: \\"¡no se va a arrepentir!\\" huele a comisión — y despierta la pregunta inversa: ¿de qué me podría arrepentir?\\n\\nNO sigas vendiendo: el cliente ya decidió. Cada beneficio extra después del sí siembra la duda de qué no le has dicho.\\n\\nNO salgas corriendo: la prisa del vendedor tras el sí es la imagen que el cliente recuerda esa noche — y no le gusta.\\n\\nCalma. Claridad. Y la relación sembrada al salir.","flip_back_text":null,"created_at":"2026-08-10T19:32:07.371189+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"2607749b-a64d-469d-9cf5-09392c1e8296","node_id":"6.2","card_order":3,"card_type":"why_it_works","title":"La despedida es de personas, no de facturas.","body":"Ya sellaste la comprensión. El último toque es el CPR de cierre: retoma algo de SU vida que la conversación te regaló — \\"que le vaya bonito el fin con los nietos; el lunes me cuenta cómo quedó el partido.\\"\\n\\nEse detalle hace dos cosas: convierte la transacción en relación (la próxima visita ya no es de vendedor — es de conocido), y le deja al cliente la última emoción de la visita: calidez. Y la última emoción es la que se recuerda... y la que se cuenta.","flip_back_text":null,"created_at":"2026-08-10T19:32:07.371189+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"ab575128-1d67-4b7b-bf1c-52d01aa7a6f4","node_id":"6.3","card_order":1,"card_type":"concept","title":"Cada cliente contento trae al siguiente — si le abres la puerta.","body":"La visita perfecta no termina en la venta. Termina con DOS puertas abiertas:\\n\\nLa recompra: \\"yo paso cada semana — ¿le late que le caiga los lunes para que nunca ande corto?\\" Es servicio, tiene día y tiene razón. El cliente que acepta tu ruta te acaba de convertir en SU proveedor.\\n\\nEl referido: la puerta al siguiente cliente... que él ya te mencionó sin darse cuenta.","flip_back_text":null,"created_at":"2026-08-10T19:32:08.512085+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"b0966fa1-47d0-4d9f-b886-f4203f6f0709","node_id":"6.3","card_order":2,"card_type":"concept","title":"El referido se ancla — o no se pide.","body":"EN FRÍO suena así: \\"¿no tiene conocidos que quieran comprar?\\" — y el cliente más contento del mundo se incomoda: le acabas de cobrar la confianza.\\n\\nANCLADO suena así: \\"ahorita que me platicó de su compadre el del negocio... ¿usted cree que a él le sirva esto? Si gusta, dígale que voy de su parte.\\" — nació de SU plática, es ligero, y el que queda bien presentándote es ÉL.\\n\\nLa regla: si el cliente no te regaló el ancla en la conversación, la puerta del referido se queda para la próxima visita. Nunca se fuerza.","flip_back_text":null,"created_at":"2026-08-10T19:32:08.512085+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"4628d981-e72c-45cf-ad23-8398141cc7ae","node_id":"6.3","card_order":3,"card_type":"why_it_works","title":"La matemática silenciosa de la consolidación","body":"Un vendedor que solo vende necesita encontrar cada cliente desde cero — puerta fría tras puerta fría, todos los días.\\n\\nUn Closer que consolida construye una red: cada cliente sellado es una ruta semanal (recompra sin esfuerzo) y un puente a su compadre (puerta tibia, \\"va de mi parte\\"). A los seis meses, la mitad de sus ventas ya no empiezan en frío.\\n\\nLa Ley de los Promedios sigue mandando — pero la consolidación te mejora la proporción. Para siempre.","flip_back_text":null,"created_at":"2026-08-10T19:32:08.512085+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c401389c-c1db-4013-8615-08caef43b234","node_id":"6.4","card_order":1,"card_type":"concept","title":"El octavo Boss.","body":"La venta ya está hecha — un administrador formal acaba de aprobar tu pedido. Y ahí empieza tu examen, porque a este señor todos sus proveedores le han fallado en los DETALLES: entregas tarde, cobros distintos, nadie que dé la cara.\\n\\nTu misión NO es vender — de hecho, vender algo más aquí es reprobar. Es sellar: cada término con hora y número, el plan B con nombre y teléfono, su cicatriz sanada con compromisos que se puedan cobrar. Relación sí — pero a su manera: formal, ganada, sin confiancitas.\\n\\nGanas cuando él repita tu trato de memoria... y le hable de ti al negocio de su hermano. Así se fabrica un aliado.","flip_back_text":null,"created_at":"2026-08-10T19:32:09.600721+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"a1fc710d-5100-4ba3-8b7f-cdf673e8bc68","node_id":"7.0","card_order":1,"card_type":"concept","title":"Examen 1 de 4.","body":"Un cliente de verdad. Sin guion pedagógico, sin pistas, sin red.\\n\\nLos seis pasos completos: ábrete la puerta, preséntate en un respiro, excava hasta el dolor, preséntale SU problema resuelto, cierra asumido en el pico — y sella el trato tan bien que ninguna duda nazca después.\\n\\nTodo lo que aprendiste en ocho mundos, en una sola conversación. Como va a ser en el campo, todos los días.","flip_back_text":null,"created_at":"2026-08-10T19:32:10.651432+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"f27002c4-ce61-418c-b30f-4c68e11a1b51","node_id":"7.1","card_order":1,"card_type":"concept","title":"Examen 2 de 4 — y el más traicionero.","body":"El siguiente cliente te va a encantar. Y no te va a comprar — no puede, por una razón real que vas a descubrir si preguntas bien.\\n\\nEste examen no mide si puedes vender. Mide si sabes CUÁNDO NO INTENTARLO: detectar la luz roja, honrar su verdad, salir rápido y cálido, dejar la puerta abierta — y llevarte algo mejor que un pedido imposible: un referido y una relación intacta.\\n\\nAquí, vender es fallar. Tiempo de calidad con gente de calidad — demuéstralo.","flip_back_text":null,"created_at":"2026-08-10T19:32:11.684061+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"16533d57-302c-4dd5-9c0a-3cf3b6cb37ee","node_id":"7.2","card_order":1,"card_type":"concept","title":"Examen 3 de 4.","body":"A este señor le vendieron mal hace un año — ocho mil pesos de producto muerta — y juró no comprarle a nadie nuevo. Te va a decir que no dos veces: la primera es el reflejo de siempre. La segunda es su cicatriz.\\n\\nNo las confundas: el reflejo se atraviesa. La cicatriz se ESCUCHA.\\n\\nY si te ganas el derecho a seguir, enciéndelo como aprendiste: con su cuenta, con sus vecinos, con condiciones que lo protejan — pura verdad verificable. Su pedido chico condicionado es la victoria más grande de este mapa: el salto de fe de alguien que juró no volver a saltar.","flip_back_text":null,"created_at":"2026-08-10T19:32:12.729906+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"c9ba1be0-7980-4a04-8f03-f3dd828f0877","node_id":"7.3","card_order":1,"card_type":"concept","title":"El examen que puedes reprobar sintiendote bien","body":"Este cliente lleva anos comprandote. Te recibe con gusto, te da su pedido sin que se lo pidas, y se queda contento hagas lo que hagas.\\n\\nPuedes terminar esta conversacion con el pedido en la mano, sentir que fue una buena visita, y haber reprobado.\\n\\nPorque la pregunta no es si saliste con pedido. Es si saliste sabiendo que mas puede comprarte, y si lograste que empezara a hacerlo.","flip_back_text":null,"created_at":"2026-08-19T14:56:05.779731+00:00","card_content_type":"static","audience":null,"skill_ids":["discovery.hueco"]}');
INSERT INTO public.node_cards SELECT * FROM json_populate_record(NULL::public.node_cards, E'{"id":"9636872d-5c42-4528-9c29-61113b5868dd","node_id":"7.4","card_order":1,"card_type":"concept","title":"El examen final.","body":"Este es el cliente del que te hablaron cuando entraste a ventas: hostil, escéptico, regateador — el que hace que los vendedores promedio cambien de calle.\\n\\nTe va a rechazar dos veces antes de escucharte. Va a objetar todo con números. Va a regatear como si le fuera la vida. Y al final se va a quedar callado, mirándote, sacando cuentas.\\n\\nAdentro de todo eso hay una venta real — para quien ejecute el sistema completo sin quebrarse un milímetro.\\n\\nOcho mundos te trajeron aquí. El vendedor no nace. Se hace — y hoy se certifica.","flip_back_text":null,"created_at":"2026-08-19T14:54:43.665061+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"aa0fbcd2-3758-47bf-b8cd-4e042645f0e9","node_id":"1.0","question_order":1,"question_text":"Un vendedor llega, saluda, y de inmediato le explica al cliente el producto que trae. Que paso se salto?","option_a":"Ninguno, ir al grano ahorra tiempo.","option_b":"Se salto la historia breve y el descubrimiento: presento sin que el cliente supiera quien era ni que necesitaba.","option_c":"Se salto el cierre.","option_d":null,"correct_option":"B","explanation_correct":"Exacto. Presentar es el paso 4. Llegar ahi sin haber pasado por los pasos 2 y 3 es construir sobre nada: el cliente no sabe con quien habla y tu no sabes que necesita. Por eso esa presentacion no se sostiene.","explanation_wrong":"Ir al grano se siente eficiente y es lo contrario. La presentacion es el paso 4 y solo funciona si antes el cliente supo quien eres (paso 2) y tu supiste que necesita (paso 3). Sin eso, le estas hablando de algo que no pidio.","created_at":"2026-08-05T17:01:53.414479+00:00","regla_id":"opening.pitch_prematuro"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"11412526-00e7-487d-8970-96a4e97a9801","node_id":"1.0","question_order":2,"question_text":"Vas avanzando bien en la conversacion y el cliente te interrumpe con algo que te detiene. Que le pasa a tu linea?","option_a":"Se borra: hay que empezar la conversacion desde el principio.","option_b":"Se pausa: sales de la linea, resuelves, y regresas al punto donde estabas.","option_c":"Se acaba: si te detuvieron, esa venta ya no va.","option_d":null,"correct_option":"B","explanation_correct":"Asi es. Lo que ya recorriste no se borra. Sales, resuelves, y vuelves exactamente al punto donde ibas. La pausa dura lo que tu decidas que dure.","explanation_wrong":"Ninguna de las dos. Lo que ya recorriste ya quedo: el cliente no olvida quien eres ni lo que ya platicaron. No se borra ni se acaba, solo se pausa. Tu trabajo es regresar a la linea y seguir avanzando.","created_at":"2026-08-05T17:01:53.414479+00:00","regla_id":"story.desvio_con_regreso"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"9e1e3a3e-5f2f-44a2-9232-40b200afa576","node_id":"1.0","question_order":3,"question_text":"Se te cayo una visita y quieres entender por que. Cual es la pregunta util?","option_a":"Que se me olvido decir?","option_b":"En que punto de la linea sali, y por que no regrese?","option_c":"Sera que no era mi dia?","option_d":null,"correct_option":"B","explanation_correct":"Esa pregunta si tiene respuesta, y una respuesta se puede corregir manana. Las otras dos terminan en encogerse de hombros.","explanation_wrong":"Esas dos preguntas no llevan a ningun lado: una te deja repasando frases sueltas y la otra le echa la culpa a la suerte. Con la linea en la cabeza puedes ubicar el punto exacto donde se salio la conversacion, y eso si se corrige.","created_at":"2026-08-05T17:01:53.414479+00:00","regla_id":"story.sale_sin_regresar"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"a655245f-7652-4545-bb5e-f515a6dfdf76","node_id":"1.1","question_order":1,"question_text":"Que hacen los primeros diez segundos de una conversacion de venta?","option_a":"Deciden si te va a comprar.","option_b":"Te ganan el derecho a seguir hablando.","option_c":"Definen el precio que vas a poder cobrar.","option_d":null,"correct_option":"B","explanation_correct":"Correcto. En diez segundos nadie decide una compra. Lo que si decide es si vale la pena seguir escuchandote, y sin eso no hay nada mas.","explanation_wrong":"La compra se decide mucho despues, en el paso 5. Lo unico que hacen los primeros segundos, y es suficiente, es ganarte el derecho a seguir hablando. Si eso se pierde, ya no importa que tan bueno sea lo que traias.","created_at":"2026-08-05T17:01:53.414479+00:00","regla_id":"opening.energia_verbal"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"82577793-c11e-4c8b-b5d3-fcca7726bd57","node_id":"1.1","question_order":2,"question_text":"Que significan las tres letras de SCE?","option_a":"Saludo, Cortesia, Empatia.","option_b":"Sonrisa, Contacto visual, Entusiasmo.","option_c":"Seguridad, Confianza, Energia.","option_d":null,"correct_option":"B","explanation_correct":"Sonrisa, Contacto visual y Entusiasmo. En ingles son los SEE factors: Smile, Eye contact, Enthusiasm. Tres cosas, ni una mas.","explanation_wrong":"Son Sonrisa, Contacto visual y Entusiasmo. Vienen de los SEE factors en ingles: Smile, Eye contact, Enthusiasm. Vale la pena memorizarlas asi, porque son las tres cosas que deciden los primeros segundos.","created_at":"2026-08-05T17:01:53.414479+00:00","regla_id":"opening.see"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"cfcba12b-5d5e-48e4-b071-e7342b439aed","node_id":"1.1","question_order":3,"question_text":"Por que Closer no te va a calificar tu sonrisa ni tu contacto visual?","option_a":"Porque no son importantes.","option_b":"Porque no puede verlos ni oirlos, y calificar lo que no se puede observar seria inventar.","option_c":"Porque solo importan en las ventas por telefono.","option_d":null,"correct_option":"B","explanation_correct":"Asi es. Son parte fundamental de la doctrina y se practican en cada visita real. Pero Closer solo evalua lo que de verdad puede observar en tus palabras. Lo demas te lo ensena y confia en ti.","explanation_wrong":"Al contrario, son fundamentales, y por eso se ensenan. Lo que pasa es que Closer no puede verte ni oirte, y una calificacion inventada no te sirve de nada. Esa parte la afinas en campo con tu entrenador.","created_at":"2026-08-05T17:01:53.414479+00:00","regla_id":"opening.see"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"9e316911-4b3c-4c0b-9fd3-1e716d6f4c44","node_id":"1.3","question_order":1,"question_text":"Por que falla preguntar tiene un minutito? aunque suene educado?","option_a":"Porque es demasiado informal.","option_b":"Porque le entrega el control al cliente y le ofrece una salida facil: la respuesta que no le cuesta nada es no.","option_c":"Porque un minuto no alcanza para nada.","option_d":null,"correct_option":"B","explanation_correct":"Exacto. No es un problema de educacion sino de estructura: le diste a elegir, y la opcion comoda siempre es la que no lo compromete. El cliente no esta siendo grosero, esta tomando la salida que tu le abriste.","explanation_wrong":"El problema no es el tono ni la duracion. Es que esa pregunta le entrega el control y le abre una salida que no le cuesta nada tomar. Cualquiera contestaria que no.","created_at":"2026-08-05T17:01:53.414479+00:00","regla_id":"opening.pide_permiso"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"fa668247-23e1-4492-aebe-2c7b831f6137","node_id":"1.3","question_order":2,"question_text":"Que hacia distinto el gasista de Londres?","option_a":"Tenia un permiso especial que le abria las puertas.","option_b":"Se comportaba como alguien que tiene derecho a estar ahi, y por eso nadie lo cuestionaba.","option_c":"Iba acompanado para que nadie lo detuviera.","option_d":null,"correct_option":"B","explanation_correct":"Asi es. No era el permiso ni el uniforme: era la postura. La autoridad no se pide, se asume. Y se nota en el primer segundo.","explanation_wrong":"No era ningun permiso ni respaldo externo. Era que actuaba como quien pertenece: llegaba, saludaba y pasaba. La gente reacciona a esa postura mucho antes de reaccionar a las palabras.","created_at":"2026-08-05T17:01:53.414479+00:00","regla_id":"opening.gasman"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"02f1e90b-52ee-417d-93e5-b63390abde2f","node_id":"1.3","question_order":3,"question_text":"Closer te enseña la sonrisa, el contacto visual y la postura, pero en la práctica de texto no te los califica. ¿Qué haces con eso?","option_a":"Ignorarlo: si no se califica, no cuenta.","option_b":"Practicarlo igual, porque en el campo la ejecución pesa más que el guion, y la app no es el examen: es el terreno de práctica.","option_c":"Escribirlo en el texto (por ejemplo «sonrío») para que el evaluador lo vea.","option_d":null,"correct_option":"B","explanation_correct":"Exacto. Lo que no se puede calificar se enseña igual y se pide igual. Un vendedor que solo entrena lo que se le califica llega al campo entrenado a medias.","explanation_wrong":"Lo físico no cabe en un texto, pero sí cabe en tu preparación. La app te dice de frente qué no puede medir para que tú lo practiques de todos modos.","created_at":"2026-08-05T17:01:53.414479+00:00","regla_id":"opening.see"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"9f21acf6-8158-494b-97a6-5658c3117e18","node_id":"2.0","question_order":1,"question_text":"Que significa KISS y por que importa en la historia breve?","option_a":"Keep It Short and Simple: corta y simple, porque cada frase de mas gasta la atencion que acabas de ganar.","option_b":"Keep It Strong and Serious: seria y formal, para que te tomen en serio.","option_c":"Es una tecnica para cerrar ventas rapido.","option_d":null,"correct_option":"A","explanation_correct":"Exacto. Corta y simple. Lo contrario es KILL, Keep It Long and Lengthy, y es lo que hace que el cliente se desconecte justo cuando ya te habia puesto atencion.","explanation_wrong":"KISS es Keep It Short and Simple: corta y simple. La historia breve no busca impresionar ni sonar formal, busca ser el puente mas corto entre no te conozco y a ver, cuenteme.","created_at":"2026-08-06T17:15:17.687565+00:00","regla_id":"story.kiss"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"5946a0f9-7d74-4e8e-9b6f-23550f9ee764","node_id":"2.0","question_order":2,"question_text":"Terminas tu historia breve. Que sigue?","option_a":"Explicar con mas detalle lo que ofreces, ya que tienes su atencion.","option_b":"Preguntarle a el. La historia breve existe para ganarte el derecho de preguntar.","option_c":"Esperar a que el cliente diga algo.","option_d":null,"correct_option":"B","explanation_correct":"Asi es. La doctrina es clara: es mucho mas efectivo pasar directo a las preguntas que dar una explicacion larga. Tu historia no existe para que te entiendan a ti.","explanation_wrong":"Explicar mas gasta la atencion que acabas de ganar, y esperar deja la conversacion en el aire para que el cliente decida si sigue. Lo que sigue es preguntarle a el: para eso te ganaste el derecho.","created_at":"2026-08-06T17:15:17.687565+00:00","regla_id":"story.pregunta_despues"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"15f96fc6-b21a-402f-a280-ef5efe0f2edf","node_id":"2.3","question_order":1,"question_text":"Por que se dice que eres tanto o mas el producto que lo que vendes?","option_a":"Porque tu comision depende de tu esfuerzo personal.","option_b":"Porque el cliente todavia no puede evaluar tu producto, pero a ti si te puede evaluar desde el primer segundo.","option_c":"Porque los productos son todos iguales.","option_d":null,"correct_option":"B","explanation_correct":"Correcto. No ha probado tu producto ni conoce tu empresa. Lo unico que si puede juzgar de inmediato eres tu, y esa decision la toma mucho antes que la otra.","explanation_wrong":"No es por la comision ni porque los productos sean iguales. Es que el cliente no tiene forma de evaluar tu producto todavia, pero a ti si te evalua desde que te ve. Esa es la unica informacion que tiene al principio.","created_at":"2026-08-06T17:15:17.687565+00:00","regla_id":"relationship.cpr"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"10267818-cb18-462d-8a51-2c0440e467bf","node_id":"2.3","question_order":2,"question_text":"En que parte de la conversacion se hace el CPR?","option_a":"Justo despues de la historia breve, antes de pasar al siguiente paso.","option_b":"En toda la conversacion. No es un paso, es algo que haces de principio a fin.","option_c":"Solo al final, cuando ya cerraste.","option_d":null,"correct_option":"B","explanation_correct":"Asi es, y eso lo hace distinto de todo lo demas. Los seis pasos van en orden; el CPR los atraviesa todos.","explanation_wrong":"El CPR no ocupa un lugar en el mapa. Se hace durante toda la conversacion, desde el primer segundo hasta el ultimo. Es lo unico que no es un paso.","created_at":"2026-08-06T17:15:17.687565+00:00","regla_id":"relationship.cpr"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"51d3a784-a19c-458a-9f2e-b51e70694a31","node_id":"2.4","question_order":1,"question_text":"Que significan las letras de FORMS?","option_a":"Family, Occupation, Recreation, Motivation, Sports.","option_b":"Focus, Order, Respect, Method, Sales.","option_c":"Es el nombre del formulario de calificacion del cliente.","option_d":null,"correct_option":"A","explanation_correct":"Familia, Ocupacion, Recreacion, Motivacion y Deportes. Cinco puertas a la persona, y siempre hay al menos una abierta.","explanation_wrong":"FORMS es Family, Occupation, Recreation, Motivation, Sports: los cinco temas para crear relacion personal. Vale la pena memorizarlos, porque son la respuesta a de que le hablo.","created_at":"2026-08-06T17:15:17.687565+00:00","regla_id":"relationship.forms"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"fb58795e-3a8e-4c94-bebb-fdb6b38722ca","node_id":"2.4","question_order":2,"question_text":"Le preguntas a un cliente por su equipo de futbol y la verdad el tema no te interesa nada. Que haces?","option_a":"Preguntar igual: lo importante es que el cliente hable.","option_b":"Buscar otra de las cinco puertas que si te interese de verdad. El interes fingido se nota y cuesta mas que no preguntar.","option_c":"No hacer CPR con ese cliente.","option_d":null,"correct_option":"B","explanation_correct":"Exacto. La doctrina insiste en la palabra genuinos por algo. Hay cinco puertas justamente para que encuentres una que si te interese.","explanation_wrong":"Fingir interes se nota siempre, y sale mas caro que no preguntar, porque el cliente se da cuenta de que le estas aplicando una tecnica. Y renunciar al CPR tampoco: hay cinco puertas, busca otra.","created_at":"2026-08-06T17:15:17.687565+00:00","regla_id":"relationship.interes_fingido"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"9d5a9dff-c180-4472-8c13-8f0bea84473b","node_id":"2.6","question_order":1,"question_text":"Un cliente te dice no me interesa antes de que le digas a que vienes. Que es eso?","option_a":"Una objecion: ya evaluo tu oferta y la rechazo.","option_b":"Un bloqueo: un reflejo que llega antes de entender. Todavia no sabe a que vienes.","option_c":"Una senal de que no es tu cliente.","option_d":null,"correct_option":"B","explanation_correct":"Correcto. No puede rechazar algo que todavia no conoce. Es la puerta cerrandose sola, la misma respuesta que le da a cualquiera que llega.","explanation_wrong":"No puede ser una objecion porque no sabe todavia que le ofreces: no hubo nada que evaluar. Es un bloqueo, un reflejo automatico. Y por eso no se discute, se atraviesa.","created_at":"2026-08-06T17:15:17.687565+00:00","regla_id":"blocks.bloqueo_vs_objecion"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"53f0ef7c-a587-43a7-bccf-e774f639a8ca","node_id":"2.6","question_order":2,"question_text":"Que pasa si discutes un bloqueo e intentas convencer al cliente de que si le interesa?","option_a":"Que entiende tu punto y te da la oportunidad.","option_b":"Que lo conviertes en una posicion: ahora tiene que defenderlo, y te acabas de crear un no de verdad.","option_c":"Nada, es lo normal insistir un poco.","option_d":null,"correct_option":"B","explanation_correct":"Asi es. Nadie se deja convencer de que no esta ocupado. Al pelearlo obligas al cliente a sostener algo que habia dicho sin pensar.","explanation_wrong":"Al contrario. Un bloqueo se dice sin pensar; si lo peleas, el cliente tiene que defenderlo, y al defenderlo se lo cree. Convertiste un reflejo en una posicion.","created_at":"2026-08-06T17:15:17.687565+00:00","regla_id":"blocks.discute_bloqueo"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"9e5cb271-1ae9-4276-835c-134af971d453","node_id":"2.6","question_order":3,"question_text":"Que significan las letras de AIR?","option_a":"Agree, Ignore, Resume: acepta, ignora, resume.","option_b":"Analiza, Investiga, Responde.","option_c":"Atiende, Insiste, Repite.","option_d":null,"correct_option":"A","explanation_correct":"Acepta lo que te dijo, no lo discutas, y sigue con lo tuyo. Tres movimientos, dos segundos.","explanation_wrong":"AIR es Agree, Ignore, Resume: acepta, ignora, resume. Ignorar aqui significa no discutirlo, no que lo pases por alto sin reconocerlo.","created_at":"2026-08-06T17:15:17.687565+00:00","regla_id":"blocks.air"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"a4adbb78-2b23-4b0b-9941-2e4fddb81bd1","node_id":"2.6","question_order":4,"question_text":"Cual de estas es una OBJECION y no un bloqueo?","option_a":"Ahorita ando ocupado.","option_b":"Ya tengo proveedor y la verdad me cumple bien.","option_c":"No estoy comprando nada.","option_d":null,"correct_option":"B","explanation_correct":"Exacto. Esa llega despues de entender: el cliente evaluo su situacion y encontro una razon concreta. Las otras dos son reflejos que se dicen sin pensar.","explanation_wrong":"Esas dos son bloqueos: se dicen en automatico, sin haber evaluado nada. Ya tengo proveedor y me cumple bien es distinto, porque ahi si hubo un razonamiento sobre su situacion real.","created_at":"2026-08-06T17:15:17.687565+00:00","regla_id":"blocks.bloqueo_vs_objecion"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"1b771b9a-c0a7-4511-901d-9a49223114d6","node_id":"3.0","question_order":1,"question_text":"El cliente le dice al vendedor: \\"cuenteme, que me trae?\\" El vendedor responde arrancando su presentacion completa de producto. Que hizo mal?","option_a":"Nada — el cliente le pidio la presentacion.","option_b":"Receto sin diagnosticar: acepto la invitacion a presentar sin saber todavia que le duele a ese negocio.","option_c":"Debio negarse a responder la pregunta.","option_d":null,"correct_option":"B","explanation_correct":"Esa invitacion es una trampa dulce. El Closer responde con jiu-jitsu: \\"Con gusto — pero primero cuenteme un poco de su negocio para no hacerle perder tiempo con cosas que no le sirvan. Que es lo que mas se le mueve?\\" Diagnostico primero, siempre.","explanation_wrong":"La invitacion del cliente no cambia el orden del sistema. Presentar sin diagnosticar produce una presentacion generica — y las genericas no venden. Lo correcto: agradecer la apertura y voltear a preguntar primero. El cliente lo respeta mas, no menos.","created_at":"2026-07-25T21:40:07.757054+00:00","regla_id":"discovery.receta_sin_diagnostico"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"d4974691-c2ea-48ec-8a1b-e93e74680648","node_id":"3.0","question_order":2,"question_text":"Cual es la diferencia central entre el vendedor promedio y el Doctor Vendedor?","option_a":"El promedio busca donde encajar su producto; el doctor primero entiende el negocio y luego conecta.","option_b":"El doctor tiene mas labia y carisma.","option_c":"El promedio trabaja menos horas.","option_d":null,"correct_option":"A","explanation_correct":"Exacto. Uno llega con la receta escrita buscando paciente. El otro examina primero — y su receta, cuando llega, cae en tierra preparada. Por eso el que pregunta vende mas que el que habla.","explanation_wrong":"No es carisma ni horas — es el ORDEN. El promedio receta primero (su producto favorito buscando donde caber). El doctor examina primero y receta despues. Ese orden invertido es toda la diferencia en conversion.","created_at":"2026-07-25T21:40:07.757054+00:00","regla_id":"discovery.examen_antes_receta"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"8d56b063-2c10-41bc-8c10-9b7080871e45","node_id":"3.0","question_order":3,"question_text":"Le preguntas al cliente que tal le cumple su proveedor y responde, genuino y sin dudar: \\"excelente, la verdad cero quejas.\\" Que hace el investigador?","option_a":"Insistir en el proveedor con mas preguntas hasta encontrar algo.","option_b":"Cambiar de territorio: ese salio limpio — ahora explora producto o precio.","option_c":"Rendirse: si el proveedor le cumple, no hay venta posible.","option_d":null,"correct_option":"B","explanation_correct":"Eso es el barrido. Un positivo limpio y genuino significa que el dolor no vive en ese territorio — no que no exista. Los otros dos territorios siguen sin examinar: que lineas le faltan? a cuanto esta comprando? El mapa tiene tres zonas por algo.","explanation_wrong":"Insistir en un territorio limpio te vuelve interrogador y quema la conversacion; rendirte regala la visita. El dolor casi siempre existe — solo que vive en OTRO territorio. Positivo limpio = cambia de zona y sigue examinando.","created_at":"2026-07-25T21:40:07.757054+00:00","regla_id":"discovery.barrido"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"08ac9568-b847-4c0e-b44c-30775b7aa4da","node_id":"3.0","question_order":4,"question_text":"Por que el cliente baja la guardia cuando le preguntas de verdad por su negocio?","option_a":"Porque se distrae y olvida que eres vendedor.","option_b":"Porque los vendedores que el conoce hablan — el que pregunta y escucha no encaja en su alarma anti-vendedor.","option_c":"Porque las preguntas lo confunden.","option_d":null,"correct_option":"B","explanation_correct":"Su alarma esta calibrada para el vendedor que llega hablando de su producto. El que pregunta con interes genuino por SU negocio rompe el patron — y el cerebro del cliente lo reclasifica: de amenaza a conversacion.","explanation_wrong":"No es distraccion ni confusion — es reclasificacion. Su alarma anti-vendedor espera un monologo de producto. Cuando en lugar de eso recibe interes genuino por su negocio, el patron no coincide y la guardia baja. Preguntar es la forma mas rapida de dejar de parecer vendedor.","created_at":"2026-07-25T21:40:07.757054+00:00","regla_id":"discovery.examen_antes_receta"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"7c03d7bd-522b-4ff3-9932-a1ed6ef8c81a","node_id":"3.5","question_order":1,"question_text":"A media conversación, el cliente suelta: \\"¿Y ese producto lo manejan también en presentación grande? ¿Cómo anda de precio?\\" ¿Qué luz es?","option_a":"Amarilla — apenas está conociendo.","option_b":"Verde encendiéndose — preguntó presentación Y precio: nadie pregunta el precio de lo que no le interesa.","option_c":"Roja — preguntar precio es buscar pretexto para decir que está caro.","option_d":null,"correct_option":"B","explanation_correct":"Doble señal de compra en una frase: presentación (ya se imagina comprándolo) y precio (ya está evaluando). El cliente te está diciendo \\"me interesa\\" sin decirlo. Detectarlo a tiempo cambia todo lo que sigue.","explanation_wrong":"Preguntar precio no es buscar pretexto — es la señal de compra más clásica que existe. Nadie evalúa el costo de lo que no piensa comprar. Ese cliente encendió la verde: tu trabajo es verla.","created_at":"2026-08-10T19:01:11.54228+00:00","regla_id":"close.fishbbod"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"51ec0685-31f6-4a38-82ac-bb25bdfad41e","node_id":"3.5","question_order":2,"question_text":"Llevas 20 minutos con un cliente amabilísimo: te ofreció café, te contó de su familia, se ríe de tus comentarios. Pero: cero preguntas sobre el producto, cero menciones de compra, y ya te dijo dos veces \\"está bonito su catálogo\\". ¿Qué luz es?","option_a":"Verde — la química es excelente.","option_b":"Probablemente roja o amarilla muy fría: amabilidad sin UNA sola señal de compra. La luz se mide en señales, no en sonrisas.","option_c":"Verde — nadie regala café a un vendedor que no le interesa.","option_d":null,"correct_option":"B","explanation_correct":"La trampa del rojo encantador. Veinte minutos, cero señales: ni una pregunta de producto, ni una mención de compra, y \\"está bonito su catálogo\\" es un cumplido de despedida, no de interés. Cierra con cariño y ve por tus amarillos.","explanation_wrong":"El café y las risas se sienten increíbles — y no son señales de compra. Señal es: pregunta de producto, mención de necesidad, evaluación de precio. Cero de eso en 20 minutos es un cliente que disfruta tu compañía, no tu oferta. Amable ≠ verde.","created_at":"2026-08-10T19:01:11.54228+00:00","regla_id":"discovery.luz_verde"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"a2c77594-d71b-4478-b95a-d6e7783746ea","node_id":"3.5","question_order":3,"question_text":"Detectas a un rojo claro: su negocio no usa lo que vendes y te lo dijo sin rodeos. ¿Cuál es la jugada del sistema?","option_a":"Insistir — todo cliente es persuadible con la técnica correcta.","option_b":"Salir rápido y amable: agradecer, dejar la puerta abierta, y llevarle tu tiempo a un amarillo.","option_c":"Quedarte a platicar para no ser grosero.","option_d":null,"correct_option":"B","explanation_correct":"Tiempo de calidad con gente de calidad. Rápido porque cada minuto ahí se lo robas a un persuadible; amable porque hoy es rojo pero en seis meses quién sabe — y la zona escucha cómo tratas a la gente.","explanation_wrong":"Ni insistir (el 10% rojo no compra HOY hagas lo que hagas — es matemática, no reto de técnica) ni quedarte por pena (tu tiempo es tu herramienta más cara). La salida correcta: rápida, cálida, puerta abierta. Y de vuelta a tus amarillos.","created_at":"2026-08-10T19:01:11.54228+00:00","regla_id":"discovery.rojo_insistir"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"c54ee946-7f56-411d-8d48-6ad07647968a","node_id":"4.0","question_order":1,"question_text":"El vendedor dice: \\"Con este multigrado sus clientes regresan cada 5,000 km en vez de cada 3,000 — menos reclamos y más recompra para usted.\\" ¿Qué hizo esa frase?","option_a":"Bajó el costo — habló de ahorro.","option_b":"Subió el valor — conectó el producto con ganancias concretas del negocio del cliente.","option_c":"Subió el costo — el producto suena caro.","option_d":null,"correct_option":"B","explanation_correct":"Subió el valor, y fíjate cómo: no habló del producto en abstracto — habló de lo que el producto hace EN el negocio del cliente: menos reclamos, más recompra. Valor es siempre el producto traducido a la vida del cliente.","explanation_wrong":"No mencionó precio ni facilidades — habló de lo que el cliente GANA: menos reclamos, clientes que regresan. Eso es subir el plato del valor. El plato del costo ni se tocó en esa frase.","created_at":"2026-07-03T22:02:51.636674+00:00","regla_id":"present.beneficio_no_caracteristica"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"f5d60551-b2d9-4ef9-9734-3153df9458dc","node_id":"4.0","question_order":2,"question_text":"El cliente duda. El vendedor, nervioso, suelta: \\"Bueno, también tengo una línea más económica si esta le parece mucho...\\" ¿Qué acaba de pasar en la balanza?","option_a":"Bajó el costo — le dio una opción accesible. Buena jugada.","option_b":"Bajó el VALOR de su propio producto: le confirmó al cliente que ni él cree que lo vale.","option_c":"Nada — solo amplió el catálogo.","option_d":null,"correct_option":"B","explanation_correct":"Exacto — y es de los errores más caros. Al retroceder ante la primera duda, el mensaje real fue: \\"tiene razón, no lo vale.\\" La duda del cliente pedía MÁS valor (más conexión con su dolor), no un producto más chico.","explanation_wrong":"Parece flexibilidad, pero mira el mensaje de fondo: el cliente dudó del valor, y el vendedor en lugar de construir valor... le dio la razón bajándose de producto. La respuesta a la duda es subir el plato del valor, no encoger la oferta.","created_at":"2026-07-03T22:02:51.636674+00:00","regla_id":"close.descuento_de_panico"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"e49398cf-ebfb-4b86-9972-3ef9f01c8760","node_id":"4.0","question_order":3,"question_text":"¿Por qué el orden correcto es subir el valor PRIMERO y bajar el costo DESPUÉS?","option_a":"Porque el precio nunca debe mencionarse.","option_b":"Porque bajar el costo de algo sin valor da desconfianza — pero cuando el valor está alto, el mismo costo se percibe chico.","option_c":"Porque así lo hacen todos los vendedores.","option_d":null,"correct_option":"B","explanation_correct":"Esa es la mecánica: $500 por \\"un aceite\\" suena caro; $500 por \\"dejar de mandar clientes a la competencia cada quincena\\" suena regalado. El mismo número, distinta balanza. Primero construyes el peso del valor — luego el costo cae solo.","explanation_wrong":"El precio sí se menciona — en su momento. La clave es el orden: descuentos y facilidades sobre algo que el cliente aún no valora provocan sospecha (¿por qué me lo remata?). Valor primero, y el costo se encoge solo en comparación.","created_at":"2026-07-03T22:02:51.636674+00:00","regla_id":"present.dos_mitades"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"0a573505-4487-42a2-986a-e12e00e0f81b","node_id":"4.4","question_order":1,"question_text":"A media presentación, el cliente interrumpe: \\"¿Y cómo estaría el precio? ¿Manejan entrega?\\" El vendedor responde: \\"Ahorita le digo, déjeme terminar de explicarle las otras líneas que manejamos.\\" ¿Qué acaba de pasar?","option_a":"Bien hecho — la información completa es primero.","option_b":"El cliente llegó al pico de la curva... y el vendedor lo dejó pasar por terminar su rollo.","option_c":"El cliente estaba siendo grosero al interrumpir.","option_d":null,"correct_option":"B","explanation_correct":"Doble señal de compra (precio + entrega) = pico de la curva. Ese era EL momento. Cada minuto extra de presentación desde ahí no suma — enfría. El catálogo completo no le importa a alguien que ya quiere comprar.","explanation_wrong":"La interrupción del cliente era la mejor noticia del día: preguntó precio Y entrega — pico de curva, señales gritando. Seguir presentando ahí es servir el postre cuando el cliente ya pidió la cuenta. La información completa vale menos que el momento.","created_at":"2026-08-10T19:11:27.770095+00:00","regla_id":"close.sigue_presentando"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"30ebddb2-dd6c-404f-aad6-1de5fcdc47b7","node_id":"4.4","question_order":2,"question_text":"¿Por qué \\"abrumar al inicio\\" mata la curva en lugar de acelerarla?","option_a":"Porque la curva sube por escalones — y el cliente en el escalón cero no tiene dónde recibir toda la artillería: se espanta en lugar de subir.","option_b":"Porque está prohibido hablar del producto.","option_c":"Porque los clientes prefieren vendedores callados.","option_d":null,"correct_option":"A","explanation_correct":"Exacto. El impulso se construye gradual: primero confianza, luego interés, luego deseo. Descargar todo en el minuto uno es pedirle a alguien que salte del piso al techo — no puede, y además le da miedo el intento.","explanation_wrong":"No es prohibición ni silencio — es secuencia. La curva necesita escalones: la apertura construye el primero, la historia el segundo, el descubrimiento el tercero... Saltárselos con artillería temprana no acelera la subida: derrumba la escalera.","created_at":"2026-08-10T19:11:27.770095+00:00","regla_id":"impulse.curva"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"1b3eb719-e34f-4976-8fc9-02c1618a49df","node_id":"4.4","question_order":3,"question_text":"El vendedor nota que las respuestas del cliente se están enfriando: contestó \\"ajá\\" dos veces seguidas y miró su celular. ¿Qué dice la curva?","option_a":"Que hay que empujar más fuerte antes de que se acabe el tiempo.","option_b":"Que la curva va bajando: dejar de empujar, y volver a construir valor — o leer si es momento de retirarse bien.","option_c":"Que el cliente es un maleducado.","option_d":null,"correct_option":"B","explanation_correct":"Curva bajando se responde con menos presión, no con más. Empujar una curva que baja la hunde. Se regresa a lo que la subió (valor, su dolor, su escena) — o si ya no hay materia, se cierra la visita con calidad para volver otro día con la curva en cero, no en negativo.","explanation_wrong":"Empujar una curva que baja es acelerar cuesta abajo: cada insistencia la hunde más. Lo que baja la curva casi siempre es exceso de presión o pérdida de conexión — y ninguna de las dos se arregla con más presión. Se arregla con valor... o con una buena retirada.","created_at":"2026-08-10T19:11:27.770095+00:00","regla_id":"impulse.curva"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"4e887b42-92ea-4c97-a9d6-4166b6a675fb","node_id":"5.0","question_order":1,"question_text":"Tras una gran conversación — dolor conectado, cuenta hecha, tres síes — el vendedor remata: \\"Entonces... ¿le interesa?\\" El cliente: \\"Pues déjeme pensarlo.\\" ¿Qué pasó?","option_a":"El cliente nunca estuvo interesado.","option_b":"El vendedor abrió la puerta al limbo con una pregunta de sí/no — y el cliente, ante una puerta abierta, la usó.","option_c":"Faltó bajarle el precio.","option_d":null,"correct_option":"B","explanation_correct":"La conversación había construido el sí — y la pregunta lo regaló. \\"¿Le interesa?\\" invita a evaluar desde cero algo que ya estaba decidido en los hechos. El cierre correcto era asumir y ofrecer opciones: ¿5 u 8? ¿lunes o miércoles?","explanation_wrong":"El interés estaba — tres síes y la cuenta hecha lo prueban. Lo que falló fue la puerta: una pregunta de sí/no al final le ofrece al cliente una salida que no buscaba, y el \\"déjeme pensarlo\\" es la salida más cómoda. El precio no tuvo nada que ver.","created_at":"2026-08-10T19:26:07.636095+00:00","regla_id":"close.mal_cierre"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"f3935040-5e2f-4fdd-a5fb-8b245a1bb446","node_id":"5.0","question_order":2,"question_text":"¿Por qué \\"¿le entrego el lunes o el miércoles?\\" funciona mejor que \\"¿quiere que le entregue?\\"","option_a":"Porque suena más profesional.","option_b":"Porque asume la decisión de fondo (ya construida por la conversación) y pregunta solo el detalle — cualquier opción que elija es un sí.","option_c":"Porque el lunes es mejor día de entrega.","option_d":null,"correct_option":"B","explanation_correct":"Esa es la mecánica del cierre asumido: la decisión grande ya la tomó la conversación — dolor, valor, síes, señales. La pregunta de opciones solo le da al cliente el volante de los detalles. Elegir miércoles ES decir sí.","explanation_wrong":"No es cuestión de sonar profesional ni de logística. Es arquitectura de la decisión: \\"¿quiere que...?\\" reabre la pregunta grande (¿compro o no?); \\"¿lunes o miércoles?\\" la da por resuelta y pregunta la chica. El cliente decide cómodo — y decide que sí.","created_at":"2026-08-10T19:26:07.636095+00:00","regla_id":"close.alternativa"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"d492b717-5c6d-4b27-aaf7-7806d6379e1f","node_id":"5.0","question_order":3,"question_text":"Un cliente escuchó todo, preguntó detalles... y al cierre dice: \\"No, fíjese que ahorita de verdad no puedo — hasta el otro mes que cobre lo del contrato.\\" ¿Cómo salió esta visita?","option_a":"Mal — no hubo venta.","option_b":"Bien — hubo CIERRE: una decisión real, con razón concreta y fecha. Eso vale oro: sabes exactamente cuándo volver y con qué.","option_c":"Regular — debió insistir hasta convertir el no.","option_d":null,"correct_option":"B","explanation_correct":"Un cierre extrae una decisión — no siempre una venta. Este no es claro, tiene razón real y trae fecha: el otro mes, con dinero del contrato. Comparado con un \\"déjeme pensarlo\\" eterno, esto es un mapa del tesoro. Agenda la vuelta y consolida la relación.","explanation_wrong":"No confundas cierre con venta. La visita SÍ cerró: decisión clara, razón concreta, fecha de regreso. Insistir contra un \\"no puedo pagar ahorita\\" genuino solo quema la relación — la jugada es capitalizar la decisión: \\"perfecto, entonces lo veo el mes que entra ya con lo del contrato, ¿como qué fecha le cae?\\"","created_at":"2026-08-10T19:26:07.636095+00:00","regla_id":"close.asumir_venta"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"9ed42523-f05c-403f-9362-bbea2fc499a3","node_id":"5.4","question_order":1,"question_text":"Tras la presentación completa, el cliente dice: \\"Está interesante, pero ya trabajo con un proveedor y me da buen precio.\\" El vendedor responde: \\"Claro, no se preocupe — oiga, ¿y ya vio qué bien acomodado tiene su mostrador?\\" ¿Qué hizo?","option_a":"AIR bien aplicado — le dio la razón y retomó por otro hilo.","option_b":"Aplicó AIR a una OBJECIÓN real: evadió a alguien que le habló en serio, y la confianza se agrietó.","option_c":"Nada grave — cambiar de tema relaja la conversación.","option_d":null,"correct_option":"B","explanation_correct":"Exacto — la herramienta correcta en el momento equivocado. Ese cliente entendió la oferta y dio un motivo concreto: merece una respuesta real, no una evasión. AIR es para reflejos pre-comprensión; a las objeciones se les responde con reencuadre y balas.","explanation_wrong":"Parece AIR de libro — pero mira el MOMENTO: llegó después de la presentación, con motivo concreto (proveedor, precio). Eso es objeción, no bloqueo. Evadirla con cambio de tema le dice al cliente \\"no tengo respuesta\\" — y la conversación seria se acabó ahí.","created_at":"2026-08-10T19:26:04.220309+00:00","regla_id":"objection.air_a_objecion"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"015affa2-9d60-4d98-a27c-5927fbc07daf","node_id":"5.4","question_order":2,"question_text":"¿Por qué \\"ya tengo proveedor\\" es de las mejores cosas que te pueden decir?","option_a":"Porque puedes hablar mal del otro proveedor.","option_b":"Porque te confirma que compra este producto, que paga por él, y que hay un lugar que disputar — es información de oro, no un rechazo.","option_c":"No es buena — significa que llegaste tarde.","option_d":null,"correct_option":"B","explanation_correct":"Información pura: hay demanda real, hay presupuesto real, y hay un incumbente con debilidades que su propio cliente conoce. La respuesta correcta es curiosidad genuina — ¿qué tal se porta con las entregas? — nunca defensa ni ataque al otro.","explanation_wrong":"Ni tarde ni para atacar al otro (hablar mal del proveedor te hace ver desesperado y de paso insulta el criterio del cliente). \\"Ya tengo proveedor\\" = compra esto, paga esto, y el lugar existe. Pregunta cómo se porta el otro — la puerta te la va a abrir él solito.","created_at":"2026-08-10T19:26:04.220309+00:00","regla_id":"objection.es_senal_de_compra"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"39aa2d9d-eeab-4455-a4b6-627164203668","node_id":"5.4","question_order":3,"question_text":"¿Cuál es la diferencia entre el cliente que objeta y el que te despide con un \\"gracias, ahí lo pensamos\\"?","option_a":"Ninguna — los dos te están diciendo que no.","option_b":"El que objeta está considerando en serio tu oferta y te dice qué le falta para el sí; el del \\"ahí lo pensamos\\" ya se desconectó.","option_c":"El que objeta es más grosero.","option_d":null,"correct_option":"B","explanation_correct":"La objeción es engagement: entendió, le importa, y está negociando consigo mismo enfrente de ti — dándote el mapa exacto de lo que falta. El \\"ahí lo pensamos\\" educado es la desconexión disfrazada. Aprende a alegrarte cuando escuches una objeción: la venta sigue viva.","explanation_wrong":"Suenan parecido y son opuestos: la objeción trae contenido (caro, proveedor, consultar) porque hay interés real detrás procesando tu oferta. El \\"gracias, ahí lo pensamos\\" no trae nada — es la salida cómoda del que ya se fue. La objeción es la venta respirando.","created_at":"2026-08-10T19:26:04.220309+00:00","regla_id":"objection.es_senal_de_compra"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"74642942-36ce-4262-bc2c-23767f8d9746","node_id":"6.0","question_order":1,"question_text":"El cliente firmó el pedido. El vendedor, feliz: \\"¡Excelente decisión, no se va a arrepentir! Cualquier cosa me marca, ¿eh?\\" — y se va. Esa noche el cliente piensa: \\"¿y cuándo dijo que llegaba? ¿y si me mandan otra cosa?\\" ¿Qué pasó?","option_a":"Nada — la venta ya estaba cerrada.","option_b":"El vendedor dejó grietas de comprensión abiertas — y el remordimiento nocturno se mete exactamente por ahí. Esa venta está en riesgo.","option_c":"El cliente es indeciso, no es culpa del vendedor.","option_d":null,"correct_option":"B","explanation_correct":"La causa #1 de cancelación no es arrepentimiento del producto — es no haber entendido algo. Cuándo llega, qué hace si falla, qué sigue. Cada hueco es una grieta, y las grietas se sellan ANTES de salir por la puerta, no \\"cualquier cosa me marca\\".","explanation_wrong":"La venta cerrada es la venta más frágil que existe — esa noche llega el remordimiento del comprador, y busca grietas: ¿cuándo llega? ¿y si sale mal? El \\"cualquier cosa me marca\\" no sella nada. La consolidación era el paso que faltó — y puede costar la venta completa.","created_at":"2026-08-10T19:32:06.161141+00:00","regla_id":"consolidation.siguientes_pasos"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, '{"id":"bd963bc8-4096-478c-9310-db642759ba7e","node_id":"6.0","question_order":2,"question_text":"¿Cuáles son los DOS propósitos del paso de consolidación?","option_a":"Cobrar rápido y salir a la siguiente visita.","option_b":"Dejar próximos pasos cristalinos (sellar la comprensión) y capitalizar al cliente positivo (relación + siguiente oportunidad).","option_c":"Repetir la presentación completa para reforzar la decisión.","option_d":null,"correct_option":"B","explanation_correct":"Los dos, en ese orden: primero la claridad — qué llega, cuándo, qué sigue, qué hace si algo falla — que blinda la venta contra el remordimiento. Y luego la cosecha: la relación sembrada y la puerta a la siguiente venta o al referido.","explanation_wrong":"Ni la prisa ni la re-presentación. Repetir la venta después del sí siembra dudas (¿por qué me sigue convenciendo?). Los dos propósitos reales: comprensión total (la venta que se entiende no se cancela) y capitalización (la relación y la siguiente puerta).","created_at":"2026-08-10T19:32:06.161141+00:00","regla_id":"consolidation.siguientes_pasos"}');
INSERT INTO public.node_quiz_questions SELECT * FROM json_populate_record(NULL::public.node_quiz_questions, E'{"id":"e59a223f-b405-4446-98df-2dc840da8e47","node_id":"6.0","question_order":3,"question_text":"¿Por qué \\"la venta se cierra en el Paso 5 pero se GANA en el 6\\"?","option_a":"Porque en el 6 se firma el contrato legal.","option_b":"Porque el sí del Paso 5 es frágil hasta que la comprensión y la confianza del Paso 6 lo blindan — y porque del 6 salen la recompra y los referidos.","option_c":"Porque el Paso 6 es donde se negocia el precio final.","option_d":null,"correct_option":"B","explanation_correct":"Exacto. Sin consolidación, el sí es una promesa a merced del remordimiento nocturno. Con ella, es una decisión blindada — y además sembraste la siguiente: el cliente que se queda tranquilo es el que te recomienda y te recompra.","explanation_wrong":"No es papeleo ni precio — es blindaje y siembra. El sí recién nacido es frágil: el Paso 6 lo protege con comprensión total, y de pasada construye lo que vale más que esta venta: la relación que trae la siguiente.","created_at":"2026-08-10T19:32:06.161141+00:00","regla_id":"consolidation.arrepentimiento"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"8b5e58b7-c512-4439-b031-8066f287249b","version":1,"section_key":"fundamento","order_index":1,"title":"PARTE 1 · EL FUNDAMENTO","body":"# EL CEREBRO DE CLOSER\\n## Doctrina canónica del sistema de venta\\n\\n*Versión 1.0 · Fuente única de verdad*\\n\\n---\\n\\n## CÓMO USAR ESTE DOCUMENTO\\n\\nEsto no es un manual ni un resumen. Es el entendimiento del sistema, escrito para que se pueda **razonar** con él.\\n\\nCada técnica se presenta con tres cosas: **qué es**, **por qué funciona** (el mecanismo humano detrás) y **qué la rompe**. El porqué importa más que el qué, porque de él se deducen los casos que ninguna lista cubre.\\n\\nEjemplo de la diferencia: una lista diría *\\"no digas «¿cómo lo ves?»\\"*. Este documento dice *\\"toda pregunta que permita aprobar o posponer le entrega el control al cliente\\"* — de donde se deduce que *\\"¿le late?\\"*, *\\"¿qué opina?\\"* y *\\"¿le parece?\\"* también están mal, aunque nadie los haya escrito nunca.\\n\\n**Regla de razonamiento:** ante un caso que este documento no cubre explícitamente, no inventes. Busca el principio que aplica y dedúcelo. Si dos principios chocan, gana el de mayor jerarquía (ver Parte 6).\\n\\n### Etiquetas\\n\\n**PROCEDENCIA** — `FUENTE` (sistema original Credico/Cydcor) · `CAMPO` (evolución de Emilio Fanjul) · `CLOSER` (andamiaje pedagógico)\\n\\n**CANAL** — `PRESENCIAL` (requiere cuerpo o presencia) · `UNIVERSAL` (funciona en persona, teléfono, mensaje o correo)\\n\\n---\\n\\n---\\n\\n# PARTE 1 · EL FUNDAMENTO\\n\\n## 1.1 El problema que resuelve todo el sistema `FUENTE`\\n\\nCuando abres una conversación con un desconocido, **su atención está dividida en tres**:\\n\\n- **Un tercio** sigue en lo que estaba haciendo\\n- **Un tercio** está resolviendo preguntas básicas: quién eres, qué quieres, por qué me hablas\\n- **Solo un tercio** está disponible para ti\\n\\n> **De aquí sale la razón de ser de los 6 pasos:** si vas directo a presentar, le estás hablando a un tercio de una persona. Cada paso previo existe para recuperar una porción de esa atención.\\n\\nLa Introducción libera el primer tercio (deja de pensar en lo que hacía). La Historia Breve libera el segundo (ya sabe quién eres y a qué vienes). Solo entonces tienes casi toda su atención — y solo entonces vale la pena presentar.\\n\\n**Esto explica por qué saltarse pasos no acelera nada: presentarle a alguien distraído es desperdiciar tu mejor material.**\\n\\n## 1.2 La Línea Recta `CAMPO` `UNIVERSAL`\\n\\nUna venta avanza en línea recta, de izquierda a derecha, a través de los 6 pasos.\\n\\n**Nada te regresa. Lo que ya recorriste, quedó.** Lo único que puede pasar es que algo te **saque de la línea y te pause**.\\n\\nLa imagen: vas dibujando la línea hacia la derecha y de pronto llega una objeción. Ahí dejas de avanzar y la línea sube — saliste. Pero no retrocede. Está en ti resolver y volver al punto donde ibas.\\n\\n| Elemento | Relación con la línea |\\n|---|---|\\n| Los 6 pasos | La línea misma |\\n| CPR / FORMS | Salida **deliberada** — sales tú, y regresas |\\n| Bloqueos → AIR, Ataque Preventivo | Salida **impuesta** al inicio |\\n| Objeciones → RRR, FFF | Salida **impuesta** después de entender |\\n| Close With Action | Lo que te devuelve y te mueve al siguiente tramo |\\n| Los 3 No seguidos | La señal de que ya no hay línea que recorrer |\\n\\n**Diagnóstico que le da al vendedor:** cuando una visita sale mal, la pregunta no es *\\"¿qué técnica olvidé?\\"* sino **\\"¿dónde salí de la línea y por qué no regresé?\\"**\\n\\n## 1.3 El principio de la balanza `FUENTE` `UNIVERSAL`\\n\\nNadie compra por precio. Compra cuando el **valor percibido** pesa más que el **costo percibido**. Cuanto mayor la brecha, mayor el impulso.\\n\\nY el costo no es solo dinero: es tiempo, riesgo de cambiar, esfuerzo, y la posibilidad de haberse equivocado.\\n\\n> **La regla que convierte esto en herramienta:** con cada frase, cada gesto y cada silencio estás haciendo una de cuatro cosas — subiendo el valor, bajándolo, subiendo el costo, o bajándolo.\\n>\\n> **No hay frases neutras.**\\n\\nDe aquí se deducen cosas que ninguna lista de reglas contiene:\\n- Titubear al dar un precio sube el costo percibido\\n- Disculparte baja tu valor\\n- Mencionar algo que **no** tienes, no aplica o no está disponible **baja el valor sin que nadie te lo pidiera** — y por eso se omite\\n- Contar un caso real de otro cliente sube el valor\\n\\n**Cost vs Value no es tanto una habilidad como una herramienta de evaluación:** revisa cada parte de tu conversación y pregúntate qué plato movió.\\n\\n## 1.4 La gente compra, pero no quiere que le vendan `FUENTE`\\n\\nEste es el principio psicológico que atraviesa todo el sistema.\\n\\nA las personas les gusta comprar. Lo que les desagrada es **sentir que les están vendiendo**. Tienen una alarma calibrada para detectar al vendedor, y en cuanto se activa, todo lo que digas después se procesa con desconfianza.\\n\\n> **Casi todas las técnicas de este sistema son formas de obtener un resultado de venta sin activar esa alarma.**\\n\\n- **Gasman** — pedir permiso te delata como forastero; asumir que perteneces no dispara nada\\n- **CPR** — ser persona antes que vendedor\\n- **Descubrimiento** — el vendedor promedio habla; el que pregunta rompe el patrón que la alarma busca\\n- **Close With Action** — nunca pides el sí, porque pedirlo enciende la alarma\\n- **Indiferencia** — la presión genera resistencia; quitarla la disuelve\\n- **FFF** — estar de acuerdo primero te vuelve distinto del vendedor promedio, *y por eso te escuchan*\\n\\n## 1.5 La decisión es emocional antes que racional `CAMPO`\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente siente algo primero, y después construye la razón que lo justifica.\\n\\nEsto no contradice el diagnóstico ni la construcción de valor: los explica. La doctrina fuente lo dice sin rodeos — **\\"el impulso es otra palabra para la emoción\\"**.\\n\\n**Lo que se deduce de aquí, y que corrige el error de modelar la venta como un proceso lógico:**\\n\\n- **El cliente no necesita reconocer un problema para sentir el alivio de resolverlo.** Por eso \\"pintar imágenes\\" funciona: no argumenta, hace sentir.\\n- **Pelear por el reconocimiento explícito mata la venta.** Insistir en que admita algo lo pone a la defensiva, y la defensiva apaga lo emocional — que era donde estaba la venta.\\n- **El 80% indiferente no tiene un problema urgente**, y aun así compra. Se mueve por los factores de impulso, no por el diagnóstico.\\n- **Un argumento perfecto dicho por alguien en quien no confía, no pesa.** Y uno mediocre dicho por alguien cercano, sí. De ahí la importancia real del CPR.\\n\\n> **La regla operativa:** el sistema construye una situación deseable, no un caso lógico. La razón sirve para que el cliente pueda **justificar** la decisión — no para que la tome.\\n\\n⚠️ **Y esto no autoriza a manipular.** El Nivel 1 sigue intacto: el impulso se construye con verdad. La diferencia es que construir una imagen real y deseable es legítimo; fabricar urgencia, escasez o problemas no lo es.\\n\\n---","is_active":false,"created_at":"2026-08-31T18:53:24.782663+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"68add4b4-b19a-4843-a3be-2f7809a9f38b","version":1,"section_key":"pasos","order_index":2,"title":"PARTE 2 · LOS 6 PASOS","body":"# PARTE 2 · LOS 6 PASOS\\n\\nEl sistema original tiene **5 pasos** `FUENTE`: Introducción, Historia Breve, Presentación, Cierre, Consolidación.\\n\\nCloser enseña **6** `CAMPO`: se separa **Descubrimiento** como paso propio. En la fuente las preguntas de calificación viven dentro del flujo; separarlas reconoce que diagnosticar y presentar son habilidades distintas que fallan por razones distintas.\\n\\n---\\n\\n## PASO 1 · INTRODUCCIÓN\\n### *Una sola oportunidad para una primera impresión*\\n\\n**Qué logra:** liberar el primer tercio de atención y ganarte el derecho a seguir hablando.\\n\\n**Qué NO es:** aquí no dices quién eres ni a qué vienes. Eso es el Paso 2. Confundirlos es el error doctrinal más común.\\n\\n### SEE / SCE `FUENTE` `PRESENCIAL`\\n**S**mile · **E**ye contact · **E**nthusiasm — Sonrisa, Contacto visual, Entusiasmo\\n\\n- **Sonrisa** — signo internacional de amistad. Elimina el miedo y crea confianza.\\n- **Contacto visual** — genera confianza, mantiene el control de la conversación, **y es una señal de compra fuerte cuando el cliente lo hace**.\\n- **Entusiasmo** — crea impulso y curiosidad. Si estás emocionado, asumen que hablas de algo emocionante. **Y al revés también funciona:** si suenas aburrido de tu producto, nadie va a estar más emocionado que tú.\\n\\nSe combinan con **lenguaje corporal abierto** y **tono de voz fuerte**.\\n\\n> ⚠️ **Límite de canal:** SEE es físico. En texto o voz no se puede evaluar. Se enseña, se pide, y se marca como *\\"esto se practica en persona\\"*. Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**.\\n\\n### Regla del 10% `FUENTE` `PRESENCIAL`\\nLee el nivel de emoción del cliente y ponte **10% por encima** de él. No al doble: 10%.\\n\\n**Por qué:** llegar gritando con alguien tranquilo lo aleja tanto como llegar apagado con alguien entusiasmado. El 10% jala sin romper.\\n\\n### Ice Breaker `FUENTE` `UNIVERSAL`\\nCumplido genuino, chiste sencillo o comentario ligero.\\n\\nPuede ser sobre **la persona**, **el lugar**, o **algo en común**. No está atado a ningún tipo de negocio.\\n\\n**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee al instante y se cierra **más** que antes — porque ahora sabe que le están aplicando una técnica.\\n\\n### Teoría del Gasman `FUENTE` `UNIVERSAL`\\nSer asumido y confiado, con alta indiferencia.\\n\\nEl gasista que viene a leer tu medidor entra con una autoridad que nace de sentir que **debe estar ahí** — no es una intrusión. Nadie lo detiene, y no es por su permiso: es por su postura.\\n\\n> **El mecanismo:** cuando preguntas *\\"¿tiene un minutito?\\"* haces dos cosas a la vez — le entregas el control, y le ofreces una salida que no le cuesta nada tomar. El cliente que dice \\"ahorita no\\" no está siendo grosero: tomó la puerta que le abriste.\\n>\\n> **La autoridad no se pide. Se asume.**\\n\\n### Regla doctrinal del paso `CAMPO`\\n**La identificación (nombre y empresa) es permitida pero nunca requerida aquí.** Su ausencia jamás se penaliza.\\n\\nSi el cliente pregunta *\\"¿y usted quién es?\\"*, **ganaste la introducción** — esa pregunta es la puerta natural al Paso 2, no una falla.\\n\\n---\\n\\n## PASO 2 · HISTORIA BREVE\\n### *Explica tu propósito de manera concisa*\\n\\n**Qué logra:** liberar el segundo tercio de atención. El cliente deja de preguntarse quién eres y qué quieres.\\n\\n### KISS vs KILL `FUENTE` `UNIVERSAL`\\n**K**eep **I**t **S**hort and **S**imple — contra **K**eep **I**t **L**ong and **L**engthy.\\n\\nQuién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible.\\n\\n> **El mecanismo:** cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él — y de los discursos uno se defiende.\\n\\n**Y después de la historia, preguntas.** La fuente es explícita: *\\"en la mayoría de los casos es más efectivo pasar directamente a las preguntas de calificación que dar una larga explicación.\\"*\\n\\nTu historia breve no existe para que te entiendan a ti. **Existe para ganarte el derecho de preguntarle a él.**\\n\\n### CPR — Create Personal Relations `FUENTE` `UNIVERSAL`\\n> *\\"Eres tanto, si no más, el producto que los productos que representas.\\"*\\n\\n**Se aplica durante TODA la conversación**, no en un paso.\\n\\n**El mecanismo:** el cliente no puede evaluar tu producto todavía — no lo ha probado, no conoce tu empresa, no sabe si le van a cumplir. Lo único que sí puede evaluar desde el primer segundo **eres tú**. Y esa evaluación la hace mucho antes que la otra.\\n\\n**Y hace dos trabajos distintos, ambos indispensables:**\\n\\n**1 · Que te contesten de verdad.** Sin relación, las preguntas del Paso 3 reciben respuestas de cortesía. A un desconocido nadie le cuenta lo que le está fallando.\\n\\n**2 · Que te crean.** Este es el más importante y el que casi nadie ve.\\n\\n> Si un amigo te dice que un producto es bueno, le crees. Si te lo dice alguien que gana comisión por vendértelo, lo descuentas automáticamente — no porque lo creas mentiroso, sino porque sabes que tiene interés.\\n>\\n> **Es la misma frase, dicha por dos personas, y produce dos efectos opuestos.**\\n\\nLo que decide cuál de los dos efectos produces **no es tu argumento: es qué tan cerca estás de ser alguien en quien confía.** Por eso el CPR no es cortesía ni relleno — **es lo que determina si tus argumentos pesan o se descuentan.**\\n\\nY conecta directo con el Efecto Jones: la gente no confía en un desconocido incentivado a vender, pero sí deja que gente cercana valide un producto. **El CPR te acerca a ese lado de la línea.**\\n\\n### FORMS `FUENTE` `UNIVERSAL`\\n**F**amily · **O**ccupation · **R**ecreation · **M**otivation · **S**ports\\n\\nLos cinco caminos a la persona. Más cumplidos genuinos y chistes sencillos.\\n\\n> **La palabra que lo decide todo es *genuinos*.** Un interés fingido se nota, y cuesta más que no haber preguntado — porque ahora el cliente sabe que le aplicaste una técnica. Si un tema no te interesa de verdad, busca otro de los cinco.\\n\\n**No requiere cierta personalidad ni ser naturalmente extrovertido: se aprende.**\\n\\n### El desvío con regreso `CAMPO` `UNIVERSAL`\\nLa mecánica que hace que el CPR no mate la venta.\\n\\nSales de la línea a propósito, das **uno o dos intercambios personales**, y **regresas**. Puedes volver a salir más adelante, pero siempre avanzando.\\n\\n**Dos errores, ambos caros:**\\n- **Nunca salir** → no hay relación, y no te van a contestar nada en el Paso 3\\n- **Salir y no regresar** → el cliente se acomoda a platicar y la venta se estanca\\n\\n> **El cliente NUNCA te va a regresar a la línea.** Cuando la plática se pone agradable, él está cómodo — nadie interrumpe una conversación agradable para hablar de negocios. El único que puede regresar eres tú.\\n\\n### Bloqueo vs Objeción `FUENTE` — *la distinción que organiza todo el manejo de resistencia*\\n\\n**BLOQUEO** — un reflejo. Llega **ANTES** de entender.\\n*\\"No tengo tiempo\\" · \\"No me interesa\\" · \\"No estoy comprando nada\\" · \\"Ya tengo con quién\\"*\\nNo hubo procesamiento. Es la puerta cerrándose sola.\\n\\n**OBJECIÓN** — una preocupación razonada. Llega **DESPUÉS** de entender.\\n*\\"Está caro\\" · \\"Ya tengo proveedor y me cumple\\" · \\"Lo tengo que consultar\\"*\\nAquí sí hubo pensamiento.\\n\\n> **Por qué importa la diferencia:** discutir con un reflejo lo convierte en una posición. El cliente dijo \\"no me interesa\\" sin pensarlo; si lo peleas, tiene que defenderlo — y al defenderlo se lo cree. **Le acabas de crear un \\"no\\" real que no tenía.**\\n>\\n> E ignorar una objeción real ofende a alguien que sí te escuchó y sí pensó.\\n>\\n> **La misma frase se maneja de dos maneras opuestas según cuándo llegó.**\\n\\n### AIR `FUENTE` `UNIVERSAL`\\n**A**gree · **I**gnore · **R**esume — Acepta, Ignora, Resume\\n**Cuándo:** bloqueos al inicio.\\n**Cómo:** reconoce con *\\"entiendo\\"* o *\\"por supuesto\\"*, no lo discutas, y continúa.\\n\\n> **El tercer movimiento es el que falla.** Casi todos aceptan bien y casi todos logran no discutir — y después se quedan parados esperando, o peor, vuelven a pedir permiso. Ahí se pierde todo lo ganado.\\n\\n### Ataque Preventivo `FUENTE` `UNIVERSAL`\\n**Cuándo:** intro o historia breve, si hay negativos comunes del territorio.\\n**Cómo:** *\\"si das la negativa antes de que el cliente lo haga, ya no es una negativa.\\"*\\n\\n**El mecanismo:** le quitas el argumento de las manos, y además te vuelves creíble — **quien reconoce lo malo se gana el derecho a que le crean lo bueno.**\\n\\n**Dos formas de arruinarlo:**\\n- **En tono de disculpa** → deja de ser adelantarse y se vuelve defenderse de algo que nadie reclamó\\n- **Con un negativo inventado** → no desactivas nada, plantas una preocupación nueva\\n\\n### Close With Action `FUENTE (dentro de FFF) + CAMPO (generalizado)` `UNIVERSAL`\\n**Es el Poder de Sugestión en ejecución.**\\n\\nUna pregunta o acción cuya respuesta **solo tiene sentido si el cliente está avanzando**. Su respuesta *es* el sí. Nunca lo pides explícito.\\n\\n- *\\"¿Cómo se escribe su apellido?\\"* → al contestar, aceptó tu respuesta y sigue en el alta\\n- *\\"¿Prefiere el jueves o el viernes?\\"* → *\\"el viernes\\"* significa que lo quiere **y** cuándo\\n\\n**Se ejecuta en cada tramo de la línea:** en descubrimiento es la siguiente pregunta; en presentación es continuar donde ibas; en cierre es la alternativa de sí/sí.\\n\\n> **El momento crítico:** justo después de resolver algo. El vendedor promedio se queda callado esperando permiso para seguir. En ese silencio el cliente retoma el control y cierra la conversación con amabilidad. **No te está rechazando: le devolviste el volante.**\\n\\n---\\n\\n## PASO 3 · DESCUBRIMIENTO `CAMPO`\\n### *Encontrar el dolor real*\\n\\n*No existe como paso en la fuente. Toda esta sección es construcción de Closer sobre el principio de \\"preguntas de calificación\\".*\\n\\n### El principio rector\\n**Primero el examen, luego la receta.** El vendedor promedio llega a recetar: trae su producto favorito buscando dónde encajarlo. El Closer llega a diagnosticar.\\n\\n**La ironía:** el que pregunta vende más que el que habla.\\n\\n### RRR — Read, Relate, Relax `FUENTE` `UNIVERSAL`\\nLee · Conecta · Relaja.\\n\\nTres cosas que leer: **el ambiente, la demografía de la persona, y su estado de ánimo.**\\n\\n**El mecanismo:** no quieres forzar a nadie a subir a tu nivel de emoción ni a adaptarse a ti. **Tú te adaptas primero.**\\n\\n> ⚠️ **Colisión de acrónimos:** existe un segundo RRR en la doctrina (Repeat, Reassure, Resume) para objeciones. Ambos se conservan con su nombre original. Al enseñar el segundo hay que advertirlo explícitamente.\\n\\n### Los 3 Territorios del Dolor `CLOSER` `UNIVERSAL`\\nTodo dolor comercial vive en uno de tres territorios:\\n\\n- **PRODUCTO** — lo que vende o usa\\n- **SERVICIO** — cómo lo trata su proveedor actual\\n- **PRECIO** — lo que paga y lo que gana\\n\\n> **El mismo territorio se pregunta distinto según el tipo de cliente.** Ver Parte 4.\\n\\n#### Cómo se investiga el territorio PRECIO `CAMPO`\\n\\nEl territorio PRECIO es el más fácil de arruinar, porque la pregunta natural es la incorrecta.\\n\\n⚠️ **NUNCA le pidas al cliente su opinión ni su aprobación sobre precios.** Prohibido: *\\"¿cómo ve los precios?\\"*, *\\"¿hay algo que sienta muy arriba?\\"*, *\\"¿le parece competitivo?\\"*, *\\"¿estoy bien de precio?\\"*\\n\\n**Tres razones, y cada una basta:**\\n\\n**1. Le pides que construya una posición sobre tu precio antes de que exista valor.** Si contesta *\\"están caros\\"*, ya no es una impresión: es algo que declaró en voz alta y ahora tiene que defender. **Te creaste una objeción de precio que no existía.**\\n\\n**2. Cedes la autoridad sobre el precio.** El precio no lo determina la percepción del cliente: lo determina lo que ofreces. Preguntarle su opinión comunica que estás dispuesto a moverlo según lo que conteste, y te vuelve regateable antes de haber presentado nada.\\n\\n**3. Renuncias a tu ventaja.** Tú conoces el mercado: ya sabes qué está caro y qué está barato. **Muchas veces el cliente no sabe que está pagando de más, y tú sí.** Preguntarle su opinión te iguala a alguien que no sabe, cuando saber es exactamente lo que te hace valioso.\\n\\n**Lo que sí se investiga en este territorio son HECHOS, no opiniones:**\\n\\n- ¿A cómo compra hoy? (dato)\\n- ¿Cada cuánto le suben? ¿Le avisan antes? (dato)\\n- ¿Le manejan crédito o de contado? ¿Qué plazo? (dato)\\n- ¿Cuánto le queda de margen en esa línea? (dato)\\n- ¿Le ha tocado que un cliente se le vaya por precio? (experiencia, no opinión)\\n\\n**La diferencia:** un hecho te da información que puedes usar. Una opinión sobre tu precio te da una objeción que tendrás que atravesar.\\n\\n> **Y si el cliente dice que tu precio está mal, el diagnóstico correcto no es bajarlo.** Es que no encontraste su dolor, o no construiste suficiente valor. **El problema nunca está en el número: está en la balanza.**\\n\\n### La Escalera de Capas `CLOSER` `UNIVERSAL`\\n**CAPA 1 — Hechos.** Fáciles, cero riesgo. Abren la plática y te dan el mapa.\\n**CAPA 2 — La puerta.** Aquí el cliente suelta una pista... o cierra con un \\"bien\\". Depende de cómo preguntes.\\n**CAPA 3 — El dolor.** Solo se abre si recoges la pista y profundizas con preguntas abiertas.\\n\\n### La Pregunta Específica `CAMPO` `UNIVERSAL`\\n> **El \\"bien\\" no es información: es un reflejo social.**\\n\\nCuando preguntas *\\"¿qué tal le va?\\"*, el cliente no consulta su experiencia — dispara la respuesta cortés que trae cargada. Y admitir un problema ante un desconocido tiene costo social: parece queja, o parece que eligió mal.\\n\\n**La solución tiene dos formas:**\\n- **ESPECÍFICA** — nombra un dato o situación concreta que tenga que ir a buscar. *\\"¿Le ha tocado quedarse sin su producto estrella?\\"*\\n- **NORMALIZADA** — da permiso citando a otros. *\\"Varios clientes me comentan que batallan con faltantes, ¿a usted le pasa?\\"* (Es el Efecto Jones aplicado a descubrimiento.)\\n\\n**Y el orden importa:** concreta para **abrir** (capa 2), abierta para **excavar** (capa 3).\\n\\n#### Suggestive Language — dale de dónde agarrarse `FUENTE` `UNIVERSAL`\\n\\nEs la S de FUJIES aplicada al descubrimiento, y es lo que convierte una pregunta que se muere en una que da información.\\n\\n**El problema de la pregunta abierta sola:** obliga al cliente a construir la respuesta desde cero. Eso cuesta esfuerzo, y como no le urge ayudarte, contesta lo más corto que puede — o de plano *\\"pues no sé\\"*.\\n\\n**La solución: después de preguntar, sugiere opciones.**\\n\\n> *\\"¿Qué familias son las que más se te mueven? ¿Anticongelantes? ¿Aceite de motor? ¿Diésel? ¿Moto?\\"*\\n>\\n> *\\"¿A cómo compras el líquido de frenos? ¿70? ¿80? ¿90?\\"*\\n\\n**Por qué funciona, y son tres cosas a la vez:**\\n\\n1. **Le das de dónde agarrarse.** O elige una de tus opciones, o te corrige con el dato real — *\\"no, más bien 95\\"*. **Y esa corrección es información que la pregunta abierta nunca habría sacado.**\\n\\n2. **Le demuestras que conoces su negocio.** Nombrar las familias correctas o el rango de precio correcto te posiciona como alguien que sabe, no como alguien que está averiguando.\\n\\n3. **Crea un poco de urgencia.** Una pregunta con opciones se contesta rápido; una abierta se puede posponer con un *\\"déjame ver\\"*.\\n\\n**Cómo se usa bien:**\\n- Las opciones tienen que ser **reales y del giro del cliente**. Si sugieres familias que él no maneja, demuestras lo contrario de lo que buscabas.\\n- **Tres o cuatro, no una lista.** Es para ayudarlo a contestar, no para que elija de un catálogo.\\n- El rango de precio **tiene que ser creíble.** Sugerir cifras muy lejanas de la realidad te desacredita.\\n- Y **no lo uses para plantar una respuesta.** Si el cliente te corrige, esa es la respuesta buena — no insistas en la tuya.\\n\\n> **Es la misma lógica del cierre de alternativa, aplicada al descubrimiento:** no preguntas al aire, das opciones donde cualquier respuesta te sirve.\\n\\n### El Barrido `CLOSER` `UNIVERSAL`\\nTerritorio limpio → ni insistas ni te rindas: **cambia de territorio.**\\n\\nEl dolor casi siempre existe, solo que vive en otra zona del mapa. Insistir en zona sana te vuelve interrogador; rendirte regala la visita.\\n\\n### El dolor y la confirmación `CLOSER` `UNIVERSAL`\\nCuando el dolor aparece, **devuélveselo con SUS palabras**. *\\"Entonces lo que más le pega es X, ¿cierto?\\"*\\n\\nEso hace dos cosas: confirma que entendiste, y **le da forma consciente a algo que a lo mejor solo sentía.**\\n\\n> ⚠️ **Pero la confirmación explícita no es requisito para avanzar.**\\n>\\n> Muchas veces el cliente no va a admitir el problema. No porque no lo tenga — sino porque admitirlo suena a queja, o a que eligió mal, o simplemente porque **no lo tiene consciente**. Nadie anda por la vida con una lista de sus problemas operativos.\\n>\\n> Y aun así te sigue escuchando. **Eso ya es información.**\\n\\n**Lo que sí necesitas** es haber leído el problema con evidencia suficiente: algo que dijo, algo que viste, algo que su tipo de negocio hace probable. **Lo que no necesitas es su permiso verbal.**\\n\\n### La venta es emocional antes que racional `CAMPO`\\n\\nEste es el principio que corrige el error de modelar la venta como un proceso lógico.\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente no llena una hoja de cálculo: siente algo, y después construye la razón.\\n\\nConsecuencias que cambian cómo se ejecuta todo el sistema:\\n\\n- **Un cliente puede no reconocer un problema y aun así sentir alivio cuando se lo resuelves.** El impulso no viene de que aceptó el diagnóstico: viene de imaginar la situación resuelta.\\n- **Por eso \\"pintar imágenes\\" funciona** — no argumenta, hace sentir.\\n- **Por eso el vendedor no debe pelear por el reconocimiento explícito.** Insistir en que el cliente admita un problema lo pone a la defensiva y mata lo emocional, que era donde estaba la venta.\\n- **Y por eso el impulso se puede construir sin que haya un dolor declarado.** El 80% indiferente no tiene un problema urgente: se mueve por los factores de impulso, no por el diagnóstico.\\n\\n**La regla operativa:** si el cliente confirma el dolor, úsalo con sus palabras — es lo más fuerte que tienes. **Si no lo confirma pero la evidencia está, avanza igual**, presentando la situación resuelta en vez del problema reconocido.\\n\\n⚠️ **Lo que sigue prohibido es fabricar.** Leer un dolor probable no es inventarlo. La diferencia: leer se apoya en evidencia real — algo que dijo, algo que viste, algo propio de su giro. Fabricar es afirmar un problema **que el cliente ya negó** o del que no hay ningún indicio.\\n\\n### La regla del investigador\\n**El dolor nunca se pregunta directo.** *\\"¿Qué problemas tiene?\\"* produce *\\"ninguno\\"*, garantizado. Se deja emerger.\\n\\n### Luz Verde — 10/80/10 `FUENTE` `UNIVERSAL`\\n**10% negativos · 80% indiferentes · 10% positivos.**\\n\\n1. Sal de las luces rojas **rápido y educadamente**\\n2. Las amarillas reciben tu mejor presentación — pero si no dan señales de compra, muévete\\n3. Las verdes reciben tiempo, relación y resolución de dudas\\n\\n**Los factores de impulso existen principalmente para convertir al 80% indiferente.**\\n\\n#### El rojo verdadero y el que quiere pero no puede `CAMPO`\\n\\nLa luz roja no es cualquier \\"no\\". Es un tipo específico de cliente, y confundirlo cuesta ventas.\\n\\n**ROJO GENUINO** — no quiere. Es cortante, tajante, desganado. Muchas veces medio grosero. Y tiene un costo escondido: **interactuar de más con él desgasta tu actitud**, que es la variable de entrada de todo tu sistema. Con este, salir rápido y bien es la ejecución correcta.\\n\\n**AMARRADO TEMPORALMENTE** — quiere y no puede. Te recibe con gusto, te habla con honestidad, y su impedimento es una **circunstancia que va a cambiar**: un contrato de exclusividad, un inventario recién surtido, un presupuesto agotado, no ser él quien decide las compras grandes.\\n\\n> **Este no es rojo: es verde amarrado.** Y con él, rendirse es la falla más cara del oficio — porque ese cliente sí quería comprarte y el vendedor se fue solo.\\n\\n**Cómo se distinguen:** el rojo se nota en el trato. Es seco, no da información, quiere que te vayas. El amarrado hace lo contrario: es amable, te explica su situación con detalle, y muchas veces se disculpa por no poder.\\n\\n#### Casi toda restricción tiene bordes `CAMPO`\\n\\nY aquí está la mecánica que separa al vendedor promedio del que crece cuentas.\\n\\nCuando un cliente dice que no puede, **el promedio lo toma como total y se va**. El Closer investiga hasta dónde llega:\\n\\n- **¿Qué cubre exactamente?** Una exclusividad casi nunca abarca todas las familias\\n- **¿Qué queda fuera?** Ahí está la venta que la competencia no vio\\n- **¿Hasta cuándo dura?** Para volver justo cuando se libere, antes que nadie\\n\\n> Un contrato que cubre lubricantes, anticongelantes y grasas **deja fuera el líquido de frenos.** Y el vendedor que preguntó se lleva una venta de un cliente que \\"no podía comprar\\".\\n\\n**Y la relación sigue construyéndose mientras tanto.** Seguir visitando a un amarrado no es perder el tiempo: es estar presente el día que la restricción se acabe. El que se rindió no va a estar ahí.\\n\\n⚠️ **La línea:** investigar los bordes no es presionar. Si el cliente ya dijo que algo está dentro de su compromiso, insistir en eso es pedirle que rompa su palabra — y eso quema la relación. Se busca lo que **sí** puede, nunca se pelea lo que no.\\n\\n### QTQP `FUENTE` `UNIVERSAL`\\n**Q**uality **T**ime with **Q**uality **P**eople.\\n\\n> *\\"Perder tiempo y energía con las personas equivocadas destruye tu capacidad de ser lo suficientemente urgente\\"* — y la urgencia es de lo que vive tu ley de promedios.\\n\\nCada minuto con un rojo se lo quitas a un amarillo que sí podía comprar hoy.\\n\\n---\\n\\n## PASO 4 · PRESENTACIÓN\\n### *Construye valor y disminuye el costo*\\n\\n**Qué logra:** convertir el dolor descubierto en valor percibido, y subir el impulso.\\n\\n### Las herramientas de la presentación `FUENTE`\\n1. Encontrar problemas y proporcionar soluciones\\n2. **Pintar imágenes** — que imaginen que ya lo tienen\\n3. Incorporar factores de impulso\\n4. **Triple desglose de precios**\\n5. Hacer el valor enorme: lenguaje expansivo, *\\"gran\\"*, *\\"masivo\\"* `PRESENCIAL`\\n6. Hacer el costo pequeño: *\\"solo\\"*, *\\"apenas\\"* `PRESENCIAL`\\n7. **Tren del Sí** — preguntas cuya respuesta natural es sí\\n8. **CPR sostenido** durante toda la presentación\\n\\n### Beneficio, no característica `CLOSER` `UNIVERSAL`\\nUna característica es lo que el producto **es**. Nadie compra lo que algo es: compran **lo que van a ganar**.\\n\\nToda característica se traduce a una de tres cosas: **dinero** (gana más o gasta menos), **clientes** (vende más o los conserva), o **tranquilidad** (menos problemas, menos tiempo perdido).\\n\\n> Si el cliente puede contestar *\\"¿y eso a mí de qué me sirve?\\"*, la traducción falló.\\n\\n### Teoría de las Balas `FUENTE` `UNIVERSAL`\\n> *\\"La persona con más balas claramente tiene el control, siempre y cuando conserve su munición.\\"*\\n\\n**Las balas son TUYAS.** Son hechos positivos y concretos sobre:\\n- **Ti / tu empresa** — experiencia, premios, casos de éxito, dedicación\\n- **El producto** — lo que lo diferencia, mejoras, datos, certificaciones\\n- **El precio** — propuesta de valor, descuentos, financiamiento, comparación\\n\\n**La prueba de si algo es bala:** si la competencia puede decir exactamente lo mismo, no era bala. *\\"Somos los mejores\\"* es aire; *\\"catorce años surtiendo esta zona sin fallar\\"* es bala.\\n\\n**La regla de dosificación:** *\\"no dispares todas las balas al principio. Reserva algunas para que no importe cuántas balas tenga tu cliente, tengas más con qué responder. Guarda balas para los pasos 4 y 5.\\"*\\n\\n> **Por qué se guardan:** más adelante el cliente va a poner razones para no comprar. Eso baja su impulso. Responderle bien solo **detiene la caída** — lo que vuelve a subirlo es **una bala nueva**. Si las gastaste presumiendo al principio, llegas a ese momento con la mano vacía.\\n\\n### FUJIES / FUJPIG — Factores de Impulso `FUENTE`\\n*\\"El impulso es otra palabra para la emoción.\\"*\\n\\n| | Factor | Físico `PRESENCIAL` | Verbal `UNIVERSAL` |\\n|---|---|---|---|\\n| **F** | Fear of Loss / Miedo a la pérdida | Producto en mano y quitarlo, retroceder un paso | *\\"solo hoy\\"*, *\\"tiempo limitado\\"*, *\\"quedan pocas\\"* |\\n| **U** | Urgency / Urgencia | Tic-tac con el bolígrafo, empezar a alejarse | *\\"ahora\\"*, *\\"rápido\\"*, *\\"solo toma un par de minutos\\"* |\\n| **G** | Greed / Avaricia | Manos mostrando altos y bajos | *\\"normalmente $100, con la promo queda en solo $59.99\\"* |\\n| **I** | Indifference / Indiferencia | Postura, lenguaje corporal | SW3 |\\n| **E** | Effect of Jones / Efecto Jones | — | *\\"tengo como 20 clientes en esta zona que...\\"* |\\n| **S** | Suggestive Language / Poder de sugestión | Manos altas precio alto, bajas precio bajo | Tren del sí, alternativas |\\n\\n**Miedo a la pérdida > necesidad de ganancia.** La gente dice que sí impulsivamente porque no quiere que algo se le vaya.\\n\\n**Urgencia:** *\\"motion creates emotion\\"*. Y además comunica que estás ocupado, o sea que tienes éxito.\\n\\n**Indiferencia:** *\\"be excited about the person and the product, but indifferent whether they buy.\\"* **SW3** — Some Will, Some Won''t, So What. *\\"Ellos solo tienen una oportunidad de comprarte; tú tienes más de cien clientes.\\"*\\n\\n**Efecto Jones:** de *\\"keeping up with the Joneses\\"*. La gente no confía naturalmente en un desconocido incentivado a vender — pero sí deja que sus vecinos, amigos y familia validen el producto por ella.\\n\\n**Poder de sugestión — tres niveles:**\\n- **Mental** — *\\"asumo que todos son un sí hasta que me digan que no\\"*\\n- **Físico** — lenguaje corporal `PRESENCIAL`\\n- **Verbal** — el tren del sí. **El cliente debería decir que sí al menos 6 veces durante el proceso.**\\n\\n> **Elimina cualquier opción que se pueda traducir en un no.** En vez de *\\"¿quiere algo de tomar?\\"* → *\\"¿té, café o jugo?\\"*\\n\\n### La Curva de Impulso `FUENTE` `UNIVERSAL`\\nEl impulso sube y baja durante la conversación, y hay que construirlo **gradualmente** para no abrumar.\\n\\n**Las tres reglas de oro:**\\n1. **Encuentra al cliente en un punto común de emoción** al inicio, y construye desde ahí\\n2. **Cierra en el momento correcto** — el pico\\n3. **Elimina el arrepentimiento con un rehash impulsivo** — porque después del sí, el impulso cae\\n\\n#### La presentación tiene dos mitades `CAMPO`\\n\\nY confundirlas es un error común, así que conviene tenerlas separadas.\\n\\n**PRIMERA MITAD — lo que vas a hacer por él.**\\nConectas con su dolor usando SUS palabras, y explicas cómo se lo resuelves. Aquí no hay producto todavía: hay un problema y una solución. *\\"Eso que me dice de quedarse sin producto cuando le entra movimiento — eso es venta que se le va.\\"*\\n\\n**SEGUNDA MITAD — el producto y el precio.**\\nUn resumen breve de qué es lo que le va a resolver eso, y el Triple Desglose de Precios. De ahí se pasa directo al cierre.\\n\\n> **El precio SÍ va en la presentación.** Lo que va en el cierre es el **resumen del pedido** — qué y cuánto lleva. Son dos cosas distintas:\\n>\\n> · **Presentación** → el precio en escalera con sus motivos. *\\"Normalmente le sale en X, como es primer pedido queda en Y, y de contado en Z.\\"*\\n> · **Cierre** → lo que lleva. *\\"Entonces le van dos cajas de esto y una de aquello. ¿Jueves o viernes?\\"*\\n>\\n> Enumerar SKUs con cantidades en la presentación es escribir el cierre en el lugar equivocado. Pero omitir el precio es dejar la presentación a medias — y el cliente se queda esperando el número que nunca llegó.\\n\\n### Triple Desglose de Precios `FUENTE (definido) + CAMPO (desarrollado)` `UNIVERSAL`\\n> **Valor menos costo es igual a ahorro.**\\n\\n**La escalera — tres cifras bajando:**\\n1. **Lo que normalmente cuesta** — hace match con lo que el cliente ya esperaba\\n2. **Con el primer descuento** — cliente nuevo, volumen, lo que aplique\\n3. **Con el segundo** — pago de contado, cerrar hoy, lo que corresponda\\n\\n**El ahorro dicho en voz alta.**\\n\\n> **La regla que lo hace funcionar: cada escalón necesita un motivo nombrado.**\\n>\\n> Un precio que baja **sin razón** le dice al cliente que el primero estaba inflado — y te vuelve regateable, porque si bajó dos veces solo, va a bajar otra si presiona.\\n>\\n> Un precio que baja **por razones nombradas** confirma que el primero era real, y cada escalón se vuelve una bala de precio.\\n\\n**Por qué se ve y no solo se escucha:** *\\"queda en ochenta\\"* se escucha como un gasto de ochenta. *\\"Normalmente cien, con su descuento noventa, de contado ochenta\\"* se ve como veinte de ahorro que antes no existían. Mismo número final, sensación opuesta.\\n\\n**Y como el último escalón depende de algo que puede hacer HOY, aparece solo el miedo a la pérdida.**\\n\\n> ⚠️ **Nunca un solo precio.** Un precio suelto es un gasto sin ahorro visible que lo compense.\\n\\n---\\n\\n## PASO 5 · CIERRE\\n### *Extrae eficientemente una decisión*\\n\\n### Qué es un cierre `FUENTE`\\n> *\\"Un cierre no es algo que le haces a alguien. Un cierre es un acuerdo, cuando el cliente se da cuenta de que el beneficio supera al costo y decide. El cierre se lo hace la gente a sí misma.\\"*\\n\\n**Un cierre no siempre es una venta.** Es pedir la decisión, sea cual sea. Asegúrate de que tus conversaciones avancen hacia una conclusión — un sí o un no.\\n\\n### Asumir la venta `FUENTE` `UNIVERSAL`\\nSi llegaste a este punto, **presume que tienes un comprador**.\\n\\n**Malos cierres** — todos invitan al no:\\n*¿Le gustaría comprar? · ¿Está interesado? · ¿Le gusta lo que oye? · ¿Qué le parece? · ¿Cómo lo ve?*\\n\\n**Buenos cierres** — alternativas donde ambas opciones sirven:\\n*¿Es su nombre el que va en la cuenta? · Las primeras fechas de entrega son jueves o viernes, ¿cuál le conviene? · ¿Visa o MasterCard? · ¿Contado o crédito?*\\n\\n> **El diagnóstico de la fuente:** *\\"la mayoría de las personas que batallan para cerrar simplemente no están rompiendo la zona de confort que viene con pedir algo.\\"*\\n>\\n> Y: *\\"aumentas la probabilidad de que compren mientras más confiadamente anuncies tu mensaje.\\"*\\n\\n### El silencio después del cierre `CAMPO` `UNIVERSAL`\\nNo llenes el silencio. Pediste la decisión: **aguanta**.\\n\\nEl vendedor que retira la pregunta, la suaviza o la contesta él mismo, pierde. El primero que habla después de un cierre, pierde.\\n\\n### FISHBBOD — Señales de Compra `FUENTE`\\nTambién llamadas **STOP signs**. En cuanto reconoces una, **DETIENES la presentación y CIERRAS**.\\n\\n**F** Future talk · **I** I want / I need · **S** Silence · **H** How much / How soon · **B** Body language `PRESENCIAL` · **B** Bashing competitor · **O** Offers of courtesy · **D** Deeper questions\\n\\n> **El error que cuesta más ventas de lo que nadie cree:** el cliente da la señal, el vendedor la ve, y como todavía le quedaban dos argumentos buenos, los suelta.\\n>\\n> **El impulso baja.** Porque el cliente ya estaba listo, y seguir vendiéndole le comunica que hay algo que convencerlo — o le da tiempo de encontrar una razón para no hacerlo.\\n>\\n> Señal de compra = deja de presentar y cierra. **Aunque te queden balas. De hecho, sobre todo si te quedan.**\\n\\n---\\n\\n## MANEJO DE OBJECIONES `FUENTE`\\n### *No son negativas: son preguntas que, bien respondidas, terminan en venta*\\n\\n**Objeción = señal de compra.** El que no tiene interés no objeta: se despide.\\n\\n### Las cuatro técnicas de overturn\\n\\n| Técnica | Cuándo | Cómo |\\n|---|---|---|\\n| **AIR** — Agree, Ignore, Resume | Bloqueos en la introducción | Reconoce, ignora, continúa |\\n| **Ataque Preventivo** | Intro o historia breve, negativos conocidos del territorio | Da el negativo antes que el cliente |\\n| **RRR** — Repeat, Reassure, Resume | Objeciones menores y comunes | Repite, responde, **continúa sin pausa** |\\n| **FFF** — Feel, Felt, Found | Preocupación seria o personal | Nunca discutas |\\n\\n### RRR de objeciones `FUENTE` `UNIVERSAL`\\n**R**epeat — repite la objeción en sus términos, para que vea que la escuchaste\\n**R**eassure — la respuesta concreta, con datos\\n**R**esume — **retoma sin pausa**\\n\\n> **La tercera R es la que falla.** El vendedor responde bien y se queda callado esperando a ver si convenció. En ese espacio el cliente encuentra la siguiente objeción, o dice que lo va a pensar.\\n\\n### FFF — el procedimiento completo `FUENTE` `UNIVERSAL`\\n**Nunca discutas con un cliente.** Ganar la discusión es perder la venta.\\n\\nEn español: **Entiendo · Sintió · Encontramos**\\n\\n1. **\\"Entiendo cómo se siente\\"** — estar de acuerdo te vuelve distinto del vendedor promedio, **y por eso te escuchan**\\n2. **\\"Mi último cliente sentía lo mismo\\"** — para que sepa que no está solo\\n3. **\\"Lo que encontramos fue...\\"** — por qué dejaron de pensar así. **Esto usa Efecto Jones**\\n4. **Inserta 3 balas** de la Teoría de las Balas\\n5. **Close With Action**\\n\\n> ⚠️ **FFF no termina en la tercera F.** El documento en español del sistema fuente está truncado y solo llega al paso 3 — por eso mucha gente aprendió un FFF incompleto, sin re-impulso y sin cierre. **Los pasos 4 y 5 son el Círculo de Cierre.**\\n\\n### El Círculo de Cierre `FUENTE (implícito) + CAMPO (nombrado)` `UNIVERSAL`\\n\\n```\\n   CLOSE WITH ACTION ←──────────────┐\\n            ↓                        │\\n   ¿Objeción? → el impulso baja      │\\n            ↓                        │\\n   Atraviesas (RRR o FFF)            │\\n            ↓                        │\\n   RE-IMPULSAS con una bala NUEVA ───┘\\n```\\n\\n> **El error más común: atravesar la objeción y cerrar de inmediato, saltándose la bala.**\\n>\\n> Técnicamente respondiste. Pero **atravesar solo detiene la caída del impulso** — no lo sube. Estás pidiendo una decisión en el punto más bajo de la conversación, y desde ahí la respuesta cómoda siempre es *\\"déjeme lo pienso\\"*.\\n\\n**Y la bala tiene que ser NUEVA.** Repetir un argumento ya usado no sube nada: comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.\\n\\n### La Regla de los No\\n- **Fuente:** *2 no''s and a go* — dos no seguidos, luz roja, sigue adelante\\n- **Campo `CAMPO`:** Emilio usa **3 no seguidos**, porque hay gente que deja ir un sí solo porque el cliente tuvo preguntas u objeciones\\n\\n> **Tienen que ser CONSECUTIVOS.** Un no, lo atraviesas, la conversación avanza, y más adelante otro no: **eso no es una racha**. Es una conversación normal con dos momentos de fricción. La racha se rompe en cuanto la conversación avanza.\\n\\n---\\n\\n## PASO 6 · CONSOLIDACIÓN / REHASH\\n### *El paso final y más importante*\\n\\n**REHASH** = **R**emember **E**veryone **H**as **A**nother **S**ale **H**idden\\n\\n**Dos propósitos** `FUENTE`:\\n1. **Capitalizar a un cliente ya positivo** — *\\"la gente compra de sus amigos mucho más fácil que de un desconocido\\"*\\n2. **Dejarlo positivo y entendiendo los siguientes pasos** — *\\"la causa número uno de cancelaciones es la falta de entendimiento\\"*\\n\\n### El arrepentimiento del comprador\\nApenas dice que sí, **el impulso cae**. El cerebro empieza a buscar razones por las que quizá no debió. Es automático y no es desconfianza hacia ti.\\n\\n### Cómo se disuelve `CAMPO`\\n> **El error que parece lo correcto: seguir vendiendo.**\\n>\\n> La reacción natural es reforzar la compra — recordarle lo bueno del producto, repetirle el ahorro, insistir en que tomó una gran decisión.\\n>\\n> **Y eso lo empeora.** Seguir vendiendo después del sí le dice al cliente que **necesitabas la venta**. Y si la necesitabas, entonces la indiferencia era actuada. Y si la indiferencia era actuada, también el interés por su negocio, también las preguntas, también la plática de su hijo.\\n>\\n> **Retroactivamente, toda la conversación se convierte en una técnica.**\\n\\n**Lo que sí funciona: demostrar que nada cambió en ti.**\\n\\nMisma indiferencia sobre la compra. Misma calidez sobre la relación. Cero producto. Y la confianza de que ahí vas a estar para lo que necesite.\\n\\n**Por qué funciona:** si tu actitud es idéntica antes y después de la firma, el cliente concluye solo lo que ninguna frase habría logrado convencerlo — **que no lo trataste así para venderle, sino porque así eres.** Y con esa conclusión, el arrepentimiento no tiene de qué agarrarse.\\n\\n**Y deja claro qué sigue.** La falta de entendimiento es la causa número uno de cancelaciones.\\n\\n---","is_active":false,"created_at":"2026-08-31T18:53:24.958974+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"32c3797e-b0f0-48be-b534-938ff62c1f47","version":1,"section_key":"mentalidad","order_index":3,"title":"PARTE 3 · LA MENTALIDAD","body":"# PARTE 3 · LA MENTALIDAD\\n### *La segunda fundación*\\n\\n> *\\"No importa qué tan buenas sean tus habilidades conversacionales, nunca vas a tener 100% de éxito.\\"*\\n>\\n> Y: *\\"hay gente con mucha personalidad o experiencia que triunfa sin trabajar bien la ley de promedios — pero no puede replicar su éxito, porque depende demasiado de la habilidad.\\"*\\n\\n**La mentalidad no es motivación: es el sistema de control que hace replicable el resultado.**\\n\\n## Ley de Promedios (LDP) `FUENTE`\\n> *\\"Si repites una acción las veces suficientes, aparecerá una proporción.\\"*\\n\\nEs un sistema probado para **encontrar compradores entre los no compradores**.\\n\\n**La analogía de la moneda:** lanzas una vez, 50/50. Lanzas diez veces y raramente sale 5 y 5. Pero mientras más lanzas, más se acerca la muestra a la proporción real. **La ley necesita volumen para manifestarse.**\\n\\n## PPA — lo que afecta tu ley de promedios `FUENTE`\\n**P**itch / Conversación — preciso, conciso, impactante\\n**P**ace / Ritmo — con cuánta gente hablas\\n**A**ttitude / Actitud — consistentemente positiva\\n\\n> **La cadena causal, y por qué la mentalidad no es opcional:**\\n> La ley de promedios necesita volumen. El volumen desgasta la actitud. La actitud degrada el pitch. Y el pitch es la variable de entrada del sistema.\\n>\\n> **Por eso KILT, los 3 tipos de día, controlables y gumball existen: protegen la única variable que el vendedor controla.**\\n\\n## Los 3 Tipos de Día `FUENTE`\\n- **Día A** — las ventas llegan temprano, la actitud es fácil\\n- **Día B** — llegan esporádicamente, no te prueba del todo\\n- **Día C** — todas llegan en las últimas horas. **La verdadera prueba de quién cree en el sistema**\\n\\n*Ejemplo real: 3 ventas de 60 contactos es normal — 5% de éxito. Es normal no tener ningún cliente hasta el final del día y aun así cumplir.*\\n\\n## Teoría del Gumball `FUENTE`\\nTres máquinas, 100 dulces cada una, 97 rojos y 3 verdes. Cada intento cuesta un peso. Tienes 100 pesos y la meta de sacar 3 verdes.\\n\\n**Mantén tu pitch, ritmo y actitud iguales, para que cada \\"no\\" te acerque al \\"sí\\".**\\n\\n> **La dificultad real:** en el campo no puedes ver dónde están los verdes como en la máquina. Tienes que seguir girando a ciegas, sabiendo que tu proporción va a aparecer.\\n\\n## Controlables vs No Controlables `FUENTE`\\n> *\\"Si no podemos controlarlo, no lo pensamos ni lo hablamos. Es una pérdida de tiempo y energía.\\"*\\n\\nLa mayoría pasa el día culpando cosas que no controla. Concentrarse en lo controlable es mucho más productivo: ver más gente, tener mejores conversaciones, cuidar la actitud.\\n\\n## KILT `FUENTE`\\n**K**ill them with kindness — sé amable sin importar la actitud del otro\\n**I**ndifference — algunos comprarán, otros no, ¿y qué?\\n**L**aw of averages — confía en los números\\n**T**reat everyone like your first — nunca sabes cuándo aparece tu cliente\\n\\n**Aplicación:** si dejamos a cada persona mejor de como la encontramos, permanecemos indiferentes al sí o al no, y tratamos a cada quien como el primero, entonces protegemos la actitud.\\n\\n## Los 8 Grandes Hábitos `FUENTE`\\n*\\"Somos lo que hacemos repetidamente; el éxito es un hábito.\\"*\\n\\n1. **Tener gran actitud** — el negocio es 99% actitud y 1% habilidad\\n2. **Ser puntual** — si no llegas temprano, llegas tarde\\n3. **Estar preparado** — fallar en prepararse es prepararse para fallar\\n4. **Esfuerzo del 100%** — recibes lo que pones\\n5. **Maximizar tu territorio** — tu territorio no es el lugar, **son las personas**\\n6. **Proteger tu actitud** — cada \\"no\\" te acerca al \\"sí\\"\\n7. **Conocer tu porqué** — metas de corto, mediano y largo plazo\\n8. **Tomar el control** — de tu día, tu carrera y tu vida\\n\\n## Indicadores / Gauges `FUENTE`\\nMiden con cuánta gente hablas y qué tan lejos llegas en los pasos.\\n\\n**Puertas → Con cuántos hablaste → Presentaciones → Cierres**\\n\\n**Para qué sirven:**\\n1. Identificar dónde **podría** romperse el sistema en tus 6 pasos\\n2. Asegurar que trabajas el sistema\\n3. Marcarte el ritmo\\n\\n> ⚠️ **Los indicadores señalan DÓNDE MIRAR, no qué está mal.**\\n>\\n> Si presentas a muchos y cierras a pocos, el número te dice que algo pasa **entre la presentación y el cierre** — pero la causa puede estar mucho antes. Puede ser que el descubrimiento no encontró el dolor real, que no hubo suficiente CPR y el cliente nunca contestó de verdad, que la presentación se alargó y cayó en KILL, que el impulso se construyó mal, o que efectivamente el cierre es débil.\\n>\\n> **Un número no diagnostica una causa.** Diagnostica una zona.\\n\\n**El diagnóstico real requiere ver la conversación.** Como manager: acompañando al vendedor en campo, o pidiéndole una práctica en Closer sobre el paso donde sospechas.\\n\\n**Números + conversación observada = conclusión.** Cualquiera de los dos solo, es especulación.\\n\\n## Metas — SMART `FUENTE`\\n**S**pecific · **M**easurable · **A**ttainable · **R**ealistic · **T**imed\\n\\nTipos: de **resultado** · de **acción** · corto plazo (<2 meses) · mediano (2 meses–3 años) · largo (3+ años)\\n\\nEscríbelas, hazlas evaluar por alguien, y recompénsate al lograrlas.\\n\\n---","is_active":false,"created_at":"2026-08-31T18:53:25.049459+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"f5ef4d1c-8e75-4072-bbce-038ef965f6ea","version":1,"section_key":"aplicacion","order_index":4,"title":"PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE","body":"# PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE\\n\\n> **El sistema es el esqueleto. Si se entiende, se aplica a cualquier cliente, cualquier industria y cualquier producto.**\\n\\nEsta parte NO es un catálogo de casos. Es la demostración de cómo se deduce la ejecución correcta a partir de los principios — para que cualquier caso que no esté aquí se resuelva igual.\\n\\n## 4.0 El método de adaptación\\n\\nCada paso existe para lograr algo. **Lo que cambia entre clientes no es el objetivo del paso: es lo que hace falta para lograrlo.**\\n\\nEjemplo con la Historia Breve. Su objetivo es liberar el segundo tercio de atención — las dos preguntas que el cliente trae en la cabeza: *quién eres* y *por qué estás aquí*.\\n\\n- Con un desconocido, las dos están abiertas → contestas las dos\\n- Con alguien que te conoce hace años, la primera ya está contestada → **solo queda el porqué de hoy**, y a veces hasta eso es obvio\\n\\n**La conclusión operativa, dicha completa:** con un cliente que ya te conoce, la Historia Breve **NO incluye tu nombre ni el de tu empresa**. Nada de \\"Soy Juan, de [empresa]\\", ni \\"trabajamos con tal marca\\". Él ya lo sabe. Repetírselo le comunica que no lo reconoces o que estás recitando un guion — y en los dos casos daña la relación que llevas años construyendo.\\n\\nLo único que queda es **por qué viniste HOY**, en una o dos frases. Y a veces hasta eso es evidente.\\n\\nEse es el método. Ante cualquier cliente, en cualquier industria:\\n\\n1. ¿Qué **objetivo** tiene este paso?\\n2. ¿Qué de ese objetivo **ya está resuelto** con este cliente?\\n3. ¿Qué **falta** por resolver?\\n4. **Ejecuta solo eso, y escribe solo eso.**\\n\\n> ⚠️ **El paso 4 es donde más se falla.** Deducir correctamente qué falta y aun así escribir la versión completa por costumbre es el error más frecuente al aplicar este método. Si concluiste que algo ya está resuelto, **ese algo no aparece en el texto.** No basta con saberlo: hay que omitirlo.\\n\\n## 4.0b Autoconsumo y distribuidor NO son un tercer eje `CAMPO`\\n\\nHay una confusión fácil de cometer: tratar \\"autoconsumo\\" y \\"distribuidor\\" como si fueran alternativas a \\"nuevo\\" y \\"recurrente\\". No lo son. **Son ejes distintos.**\\n\\n**EJE 1 — ¿Ya te compra?** Nuevo o recurrente. Esto define **la relación**: si te conoces, si hay historial, si hay pedido base.\\n\\n**EJE 2 — ¿Qué hace con el producto?** Revende, consume o distribuye. Esto define **las preguntas**: qué se le pregunta en cada territorio.\\n\\n**Se cruzan.** Un cliente de autoconsumo puede ser nuevo (nunca te ha comprado) o recurrente (lleva años surtiéndose contigo). Y la ejecución cambia según el cruce:\\n\\n| | Nuevo | Recurrente |\\n|---|---|---|\\n| **Revende** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Consume** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Distribuye** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n\\n> **Lo que cambia por el EJE 1** es si te presentas, si hay \\"lo de siempre\\", y si buscas dolor o hueco.\\n>\\n> **Lo que cambia por el EJE 2** es únicamente el vocabulario del descubrimiento: al que revende le preguntas qué maneja y qué le piden; al que consume, qué usa y cada cuánto repone; al que distribuye, sus líneas y a cuántos surte.\\n\\n**Error concreto que esto evita:** escribir la historia breve de un cliente de autoconsumo como si fuera recurrente — *\\"vine a ver cómo les funcionó lo que dejamos la vez pasada\\"* — cuando nunca ha habido una vez pasada. Autoconsumo no dice nada sobre si ya te compra o no.\\n\\n**Y una vez que un cliente de autoconsumo te compra, se vuelve recurrente**: el seguimiento y el crecimiento de esa cuenta funcionan igual que con cualquier otro recurrente. Buscas huecos, cierras el incremento, y no te vuelves a presentar.\\n\\n## 4.1 Lo que sí cambia sustancialmente\\n\\nHay dos diferencias que no son obvias y que sí conviene tener explícitas, porque cambian **qué se busca**, no solo cómo se dice.\\n\\n### Diferencia 1 — Qué buscas en el Descubrimiento\\n\\n**DOLOR** — algo anda mal. Tiene señal verbal: **el \\"aunque\\"**. Se busca con los 3 Territorios y la escalera de capas.\\n\\n**HUECO** — algo que podría comprarte y no te compra. **No tiene señal verbal: se ve, no se oye.**\\n\\n> Un cliente conforme no tiene dolor. **Por eso el vendedor que solo sabe buscar dolor visita durante años sin crecer una cuenta**: busca, no encuentra, y concluye correctamente que no hay nada.\\n\\n**Las tres herramientas del hueco:**\\n\\n**1 · Lee el lugar** — lo que ves te dice qué maneja y de quién. Un producto de otra marca es un espacio ocupado; un estante vacío es una familia que nadie cubre; algo empolvado no es hueco, **es dolor**.\\n\\n**2 · Pregunta por lo que le piden** — *\\"¿le ha tocado que le pidan algo que no maneje?\\"* Demanda que ya existe sin oferta que la cubra.\\n\\n**3 · Ancla en negocios como el suyo** — Efecto Jones aplicado. Solo si es verdad y lo puedes sostener.\\n\\n**Adaptación por canal:** presencial observas; a distancia preguntas por el catálogo. **Adaptación por giro:** si el cliente no revende, \\"lo que ves\\" no es un mostrador — son sus unidades, su patio, su operación.\\n\\n> **La línea que no se cruza:** un hueco tiene que ser real y verificable. **Descubrir un hueco es señalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.**\\n\\n### Diferencia 2 — Qué estás cerrando\\n\\nCon un cliente que ya compra, **el pedido base no está en duda: ya iba a existir.** Lo que se cierra es **lo que se agrega**.\\n\\nReabrir el pedido base al cerrar pone sobre la mesa algo que ya estaba resuelto, e invita al cliente a revisar toda la orden.\\n\\n## 4.1b La observación del recurrente no puede sonar a primera visita `CAMPO`\\n\\nEl SCE y el ice breaker siguen aplicando con un cliente de años. Lo que cambia es **de qué se observa**.\\n\\n**El error:** *\\"¿Siempre está así de lleno o hoy le tocó día pesado?\\"*\\n\\nEsa pregunta la hace alguien que no conoce el lugar. Y este vendedor lleva años pasando cada quincena — **ya sabe si el negocio es movido.** Preguntarlo le comunica al cliente que no lo tiene presente, que es lo contrario de lo que la relación construyó.\\n\\n**Lo correcto: observar lo que CAMBIÓ desde la última visita.**\\n\\n> *\\"Oiga, ¿ya le entró más gente que la vez pasada, verdad?\\"*\\n> *\\"Veo que le movió al acomodo desde que vine.\\"*\\n> *\\"¿Ya se compuso lo del clima o siguen igual de flojas las tardes?\\"*\\n\\nY también funciona lo personal, que con un desconocido no puedes usar:\\n\\n> *\\"¿Cómo salió su muchacho de lo que me contó?\\"*\\n> *\\"¿Le fue bien en el puente?\\"*\\n\\n> **La prueba:** si tu observación de apertura funcionaría igual con un cliente que ves por primera vez, no está aprovechando la relación. **Con un recurrente, la apertura demuestra memoria** — y esa memoria es el activo que llevas años construyendo.\\n\\n⚠️ **Y esto solo funciona si la memoria es real.** Inventar que recuerdas algo que no pasó es peor que no recordar nada. Si no tienes un dato de la visita anterior, observa el momento presente sin fingir historia: *\\"se ve movido hoy\\"* es honesto; *\\"¿siempre está así?\\"* no lo es.\\n\\n## 4.2 Lo que NO cambia nunca\\n\\n- El orden de los 6 pasos\\n- Que el descubrimiento va antes de la presentación\\n- Que el cierre asume en vez de pedir aprobación\\n- Que el precio va en escalera con motivo\\n- Que no hay frases neutras\\n- Toda la Parte 6 (jerarquía de reglas)\\n\\n## 4.3 Presentar un hueco `CAMPO`\\n\\nCuando lo que encontraste es un hueco, no hay nada que resolver: el cliente está conforme. Hay un espacio que ocupar.\\n\\n**La pregunta que define el argumento: ¿qué gana él con que tú se lo surtas?**\\n\\nY la respuesta depende del caso, no de una fórmula. Posibilidades reales:\\n\\n- **Consolidación** — si el cliente trata con muchos proveedores y eso le pesa, reducir el número tiene valor por sí mismo\\n- **Conveniencia** — te ve de todos modos; agregar una familia no le suma trabajo\\n- **Complementariedad** — lo que ofreces se usa junto con lo que ya te compra\\n- **Una condición concreta** — plazo, disponibilidad, presentación, tiempo de entrega\\n\\n> ⚠️ **La consolidación NO es un argumento universal.** Si tu producto es complementario y el cliente ya tiene cinco proveedores, con la familia nueva pasa a tener **seis, no cuatro**. Ahí *\\"menos proveedores que seguir\\"* es falso, y usarlo te desacredita.\\n>\\n> Antes de usarlo, verifica que el cliente **efectivamente vaya a reducir** su número de proveedores.\\n\\n⚠️ **Nunca ataques al proveedor actual.** Criticarlo es criticar la decisión del cliente, y la gente defiende sus decisiones.\\n\\n⚠️ **No afirmes ventajas que no puedes verificar.** *\\"El otro no maneja esta línea\\"*, *\\"nadie tiene nuestro catálogo\\"*, *\\"con nosotros le sale mejor\\"* — si no lo sabes de cierto, no lo digas. Puede ser falso, y en una cuenta de años se descubre siempre. **Habla de lo que TÚ ofreces, con hechos que puedas sostener.**\\n\\n## 4.4 Convicción sin garantía `CAMPO`\\n\\n> **Nunca le pidas que \\"pruebe\\".**\\n>\\n> *\\"Le pongo unas pocas para que lo pruebe\\"* suena humilde y es lo peor que puedes decir: **le pasas el riesgo a él.** La gente no quiere experimentar — está cómoda donde está, y probar algo nuevo es riesgo, incomodidad y la posibilidad de haberse equivocado.\\n\\n**El trabajo del vendedor no es pedir permiso para experimentar. Es hacer que el cliente se sienta seguro.** Dos movimientos:\\n\\n1. **Convicción, sin garantía** — *\\"no le puedo garantizar nada, pero estoy seguro de que le va a servir\\"*\\n   **Funciona precisamente porque reconoce el límite.** Admitir lo que no controlas hace creíble lo que sí afirmas.\\n\\n2. **La razón detrás** — *\\"se lo digo porque en negocios como el suyo es de lo que más sale\\"*\\n   Sin la razón, tu convicción es solo optimismo de vendedor.\\n\\n**Y ahí te callas.**\\n\\n⚠️ **No ofrezcas el plan B.** *\\"Y si no funciona lo ajustamos\\"* parece que baja el riesgo y hace lo contrario: **le mete una duda que no tenía**, y desmiente lo que acabas de afirmar. Si de verdad estás seguro, ¿para qué el paracaídas?\\n\\n*(Si después no funciona, ahí lo ajustas. Eso es Consolidación y se hace cuando pasa — no se anuncia por adelantado.)*\\n\\n## 4.5 El capital del récord `CAMPO`\\n\\n> **La primera vez que recomiendas algo, el cliente compra por la relación. La segunda vez, compra por tu récord.**\\n\\nY eso disciplina: si recomiendas algo que no funciona, **no perdiste una venta — gastaste crédito que te costó años juntar.** Por eso solo se recomienda lo que de verdad sirve a ese perfil, aunque haya cosas con mejor margen.\\n\\n## 4.6 Los dos juegos `CAMPO`\\n\\n**ADQUISICIÓN** — convertir a un desconocido en cliente.\\n**DESARROLLO** — convertir a un cliente en un cliente más grande.\\n\\n> **La asimetría que explica por qué el segundo se descuida:** adquisición da retroalimentación inmediata — vendes o no vendes. Desarrollo no. Puedes visitar cien veces, levantar el mismo pedido, sentir que hiciste bien tu trabajo, y nunca enterarte de lo que dejaste sobre la mesa.\\n>\\n> **El fracaso en desarrollo es invisible.**\\n\\n**El enemigo: la visita que se vuelve trámite.** El vendedor está haciendo adquisición con alguien que ya adquirió — y como no hay nada que adquirir, no hay nada que hacer.\\n\\n> **Al que solo toma pedidos lo reemplaza un formulario.**\\n\\n---","is_active":false,"created_at":"2026-08-31T18:53:25.138466+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"b2d59829-77ba-40d4-9c88-c27b8a69bd3d","version":1,"section_key":"canales","order_index":5,"title":"PARTE 5 · MODIFICADORES DE CANAL","body":"# PARTE 5 · MODIFICADORES DE CANAL\\n\\n| Canal | Qué se conserva | Qué se adapta |\\n|---|---|---|\\n| **Presencial** | Todo | — |\\n| **Teléfono** | Los 6 pasos, KISS, FORMS, las 4 técnicas de overturn, balas, FUJIES verbales, CWA, triple desglose, y el **entusiasmo del tono** | Contacto visual → pausas y ritmo. Todo lo físico se pierde |\\n| **WhatsApp / mensaje** | La estructura completa, balas, triple desglose, ataque preventivo | Mensajes cortos, uno por idea. Señales de compra → velocidad de respuesta, emojis, preguntas de precio. El cierre debe contestarse con una palabra |\\n| **Correo** | Estructura, KISS, balas, triple desglose | Todo lo interactivo se vuelve secuencia |\\n\\n> **El principio de adaptación: entender qué HACE cada técnica permite encontrar su equivalente en cualquier medio.**\\n>\\n> El miedo a la pérdida no es *\\"quitar el producto de la mano\\"* — es **crear la sensación de que algo se va**. Eso existe en los cuatro canales.\\n\\n---","is_active":false,"created_at":"2026-08-31T18:53:25.227194+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"43106094-6ab6-4a8c-8e33-873b6edf28e9","version":1,"section_key":"jerarquia","order_index":6,"title":"PARTE 6 · JERARQUÍA DE REGLAS","body":"# PARTE 6 · JERARQUÍA DE REGLAS\\n\\nCuando dos principios chocan, gana el de mayor jerarquía.\\n\\n## NIVEL 1 — Inviolables (ética y verdad)\\nNunca se rompen, en ningún contexto, por ninguna razón.\\n\\n1. **Impulso falso está prohibido.** Urgencia inventada, escasez que no existe, prueba social fabricada. *(Práctico, no solo moral: un impulso falso se derrumba cuando el cliente lo descubre, y se lleva la venta, la relación y tu reputación en la zona.)*\\n2. **No garantizar lo que no controlas.** Convicción sí; garantía no.\\n3. **No fabricar un hueco ni un dolor.** Descubrir es señalar lo que existe.\\n4. **No atacar al competidor ni al proveedor actual.**\\n5. **No afirmar ventajas que no puedes verificar.** *\\"Nadie más tiene esto\\"*, *\\"el otro no lo maneja\\"*, *\\"con nosotros sale mejor\\"* — si no lo sabes de cierto, no lo dices. Habla de lo que TÚ ofreces.\\n6. **Nunca discutir con un cliente.**\\n\\n## NIVEL 2 — Estructurales\\nSe rompen solo si el Nivel 1 lo exige.\\n\\n7. **El orden de los 6 pasos.** No se salta ninguno.\\n8. **Primero el examen, luego la receta.** No presentar sin diagnosticar.\\n9. **El cierre asume, no pide aprobación.** Toda pregunta que permita aprobar o posponer entrega el control.\\n10. **El precio va en escalera con motivo en cada escalón.** Nunca un solo número.\\n11. **No hay frases neutras.** Si algo resta valor y nadie lo preguntó, se omite.\\n12. **Señal de compra = detente y cierra.**\\n13. **Se sale de la línea, pero siempre se regresa.**\\n14. **Nunca pidas opinión ni aprobación sobre el precio.** Ni el tuyo ni el de la competencia. Preguntar *\\"¿cómo ve los precios?\\"* le pide al cliente que construya una posición contra ti antes de que exista valor, cede tu autoridad sobre el precio, y renuncia a tu ventaja — porque tú conoces el mercado y él muchas veces no. En el territorio PRECIO se investigan **hechos** (a cómo compra, qué plazo tiene, cada cuánto le suben), nunca opiniones.\\n\\n## NIVEL 3 — Contextuales\\nDependen del tipo de cliente, canal o situación. **Se deducen del método de la Parte 4.0, no se memorizan.**\\n\\n14. Qué parte de la Historia Breve hace falta — depende de qué ya sabe el cliente\\n15. Buscar dolor o buscar hueco — depende de si el cliente está conforme\\n16. Qué argumento usar al presentar un hueco — depende de qué gana él en ESE caso\\n17. Cerrar la venta o cerrar el incremento — depende de si hay un pedido base\\n18. SEE físico — solo presencial\\n\\n## NIVEL 4 — Estilo\\nAjustables al lenguaje del vendedor, la zona y la empresa.\\n\\nTono, vocabulario, longitud de frases, formalidad. **El manager conoce el lenguaje de su gente mejor que Closer.**\\n\\n---","is_active":false,"created_at":"2026-08-31T18:53:25.315451+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"6f586393-325b-4c99-81d2-79444ceaa3a0","version":1,"section_key":"razonamiento","order_index":7,"title":"PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO","body":"# PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO\\n\\n## Ante un caso no cubierto\\n1. Identifica **qué paso** de la línea es\\n2. Pregunta **qué objetivo tiene ese paso**\\n3. Pregunta **qué de ese objetivo ya está resuelto** con este cliente, y qué falta\\n4. Verifica contra la **jerarquía**: ¿viola algo de Nivel 1 o 2?\\n5. Si sigue sin resolverse, **di que no lo sabes.** No inventes doctrina.\\n\\n## Ejemplos de deducción\\n\\n**Caso:** un vendedor pregunta si puede decir *\\"¿le late?\\"* al cerrar.\\n**Razonamiento:** es una pregunta que permite aprobar o posponer → viola la regla 9 (Nivel 2) → **no**. La alternativa es una pregunta donde ambas opciones sirvan.\\n\\n**Caso:** un manager quiere que el pitch mencione que un producto no trae promoción este mes.\\n**Razonamiento:** no hay frases neutras (1.3); esto baja el valor percibido; nadie lo preguntó → **se omite**. Regla 11, Nivel 2.\\n\\n**Caso:** un vendedor pregunta cómo abrir con un cliente que le compra desde hace cinco años.\\n**Razonamiento:** aplica el método 4.0. Objetivo de la Historia Breve = contestar *quién eres* y *por qué estás aquí*. Lo primero ya está resuelto → **solo queda el porqué de hoy**, y a veces hasta eso es evidente. No hace falta una regla especial: sale del objetivo del paso.\\n\\n**Caso:** vender un servicio de software por videollamada a una empresa que nunca lo ha usado.\\n**Razonamiento:** el sistema aplica igual. Cliente nuevo → doctrina de adquisición. Canal remoto → SEE físico no aplica, pero el entusiasmo del tono sí. \\"Lee el lugar\\" no existe, así que se pregunta. Los 3 Territorios se traducen: producto = qué usan hoy, servicio = cómo los atiende su proveedor, precio = qué pagan. **Nada del esqueleto cambia.**\\n\\n**Caso:** un vendedor dice que el cliente no le reconoce ningún problema, pero él ve claro que sí lo tiene.\\n**Razonamiento:** aplica 1.5. La confirmación explícita no es requisito. Si hay evidencia real — algo que dijo, algo que vio, algo propio de su giro — **avanza presentando la situación resuelta**, no el problema reconocido. Insistir en que lo admita lo pone a la defensiva y apaga lo emocional, que es donde está la venta. **El límite:** si el cliente ya negó explícitamente ese problema, insistir es fabricar, y eso es Nivel 1.\\n\\n**Caso:** un vendedor lleva tres días sin cerrar y está desanimado.\\n**Razonamiento:** esto es Parte 3, no Parte 2. Aplica Ley de Promedios, los 3 Tipos de Día (día C), gumball, y controlables vs no controlables. **No es un problema de técnica: es de protección de la actitud, que es la variable de entrada del sistema.**\\n\\n**Caso:** un manager ve que su vendedor presenta mucho y cierra poco, y quiere saber qué corregir.\\n**Razonamiento:** el indicador señala una zona, no una causa. Puede ser el cierre, pero también un descubrimiento que no encontró el dolor real, CPR insuficiente, o una presentación que se alargó y cayó en KILL. **Números + conversación observada.** Pídele una práctica o acompáñalo en campo antes de concluir.\\n\\n## Sobre la incertidumbre\\nEste documento tiene procedencia marcada por una razón: **lo que está como `CAMPO` no se puede verificar contra la fuente.** Si un caso depende de doctrina `CAMPO` y hay duda, la autoridad es Emilio, no la inferencia.\\n\\n**Nunca completes un hueco de doctrina inventando.** Di qué falta y pídelo.\\n\\n**Y nunca inventes un hecho comercial** — una ventaja, una comparación con la competencia, un dato de mercado. Eso no es doctrina: es información de la empresa, y si no está en su contexto, se pide.","is_active":false,"created_at":"2026-08-31T18:53:25.404147+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"a058c808-0c59-41dd-9085-aaf782b4e0f9","version":2,"section_key":"fundamento","order_index":1,"title":"PARTE 1 · EL FUNDAMENTO","body":"# EL CEREBRO DE CLOSER\\n## Doctrina canónica del sistema de venta\\n\\n*Versión 1.0 · Fuente única de verdad*\\n\\n---\\n\\n## CÓMO USAR ESTE DOCUMENTO\\n\\nEsto no es un manual ni un resumen. Es el entendimiento del sistema, escrito para que se pueda **razonar** con él.\\n\\nCada técnica se presenta con tres cosas: **qué es**, **por qué funciona** (el mecanismo humano detrás) y **qué la rompe**. El porqué importa más que el qué, porque de él se deducen los casos que ninguna lista cubre.\\n\\nEjemplo de la diferencia: una lista diría *\\"no digas «¿cómo lo ves?»\\"*. Este documento dice *\\"toda pregunta que permita aprobar o posponer le entrega el control al cliente\\"* — de donde se deduce que *\\"¿le late?\\"*, *\\"¿qué opina?\\"* y *\\"¿le parece?\\"* también están mal, aunque nadie los haya escrito nunca.\\n\\n**Regla de razonamiento:** ante un caso que este documento no cubre explícitamente, no inventes. Busca el principio que aplica y dedúcelo. Si dos principios chocan, gana el de mayor jerarquía (ver Parte 6).\\n\\n### Etiquetas\\n\\n**PROCEDENCIA** — `FUENTE` (sistema original Credico/Cydcor) · `CAMPO` (evolución de Emilio Fanjul) · `CLOSER` (andamiaje pedagógico)\\n\\n**CANAL** — `PRESENCIAL` (requiere cuerpo o presencia) · `UNIVERSAL` (funciona en persona, teléfono, mensaje o correo)\\n\\n---\\n\\n---\\n\\n# PARTE 1 · EL FUNDAMENTO\\n\\n## 1.1 El problema que resuelve todo el sistema `FUENTE`\\n\\nCuando abres una conversación con un desconocido, **su atención está dividida en tres**:\\n\\n- **Un tercio** sigue en lo que estaba haciendo\\n- **Un tercio** está resolviendo preguntas básicas: quién eres, qué quieres, por qué me hablas\\n- **Solo un tercio** está disponible para ti\\n\\n> **De aquí sale la razón de ser de los 6 pasos:** si vas directo a presentar, le estás hablando a un tercio de una persona. Cada paso previo existe para recuperar una porción de esa atención.\\n\\nLa Introducción libera el primer tercio (deja de pensar en lo que hacía). La Historia Breve libera el segundo (ya sabe quién eres y a qué vienes). Solo entonces tienes casi toda su atención — y solo entonces vale la pena presentar.\\n\\n**Esto explica por qué saltarse pasos no acelera nada: presentarle a alguien distraído es desperdiciar tu mejor material.**\\n\\n## 1.2 La Línea Recta `CAMPO` `UNIVERSAL`\\n\\nUna venta avanza en línea recta, de izquierda a derecha, a través de los 6 pasos.\\n\\n**Nada te regresa. Lo que ya recorriste, quedó.** Lo único que puede pasar es que algo te **saque de la línea y te pause**.\\n\\nLa imagen: vas dibujando la línea hacia la derecha y de pronto llega una objeción. Ahí dejas de avanzar y la línea sube — saliste. Pero no retrocede. Está en ti resolver y volver al punto donde ibas.\\n\\n| Elemento | Relación con la línea |\\n|---|---|\\n| Los 6 pasos | La línea misma |\\n| CPR / FORMS | Salida **deliberada** — sales tú, y regresas |\\n| Bloqueos → AIR, Ataque Preventivo | Salida **impuesta** al inicio |\\n| Objeciones → RRR, FFF | Salida **impuesta** después de entender |\\n| Close With Action | Lo que te devuelve y te mueve al siguiente tramo |\\n| Los 3 No seguidos | La señal de que ya no hay línea que recorrer |\\n\\n**Diagnóstico que le da al vendedor:** cuando una visita sale mal, la pregunta no es *\\"¿qué técnica olvidé?\\"* sino **\\"¿dónde salí de la línea y por qué no regresé?\\"**\\n\\n## 1.3 El principio de la balanza `FUENTE` `UNIVERSAL`\\n\\nNadie compra por precio. Compra cuando el **valor percibido** pesa más que el **costo percibido**. Cuanto mayor la brecha, mayor el impulso.\\n\\nY el costo no es solo dinero: es tiempo, riesgo de cambiar, esfuerzo, y la posibilidad de haberse equivocado.\\n\\n> **La regla que convierte esto en herramienta:** con cada frase, cada gesto y cada silencio estás haciendo una de cuatro cosas — subiendo el valor, bajándolo, subiendo el costo, o bajándolo.\\n>\\n> **No hay frases neutras.**\\n\\nDe aquí se deducen cosas que ninguna lista de reglas contiene:\\n- Titubear al dar un precio sube el costo percibido\\n- Disculparte baja tu valor\\n- Mencionar algo que **no** tienes, no aplica o no está disponible **baja el valor sin que nadie te lo pidiera** — y por eso se omite\\n- Contar un caso real de otro cliente sube el valor\\n\\n**Cost vs Value no es tanto una habilidad como una herramienta de evaluación:** revisa cada parte de tu conversación y pregúntate qué plato movió.\\n\\n## 1.4 La gente compra, pero no quiere que le vendan `FUENTE`\\n\\nEste es el principio psicológico que atraviesa todo el sistema.\\n\\nA las personas les gusta comprar. Lo que les desagrada es **sentir que les están vendiendo**. Tienen una alarma calibrada para detectar al vendedor, y en cuanto se activa, todo lo que digas después se procesa con desconfianza.\\n\\n> **Casi todas las técnicas de este sistema son formas de obtener un resultado de venta sin activar esa alarma.**\\n\\n- **Gasman** — pedir permiso te delata como forastero; asumir que perteneces no dispara nada\\n- **CPR** — ser persona antes que vendedor\\n- **Descubrimiento** — el vendedor promedio habla; el que pregunta rompe el patrón que la alarma busca\\n- **Close With Action** — nunca pides el sí, porque pedirlo enciende la alarma\\n- **Indiferencia** — la presión genera resistencia; quitarla la disuelve\\n- **FFF** — estar de acuerdo primero te vuelve distinto del vendedor promedio, *y por eso te escuchan*\\n\\n## 1.5 La decisión es emocional antes que racional `CAMPO`\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente siente algo primero, y después construye la razón que lo justifica.\\n\\nEsto no contradice el diagnóstico ni la construcción de valor: los explica. La doctrina fuente lo dice sin rodeos — **\\"el impulso es otra palabra para la emoción\\"**.\\n\\n**Lo que se deduce de aquí, y que corrige el error de modelar la venta como un proceso lógico:**\\n\\n- **El cliente no necesita reconocer un problema para sentir el alivio de resolverlo.** Por eso \\"pintar imágenes\\" funciona: no argumenta, hace sentir.\\n- **Pelear por el reconocimiento explícito mata la venta.** Insistir en que admita algo lo pone a la defensiva, y la defensiva apaga lo emocional — que era donde estaba la venta.\\n- **El 80% indiferente no tiene un problema urgente**, y aun así compra. Se mueve por los factores de impulso, no por el diagnóstico.\\n- **Un argumento perfecto dicho por alguien en quien no confía, no pesa.** Y uno mediocre dicho por alguien cercano, sí. De ahí la importancia real del CPR.\\n\\n> **La regla operativa:** el sistema construye una situación deseable, no un caso lógico. La razón sirve para que el cliente pueda **justificar** la decisión — no para que la tome.\\n\\n⚠️ **Y esto no autoriza a manipular.** El Nivel 1 sigue intacto: el impulso se construye con verdad. La diferencia es que construir una imagen real y deseable es legítimo; fabricar urgencia, escasez o problemas no lo es.\\n\\n---","is_active":false,"created_at":"2026-09-25T20:26:45.879837+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"546b2bc3-ec0b-4a6c-8e90-99f3ab3a1aed","version":2,"section_key":"pasos","order_index":2,"title":"PARTE 2 · LOS 6 PASOS","body":"# PARTE 2 · LOS 6 PASOS\\n\\nEl sistema original tiene **5 pasos** `FUENTE`: Introducción, Historia Breve, Presentación, Cierre, Consolidación.\\n\\nCloser enseña **6** `CAMPO`: se separa **Descubrimiento** como paso propio. En la fuente las preguntas de calificación viven dentro del flujo; separarlas reconoce que diagnosticar y presentar son habilidades distintas que fallan por razones distintas.\\n\\n---\\n\\n## PASO 1 · INTRODUCCIÓN\\n### *Una sola oportunidad para una primera impresión*\\n\\n**Qué logra:** liberar el primer tercio de atención y ganarte el derecho a seguir hablando.\\n\\n**Qué NO es:** aquí no dices quién eres ni a qué vienes. Eso es el Paso 2. Confundirlos es el error doctrinal más común.\\n\\n### SEE / SCE `FUENTE` `PRESENCIAL`\\n**S**mile · **E**ye contact · **E**nthusiasm — Sonrisa, Contacto visual, Entusiasmo\\n\\n- **Sonrisa** — signo internacional de amistad. Elimina el miedo y crea confianza.\\n- **Contacto visual** — genera confianza, mantiene el control de la conversación, **y es una señal de compra fuerte cuando el cliente lo hace**.\\n- **Entusiasmo** — crea impulso y curiosidad. Si estás emocionado, asumen que hablas de algo emocionante. **Y al revés también funciona:** si suenas aburrido de tu producto, nadie va a estar más emocionado que tú.\\n\\nSe combinan con **lenguaje corporal abierto** y **tono de voz fuerte**.\\n\\n> ⚠️ **Límite de canal:** SEE es físico. En texto o voz no se puede evaluar. Se enseña, se pide, y se marca como *\\"esto se practica en persona\\"*. Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**.\\n\\n### Regla del 10% `FUENTE` `PRESENCIAL`\\nLee el nivel de emoción del cliente y ponte **10% por encima** de él. No al doble: 10%.\\n\\n**Por qué:** llegar gritando con alguien tranquilo lo aleja tanto como llegar apagado con alguien entusiasmado. El 10% jala sin romper.\\n\\n### Ice Breaker `FUENTE` `UNIVERSAL`\\nCumplido genuino, chiste sencillo o comentario ligero.\\n\\nPuede ser sobre **la persona**, **el lugar**, o **algo en común**. No está atado a ningún tipo de negocio.\\n\\n**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee al instante y se cierra **más** que antes — porque ahora sabe que le están aplicando una técnica.\\n\\n### La escalera de la especificidad `CAMPO` `UNIVERSAL`\\n\\nLa observación y la pregunta de la apertura se miden igual: **¿se la harías a cualquiera?** Entre más específica para ESE cliente en ESE momento, más vale.\\n\\n- **Escalón 1 — de cortesía.** Se la harías a cualquiera: *\\"¿cómo está?\\"*, *\\"qué gusto saludarlo\\"*. Cumple lo mínimo porque le devuelve la palabra, pero no construye nada.\\n- **Escalón 2 — del entorno.** Sale de lo que ves ahí, en ese momento: *\\"veo que no paran, ¿siempre está así de movido?\\"*. Solo tiene sentido en ese lugar.\\n- **Escalón 3 — de él.** Solo se la harías a él, porque sabes algo de antes: *\\"¿cómo sigue? ¿va mejorando?\\"*.\\n\\n> **Las mismas palabras pueden estar en escalones distintos.** *\\"¿Cómo está?\\"* a secas es escalón 1; *\\"¿cómo está? ¿va mejorando?\\"* a alguien que estuvo enfermo es escalón 3. Lo que sube el escalón no son las palabras: es qué tanto sabe la pregunta de él.\\n\\n**La relación cambia la escalera.** Con un cliente nuevo no existe el escalón 3 —no hay historia con él—, así que el escalón 2 es la excelencia. Con un recurrente la meta es el escalón 3, y el 2 puede ser un error: preguntarle si siempre está así de movido a alguien que visitas desde hace años le dice que no lo tienes presente (ver 4.1b).\\n\\n**Una pregunta de cortesía no es una falla: es el primer escalón.** La falla es no preguntar nada: sin ninguna pregunta, el cliente no tiene qué contestar y la conversación se muere ahí.\\n\\n**Y la pregunta que mejor devuelve la palabra es la que sale de la observación y cierra la apertura:** *\\"veo que no paran, ¿siempre está así de movido?\\"*. Un *\\"¿cómo está?\\"* dentro del saludo cumple, pero si después sigues hablando, el cliente espera a que termines en vez de contestar. Convertir la observación en la pregunta final es como se sube de escalón.\\n\\n### Teoría del Gasman `FUENTE` `UNIVERSAL`\\nSer asumido y confiado, con alta indiferencia.\\n\\nEl gasista que viene a leer tu medidor entra con una autoridad que nace de sentir que **debe estar ahí** — no es una intrusión. Nadie lo detiene, y no es por su permiso: es por su postura.\\n\\n> **El mecanismo:** cuando preguntas *\\"¿tiene un minutito?\\"* haces dos cosas a la vez — le entregas el control, y le ofreces una salida que no le cuesta nada tomar. El cliente que dice \\"ahorita no\\" no está siendo grosero: tomó la puerta que le abriste.\\n>\\n> **La autoridad no se pide. Se asume.**\\n\\n### Regla doctrinal del paso `CAMPO`\\n**La identificación (nombre y empresa) es permitida pero nunca requerida aquí.** Su ausencia jamás se penaliza.\\n\\nSi el cliente pregunta *\\"¿y usted quién es?\\"*, **ganaste la introducción** — esa pregunta es la puerta natural al Paso 2, no una falla.\\n\\n---\\n\\n## PASO 2 · HISTORIA BREVE\\n### *Explica tu propósito de manera concisa*\\n\\n**Qué logra:** liberar el segundo tercio de atención. El cliente deja de preguntarse quién eres y qué quieres.\\n\\n### KISS vs KILL `FUENTE` `UNIVERSAL`\\n**K**eep **I**t **S**hort and **S**imple — contra **K**eep **I**t **L**ong and **L**engthy.\\n\\nQuién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible.\\n\\n> **El mecanismo:** cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él — y de los discursos uno se defiende.\\n\\n**Y después de la historia, preguntas.** La fuente es explícita: *\\"en la mayoría de los casos es más efectivo pasar directamente a las preguntas de calificación que dar una larga explicación.\\"*\\n\\nTu historia breve no existe para que te entiendan a ti. **Existe para ganarte el derecho de preguntarle a él.**\\n\\n### CPR — Create Personal Relations `FUENTE` `UNIVERSAL`\\n> *\\"Eres tanto, si no más, el producto que los productos que representas.\\"*\\n\\n**Se aplica durante TODA la conversación**, no en un paso.\\n\\n**El mecanismo:** el cliente no puede evaluar tu producto todavía — no lo ha probado, no conoce tu empresa, no sabe si le van a cumplir. Lo único que sí puede evaluar desde el primer segundo **eres tú**. Y esa evaluación la hace mucho antes que la otra.\\n\\n**Y hace dos trabajos distintos, ambos indispensables:**\\n\\n**1 · Que te contesten de verdad.** Sin relación, las preguntas del Paso 3 reciben respuestas de cortesía. A un desconocido nadie le cuenta lo que le está fallando.\\n\\n**2 · Que te crean.** Este es el más importante y el que casi nadie ve.\\n\\n> Si un amigo te dice que un producto es bueno, le crees. Si te lo dice alguien que gana comisión por vendértelo, lo descuentas automáticamente — no porque lo creas mentiroso, sino porque sabes que tiene interés.\\n>\\n> **Es la misma frase, dicha por dos personas, y produce dos efectos opuestos.**\\n\\nLo que decide cuál de los dos efectos produces **no es tu argumento: es qué tan cerca estás de ser alguien en quien confía.** Por eso el CPR no es cortesía ni relleno — **es lo que determina si tus argumentos pesan o se descuentan.**\\n\\nY conecta directo con el Efecto Jones: la gente no confía en un desconocido incentivado a vender, pero sí deja que gente cercana valide un producto. **El CPR te acerca a ese lado de la línea.**\\n\\n### FORMS `FUENTE` `UNIVERSAL`\\n**F**amily · **O**ccupation · **R**ecreation · **M**otivation · **S**ports\\n\\nLos cinco caminos a la persona. Más cumplidos genuinos y chistes sencillos.\\n\\n> **La palabra que lo decide todo es *genuinos*.** Un interés fingido se nota, y cuesta más que no haber preguntado — porque ahora el cliente sabe que le aplicaste una técnica. Si un tema no te interesa de verdad, busca otro de los cinco.\\n\\n**No requiere cierta personalidad ni ser naturalmente extrovertido: se aprende.**\\n\\n### El desvío con regreso `CAMPO` `UNIVERSAL`\\nLa mecánica que hace que el CPR no mate la venta.\\n\\nSales de la línea a propósito, das **uno o dos intercambios personales**, y **regresas**. Puedes volver a salir más adelante, pero siempre avanzando.\\n\\n**Dos errores, ambos caros:**\\n- **Nunca salir** → no hay relación, y no te van a contestar nada en el Paso 3\\n- **Salir y no regresar** → el cliente se acomoda a platicar y la venta se estanca\\n\\n> **El cliente NUNCA te va a regresar a la línea.** Cuando la plática se pone agradable, él está cómodo — nadie interrumpe una conversación agradable para hablar de negocios. El único que puede regresar eres tú.\\n\\n### Bloqueo vs Objeción `FUENTE` — *la distinción que organiza todo el manejo de resistencia*\\n\\n**BLOQUEO** — un reflejo. Llega **ANTES** de entender.\\n*\\"No tengo tiempo\\" · \\"No me interesa\\" · \\"No estoy comprando nada\\" · \\"Ya tengo con quién\\"*\\nNo hubo procesamiento. Es la puerta cerrándose sola.\\n\\n**OBJECIÓN** — una preocupación razonada. Llega **DESPUÉS** de entender.\\n*\\"Está caro\\" · \\"Ya tengo proveedor y me cumple\\" · \\"Lo tengo que consultar\\"*\\nAquí sí hubo pensamiento.\\n\\n> **Por qué importa la diferencia:** discutir con un reflejo lo convierte en una posición. El cliente dijo \\"no me interesa\\" sin pensarlo; si lo peleas, tiene que defenderlo — y al defenderlo se lo cree. **Le acabas de crear un \\"no\\" real que no tenía.**\\n>\\n> E ignorar una objeción real ofende a alguien que sí te escuchó y sí pensó.\\n>\\n> **La misma frase se maneja de dos maneras opuestas según cuándo llegó.**\\n\\n### AIR `FUENTE` `UNIVERSAL`\\n**A**gree · **I**gnore · **R**esume — Acepta, Ignora, Resume\\n**Cuándo:** bloqueos al inicio.\\n**Cómo:** reconoce con *\\"entiendo\\"* o *\\"por supuesto\\"*, no lo discutas, y continúa.\\n\\n> **El tercer movimiento es el que falla.** Casi todos aceptan bien y casi todos logran no discutir — y después se quedan parados esperando, o peor, vuelven a pedir permiso. Ahí se pierde todo lo ganado.\\n\\n### Ataque Preventivo `FUENTE` `UNIVERSAL`\\n**Cuándo:** intro o historia breve, si hay negativos comunes del territorio.\\n**Cómo:** *\\"si das la negativa antes de que el cliente lo haga, ya no es una negativa.\\"*\\n\\n**El mecanismo:** le quitas el argumento de las manos, y además te vuelves creíble — **quien reconoce lo malo se gana el derecho a que le crean lo bueno.**\\n\\n**Dos formas de arruinarlo:**\\n- **En tono de disculpa** → deja de ser adelantarse y se vuelve defenderse de algo que nadie reclamó\\n- **Con un negativo inventado** → no desactivas nada, plantas una preocupación nueva\\n\\n### Close With Action `FUENTE (dentro de FFF) + CAMPO (generalizado)` `UNIVERSAL`\\n**Es el Poder de Sugestión en ejecución.**\\n\\nUna pregunta o acción cuya respuesta **solo tiene sentido si el cliente está avanzando**. Su respuesta *es* el sí. Nunca lo pides explícito.\\n\\n- *\\"¿Cómo se escribe su apellido?\\"* → al contestar, aceptó tu respuesta y sigue en el alta\\n- *\\"¿Prefiere el jueves o el viernes?\\"* → *\\"el viernes\\"* significa que lo quiere **y** cuándo\\n\\n**Se ejecuta en cada tramo de la línea:** en descubrimiento es la siguiente pregunta; en presentación es continuar donde ibas; en cierre es la alternativa de sí/sí.\\n\\n> **El momento crítico:** justo después de resolver algo. El vendedor promedio se queda callado esperando permiso para seguir. En ese silencio el cliente retoma el control y cierra la conversación con amabilidad. **No te está rechazando: le devolviste el volante.**\\n\\n---\\n\\n## PASO 3 · DESCUBRIMIENTO `CAMPO`\\n### *Encontrar el dolor real*\\n\\n*No existe como paso en la fuente. Toda esta sección es construcción de Closer sobre el principio de \\"preguntas de calificación\\".*\\n\\n### El principio rector\\n**Primero el examen, luego la receta.** El vendedor promedio llega a recetar: trae su producto favorito buscando dónde encajarlo. El Closer llega a diagnosticar.\\n\\n**La ironía:** el que pregunta vende más que el que habla.\\n\\n### RRR — Read, Relate, Relax `FUENTE` `UNIVERSAL`\\nLee · Conecta · Relaja.\\n\\nTres cosas que leer: **el ambiente, la demografía de la persona, y su estado de ánimo.**\\n\\n**El mecanismo:** no quieres forzar a nadie a subir a tu nivel de emoción ni a adaptarse a ti. **Tú te adaptas primero.**\\n\\n> ⚠️ **Colisión de acrónimos:** existe un segundo RRR en la doctrina (Repeat, Reassure, Resume) para objeciones. Ambos se conservan con su nombre original. Al enseñar el segundo hay que advertirlo explícitamente.\\n\\n### Los 3 Territorios del Dolor `CLOSER` `UNIVERSAL`\\nTodo dolor comercial vive en uno de tres territorios:\\n\\n- **PRODUCTO** — lo que vende o usa\\n- **SERVICIO** — cómo lo trata su proveedor actual\\n- **PRECIO** — lo que paga y lo que gana\\n\\n> **El mismo territorio se pregunta distinto según el tipo de cliente.** Ver Parte 4.\\n\\n#### Cómo se investiga el territorio PRECIO `CAMPO`\\n\\nEl territorio PRECIO es el más fácil de arruinar, porque la pregunta natural es la incorrecta.\\n\\n⚠️ **NUNCA le pidas al cliente su opinión ni su aprobación sobre precios.** Prohibido: *\\"¿cómo ve los precios?\\"*, *\\"¿hay algo que sienta muy arriba?\\"*, *\\"¿le parece competitivo?\\"*, *\\"¿estoy bien de precio?\\"*\\n\\n**Tres razones, y cada una basta:**\\n\\n**1. Le pides que construya una posición sobre tu precio antes de que exista valor.** Si contesta *\\"están caros\\"*, ya no es una impresión: es algo que declaró en voz alta y ahora tiene que defender. **Te creaste una objeción de precio que no existía.**\\n\\n**2. Cedes la autoridad sobre el precio.** El precio no lo determina la percepción del cliente: lo determina lo que ofreces. Preguntarle su opinión comunica que estás dispuesto a moverlo según lo que conteste, y te vuelve regateable antes de haber presentado nada.\\n\\n**3. Renuncias a tu ventaja.** Tú conoces el mercado: ya sabes qué está caro y qué está barato. **Muchas veces el cliente no sabe que está pagando de más, y tú sí.** Preguntarle su opinión te iguala a alguien que no sabe, cuando saber es exactamente lo que te hace valioso.\\n\\n**Lo que sí se investiga en este territorio son HECHOS, no opiniones:**\\n\\n- ¿A cómo compra hoy? (dato)\\n- ¿Cada cuánto le suben? ¿Le avisan antes? (dato)\\n- ¿Le manejan crédito o de contado? ¿Qué plazo? (dato)\\n- ¿Cuánto le queda de margen en esa línea? (dato)\\n- ¿Le ha tocado que un cliente se le vaya por precio? (experiencia, no opinión)\\n\\n**La diferencia:** un hecho te da información que puedes usar. Una opinión sobre tu precio te da una objeción que tendrás que atravesar.\\n\\n> **Y si el cliente dice que tu precio está mal, el diagnóstico correcto no es bajarlo.** Es que no encontraste su dolor, o no construiste suficiente valor. **El problema nunca está en el número: está en la balanza.**\\n\\n### La Escalera de Capas `CLOSER` `UNIVERSAL`\\n**CAPA 1 — Hechos.** Fáciles, cero riesgo. Abren la plática y te dan el mapa.\\n**CAPA 2 — La puerta.** Aquí el cliente suelta una pista... o cierra con un \\"bien\\". Depende de cómo preguntes.\\n**CAPA 3 — El dolor.** Solo se abre si recoges la pista y profundizas con preguntas abiertas.\\n\\n### La Pregunta Específica `CAMPO` `UNIVERSAL`\\n> **El \\"bien\\" no es información: es un reflejo social.**\\n\\nCuando preguntas *\\"¿qué tal le va?\\"*, el cliente no consulta su experiencia — dispara la respuesta cortés que trae cargada. Y admitir un problema ante un desconocido tiene costo social: parece queja, o parece que eligió mal.\\n\\n**La solución tiene dos formas:**\\n- **ESPECÍFICA** — nombra un dato o situación concreta que tenga que ir a buscar. *\\"¿Le ha tocado quedarse sin su producto estrella?\\"*\\n- **NORMALIZADA** — da permiso citando a otros. *\\"Varios clientes me comentan que batallan con faltantes, ¿a usted le pasa?\\"* (Es el Efecto Jones aplicado a descubrimiento.)\\n\\n**Y el orden importa:** concreta para **abrir** (capa 2), abierta para **excavar** (capa 3).\\n\\n#### Suggestive Language — dale de dónde agarrarse `FUENTE` `UNIVERSAL`\\n\\nEs la S de FUJIES aplicada al descubrimiento, y es lo que convierte una pregunta que se muere en una que da información.\\n\\n**El problema de la pregunta abierta sola:** obliga al cliente a construir la respuesta desde cero. Eso cuesta esfuerzo, y como no le urge ayudarte, contesta lo más corto que puede — o de plano *\\"pues no sé\\"*.\\n\\n**La solución: después de preguntar, sugiere opciones.**\\n\\n> *\\"¿Qué familias son las que más se te mueven? ¿Anticongelantes? ¿Aceite de motor? ¿Diésel? ¿Moto?\\"*\\n>\\n> *\\"¿A cómo compras el líquido de frenos? ¿70? ¿80? ¿90?\\"*\\n\\n**Por qué funciona, y son tres cosas a la vez:**\\n\\n1. **Le das de dónde agarrarse.** O elige una de tus opciones, o te corrige con el dato real — *\\"no, más bien 95\\"*. **Y esa corrección es información que la pregunta abierta nunca habría sacado.**\\n\\n2. **Le demuestras que conoces su negocio.** Nombrar las familias correctas o el rango de precio correcto te posiciona como alguien que sabe, no como alguien que está averiguando.\\n\\n3. **Crea un poco de urgencia.** Una pregunta con opciones se contesta rápido; una abierta se puede posponer con un *\\"déjame ver\\"*.\\n\\n**Cómo se usa bien:**\\n- Las opciones tienen que ser **reales y del giro del cliente**. Si sugieres familias que él no maneja, demuestras lo contrario de lo que buscabas.\\n- **Tres o cuatro, no una lista.** Es para ayudarlo a contestar, no para que elija de un catálogo.\\n- El rango de precio **tiene que ser creíble.** Sugerir cifras muy lejanas de la realidad te desacredita.\\n- Y **no lo uses para plantar una respuesta.** Si el cliente te corrige, esa es la respuesta buena — no insistas en la tuya.\\n\\n> **Es la misma lógica del cierre de alternativa, aplicada al descubrimiento:** no preguntas al aire, das opciones donde cualquier respuesta te sirve.\\n\\n### El Barrido `CLOSER` `UNIVERSAL`\\nTerritorio limpio → ni insistas ni te rindas: **cambia de territorio.**\\n\\nEl dolor casi siempre existe, solo que vive en otra zona del mapa. Insistir en zona sana te vuelve interrogador; rendirte regala la visita.\\n\\n### El dolor y la confirmación `CLOSER` `UNIVERSAL`\\nCuando el dolor aparece, **devuélveselo con SUS palabras**. *\\"Entonces lo que más le pega es X, ¿cierto?\\"*\\n\\nEso hace dos cosas: confirma que entendiste, y **le da forma consciente a algo que a lo mejor solo sentía.**\\n\\n> ⚠️ **Pero la confirmación explícita no es requisito para avanzar.**\\n>\\n> Muchas veces el cliente no va a admitir el problema. No porque no lo tenga — sino porque admitirlo suena a queja, o a que eligió mal, o simplemente porque **no lo tiene consciente**. Nadie anda por la vida con una lista de sus problemas operativos.\\n>\\n> Y aun así te sigue escuchando. **Eso ya es información.**\\n\\n**Lo que sí necesitas** es haber leído el problema con evidencia suficiente: algo que dijo, algo que viste, algo que su tipo de negocio hace probable. **Lo que no necesitas es su permiso verbal.**\\n\\n### La venta es emocional antes que racional `CAMPO`\\n\\nEste es el principio que corrige el error de modelar la venta como un proceso lógico.\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente no llena una hoja de cálculo: siente algo, y después construye la razón.\\n\\nConsecuencias que cambian cómo se ejecuta todo el sistema:\\n\\n- **Un cliente puede no reconocer un problema y aun así sentir alivio cuando se lo resuelves.** El impulso no viene de que aceptó el diagnóstico: viene de imaginar la situación resuelta.\\n- **Por eso \\"pintar imágenes\\" funciona** — no argumenta, hace sentir.\\n- **Por eso el vendedor no debe pelear por el reconocimiento explícito.** Insistir en que el cliente admita un problema lo pone a la defensiva y mata lo emocional, que era donde estaba la venta.\\n- **Y por eso el impulso se puede construir sin que haya un dolor declarado.** El 80% indiferente no tiene un problema urgente: se mueve por los factores de impulso, no por el diagnóstico.\\n\\n**La regla operativa:** si el cliente confirma el dolor, úsalo con sus palabras — es lo más fuerte que tienes. **Si no lo confirma pero la evidencia está, avanza igual**, presentando la situación resuelta en vez del problema reconocido.\\n\\n⚠️ **Lo que sigue prohibido es fabricar.** Leer un dolor probable no es inventarlo. La diferencia: leer se apoya en evidencia real — algo que dijo, algo que viste, algo propio de su giro. Fabricar es afirmar un problema **que el cliente ya negó** o del que no hay ningún indicio.\\n\\n### La regla del investigador\\n**El dolor nunca se pregunta directo.** *\\"¿Qué problemas tiene?\\"* produce *\\"ninguno\\"*, garantizado. Se deja emerger.\\n\\n### Luz Verde — 10/80/10 `FUENTE` `UNIVERSAL`\\n**10% negativos · 80% indiferentes · 10% positivos.**\\n\\n1. Sal de las luces rojas **rápido y educadamente**\\n2. Las amarillas reciben tu mejor presentación — pero si no dan señales de compra, muévete\\n3. Las verdes reciben tiempo, relación y resolución de dudas\\n\\n**Los factores de impulso existen principalmente para convertir al 80% indiferente.**\\n\\n#### El rojo verdadero y el que quiere pero no puede `CAMPO`\\n\\nLa luz roja no es cualquier \\"no\\". Es un tipo específico de cliente, y confundirlo cuesta ventas.\\n\\n**ROJO GENUINO** — no quiere. Es cortante, tajante, desganado. Muchas veces medio grosero. Y tiene un costo escondido: **interactuar de más con él desgasta tu actitud**, que es la variable de entrada de todo tu sistema. Con este, salir rápido y bien es la ejecución correcta.\\n\\n**AMARRADO TEMPORALMENTE** — quiere y no puede. Te recibe con gusto, te habla con honestidad, y su impedimento es una **circunstancia que va a cambiar**: un contrato de exclusividad, un inventario recién surtido, un presupuesto agotado, no ser él quien decide las compras grandes.\\n\\n> **Este no es rojo: es verde amarrado.** Y con él, rendirse es la falla más cara del oficio — porque ese cliente sí quería comprarte y el vendedor se fue solo.\\n\\n**Cómo se distinguen:** el rojo se nota en el trato. Es seco, no da información, quiere que te vayas. El amarrado hace lo contrario: es amable, te explica su situación con detalle, y muchas veces se disculpa por no poder.\\n\\n#### Casi toda restricción tiene bordes `CAMPO`\\n\\nY aquí está la mecánica que separa al vendedor promedio del que crece cuentas.\\n\\nCuando un cliente dice que no puede, **el promedio lo toma como total y se va**. El Closer investiga hasta dónde llega:\\n\\n- **¿Qué cubre exactamente?** Una exclusividad casi nunca abarca todas las familias\\n- **¿Qué queda fuera?** Ahí está la venta que la competencia no vio\\n- **¿Hasta cuándo dura?** Para volver justo cuando se libere, antes que nadie\\n\\n> Un contrato que cubre lubricantes, anticongelantes y grasas **deja fuera el líquido de frenos.** Y el vendedor que preguntó se lleva una venta de un cliente que \\"no podía comprar\\".\\n\\n**Y la relación sigue construyéndose mientras tanto.** Seguir visitando a un amarrado no es perder el tiempo: es estar presente el día que la restricción se acabe. El que se rindió no va a estar ahí.\\n\\n⚠️ **La línea:** investigar los bordes no es presionar. Si el cliente ya dijo que algo está dentro de su compromiso, insistir en eso es pedirle que rompa su palabra — y eso quema la relación. Se busca lo que **sí** puede, nunca se pelea lo que no.\\n\\n### QTQP `FUENTE` `UNIVERSAL`\\n**Q**uality **T**ime with **Q**uality **P**eople.\\n\\n> *\\"Perder tiempo y energía con las personas equivocadas destruye tu capacidad de ser lo suficientemente urgente\\"* — y la urgencia es de lo que vive tu ley de promedios.\\n\\nCada minuto con un rojo se lo quitas a un amarillo que sí podía comprar hoy.\\n\\n---\\n\\n## PASO 4 · PRESENTACIÓN\\n### *Construye valor y disminuye el costo*\\n\\n**Qué logra:** convertir el dolor descubierto en valor percibido, y subir el impulso.\\n\\n### Las herramientas de la presentación `FUENTE`\\n1. Encontrar problemas y proporcionar soluciones\\n2. **Pintar imágenes** — que imaginen que ya lo tienen\\n3. Incorporar factores de impulso\\n4. **Triple desglose de precios**\\n5. Hacer el valor enorme: lenguaje expansivo, *\\"gran\\"*, *\\"masivo\\"* `PRESENCIAL`\\n6. Hacer el costo pequeño: *\\"solo\\"*, *\\"apenas\\"* `PRESENCIAL`\\n7. **Tren del Sí** — preguntas cuya respuesta natural es sí\\n8. **CPR sostenido** durante toda la presentación\\n\\n### Beneficio, no característica `CLOSER` `UNIVERSAL`\\nUna característica es lo que el producto **es**. Nadie compra lo que algo es: compran **lo que van a ganar**.\\n\\nToda característica se traduce a una de tres cosas: **dinero** (gana más o gasta menos), **clientes** (vende más o los conserva), o **tranquilidad** (menos problemas, menos tiempo perdido).\\n\\n> Si el cliente puede contestar *\\"¿y eso a mí de qué me sirve?\\"*, la traducción falló.\\n\\n### Teoría de las Balas `FUENTE` `UNIVERSAL`\\n> *\\"La persona con más balas claramente tiene el control, siempre y cuando conserve su munición.\\"*\\n\\n**Las balas son TUYAS.** Son hechos positivos y concretos sobre:\\n- **Ti / tu empresa** — experiencia, premios, casos de éxito, dedicación\\n- **El producto** — lo que lo diferencia, mejoras, datos, certificaciones\\n- **El precio** — propuesta de valor, descuentos, financiamiento, comparación\\n\\n**La prueba de si algo es bala:** si la competencia puede decir exactamente lo mismo, no era bala. *\\"Somos los mejores\\"* es aire; *\\"catorce años surtiendo esta zona sin fallar\\"* es bala.\\n\\n**La regla de dosificación:** *\\"no dispares todas las balas al principio. Reserva algunas para que no importe cuántas balas tenga tu cliente, tengas más con qué responder. Guarda balas para los pasos 4 y 5.\\"*\\n\\n> **Por qué se guardan:** más adelante el cliente va a poner razones para no comprar. Eso baja su impulso. Responderle bien solo **detiene la caída** — lo que vuelve a subirlo es **una bala nueva**. Si las gastaste presumiendo al principio, llegas a ese momento con la mano vacía.\\n\\n### FUJIES / FUJPIG — Factores de Impulso `FUENTE`\\n*\\"El impulso es otra palabra para la emoción.\\"*\\n\\n| | Factor | Físico `PRESENCIAL` | Verbal `UNIVERSAL` |\\n|---|---|---|---|\\n| **F** | Fear of Loss / Miedo a la pérdida | Producto en mano y quitarlo, retroceder un paso | *\\"solo hoy\\"*, *\\"tiempo limitado\\"*, *\\"quedan pocas\\"* |\\n| **U** | Urgency / Urgencia | Tic-tac con el bolígrafo, empezar a alejarse | *\\"ahora\\"*, *\\"rápido\\"*, *\\"solo toma un par de minutos\\"* |\\n| **G** | Greed / Avaricia | Manos mostrando altos y bajos | *\\"normalmente $100, con la promo queda en solo $59.99\\"* |\\n| **I** | Indifference / Indiferencia | Postura, lenguaje corporal | SW3 |\\n| **E** | Effect of Jones / Efecto Jones | — | *\\"tengo como 20 clientes en esta zona que...\\"* |\\n| **S** | Suggestive Language / Poder de sugestión | Manos altas precio alto, bajas precio bajo | Tren del sí, alternativas |\\n\\n**Miedo a la pérdida > necesidad de ganancia.** La gente dice que sí impulsivamente porque no quiere que algo se le vaya.\\n\\n**Urgencia:** *\\"motion creates emotion\\"*. Y además comunica que estás ocupado, o sea que tienes éxito.\\n\\n**Indiferencia:** *\\"be excited about the person and the product, but indifferent whether they buy.\\"* **SW3** — Some Will, Some Won''t, So What. *\\"Ellos solo tienen una oportunidad de comprarte; tú tienes más de cien clientes.\\"*\\n\\n**Efecto Jones:** de *\\"keeping up with the Joneses\\"*. La gente no confía naturalmente en un desconocido incentivado a vender — pero sí deja que sus vecinos, amigos y familia validen el producto por ella.\\n\\n**Poder de sugestión — tres niveles:**\\n- **Mental** — *\\"asumo que todos son un sí hasta que me digan que no\\"*\\n- **Físico** — lenguaje corporal `PRESENCIAL`\\n- **Verbal** — el tren del sí. **El cliente debería decir que sí al menos 6 veces durante el proceso.**\\n\\n> **Elimina cualquier opción que se pueda traducir en un no.** En vez de *\\"¿quiere algo de tomar?\\"* → *\\"¿té, café o jugo?\\"*\\n\\n### La Curva de Impulso `FUENTE` `UNIVERSAL`\\nEl impulso sube y baja durante la conversación, y hay que construirlo **gradualmente** para no abrumar.\\n\\n**Las tres reglas de oro:**\\n1. **Encuentra al cliente en un punto común de emoción** al inicio, y construye desde ahí\\n2. **Cierra en el momento correcto** — el pico\\n3. **Elimina el arrepentimiento con un rehash impulsivo** — porque después del sí, el impulso cae\\n\\n#### La presentación tiene dos mitades `CAMPO`\\n\\nY confundirlas es un error común, así que conviene tenerlas separadas.\\n\\n**PRIMERA MITAD — lo que vas a hacer por él.**\\nConectas con su dolor usando SUS palabras, y explicas cómo se lo resuelves. Aquí no hay producto todavía: hay un problema y una solución. *\\"Eso que me dice de quedarse sin producto cuando le entra movimiento — eso es venta que se le va.\\"*\\n\\n**SEGUNDA MITAD — el producto y el precio.**\\nUn resumen breve de qué es lo que le va a resolver eso, y el Triple Desglose de Precios. De ahí se pasa directo al cierre.\\n\\n> **El precio SÍ va en la presentación.** Lo que va en el cierre es el **resumen del pedido** — qué y cuánto lleva. Son dos cosas distintas:\\n>\\n> · **Presentación** → el precio en escalera con sus motivos. *\\"Normalmente le sale en X, como es primer pedido queda en Y, y de contado en Z.\\"*\\n> · **Cierre** → lo que lleva. *\\"Entonces le van dos cajas de esto y una de aquello. ¿Jueves o viernes?\\"*\\n>\\n> Enumerar SKUs con cantidades en la presentación es escribir el cierre en el lugar equivocado. Pero omitir el precio es dejar la presentación a medias — y el cliente se queda esperando el número que nunca llegó.\\n\\n### Triple Desglose de Precios `FUENTE (definido) + CAMPO (desarrollado)` `UNIVERSAL`\\n> **Valor menos costo es igual a ahorro.**\\n\\n**La escalera — tres cifras bajando:**\\n1. **Lo que normalmente cuesta** — hace match con lo que el cliente ya esperaba\\n2. **Con el primer descuento** — cliente nuevo, volumen, lo que aplique\\n3. **Con el segundo** — pago de contado, cerrar hoy, lo que corresponda\\n\\n**El ahorro dicho en voz alta.**\\n\\n> **La regla que lo hace funcionar: cada escalón necesita un motivo nombrado.**\\n>\\n> Un precio que baja **sin razón** le dice al cliente que el primero estaba inflado — y te vuelve regateable, porque si bajó dos veces solo, va a bajar otra si presiona.\\n>\\n> Un precio que baja **por razones nombradas** confirma que el primero era real, y cada escalón se vuelve una bala de precio.\\n\\n**Por qué se ve y no solo se escucha:** *\\"queda en ochenta\\"* se escucha como un gasto de ochenta. *\\"Normalmente cien, con su descuento noventa, de contado ochenta\\"* se ve como veinte de ahorro que antes no existían. Mismo número final, sensación opuesta.\\n\\n**Y como el último escalón depende de algo que puede hacer HOY, aparece solo el miedo a la pérdida.**\\n\\n> ⚠️ **Nunca un solo precio.** Un precio suelto es un gasto sin ahorro visible que lo compense.\\n\\n---\\n\\n## PASO 5 · CIERRE\\n### *Extrae eficientemente una decisión*\\n\\n### Qué es un cierre `FUENTE`\\n> *\\"Un cierre no es algo que le haces a alguien. Un cierre es un acuerdo, cuando el cliente se da cuenta de que el beneficio supera al costo y decide. El cierre se lo hace la gente a sí misma.\\"*\\n\\n**Un cierre no siempre es una venta.** Es pedir la decisión, sea cual sea. Asegúrate de que tus conversaciones avancen hacia una conclusión — un sí o un no.\\n\\n### Asumir la venta `FUENTE` `UNIVERSAL`\\nSi llegaste a este punto, **presume que tienes un comprador**.\\n\\n**Malos cierres** — todos invitan al no:\\n*¿Le gustaría comprar? · ¿Está interesado? · ¿Le gusta lo que oye? · ¿Qué le parece? · ¿Cómo lo ve?*\\n\\n**Buenos cierres** — alternativas donde ambas opciones sirven:\\n*¿Es su nombre el que va en la cuenta? · Las primeras fechas de entrega son jueves o viernes, ¿cuál le conviene? · ¿Visa o MasterCard? · ¿Contado o crédito?*\\n\\n> **El diagnóstico de la fuente:** *\\"la mayoría de las personas que batallan para cerrar simplemente no están rompiendo la zona de confort que viene con pedir algo.\\"*\\n>\\n> Y: *\\"aumentas la probabilidad de que compren mientras más confiadamente anuncies tu mensaje.\\"*\\n\\n### El silencio después del cierre `CAMPO` `UNIVERSAL`\\nNo llenes el silencio. Pediste la decisión: **aguanta**.\\n\\nEl vendedor que retira la pregunta, la suaviza o la contesta él mismo, pierde. El primero que habla después de un cierre, pierde.\\n\\n### FISHBBOD — Señales de Compra `FUENTE`\\nTambién llamadas **STOP signs**. En cuanto reconoces una, **DETIENES la presentación y CIERRAS**.\\n\\n**F** Future talk · **I** I want / I need · **S** Silence · **H** How much / How soon · **B** Body language `PRESENCIAL` · **B** Bashing competitor · **O** Offers of courtesy · **D** Deeper questions\\n\\n> **El error que cuesta más ventas de lo que nadie cree:** el cliente da la señal, el vendedor la ve, y como todavía le quedaban dos argumentos buenos, los suelta.\\n>\\n> **El impulso baja.** Porque el cliente ya estaba listo, y seguir vendiéndole le comunica que hay algo que convencerlo — o le da tiempo de encontrar una razón para no hacerlo.\\n>\\n> Señal de compra = deja de presentar y cierra. **Aunque te queden balas. De hecho, sobre todo si te quedan.**\\n\\n---\\n\\n## MANEJO DE OBJECIONES `FUENTE`\\n### *No son negativas: son preguntas que, bien respondidas, terminan en venta*\\n\\n**Objeción = señal de compra.** El que no tiene interés no objeta: se despide.\\n\\n### Las cuatro técnicas de overturn\\n\\n| Técnica | Cuándo | Cómo |\\n|---|---|---|\\n| **AIR** — Agree, Ignore, Resume | Bloqueos en la introducción | Reconoce, ignora, continúa |\\n| **Ataque Preventivo** | Intro o historia breve, negativos conocidos del territorio | Da el negativo antes que el cliente |\\n| **RRR** — Repeat, Reassure, Resume | Objeciones menores y comunes | Repite, responde, **continúa sin pausa** |\\n| **FFF** — Feel, Felt, Found | Preocupación seria o personal | Nunca discutas |\\n\\n### RRR de objeciones `FUENTE` `UNIVERSAL`\\n**R**epeat — repite la objeción en sus términos, para que vea que la escuchaste\\n**R**eassure — la respuesta concreta, con datos\\n**R**esume — **retoma sin pausa**\\n\\n> **La tercera R es la que falla.** El vendedor responde bien y se queda callado esperando a ver si convenció. En ese espacio el cliente encuentra la siguiente objeción, o dice que lo va a pensar.\\n\\n### FFF — el procedimiento completo `FUENTE` `UNIVERSAL`\\n**Nunca discutas con un cliente.** Ganar la discusión es perder la venta.\\n\\nEn español: **Entiendo · Sintió · Encontramos**\\n\\n1. **\\"Entiendo cómo se siente\\"** — estar de acuerdo te vuelve distinto del vendedor promedio, **y por eso te escuchan**\\n2. **\\"Mi último cliente sentía lo mismo\\"** — para que sepa que no está solo\\n3. **\\"Lo que encontramos fue...\\"** — por qué dejaron de pensar así. **Esto usa Efecto Jones**\\n4. **Inserta 3 balas** de la Teoría de las Balas\\n5. **Close With Action**\\n\\n> ⚠️ **FFF no termina en la tercera F.** El documento en español del sistema fuente está truncado y solo llega al paso 3 — por eso mucha gente aprendió un FFF incompleto, sin re-impulso y sin cierre. **Los pasos 4 y 5 son el Círculo de Cierre.**\\n\\n### El Círculo de Cierre `FUENTE (implícito) + CAMPO (nombrado)` `UNIVERSAL`\\n\\n```\\n   CLOSE WITH ACTION ←──────────────┐\\n            ↓                        │\\n   ¿Objeción? → el impulso baja      │\\n            ↓                        │\\n   Atraviesas (RRR o FFF)            │\\n            ↓                        │\\n   RE-IMPULSAS con una bala NUEVA ───┘\\n```\\n\\n> **El error más común: atravesar la objeción y cerrar de inmediato, saltándose la bala.**\\n>\\n> Técnicamente respondiste. Pero **atravesar solo detiene la caída del impulso** — no lo sube. Estás pidiendo una decisión en el punto más bajo de la conversación, y desde ahí la respuesta cómoda siempre es *\\"déjeme lo pienso\\"*.\\n\\n**Y la bala tiene que ser NUEVA.** Repetir un argumento ya usado no sube nada: comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.\\n\\n### La Regla de los No\\n- **Fuente:** *2 no''s and a go* — dos no seguidos, luz roja, sigue adelante\\n- **Campo `CAMPO`:** Emilio usa **3 no seguidos**, porque hay gente que deja ir un sí solo porque el cliente tuvo preguntas u objeciones\\n\\n> **Tienen que ser CONSECUTIVOS.** Un no, lo atraviesas, la conversación avanza, y más adelante otro no: **eso no es una racha**. Es una conversación normal con dos momentos de fricción. La racha se rompe en cuanto la conversación avanza.\\n\\n---\\n\\n## PASO 6 · CONSOLIDACIÓN / REHASH\\n### *El paso final y más importante*\\n\\n**REHASH** = **R**emember **E**veryone **H**as **A**nother **S**ale **H**idden\\n\\n**Dos propósitos** `FUENTE`:\\n1. **Capitalizar a un cliente ya positivo** — *\\"la gente compra de sus amigos mucho más fácil que de un desconocido\\"*\\n2. **Dejarlo positivo y entendiendo los siguientes pasos** — *\\"la causa número uno de cancelaciones es la falta de entendimiento\\"*\\n\\n### El arrepentimiento del comprador\\nApenas dice que sí, **el impulso cae**. El cerebro empieza a buscar razones por las que quizá no debió. Es automático y no es desconfianza hacia ti.\\n\\n### Cómo se disuelve `CAMPO`\\n> **El error que parece lo correcto: seguir vendiendo.**\\n>\\n> La reacción natural es reforzar la compra — recordarle lo bueno del producto, repetirle el ahorro, insistir en que tomó una gran decisión.\\n>\\n> **Y eso lo empeora.** Seguir vendiendo después del sí le dice al cliente que **necesitabas la venta**. Y si la necesitabas, entonces la indiferencia era actuada. Y si la indiferencia era actuada, también el interés por su negocio, también las preguntas, también la plática de su hijo.\\n>\\n> **Retroactivamente, toda la conversación se convierte en una técnica.**\\n\\n**Lo que sí funciona: demostrar que nada cambió en ti.**\\n\\nMisma indiferencia sobre la compra. Misma calidez sobre la relación. Cero producto. Y la confianza de que ahí vas a estar para lo que necesite.\\n\\n**Por qué funciona:** si tu actitud es idéntica antes y después de la firma, el cliente concluye solo lo que ninguna frase habría logrado convencerlo — **que no lo trataste así para venderle, sino porque así eres.** Y con esa conclusión, el arrepentimiento no tiene de qué agarrarse.\\n\\n**Y deja claro qué sigue.** La falta de entendimiento es la causa número uno de cancelaciones.\\n\\n---","is_active":false,"created_at":"2026-09-25T20:26:45.879837+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"6b46630f-49c7-4d08-8ada-7e58843db6af","version":2,"section_key":"mentalidad","order_index":3,"title":"PARTE 3 · LA MENTALIDAD","body":"# PARTE 3 · LA MENTALIDAD\\n### *La segunda fundación*\\n\\n> *\\"No importa qué tan buenas sean tus habilidades conversacionales, nunca vas a tener 100% de éxito.\\"*\\n>\\n> Y: *\\"hay gente con mucha personalidad o experiencia que triunfa sin trabajar bien la ley de promedios — pero no puede replicar su éxito, porque depende demasiado de la habilidad.\\"*\\n\\n**La mentalidad no es motivación: es el sistema de control que hace replicable el resultado.**\\n\\n## Ley de Promedios (LDP) `FUENTE`\\n> *\\"Si repites una acción las veces suficientes, aparecerá una proporción.\\"*\\n\\nEs un sistema probado para **encontrar compradores entre los no compradores**.\\n\\n**La analogía de la moneda:** lanzas una vez, 50/50. Lanzas diez veces y raramente sale 5 y 5. Pero mientras más lanzas, más se acerca la muestra a la proporción real. **La ley necesita volumen para manifestarse.**\\n\\n## PPA — lo que afecta tu ley de promedios `FUENTE`\\n**P**itch / Conversación — preciso, conciso, impactante\\n**P**ace / Ritmo — con cuánta gente hablas\\n**A**ttitude / Actitud — consistentemente positiva\\n\\n> **La cadena causal, y por qué la mentalidad no es opcional:**\\n> La ley de promedios necesita volumen. El volumen desgasta la actitud. La actitud degrada el pitch. Y el pitch es la variable de entrada del sistema.\\n>\\n> **Por eso KILT, los 3 tipos de día, controlables y gumball existen: protegen la única variable que el vendedor controla.**\\n\\n## Los 3 Tipos de Día `FUENTE`\\n- **Día A** — las ventas llegan temprano, la actitud es fácil\\n- **Día B** — llegan esporádicamente, no te prueba del todo\\n- **Día C** — todas llegan en las últimas horas. **La verdadera prueba de quién cree en el sistema**\\n\\n*Ejemplo real: 3 ventas de 60 contactos es normal — 5% de éxito. Es normal no tener ningún cliente hasta el final del día y aun así cumplir.*\\n\\n## Teoría del Gumball `FUENTE`\\nTres máquinas, 100 dulces cada una, 97 rojos y 3 verdes. Cada intento cuesta un peso. Tienes 100 pesos y la meta de sacar 3 verdes.\\n\\n**Mantén tu pitch, ritmo y actitud iguales, para que cada \\"no\\" te acerque al \\"sí\\".**\\n\\n> **La dificultad real:** en el campo no puedes ver dónde están los verdes como en la máquina. Tienes que seguir girando a ciegas, sabiendo que tu proporción va a aparecer.\\n\\n## Controlables vs No Controlables `FUENTE`\\n> *\\"Si no podemos controlarlo, no lo pensamos ni lo hablamos. Es una pérdida de tiempo y energía.\\"*\\n\\nLa mayoría pasa el día culpando cosas que no controla. Concentrarse en lo controlable es mucho más productivo: ver más gente, tener mejores conversaciones, cuidar la actitud.\\n\\n## KILT `FUENTE`\\n**K**ill them with kindness — sé amable sin importar la actitud del otro\\n**I**ndifference — algunos comprarán, otros no, ¿y qué?\\n**L**aw of averages — confía en los números\\n**T**reat everyone like your first — nunca sabes cuándo aparece tu cliente\\n\\n**Aplicación:** si dejamos a cada persona mejor de como la encontramos, permanecemos indiferentes al sí o al no, y tratamos a cada quien como el primero, entonces protegemos la actitud.\\n\\n## Los 8 Grandes Hábitos `FUENTE`\\n*\\"Somos lo que hacemos repetidamente; el éxito es un hábito.\\"*\\n\\n1. **Tener gran actitud** — el negocio es 99% actitud y 1% habilidad\\n2. **Ser puntual** — si no llegas temprano, llegas tarde\\n3. **Estar preparado** — fallar en prepararse es prepararse para fallar\\n4. **Esfuerzo del 100%** — recibes lo que pones\\n5. **Maximizar tu territorio** — tu territorio no es el lugar, **son las personas**\\n6. **Proteger tu actitud** — cada \\"no\\" te acerca al \\"sí\\"\\n7. **Conocer tu porqué** — metas de corto, mediano y largo plazo\\n8. **Tomar el control** — de tu día, tu carrera y tu vida\\n\\n## Indicadores / Gauges `FUENTE`\\nMiden con cuánta gente hablas y qué tan lejos llegas en los pasos.\\n\\n**Puertas → Con cuántos hablaste → Presentaciones → Cierres**\\n\\n**Para qué sirven:**\\n1. Identificar dónde **podría** romperse el sistema en tus 6 pasos\\n2. Asegurar que trabajas el sistema\\n3. Marcarte el ritmo\\n\\n> ⚠️ **Los indicadores señalan DÓNDE MIRAR, no qué está mal.**\\n>\\n> Si presentas a muchos y cierras a pocos, el número te dice que algo pasa **entre la presentación y el cierre** — pero la causa puede estar mucho antes. Puede ser que el descubrimiento no encontró el dolor real, que no hubo suficiente CPR y el cliente nunca contestó de verdad, que la presentación se alargó y cayó en KILL, que el impulso se construyó mal, o que efectivamente el cierre es débil.\\n>\\n> **Un número no diagnostica una causa.** Diagnostica una zona.\\n\\n**El diagnóstico real requiere ver la conversación.** Como manager: acompañando al vendedor en campo, o pidiéndole una práctica en Closer sobre el paso donde sospechas.\\n\\n**Números + conversación observada = conclusión.** Cualquiera de los dos solo, es especulación.\\n\\n## Metas — SMART `FUENTE`\\n**S**pecific · **M**easurable · **A**ttainable · **R**ealistic · **T**imed\\n\\nTipos: de **resultado** · de **acción** · corto plazo (<2 meses) · mediano (2 meses–3 años) · largo (3+ años)\\n\\nEscríbelas, hazlas evaluar por alguien, y recompénsate al lograrlas.\\n\\n---","is_active":false,"created_at":"2026-09-25T20:26:45.879837+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"2bc694ec-5d33-4ac9-972a-7d0d3f753e66","version":2,"section_key":"aplicacion","order_index":4,"title":"PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE","body":"# PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE\\n\\n> **El sistema es el esqueleto. Si se entiende, se aplica a cualquier cliente, cualquier industria y cualquier producto.**\\n\\nEsta parte NO es un catálogo de casos. Es la demostración de cómo se deduce la ejecución correcta a partir de los principios — para que cualquier caso que no esté aquí se resuelva igual.\\n\\n## 4.0 El método de adaptación\\n\\nCada paso existe para lograr algo. **Lo que cambia entre clientes no es el objetivo del paso: es lo que hace falta para lograrlo.**\\n\\nEjemplo con la Historia Breve. Su objetivo es liberar el segundo tercio de atención — las dos preguntas que el cliente trae en la cabeza: *quién eres* y *por qué estás aquí*.\\n\\n- Con un desconocido, las dos están abiertas → contestas las dos\\n- Con alguien que te conoce hace años, la primera ya está contestada → **solo queda el porqué de hoy**, y a veces hasta eso es obvio\\n\\n**La conclusión operativa, dicha completa:** con un cliente que ya te conoce, la Historia Breve **NO incluye tu nombre ni el de tu empresa**. Nada de \\"Soy Juan, de [empresa]\\", ni \\"trabajamos con tal marca\\". Él ya lo sabe. Repetírselo le comunica que no lo reconoces o que estás recitando un guion — y en los dos casos daña la relación que llevas años construyendo.\\n\\nLo único que queda es **por qué viniste HOY**, en una o dos frases. Y a veces hasta eso es evidente.\\n\\nEse es el método. Ante cualquier cliente, en cualquier industria:\\n\\n1. ¿Qué **objetivo** tiene este paso?\\n2. ¿Qué de ese objetivo **ya está resuelto** con este cliente?\\n3. ¿Qué **falta** por resolver?\\n4. **Ejecuta solo eso, y escribe solo eso.**\\n\\n> ⚠️ **El paso 4 es donde más se falla.** Deducir correctamente qué falta y aun así escribir la versión completa por costumbre es el error más frecuente al aplicar este método. Si concluiste que algo ya está resuelto, **ese algo no aparece en el texto.** No basta con saberlo: hay que omitirlo.\\n\\n## 4.0b Autoconsumo y distribuidor NO son un tercer eje `CAMPO`\\n\\nHay una confusión fácil de cometer: tratar \\"autoconsumo\\" y \\"distribuidor\\" como si fueran alternativas a \\"nuevo\\" y \\"recurrente\\". No lo son. **Son ejes distintos.**\\n\\n**EJE 1 — ¿Ya te compra?** Nuevo o recurrente. Esto define **la relación**: si te conoces, si hay historial, si hay pedido base.\\n\\n**EJE 2 — ¿Qué hace con el producto?** Revende, consume o distribuye. Esto define **las preguntas**: qué se le pregunta en cada territorio.\\n\\n**Se cruzan.** Un cliente de autoconsumo puede ser nuevo (nunca te ha comprado) o recurrente (lleva años surtiéndose contigo). Y la ejecución cambia según el cruce:\\n\\n| | Nuevo | Recurrente |\\n|---|---|---|\\n| **Revende** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Consume** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Distribuye** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n\\n> **Lo que cambia por el EJE 1** es si te presentas, si hay \\"lo de siempre\\", y si buscas dolor o hueco.\\n>\\n> **Lo que cambia por el EJE 2** es únicamente el vocabulario del descubrimiento: al que revende le preguntas qué maneja y qué le piden; al que consume, qué usa y cada cuánto repone; al que distribuye, sus líneas y a cuántos surte.\\n\\n**Error concreto que esto evita:** escribir la historia breve de un cliente de autoconsumo como si fuera recurrente — *\\"vine a ver cómo les funcionó lo que dejamos la vez pasada\\"* — cuando nunca ha habido una vez pasada. Autoconsumo no dice nada sobre si ya te compra o no.\\n\\n**Y una vez que un cliente de autoconsumo te compra, se vuelve recurrente**: el seguimiento y el crecimiento de esa cuenta funcionan igual que con cualquier otro recurrente. Buscas huecos, cierras el incremento, y no te vuelves a presentar.\\n\\n## 4.1 Lo que sí cambia sustancialmente\\n\\nHay dos diferencias que no son obvias y que sí conviene tener explícitas, porque cambian **qué se busca**, no solo cómo se dice.\\n\\n### Diferencia 1 — Qué buscas en el Descubrimiento\\n\\n**DOLOR** — algo anda mal. Tiene señal verbal: **el \\"aunque\\"**. Se busca con los 3 Territorios y la escalera de capas.\\n\\n**HUECO** — algo que podría comprarte y no te compra. **No tiene señal verbal: se ve, no se oye.**\\n\\n> Un cliente conforme no tiene dolor. **Por eso el vendedor que solo sabe buscar dolor visita durante años sin crecer una cuenta**: busca, no encuentra, y concluye correctamente que no hay nada.\\n\\n**Las tres herramientas del hueco:**\\n\\n**1 · Lee el lugar** — lo que ves te dice qué maneja y de quién. Un producto de otra marca es un espacio ocupado; un estante vacío es una familia que nadie cubre; algo empolvado no es hueco, **es dolor**.\\n\\n**2 · Pregunta por lo que le piden** — *\\"¿le ha tocado que le pidan algo que no maneje?\\"* Demanda que ya existe sin oferta que la cubra.\\n\\n**3 · Ancla en negocios como el suyo** — Efecto Jones aplicado. Solo si es verdad y lo puedes sostener.\\n\\n**Adaptación por canal:** presencial observas; a distancia preguntas por el catálogo. **Adaptación por giro:** si el cliente no revende, \\"lo que ves\\" no es un mostrador — son sus unidades, su patio, su operación.\\n\\n> **La línea que no se cruza:** un hueco tiene que ser real y verificable. **Descubrir un hueco es señalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.**\\n\\n### Diferencia 2 — Qué estás cerrando\\n\\nCon un cliente que ya compra, **el pedido base no está en duda: ya iba a existir.** Lo que se cierra es **lo que se agrega**.\\n\\nReabrir el pedido base al cerrar pone sobre la mesa algo que ya estaba resuelto, e invita al cliente a revisar toda la orden.\\n\\n## 4.1b La observación del recurrente no puede sonar a primera visita `CAMPO`\\n\\nEl SCE y el ice breaker siguen aplicando con un cliente de años. Lo que cambia es **de qué se observa**.\\n\\n**El error:** *\\"¿Siempre está así de lleno o hoy le tocó día pesado?\\"*\\n\\nEsa pregunta la hace alguien que no conoce el lugar. Y este vendedor lleva años pasando cada quincena — **ya sabe si el negocio es movido.** Preguntarlo le comunica al cliente que no lo tiene presente, que es lo contrario de lo que la relación construyó.\\n\\n**Lo correcto: observar lo que CAMBIÓ desde la última visita.**\\n\\n> *\\"Oiga, ¿ya le entró más gente que la vez pasada, verdad?\\"*\\n> *\\"Veo que le movió al acomodo desde que vine.\\"*\\n> *\\"¿Ya se compuso lo del clima o siguen igual de flojas las tardes?\\"*\\n\\nY también funciona lo personal, que con un desconocido no puedes usar:\\n\\n> *\\"¿Cómo salió su muchacho de lo que me contó?\\"*\\n> *\\"¿Le fue bien en el puente?\\"*\\n\\n> **La prueba:** si tu observación de apertura funcionaría igual con un cliente que ves por primera vez, no está aprovechando la relación. **Con un recurrente, la apertura demuestra memoria** — y esa memoria es el activo que llevas años construyendo.\\n\\n⚠️ **Y esto solo funciona si la memoria es real.** Inventar que recuerdas algo que no pasó es peor que no recordar nada. Si no tienes un dato de la visita anterior, observa el momento presente sin fingir historia: *\\"se ve movido hoy\\"* es honesto; *\\"¿siempre está así?\\"* no lo es.\\n\\n## 4.2 Lo que NO cambia nunca\\n\\n- El orden de los 6 pasos\\n- Que el descubrimiento va antes de la presentación\\n- Que el cierre asume en vez de pedir aprobación\\n- Que el precio va en escalera con motivo\\n- Que no hay frases neutras\\n- Toda la Parte 6 (jerarquía de reglas)\\n\\n## 4.3 Presentar un hueco `CAMPO`\\n\\nCuando lo que encontraste es un hueco, no hay nada que resolver: el cliente está conforme. Hay un espacio que ocupar.\\n\\n**La pregunta que define el argumento: ¿qué gana él con que tú se lo surtas?**\\n\\nY la respuesta depende del caso, no de una fórmula. Posibilidades reales:\\n\\n- **Consolidación** — si el cliente trata con muchos proveedores y eso le pesa, reducir el número tiene valor por sí mismo\\n- **Conveniencia** — te ve de todos modos; agregar una familia no le suma trabajo\\n- **Complementariedad** — lo que ofreces se usa junto con lo que ya te compra\\n- **Una condición concreta** — plazo, disponibilidad, presentación, tiempo de entrega\\n\\n> ⚠️ **La consolidación NO es un argumento universal.** Si tu producto es complementario y el cliente ya tiene cinco proveedores, con la familia nueva pasa a tener **seis, no cuatro**. Ahí *\\"menos proveedores que seguir\\"* es falso, y usarlo te desacredita.\\n>\\n> Antes de usarlo, verifica que el cliente **efectivamente vaya a reducir** su número de proveedores.\\n\\n⚠️ **Nunca ataques al proveedor actual.** Criticarlo es criticar la decisión del cliente, y la gente defiende sus decisiones.\\n\\n⚠️ **No afirmes ventajas que no puedes verificar.** *\\"El otro no maneja esta línea\\"*, *\\"nadie tiene nuestro catálogo\\"*, *\\"con nosotros le sale mejor\\"* — si no lo sabes de cierto, no lo digas. Puede ser falso, y en una cuenta de años se descubre siempre. **Habla de lo que TÚ ofreces, con hechos que puedas sostener.**\\n\\n## 4.4 Convicción sin garantía `CAMPO`\\n\\n> **Nunca le pidas que \\"pruebe\\".**\\n>\\n> *\\"Le pongo unas pocas para que lo pruebe\\"* suena humilde y es lo peor que puedes decir: **le pasas el riesgo a él.** La gente no quiere experimentar — está cómoda donde está, y probar algo nuevo es riesgo, incomodidad y la posibilidad de haberse equivocado.\\n\\n**El trabajo del vendedor no es pedir permiso para experimentar. Es hacer que el cliente se sienta seguro.** Dos movimientos:\\n\\n1. **Convicción, sin garantía** — *\\"no le puedo garantizar nada, pero estoy seguro de que le va a servir\\"*\\n   **Funciona precisamente porque reconoce el límite.** Admitir lo que no controlas hace creíble lo que sí afirmas.\\n\\n2. **La razón detrás** — *\\"se lo digo porque en negocios como el suyo es de lo que más sale\\"*\\n   Sin la razón, tu convicción es solo optimismo de vendedor.\\n\\n**Y ahí te callas.**\\n\\n⚠️ **No ofrezcas el plan B.** *\\"Y si no funciona lo ajustamos\\"* parece que baja el riesgo y hace lo contrario: **le mete una duda que no tenía**, y desmiente lo que acabas de afirmar. Si de verdad estás seguro, ¿para qué el paracaídas?\\n\\n*(Si después no funciona, ahí lo ajustas. Eso es Consolidación y se hace cuando pasa — no se anuncia por adelantado.)*\\n\\n## 4.5 El capital del récord `CAMPO`\\n\\n> **La primera vez que recomiendas algo, el cliente compra por la relación. La segunda vez, compra por tu récord.**\\n\\nY eso disciplina: si recomiendas algo que no funciona, **no perdiste una venta — gastaste crédito que te costó años juntar.** Por eso solo se recomienda lo que de verdad sirve a ese perfil, aunque haya cosas con mejor margen.\\n\\n## 4.6 Los dos juegos `CAMPO`\\n\\n**ADQUISICIÓN** — convertir a un desconocido en cliente.\\n**DESARROLLO** — convertir a un cliente en un cliente más grande.\\n\\n> **La asimetría que explica por qué el segundo se descuida:** adquisición da retroalimentación inmediata — vendes o no vendes. Desarrollo no. Puedes visitar cien veces, levantar el mismo pedido, sentir que hiciste bien tu trabajo, y nunca enterarte de lo que dejaste sobre la mesa.\\n>\\n> **El fracaso en desarrollo es invisible.**\\n\\n**El enemigo: la visita que se vuelve trámite.** El vendedor está haciendo adquisición con alguien que ya adquirió — y como no hay nada que adquirir, no hay nada que hacer.\\n\\n> **Al que solo toma pedidos lo reemplaza un formulario.**\\n\\n---","is_active":false,"created_at":"2026-09-25T20:26:45.879837+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"40ceb15c-1bce-49fe-a78e-7cc15a65c4fc","version":2,"section_key":"canales","order_index":5,"title":"PARTE 5 · MODIFICADORES DE CANAL","body":"# PARTE 5 · MODIFICADORES DE CANAL\\n\\n| Canal | Qué se conserva | Qué se adapta |\\n|---|---|---|\\n| **Presencial** | Todo | — |\\n| **Teléfono** | Los 6 pasos, KISS, FORMS, las 4 técnicas de overturn, balas, FUJIES verbales, CWA, triple desglose, y el **entusiasmo del tono** | Contacto visual → pausas y ritmo. Todo lo físico se pierde |\\n| **WhatsApp / mensaje** | La estructura completa, balas, triple desglose, ataque preventivo | Mensajes cortos, uno por idea. Señales de compra → velocidad de respuesta, emojis, preguntas de precio. El cierre debe contestarse con una palabra |\\n| **Correo** | Estructura, KISS, balas, triple desglose | Todo lo interactivo se vuelve secuencia |\\n\\n> **El principio de adaptación: entender qué HACE cada técnica permite encontrar su equivalente en cualquier medio.**\\n>\\n> El miedo a la pérdida no es *\\"quitar el producto de la mano\\"* — es **crear la sensación de que algo se va**. Eso existe en los cuatro canales.\\n\\n---","is_active":false,"created_at":"2026-09-25T20:26:45.879837+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"42d87b7d-d1e9-47ae-82cf-d497ff370e53","version":2,"section_key":"jerarquia","order_index":6,"title":"PARTE 6 · JERARQUÍA DE REGLAS","body":"# PARTE 6 · JERARQUÍA DE REGLAS\\n\\nCuando dos principios chocan, gana el de mayor jerarquía.\\n\\n## NIVEL 1 — Inviolables (ética y verdad)\\nNunca se rompen, en ningún contexto, por ninguna razón.\\n\\n1. **Impulso falso está prohibido.** Urgencia inventada, escasez que no existe, prueba social fabricada. *(Práctico, no solo moral: un impulso falso se derrumba cuando el cliente lo descubre, y se lleva la venta, la relación y tu reputación en la zona.)*\\n2. **No garantizar lo que no controlas.** Convicción sí; garantía no.\\n3. **No fabricar un hueco ni un dolor.** Descubrir es señalar lo que existe.\\n4. **No atacar al competidor ni al proveedor actual.**\\n5. **No afirmar ventajas que no puedes verificar.** *\\"Nadie más tiene esto\\"*, *\\"el otro no lo maneja\\"*, *\\"con nosotros sale mejor\\"* — si no lo sabes de cierto, no lo dices. Habla de lo que TÚ ofreces.\\n6. **Nunca discutir con un cliente.**\\n\\n## NIVEL 2 — Estructurales\\nSe rompen solo si el Nivel 1 lo exige.\\n\\n7. **El orden de los 6 pasos.** No se salta ninguno.\\n8. **Primero el examen, luego la receta.** No presentar sin diagnosticar.\\n9. **El cierre asume, no pide aprobación.** Toda pregunta que permita aprobar o posponer entrega el control.\\n10. **El precio va en escalera con motivo en cada escalón.** Nunca un solo número.\\n11. **No hay frases neutras.** Si algo resta valor y nadie lo preguntó, se omite.\\n12. **Señal de compra = detente y cierra.**\\n13. **Se sale de la línea, pero siempre se regresa.**\\n14. **Nunca pidas opinión ni aprobación sobre el precio.** Ni el tuyo ni el de la competencia. Preguntar *\\"¿cómo ve los precios?\\"* le pide al cliente que construya una posición contra ti antes de que exista valor, cede tu autoridad sobre el precio, y renuncia a tu ventaja — porque tú conoces el mercado y él muchas veces no. En el territorio PRECIO se investigan **hechos** (a cómo compra, qué plazo tiene, cada cuánto le suben), nunca opiniones.\\n\\n## NIVEL 3 — Contextuales\\nDependen del tipo de cliente, canal o situación. **Se deducen del método de la Parte 4.0, no se memorizan.**\\n\\n14. Qué parte de la Historia Breve hace falta — depende de qué ya sabe el cliente\\n15. Buscar dolor o buscar hueco — depende de si el cliente está conforme\\n16. Qué argumento usar al presentar un hueco — depende de qué gana él en ESE caso\\n17. Cerrar la venta o cerrar el incremento — depende de si hay un pedido base\\n18. SEE físico — solo presencial\\n\\n## NIVEL 4 — Estilo\\nAjustables al lenguaje del vendedor, la zona y la empresa.\\n\\nTono, vocabulario, longitud de frases, formalidad. **El manager conoce el lenguaje de su gente mejor que Closer.**\\n\\n---","is_active":false,"created_at":"2026-09-25T20:26:45.879837+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"789d9b21-83f9-46a2-a21b-9882fc8de73c","version":2,"section_key":"razonamiento","order_index":7,"title":"PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO","body":"# PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO\\n\\n## Ante un caso no cubierto\\n1. Identifica **qué paso** de la línea es\\n2. Pregunta **qué objetivo tiene ese paso**\\n3. Pregunta **qué de ese objetivo ya está resuelto** con este cliente, y qué falta\\n4. Verifica contra la **jerarquía**: ¿viola algo de Nivel 1 o 2?\\n5. Si sigue sin resolverse, **di que no lo sabes.** No inventes doctrina.\\n\\n## Ejemplos de deducción\\n\\n**Caso:** un vendedor pregunta si puede decir *\\"¿le late?\\"* al cerrar.\\n**Razonamiento:** es una pregunta que permite aprobar o posponer → viola la regla 9 (Nivel 2) → **no**. La alternativa es una pregunta donde ambas opciones sirvan.\\n\\n**Caso:** un manager quiere que el pitch mencione que un producto no trae promoción este mes.\\n**Razonamiento:** no hay frases neutras (1.3); esto baja el valor percibido; nadie lo preguntó → **se omite**. Regla 11, Nivel 2.\\n\\n**Caso:** un vendedor pregunta cómo abrir con un cliente que le compra desde hace cinco años.\\n**Razonamiento:** aplica el método 4.0. Objetivo de la Historia Breve = contestar *quién eres* y *por qué estás aquí*. Lo primero ya está resuelto → **solo queda el porqué de hoy**, y a veces hasta eso es evidente. No hace falta una regla especial: sale del objetivo del paso.\\n\\n**Caso:** vender un servicio de software por videollamada a una empresa que nunca lo ha usado.\\n**Razonamiento:** el sistema aplica igual. Cliente nuevo → doctrina de adquisición. Canal remoto → SEE físico no aplica, pero el entusiasmo del tono sí. \\"Lee el lugar\\" no existe, así que se pregunta. Los 3 Territorios se traducen: producto = qué usan hoy, servicio = cómo los atiende su proveedor, precio = qué pagan. **Nada del esqueleto cambia.**\\n\\n**Caso:** un vendedor dice que el cliente no le reconoce ningún problema, pero él ve claro que sí lo tiene.\\n**Razonamiento:** aplica 1.5. La confirmación explícita no es requisito. Si hay evidencia real — algo que dijo, algo que vio, algo propio de su giro — **avanza presentando la situación resuelta**, no el problema reconocido. Insistir en que lo admita lo pone a la defensiva y apaga lo emocional, que es donde está la venta. **El límite:** si el cliente ya negó explícitamente ese problema, insistir es fabricar, y eso es Nivel 1.\\n\\n**Caso:** un vendedor lleva tres días sin cerrar y está desanimado.\\n**Razonamiento:** esto es Parte 3, no Parte 2. Aplica Ley de Promedios, los 3 Tipos de Día (día C), gumball, y controlables vs no controlables. **No es un problema de técnica: es de protección de la actitud, que es la variable de entrada del sistema.**\\n\\n**Caso:** un manager ve que su vendedor presenta mucho y cierra poco, y quiere saber qué corregir.\\n**Razonamiento:** el indicador señala una zona, no una causa. Puede ser el cierre, pero también un descubrimiento que no encontró el dolor real, CPR insuficiente, o una presentación que se alargó y cayó en KILL. **Números + conversación observada.** Pídele una práctica o acompáñalo en campo antes de concluir.\\n\\n## Sobre la incertidumbre\\nEste documento tiene procedencia marcada por una razón: **lo que está como `CAMPO` no se puede verificar contra la fuente.** Si un caso depende de doctrina `CAMPO` y hay duda, la autoridad es Emilio, no la inferencia.\\n\\n**Nunca completes un hueco de doctrina inventando.** Di qué falta y pídelo.\\n\\n**Y nunca inventes un hecho comercial** — una ventaja, una comparación con la competencia, un dato de mercado. Eso no es doctrina: es información de la empresa, y si no está en su contexto, se pide.","is_active":false,"created_at":"2026-09-25T20:26:45.879837+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"affe1105-551b-42d8-a48a-f1ea16d9350e","version":3,"section_key":"fundamento","order_index":1,"title":"PARTE 1 · EL FUNDAMENTO","body":"# EL CEREBRO DE CLOSER\\n## Doctrina canónica del sistema de venta\\n\\n*Versión 1.0 · Fuente única de verdad*\\n\\n---\\n\\n## CÓMO USAR ESTE DOCUMENTO\\n\\nEsto no es un manual ni un resumen. Es el entendimiento del sistema, escrito para que se pueda **razonar** con él.\\n\\nCada técnica se presenta con tres cosas: **qué es**, **por qué funciona** (el mecanismo humano detrás) y **qué la rompe**. El porqué importa más que el qué, porque de él se deducen los casos que ninguna lista cubre.\\n\\nEjemplo de la diferencia: una lista diría *\\"no digas «¿cómo lo ves?»\\"*. Este documento dice *\\"toda pregunta que permita aprobar o posponer le entrega el control al cliente\\"* — de donde se deduce que *\\"¿le late?\\"*, *\\"¿qué opina?\\"* y *\\"¿le parece?\\"* también están mal, aunque nadie los haya escrito nunca.\\n\\n**Regla de razonamiento:** ante un caso que este documento no cubre explícitamente, no inventes. Busca el principio que aplica y dedúcelo. Si dos principios chocan, gana el de mayor jerarquía (ver Parte 6).\\n\\n### Etiquetas\\n\\n**PROCEDENCIA** — `FUENTE` (sistema original Credico/Cydcor) · `CAMPO` (evolución de Emilio Fanjul) · `CLOSER` (andamiaje pedagógico)\\n\\n**CANAL** — `PRESENCIAL` (requiere cuerpo o presencia) · `UNIVERSAL` (funciona en persona, teléfono, mensaje o correo)\\n\\n---\\n\\n---\\n\\n# PARTE 1 · EL FUNDAMENTO\\n\\n## 1.1 El problema que resuelve todo el sistema `FUENTE`\\n\\nCuando abres una conversación con un desconocido, **su atención está dividida en tres**:\\n\\n- **Un tercio** sigue en lo que estaba haciendo\\n- **Un tercio** está resolviendo preguntas básicas: quién eres, qué quieres, por qué me hablas\\n- **Solo un tercio** está disponible para ti\\n\\n> **De aquí sale la razón de ser de los 6 pasos:** si vas directo a presentar, le estás hablando a un tercio de una persona. Cada paso previo existe para recuperar una porción de esa atención.\\n\\nLa Introducción libera el primer tercio (deja de pensar en lo que hacía). La Historia Breve libera el segundo (ya sabe quién eres y a qué vienes). Solo entonces tienes casi toda su atención — y solo entonces vale la pena presentar.\\n\\n**Esto explica por qué saltarse pasos no acelera nada: presentarle a alguien distraído es desperdiciar tu mejor material.**\\n\\n## 1.2 La Línea Recta `CAMPO` `UNIVERSAL`\\n\\nUna venta avanza en línea recta, de izquierda a derecha, a través de los 6 pasos.\\n\\n**Nada te regresa. Lo que ya recorriste, quedó.** Lo único que puede pasar es que algo te **saque de la línea y te pause**.\\n\\nLa imagen: vas dibujando la línea hacia la derecha y de pronto llega una objeción. Ahí dejas de avanzar y la línea sube — saliste. Pero no retrocede. Está en ti resolver y volver al punto donde ibas.\\n\\n| Elemento | Relación con la línea |\\n|---|---|\\n| Los 6 pasos | La línea misma |\\n| CPR / FORMS | Salida **deliberada** — sales tú, y regresas |\\n| Bloqueos → AIR, Ataque Preventivo | Salida **impuesta** al inicio |\\n| Objeciones → RRR, FFF | Salida **impuesta** después de entender |\\n| Close With Action | Lo que te devuelve y te mueve al siguiente tramo |\\n| Los 3 No seguidos | La señal de que ya no hay línea que recorrer |\\n\\n**Diagnóstico que le da al vendedor:** cuando una visita sale mal, la pregunta no es *\\"¿qué técnica olvidé?\\"* sino **\\"¿dónde salí de la línea y por qué no regresé?\\"**\\n\\n## 1.3 El principio de la balanza `FUENTE` `UNIVERSAL`\\n\\nNadie compra por precio. Compra cuando el **valor percibido** pesa más que el **costo percibido**. Cuanto mayor la brecha, mayor el impulso.\\n\\nY el costo no es solo dinero: es tiempo, riesgo de cambiar, esfuerzo, y la posibilidad de haberse equivocado.\\n\\n> **La regla que convierte esto en herramienta:** con cada frase, cada gesto y cada silencio estás haciendo una de cuatro cosas — subiendo el valor, bajándolo, subiendo el costo, o bajándolo.\\n>\\n> **No hay frases neutras.**\\n\\nDe aquí se deducen cosas que ninguna lista de reglas contiene:\\n- Titubear al dar un precio sube el costo percibido\\n- Disculparte baja tu valor\\n- Mencionar algo que **no** tienes, no aplica o no está disponible **baja el valor sin que nadie te lo pidiera** — y por eso se omite\\n- Contar un caso real de otro cliente sube el valor\\n\\n**Cost vs Value no es tanto una habilidad como una herramienta de evaluación:** revisa cada parte de tu conversación y pregúntate qué plato movió.\\n\\n## 1.4 La gente compra, pero no quiere que le vendan `FUENTE`\\n\\nEste es el principio psicológico que atraviesa todo el sistema.\\n\\nA las personas les gusta comprar. Lo que les desagrada es **sentir que les están vendiendo**. Tienen una alarma calibrada para detectar al vendedor, y en cuanto se activa, todo lo que digas después se procesa con desconfianza.\\n\\n> **Casi todas las técnicas de este sistema son formas de obtener un resultado de venta sin activar esa alarma.**\\n\\n- **Gasman** — pedir permiso te delata como forastero; asumir que perteneces no dispara nada\\n- **CPR** — ser persona antes que vendedor\\n- **Descubrimiento** — el vendedor promedio habla; el que pregunta rompe el patrón que la alarma busca\\n- **Close With Action** — nunca pides el sí, porque pedirlo enciende la alarma\\n- **Indiferencia** — la presión genera resistencia; quitarla la disuelve\\n- **FFF** — estar de acuerdo primero te vuelve distinto del vendedor promedio, *y por eso te escuchan*\\n\\n## 1.5 La decisión es emocional antes que racional `CAMPO`\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente siente algo primero, y después construye la razón que lo justifica.\\n\\nEsto no contradice el diagnóstico ni la construcción de valor: los explica. La doctrina fuente lo dice sin rodeos — **\\"el impulso es otra palabra para la emoción\\"**.\\n\\n**Lo que se deduce de aquí, y que corrige el error de modelar la venta como un proceso lógico:**\\n\\n- **El cliente no necesita reconocer un problema para sentir el alivio de resolverlo.** Por eso \\"pintar imágenes\\" funciona: no argumenta, hace sentir.\\n- **Pelear por el reconocimiento explícito mata la venta.** Insistir en que admita algo lo pone a la defensiva, y la defensiva apaga lo emocional — que era donde estaba la venta.\\n- **El 80% indiferente no tiene un problema urgente**, y aun así compra. Se mueve por los factores de impulso, no por el diagnóstico.\\n- **Un argumento perfecto dicho por alguien en quien no confía, no pesa.** Y uno mediocre dicho por alguien cercano, sí. De ahí la importancia real del CPR.\\n\\n> **La regla operativa:** el sistema construye una situación deseable, no un caso lógico. La razón sirve para que el cliente pueda **justificar** la decisión — no para que la tome.\\n\\n⚠️ **Y esto no autoriza a manipular.** El Nivel 1 sigue intacto: el impulso se construye con verdad. La diferencia es que construir una imagen real y deseable es legítimo; fabricar urgencia, escasez o problemas no lo es.\\n\\n---","is_active":false,"created_at":"2026-09-26T18:59:04.141328+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"0c9eb4ca-a21a-444a-9c3a-b1a488c796e5","version":3,"section_key":"pasos","order_index":2,"title":"PARTE 2 · LOS 6 PASOS","body":"# PARTE 2 · LOS 6 PASOS\\n\\nEl sistema original tiene **5 pasos** `FUENTE`: Introducción, Historia Breve, Presentación, Cierre, Consolidación.\\n\\nCloser enseña **6** `CAMPO`: se separa **Descubrimiento** como paso propio. En la fuente las preguntas de calificación viven dentro del flujo; separarlas reconoce que diagnosticar y presentar son habilidades distintas que fallan por razones distintas.\\n\\n---\\n\\n## PASO 1 · INTRODUCCIÓN\\n### *Una sola oportunidad para una primera impresión*\\n\\n**Qué logra:** liberar el primer tercio de atención y ganarte el derecho a seguir hablando.\\n\\n**Qué NO es:** aquí no dices quién eres ni a qué vienes. Eso es el Paso 2. Confundirlos es el error doctrinal más común.\\n\\n### SEE / SCE `FUENTE` `PRESENCIAL`\\n**S**mile · **E**ye contact · **E**nthusiasm — Sonrisa, Contacto visual, Entusiasmo\\n\\n- **Sonrisa** — signo internacional de amistad. Elimina el miedo y crea confianza.\\n- **Contacto visual** — genera confianza, mantiene el control de la conversación, **y es una señal de compra fuerte cuando el cliente lo hace**.\\n- **Entusiasmo** — crea impulso y curiosidad. Si estás emocionado, asumen que hablas de algo emocionante. **Y al revés también funciona:** si suenas aburrido de tu producto, nadie va a estar más emocionado que tú.\\n\\nSe combinan con **lenguaje corporal abierto** y **tono de voz fuerte**.\\n\\n> ⚠️ **Límite de canal:** SEE es físico. En texto o voz no se puede evaluar. Se enseña, se pide, y se marca como *\\"esto se practica en persona\\"*. Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**.\\n\\n### Regla del 10% `FUENTE` `PRESENCIAL`\\nLee el nivel de emoción del cliente y ponte **10% por encima** de él. No al doble: 10%.\\n\\n**Por qué:** llegar gritando con alguien tranquilo lo aleja tanto como llegar apagado con alguien entusiasmado. El 10% jala sin romper.\\n\\n### Ice Breaker `FUENTE` `UNIVERSAL`\\nCumplido genuino, chiste sencillo o comentario ligero.\\n\\nPuede ser sobre **la persona**, **el lugar**, o **algo en común**. No está atado a ningún tipo de negocio.\\n\\n**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee al instante y se cierra **más** que antes — porque ahora sabe que le están aplicando una técnica.\\n\\n### La escalera de la especificidad `CAMPO` `UNIVERSAL`\\n\\nLa observación y la pregunta de la apertura se miden igual: **¿se la harías a cualquiera?** Entre más específica para ESE cliente en ESE momento, más vale.\\n\\n- **Escalón 1 — de cortesía.** Se la harías a cualquiera: *\\"¿cómo está?\\"*, *\\"qué gusto saludarlo\\"*. Cumple lo mínimo porque le devuelve la palabra, pero no construye nada.\\n- **Escalón 2 — del entorno.** Sale de lo que ves ahí, en ese momento: *\\"veo que no paran, ¿siempre está así de movido?\\"*. Solo tiene sentido en ese lugar.\\n- **Escalón 3 — de él.** Solo se la harías a él, porque sabes algo de antes: *\\"¿cómo sigue? ¿va mejorando?\\"*.\\n\\n> **Las mismas palabras pueden estar en escalones distintos.** *\\"¿Cómo está?\\"* a secas es escalón 1; *\\"¿cómo está? ¿va mejorando?\\"* a alguien que estuvo enfermo es escalón 3. Lo que sube el escalón no son las palabras: es qué tanto sabe la pregunta de él.\\n\\n**La relación cambia la escalera.** Con un cliente nuevo no existe el escalón 3 —no hay historia con él—, así que el escalón 2 es la excelencia. Con un recurrente la meta es el escalón 3, y el 2 puede ser un error: preguntarle si siempre está así de movido a alguien que visitas desde hace años le dice que no lo tienes presente (ver 4.1b).\\n\\n**Una pregunta de cortesía no es una falla: es el primer escalón.** La falla es no preguntar nada: sin ninguna pregunta, el cliente no tiene qué contestar y la conversación se muere ahí.\\n\\n**Y la pregunta que mejor devuelve la palabra es la que sale de la observación y cierra la apertura:** *\\"veo que no paran, ¿siempre está así de movido?\\"*. Un *\\"¿cómo está?\\"* dentro del saludo cumple, pero si después sigues hablando, el cliente espera a que termines en vez de contestar. Convertir la observación en la pregunta final es como se sube de escalón.\\n\\n### Especificidad y ligereza son dos cosas distintas `CAMPO` `UNIVERSAL`\\n\\nUn comentario de apertura se mide con dos preguntas diferentes. **¿Se lo dirías a cualquiera?** es la especificidad: la escalera. **¿Baja la guardia?** es la ligereza: humor suave, un guiño o calidez en lo que dices.\\n\\nUna no garantiza la otra. *\\"Veo que tiene cuatro cajas de filtros de una marca y dos de otra\\"* es muy específico, y suena a inspección. *\\"¡Qué buen día hace, eh!\\"* es ligero, y se lo dirías a cualquiera. *\\"¿Qué les pasó hoy que está lleno? ¿Regalan algo o qué?\\"* tiene las dos.\\n\\n**La ligereza se mide en lo que haces, no en cómo reacciona el cliente.** Un buen chiste puede no hacerle gracia a un cliente rojo, o a alguien que viene enojado ese día, y no por eso se hizo mal. La reacción del cliente puede confirmar que algo funcionó; nunca puede condenar una acción bien hecha. Es la lógica de los controlables: al vendedor se le mide por lo que controla, y el humor del cliente no es una de esas cosas.\\n\\nLa calidez que vive en el tono de voz no se puede calificar por escrito: se enseña igual, se practica igual, y la escucha el manager (ver 1.7).\\n\\n### Teoría del Gasman `FUENTE` `UNIVERSAL`\\nSer asumido y confiado, con alta indiferencia.\\n\\nEl gasista que viene a leer tu medidor entra con una autoridad que nace de sentir que **debe estar ahí** — no es una intrusión. Nadie lo detiene, y no es por su permiso: es por su postura.\\n\\n> **El mecanismo:** cuando preguntas *\\"¿tiene un minutito?\\"* haces dos cosas a la vez — le entregas el control, y le ofreces una salida que no le cuesta nada tomar. El cliente que dice \\"ahorita no\\" no está siendo grosero: tomó la puerta que le abriste.\\n>\\n> **La autoridad no se pide. Se asume.**\\n\\n### Regla doctrinal del paso `CAMPO`\\n**La identificación (nombre y empresa) es permitida pero nunca requerida aquí.** Su ausencia jamás se penaliza.\\n\\nSi el cliente pregunta *\\"¿y usted quién es?\\"*, **ganaste la introducción** — esa pregunta es la puerta natural al Paso 2, no una falla.\\n\\n---\\n\\n## PASO 2 · HISTORIA BREVE\\n### *Explica tu propósito de manera concisa*\\n\\n**Qué logra:** liberar el segundo tercio de atención. El cliente deja de preguntarse quién eres y qué quieres.\\n\\n### KISS vs KILL `FUENTE` `UNIVERSAL`\\n**K**eep **I**t **S**hort and **S**imple — contra **K**eep **I**t **L**ong and **L**engthy.\\n\\nQuién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible.\\n\\n> **El mecanismo:** cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él — y de los discursos uno se defiende.\\n\\n**Y después de la historia, preguntas.** La fuente es explícita: *\\"en la mayoría de los casos es más efectivo pasar directamente a las preguntas de calificación que dar una larga explicación.\\"*\\n\\nTu historia breve no existe para que te entiendan a ti. **Existe para ganarte el derecho de preguntarle a él.**\\n\\n### CPR — Create Personal Relations `FUENTE` `UNIVERSAL`\\n> *\\"Eres tanto, si no más, el producto que los productos que representas.\\"*\\n\\n**Se aplica durante TODA la conversación**, no en un paso.\\n\\n**El mecanismo:** el cliente no puede evaluar tu producto todavía — no lo ha probado, no conoce tu empresa, no sabe si le van a cumplir. Lo único que sí puede evaluar desde el primer segundo **eres tú**. Y esa evaluación la hace mucho antes que la otra.\\n\\n**Y hace dos trabajos distintos, ambos indispensables:**\\n\\n**1 · Que te contesten de verdad.** Sin relación, las preguntas del Paso 3 reciben respuestas de cortesía. A un desconocido nadie le cuenta lo que le está fallando.\\n\\n**2 · Que te crean.** Este es el más importante y el que casi nadie ve.\\n\\n> Si un amigo te dice que un producto es bueno, le crees. Si te lo dice alguien que gana comisión por vendértelo, lo descuentas automáticamente — no porque lo creas mentiroso, sino porque sabes que tiene interés.\\n>\\n> **Es la misma frase, dicha por dos personas, y produce dos efectos opuestos.**\\n\\nLo que decide cuál de los dos efectos produces **no es tu argumento: es qué tan cerca estás de ser alguien en quien confía.** Por eso el CPR no es cortesía ni relleno — **es lo que determina si tus argumentos pesan o se descuentan.**\\n\\nY conecta directo con el Efecto Jones: la gente no confía en un desconocido incentivado a vender, pero sí deja que gente cercana valide un producto. **El CPR te acerca a ese lado de la línea.**\\n\\n### FORMS `FUENTE` `UNIVERSAL`\\n**F**amily · **O**ccupation · **R**ecreation · **M**otivation · **S**ports\\n\\nLos cinco caminos a la persona. Más cumplidos genuinos y chistes sencillos.\\n\\n> **La palabra que lo decide todo es *genuinos*.** Un interés fingido se nota, y cuesta más que no haber preguntado — porque ahora el cliente sabe que le aplicaste una técnica. Si un tema no te interesa de verdad, busca otro de los cinco.\\n\\n**No requiere cierta personalidad ni ser naturalmente extrovertido: se aprende.**\\n\\n### El desvío con regreso `CAMPO` `UNIVERSAL`\\nLa mecánica que hace que el CPR no mate la venta.\\n\\nSales de la línea a propósito, das **uno o dos intercambios personales**, y **regresas**. Puedes volver a salir más adelante, pero siempre avanzando.\\n\\n**Dos errores, ambos caros:**\\n- **Nunca salir** → no hay relación, y no te van a contestar nada en el Paso 3\\n- **Salir y no regresar** → el cliente se acomoda a platicar y la venta se estanca\\n\\n> **El cliente NUNCA te va a regresar a la línea.** Cuando la plática se pone agradable, él está cómodo — nadie interrumpe una conversación agradable para hablar de negocios. El único que puede regresar eres tú.\\n\\n### Bloqueo vs Objeción `FUENTE` — *la distinción que organiza todo el manejo de resistencia*\\n\\n**BLOQUEO** — un reflejo. Llega **ANTES** de entender.\\n*\\"No tengo tiempo\\" · \\"No me interesa\\" · \\"No estoy comprando nada\\" · \\"Ya tengo con quién\\"*\\nNo hubo procesamiento. Es la puerta cerrándose sola.\\n\\n**OBJECIÓN** — una preocupación razonada. Llega **DESPUÉS** de entender.\\n*\\"Está caro\\" · \\"Ya tengo proveedor y me cumple\\" · \\"Lo tengo que consultar\\"*\\nAquí sí hubo pensamiento.\\n\\n> **Por qué importa la diferencia:** discutir con un reflejo lo convierte en una posición. El cliente dijo \\"no me interesa\\" sin pensarlo; si lo peleas, tiene que defenderlo — y al defenderlo se lo cree. **Le acabas de crear un \\"no\\" real que no tenía.**\\n>\\n> E ignorar una objeción real ofende a alguien que sí te escuchó y sí pensó.\\n>\\n> **La misma frase se maneja de dos maneras opuestas según cuándo llegó.**\\n\\n### AIR `FUENTE` `UNIVERSAL`\\n**A**gree · **I**gnore · **R**esume — Acepta, Ignora, Resume\\n**Cuándo:** bloqueos al inicio.\\n**Cómo:** reconoce con *\\"entiendo\\"* o *\\"por supuesto\\"*, no lo discutas, y continúa.\\n\\n> **El tercer movimiento es el que falla.** Casi todos aceptan bien y casi todos logran no discutir — y después se quedan parados esperando, o peor, vuelven a pedir permiso. Ahí se pierde todo lo ganado.\\n\\n### Ataque Preventivo `FUENTE` `UNIVERSAL`\\n**Cuándo:** intro o historia breve, si hay negativos comunes del territorio.\\n**Cómo:** *\\"si das la negativa antes de que el cliente lo haga, ya no es una negativa.\\"*\\n\\n**El mecanismo:** le quitas el argumento de las manos, y además te vuelves creíble — **quien reconoce lo malo se gana el derecho a que le crean lo bueno.**\\n\\n**Dos formas de arruinarlo:**\\n- **En tono de disculpa** → deja de ser adelantarse y se vuelve defenderse de algo que nadie reclamó\\n- **Con un negativo inventado** → no desactivas nada, plantas una preocupación nueva\\n\\n### Close With Action `FUENTE (dentro de FFF) + CAMPO (generalizado)` `UNIVERSAL`\\n**Es el Poder de Sugestión en ejecución.**\\n\\nUna pregunta o acción cuya respuesta **solo tiene sentido si el cliente está avanzando**. Su respuesta *es* el sí. Nunca lo pides explícito.\\n\\n- *\\"¿Cómo se escribe su apellido?\\"* → al contestar, aceptó tu respuesta y sigue en el alta\\n- *\\"¿Prefiere el jueves o el viernes?\\"* → *\\"el viernes\\"* significa que lo quiere **y** cuándo\\n\\n**Se ejecuta en cada tramo de la línea:** en descubrimiento es la siguiente pregunta; en presentación es continuar donde ibas; en cierre es la alternativa de sí/sí.\\n\\n> **El momento crítico:** justo después de resolver algo. El vendedor promedio se queda callado esperando permiso para seguir. En ese silencio el cliente retoma el control y cierra la conversación con amabilidad. **No te está rechazando: le devolviste el volante.**\\n\\n---\\n\\n## PASO 3 · DESCUBRIMIENTO `CAMPO`\\n### *Encontrar el dolor real*\\n\\n*No existe como paso en la fuente. Toda esta sección es construcción de Closer sobre el principio de \\"preguntas de calificación\\".*\\n\\n### El principio rector\\n**Primero el examen, luego la receta.** El vendedor promedio llega a recetar: trae su producto favorito buscando dónde encajarlo. El Closer llega a diagnosticar.\\n\\n**La ironía:** el que pregunta vende más que el que habla.\\n\\n### RRR — Read, Relate, Relax `FUENTE` `UNIVERSAL`\\nLee · Conecta · Relaja.\\n\\nTres cosas que leer: **el ambiente, la demografía de la persona, y su estado de ánimo.**\\n\\n**El mecanismo:** no quieres forzar a nadie a subir a tu nivel de emoción ni a adaptarse a ti. **Tú te adaptas primero.**\\n\\n> ⚠️ **Colisión de acrónimos:** existe un segundo RRR en la doctrina (Repeat, Reassure, Resume) para objeciones. Ambos se conservan con su nombre original. Al enseñar el segundo hay que advertirlo explícitamente.\\n\\n### Los 3 Territorios del Dolor `CLOSER` `UNIVERSAL`\\nTodo dolor comercial vive en uno de tres territorios:\\n\\n- **PRODUCTO** — lo que vende o usa\\n- **SERVICIO** — cómo lo trata su proveedor actual\\n- **PRECIO** — lo que paga y lo que gana\\n\\n> **El mismo territorio se pregunta distinto según el tipo de cliente.** Ver Parte 4.\\n\\n#### Cómo se investiga el territorio PRECIO `CAMPO`\\n\\nEl territorio PRECIO es el más fácil de arruinar, porque la pregunta natural es la incorrecta.\\n\\n⚠️ **NUNCA le pidas al cliente su opinión ni su aprobación sobre precios.** Prohibido: *\\"¿cómo ve los precios?\\"*, *\\"¿hay algo que sienta muy arriba?\\"*, *\\"¿le parece competitivo?\\"*, *\\"¿estoy bien de precio?\\"*\\n\\n**Tres razones, y cada una basta:**\\n\\n**1. Le pides que construya una posición sobre tu precio antes de que exista valor.** Si contesta *\\"están caros\\"*, ya no es una impresión: es algo que declaró en voz alta y ahora tiene que defender. **Te creaste una objeción de precio que no existía.**\\n\\n**2. Cedes la autoridad sobre el precio.** El precio no lo determina la percepción del cliente: lo determina lo que ofreces. Preguntarle su opinión comunica que estás dispuesto a moverlo según lo que conteste, y te vuelve regateable antes de haber presentado nada.\\n\\n**3. Renuncias a tu ventaja.** Tú conoces el mercado: ya sabes qué está caro y qué está barato. **Muchas veces el cliente no sabe que está pagando de más, y tú sí.** Preguntarle su opinión te iguala a alguien que no sabe, cuando saber es exactamente lo que te hace valioso.\\n\\n**Lo que sí se investiga en este territorio son HECHOS, no opiniones:**\\n\\n- ¿A cómo compra hoy? (dato)\\n- ¿Cada cuánto le suben? ¿Le avisan antes? (dato)\\n- ¿Le manejan crédito o de contado? ¿Qué plazo? (dato)\\n- ¿Cuánto le queda de margen en esa línea? (dato)\\n- ¿Le ha tocado que un cliente se le vaya por precio? (experiencia, no opinión)\\n\\n**La diferencia:** un hecho te da información que puedes usar. Una opinión sobre tu precio te da una objeción que tendrás que atravesar.\\n\\n> **Y si el cliente dice que tu precio está mal, el diagnóstico correcto no es bajarlo.** Es que no encontraste su dolor, o no construiste suficiente valor. **El problema nunca está en el número: está en la balanza.**\\n\\n### La Escalera de Capas `CLOSER` `UNIVERSAL`\\n**CAPA 1 — Hechos.** Fáciles, cero riesgo. Abren la plática y te dan el mapa.\\n**CAPA 2 — La puerta.** Aquí el cliente suelta una pista... o cierra con un \\"bien\\". Depende de cómo preguntes.\\n**CAPA 3 — El dolor.** Solo se abre si recoges la pista y profundizas con preguntas abiertas.\\n\\n### La Pregunta Específica `CAMPO` `UNIVERSAL`\\n> **El \\"bien\\" no es información: es un reflejo social.**\\n\\nCuando preguntas *\\"¿qué tal le va?\\"*, el cliente no consulta su experiencia — dispara la respuesta cortés que trae cargada. Y admitir un problema ante un desconocido tiene costo social: parece queja, o parece que eligió mal.\\n\\n**La solución tiene dos formas:**\\n- **ESPECÍFICA** — nombra un dato o situación concreta que tenga que ir a buscar. *\\"¿Le ha tocado quedarse sin su producto estrella?\\"*\\n- **NORMALIZADA** — da permiso citando a otros. *\\"Varios clientes me comentan que batallan con faltantes, ¿a usted le pasa?\\"* (Es el Efecto Jones aplicado a descubrimiento.)\\n\\n**Y el orden importa:** concreta para **abrir** (capa 2), abierta para **excavar** (capa 3).\\n\\n#### Suggestive Language — dale de dónde agarrarse `FUENTE` `UNIVERSAL`\\n\\nEs la S de FUJIES aplicada al descubrimiento, y es lo que convierte una pregunta que se muere en una que da información.\\n\\n**El problema de la pregunta abierta sola:** obliga al cliente a construir la respuesta desde cero. Eso cuesta esfuerzo, y como no le urge ayudarte, contesta lo más corto que puede — o de plano *\\"pues no sé\\"*.\\n\\n**La solución: después de preguntar, sugiere opciones.**\\n\\n> *\\"¿Qué familias son las que más se te mueven? ¿Anticongelantes? ¿Aceite de motor? ¿Diésel? ¿Moto?\\"*\\n>\\n> *\\"¿A cómo compras el líquido de frenos? ¿70? ¿80? ¿90?\\"*\\n\\n**Por qué funciona, y son tres cosas a la vez:**\\n\\n1. **Le das de dónde agarrarse.** O elige una de tus opciones, o te corrige con el dato real — *\\"no, más bien 95\\"*. **Y esa corrección es información que la pregunta abierta nunca habría sacado.**\\n\\n2. **Le demuestras que conoces su negocio.** Nombrar las familias correctas o el rango de precio correcto te posiciona como alguien que sabe, no como alguien que está averiguando.\\n\\n3. **Crea un poco de urgencia.** Una pregunta con opciones se contesta rápido; una abierta se puede posponer con un *\\"déjame ver\\"*.\\n\\n**Cómo se usa bien:**\\n- Las opciones tienen que ser **reales y del giro del cliente**. Si sugieres familias que él no maneja, demuestras lo contrario de lo que buscabas.\\n- **Tres o cuatro, no una lista.** Es para ayudarlo a contestar, no para que elija de un catálogo.\\n- El rango de precio **tiene que ser creíble.** Sugerir cifras muy lejanas de la realidad te desacredita.\\n- Y **no lo uses para plantar una respuesta.** Si el cliente te corrige, esa es la respuesta buena — no insistas en la tuya.\\n\\n> **Es la misma lógica del cierre de alternativa, aplicada al descubrimiento:** no preguntas al aire, das opciones donde cualquier respuesta te sirve.\\n\\n### El Barrido `CLOSER` `UNIVERSAL`\\nTerritorio limpio → ni insistas ni te rindas: **cambia de territorio.**\\n\\nEl dolor casi siempre existe, solo que vive en otra zona del mapa. Insistir en zona sana te vuelve interrogador; rendirte regala la visita.\\n\\n### El dolor y la confirmación `CLOSER` `UNIVERSAL`\\nCuando el dolor aparece, **devuélveselo con SUS palabras**. *\\"Entonces lo que más le pega es X, ¿cierto?\\"*\\n\\nEso hace dos cosas: confirma que entendiste, y **le da forma consciente a algo que a lo mejor solo sentía.**\\n\\n> ⚠️ **Pero la confirmación explícita no es requisito para avanzar.**\\n>\\n> Muchas veces el cliente no va a admitir el problema. No porque no lo tenga — sino porque admitirlo suena a queja, o a que eligió mal, o simplemente porque **no lo tiene consciente**. Nadie anda por la vida con una lista de sus problemas operativos.\\n>\\n> Y aun así te sigue escuchando. **Eso ya es información.**\\n\\n**Lo que sí necesitas** es haber leído el problema con evidencia suficiente: algo que dijo, algo que viste, algo que su tipo de negocio hace probable. **Lo que no necesitas es su permiso verbal.**\\n\\n### La venta es emocional antes que racional `CAMPO`\\n\\nEste es el principio que corrige el error de modelar la venta como un proceso lógico.\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente no llena una hoja de cálculo: siente algo, y después construye la razón.\\n\\nConsecuencias que cambian cómo se ejecuta todo el sistema:\\n\\n- **Un cliente puede no reconocer un problema y aun así sentir alivio cuando se lo resuelves.** El impulso no viene de que aceptó el diagnóstico: viene de imaginar la situación resuelta.\\n- **Por eso \\"pintar imágenes\\" funciona** — no argumenta, hace sentir.\\n- **Por eso el vendedor no debe pelear por el reconocimiento explícito.** Insistir en que el cliente admita un problema lo pone a la defensiva y mata lo emocional, que era donde estaba la venta.\\n- **Y por eso el impulso se puede construir sin que haya un dolor declarado.** El 80% indiferente no tiene un problema urgente: se mueve por los factores de impulso, no por el diagnóstico.\\n\\n**La regla operativa:** si el cliente confirma el dolor, úsalo con sus palabras — es lo más fuerte que tienes. **Si no lo confirma pero la evidencia está, avanza igual**, presentando la situación resuelta en vez del problema reconocido.\\n\\n⚠️ **Lo que sigue prohibido es fabricar.** Leer un dolor probable no es inventarlo. La diferencia: leer se apoya en evidencia real — algo que dijo, algo que viste, algo propio de su giro. Fabricar es afirmar un problema **que el cliente ya negó** o del que no hay ningún indicio.\\n\\n### La regla del investigador\\n**El dolor nunca se pregunta directo.** *\\"¿Qué problemas tiene?\\"* produce *\\"ninguno\\"*, garantizado. Se deja emerger.\\n\\n### Luz Verde — 10/80/10 `FUENTE` `UNIVERSAL`\\n**10% negativos · 80% indiferentes · 10% positivos.**\\n\\n1. Sal de las luces rojas **rápido y educadamente**\\n2. Las amarillas reciben tu mejor presentación — pero si no dan señales de compra, muévete\\n3. Las verdes reciben tiempo, relación y resolución de dudas\\n\\n**Los factores de impulso existen principalmente para convertir al 80% indiferente.**\\n\\n#### El rojo verdadero y el que quiere pero no puede `CAMPO`\\n\\nLa luz roja no es cualquier \\"no\\". Es un tipo específico de cliente, y confundirlo cuesta ventas.\\n\\n**ROJO GENUINO** — no quiere. Es cortante, tajante, desganado. Muchas veces medio grosero. Y tiene un costo escondido: **interactuar de más con él desgasta tu actitud**, que es la variable de entrada de todo tu sistema. Con este, salir rápido y bien es la ejecución correcta.\\n\\n**AMARRADO TEMPORALMENTE** — quiere y no puede. Te recibe con gusto, te habla con honestidad, y su impedimento es una **circunstancia que va a cambiar**: un contrato de exclusividad, un inventario recién surtido, un presupuesto agotado, no ser él quien decide las compras grandes.\\n\\n> **Este no es rojo: es verde amarrado.** Y con él, rendirse es la falla más cara del oficio — porque ese cliente sí quería comprarte y el vendedor se fue solo.\\n\\n**Cómo se distinguen:** el rojo se nota en el trato. Es seco, no da información, quiere que te vayas. El amarrado hace lo contrario: es amable, te explica su situación con detalle, y muchas veces se disculpa por no poder.\\n\\n#### Casi toda restricción tiene bordes `CAMPO`\\n\\nY aquí está la mecánica que separa al vendedor promedio del que crece cuentas.\\n\\nCuando un cliente dice que no puede, **el promedio lo toma como total y se va**. El Closer investiga hasta dónde llega:\\n\\n- **¿Qué cubre exactamente?** Una exclusividad casi nunca abarca todas las familias\\n- **¿Qué queda fuera?** Ahí está la venta que la competencia no vio\\n- **¿Hasta cuándo dura?** Para volver justo cuando se libere, antes que nadie\\n\\n> Un contrato que cubre lubricantes, anticongelantes y grasas **deja fuera el líquido de frenos.** Y el vendedor que preguntó se lleva una venta de un cliente que \\"no podía comprar\\".\\n\\n**Y la relación sigue construyéndose mientras tanto.** Seguir visitando a un amarrado no es perder el tiempo: es estar presente el día que la restricción se acabe. El que se rindió no va a estar ahí.\\n\\n⚠️ **La línea:** investigar los bordes no es presionar. Si el cliente ya dijo que algo está dentro de su compromiso, insistir en eso es pedirle que rompa su palabra — y eso quema la relación. Se busca lo que **sí** puede, nunca se pelea lo que no.\\n\\n### QTQP `FUENTE` `UNIVERSAL`\\n**Q**uality **T**ime with **Q**uality **P**eople.\\n\\n> *\\"Perder tiempo y energía con las personas equivocadas destruye tu capacidad de ser lo suficientemente urgente\\"* — y la urgencia es de lo que vive tu ley de promedios.\\n\\nCada minuto con un rojo se lo quitas a un amarillo que sí podía comprar hoy.\\n\\n---\\n\\n## PASO 4 · PRESENTACIÓN\\n### *Construye valor y disminuye el costo*\\n\\n**Qué logra:** convertir el dolor descubierto en valor percibido, y subir el impulso.\\n\\n### Las herramientas de la presentación `FUENTE`\\n1. Encontrar problemas y proporcionar soluciones\\n2. **Pintar imágenes** — que imaginen que ya lo tienen\\n3. Incorporar factores de impulso\\n4. **Triple desglose de precios**\\n5. Hacer el valor enorme: lenguaje expansivo, *\\"gran\\"*, *\\"masivo\\"* `PRESENCIAL`\\n6. Hacer el costo pequeño: *\\"solo\\"*, *\\"apenas\\"* `PRESENCIAL`\\n7. **Tren del Sí** — preguntas cuya respuesta natural es sí\\n8. **CPR sostenido** durante toda la presentación\\n\\n### Beneficio, no característica `CLOSER` `UNIVERSAL`\\nUna característica es lo que el producto **es**. Nadie compra lo que algo es: compran **lo que van a ganar**.\\n\\nToda característica se traduce a una de tres cosas: **dinero** (gana más o gasta menos), **clientes** (vende más o los conserva), o **tranquilidad** (menos problemas, menos tiempo perdido).\\n\\n> Si el cliente puede contestar *\\"¿y eso a mí de qué me sirve?\\"*, la traducción falló.\\n\\n### Teoría de las Balas `FUENTE` `UNIVERSAL`\\n> *\\"La persona con más balas claramente tiene el control, siempre y cuando conserve su munición.\\"*\\n\\n**Las balas son TUYAS.** Son hechos positivos y concretos sobre:\\n- **Ti / tu empresa** — experiencia, premios, casos de éxito, dedicación\\n- **El producto** — lo que lo diferencia, mejoras, datos, certificaciones\\n- **El precio** — propuesta de valor, descuentos, financiamiento, comparación\\n\\n**La prueba de si algo es bala:** si la competencia puede decir exactamente lo mismo, no era bala. *\\"Somos los mejores\\"* es aire; *\\"catorce años surtiendo esta zona sin fallar\\"* es bala.\\n\\n**La regla de dosificación:** *\\"no dispares todas las balas al principio. Reserva algunas para que no importe cuántas balas tenga tu cliente, tengas más con qué responder. Guarda balas para los pasos 4 y 5.\\"*\\n\\n> **Por qué se guardan:** más adelante el cliente va a poner razones para no comprar. Eso baja su impulso. Responderle bien solo **detiene la caída** — lo que vuelve a subirlo es **una bala nueva**. Si las gastaste presumiendo al principio, llegas a ese momento con la mano vacía.\\n\\n### FUJIES / FUJPIG — Factores de Impulso `FUENTE`\\n*\\"El impulso es otra palabra para la emoción.\\"*\\n\\n| | Factor | Físico `PRESENCIAL` | Verbal `UNIVERSAL` |\\n|---|---|---|---|\\n| **F** | Fear of Loss / Miedo a la pérdida | Producto en mano y quitarlo, retroceder un paso | *\\"solo hoy\\"*, *\\"tiempo limitado\\"*, *\\"quedan pocas\\"* |\\n| **U** | Urgency / Urgencia | Tic-tac con el bolígrafo, empezar a alejarse | *\\"ahora\\"*, *\\"rápido\\"*, *\\"solo toma un par de minutos\\"* |\\n| **G** | Greed / Avaricia | Manos mostrando altos y bajos | *\\"normalmente $100, con la promo queda en solo $59.99\\"* |\\n| **I** | Indifference / Indiferencia | Postura, lenguaje corporal | SW3 |\\n| **E** | Effect of Jones / Efecto Jones | — | *\\"tengo como 20 clientes en esta zona que...\\"* |\\n| **S** | Suggestive Language / Poder de sugestión | Manos altas precio alto, bajas precio bajo | Tren del sí, alternativas |\\n\\n**Miedo a la pérdida > necesidad de ganancia.** La gente dice que sí impulsivamente porque no quiere que algo se le vaya.\\n\\n**Urgencia:** *\\"motion creates emotion\\"*. Y además comunica que estás ocupado, o sea que tienes éxito.\\n\\n**Indiferencia:** *\\"be excited about the person and the product, but indifferent whether they buy.\\"* **SW3** — Some Will, Some Won''t, So What. *\\"Ellos solo tienen una oportunidad de comprarte; tú tienes más de cien clientes.\\"*\\n\\n**Efecto Jones:** de *\\"keeping up with the Joneses\\"*. La gente no confía naturalmente en un desconocido incentivado a vender — pero sí deja que sus vecinos, amigos y familia validen el producto por ella.\\n\\n**Poder de sugestión — tres niveles:**\\n- **Mental** — *\\"asumo que todos son un sí hasta que me digan que no\\"*\\n- **Físico** — lenguaje corporal `PRESENCIAL`\\n- **Verbal** — el tren del sí. **El cliente debería decir que sí al menos 6 veces durante el proceso.**\\n\\n> **Elimina cualquier opción que se pueda traducir en un no.** En vez de *\\"¿quiere algo de tomar?\\"* → *\\"¿té, café o jugo?\\"*\\n\\n### La Curva de Impulso `FUENTE` `UNIVERSAL`\\nEl impulso sube y baja durante la conversación, y hay que construirlo **gradualmente** para no abrumar.\\n\\n**Las tres reglas de oro:**\\n1. **Encuentra al cliente en un punto común de emoción** al inicio, y construye desde ahí\\n2. **Cierra en el momento correcto** — el pico\\n3. **Elimina el arrepentimiento con un rehash impulsivo** — porque después del sí, el impulso cae\\n\\n#### La presentación tiene dos mitades `CAMPO`\\n\\nY confundirlas es un error común, así que conviene tenerlas separadas.\\n\\n**PRIMERA MITAD — lo que vas a hacer por él.**\\nConectas con su dolor usando SUS palabras, y explicas cómo se lo resuelves. Aquí no hay producto todavía: hay un problema y una solución. *\\"Eso que me dice de quedarse sin producto cuando le entra movimiento — eso es venta que se le va.\\"*\\n\\n**SEGUNDA MITAD — el producto y el precio.**\\nUn resumen breve de qué es lo que le va a resolver eso, y el Triple Desglose de Precios. De ahí se pasa directo al cierre.\\n\\n> **El precio SÍ va en la presentación.** Lo que va en el cierre es el **resumen del pedido** — qué y cuánto lleva. Son dos cosas distintas:\\n>\\n> · **Presentación** → el precio en escalera con sus motivos. *\\"Normalmente le sale en X, como es primer pedido queda en Y, y de contado en Z.\\"*\\n> · **Cierre** → lo que lleva. *\\"Entonces le van dos cajas de esto y una de aquello. ¿Jueves o viernes?\\"*\\n>\\n> Enumerar SKUs con cantidades en la presentación es escribir el cierre en el lugar equivocado. Pero omitir el precio es dejar la presentación a medias — y el cliente se queda esperando el número que nunca llegó.\\n\\n### Triple Desglose de Precios `FUENTE (definido) + CAMPO (desarrollado)` `UNIVERSAL`\\n> **Valor menos costo es igual a ahorro.**\\n\\n**La escalera — tres cifras bajando:**\\n1. **Lo que normalmente cuesta** — hace match con lo que el cliente ya esperaba\\n2. **Con el primer descuento** — cliente nuevo, volumen, lo que aplique\\n3. **Con el segundo** — pago de contado, cerrar hoy, lo que corresponda\\n\\n**El ahorro dicho en voz alta.**\\n\\n> **La regla que lo hace funcionar: cada escalón necesita un motivo nombrado.**\\n>\\n> Un precio que baja **sin razón** le dice al cliente que el primero estaba inflado — y te vuelve regateable, porque si bajó dos veces solo, va a bajar otra si presiona.\\n>\\n> Un precio que baja **por razones nombradas** confirma que el primero era real, y cada escalón se vuelve una bala de precio.\\n\\n**Por qué se ve y no solo se escucha:** *\\"queda en ochenta\\"* se escucha como un gasto de ochenta. *\\"Normalmente cien, con su descuento noventa, de contado ochenta\\"* se ve como veinte de ahorro que antes no existían. Mismo número final, sensación opuesta.\\n\\n**Y como el último escalón depende de algo que puede hacer HOY, aparece solo el miedo a la pérdida.**\\n\\n> ⚠️ **Nunca un solo precio.** Un precio suelto es un gasto sin ahorro visible que lo compense.\\n\\n---\\n\\n## PASO 5 · CIERRE\\n### *Extrae eficientemente una decisión*\\n\\n### Qué es un cierre `FUENTE`\\n> *\\"Un cierre no es algo que le haces a alguien. Un cierre es un acuerdo, cuando el cliente se da cuenta de que el beneficio supera al costo y decide. El cierre se lo hace la gente a sí misma.\\"*\\n\\n**Un cierre no siempre es una venta.** Es pedir la decisión, sea cual sea. Asegúrate de que tus conversaciones avancen hacia una conclusión — un sí o un no.\\n\\n### Asumir la venta `FUENTE` `UNIVERSAL`\\nSi llegaste a este punto, **presume que tienes un comprador**.\\n\\n**Malos cierres** — todos invitan al no:\\n*¿Le gustaría comprar? · ¿Está interesado? · ¿Le gusta lo que oye? · ¿Qué le parece? · ¿Cómo lo ve?*\\n\\n**Buenos cierres** — alternativas donde ambas opciones sirven:\\n*¿Es su nombre el que va en la cuenta? · Las primeras fechas de entrega son jueves o viernes, ¿cuál le conviene? · ¿Visa o MasterCard? · ¿Contado o crédito?*\\n\\n> **El diagnóstico de la fuente:** *\\"la mayoría de las personas que batallan para cerrar simplemente no están rompiendo la zona de confort que viene con pedir algo.\\"*\\n>\\n> Y: *\\"aumentas la probabilidad de que compren mientras más confiadamente anuncies tu mensaje.\\"*\\n\\n### El silencio después del cierre `CAMPO` `UNIVERSAL`\\nNo llenes el silencio. Pediste la decisión: **aguanta**.\\n\\nEl vendedor que retira la pregunta, la suaviza o la contesta él mismo, pierde. El primero que habla después de un cierre, pierde.\\n\\n### FISHBBOD — Señales de Compra `FUENTE`\\nTambién llamadas **STOP signs**. En cuanto reconoces una, **DETIENES la presentación y CIERRAS**.\\n\\n**F** Future talk · **I** I want / I need · **S** Silence · **H** How much / How soon · **B** Body language `PRESENCIAL` · **B** Bashing competitor · **O** Offers of courtesy · **D** Deeper questions\\n\\n> **El error que cuesta más ventas de lo que nadie cree:** el cliente da la señal, el vendedor la ve, y como todavía le quedaban dos argumentos buenos, los suelta.\\n>\\n> **El impulso baja.** Porque el cliente ya estaba listo, y seguir vendiéndole le comunica que hay algo que convencerlo — o le da tiempo de encontrar una razón para no hacerlo.\\n>\\n> Señal de compra = deja de presentar y cierra. **Aunque te queden balas. De hecho, sobre todo si te quedan.**\\n\\n---\\n\\n## MANEJO DE OBJECIONES `FUENTE`\\n### *No son negativas: son preguntas que, bien respondidas, terminan en venta*\\n\\n**Objeción = señal de compra.** El que no tiene interés no objeta: se despide.\\n\\n### Las cuatro técnicas de overturn\\n\\n| Técnica | Cuándo | Cómo |\\n|---|---|---|\\n| **AIR** — Agree, Ignore, Resume | Bloqueos en la introducción | Reconoce, ignora, continúa |\\n| **Ataque Preventivo** | Intro o historia breve, negativos conocidos del territorio | Da el negativo antes que el cliente |\\n| **RRR** — Repeat, Reassure, Resume | Objeciones menores y comunes | Repite, responde, **continúa sin pausa** |\\n| **FFF** — Feel, Felt, Found | Preocupación seria o personal | Nunca discutas |\\n\\n### RRR de objeciones `FUENTE` `UNIVERSAL`\\n**R**epeat — repite la objeción en sus términos, para que vea que la escuchaste\\n**R**eassure — la respuesta concreta, con datos\\n**R**esume — **retoma sin pausa**\\n\\n> **La tercera R es la que falla.** El vendedor responde bien y se queda callado esperando a ver si convenció. En ese espacio el cliente encuentra la siguiente objeción, o dice que lo va a pensar.\\n\\n### FFF — el procedimiento completo `FUENTE` `UNIVERSAL`\\n**Nunca discutas con un cliente.** Ganar la discusión es perder la venta.\\n\\nEn español: **Entiendo · Sintió · Encontramos**\\n\\n1. **\\"Entiendo cómo se siente\\"** — estar de acuerdo te vuelve distinto del vendedor promedio, **y por eso te escuchan**\\n2. **\\"Mi último cliente sentía lo mismo\\"** — para que sepa que no está solo\\n3. **\\"Lo que encontramos fue...\\"** — por qué dejaron de pensar así. **Esto usa Efecto Jones**\\n4. **Inserta 3 balas** de la Teoría de las Balas\\n5. **Close With Action**\\n\\n> ⚠️ **FFF no termina en la tercera F.** El documento en español del sistema fuente está truncado y solo llega al paso 3 — por eso mucha gente aprendió un FFF incompleto, sin re-impulso y sin cierre. **Los pasos 4 y 5 son el Círculo de Cierre.**\\n\\n### El Círculo de Cierre `FUENTE (implícito) + CAMPO (nombrado)` `UNIVERSAL`\\n\\n```\\n   CLOSE WITH ACTION ←──────────────┐\\n            ↓                        │\\n   ¿Objeción? → el impulso baja      │\\n            ↓                        │\\n   Atraviesas (RRR o FFF)            │\\n            ↓                        │\\n   RE-IMPULSAS con una bala NUEVA ───┘\\n```\\n\\n> **El error más común: atravesar la objeción y cerrar de inmediato, saltándose la bala.**\\n>\\n> Técnicamente respondiste. Pero **atravesar solo detiene la caída del impulso** — no lo sube. Estás pidiendo una decisión en el punto más bajo de la conversación, y desde ahí la respuesta cómoda siempre es *\\"déjeme lo pienso\\"*.\\n\\n**Y la bala tiene que ser NUEVA.** Repetir un argumento ya usado no sube nada: comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.\\n\\n### La Regla de los No\\n- **Fuente:** *2 no''s and a go* — dos no seguidos, luz roja, sigue adelante\\n- **Campo `CAMPO`:** Emilio usa **3 no seguidos**, porque hay gente que deja ir un sí solo porque el cliente tuvo preguntas u objeciones\\n\\n> **Tienen que ser CONSECUTIVOS.** Un no, lo atraviesas, la conversación avanza, y más adelante otro no: **eso no es una racha**. Es una conversación normal con dos momentos de fricción. La racha se rompe en cuanto la conversación avanza.\\n\\n---\\n\\n## PASO 6 · CONSOLIDACIÓN / REHASH\\n### *El paso final y más importante*\\n\\n**REHASH** = **R**emember **E**veryone **H**as **A**nother **S**ale **H**idden\\n\\n**Dos propósitos** `FUENTE`:\\n1. **Capitalizar a un cliente ya positivo** — *\\"la gente compra de sus amigos mucho más fácil que de un desconocido\\"*\\n2. **Dejarlo positivo y entendiendo los siguientes pasos** — *\\"la causa número uno de cancelaciones es la falta de entendimiento\\"*\\n\\n### El arrepentimiento del comprador\\nApenas dice que sí, **el impulso cae**. El cerebro empieza a buscar razones por las que quizá no debió. Es automático y no es desconfianza hacia ti.\\n\\n### Cómo se disuelve `CAMPO`\\n> **El error que parece lo correcto: seguir vendiendo.**\\n>\\n> La reacción natural es reforzar la compra — recordarle lo bueno del producto, repetirle el ahorro, insistir en que tomó una gran decisión.\\n>\\n> **Y eso lo empeora.** Seguir vendiendo después del sí le dice al cliente que **necesitabas la venta**. Y si la necesitabas, entonces la indiferencia era actuada. Y si la indiferencia era actuada, también el interés por su negocio, también las preguntas, también la plática de su hijo.\\n>\\n> **Retroactivamente, toda la conversación se convierte en una técnica.**\\n\\n**Lo que sí funciona: demostrar que nada cambió en ti.**\\n\\nMisma indiferencia sobre la compra. Misma calidez sobre la relación. Cero producto. Y la confianza de que ahí vas a estar para lo que necesite.\\n\\n**Por qué funciona:** si tu actitud es idéntica antes y después de la firma, el cliente concluye solo lo que ninguna frase habría logrado convencerlo — **que no lo trataste así para venderle, sino porque así eres.** Y con esa conclusión, el arrepentimiento no tiene de qué agarrarse.\\n\\n**Y deja claro qué sigue.** La falta de entendimiento es la causa número uno de cancelaciones.\\n\\n---","is_active":false,"created_at":"2026-09-26T18:59:04.141328+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"6e99d011-1030-4490-873c-217bf18da4dc","version":3,"section_key":"mentalidad","order_index":3,"title":"PARTE 3 · LA MENTALIDAD","body":"# PARTE 3 · LA MENTALIDAD\\n### *La segunda fundación*\\n\\n> *\\"No importa qué tan buenas sean tus habilidades conversacionales, nunca vas a tener 100% de éxito.\\"*\\n>\\n> Y: *\\"hay gente con mucha personalidad o experiencia que triunfa sin trabajar bien la ley de promedios — pero no puede replicar su éxito, porque depende demasiado de la habilidad.\\"*\\n\\n**La mentalidad no es motivación: es el sistema de control que hace replicable el resultado.**\\n\\n## Ley de Promedios (LDP) `FUENTE`\\n> *\\"Si repites una acción las veces suficientes, aparecerá una proporción.\\"*\\n\\nEs un sistema probado para **encontrar compradores entre los no compradores**.\\n\\n**La analogía de la moneda:** lanzas una vez, 50/50. Lanzas diez veces y raramente sale 5 y 5. Pero mientras más lanzas, más se acerca la muestra a la proporción real. **La ley necesita volumen para manifestarse.**\\n\\n## PPA — lo que afecta tu ley de promedios `FUENTE`\\n**P**itch / Conversación — preciso, conciso, impactante\\n**P**ace / Ritmo — con cuánta gente hablas\\n**A**ttitude / Actitud — consistentemente positiva\\n\\n> **La cadena causal, y por qué la mentalidad no es opcional:**\\n> La ley de promedios necesita volumen. El volumen desgasta la actitud. La actitud degrada el pitch. Y el pitch es la variable de entrada del sistema.\\n>\\n> **Por eso KILT, los 3 tipos de día, controlables y gumball existen: protegen la única variable que el vendedor controla.**\\n\\n## Los 3 Tipos de Día `FUENTE`\\n- **Día A** — las ventas llegan temprano, la actitud es fácil\\n- **Día B** — llegan esporádicamente, no te prueba del todo\\n- **Día C** — todas llegan en las últimas horas. **La verdadera prueba de quién cree en el sistema**\\n\\n*Ejemplo real: 3 ventas de 60 contactos es normal — 5% de éxito. Es normal no tener ningún cliente hasta el final del día y aun así cumplir.*\\n\\n## Teoría del Gumball `FUENTE`\\nTres máquinas, 100 dulces cada una, 97 rojos y 3 verdes. Cada intento cuesta un peso. Tienes 100 pesos y la meta de sacar 3 verdes.\\n\\n**Mantén tu pitch, ritmo y actitud iguales, para que cada \\"no\\" te acerque al \\"sí\\".**\\n\\n> **La dificultad real:** en el campo no puedes ver dónde están los verdes como en la máquina. Tienes que seguir girando a ciegas, sabiendo que tu proporción va a aparecer.\\n\\n## Controlables vs No Controlables `FUENTE`\\n> *\\"Si no podemos controlarlo, no lo pensamos ni lo hablamos. Es una pérdida de tiempo y energía.\\"*\\n\\nLa mayoría pasa el día culpando cosas que no controla. Concentrarse en lo controlable es mucho más productivo: ver más gente, tener mejores conversaciones, cuidar la actitud.\\n\\n## KILT `FUENTE`\\n**K**ill them with kindness — sé amable sin importar la actitud del otro\\n**I**ndifference — algunos comprarán, otros no, ¿y qué?\\n**L**aw of averages — confía en los números\\n**T**reat everyone like your first — nunca sabes cuándo aparece tu cliente\\n\\n**Aplicación:** si dejamos a cada persona mejor de como la encontramos, permanecemos indiferentes al sí o al no, y tratamos a cada quien como el primero, entonces protegemos la actitud.\\n\\n## Los 8 Grandes Hábitos `FUENTE`\\n*\\"Somos lo que hacemos repetidamente; el éxito es un hábito.\\"*\\n\\n1. **Tener gran actitud** — el negocio es 99% actitud y 1% habilidad\\n2. **Ser puntual** — si no llegas temprano, llegas tarde\\n3. **Estar preparado** — fallar en prepararse es prepararse para fallar\\n4. **Esfuerzo del 100%** — recibes lo que pones\\n5. **Maximizar tu territorio** — tu territorio no es el lugar, **son las personas**\\n6. **Proteger tu actitud** — cada \\"no\\" te acerca al \\"sí\\"\\n7. **Conocer tu porqué** — metas de corto, mediano y largo plazo\\n8. **Tomar el control** — de tu día, tu carrera y tu vida\\n\\n## Indicadores / Gauges `FUENTE`\\nMiden con cuánta gente hablas y qué tan lejos llegas en los pasos.\\n\\n**Puertas → Con cuántos hablaste → Presentaciones → Cierres**\\n\\n**Para qué sirven:**\\n1. Identificar dónde **podría** romperse el sistema en tus 6 pasos\\n2. Asegurar que trabajas el sistema\\n3. Marcarte el ritmo\\n\\n> ⚠️ **Los indicadores señalan DÓNDE MIRAR, no qué está mal.**\\n>\\n> Si presentas a muchos y cierras a pocos, el número te dice que algo pasa **entre la presentación y el cierre** — pero la causa puede estar mucho antes. Puede ser que el descubrimiento no encontró el dolor real, que no hubo suficiente CPR y el cliente nunca contestó de verdad, que la presentación se alargó y cayó en KILL, que el impulso se construyó mal, o que efectivamente el cierre es débil.\\n>\\n> **Un número no diagnostica una causa.** Diagnostica una zona.\\n\\n**El diagnóstico real requiere ver la conversación.** Como manager: acompañando al vendedor en campo, o pidiéndole una práctica en Closer sobre el paso donde sospechas.\\n\\n**Números + conversación observada = conclusión.** Cualquiera de los dos solo, es especulación.\\n\\n## Metas — SMART `FUENTE`\\n**S**pecific · **M**easurable · **A**ttainable · **R**ealistic · **T**imed\\n\\nTipos: de **resultado** · de **acción** · corto plazo (<2 meses) · mediano (2 meses–3 años) · largo (3+ años)\\n\\nEscríbelas, hazlas evaluar por alguien, y recompénsate al lograrlas.\\n\\n---","is_active":false,"created_at":"2026-09-26T18:59:04.141328+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"6fed1813-63af-42ef-8859-f6bf5bccb08c","version":3,"section_key":"aplicacion","order_index":4,"title":"PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE","body":"# PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE\\n\\n> **El sistema es el esqueleto. Si se entiende, se aplica a cualquier cliente, cualquier industria y cualquier producto.**\\n\\nEsta parte NO es un catálogo de casos. Es la demostración de cómo se deduce la ejecución correcta a partir de los principios — para que cualquier caso que no esté aquí se resuelva igual.\\n\\n## 4.0 El método de adaptación\\n\\nCada paso existe para lograr algo. **Lo que cambia entre clientes no es el objetivo del paso: es lo que hace falta para lograrlo.**\\n\\nEjemplo con la Historia Breve. Su objetivo es liberar el segundo tercio de atención — las dos preguntas que el cliente trae en la cabeza: *quién eres* y *por qué estás aquí*.\\n\\n- Con un desconocido, las dos están abiertas → contestas las dos\\n- Con alguien que te conoce hace años, la primera ya está contestada → **solo queda el porqué de hoy**, y a veces hasta eso es obvio\\n\\n**La conclusión operativa, dicha completa:** con un cliente que ya te conoce, la Historia Breve **NO incluye tu nombre ni el de tu empresa**. Nada de \\"Soy Juan, de [empresa]\\", ni \\"trabajamos con tal marca\\". Él ya lo sabe. Repetírselo le comunica que no lo reconoces o que estás recitando un guion — y en los dos casos daña la relación que llevas años construyendo.\\n\\nLo único que queda es **por qué viniste HOY**, en una o dos frases. Y a veces hasta eso es evidente.\\n\\nEse es el método. Ante cualquier cliente, en cualquier industria:\\n\\n1. ¿Qué **objetivo** tiene este paso?\\n2. ¿Qué de ese objetivo **ya está resuelto** con este cliente?\\n3. ¿Qué **falta** por resolver?\\n4. **Ejecuta solo eso, y escribe solo eso.**\\n\\n> ⚠️ **El paso 4 es donde más se falla.** Deducir correctamente qué falta y aun así escribir la versión completa por costumbre es el error más frecuente al aplicar este método. Si concluiste que algo ya está resuelto, **ese algo no aparece en el texto.** No basta con saberlo: hay que omitirlo.\\n\\n## 4.0b Autoconsumo y distribuidor NO son un tercer eje `CAMPO`\\n\\nHay una confusión fácil de cometer: tratar \\"autoconsumo\\" y \\"distribuidor\\" como si fueran alternativas a \\"nuevo\\" y \\"recurrente\\". No lo son. **Son ejes distintos.**\\n\\n**EJE 1 — ¿Ya te compra?** Nuevo o recurrente. Esto define **la relación**: si te conoces, si hay historial, si hay pedido base.\\n\\n**EJE 2 — ¿Qué hace con el producto?** Revende, consume o distribuye. Esto define **las preguntas**: qué se le pregunta en cada territorio.\\n\\n**Se cruzan.** Un cliente de autoconsumo puede ser nuevo (nunca te ha comprado) o recurrente (lleva años surtiéndose contigo). Y la ejecución cambia según el cruce:\\n\\n| | Nuevo | Recurrente |\\n|---|---|---|\\n| **Revende** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Consume** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Distribuye** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n\\n> **Lo que cambia por el EJE 1** es si te presentas, si hay \\"lo de siempre\\", y si buscas dolor o hueco.\\n>\\n> **Lo que cambia por el EJE 2** es únicamente el vocabulario del descubrimiento: al que revende le preguntas qué maneja y qué le piden; al que consume, qué usa y cada cuánto repone; al que distribuye, sus líneas y a cuántos surte.\\n\\n**Error concreto que esto evita:** escribir la historia breve de un cliente de autoconsumo como si fuera recurrente — *\\"vine a ver cómo les funcionó lo que dejamos la vez pasada\\"* — cuando nunca ha habido una vez pasada. Autoconsumo no dice nada sobre si ya te compra o no.\\n\\n**Y una vez que un cliente de autoconsumo te compra, se vuelve recurrente**: el seguimiento y el crecimiento de esa cuenta funcionan igual que con cualquier otro recurrente. Buscas huecos, cierras el incremento, y no te vuelves a presentar.\\n\\n## 4.1 Lo que sí cambia sustancialmente\\n\\nHay dos diferencias que no son obvias y que sí conviene tener explícitas, porque cambian **qué se busca**, no solo cómo se dice.\\n\\n### Diferencia 1 — Qué buscas en el Descubrimiento\\n\\n**DOLOR** — algo anda mal. Tiene señal verbal: **el \\"aunque\\"**. Se busca con los 3 Territorios y la escalera de capas.\\n\\n**HUECO** — algo que podría comprarte y no te compra. **No tiene señal verbal: se ve, no se oye.**\\n\\n> Un cliente conforme no tiene dolor. **Por eso el vendedor que solo sabe buscar dolor visita durante años sin crecer una cuenta**: busca, no encuentra, y concluye correctamente que no hay nada.\\n\\n**Las tres herramientas del hueco:**\\n\\n**1 · Lee el lugar** — lo que ves te dice qué maneja y de quién. Un producto de otra marca es un espacio ocupado; un estante vacío es una familia que nadie cubre; algo empolvado no es hueco, **es dolor**.\\n\\n**2 · Pregunta por lo que le piden** — *\\"¿le ha tocado que le pidan algo que no maneje?\\"* Demanda que ya existe sin oferta que la cubra.\\n\\n**3 · Ancla en negocios como el suyo** — Efecto Jones aplicado. Solo si es verdad y lo puedes sostener.\\n\\n**Adaptación por canal:** presencial observas; a distancia preguntas por el catálogo. **Adaptación por giro:** si el cliente no revende, \\"lo que ves\\" no es un mostrador — son sus unidades, su patio, su operación.\\n\\n> **La línea que no se cruza:** un hueco tiene que ser real y verificable. **Descubrir un hueco es señalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.**\\n\\n### Diferencia 2 — Qué estás cerrando\\n\\nCon un cliente que ya compra, **el pedido base no está en duda: ya iba a existir.** Lo que se cierra es **lo que se agrega**.\\n\\nReabrir el pedido base al cerrar pone sobre la mesa algo que ya estaba resuelto, e invita al cliente a revisar toda la orden.\\n\\n## 4.1b La observación del recurrente no puede sonar a primera visita `CAMPO`\\n\\nEl SCE y el ice breaker siguen aplicando con un cliente de años. Lo que cambia es **de qué se observa**.\\n\\n**El error:** *\\"¿Siempre está así de lleno o hoy le tocó día pesado?\\"*\\n\\nEsa pregunta la hace alguien que no conoce el lugar. Y este vendedor lleva años pasando cada quincena — **ya sabe si el negocio es movido.** Preguntarlo le comunica al cliente que no lo tiene presente, que es lo contrario de lo que la relación construyó.\\n\\n**Lo correcto: observar lo que CAMBIÓ desde la última visita.**\\n\\n> *\\"Oiga, ¿ya le entró más gente que la vez pasada, verdad?\\"*\\n> *\\"Veo que le movió al acomodo desde que vine.\\"*\\n> *\\"¿Ya se compuso lo del clima o siguen igual de flojas las tardes?\\"*\\n\\nY también funciona lo personal, que con un desconocido no puedes usar:\\n\\n> *\\"¿Cómo salió su muchacho de lo que me contó?\\"*\\n> *\\"¿Le fue bien en el puente?\\"*\\n\\n> **La prueba:** si tu observación de apertura funcionaría igual con un cliente que ves por primera vez, no está aprovechando la relación. **Con un recurrente, la apertura demuestra memoria** — y esa memoria es el activo que llevas años construyendo.\\n\\n⚠️ **Y esto solo funciona si la memoria es real.** Inventar que recuerdas algo que no pasó es peor que no recordar nada. Si no tienes un dato de la visita anterior, observa el momento presente sin fingir historia: *\\"se ve movido hoy\\"* es honesto; *\\"¿siempre está así?\\"* no lo es.\\n\\n## 4.2 Lo que NO cambia nunca\\n\\n- El orden de los 6 pasos\\n- Que el descubrimiento va antes de la presentación\\n- Que el cierre asume en vez de pedir aprobación\\n- Que el precio va en escalera con motivo\\n- Que no hay frases neutras\\n- Toda la Parte 6 (jerarquía de reglas)\\n\\n## 4.3 Presentar un hueco `CAMPO`\\n\\nCuando lo que encontraste es un hueco, no hay nada que resolver: el cliente está conforme. Hay un espacio que ocupar.\\n\\n**La pregunta que define el argumento: ¿qué gana él con que tú se lo surtas?**\\n\\nY la respuesta depende del caso, no de una fórmula. Posibilidades reales:\\n\\n- **Consolidación** — si el cliente trata con muchos proveedores y eso le pesa, reducir el número tiene valor por sí mismo\\n- **Conveniencia** — te ve de todos modos; agregar una familia no le suma trabajo\\n- **Complementariedad** — lo que ofreces se usa junto con lo que ya te compra\\n- **Una condición concreta** — plazo, disponibilidad, presentación, tiempo de entrega\\n\\n> ⚠️ **La consolidación NO es un argumento universal.** Si tu producto es complementario y el cliente ya tiene cinco proveedores, con la familia nueva pasa a tener **seis, no cuatro**. Ahí *\\"menos proveedores que seguir\\"* es falso, y usarlo te desacredita.\\n>\\n> Antes de usarlo, verifica que el cliente **efectivamente vaya a reducir** su número de proveedores.\\n\\n⚠️ **Nunca ataques al proveedor actual.** Criticarlo es criticar la decisión del cliente, y la gente defiende sus decisiones.\\n\\n⚠️ **No afirmes ventajas que no puedes verificar.** *\\"El otro no maneja esta línea\\"*, *\\"nadie tiene nuestro catálogo\\"*, *\\"con nosotros le sale mejor\\"* — si no lo sabes de cierto, no lo digas. Puede ser falso, y en una cuenta de años se descubre siempre. **Habla de lo que TÚ ofreces, con hechos que puedas sostener.**\\n\\n## 4.4 Convicción sin garantía `CAMPO`\\n\\n> **Nunca le pidas que \\"pruebe\\".**\\n>\\n> *\\"Le pongo unas pocas para que lo pruebe\\"* suena humilde y es lo peor que puedes decir: **le pasas el riesgo a él.** La gente no quiere experimentar — está cómoda donde está, y probar algo nuevo es riesgo, incomodidad y la posibilidad de haberse equivocado.\\n\\n**El trabajo del vendedor no es pedir permiso para experimentar. Es hacer que el cliente se sienta seguro.** Dos movimientos:\\n\\n1. **Convicción, sin garantía** — *\\"no le puedo garantizar nada, pero estoy seguro de que le va a servir\\"*\\n   **Funciona precisamente porque reconoce el límite.** Admitir lo que no controlas hace creíble lo que sí afirmas.\\n\\n2. **La razón detrás** — *\\"se lo digo porque en negocios como el suyo es de lo que más sale\\"*\\n   Sin la razón, tu convicción es solo optimismo de vendedor.\\n\\n**Y ahí te callas.**\\n\\n⚠️ **No ofrezcas el plan B.** *\\"Y si no funciona lo ajustamos\\"* parece que baja el riesgo y hace lo contrario: **le mete una duda que no tenía**, y desmiente lo que acabas de afirmar. Si de verdad estás seguro, ¿para qué el paracaídas?\\n\\n*(Si después no funciona, ahí lo ajustas. Eso es Consolidación y se hace cuando pasa — no se anuncia por adelantado.)*\\n\\n## 4.5 El capital del récord `CAMPO`\\n\\n> **La primera vez que recomiendas algo, el cliente compra por la relación. La segunda vez, compra por tu récord.**\\n\\nY eso disciplina: si recomiendas algo que no funciona, **no perdiste una venta — gastaste crédito que te costó años juntar.** Por eso solo se recomienda lo que de verdad sirve a ese perfil, aunque haya cosas con mejor margen.\\n\\n## 4.6 Los dos juegos `CAMPO`\\n\\n**ADQUISICIÓN** — convertir a un desconocido en cliente.\\n**DESARROLLO** — convertir a un cliente en un cliente más grande.\\n\\n> **La asimetría que explica por qué el segundo se descuida:** adquisición da retroalimentación inmediata — vendes o no vendes. Desarrollo no. Puedes visitar cien veces, levantar el mismo pedido, sentir que hiciste bien tu trabajo, y nunca enterarte de lo que dejaste sobre la mesa.\\n>\\n> **El fracaso en desarrollo es invisible.**\\n\\n**El enemigo: la visita que se vuelve trámite.** El vendedor está haciendo adquisición con alguien que ya adquirió — y como no hay nada que adquirir, no hay nada que hacer.\\n\\n> **Al que solo toma pedidos lo reemplaza un formulario.**\\n\\n---","is_active":false,"created_at":"2026-09-26T18:59:04.141328+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"d2133dba-c4c1-43ab-b30a-7364ce783adb","version":3,"section_key":"canales","order_index":5,"title":"PARTE 5 · MODIFICADORES DE CANAL","body":"# PARTE 5 · MODIFICADORES DE CANAL\\n\\n| Canal | Qué se conserva | Qué se adapta |\\n|---|---|---|\\n| **Presencial** | Todo | — |\\n| **Teléfono** | Los 6 pasos, KISS, FORMS, las 4 técnicas de overturn, balas, FUJIES verbales, CWA, triple desglose, y el **entusiasmo del tono** | Contacto visual → pausas y ritmo. Todo lo físico se pierde |\\n| **WhatsApp / mensaje** | La estructura completa, balas, triple desglose, ataque preventivo | Mensajes cortos, uno por idea. Señales de compra → velocidad de respuesta, emojis, preguntas de precio. El cierre debe contestarse con una palabra |\\n| **Correo** | Estructura, KISS, balas, triple desglose | Todo lo interactivo se vuelve secuencia |\\n\\n> **El principio de adaptación: entender qué HACE cada técnica permite encontrar su equivalente en cualquier medio.**\\n>\\n> El miedo a la pérdida no es *\\"quitar el producto de la mano\\"* — es **crear la sensación de que algo se va**. Eso existe en los cuatro canales.\\n\\n---","is_active":false,"created_at":"2026-09-26T18:59:04.141328+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"4ff31577-2dbe-4b24-9f05-4e235d48397f","version":3,"section_key":"jerarquia","order_index":6,"title":"PARTE 6 · JERARQUÍA DE REGLAS","body":"# PARTE 6 · JERARQUÍA DE REGLAS\\n\\nCuando dos principios chocan, gana el de mayor jerarquía.\\n\\n## NIVEL 1 — Inviolables (ética y verdad)\\nNunca se rompen, en ningún contexto, por ninguna razón.\\n\\n1. **Impulso falso está prohibido.** Urgencia inventada, escasez que no existe, prueba social fabricada. *(Práctico, no solo moral: un impulso falso se derrumba cuando el cliente lo descubre, y se lleva la venta, la relación y tu reputación en la zona.)*\\n2. **No garantizar lo que no controlas.** Convicción sí; garantía no.\\n3. **No fabricar un hueco ni un dolor.** Descubrir es señalar lo que existe.\\n4. **No atacar al competidor ni al proveedor actual.**\\n5. **No afirmar ventajas que no puedes verificar.** *\\"Nadie más tiene esto\\"*, *\\"el otro no lo maneja\\"*, *\\"con nosotros sale mejor\\"* — si no lo sabes de cierto, no lo dices. Habla de lo que TÚ ofreces.\\n6. **Nunca discutir con un cliente.**\\n\\n## NIVEL 2 — Estructurales\\nSe rompen solo si el Nivel 1 lo exige.\\n\\n7. **El orden de los 6 pasos.** No se salta ninguno.\\n8. **Primero el examen, luego la receta.** No presentar sin diagnosticar.\\n9. **El cierre asume, no pide aprobación.** Toda pregunta que permita aprobar o posponer entrega el control.\\n10. **El precio va en escalera con motivo en cada escalón.** Nunca un solo número.\\n11. **No hay frases neutras.** Si algo resta valor y nadie lo preguntó, se omite.\\n12. **Señal de compra = detente y cierra.**\\n13. **Se sale de la línea, pero siempre se regresa.**\\n14. **Nunca pidas opinión ni aprobación sobre el precio.** Ni el tuyo ni el de la competencia. Preguntar *\\"¿cómo ve los precios?\\"* le pide al cliente que construya una posición contra ti antes de que exista valor, cede tu autoridad sobre el precio, y renuncia a tu ventaja — porque tú conoces el mercado y él muchas veces no. En el territorio PRECIO se investigan **hechos** (a cómo compra, qué plazo tiene, cada cuánto le suben), nunca opiniones.\\n\\n## NIVEL 3 — Contextuales\\nDependen del tipo de cliente, canal o situación. **Se deducen del método de la Parte 4.0, no se memorizan.**\\n\\n14. Qué parte de la Historia Breve hace falta — depende de qué ya sabe el cliente\\n15. Buscar dolor o buscar hueco — depende de si el cliente está conforme\\n16. Qué argumento usar al presentar un hueco — depende de qué gana él en ESE caso\\n17. Cerrar la venta o cerrar el incremento — depende de si hay un pedido base\\n18. SEE físico — solo presencial\\n\\n## NIVEL 4 — Estilo\\nAjustables al lenguaje del vendedor, la zona y la empresa.\\n\\nTono, vocabulario, longitud de frases, formalidad. **El manager conoce el lenguaje de su gente mejor que Closer.**\\n\\n---","is_active":false,"created_at":"2026-09-26T18:59:04.141328+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"7b452c9f-81d3-421d-aafa-8515c76ccb25","version":3,"section_key":"razonamiento","order_index":7,"title":"PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO","body":"# PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO\\n\\n## Ante un caso no cubierto\\n1. Identifica **qué paso** de la línea es\\n2. Pregunta **qué objetivo tiene ese paso**\\n3. Pregunta **qué de ese objetivo ya está resuelto** con este cliente, y qué falta\\n4. Verifica contra la **jerarquía**: ¿viola algo de Nivel 1 o 2?\\n5. Si sigue sin resolverse, **di que no lo sabes.** No inventes doctrina.\\n\\n## Ejemplos de deducción\\n\\n**Caso:** un vendedor pregunta si puede decir *\\"¿le late?\\"* al cerrar.\\n**Razonamiento:** es una pregunta que permite aprobar o posponer → viola la regla 9 (Nivel 2) → **no**. La alternativa es una pregunta donde ambas opciones sirvan.\\n\\n**Caso:** un manager quiere que el pitch mencione que un producto no trae promoción este mes.\\n**Razonamiento:** no hay frases neutras (1.3); esto baja el valor percibido; nadie lo preguntó → **se omite**. Regla 11, Nivel 2.\\n\\n**Caso:** un vendedor pregunta cómo abrir con un cliente que le compra desde hace cinco años.\\n**Razonamiento:** aplica el método 4.0. Objetivo de la Historia Breve = contestar *quién eres* y *por qué estás aquí*. Lo primero ya está resuelto → **solo queda el porqué de hoy**, y a veces hasta eso es evidente. No hace falta una regla especial: sale del objetivo del paso.\\n\\n**Caso:** vender un servicio de software por videollamada a una empresa que nunca lo ha usado.\\n**Razonamiento:** el sistema aplica igual. Cliente nuevo → doctrina de adquisición. Canal remoto → SEE físico no aplica, pero el entusiasmo del tono sí. \\"Lee el lugar\\" no existe, así que se pregunta. Los 3 Territorios se traducen: producto = qué usan hoy, servicio = cómo los atiende su proveedor, precio = qué pagan. **Nada del esqueleto cambia.**\\n\\n**Caso:** un vendedor dice que el cliente no le reconoce ningún problema, pero él ve claro que sí lo tiene.\\n**Razonamiento:** aplica 1.5. La confirmación explícita no es requisito. Si hay evidencia real — algo que dijo, algo que vio, algo propio de su giro — **avanza presentando la situación resuelta**, no el problema reconocido. Insistir en que lo admita lo pone a la defensiva y apaga lo emocional, que es donde está la venta. **El límite:** si el cliente ya negó explícitamente ese problema, insistir es fabricar, y eso es Nivel 1.\\n\\n**Caso:** un vendedor lleva tres días sin cerrar y está desanimado.\\n**Razonamiento:** esto es Parte 3, no Parte 2. Aplica Ley de Promedios, los 3 Tipos de Día (día C), gumball, y controlables vs no controlables. **No es un problema de técnica: es de protección de la actitud, que es la variable de entrada del sistema.**\\n\\n**Caso:** un manager ve que su vendedor presenta mucho y cierra poco, y quiere saber qué corregir.\\n**Razonamiento:** el indicador señala una zona, no una causa. Puede ser el cierre, pero también un descubrimiento que no encontró el dolor real, CPR insuficiente, o una presentación que se alargó y cayó en KILL. **Números + conversación observada.** Pídele una práctica o acompáñalo en campo antes de concluir.\\n\\n## Sobre la incertidumbre\\nEste documento tiene procedencia marcada por una razón: **lo que está como `CAMPO` no se puede verificar contra la fuente.** Si un caso depende de doctrina `CAMPO` y hay duda, la autoridad es Emilio, no la inferencia.\\n\\n**Nunca completes un hueco de doctrina inventando.** Di qué falta y pídelo.\\n\\n**Y nunca inventes un hecho comercial** — una ventaja, una comparación con la competencia, un dato de mercado. Eso no es doctrina: es información de la empresa, y si no está en su contexto, se pide.","is_active":false,"created_at":"2026-09-26T18:59:04.141328+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"0885d37d-4815-44c9-b958-7dbfba87e63d","version":4,"section_key":"fundamento","order_index":1,"title":"PARTE 1 · EL FUNDAMENTO","body":"# EL CEREBRO DE CLOSER\\n## Doctrina canónica del sistema de venta\\n\\n*Versión 1.0 · Fuente única de verdad*\\n\\n---\\n\\n## CÓMO USAR ESTE DOCUMENTO\\n\\nEsto no es un manual ni un resumen. Es el entendimiento del sistema, escrito para que se pueda **razonar** con él.\\n\\nCada técnica se presenta con tres cosas: **qué es**, **por qué funciona** (el mecanismo humano detrás) y **qué la rompe**. El porqué importa más que el qué, porque de él se deducen los casos que ninguna lista cubre.\\n\\nEjemplo de la diferencia: una lista diría *\\"no digas «¿cómo lo ves?»\\"*. Este documento dice *\\"toda pregunta que permita aprobar o posponer le entrega el control al cliente\\"* — de donde se deduce que *\\"¿le late?\\"*, *\\"¿qué opina?\\"* y *\\"¿le parece?\\"* también están mal, aunque nadie los haya escrito nunca.\\n\\n**Regla de razonamiento:** ante un caso que este documento no cubre explícitamente, no inventes. Busca el principio que aplica y dedúcelo. Si dos principios chocan, gana el de mayor jerarquía (ver Parte 6).\\n\\n### Etiquetas\\n\\n**PROCEDENCIA** — `FUENTE` (sistema original Credico/Cydcor) · `CAMPO` (evolución de Emilio Fanjul) · `CLOSER` (andamiaje pedagógico)\\n\\n**CANAL** — `PRESENCIAL` (requiere cuerpo o presencia) · `UNIVERSAL` (funciona en persona, teléfono, mensaje o correo)\\n\\n---\\n\\n---\\n\\n# PARTE 1 · EL FUNDAMENTO\\n\\n## 1.1 El problema que resuelve todo el sistema `FUENTE`\\n\\nCuando abres una conversación con un desconocido, **su atención está dividida en tres**:\\n\\n- **Un tercio** sigue en lo que estaba haciendo\\n- **Un tercio** está resolviendo preguntas básicas: quién eres, qué quieres, por qué me hablas\\n- **Solo un tercio** está disponible para ti\\n\\n> **De aquí sale la razón de ser de los 6 pasos:** si vas directo a presentar, le estás hablando a un tercio de una persona. Cada paso previo existe para recuperar una porción de esa atención.\\n\\nLa Introducción libera el primer tercio (deja de pensar en lo que hacía). La Historia Breve libera el segundo (ya sabe quién eres y a qué vienes). Solo entonces tienes casi toda su atención — y solo entonces vale la pena presentar.\\n\\n**Esto explica por qué saltarse pasos no acelera nada: presentarle a alguien distraído es desperdiciar tu mejor material.**\\n\\n## 1.2 La Línea Recta `CAMPO` `UNIVERSAL`\\n\\nUna venta avanza en línea recta, de izquierda a derecha, a través de los 6 pasos.\\n\\n**Nada te regresa. Lo que ya recorriste, quedó.** Lo único que puede pasar es que algo te **saque de la línea y te pause**.\\n\\nLa imagen: vas dibujando la línea hacia la derecha y de pronto llega una objeción. Ahí dejas de avanzar y la línea sube — saliste. Pero no retrocede. Está en ti resolver y volver al punto donde ibas.\\n\\n| Elemento | Relación con la línea |\\n|---|---|\\n| Los 6 pasos | La línea misma |\\n| CPR / FORMS | Salida **deliberada** — sales tú, y regresas |\\n| Bloqueos → AIR, Ataque Preventivo | Salida **impuesta** al inicio |\\n| Objeciones → RRR, FFF | Salida **impuesta** después de entender |\\n| Close With Action | Lo que te devuelve y te mueve al siguiente tramo |\\n| Los 3 No seguidos | La señal de que ya no hay línea que recorrer |\\n\\n**Diagnóstico que le da al vendedor:** cuando una visita sale mal, la pregunta no es *\\"¿qué técnica olvidé?\\"* sino **\\"¿dónde salí de la línea y por qué no regresé?\\"**\\n\\n## 1.3 El principio de la balanza `FUENTE` `UNIVERSAL`\\n\\nNadie compra por precio. Compra cuando el **valor percibido** pesa más que el **costo percibido**. Cuanto mayor la brecha, mayor el impulso.\\n\\nY el costo no es solo dinero: es tiempo, riesgo de cambiar, esfuerzo, y la posibilidad de haberse equivocado.\\n\\n> **La regla que convierte esto en herramienta:** con cada frase, cada gesto y cada silencio estás haciendo una de cuatro cosas — subiendo el valor, bajándolo, subiendo el costo, o bajándolo.\\n>\\n> **No hay frases neutras.**\\n\\nDe aquí se deducen cosas que ninguna lista de reglas contiene:\\n- Titubear al dar un precio sube el costo percibido\\n- Disculparte baja tu valor\\n- Mencionar algo que **no** tienes, no aplica o no está disponible **baja el valor sin que nadie te lo pidiera** — y por eso se omite\\n- Contar un caso real de otro cliente sube el valor\\n\\n**Cost vs Value no es tanto una habilidad como una herramienta de evaluación:** revisa cada parte de tu conversación y pregúntate qué plato movió.\\n\\n## 1.4 La gente compra, pero no quiere que le vendan `FUENTE`\\n\\nEste es el principio psicológico que atraviesa todo el sistema.\\n\\nA las personas les gusta comprar. Lo que les desagrada es **sentir que les están vendiendo**. Tienen una alarma calibrada para detectar al vendedor, y en cuanto se activa, todo lo que digas después se procesa con desconfianza.\\n\\n> **Casi todas las técnicas de este sistema son formas de obtener un resultado de venta sin activar esa alarma.**\\n\\n- **Gasman** — pedir permiso te delata como forastero; asumir que perteneces no dispara nada\\n- **CPR** — ser persona antes que vendedor\\n- **Descubrimiento** — el vendedor promedio habla; el que pregunta rompe el patrón que la alarma busca\\n- **Close With Action** — nunca pides el sí, porque pedirlo enciende la alarma\\n- **Indiferencia** — la presión genera resistencia; quitarla la disuelve\\n- **FFF** — estar de acuerdo primero te vuelve distinto del vendedor promedio, *y por eso te escuchan*\\n\\n## 1.5 La decisión es emocional antes que racional `CAMPO`\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente siente algo primero, y después construye la razón que lo justifica.\\n\\nEsto no contradice el diagnóstico ni la construcción de valor: los explica. La doctrina fuente lo dice sin rodeos — **\\"el impulso es otra palabra para la emoción\\"**.\\n\\n**Lo que se deduce de aquí, y que corrige el error de modelar la venta como un proceso lógico:**\\n\\n- **El cliente no necesita reconocer un problema para sentir el alivio de resolverlo.** Por eso \\"pintar imágenes\\" funciona: no argumenta, hace sentir.\\n- **Pelear por el reconocimiento explícito mata la venta.** Insistir en que admita algo lo pone a la defensiva, y la defensiva apaga lo emocional — que era donde estaba la venta.\\n- **El 80% indiferente no tiene un problema urgente**, y aun así compra. Se mueve por los factores de impulso, no por el diagnóstico.\\n- **Un argumento perfecto dicho por alguien en quien no confía, no pesa.** Y uno mediocre dicho por alguien cercano, sí. De ahí la importancia real del CPR.\\n\\n> **La regla operativa:** el sistema construye una situación deseable, no un caso lógico. La razón sirve para que el cliente pueda **justificar** la decisión — no para que la tome.\\n\\n⚠️ **Y esto no autoriza a manipular.** El Nivel 1 sigue intacto: el impulso se construye con verdad. La diferencia es que construir una imagen real y deseable es legítimo; fabricar urgencia, escasez o problemas no lo es.\\n\\n---","is_active":false,"created_at":"2026-09-26T21:43:44.070314+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"d20fee1d-f035-4495-a751-7a66c811e398","version":4,"section_key":"pasos","order_index":2,"title":"PARTE 2 · LOS 6 PASOS","body":"# PARTE 2 · LOS 6 PASOS\\n\\nEl sistema original tiene **5 pasos** `FUENTE`: Introducción, Historia Breve, Presentación, Cierre, Consolidación.\\n\\nCloser enseña **6** `CAMPO`: se separa **Descubrimiento** como paso propio. En la fuente las preguntas de calificación viven dentro del flujo; separarlas reconoce que diagnosticar y presentar son habilidades distintas que fallan por razones distintas.\\n\\n---\\n\\n## PASO 1 · INTRODUCCIÓN\\n### *Una sola oportunidad para una primera impresión*\\n\\n**Qué logra:** liberar el primer tercio de atención y ganarte el derecho a seguir hablando.\\n\\n**Qué NO es:** aquí no dices quién eres ni a qué vienes. Eso es el Paso 2. Confundirlos es el error doctrinal más común.\\n\\n### SEE / SCE `FUENTE` `PRESENCIAL`\\n**S**mile · **E**ye contact · **E**nthusiasm — Sonrisa, Contacto visual, Entusiasmo\\n\\n- **Sonrisa** — signo internacional de amistad. Elimina el miedo y crea confianza.\\n- **Contacto visual** — genera confianza, mantiene el control de la conversación, **y es una señal de compra fuerte cuando el cliente lo hace**.\\n- **Entusiasmo** — crea impulso y curiosidad. Si estás emocionado, asumen que hablas de algo emocionante. **Y al revés también funciona:** si suenas aburrido de tu producto, nadie va a estar más emocionado que tú.\\n\\nSe combinan con **lenguaje corporal abierto** y **tono de voz fuerte**.\\n\\n> ⚠️ **Límite de canal:** SEE es físico. En texto o voz no se puede evaluar. Se enseña, se pide, y se marca como *\\"esto se practica en persona\\"*. Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**.\\n\\n### Regla del 10% `FUENTE` `PRESENCIAL`\\nLee el nivel de emoción del cliente y ponte **10% por encima** de él. No al doble: 10%.\\n\\n**Por qué:** llegar gritando con alguien tranquilo lo aleja tanto como llegar apagado con alguien entusiasmado. El 10% jala sin romper.\\n\\n### Ice Breaker `FUENTE` `UNIVERSAL`\\nCumplido genuino, chiste sencillo o comentario ligero.\\n\\nPuede ser sobre **la persona**, **el lugar**, o **algo en común**. No está atado a ningún tipo de negocio.\\n\\n**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee al instante y se cierra **más** que antes — porque ahora sabe que le están aplicando una técnica.\\n\\n### La escalera de la especificidad `CAMPO` `UNIVERSAL`\\n\\nLa observación y la pregunta de la apertura se miden igual: **¿se la harías a cualquiera?** Entre más específica para ESE cliente en ESE momento, más vale.\\n\\n- **Escalón 1 — de cortesía.** Se la harías a cualquiera: *\\"¿cómo está?\\"*, *\\"qué gusto saludarlo\\"*. Cumple lo mínimo porque le devuelve la palabra, pero no construye nada.\\n- **Escalón 2 — del entorno.** Sale de lo que ves ahí, en ese momento: *\\"veo que no paran, ¿siempre está así de movido?\\"*. Solo tiene sentido en ese lugar.\\n- **Escalón 3 — de él.** Solo se la harías a él, porque sabes algo de antes: *\\"¿cómo sigue? ¿va mejorando?\\"*.\\n\\n**La prueba del escalón 2:** nombra algo concreto que viste ahí —el movimiento, que está lleno, un cambio, algo nuevo—. Un adjetivo genérico, como *\\"qué bien se ve el local\\"* o *\\"qué bonito\\"*, se lo dirías a cualquiera: es escalón 1.\\n\\n> **Las mismas palabras pueden estar en escalones distintos.** *\\"¿Cómo está?\\"* a secas es escalón 1; *\\"¿cómo está? ¿va mejorando?\\"* a alguien que estuvo enfermo es escalón 3. Lo que sube el escalón no son las palabras: es qué tanto sabe la pregunta de él.\\n\\n**La relación cambia la escalera.** Con un cliente nuevo no existe el escalón 3 —no hay historia con él—, así que el escalón 2 es la excelencia. Con un recurrente la meta es el escalón 3, y el 2 puede ser un error: preguntarle si siempre está así de movido a alguien que visitas desde hace años le dice que no lo tienes presente (ver 4.1b).\\n\\n**Una pregunta de cortesía no es una falla: es el primer escalón.** La falla es no preguntar nada: sin ninguna pregunta, el cliente no tiene qué contestar y la conversación se muere ahí.\\n\\n**Y la pregunta que mejor devuelve la palabra es la que sale de la observación y cierra la apertura:** *\\"veo que no paran, ¿siempre está así de movido?\\"*. Un *\\"¿cómo está?\\"* dentro del saludo cumple, pero si después sigues hablando, el cliente espera a que termines en vez de contestar. Convertir la observación en la pregunta final es como se sube de escalón.\\n\\n### Especificidad y ligereza son dos cosas distintas `CAMPO` `UNIVERSAL`\\n\\nUn comentario de apertura se mide con dos preguntas diferentes. **¿Se lo dirías a cualquiera?** es la especificidad: la escalera. **¿Baja la guardia?** es la ligereza: humor suave, un guiño o calidez en lo que dices.\\n\\nUna no garantiza la otra. *\\"Veo que tiene cuatro cajas de filtros de una marca y dos de otra\\"* es muy específico, y suena a inspección. *\\"¡Qué buen día hace, eh!\\"* es ligero, y se lo dirías a cualquiera. *\\"¿Qué les pasó hoy que está lleno? ¿Regalan algo o qué?\\"* tiene las dos.\\n\\n**La ligereza se mide en lo que haces, no en cómo reacciona el cliente.** Un buen chiste puede no hacerle gracia a un cliente rojo, o a alguien que viene enojado ese día, y no por eso se hizo mal. La reacción del cliente puede confirmar que algo funcionó; nunca puede condenar una acción bien hecha. Es la lógica de los controlables: al vendedor se le mide por lo que controla, y el humor del cliente no es una de esas cosas.\\n\\nLa calidez que vive en el tono de voz no se puede calificar por escrito: se enseña igual, se practica igual, y la escucha el manager (ver 1.7).\\n\\n### Teoría del Gasman `FUENTE` `UNIVERSAL`\\nSer asumido y confiado, con alta indiferencia.\\n\\nEl gasista que viene a leer tu medidor entra con una autoridad que nace de sentir que **debe estar ahí** — no es una intrusión. Nadie lo detiene, y no es por su permiso: es por su postura.\\n\\n> **El mecanismo:** cuando preguntas *\\"¿tiene un minutito?\\"* haces dos cosas a la vez — le entregas el control, y le ofreces una salida que no le cuesta nada tomar. El cliente que dice \\"ahorita no\\" no está siendo grosero: tomó la puerta que le abriste.\\n>\\n> **La autoridad no se pide. Se asume.**\\n\\n### Regla doctrinal del paso `CAMPO`\\n**La identificación (nombre y empresa) es permitida pero nunca requerida aquí.** Su ausencia jamás se penaliza.\\n\\nSi el cliente pregunta *\\"¿y usted quién es?\\"*, **ganaste la introducción** — esa pregunta es la puerta natural al Paso 2, no una falla.\\n\\n---\\n\\n## PASO 2 · HISTORIA BREVE\\n### *Explica tu propósito de manera concisa*\\n\\n**Qué logra:** liberar el segundo tercio de atención. El cliente deja de preguntarse quién eres y qué quieres.\\n\\n### KISS vs KILL `FUENTE` `UNIVERSAL`\\n**K**eep **I**t **S**hort and **S**imple — contra **K**eep **I**t **L**ong and **L**engthy.\\n\\nQuién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible.\\n\\n> **El mecanismo:** cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él — y de los discursos uno se defiende.\\n\\n**Y después de la historia, preguntas.** La fuente es explícita: *\\"en la mayoría de los casos es más efectivo pasar directamente a las preguntas de calificación que dar una larga explicación.\\"*\\n\\nTu historia breve no existe para que te entiendan a ti. **Existe para ganarte el derecho de preguntarle a él.**\\n\\n### CPR — Create Personal Relations `FUENTE` `UNIVERSAL`\\n> *\\"Eres tanto, si no más, el producto que los productos que representas.\\"*\\n\\n**Se aplica durante TODA la conversación**, no en un paso.\\n\\n**El mecanismo:** el cliente no puede evaluar tu producto todavía — no lo ha probado, no conoce tu empresa, no sabe si le van a cumplir. Lo único que sí puede evaluar desde el primer segundo **eres tú**. Y esa evaluación la hace mucho antes que la otra.\\n\\n**Y hace dos trabajos distintos, ambos indispensables:**\\n\\n**1 · Que te contesten de verdad.** Sin relación, las preguntas del Paso 3 reciben respuestas de cortesía. A un desconocido nadie le cuenta lo que le está fallando.\\n\\n**2 · Que te crean.** Este es el más importante y el que casi nadie ve.\\n\\n> Si un amigo te dice que un producto es bueno, le crees. Si te lo dice alguien que gana comisión por vendértelo, lo descuentas automáticamente — no porque lo creas mentiroso, sino porque sabes que tiene interés.\\n>\\n> **Es la misma frase, dicha por dos personas, y produce dos efectos opuestos.**\\n\\nLo que decide cuál de los dos efectos produces **no es tu argumento: es qué tan cerca estás de ser alguien en quien confía.** Por eso el CPR no es cortesía ni relleno — **es lo que determina si tus argumentos pesan o se descuentan.**\\n\\nY conecta directo con el Efecto Jones: la gente no confía en un desconocido incentivado a vender, pero sí deja que gente cercana valide un producto. **El CPR te acerca a ese lado de la línea.**\\n\\n### FORMS `FUENTE` `UNIVERSAL`\\n**F**amily · **O**ccupation · **R**ecreation · **M**otivation · **S**ports\\n\\nLos cinco caminos a la persona. Más cumplidos genuinos y chistes sencillos.\\n\\n> **La palabra que lo decide todo es *genuinos*.** Un interés fingido se nota, y cuesta más que no haber preguntado — porque ahora el cliente sabe que le aplicaste una técnica. Si un tema no te interesa de verdad, busca otro de los cinco.\\n\\n**No requiere cierta personalidad ni ser naturalmente extrovertido: se aprende.**\\n\\n### El desvío con regreso `CAMPO` `UNIVERSAL`\\nLa mecánica que hace que el CPR no mate la venta.\\n\\nSales de la línea a propósito, das **uno o dos intercambios personales**, y **regresas**. Puedes volver a salir más adelante, pero siempre avanzando.\\n\\n**Dos errores, ambos caros:**\\n- **Nunca salir** → no hay relación, y no te van a contestar nada en el Paso 3\\n- **Salir y no regresar** → el cliente se acomoda a platicar y la venta se estanca\\n\\n> **El cliente NUNCA te va a regresar a la línea.** Cuando la plática se pone agradable, él está cómodo — nadie interrumpe una conversación agradable para hablar de negocios. El único que puede regresar eres tú.\\n\\n### Bloqueo vs Objeción `FUENTE` — *la distinción que organiza todo el manejo de resistencia*\\n\\n**BLOQUEO** — un reflejo. Llega **ANTES** de entender.\\n*\\"No tengo tiempo\\" · \\"No me interesa\\" · \\"No estoy comprando nada\\" · \\"Ya tengo con quién\\"*\\nNo hubo procesamiento. Es la puerta cerrándose sola.\\n\\n**OBJECIÓN** — una preocupación razonada. Llega **DESPUÉS** de entender.\\n*\\"Está caro\\" · \\"Ya tengo proveedor y me cumple\\" · \\"Lo tengo que consultar\\"*\\nAquí sí hubo pensamiento.\\n\\n> **Por qué importa la diferencia:** discutir con un reflejo lo convierte en una posición. El cliente dijo \\"no me interesa\\" sin pensarlo; si lo peleas, tiene que defenderlo — y al defenderlo se lo cree. **Le acabas de crear un \\"no\\" real que no tenía.**\\n>\\n> E ignorar una objeción real ofende a alguien que sí te escuchó y sí pensó.\\n>\\n> **La misma frase se maneja de dos maneras opuestas según cuándo llegó.**\\n\\n### AIR `FUENTE` `UNIVERSAL`\\n**A**gree · **I**gnore · **R**esume — Acepta, Ignora, Resume\\n**Cuándo:** bloqueos al inicio.\\n**Cómo:** reconoce con *\\"entiendo\\"* o *\\"por supuesto\\"*, no lo discutas, y continúa.\\n\\n> **El tercer movimiento es el que falla.** Casi todos aceptan bien y casi todos logran no discutir — y después se quedan parados esperando, o peor, vuelven a pedir permiso. Ahí se pierde todo lo ganado.\\n\\n### Ataque Preventivo `FUENTE` `UNIVERSAL`\\n**Cuándo:** intro o historia breve, si hay negativos comunes del territorio.\\n**Cómo:** *\\"si das la negativa antes de que el cliente lo haga, ya no es una negativa.\\"*\\n\\n**El mecanismo:** le quitas el argumento de las manos, y además te vuelves creíble — **quien reconoce lo malo se gana el derecho a que le crean lo bueno.**\\n\\n**Dos formas de arruinarlo:**\\n- **En tono de disculpa** → deja de ser adelantarse y se vuelve defenderse de algo que nadie reclamó\\n- **Con un negativo inventado** → no desactivas nada, plantas una preocupación nueva\\n\\n### Close With Action `FUENTE (dentro de FFF) + CAMPO (generalizado)` `UNIVERSAL`\\n**Es el Poder de Sugestión en ejecución.**\\n\\nUna pregunta o acción cuya respuesta **solo tiene sentido si el cliente está avanzando**. Su respuesta *es* el sí. Nunca lo pides explícito.\\n\\n- *\\"¿Cómo se escribe su apellido?\\"* → al contestar, aceptó tu respuesta y sigue en el alta\\n- *\\"¿Prefiere el jueves o el viernes?\\"* → *\\"el viernes\\"* significa que lo quiere **y** cuándo\\n\\n**Se ejecuta en cada tramo de la línea:** en descubrimiento es la siguiente pregunta; en presentación es continuar donde ibas; en cierre es la alternativa de sí/sí.\\n\\n> **El momento crítico:** justo después de resolver algo. El vendedor promedio se queda callado esperando permiso para seguir. En ese silencio el cliente retoma el control y cierra la conversación con amabilidad. **No te está rechazando: le devolviste el volante.**\\n\\n---\\n\\n## PASO 3 · DESCUBRIMIENTO `CAMPO`\\n### *Encontrar el dolor real*\\n\\n*No existe como paso en la fuente. Toda esta sección es construcción de Closer sobre el principio de \\"preguntas de calificación\\".*\\n\\n### El principio rector\\n**Primero el examen, luego la receta.** El vendedor promedio llega a recetar: trae su producto favorito buscando dónde encajarlo. El Closer llega a diagnosticar.\\n\\n**La ironía:** el que pregunta vende más que el que habla.\\n\\n### RRR — Read, Relate, Relax `FUENTE` `UNIVERSAL`\\nLee · Conecta · Relaja.\\n\\nTres cosas que leer: **el ambiente, la demografía de la persona, y su estado de ánimo.**\\n\\n**El mecanismo:** no quieres forzar a nadie a subir a tu nivel de emoción ni a adaptarse a ti. **Tú te adaptas primero.**\\n\\n> ⚠️ **Colisión de acrónimos:** existe un segundo RRR en la doctrina (Repeat, Reassure, Resume) para objeciones. Ambos se conservan con su nombre original. Al enseñar el segundo hay que advertirlo explícitamente.\\n\\n### Los 3 Territorios del Dolor `CLOSER` `UNIVERSAL`\\nTodo dolor comercial vive en uno de tres territorios:\\n\\n- **PRODUCTO** — lo que vende o usa\\n- **SERVICIO** — cómo lo trata su proveedor actual\\n- **PRECIO** — lo que paga y lo que gana\\n\\n> **El mismo territorio se pregunta distinto según el tipo de cliente.** Ver Parte 4.\\n\\n#### Cómo se investiga el territorio PRECIO `CAMPO`\\n\\nEl territorio PRECIO es el más fácil de arruinar, porque la pregunta natural es la incorrecta.\\n\\n⚠️ **NUNCA le pidas al cliente su opinión ni su aprobación sobre precios.** Prohibido: *\\"¿cómo ve los precios?\\"*, *\\"¿hay algo que sienta muy arriba?\\"*, *\\"¿le parece competitivo?\\"*, *\\"¿estoy bien de precio?\\"*\\n\\n**Tres razones, y cada una basta:**\\n\\n**1. Le pides que construya una posición sobre tu precio antes de que exista valor.** Si contesta *\\"están caros\\"*, ya no es una impresión: es algo que declaró en voz alta y ahora tiene que defender. **Te creaste una objeción de precio que no existía.**\\n\\n**2. Cedes la autoridad sobre el precio.** El precio no lo determina la percepción del cliente: lo determina lo que ofreces. Preguntarle su opinión comunica que estás dispuesto a moverlo según lo que conteste, y te vuelve regateable antes de haber presentado nada.\\n\\n**3. Renuncias a tu ventaja.** Tú conoces el mercado: ya sabes qué está caro y qué está barato. **Muchas veces el cliente no sabe que está pagando de más, y tú sí.** Preguntarle su opinión te iguala a alguien que no sabe, cuando saber es exactamente lo que te hace valioso.\\n\\n**Lo que sí se investiga en este territorio son HECHOS, no opiniones:**\\n\\n- ¿A cómo compra hoy? (dato)\\n- ¿Cada cuánto le suben? ¿Le avisan antes? (dato)\\n- ¿Le manejan crédito o de contado? ¿Qué plazo? (dato)\\n- ¿Cuánto le queda de margen en esa línea? (dato)\\n- ¿Le ha tocado que un cliente se le vaya por precio? (experiencia, no opinión)\\n\\n**La diferencia:** un hecho te da información que puedes usar. Una opinión sobre tu precio te da una objeción que tendrás que atravesar.\\n\\n> **Y si el cliente dice que tu precio está mal, el diagnóstico correcto no es bajarlo.** Es que no encontraste su dolor, o no construiste suficiente valor. **El problema nunca está en el número: está en la balanza.**\\n\\n### La Escalera de Capas `CLOSER` `UNIVERSAL`\\n**CAPA 1 — Hechos.** Fáciles, cero riesgo. Abren la plática y te dan el mapa.\\n**CAPA 2 — La puerta.** Aquí el cliente suelta una pista... o cierra con un \\"bien\\". Depende de cómo preguntes.\\n**CAPA 3 — El dolor.** Solo se abre si recoges la pista y profundizas con preguntas abiertas.\\n\\n### La Pregunta Específica `CAMPO` `UNIVERSAL`\\n> **El \\"bien\\" no es información: es un reflejo social.**\\n\\nCuando preguntas *\\"¿qué tal le va?\\"*, el cliente no consulta su experiencia — dispara la respuesta cortés que trae cargada. Y admitir un problema ante un desconocido tiene costo social: parece queja, o parece que eligió mal.\\n\\n**La solución tiene dos formas:**\\n- **ESPECÍFICA** — nombra un dato o situación concreta que tenga que ir a buscar. *\\"¿Le ha tocado quedarse sin su producto estrella?\\"*\\n- **NORMALIZADA** — da permiso citando a otros. *\\"Varios clientes me comentan que batallan con faltantes, ¿a usted le pasa?\\"* (Es el Efecto Jones aplicado a descubrimiento.)\\n\\n**Y el orden importa:** concreta para **abrir** (capa 2), abierta para **excavar** (capa 3).\\n\\n#### Suggestive Language — dale de dónde agarrarse `FUENTE` `UNIVERSAL`\\n\\nEs la S de FUJIES aplicada al descubrimiento, y es lo que convierte una pregunta que se muere en una que da información.\\n\\n**El problema de la pregunta abierta sola:** obliga al cliente a construir la respuesta desde cero. Eso cuesta esfuerzo, y como no le urge ayudarte, contesta lo más corto que puede — o de plano *\\"pues no sé\\"*.\\n\\n**La solución: después de preguntar, sugiere opciones.**\\n\\n> *\\"¿Qué familias son las que más se te mueven? ¿Anticongelantes? ¿Aceite de motor? ¿Diésel? ¿Moto?\\"*\\n>\\n> *\\"¿A cómo compras el líquido de frenos? ¿70? ¿80? ¿90?\\"*\\n\\n**Por qué funciona, y son tres cosas a la vez:**\\n\\n1. **Le das de dónde agarrarse.** O elige una de tus opciones, o te corrige con el dato real — *\\"no, más bien 95\\"*. **Y esa corrección es información que la pregunta abierta nunca habría sacado.**\\n\\n2. **Le demuestras que conoces su negocio.** Nombrar las familias correctas o el rango de precio correcto te posiciona como alguien que sabe, no como alguien que está averiguando.\\n\\n3. **Crea un poco de urgencia.** Una pregunta con opciones se contesta rápido; una abierta se puede posponer con un *\\"déjame ver\\"*.\\n\\n**Cómo se usa bien:**\\n- Las opciones tienen que ser **reales y del giro del cliente**. Si sugieres familias que él no maneja, demuestras lo contrario de lo que buscabas.\\n- **Tres o cuatro, no una lista.** Es para ayudarlo a contestar, no para que elija de un catálogo.\\n- El rango de precio **tiene que ser creíble.** Sugerir cifras muy lejanas de la realidad te desacredita.\\n- Y **no lo uses para plantar una respuesta.** Si el cliente te corrige, esa es la respuesta buena — no insistas en la tuya.\\n\\n> **Es la misma lógica del cierre de alternativa, aplicada al descubrimiento:** no preguntas al aire, das opciones donde cualquier respuesta te sirve.\\n\\n### El Barrido `CLOSER` `UNIVERSAL`\\nTerritorio limpio → ni insistas ni te rindas: **cambia de territorio.**\\n\\nEl dolor casi siempre existe, solo que vive en otra zona del mapa. Insistir en zona sana te vuelve interrogador; rendirte regala la visita.\\n\\n### El dolor y la confirmación `CLOSER` `UNIVERSAL`\\nCuando el dolor aparece, **devuélveselo con SUS palabras**. *\\"Entonces lo que más le pega es X, ¿cierto?\\"*\\n\\nEso hace dos cosas: confirma que entendiste, y **le da forma consciente a algo que a lo mejor solo sentía.**\\n\\n> ⚠️ **Pero la confirmación explícita no es requisito para avanzar.**\\n>\\n> Muchas veces el cliente no va a admitir el problema. No porque no lo tenga — sino porque admitirlo suena a queja, o a que eligió mal, o simplemente porque **no lo tiene consciente**. Nadie anda por la vida con una lista de sus problemas operativos.\\n>\\n> Y aun así te sigue escuchando. **Eso ya es información.**\\n\\n**Lo que sí necesitas** es haber leído el problema con evidencia suficiente: algo que dijo, algo que viste, algo que su tipo de negocio hace probable. **Lo que no necesitas es su permiso verbal.**\\n\\n### La venta es emocional antes que racional `CAMPO`\\n\\nEste es el principio que corrige el error de modelar la venta como un proceso lógico.\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente no llena una hoja de cálculo: siente algo, y después construye la razón.\\n\\nConsecuencias que cambian cómo se ejecuta todo el sistema:\\n\\n- **Un cliente puede no reconocer un problema y aun así sentir alivio cuando se lo resuelves.** El impulso no viene de que aceptó el diagnóstico: viene de imaginar la situación resuelta.\\n- **Por eso \\"pintar imágenes\\" funciona** — no argumenta, hace sentir.\\n- **Por eso el vendedor no debe pelear por el reconocimiento explícito.** Insistir en que el cliente admita un problema lo pone a la defensiva y mata lo emocional, que era donde estaba la venta.\\n- **Y por eso el impulso se puede construir sin que haya un dolor declarado.** El 80% indiferente no tiene un problema urgente: se mueve por los factores de impulso, no por el diagnóstico.\\n\\n**La regla operativa:** si el cliente confirma el dolor, úsalo con sus palabras — es lo más fuerte que tienes. **Si no lo confirma pero la evidencia está, avanza igual**, presentando la situación resuelta en vez del problema reconocido.\\n\\n⚠️ **Lo que sigue prohibido es fabricar.** Leer un dolor probable no es inventarlo. La diferencia: leer se apoya en evidencia real — algo que dijo, algo que viste, algo propio de su giro. Fabricar es afirmar un problema **que el cliente ya negó** o del que no hay ningún indicio.\\n\\n### La regla del investigador\\n**El dolor nunca se pregunta directo.** *\\"¿Qué problemas tiene?\\"* produce *\\"ninguno\\"*, garantizado. Se deja emerger.\\n\\n### Luz Verde — 10/80/10 `FUENTE` `UNIVERSAL`\\n**10% negativos · 80% indiferentes · 10% positivos.**\\n\\n1. Sal de las luces rojas **rápido y educadamente**\\n2. Las amarillas reciben tu mejor presentación — pero si no dan señales de compra, muévete\\n3. Las verdes reciben tiempo, relación y resolución de dudas\\n\\n**Los factores de impulso existen principalmente para convertir al 80% indiferente.**\\n\\n#### El rojo verdadero y el que quiere pero no puede `CAMPO`\\n\\nLa luz roja no es cualquier \\"no\\". Es un tipo específico de cliente, y confundirlo cuesta ventas.\\n\\n**ROJO GENUINO** — no quiere. Es cortante, tajante, desganado. Muchas veces medio grosero. Y tiene un costo escondido: **interactuar de más con él desgasta tu actitud**, que es la variable de entrada de todo tu sistema. Con este, salir rápido y bien es la ejecución correcta.\\n\\n**AMARRADO TEMPORALMENTE** — quiere y no puede. Te recibe con gusto, te habla con honestidad, y su impedimento es una **circunstancia que va a cambiar**: un contrato de exclusividad, un inventario recién surtido, un presupuesto agotado, no ser él quien decide las compras grandes.\\n\\n> **Este no es rojo: es verde amarrado.** Y con él, rendirse es la falla más cara del oficio — porque ese cliente sí quería comprarte y el vendedor se fue solo.\\n\\n**Cómo se distinguen:** el rojo se nota en el trato. Es seco, no da información, quiere que te vayas. El amarrado hace lo contrario: es amable, te explica su situación con detalle, y muchas veces se disculpa por no poder.\\n\\n#### Casi toda restricción tiene bordes `CAMPO`\\n\\nY aquí está la mecánica que separa al vendedor promedio del que crece cuentas.\\n\\nCuando un cliente dice que no puede, **el promedio lo toma como total y se va**. El Closer investiga hasta dónde llega:\\n\\n- **¿Qué cubre exactamente?** Una exclusividad casi nunca abarca todas las familias\\n- **¿Qué queda fuera?** Ahí está la venta que la competencia no vio\\n- **¿Hasta cuándo dura?** Para volver justo cuando se libere, antes que nadie\\n\\n> Un contrato que cubre lubricantes, anticongelantes y grasas **deja fuera el líquido de frenos.** Y el vendedor que preguntó se lleva una venta de un cliente que \\"no podía comprar\\".\\n\\n**Y la relación sigue construyéndose mientras tanto.** Seguir visitando a un amarrado no es perder el tiempo: es estar presente el día que la restricción se acabe. El que se rindió no va a estar ahí.\\n\\n⚠️ **La línea:** investigar los bordes no es presionar. Si el cliente ya dijo que algo está dentro de su compromiso, insistir en eso es pedirle que rompa su palabra — y eso quema la relación. Se busca lo que **sí** puede, nunca se pelea lo que no.\\n\\n### QTQP `FUENTE` `UNIVERSAL`\\n**Q**uality **T**ime with **Q**uality **P**eople.\\n\\n> *\\"Perder tiempo y energía con las personas equivocadas destruye tu capacidad de ser lo suficientemente urgente\\"* — y la urgencia es de lo que vive tu ley de promedios.\\n\\nCada minuto con un rojo se lo quitas a un amarillo que sí podía comprar hoy.\\n\\n---\\n\\n## PASO 4 · PRESENTACIÓN\\n### *Construye valor y disminuye el costo*\\n\\n**Qué logra:** convertir el dolor descubierto en valor percibido, y subir el impulso.\\n\\n### Las herramientas de la presentación `FUENTE`\\n1. Encontrar problemas y proporcionar soluciones\\n2. **Pintar imágenes** — que imaginen que ya lo tienen\\n3. Incorporar factores de impulso\\n4. **Triple desglose de precios**\\n5. Hacer el valor enorme: lenguaje expansivo, *\\"gran\\"*, *\\"masivo\\"* `PRESENCIAL`\\n6. Hacer el costo pequeño: *\\"solo\\"*, *\\"apenas\\"* `PRESENCIAL`\\n7. **Tren del Sí** — preguntas cuya respuesta natural es sí\\n8. **CPR sostenido** durante toda la presentación\\n\\n### Beneficio, no característica `CLOSER` `UNIVERSAL`\\nUna característica es lo que el producto **es**. Nadie compra lo que algo es: compran **lo que van a ganar**.\\n\\nToda característica se traduce a una de tres cosas: **dinero** (gana más o gasta menos), **clientes** (vende más o los conserva), o **tranquilidad** (menos problemas, menos tiempo perdido).\\n\\n> Si el cliente puede contestar *\\"¿y eso a mí de qué me sirve?\\"*, la traducción falló.\\n\\n### Teoría de las Balas `FUENTE` `UNIVERSAL`\\n> *\\"La persona con más balas claramente tiene el control, siempre y cuando conserve su munición.\\"*\\n\\n**Las balas son TUYAS.** Son hechos positivos y concretos sobre:\\n- **Ti / tu empresa** — experiencia, premios, casos de éxito, dedicación\\n- **El producto** — lo que lo diferencia, mejoras, datos, certificaciones\\n- **El precio** — propuesta de valor, descuentos, financiamiento, comparación\\n\\n**La prueba de si algo es bala:** si la competencia puede decir exactamente lo mismo, no era bala. *\\"Somos los mejores\\"* es aire; *\\"catorce años surtiendo esta zona sin fallar\\"* es bala.\\n\\n**La regla de dosificación:** *\\"no dispares todas las balas al principio. Reserva algunas para que no importe cuántas balas tenga tu cliente, tengas más con qué responder. Guarda balas para los pasos 4 y 5.\\"*\\n\\n> **Por qué se guardan:** más adelante el cliente va a poner razones para no comprar. Eso baja su impulso. Responderle bien solo **detiene la caída** — lo que vuelve a subirlo es **una bala nueva**. Si las gastaste presumiendo al principio, llegas a ese momento con la mano vacía.\\n\\n### FUJIES / FUJPIG — Factores de Impulso `FUENTE`\\n*\\"El impulso es otra palabra para la emoción.\\"*\\n\\n| | Factor | Físico `PRESENCIAL` | Verbal `UNIVERSAL` |\\n|---|---|---|---|\\n| **F** | Fear of Loss / Miedo a la pérdida | Producto en mano y quitarlo, retroceder un paso | *\\"solo hoy\\"*, *\\"tiempo limitado\\"*, *\\"quedan pocas\\"* |\\n| **U** | Urgency / Urgencia | Tic-tac con el bolígrafo, empezar a alejarse | *\\"ahora\\"*, *\\"rápido\\"*, *\\"solo toma un par de minutos\\"* |\\n| **G** | Greed / Avaricia | Manos mostrando altos y bajos | *\\"normalmente $100, con la promo queda en solo $59.99\\"* |\\n| **I** | Indifference / Indiferencia | Postura, lenguaje corporal | SW3 |\\n| **E** | Effect of Jones / Efecto Jones | — | *\\"tengo como 20 clientes en esta zona que...\\"* |\\n| **S** | Suggestive Language / Poder de sugestión | Manos altas precio alto, bajas precio bajo | Tren del sí, alternativas |\\n\\n**Miedo a la pérdida > necesidad de ganancia.** La gente dice que sí impulsivamente porque no quiere que algo se le vaya.\\n\\n**Urgencia:** *\\"motion creates emotion\\"*. Y además comunica que estás ocupado, o sea que tienes éxito.\\n\\n**Indiferencia:** *\\"be excited about the person and the product, but indifferent whether they buy.\\"* **SW3** — Some Will, Some Won''t, So What. *\\"Ellos solo tienen una oportunidad de comprarte; tú tienes más de cien clientes.\\"*\\n\\n**Efecto Jones:** de *\\"keeping up with the Joneses\\"*. La gente no confía naturalmente en un desconocido incentivado a vender — pero sí deja que sus vecinos, amigos y familia validen el producto por ella.\\n\\n**Poder de sugestión — tres niveles:**\\n- **Mental** — *\\"asumo que todos son un sí hasta que me digan que no\\"*\\n- **Físico** — lenguaje corporal `PRESENCIAL`\\n- **Verbal** — el tren del sí. **El cliente debería decir que sí al menos 6 veces durante el proceso.**\\n\\n> **Elimina cualquier opción que se pueda traducir en un no.** En vez de *\\"¿quiere algo de tomar?\\"* → *\\"¿té, café o jugo?\\"*\\n\\n### La Curva de Impulso `FUENTE` `UNIVERSAL`\\nEl impulso sube y baja durante la conversación, y hay que construirlo **gradualmente** para no abrumar.\\n\\n**Las tres reglas de oro:**\\n1. **Encuentra al cliente en un punto común de emoción** al inicio, y construye desde ahí\\n2. **Cierra en el momento correcto** — el pico\\n3. **Elimina el arrepentimiento con un rehash impulsivo** — porque después del sí, el impulso cae\\n\\n#### La presentación tiene dos mitades `CAMPO`\\n\\nY confundirlas es un error común, así que conviene tenerlas separadas.\\n\\n**PRIMERA MITAD — lo que vas a hacer por él.**\\nConectas con su dolor usando SUS palabras, y explicas cómo se lo resuelves. Aquí no hay producto todavía: hay un problema y una solución. *\\"Eso que me dice de quedarse sin producto cuando le entra movimiento — eso es venta que se le va.\\"*\\n\\n**SEGUNDA MITAD — el producto y el precio.**\\nUn resumen breve de qué es lo que le va a resolver eso, y el Triple Desglose de Precios. De ahí se pasa directo al cierre.\\n\\n> **El precio SÍ va en la presentación.** Lo que va en el cierre es el **resumen del pedido** — qué y cuánto lleva. Son dos cosas distintas:\\n>\\n> · **Presentación** → el precio en escalera con sus motivos. *\\"Normalmente le sale en X, como es primer pedido queda en Y, y de contado en Z.\\"*\\n> · **Cierre** → lo que lleva. *\\"Entonces le van dos cajas de esto y una de aquello. ¿Jueves o viernes?\\"*\\n>\\n> Enumerar SKUs con cantidades en la presentación es escribir el cierre en el lugar equivocado. Pero omitir el precio es dejar la presentación a medias — y el cliente se queda esperando el número que nunca llegó.\\n\\n### Triple Desglose de Precios `FUENTE (definido) + CAMPO (desarrollado)` `UNIVERSAL`\\n> **Valor menos costo es igual a ahorro.**\\n\\n**La escalera — tres cifras bajando:**\\n1. **Lo que normalmente cuesta** — hace match con lo que el cliente ya esperaba\\n2. **Con el primer descuento** — cliente nuevo, volumen, lo que aplique\\n3. **Con el segundo** — pago de contado, cerrar hoy, lo que corresponda\\n\\n**El ahorro dicho en voz alta.**\\n\\n> **La regla que lo hace funcionar: cada escalón necesita un motivo nombrado.**\\n>\\n> Un precio que baja **sin razón** le dice al cliente que el primero estaba inflado — y te vuelve regateable, porque si bajó dos veces solo, va a bajar otra si presiona.\\n>\\n> Un precio que baja **por razones nombradas** confirma que el primero era real, y cada escalón se vuelve una bala de precio.\\n\\n**Por qué se ve y no solo se escucha:** *\\"queda en ochenta\\"* se escucha como un gasto de ochenta. *\\"Normalmente cien, con su descuento noventa, de contado ochenta\\"* se ve como veinte de ahorro que antes no existían. Mismo número final, sensación opuesta.\\n\\n**Y como el último escalón depende de algo que puede hacer HOY, aparece solo el miedo a la pérdida.**\\n\\n> ⚠️ **Nunca un solo precio.** Un precio suelto es un gasto sin ahorro visible que lo compense.\\n\\n---\\n\\n## PASO 5 · CIERRE\\n### *Extrae eficientemente una decisión*\\n\\n### Qué es un cierre `FUENTE`\\n> *\\"Un cierre no es algo que le haces a alguien. Un cierre es un acuerdo, cuando el cliente se da cuenta de que el beneficio supera al costo y decide. El cierre se lo hace la gente a sí misma.\\"*\\n\\n**Un cierre no siempre es una venta.** Es pedir la decisión, sea cual sea. Asegúrate de que tus conversaciones avancen hacia una conclusión — un sí o un no.\\n\\n### Asumir la venta `FUENTE` `UNIVERSAL`\\nSi llegaste a este punto, **presume que tienes un comprador**.\\n\\n**Malos cierres** — todos invitan al no:\\n*¿Le gustaría comprar? · ¿Está interesado? · ¿Le gusta lo que oye? · ¿Qué le parece? · ¿Cómo lo ve?*\\n\\n**Buenos cierres** — alternativas donde ambas opciones sirven:\\n*¿Es su nombre el que va en la cuenta? · Las primeras fechas de entrega son jueves o viernes, ¿cuál le conviene? · ¿Visa o MasterCard? · ¿Contado o crédito?*\\n\\n> **El diagnóstico de la fuente:** *\\"la mayoría de las personas que batallan para cerrar simplemente no están rompiendo la zona de confort que viene con pedir algo.\\"*\\n>\\n> Y: *\\"aumentas la probabilidad de que compren mientras más confiadamente anuncies tu mensaje.\\"*\\n\\n### El silencio después del cierre `CAMPO` `UNIVERSAL`\\nNo llenes el silencio. Pediste la decisión: **aguanta**.\\n\\nEl vendedor que retira la pregunta, la suaviza o la contesta él mismo, pierde. El primero que habla después de un cierre, pierde.\\n\\n### FISHBBOD — Señales de Compra `FUENTE`\\nTambién llamadas **STOP signs**. En cuanto reconoces una, **DETIENES la presentación y CIERRAS**.\\n\\n**F** Future talk · **I** I want / I need · **S** Silence · **H** How much / How soon · **B** Body language `PRESENCIAL` · **B** Bashing competitor · **O** Offers of courtesy · **D** Deeper questions\\n\\n> **El error que cuesta más ventas de lo que nadie cree:** el cliente da la señal, el vendedor la ve, y como todavía le quedaban dos argumentos buenos, los suelta.\\n>\\n> **El impulso baja.** Porque el cliente ya estaba listo, y seguir vendiéndole le comunica que hay algo que convencerlo — o le da tiempo de encontrar una razón para no hacerlo.\\n>\\n> Señal de compra = deja de presentar y cierra. **Aunque te queden balas. De hecho, sobre todo si te quedan.**\\n\\n---\\n\\n## MANEJO DE OBJECIONES `FUENTE`\\n### *No son negativas: son preguntas que, bien respondidas, terminan en venta*\\n\\n**Objeción = señal de compra.** El que no tiene interés no objeta: se despide.\\n\\n### Las cuatro técnicas de overturn\\n\\n| Técnica | Cuándo | Cómo |\\n|---|---|---|\\n| **AIR** — Agree, Ignore, Resume | Bloqueos en la introducción | Reconoce, ignora, continúa |\\n| **Ataque Preventivo** | Intro o historia breve, negativos conocidos del territorio | Da el negativo antes que el cliente |\\n| **RRR** — Repeat, Reassure, Resume | Objeciones menores y comunes | Repite, responde, **continúa sin pausa** |\\n| **FFF** — Feel, Felt, Found | Preocupación seria o personal | Nunca discutas |\\n\\n### RRR de objeciones `FUENTE` `UNIVERSAL`\\n**R**epeat — repite la objeción en sus términos, para que vea que la escuchaste\\n**R**eassure — la respuesta concreta, con datos\\n**R**esume — **retoma sin pausa**\\n\\n> **La tercera R es la que falla.** El vendedor responde bien y se queda callado esperando a ver si convenció. En ese espacio el cliente encuentra la siguiente objeción, o dice que lo va a pensar.\\n\\n### FFF — el procedimiento completo `FUENTE` `UNIVERSAL`\\n**Nunca discutas con un cliente.** Ganar la discusión es perder la venta.\\n\\nEn español: **Entiendo · Sintió · Encontramos**\\n\\n1. **\\"Entiendo cómo se siente\\"** — estar de acuerdo te vuelve distinto del vendedor promedio, **y por eso te escuchan**\\n2. **\\"Mi último cliente sentía lo mismo\\"** — para que sepa que no está solo\\n3. **\\"Lo que encontramos fue...\\"** — por qué dejaron de pensar así. **Esto usa Efecto Jones**\\n4. **Inserta 3 balas** de la Teoría de las Balas\\n5. **Close With Action**\\n\\n> ⚠️ **FFF no termina en la tercera F.** El documento en español del sistema fuente está truncado y solo llega al paso 3 — por eso mucha gente aprendió un FFF incompleto, sin re-impulso y sin cierre. **Los pasos 4 y 5 son el Círculo de Cierre.**\\n\\n### El Círculo de Cierre `FUENTE (implícito) + CAMPO (nombrado)` `UNIVERSAL`\\n\\n```\\n   CLOSE WITH ACTION ←──────────────┐\\n            ↓                        │\\n   ¿Objeción? → el impulso baja      │\\n            ↓                        │\\n   Atraviesas (RRR o FFF)            │\\n            ↓                        │\\n   RE-IMPULSAS con una bala NUEVA ───┘\\n```\\n\\n> **El error más común: atravesar la objeción y cerrar de inmediato, saltándose la bala.**\\n>\\n> Técnicamente respondiste. Pero **atravesar solo detiene la caída del impulso** — no lo sube. Estás pidiendo una decisión en el punto más bajo de la conversación, y desde ahí la respuesta cómoda siempre es *\\"déjeme lo pienso\\"*.\\n\\n**Y la bala tiene que ser NUEVA.** Repetir un argumento ya usado no sube nada: comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.\\n\\n### La Regla de los No\\n- **Fuente:** *2 no''s and a go* — dos no seguidos, luz roja, sigue adelante\\n- **Campo `CAMPO`:** Emilio usa **3 no seguidos**, porque hay gente que deja ir un sí solo porque el cliente tuvo preguntas u objeciones\\n\\n> **Tienen que ser CONSECUTIVOS.** Un no, lo atraviesas, la conversación avanza, y más adelante otro no: **eso no es una racha**. Es una conversación normal con dos momentos de fricción. La racha se rompe en cuanto la conversación avanza.\\n\\n---\\n\\n## PASO 6 · CONSOLIDACIÓN / REHASH\\n### *El paso final y más importante*\\n\\n**REHASH** = **R**emember **E**veryone **H**as **A**nother **S**ale **H**idden\\n\\n**Dos propósitos** `FUENTE`:\\n1. **Capitalizar a un cliente ya positivo** — *\\"la gente compra de sus amigos mucho más fácil que de un desconocido\\"*\\n2. **Dejarlo positivo y entendiendo los siguientes pasos** — *\\"la causa número uno de cancelaciones es la falta de entendimiento\\"*\\n\\n### El arrepentimiento del comprador\\nApenas dice que sí, **el impulso cae**. El cerebro empieza a buscar razones por las que quizá no debió. Es automático y no es desconfianza hacia ti.\\n\\n### Cómo se disuelve `CAMPO`\\n> **El error que parece lo correcto: seguir vendiendo.**\\n>\\n> La reacción natural es reforzar la compra — recordarle lo bueno del producto, repetirle el ahorro, insistir en que tomó una gran decisión.\\n>\\n> **Y eso lo empeora.** Seguir vendiendo después del sí le dice al cliente que **necesitabas la venta**. Y si la necesitabas, entonces la indiferencia era actuada. Y si la indiferencia era actuada, también el interés por su negocio, también las preguntas, también la plática de su hijo.\\n>\\n> **Retroactivamente, toda la conversación se convierte en una técnica.**\\n\\n**Lo que sí funciona: demostrar que nada cambió en ti.**\\n\\nMisma indiferencia sobre la compra. Misma calidez sobre la relación. Cero producto. Y la confianza de que ahí vas a estar para lo que necesite.\\n\\n**Por qué funciona:** si tu actitud es idéntica antes y después de la firma, el cliente concluye solo lo que ninguna frase habría logrado convencerlo — **que no lo trataste así para venderle, sino porque así eres.** Y con esa conclusión, el arrepentimiento no tiene de qué agarrarse.\\n\\n**Y deja claro qué sigue.** La falta de entendimiento es la causa número uno de cancelaciones.\\n\\n---","is_active":false,"created_at":"2026-09-26T21:43:44.070314+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"3a259e8d-eb96-42d6-9f65-014b6becda1a","version":4,"section_key":"mentalidad","order_index":3,"title":"PARTE 3 · LA MENTALIDAD","body":"# PARTE 3 · LA MENTALIDAD\\n### *La segunda fundación*\\n\\n> *\\"No importa qué tan buenas sean tus habilidades conversacionales, nunca vas a tener 100% de éxito.\\"*\\n>\\n> Y: *\\"hay gente con mucha personalidad o experiencia que triunfa sin trabajar bien la ley de promedios — pero no puede replicar su éxito, porque depende demasiado de la habilidad.\\"*\\n\\n**La mentalidad no es motivación: es el sistema de control que hace replicable el resultado.**\\n\\n## Ley de Promedios (LDP) `FUENTE`\\n> *\\"Si repites una acción las veces suficientes, aparecerá una proporción.\\"*\\n\\nEs un sistema probado para **encontrar compradores entre los no compradores**.\\n\\n**La analogía de la moneda:** lanzas una vez, 50/50. Lanzas diez veces y raramente sale 5 y 5. Pero mientras más lanzas, más se acerca la muestra a la proporción real. **La ley necesita volumen para manifestarse.**\\n\\n## PPA — lo que afecta tu ley de promedios `FUENTE`\\n**P**itch / Conversación — preciso, conciso, impactante\\n**P**ace / Ritmo — con cuánta gente hablas\\n**A**ttitude / Actitud — consistentemente positiva\\n\\n> **La cadena causal, y por qué la mentalidad no es opcional:**\\n> La ley de promedios necesita volumen. El volumen desgasta la actitud. La actitud degrada el pitch. Y el pitch es la variable de entrada del sistema.\\n>\\n> **Por eso KILT, los 3 tipos de día, controlables y gumball existen: protegen la única variable que el vendedor controla.**\\n\\n## Los 3 Tipos de Día `FUENTE`\\n- **Día A** — las ventas llegan temprano, la actitud es fácil\\n- **Día B** — llegan esporádicamente, no te prueba del todo\\n- **Día C** — todas llegan en las últimas horas. **La verdadera prueba de quién cree en el sistema**\\n\\n*Ejemplo real: 3 ventas de 60 contactos es normal — 5% de éxito. Es normal no tener ningún cliente hasta el final del día y aun así cumplir.*\\n\\n## Teoría del Gumball `FUENTE`\\nTres máquinas, 100 dulces cada una, 97 rojos y 3 verdes. Cada intento cuesta un peso. Tienes 100 pesos y la meta de sacar 3 verdes.\\n\\n**Mantén tu pitch, ritmo y actitud iguales, para que cada \\"no\\" te acerque al \\"sí\\".**\\n\\n> **La dificultad real:** en el campo no puedes ver dónde están los verdes como en la máquina. Tienes que seguir girando a ciegas, sabiendo que tu proporción va a aparecer.\\n\\n## Controlables vs No Controlables `FUENTE`\\n> *\\"Si no podemos controlarlo, no lo pensamos ni lo hablamos. Es una pérdida de tiempo y energía.\\"*\\n\\nLa mayoría pasa el día culpando cosas que no controla. Concentrarse en lo controlable es mucho más productivo: ver más gente, tener mejores conversaciones, cuidar la actitud.\\n\\n## KILT `FUENTE`\\n**K**ill them with kindness — sé amable sin importar la actitud del otro\\n**I**ndifference — algunos comprarán, otros no, ¿y qué?\\n**L**aw of averages — confía en los números\\n**T**reat everyone like your first — nunca sabes cuándo aparece tu cliente\\n\\n**Aplicación:** si dejamos a cada persona mejor de como la encontramos, permanecemos indiferentes al sí o al no, y tratamos a cada quien como el primero, entonces protegemos la actitud.\\n\\n## Los 8 Grandes Hábitos `FUENTE`\\n*\\"Somos lo que hacemos repetidamente; el éxito es un hábito.\\"*\\n\\n1. **Tener gran actitud** — el negocio es 99% actitud y 1% habilidad\\n2. **Ser puntual** — si no llegas temprano, llegas tarde\\n3. **Estar preparado** — fallar en prepararse es prepararse para fallar\\n4. **Esfuerzo del 100%** — recibes lo que pones\\n5. **Maximizar tu territorio** — tu territorio no es el lugar, **son las personas**\\n6. **Proteger tu actitud** — cada \\"no\\" te acerca al \\"sí\\"\\n7. **Conocer tu porqué** — metas de corto, mediano y largo plazo\\n8. **Tomar el control** — de tu día, tu carrera y tu vida\\n\\n## Indicadores / Gauges `FUENTE`\\nMiden con cuánta gente hablas y qué tan lejos llegas en los pasos.\\n\\n**Puertas → Con cuántos hablaste → Presentaciones → Cierres**\\n\\n**Para qué sirven:**\\n1. Identificar dónde **podría** romperse el sistema en tus 6 pasos\\n2. Asegurar que trabajas el sistema\\n3. Marcarte el ritmo\\n\\n> ⚠️ **Los indicadores señalan DÓNDE MIRAR, no qué está mal.**\\n>\\n> Si presentas a muchos y cierras a pocos, el número te dice que algo pasa **entre la presentación y el cierre** — pero la causa puede estar mucho antes. Puede ser que el descubrimiento no encontró el dolor real, que no hubo suficiente CPR y el cliente nunca contestó de verdad, que la presentación se alargó y cayó en KILL, que el impulso se construyó mal, o que efectivamente el cierre es débil.\\n>\\n> **Un número no diagnostica una causa.** Diagnostica una zona.\\n\\n**El diagnóstico real requiere ver la conversación.** Como manager: acompañando al vendedor en campo, o pidiéndole una práctica en Closer sobre el paso donde sospechas.\\n\\n**Números + conversación observada = conclusión.** Cualquiera de los dos solo, es especulación.\\n\\n## Metas — SMART `FUENTE`\\n**S**pecific · **M**easurable · **A**ttainable · **R**ealistic · **T**imed\\n\\nTipos: de **resultado** · de **acción** · corto plazo (<2 meses) · mediano (2 meses–3 años) · largo (3+ años)\\n\\nEscríbelas, hazlas evaluar por alguien, y recompénsate al lograrlas.\\n\\n---","is_active":false,"created_at":"2026-09-26T21:43:44.070314+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"3fe3a82d-ca94-4409-8b00-86ba7a9c1a10","version":4,"section_key":"aplicacion","order_index":4,"title":"PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE","body":"# PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE\\n\\n> **El sistema es el esqueleto. Si se entiende, se aplica a cualquier cliente, cualquier industria y cualquier producto.**\\n\\nEsta parte NO es un catálogo de casos. Es la demostración de cómo se deduce la ejecución correcta a partir de los principios — para que cualquier caso que no esté aquí se resuelva igual.\\n\\n## 4.0 El método de adaptación\\n\\nCada paso existe para lograr algo. **Lo que cambia entre clientes no es el objetivo del paso: es lo que hace falta para lograrlo.**\\n\\nEjemplo con la Historia Breve. Su objetivo es liberar el segundo tercio de atención — las dos preguntas que el cliente trae en la cabeza: *quién eres* y *por qué estás aquí*.\\n\\n- Con un desconocido, las dos están abiertas → contestas las dos\\n- Con alguien que te conoce hace años, la primera ya está contestada → **solo queda el porqué de hoy**, y a veces hasta eso es obvio\\n\\n**La conclusión operativa, dicha completa:** con un cliente que ya te conoce, la Historia Breve **NO incluye tu nombre ni el de tu empresa**. Nada de \\"Soy Juan, de [empresa]\\", ni \\"trabajamos con tal marca\\". Él ya lo sabe. Repetírselo le comunica que no lo reconoces o que estás recitando un guion — y en los dos casos daña la relación que llevas años construyendo.\\n\\nLo único que queda es **por qué viniste HOY**, en una o dos frases. Y a veces hasta eso es evidente.\\n\\nEse es el método. Ante cualquier cliente, en cualquier industria:\\n\\n1. ¿Qué **objetivo** tiene este paso?\\n2. ¿Qué de ese objetivo **ya está resuelto** con este cliente?\\n3. ¿Qué **falta** por resolver?\\n4. **Ejecuta solo eso, y escribe solo eso.**\\n\\n> ⚠️ **El paso 4 es donde más se falla.** Deducir correctamente qué falta y aun así escribir la versión completa por costumbre es el error más frecuente al aplicar este método. Si concluiste que algo ya está resuelto, **ese algo no aparece en el texto.** No basta con saberlo: hay que omitirlo.\\n\\n## 4.0b Autoconsumo y distribuidor NO son un tercer eje `CAMPO`\\n\\nHay una confusión fácil de cometer: tratar \\"autoconsumo\\" y \\"distribuidor\\" como si fueran alternativas a \\"nuevo\\" y \\"recurrente\\". No lo son. **Son ejes distintos.**\\n\\n**EJE 1 — ¿Ya te compra?** Nuevo o recurrente. Esto define **la relación**: si te conoces, si hay historial, si hay pedido base.\\n\\n**EJE 2 — ¿Qué hace con el producto?** Revende, consume o distribuye. Esto define **las preguntas**: qué se le pregunta en cada territorio.\\n\\n**Se cruzan.** Un cliente de autoconsumo puede ser nuevo (nunca te ha comprado) o recurrente (lleva años surtiéndose contigo). Y la ejecución cambia según el cruce:\\n\\n| | Nuevo | Recurrente |\\n|---|---|---|\\n| **Revende** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Consume** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Distribuye** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n\\n> **Lo que cambia por el EJE 1** es si te presentas, si hay \\"lo de siempre\\", y si buscas dolor o hueco.\\n>\\n> **Lo que cambia por el EJE 2** es únicamente el vocabulario del descubrimiento: al que revende le preguntas qué maneja y qué le piden; al que consume, qué usa y cada cuánto repone; al que distribuye, sus líneas y a cuántos surte.\\n\\n**Error concreto que esto evita:** escribir la historia breve de un cliente de autoconsumo como si fuera recurrente — *\\"vine a ver cómo les funcionó lo que dejamos la vez pasada\\"* — cuando nunca ha habido una vez pasada. Autoconsumo no dice nada sobre si ya te compra o no.\\n\\n**Y una vez que un cliente de autoconsumo te compra, se vuelve recurrente**: el seguimiento y el crecimiento de esa cuenta funcionan igual que con cualquier otro recurrente. Buscas huecos, cierras el incremento, y no te vuelves a presentar.\\n\\n## 4.1 Lo que sí cambia sustancialmente\\n\\nHay dos diferencias que no son obvias y que sí conviene tener explícitas, porque cambian **qué se busca**, no solo cómo se dice.\\n\\n### Diferencia 1 — Qué buscas en el Descubrimiento\\n\\n**DOLOR** — algo anda mal. Tiene señal verbal: **el \\"aunque\\"**. Se busca con los 3 Territorios y la escalera de capas.\\n\\n**HUECO** — algo que podría comprarte y no te compra. **No tiene señal verbal: se ve, no se oye.**\\n\\n> Un cliente conforme no tiene dolor. **Por eso el vendedor que solo sabe buscar dolor visita durante años sin crecer una cuenta**: busca, no encuentra, y concluye correctamente que no hay nada.\\n\\n**Las tres herramientas del hueco:**\\n\\n**1 · Lee el lugar** — lo que ves te dice qué maneja y de quién. Un producto de otra marca es un espacio ocupado; un estante vacío es una familia que nadie cubre; algo empolvado no es hueco, **es dolor**.\\n\\n**2 · Pregunta por lo que le piden** — *\\"¿le ha tocado que le pidan algo que no maneje?\\"* Demanda que ya existe sin oferta que la cubra.\\n\\n**3 · Ancla en negocios como el suyo** — Efecto Jones aplicado. Solo si es verdad y lo puedes sostener.\\n\\n**Adaptación por canal:** presencial observas; a distancia preguntas por el catálogo. **Adaptación por giro:** si el cliente no revende, \\"lo que ves\\" no es un mostrador — son sus unidades, su patio, su operación.\\n\\n> **La línea que no se cruza:** un hueco tiene que ser real y verificable. **Descubrir un hueco es señalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.**\\n\\n### Diferencia 2 — Qué estás cerrando\\n\\nCon un cliente que ya compra, **el pedido base no está en duda: ya iba a existir.** Lo que se cierra es **lo que se agrega**.\\n\\nReabrir el pedido base al cerrar pone sobre la mesa algo que ya estaba resuelto, e invita al cliente a revisar toda la orden.\\n\\n## 4.1b La observación del recurrente no puede sonar a primera visita `CAMPO`\\n\\nEl SCE y el ice breaker siguen aplicando con un cliente de años. Lo que cambia es **de qué se observa**.\\n\\n**El error:** *\\"¿Siempre está así de lleno o hoy le tocó día pesado?\\"*\\n\\nEsa pregunta la hace alguien que no conoce el lugar. Y este vendedor lleva años pasando cada quincena — **ya sabe si el negocio es movido.** Preguntarlo le comunica al cliente que no lo tiene presente, que es lo contrario de lo que la relación construyó.\\n\\n**Lo correcto: observar lo que CAMBIÓ desde la última visita.**\\n\\n> *\\"Oiga, ¿ya le entró más gente que la vez pasada, verdad?\\"*\\n> *\\"Veo que le movió al acomodo desde que vine.\\"*\\n> *\\"¿Ya se compuso lo del clima o siguen igual de flojas las tardes?\\"*\\n\\nY también funciona lo personal, que con un desconocido no puedes usar:\\n\\n> *\\"¿Cómo salió su muchacho de lo que me contó?\\"*\\n> *\\"¿Le fue bien en el puente?\\"*\\n\\n> **La prueba:** si tu observación de apertura funcionaría igual con un cliente que ves por primera vez, no está aprovechando la relación. **Con un recurrente, la apertura demuestra memoria** — y esa memoria es el activo que llevas años construyendo.\\n\\n⚠️ **Y esto solo funciona si la memoria es real.** Inventar que recuerdas algo que no pasó es peor que no recordar nada. Si no tienes un dato de la visita anterior, observa el momento presente sin fingir historia: *\\"se ve movido hoy\\"* es honesto; *\\"¿siempre está así?\\"* no lo es.\\n\\n## 4.2 Lo que NO cambia nunca\\n\\n- El orden de los 6 pasos\\n- Que el descubrimiento va antes de la presentación\\n- Que el cierre asume en vez de pedir aprobación\\n- Que el precio va en escalera con motivo\\n- Que no hay frases neutras\\n- Toda la Parte 6 (jerarquía de reglas)\\n\\n## 4.3 Presentar un hueco `CAMPO`\\n\\nCuando lo que encontraste es un hueco, no hay nada que resolver: el cliente está conforme. Hay un espacio que ocupar.\\n\\n**La pregunta que define el argumento: ¿qué gana él con que tú se lo surtas?**\\n\\nY la respuesta depende del caso, no de una fórmula. Posibilidades reales:\\n\\n- **Consolidación** — si el cliente trata con muchos proveedores y eso le pesa, reducir el número tiene valor por sí mismo\\n- **Conveniencia** — te ve de todos modos; agregar una familia no le suma trabajo\\n- **Complementariedad** — lo que ofreces se usa junto con lo que ya te compra\\n- **Una condición concreta** — plazo, disponibilidad, presentación, tiempo de entrega\\n\\n> ⚠️ **La consolidación NO es un argumento universal.** Si tu producto es complementario y el cliente ya tiene cinco proveedores, con la familia nueva pasa a tener **seis, no cuatro**. Ahí *\\"menos proveedores que seguir\\"* es falso, y usarlo te desacredita.\\n>\\n> Antes de usarlo, verifica que el cliente **efectivamente vaya a reducir** su número de proveedores.\\n\\n⚠️ **Nunca ataques al proveedor actual.** Criticarlo es criticar la decisión del cliente, y la gente defiende sus decisiones.\\n\\n⚠️ **No afirmes ventajas que no puedes verificar.** *\\"El otro no maneja esta línea\\"*, *\\"nadie tiene nuestro catálogo\\"*, *\\"con nosotros le sale mejor\\"* — si no lo sabes de cierto, no lo digas. Puede ser falso, y en una cuenta de años se descubre siempre. **Habla de lo que TÚ ofreces, con hechos que puedas sostener.**\\n\\n## 4.4 Convicción sin garantía `CAMPO`\\n\\n> **Nunca le pidas que \\"pruebe\\".**\\n>\\n> *\\"Le pongo unas pocas para que lo pruebe\\"* suena humilde y es lo peor que puedes decir: **le pasas el riesgo a él.** La gente no quiere experimentar — está cómoda donde está, y probar algo nuevo es riesgo, incomodidad y la posibilidad de haberse equivocado.\\n\\n**El trabajo del vendedor no es pedir permiso para experimentar. Es hacer que el cliente se sienta seguro.** Dos movimientos:\\n\\n1. **Convicción, sin garantía** — *\\"no le puedo garantizar nada, pero estoy seguro de que le va a servir\\"*\\n   **Funciona precisamente porque reconoce el límite.** Admitir lo que no controlas hace creíble lo que sí afirmas.\\n\\n2. **La razón detrás** — *\\"se lo digo porque en negocios como el suyo es de lo que más sale\\"*\\n   Sin la razón, tu convicción es solo optimismo de vendedor.\\n\\n**Y ahí te callas.**\\n\\n⚠️ **No ofrezcas el plan B.** *\\"Y si no funciona lo ajustamos\\"* parece que baja el riesgo y hace lo contrario: **le mete una duda que no tenía**, y desmiente lo que acabas de afirmar. Si de verdad estás seguro, ¿para qué el paracaídas?\\n\\n*(Si después no funciona, ahí lo ajustas. Eso es Consolidación y se hace cuando pasa — no se anuncia por adelantado.)*\\n\\n## 4.5 El capital del récord `CAMPO`\\n\\n> **La primera vez que recomiendas algo, el cliente compra por la relación. La segunda vez, compra por tu récord.**\\n\\nY eso disciplina: si recomiendas algo que no funciona, **no perdiste una venta — gastaste crédito que te costó años juntar.** Por eso solo se recomienda lo que de verdad sirve a ese perfil, aunque haya cosas con mejor margen.\\n\\n## 4.6 Los dos juegos `CAMPO`\\n\\n**ADQUISICIÓN** — convertir a un desconocido en cliente.\\n**DESARROLLO** — convertir a un cliente en un cliente más grande.\\n\\n> **La asimetría que explica por qué el segundo se descuida:** adquisición da retroalimentación inmediata — vendes o no vendes. Desarrollo no. Puedes visitar cien veces, levantar el mismo pedido, sentir que hiciste bien tu trabajo, y nunca enterarte de lo que dejaste sobre la mesa.\\n>\\n> **El fracaso en desarrollo es invisible.**\\n\\n**El enemigo: la visita que se vuelve trámite.** El vendedor está haciendo adquisición con alguien que ya adquirió — y como no hay nada que adquirir, no hay nada que hacer.\\n\\n> **Al que solo toma pedidos lo reemplaza un formulario.**\\n\\n---","is_active":false,"created_at":"2026-09-26T21:43:44.070314+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"de1e900e-8381-494a-9206-df2be20eab24","version":4,"section_key":"canales","order_index":5,"title":"PARTE 5 · MODIFICADORES DE CANAL","body":"# PARTE 5 · MODIFICADORES DE CANAL\\n\\n| Canal | Qué se conserva | Qué se adapta |\\n|---|---|---|\\n| **Presencial** | Todo | — |\\n| **Teléfono** | Los 6 pasos, KISS, FORMS, las 4 técnicas de overturn, balas, FUJIES verbales, CWA, triple desglose, y el **entusiasmo del tono** | Contacto visual → pausas y ritmo. Todo lo físico se pierde |\\n| **WhatsApp / mensaje** | La estructura completa, balas, triple desglose, ataque preventivo | Mensajes cortos, uno por idea. Señales de compra → velocidad de respuesta, emojis, preguntas de precio. El cierre debe contestarse con una palabra |\\n| **Correo** | Estructura, KISS, balas, triple desglose | Todo lo interactivo se vuelve secuencia |\\n\\n> **El principio de adaptación: entender qué HACE cada técnica permite encontrar su equivalente en cualquier medio.**\\n>\\n> El miedo a la pérdida no es *\\"quitar el producto de la mano\\"* — es **crear la sensación de que algo se va**. Eso existe en los cuatro canales.\\n\\n---","is_active":false,"created_at":"2026-09-26T21:43:44.070314+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"e18ede6a-ddae-4cb5-a2ec-e99058989955","version":4,"section_key":"jerarquia","order_index":6,"title":"PARTE 6 · JERARQUÍA DE REGLAS","body":"# PARTE 6 · JERARQUÍA DE REGLAS\\n\\nCuando dos principios chocan, gana el de mayor jerarquía.\\n\\n## NIVEL 1 — Inviolables (ética y verdad)\\nNunca se rompen, en ningún contexto, por ninguna razón.\\n\\n1. **Impulso falso está prohibido.** Urgencia inventada, escasez que no existe, prueba social fabricada. *(Práctico, no solo moral: un impulso falso se derrumba cuando el cliente lo descubre, y se lleva la venta, la relación y tu reputación en la zona.)*\\n2. **No garantizar lo que no controlas.** Convicción sí; garantía no.\\n3. **No fabricar un hueco ni un dolor.** Descubrir es señalar lo que existe.\\n4. **No atacar al competidor ni al proveedor actual.**\\n5. **No afirmar ventajas que no puedes verificar.** *\\"Nadie más tiene esto\\"*, *\\"el otro no lo maneja\\"*, *\\"con nosotros sale mejor\\"* — si no lo sabes de cierto, no lo dices. Habla de lo que TÚ ofreces.\\n6. **Nunca discutir con un cliente.**\\n\\n## NIVEL 2 — Estructurales\\nSe rompen solo si el Nivel 1 lo exige.\\n\\n7. **El orden de los 6 pasos.** No se salta ninguno.\\n8. **Primero el examen, luego la receta.** No presentar sin diagnosticar.\\n9. **El cierre asume, no pide aprobación.** Toda pregunta que permita aprobar o posponer entrega el control.\\n10. **El precio va en escalera con motivo en cada escalón.** Nunca un solo número.\\n11. **No hay frases neutras.** Si algo resta valor y nadie lo preguntó, se omite.\\n12. **Señal de compra = detente y cierra.**\\n13. **Se sale de la línea, pero siempre se regresa.**\\n14. **Nunca pidas opinión ni aprobación sobre el precio.** Ni el tuyo ni el de la competencia. Preguntar *\\"¿cómo ve los precios?\\"* le pide al cliente que construya una posición contra ti antes de que exista valor, cede tu autoridad sobre el precio, y renuncia a tu ventaja — porque tú conoces el mercado y él muchas veces no. En el territorio PRECIO se investigan **hechos** (a cómo compra, qué plazo tiene, cada cuánto le suben), nunca opiniones.\\n\\n## NIVEL 3 — Contextuales\\nDependen del tipo de cliente, canal o situación. **Se deducen del método de la Parte 4.0, no se memorizan.**\\n\\n14. Qué parte de la Historia Breve hace falta — depende de qué ya sabe el cliente\\n15. Buscar dolor o buscar hueco — depende de si el cliente está conforme\\n16. Qué argumento usar al presentar un hueco — depende de qué gana él en ESE caso\\n17. Cerrar la venta o cerrar el incremento — depende de si hay un pedido base\\n18. SEE físico — solo presencial\\n\\n## NIVEL 4 — Estilo\\nAjustables al lenguaje del vendedor, la zona y la empresa.\\n\\nTono, vocabulario, longitud de frases, formalidad. **El manager conoce el lenguaje de su gente mejor que Closer.**\\n\\n---","is_active":false,"created_at":"2026-09-26T21:43:44.070314+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"1bfa7b49-1ede-4c77-9c3d-25a7b9c84bb8","version":4,"section_key":"razonamiento","order_index":7,"title":"PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO","body":"# PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO\\n\\n## Ante un caso no cubierto\\n1. Identifica **qué paso** de la línea es\\n2. Pregunta **qué objetivo tiene ese paso**\\n3. Pregunta **qué de ese objetivo ya está resuelto** con este cliente, y qué falta\\n4. Verifica contra la **jerarquía**: ¿viola algo de Nivel 1 o 2?\\n5. Si sigue sin resolverse, **di que no lo sabes.** No inventes doctrina.\\n\\n## Ejemplos de deducción\\n\\n**Caso:** un vendedor pregunta si puede decir *\\"¿le late?\\"* al cerrar.\\n**Razonamiento:** es una pregunta que permite aprobar o posponer → viola la regla 9 (Nivel 2) → **no**. La alternativa es una pregunta donde ambas opciones sirvan.\\n\\n**Caso:** un manager quiere que el pitch mencione que un producto no trae promoción este mes.\\n**Razonamiento:** no hay frases neutras (1.3); esto baja el valor percibido; nadie lo preguntó → **se omite**. Regla 11, Nivel 2.\\n\\n**Caso:** un vendedor pregunta cómo abrir con un cliente que le compra desde hace cinco años.\\n**Razonamiento:** aplica el método 4.0. Objetivo de la Historia Breve = contestar *quién eres* y *por qué estás aquí*. Lo primero ya está resuelto → **solo queda el porqué de hoy**, y a veces hasta eso es evidente. No hace falta una regla especial: sale del objetivo del paso.\\n\\n**Caso:** vender un servicio de software por videollamada a una empresa que nunca lo ha usado.\\n**Razonamiento:** el sistema aplica igual. Cliente nuevo → doctrina de adquisición. Canal remoto → SEE físico no aplica, pero el entusiasmo del tono sí. \\"Lee el lugar\\" no existe, así que se pregunta. Los 3 Territorios se traducen: producto = qué usan hoy, servicio = cómo los atiende su proveedor, precio = qué pagan. **Nada del esqueleto cambia.**\\n\\n**Caso:** un vendedor dice que el cliente no le reconoce ningún problema, pero él ve claro que sí lo tiene.\\n**Razonamiento:** aplica 1.5. La confirmación explícita no es requisito. Si hay evidencia real — algo que dijo, algo que vio, algo propio de su giro — **avanza presentando la situación resuelta**, no el problema reconocido. Insistir en que lo admita lo pone a la defensiva y apaga lo emocional, que es donde está la venta. **El límite:** si el cliente ya negó explícitamente ese problema, insistir es fabricar, y eso es Nivel 1.\\n\\n**Caso:** un vendedor lleva tres días sin cerrar y está desanimado.\\n**Razonamiento:** esto es Parte 3, no Parte 2. Aplica Ley de Promedios, los 3 Tipos de Día (día C), gumball, y controlables vs no controlables. **No es un problema de técnica: es de protección de la actitud, que es la variable de entrada del sistema.**\\n\\n**Caso:** un manager ve que su vendedor presenta mucho y cierra poco, y quiere saber qué corregir.\\n**Razonamiento:** el indicador señala una zona, no una causa. Puede ser el cierre, pero también un descubrimiento que no encontró el dolor real, CPR insuficiente, o una presentación que se alargó y cayó en KILL. **Números + conversación observada.** Pídele una práctica o acompáñalo en campo antes de concluir.\\n\\n## Sobre la incertidumbre\\nEste documento tiene procedencia marcada por una razón: **lo que está como `CAMPO` no se puede verificar contra la fuente.** Si un caso depende de doctrina `CAMPO` y hay duda, la autoridad es Emilio, no la inferencia.\\n\\n**Nunca completes un hueco de doctrina inventando.** Di qué falta y pídelo.\\n\\n**Y nunca inventes un hecho comercial** — una ventaja, una comparación con la competencia, un dato de mercado. Eso no es doctrina: es información de la empresa, y si no está en su contexto, se pide.","is_active":false,"created_at":"2026-09-26T21:43:44.070314+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"606cc20b-468a-444a-bd9d-5ba24e7e87cd","version":5,"section_key":"fundamento","order_index":1,"title":"PARTE 1 · EL FUNDAMENTO","body":"# EL CEREBRO DE CLOSER\\n## Doctrina canónica del sistema de venta\\n\\n*Versión 1.0 · Fuente única de verdad*\\n\\n---\\n\\n## CÓMO USAR ESTE DOCUMENTO\\n\\nEsto no es un manual ni un resumen. Es el entendimiento del sistema, escrito para que se pueda **razonar** con él.\\n\\nCada técnica se presenta con tres cosas: **qué es**, **por qué funciona** (el mecanismo humano detrás) y **qué la rompe**. El porqué importa más que el qué, porque de él se deducen los casos que ninguna lista cubre.\\n\\nEjemplo de la diferencia: una lista diría *\\"no digas «¿cómo lo ves?»\\"*. Este documento dice *\\"toda pregunta que permita aprobar o posponer le entrega el control al cliente\\"* — de donde se deduce que *\\"¿le late?\\"*, *\\"¿qué opina?\\"* y *\\"¿le parece?\\"* también están mal, aunque nadie los haya escrito nunca.\\n\\n**Regla de razonamiento:** ante un caso que este documento no cubre explícitamente, no inventes. Busca el principio que aplica y dedúcelo. Si dos principios chocan, gana el de mayor jerarquía (ver Parte 6).\\n\\n### Etiquetas\\n\\n**PROCEDENCIA** — `FUENTE` (sistema original Credico/Cydcor) · `CAMPO` (evolución de Emilio Fanjul) · `CLOSER` (andamiaje pedagógico)\\n\\n**CANAL** — `PRESENCIAL` (requiere cuerpo o presencia) · `UNIVERSAL` (funciona en persona, teléfono, mensaje o correo)\\n\\n---\\n\\n---\\n\\n# PARTE 1 · EL FUNDAMENTO\\n\\n## 1.1 El problema que resuelve todo el sistema `FUENTE`\\n\\nCuando abres una conversación con un desconocido, **su atención está dividida en tres**:\\n\\n- **Un tercio** sigue en lo que estaba haciendo\\n- **Un tercio** está resolviendo preguntas básicas: quién eres, qué quieres, por qué me hablas\\n- **Solo un tercio** está disponible para ti\\n\\n> **De aquí sale la razón de ser de los 6 pasos:** si vas directo a presentar, le estás hablando a un tercio de una persona. Cada paso previo existe para recuperar una porción de esa atención.\\n\\nLa Introducción libera el primer tercio (deja de pensar en lo que hacía). La Historia Breve libera el segundo (ya sabe quién eres y a qué vienes). Solo entonces tienes casi toda su atención — y solo entonces vale la pena presentar.\\n\\n**Esto explica por qué saltarse pasos no acelera nada: presentarle a alguien distraído es desperdiciar tu mejor material.**\\n\\n## 1.2 La Línea Recta `CAMPO` `UNIVERSAL`\\n\\nUna venta avanza en línea recta, de izquierda a derecha, a través de los 6 pasos.\\n\\n**Nada te regresa. Lo que ya recorriste, quedó.** Lo único que puede pasar es que algo te **saque de la línea y te pause**.\\n\\nLa imagen: vas dibujando la línea hacia la derecha y de pronto llega una objeción. Ahí dejas de avanzar y la línea sube — saliste. Pero no retrocede. Está en ti resolver y volver al punto donde ibas.\\n\\n| Elemento | Relación con la línea |\\n|---|---|\\n| Los 6 pasos | La línea misma |\\n| CPR / FORMS | Salida **deliberada** — sales tú, y regresas |\\n| Bloqueos → AIR, Ataque Preventivo | Salida **impuesta** al inicio |\\n| Objeciones → RRR, FFF | Salida **impuesta** después de entender |\\n| Close With Action | Lo que te devuelve y te mueve al siguiente tramo |\\n| Los 3 No seguidos | La señal de que ya no hay línea que recorrer |\\n\\n**Diagnóstico que le da al vendedor:** cuando una visita sale mal, la pregunta no es *\\"¿qué técnica olvidé?\\"* sino **\\"¿dónde salí de la línea y por qué no regresé?\\"**\\n\\n## 1.3 El principio de la balanza `FUENTE` `UNIVERSAL`\\n\\nNadie compra por precio. Compra cuando el **valor percibido** pesa más que el **costo percibido**. Cuanto mayor la brecha, mayor el impulso.\\n\\nY el costo no es solo dinero: es tiempo, riesgo de cambiar, esfuerzo, y la posibilidad de haberse equivocado.\\n\\n> **La regla que convierte esto en herramienta:** con cada frase, cada gesto y cada silencio estás haciendo una de cuatro cosas — subiendo el valor, bajándolo, subiendo el costo, o bajándolo.\\n>\\n> **No hay frases neutras.**\\n\\nDe aquí se deducen cosas que ninguna lista de reglas contiene:\\n- Titubear al dar un precio sube el costo percibido\\n- Disculparte baja tu valor\\n- Mencionar algo que **no** tienes, no aplica o no está disponible **baja el valor sin que nadie te lo pidiera** — y por eso se omite\\n- Contar un caso real de otro cliente sube el valor\\n\\n**Cost vs Value no es tanto una habilidad como una herramienta de evaluación:** revisa cada parte de tu conversación y pregúntate qué plato movió.\\n\\n## 1.4 La gente compra, pero no quiere que le vendan `FUENTE`\\n\\nEste es el principio psicológico que atraviesa todo el sistema.\\n\\nA las personas les gusta comprar. Lo que les desagrada es **sentir que les están vendiendo**. Tienen una alarma calibrada para detectar al vendedor, y en cuanto se activa, todo lo que digas después se procesa con desconfianza.\\n\\n> **Casi todas las técnicas de este sistema son formas de obtener un resultado de venta sin activar esa alarma.**\\n\\n- **Gasman** — pedir permiso te delata como forastero; asumir que perteneces no dispara nada\\n- **CPR** — ser persona antes que vendedor\\n- **Descubrimiento** — el vendedor promedio habla; el que pregunta rompe el patrón que la alarma busca\\n- **Close With Action** — nunca pides el sí, porque pedirlo enciende la alarma\\n- **Indiferencia** — la presión genera resistencia; quitarla la disuelve\\n- **FFF** — estar de acuerdo primero te vuelve distinto del vendedor promedio, *y por eso te escuchan*\\n\\n## 1.5 La decisión es emocional antes que racional `CAMPO`\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente siente algo primero, y después construye la razón que lo justifica.\\n\\nEsto no contradice el diagnóstico ni la construcción de valor: los explica. La doctrina fuente lo dice sin rodeos — **\\"el impulso es otra palabra para la emoción\\"**.\\n\\n**Lo que se deduce de aquí, y que corrige el error de modelar la venta como un proceso lógico:**\\n\\n- **El cliente no necesita reconocer un problema para sentir el alivio de resolverlo.** Por eso \\"pintar imágenes\\" funciona: no argumenta, hace sentir.\\n- **Pelear por el reconocimiento explícito mata la venta.** Insistir en que admita algo lo pone a la defensiva, y la defensiva apaga lo emocional — que era donde estaba la venta.\\n- **El 80% indiferente no tiene un problema urgente**, y aun así compra. Se mueve por los factores de impulso, no por el diagnóstico.\\n- **Un argumento perfecto dicho por alguien en quien no confía, no pesa.** Y uno mediocre dicho por alguien cercano, sí. De ahí la importancia real del CPR.\\n\\n> **La regla operativa:** el sistema construye una situación deseable, no un caso lógico. La razón sirve para que el cliente pueda **justificar** la decisión — no para que la tome.\\n\\n⚠️ **Y esto no autoriza a manipular.** El Nivel 1 sigue intacto: el impulso se construye con verdad. La diferencia es que construir una imagen real y deseable es legítimo; fabricar urgencia, escasez o problemas no lo es.\\n\\n---\\n\\n## 1.6 Sin groserías `CAMPO` `UNIVERSAL`\\n\\nCloser no dice groserías, y el vendedor no las necesita. Las groserías no hacen falta para comunicar lo que quieres decir, y en la mayoría de las empresas le quitan profesionalidad al vendedor. Si el cliente las usa, no hace falta imitarlo para conectar: se conecta con interés genuino y con el sistema, no con el lenguaje.","is_active":false,"created_at":"2026-09-29T17:14:32.375719+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"52a161f0-9883-46ba-a44f-812390badcdc","version":5,"section_key":"pasos","order_index":2,"title":"PARTE 2 · LOS 6 PASOS","body":"# PARTE 2 · LOS 6 PASOS\\n\\nEl sistema original tiene **5 pasos** `FUENTE`: Introducción, Historia Breve, Presentación, Cierre, Consolidación.\\n\\nCloser enseña **6** `CAMPO`: se separa **Descubrimiento** como paso propio. En la fuente las preguntas de calificación viven dentro del flujo; separarlas reconoce que diagnosticar y presentar son habilidades distintas que fallan por razones distintas.\\n\\n---\\n\\n## PASO 1 · INTRODUCCIÓN\\n### *Una sola oportunidad para una primera impresión*\\n\\n**Qué logra:** liberar el primer tercio de atención y ganarte el derecho a seguir hablando.\\n\\n**Qué NO es:** aquí no dices quién eres ni a qué vienes. Eso es el Paso 2. Confundirlos es el error doctrinal más común.\\n\\n### SEE / SCE `FUENTE` `PRESENCIAL`\\n**S**mile · **E**ye contact · **E**nthusiasm — Sonrisa, Contacto visual, Entusiasmo\\n\\n- **Sonrisa** — signo internacional de amistad. Elimina el miedo y crea confianza.\\n- **Contacto visual** — genera confianza, mantiene el control de la conversación, **y es una señal de compra fuerte cuando el cliente lo hace**.\\n- **Entusiasmo** — crea impulso y curiosidad. Si estás emocionado, asumen que hablas de algo emocionante. **Y al revés también funciona:** si suenas aburrido de tu producto, nadie va a estar más emocionado que tú.\\n\\nSe combinan con **lenguaje corporal abierto** y **tono de voz fuerte**.\\n\\n> ⚠️ **Límite de canal:** SEE es físico. En texto o voz no se puede evaluar. Se enseña, se pide, y se marca como *\\"esto se practica en persona\\"*. Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**.\\n\\n### Regla del 10% `FUENTE` `PRESENCIAL`\\nLee el nivel de emoción del cliente y ponte **10% por encima** de él. No al doble: 10%.\\n\\n**Por qué:** llegar gritando con alguien tranquilo lo aleja tanto como llegar apagado con alguien entusiasmado. El 10% jala sin romper.\\n\\n### Ice Breaker `FUENTE` `UNIVERSAL`\\nCumplido genuino, chiste sencillo o comentario ligero.\\n\\nPuede ser sobre **la persona**, **el lugar**, o **algo en común**. No está atado a ningún tipo de negocio.\\n\\n**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee al instante y se cierra **más** que antes — porque ahora sabe que le están aplicando una técnica.\\n\\n### La escalera de la especificidad `CAMPO` `UNIVERSAL`\\n\\nLa observación y la pregunta de la apertura se miden igual: **¿se la harías a cualquiera?** Entre más específica para ESE cliente en ESE momento, más vale.\\n\\n- **Escalón 1 — de cortesía.** Se la harías a cualquiera: *\\"¿cómo está?\\"*, *\\"qué gusto saludarlo\\"*. Cumple lo mínimo porque le devuelve la palabra, pero no construye nada.\\n- **Escalón 2 — del entorno.** Sale de lo que ves ahí, en ese momento: *\\"veo que no paran, ¿siempre está así de movido?\\"*. Solo tiene sentido en ese lugar.\\n- **Escalón 3 — de él.** Solo se la harías a él, porque sabes algo de antes: *\\"¿cómo sigue? ¿va mejorando?\\"*.\\n\\n**La prueba del escalón 2:** nombra algo concreto que viste ahí —el movimiento, que está lleno, un cambio, algo nuevo—. Un adjetivo genérico, como *\\"qué bien se ve el local\\"* o *\\"qué bonito\\"*, se lo dirías a cualquiera: es escalón 1.\\n\\n> **Las mismas palabras pueden estar en escalones distintos.** *\\"¿Cómo está?\\"* a secas es escalón 1; *\\"¿cómo está? ¿va mejorando?\\"* a alguien que estuvo enfermo es escalón 3. Lo que sube el escalón no son las palabras: es qué tanto sabe la pregunta de él.\\n\\n**La relación cambia la escalera.** Con un cliente nuevo no existe el escalón 3 —no hay historia con él—, así que el escalón 2 es la excelencia. Con un recurrente la meta es el escalón 3, y el 2 puede ser un error: preguntarle si siempre está así de movido a alguien que visitas desde hace años le dice que no lo tienes presente (ver 4.1b).\\n\\n**Una pregunta de cortesía no es una falla: es el primer escalón.** La falla es no preguntar nada: sin ninguna pregunta, el cliente no tiene qué contestar y la conversación se muere ahí.\\n\\n**Y la pregunta que mejor devuelve la palabra es la que sale de la observación y cierra la apertura:** *\\"veo que no paran, ¿siempre está así de movido?\\"*. Un *\\"¿cómo está?\\"* dentro del saludo cumple, pero si después sigues hablando, el cliente espera a que termines en vez de contestar. Convertir la observación en la pregunta final es como se sube de escalón.\\n\\n### Especificidad y ligereza son dos cosas distintas `CAMPO` `UNIVERSAL`\\n\\nUn comentario de apertura se mide con dos preguntas diferentes. **¿Se lo dirías a cualquiera?** es la especificidad: la escalera. **¿Baja la guardia?** es la ligereza: humor suave, un guiño o calidez en lo que dices.\\n\\nUna no garantiza la otra. *\\"Veo que tiene cuatro cajas de filtros de una marca y dos de otra\\"* es muy específico, y suena a inspección. *\\"¡Qué buen día hace, eh!\\"* es ligero, y se lo dirías a cualquiera. *\\"¿Qué les pasó hoy que está lleno? ¿Regalan algo o qué?\\"* tiene las dos.\\n\\n**La ligereza se mide en lo que haces, no en cómo reacciona el cliente.** Un buen chiste puede no hacerle gracia a un cliente rojo, o a alguien que viene enojado ese día, y no por eso se hizo mal. La reacción del cliente puede confirmar que algo funcionó; nunca puede condenar una acción bien hecha. Es la lógica de los controlables: al vendedor se le mide por lo que controla, y el humor del cliente no es una de esas cosas.\\n\\nLa calidez que vive en el tono de voz no se puede calificar por escrito: se enseña igual, se practica igual, y la escucha el manager (ver 1.7).\\n\\n### Teoría del Gasman `FUENTE` `UNIVERSAL`\\nSer asumido y confiado, con alta indiferencia.\\n\\nEl gasista que viene a leer tu medidor entra con una autoridad que nace de sentir que **debe estar ahí** — no es una intrusión. Nadie lo detiene, y no es por su permiso: es por su postura.\\n\\n> **El mecanismo:** cuando preguntas *\\"¿tiene un minutito?\\"* haces dos cosas a la vez — le entregas el control, y le ofreces una salida que no le cuesta nada tomar. El cliente que dice \\"ahorita no\\" no está siendo grosero: tomó la puerta que le abriste.\\n>\\n> **La autoridad no se pide. Se asume.**\\n\\n### Regla doctrinal del paso `CAMPO`\\n**La identificación (nombre y empresa) es permitida pero nunca requerida aquí.** Su ausencia jamás se penaliza.\\n\\nSi el cliente pregunta *\\"¿y usted quién es?\\"*, **ganaste la introducción** — esa pregunta es la puerta natural al Paso 2, no una falla.\\n\\n---\\n\\n## PASO 2 · HISTORIA BREVE\\n### *Explica tu propósito de manera concisa*\\n\\n**Qué logra:** liberar el segundo tercio de atención. El cliente deja de preguntarse quién eres y qué quieres.\\n\\n### KISS vs KILL `FUENTE` `UNIVERSAL`\\n**K**eep **I**t **S**hort and **S**imple — contra **K**eep **I**t **L**ong and **L**engthy.\\n\\nQuién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible.\\n\\n> **El mecanismo:** cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él — y de los discursos uno se defiende.\\n\\n**Y después de la historia, preguntas.** La fuente es explícita: *\\"en la mayoría de los casos es más efectivo pasar directamente a las preguntas de calificación que dar una larga explicación.\\"*\\n\\nTu historia breve no existe para que te entiendan a ti. **Existe para ganarte el derecho de preguntarle a él.**\\n\\n### CPR — Create Personal Relations `FUENTE` `UNIVERSAL`\\n> *\\"Eres tanto, si no más, el producto que los productos que representas.\\"*\\n\\n**Se aplica durante TODA la conversación**, no en un paso.\\n\\n**El mecanismo:** el cliente no puede evaluar tu producto todavía — no lo ha probado, no conoce tu empresa, no sabe si le van a cumplir. Lo único que sí puede evaluar desde el primer segundo **eres tú**. Y esa evaluación la hace mucho antes que la otra.\\n\\n**Y hace dos trabajos distintos, ambos indispensables:**\\n\\n**1 · Que te contesten de verdad.** Sin relación, las preguntas del Paso 3 reciben respuestas de cortesía. A un desconocido nadie le cuenta lo que le está fallando.\\n\\n**2 · Que te crean.** Este es el más importante y el que casi nadie ve.\\n\\n> Si un amigo te dice que un producto es bueno, le crees. Si te lo dice alguien que gana comisión por vendértelo, lo descuentas automáticamente — no porque lo creas mentiroso, sino porque sabes que tiene interés.\\n>\\n> **Es la misma frase, dicha por dos personas, y produce dos efectos opuestos.**\\n\\nLo que decide cuál de los dos efectos produces **no es tu argumento: es qué tan cerca estás de ser alguien en quien confía.** Por eso el CPR no es cortesía ni relleno — **es lo que determina si tus argumentos pesan o se descuentan.**\\n\\nY conecta directo con el Efecto Jones: la gente no confía en un desconocido incentivado a vender, pero sí deja que gente cercana valide un producto. **El CPR te acerca a ese lado de la línea.**\\n\\n### FORMS `FUENTE` `UNIVERSAL`\\n**F**amily · **O**ccupation · **R**ecreation · **M**otivation · **S**ports\\n\\nLos cinco caminos a la persona. Más cumplidos genuinos y chistes sencillos.\\n\\n> **La palabra que lo decide todo es *genuinos*.** Un interés fingido se nota, y cuesta más que no haber preguntado — porque ahora el cliente sabe que le aplicaste una técnica. Si un tema no te interesa de verdad, busca otro de los cinco.\\n\\n**No requiere cierta personalidad ni ser naturalmente extrovertido: se aprende.**\\n\\n### El desvío con regreso `CAMPO` `UNIVERSAL`\\nLa mecánica que hace que el CPR no mate la venta.\\n\\nSales de la línea a propósito, das **uno o dos intercambios personales**, y **regresas**. Puedes volver a salir más adelante, pero siempre avanzando.\\n\\n**Dos errores, ambos caros:**\\n- **Nunca salir** → no hay relación, y no te van a contestar nada en el Paso 3\\n- **Salir y no regresar** → el cliente se acomoda a platicar y la venta se estanca\\n\\n> **El cliente NUNCA te va a regresar a la línea.** Cuando la plática se pone agradable, él está cómodo — nadie interrumpe una conversación agradable para hablar de negocios. El único que puede regresar eres tú.\\n\\n### Bloqueo vs Objeción `FUENTE` — *la distinción que organiza todo el manejo de resistencia*\\n\\n**BLOQUEO** — un reflejo. Llega **ANTES** de entender.\\n*\\"No tengo tiempo\\" · \\"No me interesa\\" · \\"No estoy comprando nada\\" · \\"Ya tengo con quién\\"*\\nNo hubo procesamiento. Es la puerta cerrándose sola.\\n\\n**OBJECIÓN** — una preocupación razonada. Llega **DESPUÉS** de entender.\\n*\\"Está caro\\" · \\"Ya tengo proveedor y me cumple\\" · \\"Lo tengo que consultar\\"*\\nAquí sí hubo pensamiento.\\n\\n> **Por qué importa la diferencia:** discutir con un reflejo lo convierte en una posición. El cliente dijo \\"no me interesa\\" sin pensarlo; si lo peleas, tiene que defenderlo — y al defenderlo se lo cree. **Le acabas de crear un \\"no\\" real que no tenía.**\\n>\\n> E ignorar una objeción real ofende a alguien que sí te escuchó y sí pensó.\\n>\\n> **La misma frase se maneja de dos maneras opuestas según cuándo llegó.**\\n\\n### AIR `FUENTE` `UNIVERSAL`\\n**A**gree · **I**gnore · **R**esume — Acepta, Ignora, Resume\\n**Cuándo:** bloqueos al inicio.\\n**Cómo:** reconoce con *\\"entiendo\\"* o *\\"por supuesto\\"*, no lo discutas, y continúa.\\n\\n> **El tercer movimiento es el que falla.** Casi todos aceptan bien y casi todos logran no discutir — y después se quedan parados esperando, o peor, vuelven a pedir permiso. Ahí se pierde todo lo ganado.\\n\\n### Ataque Preventivo `FUENTE` `UNIVERSAL`\\n**Cuándo:** intro o historia breve, si hay negativos comunes del territorio.\\n**Cómo:** *\\"si das la negativa antes de que el cliente lo haga, ya no es una negativa.\\"*\\n\\n**El mecanismo:** le quitas el argumento de las manos, y además te vuelves creíble — **quien reconoce lo malo se gana el derecho a que le crean lo bueno.**\\n\\n**Dos formas de arruinarlo:**\\n- **En tono de disculpa** → deja de ser adelantarse y se vuelve defenderse de algo que nadie reclamó\\n- **Con un negativo inventado** → no desactivas nada, plantas una preocupación nueva\\n\\n### Close With Action `FUENTE (dentro de FFF) + CAMPO (generalizado)` `UNIVERSAL`\\n**Es el Poder de Sugestión en ejecución.**\\n\\nUna pregunta o acción cuya respuesta **solo tiene sentido si el cliente está avanzando**. Su respuesta *es* el sí. Nunca lo pides explícito.\\n\\n- *\\"¿Cómo se escribe su apellido?\\"* → al contestar, aceptó tu respuesta y sigue en el alta\\n- *\\"¿Prefiere el jueves o el viernes?\\"* → *\\"el viernes\\"* significa que lo quiere **y** cuándo\\n\\n**Se ejecuta en cada tramo de la línea:** en descubrimiento es la siguiente pregunta; en presentación es continuar donde ibas; en cierre es la alternativa de sí/sí.\\n\\n> **El momento crítico:** justo después de resolver algo. El vendedor promedio se queda callado esperando permiso para seguir. En ese silencio el cliente retoma el control y cierra la conversación con amabilidad. **No te está rechazando: le devolviste el volante.**\\n\\n---\\n\\n## PASO 3 · DESCUBRIMIENTO `CAMPO`\\n### *Encontrar el dolor real*\\n\\n*No existe como paso en la fuente. Toda esta sección es construcción de Closer sobre el principio de \\"preguntas de calificación\\".*\\n\\n### El principio rector\\n**Primero el examen, luego la receta.** El vendedor promedio llega a recetar: trae su producto favorito buscando dónde encajarlo. El Closer llega a diagnosticar.\\n\\n**La ironía:** el que pregunta vende más que el que habla.\\n\\n### RRR — Read, Relate, Relax `FUENTE` `UNIVERSAL`\\nLee · Conecta · Relaja.\\n\\nTres cosas que leer: **el ambiente, la demografía de la persona, y su estado de ánimo.**\\n\\n**El mecanismo:** no quieres forzar a nadie a subir a tu nivel de emoción ni a adaptarse a ti. **Tú te adaptas primero.**\\n\\n> ⚠️ **Colisión de acrónimos:** existe un segundo RRR en la doctrina (Repeat, Reassure, Resume) para objeciones. Ambos se conservan con su nombre original. Al enseñar el segundo hay que advertirlo explícitamente.\\n\\n### Los 3 Territorios del Dolor `CLOSER` `UNIVERSAL`\\nTodo dolor comercial vive en uno de tres territorios:\\n\\n- **PRODUCTO** — lo que vende o usa\\n- **SERVICIO** — cómo lo trata su proveedor actual\\n- **PRECIO** — lo que paga y lo que gana\\n\\n> **El mismo territorio se pregunta distinto según el tipo de cliente.** Ver Parte 4.\\n\\n#### Cómo se investiga el territorio PRECIO `CAMPO`\\n\\nEl territorio PRECIO es el más fácil de arruinar, porque la pregunta natural es la incorrecta.\\n\\n⚠️ **NUNCA le pidas al cliente su opinión ni su aprobación sobre precios.** Prohibido: *\\"¿cómo ve los precios?\\"*, *\\"¿hay algo que sienta muy arriba?\\"*, *\\"¿le parece competitivo?\\"*, *\\"¿estoy bien de precio?\\"*\\n\\n**Tres razones, y cada una basta:**\\n\\n**1. Le pides que construya una posición sobre tu precio antes de que exista valor.** Si contesta *\\"están caros\\"*, ya no es una impresión: es algo que declaró en voz alta y ahora tiene que defender. **Te creaste una objeción de precio que no existía.**\\n\\n**2. Cedes la autoridad sobre el precio.** El precio no lo determina la percepción del cliente: lo determina lo que ofreces. Preguntarle su opinión comunica que estás dispuesto a moverlo según lo que conteste, y te vuelve regateable antes de haber presentado nada.\\n\\n**3. Renuncias a tu ventaja.** Tú conoces el mercado: ya sabes qué está caro y qué está barato. **Muchas veces el cliente no sabe que está pagando de más, y tú sí.** Preguntarle su opinión te iguala a alguien que no sabe, cuando saber es exactamente lo que te hace valioso.\\n\\n**Lo que sí se investiga en este territorio son HECHOS, no opiniones:**\\n\\n- ¿A cómo compra hoy? (dato)\\n- ¿Cada cuánto le suben? ¿Le avisan antes? (dato)\\n- ¿Le manejan crédito o de contado? ¿Qué plazo? (dato)\\n- ¿Cuánto le queda de margen en esa línea? (dato)\\n- ¿Le ha tocado que un cliente se le vaya por precio? (experiencia, no opinión)\\n\\n**La diferencia:** un hecho te da información que puedes usar. Una opinión sobre tu precio te da una objeción que tendrás que atravesar.\\n\\n> **Y si el cliente dice que tu precio está mal, el diagnóstico correcto no es bajarlo.** Es que no encontraste su dolor, o no construiste suficiente valor. **El problema nunca está en el número: está en la balanza.**\\n\\n### La Escalera de Capas `CLOSER` `UNIVERSAL`\\n**CAPA 1 — Hechos.** Fáciles, cero riesgo. Abren la plática y te dan el mapa.\\n**CAPA 2 — La puerta.** Aquí el cliente suelta una pista... o cierra con un \\"bien\\". Depende de cómo preguntes.\\n**CAPA 3 — El dolor.** Solo se abre si recoges la pista y profundizas con preguntas abiertas.\\n\\n### La Pregunta Específica `CAMPO` `UNIVERSAL`\\n> **El \\"bien\\" no es información: es un reflejo social.**\\n\\nCuando preguntas *\\"¿qué tal le va?\\"*, el cliente no consulta su experiencia — dispara la respuesta cortés que trae cargada. Y admitir un problema ante un desconocido tiene costo social: parece queja, o parece que eligió mal.\\n\\n**La solución tiene dos formas:**\\n- **ESPECÍFICA** — nombra un dato o situación concreta que tenga que ir a buscar. *\\"¿Le ha tocado quedarse sin su producto estrella?\\"*\\n- **NORMALIZADA** — da permiso citando a otros. *\\"Varios clientes me comentan que batallan con faltantes, ¿a usted le pasa?\\"* (Es el Efecto Jones aplicado a descubrimiento.)\\n\\n**Y el orden importa:** concreta para **abrir** (capa 2), abierta para **excavar** (capa 3).\\n\\n#### Suggestive Language — dale de dónde agarrarse `FUENTE` `UNIVERSAL`\\n\\nEs la S de FUJIES aplicada al descubrimiento, y es lo que convierte una pregunta que se muere en una que da información.\\n\\n**El problema de la pregunta abierta sola:** obliga al cliente a construir la respuesta desde cero. Eso cuesta esfuerzo, y como no le urge ayudarte, contesta lo más corto que puede — o de plano *\\"pues no sé\\"*.\\n\\n**La solución: después de preguntar, sugiere opciones.**\\n\\n> *\\"¿Qué familias son las que más se te mueven? ¿Anticongelantes? ¿Aceite de motor? ¿Diésel? ¿Moto?\\"*\\n>\\n> *\\"¿A cómo compras el líquido de frenos? ¿70? ¿80? ¿90?\\"*\\n\\n**Por qué funciona, y son tres cosas a la vez:**\\n\\n1. **Le das de dónde agarrarse.** O elige una de tus opciones, o te corrige con el dato real — *\\"no, más bien 95\\"*. **Y esa corrección es información que la pregunta abierta nunca habría sacado.**\\n\\n2. **Le demuestras que conoces su negocio.** Nombrar las familias correctas o el rango de precio correcto te posiciona como alguien que sabe, no como alguien que está averiguando.\\n\\n3. **Crea un poco de urgencia.** Una pregunta con opciones se contesta rápido; una abierta se puede posponer con un *\\"déjame ver\\"*.\\n\\n**Cómo se usa bien:**\\n- Las opciones tienen que ser **reales y del giro del cliente**. Si sugieres familias que él no maneja, demuestras lo contrario de lo que buscabas.\\n- **Tres o cuatro, no una lista.** Es para ayudarlo a contestar, no para que elija de un catálogo.\\n- El rango de precio **tiene que ser creíble.** Sugerir cifras muy lejanas de la realidad te desacredita.\\n- Y **no lo uses para plantar una respuesta.** Si el cliente te corrige, esa es la respuesta buena — no insistas en la tuya.\\n\\n> **Es la misma lógica del cierre de alternativa, aplicada al descubrimiento:** no preguntas al aire, das opciones donde cualquier respuesta te sirve.\\n\\n### El Barrido `CLOSER` `UNIVERSAL`\\nTerritorio limpio → ni insistas ni te rindas: **cambia de territorio.**\\n\\nEl dolor casi siempre existe, solo que vive en otra zona del mapa. Insistir en zona sana te vuelve interrogador; rendirte regala la visita.\\n\\n### El dolor y la confirmación `CLOSER` `UNIVERSAL`\\nCuando el dolor aparece, **devuélveselo con SUS palabras**. *\\"Entonces lo que más le pega es X, ¿cierto?\\"*\\n\\nEso hace dos cosas: confirma que entendiste, y **le da forma consciente a algo que a lo mejor solo sentía.**\\n\\n> ⚠️ **Pero la confirmación explícita no es requisito para avanzar.**\\n>\\n> Muchas veces el cliente no va a admitir el problema. No porque no lo tenga — sino porque admitirlo suena a queja, o a que eligió mal, o simplemente porque **no lo tiene consciente**. Nadie anda por la vida con una lista de sus problemas operativos.\\n>\\n> Y aun así te sigue escuchando. **Eso ya es información.**\\n\\n**Lo que sí necesitas** es haber leído el problema con evidencia suficiente: algo que dijo, algo que viste, algo que su tipo de negocio hace probable. **Lo que no necesitas es su permiso verbal.**\\n\\n### La venta es emocional antes que racional `CAMPO`\\n\\nEste es el principio que corrige el error de modelar la venta como un proceso lógico.\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente no llena una hoja de cálculo: siente algo, y después construye la razón.\\n\\nConsecuencias que cambian cómo se ejecuta todo el sistema:\\n\\n- **Un cliente puede no reconocer un problema y aun así sentir alivio cuando se lo resuelves.** El impulso no viene de que aceptó el diagnóstico: viene de imaginar la situación resuelta.\\n- **Por eso \\"pintar imágenes\\" funciona** — no argumenta, hace sentir.\\n- **Por eso el vendedor no debe pelear por el reconocimiento explícito.** Insistir en que el cliente admita un problema lo pone a la defensiva y mata lo emocional, que era donde estaba la venta.\\n- **Y por eso el impulso se puede construir sin que haya un dolor declarado.** El 80% indiferente no tiene un problema urgente: se mueve por los factores de impulso, no por el diagnóstico.\\n\\n**La regla operativa:** si el cliente confirma el dolor, úsalo con sus palabras — es lo más fuerte que tienes. **Si no lo confirma pero la evidencia está, avanza igual**, presentando la situación resuelta en vez del problema reconocido.\\n\\n⚠️ **Lo que sigue prohibido es fabricar.** Leer un dolor probable no es inventarlo. La diferencia: leer se apoya en evidencia real — algo que dijo, algo que viste, algo propio de su giro. Fabricar es afirmar un problema **que el cliente ya negó** o del que no hay ningún indicio.\\n\\n### La regla del investigador\\n**El dolor nunca se pregunta directo.** *\\"¿Qué problemas tiene?\\"* produce *\\"ninguno\\"*, garantizado. Se deja emerger.\\n\\n### Luz Verde — 10/80/10 `FUENTE` `UNIVERSAL`\\n**10% negativos · 80% indiferentes · 10% positivos.**\\n\\n1. Sal de las luces rojas **rápido y educadamente**\\n2. Las amarillas reciben tu mejor presentación — pero si no dan señales de compra, muévete\\n3. Las verdes reciben tiempo, relación y resolución de dudas\\n\\n**Los factores de impulso existen principalmente para convertir al 80% indiferente.**\\n\\n#### El rojo verdadero y el que quiere pero no puede `CAMPO`\\n\\nLa luz roja no es cualquier \\"no\\". Es un tipo específico de cliente, y confundirlo cuesta ventas.\\n\\n**ROJO GENUINO** — no quiere. Es cortante, tajante, desganado. Muchas veces medio grosero. Y tiene un costo escondido: **interactuar de más con él desgasta tu actitud**, que es la variable de entrada de todo tu sistema. Con este, salir rápido y bien es la ejecución correcta.\\n\\n**AMARRADO TEMPORALMENTE** — quiere y no puede. Te recibe con gusto, te habla con honestidad, y su impedimento es una **circunstancia que va a cambiar**: un contrato de exclusividad, un inventario recién surtido, un presupuesto agotado, no ser él quien decide las compras grandes.\\n\\n> **Este no es rojo: es verde amarrado.** Y con él, rendirse es la falla más cara del oficio — porque ese cliente sí quería comprarte y el vendedor se fue solo.\\n\\n**Cómo se distinguen:** el rojo se nota en el trato. Es seco, no da información, quiere que te vayas. El amarrado hace lo contrario: es amable, te explica su situación con detalle, y muchas veces se disculpa por no poder.\\n\\n#### Casi toda restricción tiene bordes `CAMPO`\\n\\nY aquí está la mecánica que separa al vendedor promedio del que crece cuentas.\\n\\nCuando un cliente dice que no puede, **el promedio lo toma como total y se va**. El Closer investiga hasta dónde llega:\\n\\n- **¿Qué cubre exactamente?** Una exclusividad casi nunca abarca todas las familias\\n- **¿Qué queda fuera?** Ahí está la venta que la competencia no vio\\n- **¿Hasta cuándo dura?** Para volver justo cuando se libere, antes que nadie\\n\\n> Un contrato que cubre lubricantes, anticongelantes y grasas **deja fuera el líquido de frenos.** Y el vendedor que preguntó se lleva una venta de un cliente que \\"no podía comprar\\".\\n\\n**Y la relación sigue construyéndose mientras tanto.** Seguir visitando a un amarrado no es perder el tiempo: es estar presente el día que la restricción se acabe. El que se rindió no va a estar ahí.\\n\\n⚠️ **La línea:** investigar los bordes no es presionar. Si el cliente ya dijo que algo está dentro de su compromiso, insistir en eso es pedirle que rompa su palabra — y eso quema la relación. Se busca lo que **sí** puede, nunca se pelea lo que no.\\n\\n### QTQP `FUENTE` `UNIVERSAL`\\n**Q**uality **T**ime with **Q**uality **P**eople.\\n\\n> *\\"Perder tiempo y energía con las personas equivocadas destruye tu capacidad de ser lo suficientemente urgente\\"* — y la urgencia es de lo que vive tu ley de promedios.\\n\\nCada minuto con un rojo se lo quitas a un amarillo que sí podía comprar hoy.\\n\\n---\\n\\n## PASO 4 · PRESENTACIÓN\\n### *Construye valor y disminuye el costo*\\n\\n**Qué logra:** convertir el dolor descubierto en valor percibido, y subir el impulso.\\n\\n### Las herramientas de la presentación `FUENTE`\\n1. Encontrar problemas y proporcionar soluciones\\n2. **Pintar imágenes** — que imaginen que ya lo tienen\\n3. Incorporar factores de impulso\\n4. **Triple desglose de precios**\\n5. Hacer el valor enorme: lenguaje expansivo, *\\"gran\\"*, *\\"masivo\\"* `PRESENCIAL`\\n6. Hacer el costo pequeño: *\\"solo\\"*, *\\"apenas\\"* `PRESENCIAL`\\n7. **Tren del Sí** — preguntas cuya respuesta natural es sí\\n8. **CPR sostenido** durante toda la presentación\\n\\n### Beneficio, no característica `CLOSER` `UNIVERSAL`\\nUna característica es lo que el producto **es**. Nadie compra lo que algo es: compran **lo que van a ganar**.\\n\\nToda característica se traduce a una de tres cosas: **dinero** (gana más o gasta menos), **clientes** (vende más o los conserva), o **tranquilidad** (menos problemas, menos tiempo perdido).\\n\\n> Si el cliente puede contestar *\\"¿y eso a mí de qué me sirve?\\"*, la traducción falló.\\n\\n### Teoría de las Balas `FUENTE` `UNIVERSAL`\\n> *\\"La persona con más balas claramente tiene el control, siempre y cuando conserve su munición.\\"*\\n\\n**Las balas son TUYAS.** Son hechos positivos y concretos sobre:\\n- **Ti / tu empresa** — experiencia, premios, casos de éxito, dedicación\\n- **El producto** — lo que lo diferencia, mejoras, datos, certificaciones\\n- **El precio** — propuesta de valor, descuentos, financiamiento, comparación\\n\\n**La prueba de si algo es bala:** si la competencia puede decir exactamente lo mismo, no era bala. *\\"Somos los mejores\\"* es aire; *\\"catorce años surtiendo esta zona sin fallar\\"* es bala.\\n\\n**La regla de dosificación:** *\\"no dispares todas las balas al principio. Reserva algunas para que no importe cuántas balas tenga tu cliente, tengas más con qué responder. Guarda balas para los pasos 4 y 5.\\"*\\n\\n> **Por qué se guardan:** más adelante el cliente va a poner razones para no comprar. Eso baja su impulso. Responderle bien solo **detiene la caída** — lo que vuelve a subirlo es **una bala nueva**. Si las gastaste presumiendo al principio, llegas a ese momento con la mano vacía.\\n\\n### FUJIES / FUJPIG — Factores de Impulso `FUENTE`\\n*\\"El impulso es otra palabra para la emoción.\\"*\\n\\n| | Factor | Físico `PRESENCIAL` | Verbal `UNIVERSAL` |\\n|---|---|---|---|\\n| **F** | Fear of Loss / Miedo a la pérdida | Producto en mano y quitarlo, retroceder un paso | *\\"solo hoy\\"*, *\\"tiempo limitado\\"*, *\\"quedan pocas\\"* |\\n| **U** | Urgency / Urgencia | Tic-tac con el bolígrafo, empezar a alejarse | *\\"ahora\\"*, *\\"rápido\\"*, *\\"solo toma un par de minutos\\"* |\\n| **G** | Greed / Avaricia | Manos mostrando altos y bajos | *\\"normalmente $100, con la promo queda en solo $59.99\\"* |\\n| **I** | Indifference / Indiferencia | Postura, lenguaje corporal | SW3 |\\n| **E** | Effect of Jones / Efecto Jones | — | *\\"tengo como 20 clientes en esta zona que...\\"* |\\n| **S** | Suggestive Language / Poder de sugestión | Manos altas precio alto, bajas precio bajo | Tren del sí, alternativas |\\n\\n**Miedo a la pérdida > necesidad de ganancia.** La gente dice que sí impulsivamente porque no quiere que algo se le vaya.\\n\\n**Urgencia:** *\\"motion creates emotion\\"*. Y además comunica que estás ocupado, o sea que tienes éxito.\\n\\n**Indiferencia:** *\\"be excited about the person and the product, but indifferent whether they buy.\\"* **SW3** — Some Will, Some Won''t, So What. *\\"Ellos solo tienen una oportunidad de comprarte; tú tienes más de cien clientes.\\"*\\n\\n**Efecto Jones:** de *\\"keeping up with the Joneses\\"*. La gente no confía naturalmente en un desconocido incentivado a vender — pero sí deja que sus vecinos, amigos y familia validen el producto por ella.\\n\\n**Poder de sugestión — tres niveles:**\\n- **Mental** — *\\"asumo que todos son un sí hasta que me digan que no\\"*\\n- **Físico** — lenguaje corporal `PRESENCIAL`\\n- **Verbal** — el tren del sí. **El cliente debería decir que sí al menos 6 veces durante el proceso.**\\n\\n> **Elimina cualquier opción que se pueda traducir en un no.** En vez de *\\"¿quiere algo de tomar?\\"* → *\\"¿té, café o jugo?\\"*\\n\\n### La Curva de Impulso `FUENTE` `UNIVERSAL`\\nEl impulso sube y baja durante la conversación, y hay que construirlo **gradualmente** para no abrumar.\\n\\n**Las tres reglas de oro:**\\n1. **Encuentra al cliente en un punto común de emoción** al inicio, y construye desde ahí\\n2. **Cierra en el momento correcto** — el pico\\n3. **Elimina el arrepentimiento con un rehash impulsivo** — porque después del sí, el impulso cae\\n\\n#### La presentación tiene dos mitades `CAMPO`\\n\\nY confundirlas es un error común, así que conviene tenerlas separadas.\\n\\n**PRIMERA MITAD — lo que vas a hacer por él.**\\nConectas con su dolor usando SUS palabras, y explicas cómo se lo resuelves. Aquí no hay producto todavía: hay un problema y una solución. *\\"Eso que me dice de quedarse sin producto cuando le entra movimiento — eso es venta que se le va.\\"*\\n\\n**SEGUNDA MITAD — el producto y el precio.**\\nUn resumen breve de qué es lo que le va a resolver eso, y el Triple Desglose de Precios. De ahí se pasa directo al cierre.\\n\\n> **El precio SÍ va en la presentación.** Lo que va en el cierre es el **resumen del pedido** — qué y cuánto lleva. Son dos cosas distintas:\\n>\\n> · **Presentación** → el precio en escalera con sus motivos. *\\"Normalmente le sale en X, como es primer pedido queda en Y, y de contado en Z.\\"*\\n> · **Cierre** → lo que lleva. *\\"Entonces le van dos cajas de esto y una de aquello. ¿Jueves o viernes?\\"*\\n>\\n> Enumerar SKUs con cantidades en la presentación es escribir el cierre en el lugar equivocado. Pero omitir el precio es dejar la presentación a medias — y el cliente se queda esperando el número que nunca llegó.\\n\\n### Triple Desglose de Precios `FUENTE (definido) + CAMPO (desarrollado)` `UNIVERSAL`\\n> **Valor menos costo es igual a ahorro.**\\n\\n**La escalera — tres cifras bajando:**\\n1. **Lo que normalmente cuesta** — hace match con lo que el cliente ya esperaba\\n2. **Con el primer descuento** — cliente nuevo, volumen, lo que aplique\\n3. **Con el segundo** — pago de contado, cerrar hoy, lo que corresponda\\n\\n**El ahorro dicho en voz alta.**\\n\\n> **La regla que lo hace funcionar: cada escalón necesita un motivo nombrado.**\\n>\\n> Un precio que baja **sin razón** le dice al cliente que el primero estaba inflado — y te vuelve regateable, porque si bajó dos veces solo, va a bajar otra si presiona.\\n>\\n> Un precio que baja **por razones nombradas** confirma que el primero era real, y cada escalón se vuelve una bala de precio.\\n\\n**Por qué se ve y no solo se escucha:** *\\"queda en ochenta\\"* se escucha como un gasto de ochenta. *\\"Normalmente cien, con su descuento noventa, de contado ochenta\\"* se ve como veinte de ahorro que antes no existían. Mismo número final, sensación opuesta.\\n\\n**Y como el último escalón depende de algo que puede hacer HOY, aparece solo el miedo a la pérdida.**\\n\\n> ⚠️ **Nunca un solo precio.** Un precio suelto es un gasto sin ahorro visible que lo compense.\\n\\n---\\n\\n## PASO 5 · CIERRE\\n### *Extrae eficientemente una decisión*\\n\\n### Qué es un cierre `FUENTE`\\n> *\\"Un cierre no es algo que le haces a alguien. Un cierre es un acuerdo, cuando el cliente se da cuenta de que el beneficio supera al costo y decide. El cierre se lo hace la gente a sí misma.\\"*\\n\\n**Un cierre no siempre es una venta.** Es pedir la decisión, sea cual sea. Asegúrate de que tus conversaciones avancen hacia una conclusión — un sí o un no.\\n\\n### Asumir la venta `FUENTE` `UNIVERSAL`\\nSi llegaste a este punto, **presume que tienes un comprador**.\\n\\n**Malos cierres** — todos invitan al no:\\n*¿Le gustaría comprar? · ¿Está interesado? · ¿Le gusta lo que oye? · ¿Qué le parece? · ¿Cómo lo ve?*\\n\\n**Buenos cierres** — alternativas donde ambas opciones sirven:\\n*¿Es su nombre el que va en la cuenta? · Las primeras fechas de entrega son jueves o viernes, ¿cuál le conviene? · ¿Visa o MasterCard? · ¿Contado o crédito?*\\n\\n> **El diagnóstico de la fuente:** *\\"la mayoría de las personas que batallan para cerrar simplemente no están rompiendo la zona de confort que viene con pedir algo.\\"*\\n>\\n> Y: *\\"aumentas la probabilidad de que compren mientras más confiadamente anuncies tu mensaje.\\"*\\n\\n### El silencio después del cierre `CAMPO` `UNIVERSAL`\\nNo llenes el silencio. Pediste la decisión: **aguanta**.\\n\\nEl vendedor que retira la pregunta, la suaviza o la contesta él mismo, pierde. El primero que habla después de un cierre, pierde.\\n\\n### FISHBBOD — Señales de Compra `FUENTE`\\nTambién llamadas **STOP signs**. En cuanto reconoces una, **DETIENES la presentación y CIERRAS**.\\n\\n**F** Future talk · **I** I want / I need · **S** Silence · **H** How much / How soon · **B** Body language `PRESENCIAL` · **B** Bashing competitor · **O** Offers of courtesy · **D** Deeper questions\\n\\n> **El error que cuesta más ventas de lo que nadie cree:** el cliente da la señal, el vendedor la ve, y como todavía le quedaban dos argumentos buenos, los suelta.\\n>\\n> **El impulso baja.** Porque el cliente ya estaba listo, y seguir vendiéndole le comunica que hay algo que convencerlo — o le da tiempo de encontrar una razón para no hacerlo.\\n>\\n> Señal de compra = deja de presentar y cierra. **Aunque te queden balas. De hecho, sobre todo si te quedan.**\\n\\n---\\n\\n## MANEJO DE OBJECIONES `FUENTE`\\n### *No son negativas: son preguntas que, bien respondidas, terminan en venta*\\n\\n**Objeción = señal de compra.** El que no tiene interés no objeta: se despide.\\n\\n### Las cuatro técnicas de overturn\\n\\n| Técnica | Cuándo | Cómo |\\n|---|---|---|\\n| **AIR** — Agree, Ignore, Resume | Bloqueos en la introducción | Reconoce, ignora, continúa |\\n| **Ataque Preventivo** | Intro o historia breve, negativos conocidos del territorio | Da el negativo antes que el cliente |\\n| **RRR** — Repeat, Reassure, Resume | Objeciones menores y comunes | Repite, responde, **continúa sin pausa** |\\n| **FFF** — Feel, Felt, Found | Preocupación seria o personal | Nunca discutas |\\n\\n### RRR de objeciones `FUENTE` `UNIVERSAL`\\n**R**epeat — repite la objeción en sus términos, para que vea que la escuchaste\\n**R**eassure — la respuesta concreta, con datos\\n**R**esume — **retoma sin pausa**\\n\\n> **La tercera R es la que falla.** El vendedor responde bien y se queda callado esperando a ver si convenció. En ese espacio el cliente encuentra la siguiente objeción, o dice que lo va a pensar.\\n\\n### FFF — el procedimiento completo `FUENTE` `UNIVERSAL`\\n**Nunca discutas con un cliente.** Ganar la discusión es perder la venta.\\n\\nEn español: **Entiendo · Sintió · Encontramos**\\n\\n1. **\\"Entiendo cómo se siente\\"** — estar de acuerdo te vuelve distinto del vendedor promedio, **y por eso te escuchan**\\n2. **\\"Mi último cliente sentía lo mismo\\"** — para que sepa que no está solo\\n3. **\\"Lo que encontramos fue...\\"** — por qué dejaron de pensar así. **Esto usa Efecto Jones**\\n4. **Inserta 3 balas** de la Teoría de las Balas\\n5. **Close With Action**\\n\\n> ⚠️ **FFF no termina en la tercera F.** El documento en español del sistema fuente está truncado y solo llega al paso 3 — por eso mucha gente aprendió un FFF incompleto, sin re-impulso y sin cierre. **Los pasos 4 y 5 son el Círculo de Cierre.**\\n\\n### El Círculo de Cierre `FUENTE (implícito) + CAMPO (nombrado)` `UNIVERSAL`\\n\\n```\\n   CLOSE WITH ACTION ←──────────────┐\\n            ↓                        │\\n   ¿Objeción? → el impulso baja      │\\n            ↓                        │\\n   Atraviesas (RRR o FFF)            │\\n            ↓                        │\\n   RE-IMPULSAS con una bala NUEVA ───┘\\n```\\n\\n> **El error más común: atravesar la objeción y cerrar de inmediato, saltándose la bala.**\\n>\\n> Técnicamente respondiste. Pero **atravesar solo detiene la caída del impulso** — no lo sube. Estás pidiendo una decisión en el punto más bajo de la conversación, y desde ahí la respuesta cómoda siempre es *\\"déjeme lo pienso\\"*.\\n\\n**Y la bala tiene que ser NUEVA.** Repetir un argumento ya usado no sube nada: comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.\\n\\n### La Regla de los No\\n- **Fuente:** *2 no''s and a go* — dos no seguidos, luz roja, sigue adelante\\n- **Campo `CAMPO`:** Emilio usa **3 no seguidos**, porque hay gente que deja ir un sí solo porque el cliente tuvo preguntas u objeciones\\n\\n> **Tienen que ser CONSECUTIVOS.** Un no, lo atraviesas, la conversación avanza, y más adelante otro no: **eso no es una racha**. Es una conversación normal con dos momentos de fricción. La racha se rompe en cuanto la conversación avanza.\\n\\n---\\n\\n## PASO 6 · CONSOLIDACIÓN / REHASH\\n### *El paso final y más importante*\\n\\n**REHASH** = **R**emember **E**veryone **H**as **A**nother **S**ale **H**idden\\n\\n**Dos propósitos** `FUENTE`:\\n1. **Capitalizar a un cliente ya positivo** — *\\"la gente compra de sus amigos mucho más fácil que de un desconocido\\"*\\n2. **Dejarlo positivo y entendiendo los siguientes pasos** — *\\"la causa número uno de cancelaciones es la falta de entendimiento\\"*\\n\\n### El arrepentimiento del comprador\\nApenas dice que sí, **el impulso cae**. El cerebro empieza a buscar razones por las que quizá no debió. Es automático y no es desconfianza hacia ti.\\n\\n### Cómo se disuelve `CAMPO`\\n> **El error que parece lo correcto: seguir vendiendo.**\\n>\\n> La reacción natural es reforzar la compra — recordarle lo bueno del producto, repetirle el ahorro, insistir en que tomó una gran decisión.\\n>\\n> **Y eso lo empeora.** Seguir vendiendo después del sí le dice al cliente que **necesitabas la venta**. Y si la necesitabas, entonces la indiferencia era actuada. Y si la indiferencia era actuada, también el interés por su negocio, también las preguntas, también la plática de su hijo.\\n>\\n> **Retroactivamente, toda la conversación se convierte en una técnica.**\\n\\n**Lo que sí funciona: demostrar que nada cambió en ti.**\\n\\nMisma indiferencia sobre la compra. Misma calidez sobre la relación. Cero producto. Y la confianza de que ahí vas a estar para lo que necesite.\\n\\n**Por qué funciona:** si tu actitud es idéntica antes y después de la firma, el cliente concluye solo lo que ninguna frase habría logrado convencerlo — **que no lo trataste así para venderle, sino porque así eres.** Y con esa conclusión, el arrepentimiento no tiene de qué agarrarse.\\n\\n**Y deja claro qué sigue.** La falta de entendimiento es la causa número uno de cancelaciones.\\n\\n---","is_active":false,"created_at":"2026-09-29T17:14:32.375719+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"cd98516a-ed64-46cd-802c-240a7524a0bd","version":5,"section_key":"mentalidad","order_index":3,"title":"PARTE 3 · LA MENTALIDAD","body":"# PARTE 3 · LA MENTALIDAD\\n### *La segunda fundación*\\n\\n> *\\"No importa qué tan buenas sean tus habilidades conversacionales, nunca vas a tener 100% de éxito.\\"*\\n>\\n> Y: *\\"hay gente con mucha personalidad o experiencia que triunfa sin trabajar bien la ley de promedios — pero no puede replicar su éxito, porque depende demasiado de la habilidad.\\"*\\n\\n**La mentalidad no es motivación: es el sistema de control que hace replicable el resultado.**\\n\\n## Ley de Promedios (LDP) `FUENTE`\\n> *\\"Si repites una acción las veces suficientes, aparecerá una proporción.\\"*\\n\\nEs un sistema probado para **encontrar compradores entre los no compradores**.\\n\\n**La analogía de la moneda:** lanzas una vez, 50/50. Lanzas diez veces y raramente sale 5 y 5. Pero mientras más lanzas, más se acerca la muestra a la proporción real. **La ley necesita volumen para manifestarse.**\\n\\n## PPA — lo que afecta tu ley de promedios `FUENTE`\\n**P**itch / Conversación — preciso, conciso, impactante\\n**P**ace / Ritmo — con cuánta gente hablas\\n**A**ttitude / Actitud — consistentemente positiva\\n\\n> **La cadena causal, y por qué la mentalidad no es opcional:**\\n> La ley de promedios necesita volumen. El volumen desgasta la actitud. La actitud degrada el pitch. Y el pitch es la variable de entrada del sistema.\\n>\\n> **Por eso KILT, los 3 tipos de día, controlables y gumball existen: protegen la única variable que el vendedor controla.**\\n\\n## Los 3 Tipos de Día `FUENTE`\\n- **Día A** — las ventas llegan temprano, la actitud es fácil\\n- **Día B** — llegan esporádicamente, no te prueba del todo\\n- **Día C** — todas llegan en las últimas horas. **La verdadera prueba de quién cree en el sistema**\\n\\n*Ejemplo real: 3 ventas de 60 contactos es normal — 5% de éxito. Es normal no tener ningún cliente hasta el final del día y aun así cumplir.*\\n\\n## Teoría del Gumball `FUENTE`\\nTres máquinas, 100 dulces cada una, 97 rojos y 3 verdes. Cada intento cuesta un peso. Tienes 100 pesos y la meta de sacar 3 verdes.\\n\\n**Mantén tu pitch, ritmo y actitud iguales, para que cada \\"no\\" te acerque al \\"sí\\".**\\n\\n> **La dificultad real:** en el campo no puedes ver dónde están los verdes como en la máquina. Tienes que seguir girando a ciegas, sabiendo que tu proporción va a aparecer.\\n\\n## Controlables vs No Controlables `FUENTE`\\n> *\\"Si no podemos controlarlo, no lo pensamos ni lo hablamos. Es una pérdida de tiempo y energía.\\"*\\n\\nLa mayoría pasa el día culpando cosas que no controla. Concentrarse en lo controlable es mucho más productivo: ver más gente, tener mejores conversaciones, cuidar la actitud.\\n\\n## KILT `FUENTE`\\n**K**ill them with kindness — sé amable sin importar la actitud del otro\\n**I**ndifference — algunos comprarán, otros no, ¿y qué?\\n**L**aw of averages — confía en los números\\n**T**reat everyone like your first — nunca sabes cuándo aparece tu cliente\\n\\n**Aplicación:** si dejamos a cada persona mejor de como la encontramos, permanecemos indiferentes al sí o al no, y tratamos a cada quien como el primero, entonces protegemos la actitud.\\n\\n## Los 8 Grandes Hábitos `FUENTE`\\n*\\"Somos lo que hacemos repetidamente; el éxito es un hábito.\\"*\\n\\n1. **Tener gran actitud** — el negocio es 99% actitud y 1% habilidad\\n2. **Ser puntual** — si no llegas temprano, llegas tarde\\n3. **Estar preparado** — fallar en prepararse es prepararse para fallar\\n4. **Esfuerzo del 100%** — recibes lo que pones\\n5. **Maximizar tu territorio** — tu territorio no es el lugar, **son las personas**\\n6. **Proteger tu actitud** — cada \\"no\\" te acerca al \\"sí\\"\\n7. **Conocer tu porqué** — metas de corto, mediano y largo plazo\\n8. **Tomar el control** — de tu día, tu carrera y tu vida\\n\\n## Indicadores / Gauges `FUENTE`\\nMiden con cuánta gente hablas y qué tan lejos llegas en los pasos.\\n\\n**Puertas → Con cuántos hablaste → Presentaciones → Cierres**\\n\\n**Para qué sirven:**\\n1. Identificar dónde **podría** romperse el sistema en tus 6 pasos\\n2. Asegurar que trabajas el sistema\\n3. Marcarte el ritmo\\n\\n> ⚠️ **Los indicadores señalan DÓNDE MIRAR, no qué está mal.**\\n>\\n> Si presentas a muchos y cierras a pocos, el número te dice que algo pasa **entre la presentación y el cierre** — pero la causa puede estar mucho antes. Puede ser que el descubrimiento no encontró el dolor real, que no hubo suficiente CPR y el cliente nunca contestó de verdad, que la presentación se alargó y cayó en KILL, que el impulso se construyó mal, o que efectivamente el cierre es débil.\\n>\\n> **Un número no diagnostica una causa.** Diagnostica una zona.\\n\\n**El diagnóstico real requiere ver la conversación.** Como manager: acompañando al vendedor en campo, o pidiéndole una práctica en Closer sobre el paso donde sospechas.\\n\\n**Números + conversación observada = conclusión.** Cualquiera de los dos solo, es especulación.\\n\\n## Metas — SMART `FUENTE`\\n**S**pecific · **M**easurable · **A**ttainable · **R**ealistic · **T**imed\\n\\nTipos: de **resultado** · de **acción** · corto plazo (<2 meses) · mediano (2 meses–3 años) · largo (3+ años)\\n\\nEscríbelas, hazlas evaluar por alguien, y recompénsate al lograrlas.\\n\\n---","is_active":false,"created_at":"2026-09-29T17:14:32.375719+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"8650213b-727f-4e40-b075-d19754023939","version":5,"section_key":"aplicacion","order_index":4,"title":"PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE","body":"# PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE\\n\\n> **El sistema es el esqueleto. Si se entiende, se aplica a cualquier cliente, cualquier industria y cualquier producto.**\\n\\nEsta parte NO es un catálogo de casos. Es la demostración de cómo se deduce la ejecución correcta a partir de los principios — para que cualquier caso que no esté aquí se resuelva igual.\\n\\n## 4.0 El método de adaptación\\n\\nCada paso existe para lograr algo. **Lo que cambia entre clientes no es el objetivo del paso: es lo que hace falta para lograrlo.**\\n\\nEjemplo con la Historia Breve. Su objetivo es liberar el segundo tercio de atención — las dos preguntas que el cliente trae en la cabeza: *quién eres* y *por qué estás aquí*.\\n\\n- Con un desconocido, las dos están abiertas → contestas las dos\\n- Con alguien que te conoce hace años, la primera ya está contestada → **solo queda el porqué de hoy**, y a veces hasta eso es obvio\\n\\n**La conclusión operativa, dicha completa:** con un cliente que ya te conoce, la Historia Breve **NO incluye tu nombre ni el de tu empresa**. Nada de \\"Soy Juan, de [empresa]\\", ni \\"trabajamos con tal marca\\". Él ya lo sabe. Repetírselo le comunica que no lo reconoces o que estás recitando un guion — y en los dos casos daña la relación que llevas años construyendo.\\n\\nLo único que queda es **por qué viniste HOY**, en una o dos frases. Y a veces hasta eso es evidente.\\n\\nEse es el método. Ante cualquier cliente, en cualquier industria:\\n\\n1. ¿Qué **objetivo** tiene este paso?\\n2. ¿Qué de ese objetivo **ya está resuelto** con este cliente?\\n3. ¿Qué **falta** por resolver?\\n4. **Ejecuta solo eso, y escribe solo eso.**\\n\\n> ⚠️ **El paso 4 es donde más se falla.** Deducir correctamente qué falta y aun así escribir la versión completa por costumbre es el error más frecuente al aplicar este método. Si concluiste que algo ya está resuelto, **ese algo no aparece en el texto.** No basta con saberlo: hay que omitirlo.\\n\\n## 4.0b Autoconsumo y distribuidor NO son un tercer eje `CAMPO`\\n\\nHay una confusión fácil de cometer: tratar \\"autoconsumo\\" y \\"distribuidor\\" como si fueran alternativas a \\"nuevo\\" y \\"recurrente\\". No lo son. **Son ejes distintos.**\\n\\n**EJE 1 — ¿Ya te compra?** Nuevo o recurrente. Esto define **la relación**: si te conoces, si hay historial, si hay pedido base.\\n\\n**EJE 2 — ¿Qué hace con el producto?** Revende, consume o distribuye. Esto define **las preguntas**: qué se le pregunta en cada territorio.\\n\\n**Se cruzan.** Un cliente de autoconsumo puede ser nuevo (nunca te ha comprado) o recurrente (lleva años surtiéndose contigo). Y la ejecución cambia según el cruce:\\n\\n| | Nuevo | Recurrente |\\n|---|---|---|\\n| **Revende** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Consume** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Distribuye** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n\\n> **Lo que cambia por el EJE 1** es si te presentas, si hay \\"lo de siempre\\", y si buscas dolor o hueco.\\n>\\n> **Lo que cambia por el EJE 2** es únicamente el vocabulario del descubrimiento: al que revende le preguntas qué maneja y qué le piden; al que consume, qué usa y cada cuánto repone; al que distribuye, sus líneas y a cuántos surte.\\n\\n**Error concreto que esto evita:** escribir la historia breve de un cliente de autoconsumo como si fuera recurrente — *\\"vine a ver cómo les funcionó lo que dejamos la vez pasada\\"* — cuando nunca ha habido una vez pasada. Autoconsumo no dice nada sobre si ya te compra o no.\\n\\n**Y una vez que un cliente de autoconsumo te compra, se vuelve recurrente**: el seguimiento y el crecimiento de esa cuenta funcionan igual que con cualquier otro recurrente. Buscas huecos, cierras el incremento, y no te vuelves a presentar.\\n\\n## 4.1 Lo que sí cambia sustancialmente\\n\\nHay dos diferencias que no son obvias y que sí conviene tener explícitas, porque cambian **qué se busca**, no solo cómo se dice.\\n\\n### Diferencia 1 — Qué buscas en el Descubrimiento\\n\\n**DOLOR** — algo anda mal. Tiene señal verbal: **el \\"aunque\\"**. Se busca con los 3 Territorios y la escalera de capas.\\n\\n**HUECO** — algo que podría comprarte y no te compra. **No tiene señal verbal: se ve, no se oye.**\\n\\n> Un cliente conforme no tiene dolor. **Por eso el vendedor que solo sabe buscar dolor visita durante años sin crecer una cuenta**: busca, no encuentra, y concluye correctamente que no hay nada.\\n\\n**Las tres herramientas del hueco:**\\n\\n**1 · Lee el lugar** — lo que ves te dice qué maneja y de quién. Un producto de otra marca es un espacio ocupado; un estante vacío es una familia que nadie cubre; algo empolvado no es hueco, **es dolor**.\\n\\n**2 · Pregunta por lo que le piden** — *\\"¿le ha tocado que le pidan algo que no maneje?\\"* Demanda que ya existe sin oferta que la cubra.\\n\\n**3 · Ancla en negocios como el suyo** — Efecto Jones aplicado. Solo si es verdad y lo puedes sostener.\\n\\n**Adaptación por canal:** presencial observas; a distancia preguntas por el catálogo. **Adaptación por giro:** si el cliente no revende, \\"lo que ves\\" no es un mostrador — son sus unidades, su patio, su operación.\\n\\n> **La línea que no se cruza:** un hueco tiene que ser real y verificable. **Descubrir un hueco es señalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.**\\n\\n### Diferencia 2 — Qué estás cerrando\\n\\nCon un cliente que ya compra, **el pedido base no está en duda: ya iba a existir.** Lo que se cierra es **lo que se agrega**.\\n\\nReabrir el pedido base al cerrar pone sobre la mesa algo que ya estaba resuelto, e invita al cliente a revisar toda la orden.\\n\\n## 4.1b La observación del recurrente no puede sonar a primera visita `CAMPO`\\n\\nEl SCE y el ice breaker siguen aplicando con un cliente de años. Lo que cambia es **de qué se observa**.\\n\\n**El error:** *\\"¿Siempre está así de lleno o hoy le tocó día pesado?\\"*\\n\\nEsa pregunta la hace alguien que no conoce el lugar. Y este vendedor lleva años pasando cada quincena — **ya sabe si el negocio es movido.** Preguntarlo le comunica al cliente que no lo tiene presente, que es lo contrario de lo que la relación construyó.\\n\\n**Lo correcto: observar lo que CAMBIÓ desde la última visita.**\\n\\n> *\\"Oiga, ¿ya le entró más gente que la vez pasada, verdad?\\"*\\n> *\\"Veo que le movió al acomodo desde que vine.\\"*\\n> *\\"¿Ya se compuso lo del clima o siguen igual de flojas las tardes?\\"*\\n\\nY también funciona lo personal, que con un desconocido no puedes usar:\\n\\n> *\\"¿Cómo salió su muchacho de lo que me contó?\\"*\\n> *\\"¿Le fue bien en el puente?\\"*\\n\\n> **La prueba:** si tu observación de apertura funcionaría igual con un cliente que ves por primera vez, no está aprovechando la relación. **Con un recurrente, la apertura demuestra memoria** — y esa memoria es el activo que llevas años construyendo.\\n\\n⚠️ **Y esto solo funciona si la memoria es real.** Inventar que recuerdas algo que no pasó es peor que no recordar nada. Si no tienes un dato de la visita anterior, observa el momento presente sin fingir historia: *\\"se ve movido hoy\\"* es honesto; *\\"¿siempre está así?\\"* no lo es.\\n\\n## 4.2 Lo que NO cambia nunca\\n\\n- El orden de los 6 pasos\\n- Que el descubrimiento va antes de la presentación\\n- Que el cierre asume en vez de pedir aprobación\\n- Que el precio va en escalera con motivo\\n- Que no hay frases neutras\\n- Toda la Parte 6 (jerarquía de reglas)\\n\\n## 4.3 Presentar un hueco `CAMPO`\\n\\nCuando lo que encontraste es un hueco, no hay nada que resolver: el cliente está conforme. Hay un espacio que ocupar.\\n\\n**La pregunta que define el argumento: ¿qué gana él con que tú se lo surtas?**\\n\\nY la respuesta depende del caso, no de una fórmula. Posibilidades reales:\\n\\n- **Consolidación** — si el cliente trata con muchos proveedores y eso le pesa, reducir el número tiene valor por sí mismo\\n- **Conveniencia** — te ve de todos modos; agregar una familia no le suma trabajo\\n- **Complementariedad** — lo que ofreces se usa junto con lo que ya te compra\\n- **Una condición concreta** — plazo, disponibilidad, presentación, tiempo de entrega\\n\\n> ⚠️ **La consolidación NO es un argumento universal.** Si tu producto es complementario y el cliente ya tiene cinco proveedores, con la familia nueva pasa a tener **seis, no cuatro**. Ahí *\\"menos proveedores que seguir\\"* es falso, y usarlo te desacredita.\\n>\\n> Antes de usarlo, verifica que el cliente **efectivamente vaya a reducir** su número de proveedores.\\n\\n⚠️ **Nunca ataques al proveedor actual.** Criticarlo es criticar la decisión del cliente, y la gente defiende sus decisiones.\\n\\n⚠️ **No afirmes ventajas que no puedes verificar.** *\\"El otro no maneja esta línea\\"*, *\\"nadie tiene nuestro catálogo\\"*, *\\"con nosotros le sale mejor\\"* — si no lo sabes de cierto, no lo digas. Puede ser falso, y en una cuenta de años se descubre siempre. **Habla de lo que TÚ ofreces, con hechos que puedas sostener.**\\n\\n## 4.4 Convicción sin garantía `CAMPO`\\n\\n> **Nunca le pidas que \\"pruebe\\".**\\n>\\n> *\\"Le pongo unas pocas para que lo pruebe\\"* suena humilde y es lo peor que puedes decir: **le pasas el riesgo a él.** La gente no quiere experimentar — está cómoda donde está, y probar algo nuevo es riesgo, incomodidad y la posibilidad de haberse equivocado.\\n\\n**El trabajo del vendedor no es pedir permiso para experimentar. Es hacer que el cliente se sienta seguro.** Dos movimientos:\\n\\n1. **Convicción, sin garantía** — *\\"no le puedo garantizar nada, pero estoy seguro de que le va a servir\\"*\\n   **Funciona precisamente porque reconoce el límite.** Admitir lo que no controlas hace creíble lo que sí afirmas.\\n\\n2. **La razón detrás** — *\\"se lo digo porque en negocios como el suyo es de lo que más sale\\"*\\n   Sin la razón, tu convicción es solo optimismo de vendedor.\\n\\n**Y ahí te callas.**\\n\\n⚠️ **No ofrezcas el plan B.** *\\"Y si no funciona lo ajustamos\\"* parece que baja el riesgo y hace lo contrario: **le mete una duda que no tenía**, y desmiente lo que acabas de afirmar. Si de verdad estás seguro, ¿para qué el paracaídas?\\n\\n*(Si después no funciona, ahí lo ajustas. Eso es Consolidación y se hace cuando pasa — no se anuncia por adelantado.)*\\n\\n## 4.5 El capital del récord `CAMPO`\\n\\n> **La primera vez que recomiendas algo, el cliente compra por la relación. La segunda vez, compra por tu récord.**\\n\\nY eso disciplina: si recomiendas algo que no funciona, **no perdiste una venta — gastaste crédito que te costó años juntar.** Por eso solo se recomienda lo que de verdad sirve a ese perfil, aunque haya cosas con mejor margen.\\n\\n## 4.6 Los dos juegos `CAMPO`\\n\\n**ADQUISICIÓN** — convertir a un desconocido en cliente.\\n**DESARROLLO** — convertir a un cliente en un cliente más grande.\\n\\n> **La asimetría que explica por qué el segundo se descuida:** adquisición da retroalimentación inmediata — vendes o no vendes. Desarrollo no. Puedes visitar cien veces, levantar el mismo pedido, sentir que hiciste bien tu trabajo, y nunca enterarte de lo que dejaste sobre la mesa.\\n>\\n> **El fracaso en desarrollo es invisible.**\\n\\n**El enemigo: la visita que se vuelve trámite.** El vendedor está haciendo adquisición con alguien que ya adquirió — y como no hay nada que adquirir, no hay nada que hacer.\\n\\n> **Al que solo toma pedidos lo reemplaza un formulario.**\\n\\n---","is_active":false,"created_at":"2026-09-29T17:14:32.375719+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"014231b1-5b93-4eda-8ac0-d976af020e08","version":5,"section_key":"canales","order_index":5,"title":"PARTE 5 · MODIFICADORES DE CANAL","body":"# PARTE 5 · MODIFICADORES DE CANAL\\n\\n| Canal | Qué se conserva | Qué se adapta |\\n|---|---|---|\\n| **Presencial** | Todo | — |\\n| **Teléfono** | Los 6 pasos, KISS, FORMS, las 4 técnicas de overturn, balas, FUJIES verbales, CWA, triple desglose, y el **entusiasmo del tono** | Contacto visual → pausas y ritmo. Todo lo físico se pierde |\\n| **WhatsApp / mensaje** | La estructura completa, balas, triple desglose, ataque preventivo | Mensajes cortos, uno por idea. Señales de compra → velocidad de respuesta, emojis, preguntas de precio. El cierre debe contestarse con una palabra |\\n| **Correo** | Estructura, KISS, balas, triple desglose | Todo lo interactivo se vuelve secuencia |\\n\\n> **El principio de adaptación: entender qué HACE cada técnica permite encontrar su equivalente en cualquier medio.**\\n>\\n> El miedo a la pérdida no es *\\"quitar el producto de la mano\\"* — es **crear la sensación de que algo se va**. Eso existe en los cuatro canales.\\n\\n---","is_active":false,"created_at":"2026-09-29T17:14:32.375719+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"7194c0fd-d678-46dd-8998-04380b5f4562","version":5,"section_key":"jerarquia","order_index":6,"title":"PARTE 6 · JERARQUÍA DE REGLAS","body":"# PARTE 6 · JERARQUÍA DE REGLAS\\n\\nCuando dos principios chocan, gana el de mayor jerarquía.\\n\\n## NIVEL 1 — Inviolables (ética y verdad)\\nNunca se rompen, en ningún contexto, por ninguna razón.\\n\\n1. **Impulso falso está prohibido.** Urgencia inventada, escasez que no existe, prueba social fabricada. *(Práctico, no solo moral: un impulso falso se derrumba cuando el cliente lo descubre, y se lleva la venta, la relación y tu reputación en la zona.)*\\n2. **No garantizar lo que no controlas.** Convicción sí; garantía no.\\n3. **No fabricar un hueco ni un dolor.** Descubrir es señalar lo que existe.\\n4. **No atacar al competidor ni al proveedor actual.**\\n5. **No afirmar ventajas que no puedes verificar.** *\\"Nadie más tiene esto\\"*, *\\"el otro no lo maneja\\"*, *\\"con nosotros sale mejor\\"* — si no lo sabes de cierto, no lo dices. Habla de lo que TÚ ofreces.\\n6. **Nunca discutir con un cliente.**\\n\\n## NIVEL 2 — Estructurales\\nSe rompen solo si el Nivel 1 lo exige.\\n\\n7. **El orden de los 6 pasos.** No se salta ninguno.\\n8. **Primero el examen, luego la receta.** No presentar sin diagnosticar.\\n9. **El cierre asume, no pide aprobación.** Toda pregunta que permita aprobar o posponer entrega el control.\\n10. **El precio va en escalera con motivo en cada escalón.** Nunca un solo número.\\n11. **No hay frases neutras.** Si algo resta valor y nadie lo preguntó, se omite.\\n12. **Señal de compra = detente y cierra.**\\n13. **Se sale de la línea, pero siempre se regresa.**\\n14. **Nunca pidas opinión ni aprobación sobre el precio.** Ni el tuyo ni el de la competencia. Preguntar *\\"¿cómo ve los precios?\\"* le pide al cliente que construya una posición contra ti antes de que exista valor, cede tu autoridad sobre el precio, y renuncia a tu ventaja — porque tú conoces el mercado y él muchas veces no. En el territorio PRECIO se investigan **hechos** (a cómo compra, qué plazo tiene, cada cuánto le suben), nunca opiniones.\\n\\n## NIVEL 3 — Contextuales\\nDependen del tipo de cliente, canal o situación. **Se deducen del método de la Parte 4.0, no se memorizan.**\\n\\n14. Qué parte de la Historia Breve hace falta — depende de qué ya sabe el cliente\\n15. Buscar dolor o buscar hueco — depende de si el cliente está conforme\\n16. Qué argumento usar al presentar un hueco — depende de qué gana él en ESE caso\\n17. Cerrar la venta o cerrar el incremento — depende de si hay un pedido base\\n18. SEE físico — solo presencial\\n\\n## NIVEL 4 — Estilo\\nAjustables al lenguaje del vendedor, la zona y la empresa.\\n\\nTono, vocabulario, longitud de frases, formalidad. **El manager conoce el lenguaje de su gente mejor que Closer.**\\n\\n---","is_active":false,"created_at":"2026-09-29T17:14:32.375719+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"2c54462c-c1b2-4fbd-840a-6c65317a8e6d","version":5,"section_key":"razonamiento","order_index":7,"title":"PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO","body":"# PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO\\n\\n## Ante un caso no cubierto\\n1. Identifica **qué paso** de la línea es\\n2. Pregunta **qué objetivo tiene ese paso**\\n3. Pregunta **qué de ese objetivo ya está resuelto** con este cliente, y qué falta\\n4. Verifica contra la **jerarquía**: ¿viola algo de Nivel 1 o 2?\\n5. Si sigue sin resolverse, **di que no lo sabes.** No inventes doctrina.\\n\\n## Ejemplos de deducción\\n\\n**Caso:** un vendedor pregunta si puede decir *\\"¿le late?\\"* al cerrar.\\n**Razonamiento:** es una pregunta que permite aprobar o posponer → viola la regla 9 (Nivel 2) → **no**. La alternativa es una pregunta donde ambas opciones sirvan.\\n\\n**Caso:** un manager quiere que el pitch mencione que un producto no trae promoción este mes.\\n**Razonamiento:** no hay frases neutras (1.3); esto baja el valor percibido; nadie lo preguntó → **se omite**. Regla 11, Nivel 2.\\n\\n**Caso:** un vendedor pregunta cómo abrir con un cliente que le compra desde hace cinco años.\\n**Razonamiento:** aplica el método 4.0. Objetivo de la Historia Breve = contestar *quién eres* y *por qué estás aquí*. Lo primero ya está resuelto → **solo queda el porqué de hoy**, y a veces hasta eso es evidente. No hace falta una regla especial: sale del objetivo del paso.\\n\\n**Caso:** vender un servicio de software por videollamada a una empresa que nunca lo ha usado.\\n**Razonamiento:** el sistema aplica igual. Cliente nuevo → doctrina de adquisición. Canal remoto → SEE físico no aplica, pero el entusiasmo del tono sí. \\"Lee el lugar\\" no existe, así que se pregunta. Los 3 Territorios se traducen: producto = qué usan hoy, servicio = cómo los atiende su proveedor, precio = qué pagan. **Nada del esqueleto cambia.**\\n\\n**Caso:** un vendedor dice que el cliente no le reconoce ningún problema, pero él ve claro que sí lo tiene.\\n**Razonamiento:** aplica 1.5. La confirmación explícita no es requisito. Si hay evidencia real — algo que dijo, algo que vio, algo propio de su giro — **avanza presentando la situación resuelta**, no el problema reconocido. Insistir en que lo admita lo pone a la defensiva y apaga lo emocional, que es donde está la venta. **El límite:** si el cliente ya negó explícitamente ese problema, insistir es fabricar, y eso es Nivel 1.\\n\\n**Caso:** un vendedor lleva tres días sin cerrar y está desanimado.\\n**Razonamiento:** esto es Parte 3, no Parte 2. Aplica Ley de Promedios, los 3 Tipos de Día (día C), gumball, y controlables vs no controlables. **No es un problema de técnica: es de protección de la actitud, que es la variable de entrada del sistema.**\\n\\n**Caso:** un manager ve que su vendedor presenta mucho y cierra poco, y quiere saber qué corregir.\\n**Razonamiento:** el indicador señala una zona, no una causa. Puede ser el cierre, pero también un descubrimiento que no encontró el dolor real, CPR insuficiente, o una presentación que se alargó y cayó en KILL. **Números + conversación observada.** Pídele una práctica o acompáñalo en campo antes de concluir.\\n\\n## Sobre la incertidumbre\\nEste documento tiene procedencia marcada por una razón: **lo que está como `CAMPO` no se puede verificar contra la fuente.** Si un caso depende de doctrina `CAMPO` y hay duda, la autoridad es Emilio, no la inferencia.\\n\\n**Nunca completes un hueco de doctrina inventando.** Di qué falta y pídelo.\\n\\n**Y nunca inventes un hecho comercial** — una ventaja, una comparación con la competencia, un dato de mercado. Eso no es doctrina: es información de la empresa, y si no está en su contexto, se pide.","is_active":false,"created_at":"2026-09-29T17:14:32.375719+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"9425a826-489b-4128-8b79-4f115b60bc7f","version":6,"section_key":"fundamento","order_index":1,"title":"PARTE 1 · EL FUNDAMENTO","body":"# EL CEREBRO DE CLOSER\\n## Doctrina canónica del sistema de venta\\n\\n*Versión 1.0 · Fuente única de verdad*\\n\\n---\\n\\n## CÓMO USAR ESTE DOCUMENTO\\n\\nEsto no es un manual ni un resumen. Es el entendimiento del sistema, escrito para que se pueda **razonar** con él.\\n\\nCada técnica se presenta con tres cosas: **qué es**, **por qué funciona** (el mecanismo humano detrás) y **qué la rompe**. El porqué importa más que el qué, porque de él se deducen los casos que ninguna lista cubre.\\n\\nEjemplo de la diferencia: una lista diría *\\"no digas «¿cómo lo ves?»\\"*. Este documento dice *\\"toda pregunta que permita aprobar o posponer le entrega el control al cliente\\"* — de donde se deduce que *\\"¿le late?\\"*, *\\"¿qué opina?\\"* y *\\"¿le parece?\\"* también están mal, aunque nadie los haya escrito nunca.\\n\\n**Regla de razonamiento:** ante un caso que este documento no cubre explícitamente, no inventes. Busca el principio que aplica y dedúcelo. Si dos principios chocan, gana el de mayor jerarquía (ver Parte 6).\\n\\n### Etiquetas\\n\\n**PROCEDENCIA** — `FUENTE` (sistema original Credico/Cydcor) · `CAMPO` (evolución de Emilio Fanjul) · `CLOSER` (andamiaje pedagógico)\\n\\n**CANAL** — `PRESENCIAL` (requiere cuerpo o presencia) · `UNIVERSAL` (funciona en persona, teléfono, mensaje o correo)\\n\\n---\\n\\n---\\n\\n# PARTE 1 · EL FUNDAMENTO\\n\\n## 1.1 El problema que resuelve todo el sistema `FUENTE`\\n\\nCuando abres una conversación con un desconocido, **su atención está dividida en tres**:\\n\\n- **Un tercio** sigue en lo que estaba haciendo\\n- **Un tercio** está resolviendo preguntas básicas: quién eres, qué quieres, por qué me hablas\\n- **Solo un tercio** está disponible para ti\\n\\n> **De aquí sale la razón de ser de los 6 pasos:** si vas directo a presentar, le estás hablando a un tercio de una persona. Cada paso previo existe para recuperar una porción de esa atención.\\n\\nLa Introducción libera el primer tercio (deja de pensar en lo que hacía). La Historia Breve libera el segundo (ya sabe quién eres y a qué vienes). Solo entonces tienes casi toda su atención — y solo entonces vale la pena presentar.\\n\\n**Esto explica por qué saltarse pasos no acelera nada: presentarle a alguien distraído es desperdiciar tu mejor material.**\\n\\n## 1.2 La Línea Recta `CAMPO` `UNIVERSAL`\\n\\nUna venta avanza en línea recta, de izquierda a derecha, a través de los 6 pasos.\\n\\n**Nada te regresa. Lo que ya recorriste, quedó.** Lo único que puede pasar es que algo te **saque de la línea y te pause**.\\n\\nLa imagen: vas dibujando la línea hacia la derecha y de pronto llega una objeción. Ahí dejas de avanzar y la línea sube — saliste. Pero no retrocede. Está en ti resolver y volver al punto donde ibas.\\n\\n| Elemento | Relación con la línea |\\n|---|---|\\n| Los 6 pasos | La línea misma |\\n| CPR / FORMS | Salida **deliberada** — sales tú, y regresas |\\n| Bloqueos → AIR, Ataque Preventivo | Salida **impuesta** al inicio |\\n| Objeciones → RRR, FFF | Salida **impuesta** después de entender |\\n| Close With Action | Lo que te devuelve y te mueve al siguiente tramo |\\n| Los 3 No seguidos | La señal de que ya no hay línea que recorrer |\\n\\n**Diagnóstico que le da al vendedor:** cuando una visita sale mal, la pregunta no es *\\"¿qué técnica olvidé?\\"* sino **\\"¿dónde salí de la línea y por qué no regresé?\\"**\\n\\n## 1.3 El principio de la balanza `FUENTE` `UNIVERSAL`\\n\\nNadie compra por precio. Compra cuando el **valor percibido** pesa más que el **costo percibido**. Cuanto mayor la brecha, mayor el impulso.\\n\\nY el costo no es solo dinero: es tiempo, riesgo de cambiar, esfuerzo, y la posibilidad de haberse equivocado.\\n\\n> **La regla que convierte esto en herramienta:** con cada frase, cada gesto y cada silencio estás haciendo una de cuatro cosas — subiendo el valor, bajándolo, subiendo el costo, o bajándolo.\\n>\\n> **No hay frases neutras.**\\n\\nDe aquí se deducen cosas que ninguna lista de reglas contiene:\\n- Titubear al dar un precio sube el costo percibido\\n- Disculparte baja tu valor\\n- Mencionar algo que **no** tienes, no aplica o no está disponible **baja el valor sin que nadie te lo pidiera** — y por eso se omite\\n- Contar un caso real de otro cliente sube el valor\\n\\n**Cost vs Value no es tanto una habilidad como una herramienta de evaluación:** revisa cada parte de tu conversación y pregúntate qué plato movió.\\n\\n## 1.4 La gente compra, pero no quiere que le vendan `FUENTE`\\n\\nEste es el principio psicológico que atraviesa todo el sistema.\\n\\nA las personas les gusta comprar. Lo que les desagrada es **sentir que les están vendiendo**. Tienen una alarma calibrada para detectar al vendedor, y en cuanto se activa, todo lo que digas después se procesa con desconfianza.\\n\\n> **Casi todas las técnicas de este sistema son formas de obtener un resultado de venta sin activar esa alarma.**\\n\\n- **Gasman** — pedir permiso te delata como forastero; asumir que perteneces no dispara nada\\n- **CPR** — ser persona antes que vendedor\\n- **Descubrimiento** — el vendedor promedio habla; el que pregunta rompe el patrón que la alarma busca\\n- **Close With Action** — nunca pides el sí, porque pedirlo enciende la alarma\\n- **Indiferencia** — la presión genera resistencia; quitarla la disuelve\\n- **FFF** — estar de acuerdo primero te vuelve distinto del vendedor promedio, *y por eso te escuchan*\\n\\n## 1.5 La decisión es emocional antes que racional `CAMPO`\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente siente algo primero, y después construye la razón que lo justifica.\\n\\nEsto no contradice el diagnóstico ni la construcción de valor: los explica. La doctrina fuente lo dice sin rodeos — **\\"el impulso es otra palabra para la emoción\\"**.\\n\\n**Lo que se deduce de aquí, y que corrige el error de modelar la venta como un proceso lógico:**\\n\\n- **El cliente no necesita reconocer un problema para sentir el alivio de resolverlo.** Por eso \\"pintar imágenes\\" funciona: no argumenta, hace sentir.\\n- **Pelear por el reconocimiento explícito mata la venta.** Insistir en que admita algo lo pone a la defensiva, y la defensiva apaga lo emocional — que era donde estaba la venta.\\n- **El 80% indiferente no tiene un problema urgente**, y aun así compra. Se mueve por los factores de impulso, no por el diagnóstico.\\n- **Un argumento perfecto dicho por alguien en quien no confía, no pesa.** Y uno mediocre dicho por alguien cercano, sí. De ahí la importancia real del CPR.\\n\\n> **La regla operativa:** el sistema construye una situación deseable, no un caso lógico. La razón sirve para que el cliente pueda **justificar** la decisión — no para que la tome.\\n\\n⚠️ **Y esto no autoriza a manipular.** El Nivel 1 sigue intacto: el impulso se construye con verdad. La diferencia es que construir una imagen real y deseable es legítimo; fabricar urgencia, escasez o problemas no lo es.\\n\\n---\\n\\n## 1.6 Sin groserías `CAMPO` `UNIVERSAL`\\n\\nCloser no dice groserías, y el vendedor no las necesita. Las groserías no hacen falta para comunicar lo que quieres decir, y en la mayoría de las empresas le quitan profesionalidad al vendedor. Si el cliente las usa, no hace falta imitarlo para conectar: se conecta con interés genuino y con el sistema, no con el lenguaje.","is_active":true,"created_at":"2026-10-01T18:11:26.114188+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"3e679020-13a2-43f9-8d99-b96f5ac01d0a","version":6,"section_key":"pasos","order_index":2,"title":"PARTE 2 · LOS 6 PASOS","body":"# PARTE 2 · LOS 6 PASOS\\n\\nEl sistema original tiene **5 pasos** `FUENTE`: Introducción, Historia Breve, Presentación, Cierre, Consolidación.\\n\\nCloser enseña **6** `CAMPO`: se separa **Descubrimiento** como paso propio. En la fuente las preguntas de calificación viven dentro del flujo; separarlas reconoce que diagnosticar y presentar son habilidades distintas que fallan por razones distintas.\\n\\n---\\n\\n## PASO 1 · INTRODUCCIÓN\\n### *Una sola oportunidad para una primera impresión*\\n\\n**Qué logra:** liberar el primer tercio de atención y ganarte el derecho a seguir hablando.\\n\\n**Qué NO es:** aquí no dices quién eres ni a qué vienes. Eso es el Paso 2. Confundirlos es el error doctrinal más común.\\n\\n### SEE / SCE `FUENTE` `PRESENCIAL`\\n**S**mile · **E**ye contact · **E**nthusiasm — Sonrisa, Contacto visual, Entusiasmo\\n\\n- **Sonrisa** — signo internacional de amistad. Elimina el miedo y crea confianza.\\n- **Contacto visual** — genera confianza, mantiene el control de la conversación, **y es una señal de compra fuerte cuando el cliente lo hace**.\\n- **Entusiasmo** — crea impulso y curiosidad. Si estás emocionado, asumen que hablas de algo emocionante. **Y al revés también funciona:** si suenas aburrido de tu producto, nadie va a estar más emocionado que tú.\\n\\nSe combinan con **lenguaje corporal abierto** y **tono de voz fuerte**.\\n\\n> ⚠️ **Límite de canal:** SEE es físico. En texto o voz no se puede evaluar. Se enseña, se pide, y se marca como *\\"esto se practica en persona\\"*. Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**.\\n\\n### Regla del 10% `FUENTE` `PRESENCIAL`\\nLee el nivel de emoción del cliente y ponte **10% por encima** de él. No al doble: 10%.\\n\\n**Por qué:** llegar gritando con alguien tranquilo lo aleja tanto como llegar apagado con alguien entusiasmado. El 10% jala sin romper.\\n\\n### Ice Breaker `FUENTE` `UNIVERSAL`\\nCumplido genuino, chiste sencillo o comentario ligero.\\n\\nPuede ser sobre **la persona**, **el lugar**, o **algo en común**. No está atado a ningún tipo de negocio.\\n\\n**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee al instante y se cierra **más** que antes — porque ahora sabe que le están aplicando una técnica.\\n\\n### La escalera de la especificidad `CAMPO` `UNIVERSAL`\\n\\nLa observación y la pregunta de la apertura se miden igual: **¿se la harías a cualquiera?** Entre más específica para ESE cliente en ESE momento, más vale.\\n\\n- **Escalón 1 — de cortesía.** Se la harías a cualquiera: *\\"¿cómo está?\\"*, *\\"qué gusto saludarlo\\"*. Cumple lo mínimo porque le devuelve la palabra, pero no construye nada.\\n- **Escalón 2 — del entorno.** Sale de lo que ves ahí, en ese momento: *\\"veo que no paran, ¿siempre está así de movido?\\"*. Solo tiene sentido en ese lugar.\\n- **Escalón 3 — de él.** Solo se la harías a él, porque sabes algo de antes: *\\"¿cómo sigue? ¿va mejorando?\\"*.\\n\\n**La prueba del escalón 2:** nombra algo concreto que viste ahí —el movimiento, que está lleno, un cambio, algo nuevo—. Un adjetivo genérico, como *\\"qué bien se ve el local\\"* o *\\"qué bonito\\"*, se lo dirías a cualquiera: es escalón 1.\\n\\n> **Las mismas palabras pueden estar en escalones distintos.** *\\"¿Cómo está?\\"* a secas es escalón 1; *\\"¿cómo está? ¿va mejorando?\\"* a alguien que estuvo enfermo es escalón 3. Lo que sube el escalón no son las palabras: es qué tanto sabe la pregunta de él.\\n\\n**La relación cambia la escalera.** Con un cliente nuevo no existe el escalón 3 —no hay historia con él—, así que el escalón 2 es la excelencia. Con un recurrente la meta es el escalón 3, y el 2 puede ser un error: preguntarle si siempre está así de movido a alguien que visitas desde hace años le dice que no lo tienes presente (ver 4.1b).\\n\\n**Una pregunta de cortesía no es una falla: es el primer escalón.** La falla es no preguntar nada: sin ninguna pregunta, el cliente no tiene qué contestar y la conversación se muere ahí.\\n\\n**La pregunta va al final: es la que le devuelve la palabra al cliente, con control hacia donde quieres que vaya la conversación.** La que mejor lo hace sale de la observación y cierra la apertura: *\\"veo que no paran, ¿siempre está así de movido?\\"*. Un *\\"¿cómo está?\\"* dentro del saludo no basta si después sigues hablando: el cliente espera a que termines en vez de contestar, y la palabra se la devolviste con un comentario, no con una pregunta. Convertir la observación en la pregunta final es como se sube de escalón.\\n\\n### Especificidad y ligereza son dos cosas distintas `CAMPO` `UNIVERSAL`\\n\\nUn comentario de apertura se mide con dos preguntas diferentes. **¿Se lo dirías a cualquiera?** es la especificidad: la escalera. **¿Baja la guardia?** es la ligereza: humor suave, un guiño o calidez en lo que dices.\\n\\nUna no garantiza la otra. *\\"Veo que tiene cuatro cajas de filtros de una marca y dos de otra\\"* es muy específico, y suena a inspección. *\\"¡Qué buen día hace, eh!\\"* es ligero, y se lo dirías a cualquiera. *\\"¿Qué les pasó hoy que está lleno? ¿Regalan algo o qué?\\"* tiene las dos.\\n\\n**La ligereza se mide en lo que haces, no en cómo reacciona el cliente.** Un buen chiste puede no hacerle gracia a un cliente rojo, o a alguien que viene enojado ese día, y no por eso se hizo mal. La reacción del cliente puede confirmar que algo funcionó; nunca puede condenar una acción bien hecha. Es la lógica de los controlables: al vendedor se le mide por lo que controla, y el humor del cliente no es una de esas cosas.\\n\\nLa calidez que vive en el tono de voz no se puede calificar por escrito: se enseña igual, se practica igual, y la escucha el manager (ver 1.7).\\n\\n### Teoría del Gasman `FUENTE` `UNIVERSAL`\\nSer asumido y confiado, con alta indiferencia.\\n\\nEl gasista que viene a leer tu medidor entra con una autoridad que nace de sentir que **debe estar ahí** — no es una intrusión. Nadie lo detiene, y no es por su permiso: es por su postura.\\n\\n> **El mecanismo:** cuando preguntas *\\"¿tiene un minutito?\\"* haces dos cosas a la vez — le entregas el control, y le ofreces una salida que no le cuesta nada tomar. El cliente que dice \\"ahorita no\\" no está siendo grosero: tomó la puerta que le abriste.\\n>\\n> **La autoridad no se pide. Se asume.**\\n\\n### Regla doctrinal del paso `CAMPO`\\n**La identificación (nombre y empresa) es permitida pero nunca requerida aquí.** Su ausencia jamás se penaliza.\\n\\nSi el cliente pregunta *\\"¿y usted quién es?\\"*, **ganaste la introducción** — esa pregunta es la puerta natural al Paso 2, no una falla.\\n\\n---\\n\\n## PASO 2 · HISTORIA BREVE\\n### *Explica tu propósito de manera concisa*\\n\\n**Qué logra:** liberar el segundo tercio de atención. El cliente deja de preguntarse quién eres y qué quieres.\\n\\n### KISS vs KILL `FUENTE` `UNIVERSAL`\\n**K**eep **I**t **S**hort and **S**imple — contra **K**eep **I**t **L**ong and **L**engthy.\\n\\nQuién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible.\\n\\n> **El mecanismo:** cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él — y de los discursos uno se defiende.\\n\\n**Y después de la historia, preguntas.** La fuente es explícita: *\\"en la mayoría de los casos es más efectivo pasar directamente a las preguntas de calificación que dar una larga explicación.\\"*\\n\\nTu historia breve no existe para que te entiendan a ti. **Existe para ganarte el derecho de preguntarle a él.**\\n\\n### CPR — Create Personal Relations `FUENTE` `UNIVERSAL`\\n> *\\"Eres tanto, si no más, el producto que los productos que representas.\\"*\\n\\n**Se aplica durante TODA la conversación**, no en un paso.\\n\\n**El mecanismo:** el cliente no puede evaluar tu producto todavía — no lo ha probado, no conoce tu empresa, no sabe si le van a cumplir. Lo único que sí puede evaluar desde el primer segundo **eres tú**. Y esa evaluación la hace mucho antes que la otra.\\n\\n**Y hace dos trabajos distintos, ambos indispensables:**\\n\\n**1 · Que te contesten de verdad.** Sin relación, las preguntas del Paso 3 reciben respuestas de cortesía. A un desconocido nadie le cuenta lo que le está fallando.\\n\\n**2 · Que te crean.** Este es el más importante y el que casi nadie ve.\\n\\n> Si un amigo te dice que un producto es bueno, le crees. Si te lo dice alguien que gana comisión por vendértelo, lo descuentas automáticamente — no porque lo creas mentiroso, sino porque sabes que tiene interés.\\n>\\n> **Es la misma frase, dicha por dos personas, y produce dos efectos opuestos.**\\n\\nLo que decide cuál de los dos efectos produces **no es tu argumento: es qué tan cerca estás de ser alguien en quien confía.** Por eso el CPR no es cortesía ni relleno — **es lo que determina si tus argumentos pesan o se descuentan.**\\n\\nY conecta directo con el Efecto Jones: la gente no confía en un desconocido incentivado a vender, pero sí deja que gente cercana valide un producto. **El CPR te acerca a ese lado de la línea.**\\n\\n### FORMS `FUENTE` `UNIVERSAL`\\n**F**amily · **O**ccupation · **R**ecreation · **M**otivation · **S**ports\\n\\nLos cinco caminos a la persona. Más cumplidos genuinos y chistes sencillos.\\n\\n> **La palabra que lo decide todo es *genuinos*.** Un interés fingido se nota, y cuesta más que no haber preguntado — porque ahora el cliente sabe que le aplicaste una técnica. Si un tema no te interesa de verdad, busca otro de los cinco.\\n\\n**No requiere cierta personalidad ni ser naturalmente extrovertido: se aprende.**\\n\\n### El desvío con regreso `CAMPO` `UNIVERSAL`\\nLa mecánica que hace que el CPR no mate la venta.\\n\\nSales de la línea a propósito, das **uno o dos intercambios personales**, y **regresas**. Puedes volver a salir más adelante, pero siempre avanzando.\\n\\n**Dos errores, ambos caros:**\\n- **Nunca salir** → no hay relación, y no te van a contestar nada en el Paso 3\\n- **Salir y no regresar** → el cliente se acomoda a platicar y la venta se estanca\\n\\n> **El cliente NUNCA te va a regresar a la línea.** Cuando la plática se pone agradable, él está cómodo — nadie interrumpe una conversación agradable para hablar de negocios. El único que puede regresar eres tú.\\n\\n### Bloqueo vs Objeción `FUENTE` — *la distinción que organiza todo el manejo de resistencia*\\n\\n**BLOQUEO** — un reflejo. Llega **ANTES** de entender.\\n*\\"No tengo tiempo\\" · \\"No me interesa\\" · \\"No estoy comprando nada\\" · \\"Ya tengo con quién\\"*\\nNo hubo procesamiento. Es la puerta cerrándose sola.\\n\\n**OBJECIÓN** — una preocupación razonada. Llega **DESPUÉS** de entender.\\n*\\"Está caro\\" · \\"Ya tengo proveedor y me cumple\\" · \\"Lo tengo que consultar\\"*\\nAquí sí hubo pensamiento.\\n\\n> **Por qué importa la diferencia:** discutir con un reflejo lo convierte en una posición. El cliente dijo \\"no me interesa\\" sin pensarlo; si lo peleas, tiene que defenderlo — y al defenderlo se lo cree. **Le acabas de crear un \\"no\\" real que no tenía.**\\n>\\n> E ignorar una objeción real ofende a alguien que sí te escuchó y sí pensó.\\n>\\n> **La misma frase se maneja de dos maneras opuestas según cuándo llegó.**\\n\\n### AIR `FUENTE` `UNIVERSAL`\\n**A**gree · **I**gnore · **R**esume — Acepta, Ignora, Resume\\n**Cuándo:** bloqueos al inicio.\\n**Cómo:** reconoce con *\\"entiendo\\"* o *\\"por supuesto\\"*, no lo discutas, y continúa.\\n\\n> **El tercer movimiento es el que falla.** Casi todos aceptan bien y casi todos logran no discutir — y después se quedan parados esperando, o peor, vuelven a pedir permiso. Ahí se pierde todo lo ganado.\\n\\n### Ataque Preventivo `FUENTE` `UNIVERSAL`\\n**Cuándo:** intro o historia breve, si hay negativos comunes del territorio.\\n**Cómo:** *\\"si das la negativa antes de que el cliente lo haga, ya no es una negativa.\\"*\\n\\n**El mecanismo:** le quitas el argumento de las manos, y además te vuelves creíble — **quien reconoce lo malo se gana el derecho a que le crean lo bueno.**\\n\\n**Dos formas de arruinarlo:**\\n- **En tono de disculpa** → deja de ser adelantarse y se vuelve defenderse de algo que nadie reclamó\\n- **Con un negativo inventado** → no desactivas nada, plantas una preocupación nueva\\n\\n### Close With Action `FUENTE (dentro de FFF) + CAMPO (generalizado)` `UNIVERSAL`\\n**Es el Poder de Sugestión en ejecución.**\\n\\nUna pregunta o acción cuya respuesta **solo tiene sentido si el cliente está avanzando**. Su respuesta *es* el sí. Nunca lo pides explícito.\\n\\n- *\\"¿Cómo se escribe su apellido?\\"* → al contestar, aceptó tu respuesta y sigue en el alta\\n- *\\"¿Prefiere el jueves o el viernes?\\"* → *\\"el viernes\\"* significa que lo quiere **y** cuándo\\n\\n**Se ejecuta en cada tramo de la línea:** en descubrimiento es la siguiente pregunta; en presentación es continuar donde ibas; en cierre es la alternativa de sí/sí.\\n\\n> **El momento crítico:** justo después de resolver algo. El vendedor promedio se queda callado esperando permiso para seguir. En ese silencio el cliente retoma el control y cierra la conversación con amabilidad. **No te está rechazando: le devolviste el volante.**\\n\\n---\\n\\n## PASO 3 · DESCUBRIMIENTO `CAMPO`\\n### *Encontrar el dolor real*\\n\\n*No existe como paso en la fuente. Toda esta sección es construcción de Closer sobre el principio de \\"preguntas de calificación\\".*\\n\\n### El principio rector\\n**Primero el examen, luego la receta.** El vendedor promedio llega a recetar: trae su producto favorito buscando dónde encajarlo. El Closer llega a diagnosticar.\\n\\n**La ironía:** el que pregunta vende más que el que habla.\\n\\n### RRR — Read, Relate, Relax `FUENTE` `UNIVERSAL`\\nLee · Conecta · Relaja.\\n\\nTres cosas que leer: **el ambiente, la demografía de la persona, y su estado de ánimo.**\\n\\n**El mecanismo:** no quieres forzar a nadie a subir a tu nivel de emoción ni a adaptarse a ti. **Tú te adaptas primero.**\\n\\n> ⚠️ **Colisión de acrónimos:** existe un segundo RRR en la doctrina (Repeat, Reassure, Resume) para objeciones. Ambos se conservan con su nombre original. Al enseñar el segundo hay que advertirlo explícitamente.\\n\\n### Los 3 Territorios del Dolor `CLOSER` `UNIVERSAL`\\nTodo dolor comercial vive en uno de tres territorios:\\n\\n- **PRODUCTO** — lo que vende o usa\\n- **SERVICIO** — cómo lo trata su proveedor actual\\n- **PRECIO** — lo que paga y lo que gana\\n\\n> **El mismo territorio se pregunta distinto según el tipo de cliente.** Ver Parte 4.\\n\\n#### Cómo se investiga el territorio PRECIO `CAMPO`\\n\\nEl territorio PRECIO es el más fácil de arruinar, porque la pregunta natural es la incorrecta.\\n\\n⚠️ **NUNCA le pidas al cliente su opinión ni su aprobación sobre precios.** Prohibido: *\\"¿cómo ve los precios?\\"*, *\\"¿hay algo que sienta muy arriba?\\"*, *\\"¿le parece competitivo?\\"*, *\\"¿estoy bien de precio?\\"*\\n\\n**Tres razones, y cada una basta:**\\n\\n**1. Le pides que construya una posición sobre tu precio antes de que exista valor.** Si contesta *\\"están caros\\"*, ya no es una impresión: es algo que declaró en voz alta y ahora tiene que defender. **Te creaste una objeción de precio que no existía.**\\n\\n**2. Cedes la autoridad sobre el precio.** El precio no lo determina la percepción del cliente: lo determina lo que ofreces. Preguntarle su opinión comunica que estás dispuesto a moverlo según lo que conteste, y te vuelve regateable antes de haber presentado nada.\\n\\n**3. Renuncias a tu ventaja.** Tú conoces el mercado: ya sabes qué está caro y qué está barato. **Muchas veces el cliente no sabe que está pagando de más, y tú sí.** Preguntarle su opinión te iguala a alguien que no sabe, cuando saber es exactamente lo que te hace valioso.\\n\\n**Lo que sí se investiga en este territorio son HECHOS, no opiniones:**\\n\\n- ¿A cómo compra hoy? (dato)\\n- ¿Cada cuánto le suben? ¿Le avisan antes? (dato)\\n- ¿Le manejan crédito o de contado? ¿Qué plazo? (dato)\\n- ¿Cuánto le queda de margen en esa línea? (dato)\\n- ¿Le ha tocado que un cliente se le vaya por precio? (experiencia, no opinión)\\n\\n**La diferencia:** un hecho te da información que puedes usar. Una opinión sobre tu precio te da una objeción que tendrás que atravesar.\\n\\n> **Y si el cliente dice que tu precio está mal, el diagnóstico correcto no es bajarlo.** Es que no encontraste su dolor, o no construiste suficiente valor. **El problema nunca está en el número: está en la balanza.**\\n\\n### La Escalera de Capas `CLOSER` `UNIVERSAL`\\n**CAPA 1 — Hechos.** Fáciles, cero riesgo. Abren la plática y te dan el mapa.\\n**CAPA 2 — La puerta.** Aquí el cliente suelta una pista... o cierra con un \\"bien\\". Depende de cómo preguntes.\\n**CAPA 3 — El dolor.** Solo se abre si recoges la pista y profundizas con preguntas abiertas.\\n\\n### La Pregunta Específica `CAMPO` `UNIVERSAL`\\n> **El \\"bien\\" no es información: es un reflejo social.**\\n\\nCuando preguntas *\\"¿qué tal le va?\\"*, el cliente no consulta su experiencia — dispara la respuesta cortés que trae cargada. Y admitir un problema ante un desconocido tiene costo social: parece queja, o parece que eligió mal.\\n\\n**La solución tiene dos formas:**\\n- **ESPECÍFICA** — nombra un dato o situación concreta que tenga que ir a buscar. *\\"¿Le ha tocado quedarse sin su producto estrella?\\"*\\n- **NORMALIZADA** — da permiso citando a otros. *\\"Varios clientes me comentan que batallan con faltantes, ¿a usted le pasa?\\"* (Es el Efecto Jones aplicado a descubrimiento.)\\n\\n**Y el orden importa:** concreta para **abrir** (capa 2), abierta para **excavar** (capa 3).\\n\\n#### Suggestive Language — dale de dónde agarrarse `FUENTE` `UNIVERSAL`\\n\\nEs la S de FUJIES aplicada al descubrimiento, y es lo que convierte una pregunta que se muere en una que da información.\\n\\n**El problema de la pregunta abierta sola:** obliga al cliente a construir la respuesta desde cero. Eso cuesta esfuerzo, y como no le urge ayudarte, contesta lo más corto que puede — o de plano *\\"pues no sé\\"*.\\n\\n**La solución: después de preguntar, sugiere opciones.**\\n\\n> *\\"¿Qué familias son las que más se te mueven? ¿Anticongelantes? ¿Aceite de motor? ¿Diésel? ¿Moto?\\"*\\n>\\n> *\\"¿A cómo compras el líquido de frenos? ¿70? ¿80? ¿90?\\"*\\n\\n**Por qué funciona, y son tres cosas a la vez:**\\n\\n1. **Le das de dónde agarrarse.** O elige una de tus opciones, o te corrige con el dato real — *\\"no, más bien 95\\"*. **Y esa corrección es información que la pregunta abierta nunca habría sacado.**\\n\\n2. **Le demuestras que conoces su negocio.** Nombrar las familias correctas o el rango de precio correcto te posiciona como alguien que sabe, no como alguien que está averiguando.\\n\\n3. **Crea un poco de urgencia.** Una pregunta con opciones se contesta rápido; una abierta se puede posponer con un *\\"déjame ver\\"*.\\n\\n**Cómo se usa bien:**\\n- Las opciones tienen que ser **reales y del giro del cliente**. Si sugieres familias que él no maneja, demuestras lo contrario de lo que buscabas.\\n- **Tres o cuatro, no una lista.** Es para ayudarlo a contestar, no para que elija de un catálogo.\\n- El rango de precio **tiene que ser creíble.** Sugerir cifras muy lejanas de la realidad te desacredita.\\n- Y **no lo uses para plantar una respuesta.** Si el cliente te corrige, esa es la respuesta buena — no insistas en la tuya.\\n\\n> **Es la misma lógica del cierre de alternativa, aplicada al descubrimiento:** no preguntas al aire, das opciones donde cualquier respuesta te sirve.\\n\\n### El Barrido `CLOSER` `UNIVERSAL`\\nTerritorio limpio → ni insistas ni te rindas: **cambia de territorio.**\\n\\nEl dolor casi siempre existe, solo que vive en otra zona del mapa. Insistir en zona sana te vuelve interrogador; rendirte regala la visita.\\n\\n### El dolor y la confirmación `CLOSER` `UNIVERSAL`\\nCuando el dolor aparece, **devuélveselo con SUS palabras**. *\\"Entonces lo que más le pega es X, ¿cierto?\\"*\\n\\nEso hace dos cosas: confirma que entendiste, y **le da forma consciente a algo que a lo mejor solo sentía.**\\n\\n> ⚠️ **Pero la confirmación explícita no es requisito para avanzar.**\\n>\\n> Muchas veces el cliente no va a admitir el problema. No porque no lo tenga — sino porque admitirlo suena a queja, o a que eligió mal, o simplemente porque **no lo tiene consciente**. Nadie anda por la vida con una lista de sus problemas operativos.\\n>\\n> Y aun así te sigue escuchando. **Eso ya es información.**\\n\\n**Lo que sí necesitas** es haber leído el problema con evidencia suficiente: algo que dijo, algo que viste, algo que su tipo de negocio hace probable. **Lo que no necesitas es su permiso verbal.**\\n\\n### La venta es emocional antes que racional `CAMPO`\\n\\nEste es el principio que corrige el error de modelar la venta como un proceso lógico.\\n\\n> **La mayoría de las decisiones de compra son mucho más emocionales que cognitivas.** El cliente no llena una hoja de cálculo: siente algo, y después construye la razón.\\n\\nConsecuencias que cambian cómo se ejecuta todo el sistema:\\n\\n- **Un cliente puede no reconocer un problema y aun así sentir alivio cuando se lo resuelves.** El impulso no viene de que aceptó el diagnóstico: viene de imaginar la situación resuelta.\\n- **Por eso \\"pintar imágenes\\" funciona** — no argumenta, hace sentir.\\n- **Por eso el vendedor no debe pelear por el reconocimiento explícito.** Insistir en que el cliente admita un problema lo pone a la defensiva y mata lo emocional, que era donde estaba la venta.\\n- **Y por eso el impulso se puede construir sin que haya un dolor declarado.** El 80% indiferente no tiene un problema urgente: se mueve por los factores de impulso, no por el diagnóstico.\\n\\n**La regla operativa:** si el cliente confirma el dolor, úsalo con sus palabras — es lo más fuerte que tienes. **Si no lo confirma pero la evidencia está, avanza igual**, presentando la situación resuelta en vez del problema reconocido.\\n\\n⚠️ **Lo que sigue prohibido es fabricar.** Leer un dolor probable no es inventarlo. La diferencia: leer se apoya en evidencia real — algo que dijo, algo que viste, algo propio de su giro. Fabricar es afirmar un problema **que el cliente ya negó** o del que no hay ningún indicio.\\n\\n### La regla del investigador\\n**El dolor nunca se pregunta directo.** *\\"¿Qué problemas tiene?\\"* produce *\\"ninguno\\"*, garantizado. Se deja emerger.\\n\\n### Luz Verde — 10/80/10 `FUENTE` `UNIVERSAL`\\n**10% negativos · 80% indiferentes · 10% positivos.**\\n\\n1. Sal de las luces rojas **rápido y educadamente**\\n2. Las amarillas reciben tu mejor presentación — pero si no dan señales de compra, muévete\\n3. Las verdes reciben tiempo, relación y resolución de dudas\\n\\n**Los factores de impulso existen principalmente para convertir al 80% indiferente.**\\n\\n#### El rojo verdadero y el que quiere pero no puede `CAMPO`\\n\\nLa luz roja no es cualquier \\"no\\". Es un tipo específico de cliente, y confundirlo cuesta ventas.\\n\\n**ROJO GENUINO** — no quiere. Es cortante, tajante, desganado. Muchas veces medio grosero. Y tiene un costo escondido: **interactuar de más con él desgasta tu actitud**, que es la variable de entrada de todo tu sistema. Con este, salir rápido y bien es la ejecución correcta.\\n\\n**AMARRADO TEMPORALMENTE** — quiere y no puede. Te recibe con gusto, te habla con honestidad, y su impedimento es una **circunstancia que va a cambiar**: un contrato de exclusividad, un inventario recién surtido, un presupuesto agotado, no ser él quien decide las compras grandes.\\n\\n> **Este no es rojo: es verde amarrado.** Y con él, rendirse es la falla más cara del oficio — porque ese cliente sí quería comprarte y el vendedor se fue solo.\\n\\n**Cómo se distinguen:** el rojo se nota en el trato. Es seco, no da información, quiere que te vayas. El amarrado hace lo contrario: es amable, te explica su situación con detalle, y muchas veces se disculpa por no poder.\\n\\n#### Casi toda restricción tiene bordes `CAMPO`\\n\\nY aquí está la mecánica que separa al vendedor promedio del que crece cuentas.\\n\\nCuando un cliente dice que no puede, **el promedio lo toma como total y se va**. El Closer investiga hasta dónde llega:\\n\\n- **¿Qué cubre exactamente?** Una exclusividad casi nunca abarca todas las familias\\n- **¿Qué queda fuera?** Ahí está la venta que la competencia no vio\\n- **¿Hasta cuándo dura?** Para volver justo cuando se libere, antes que nadie\\n\\n> Un contrato que cubre lubricantes, anticongelantes y grasas **deja fuera el líquido de frenos.** Y el vendedor que preguntó se lleva una venta de un cliente que \\"no podía comprar\\".\\n\\n**Y la relación sigue construyéndose mientras tanto.** Seguir visitando a un amarrado no es perder el tiempo: es estar presente el día que la restricción se acabe. El que se rindió no va a estar ahí.\\n\\n⚠️ **La línea:** investigar los bordes no es presionar. Si el cliente ya dijo que algo está dentro de su compromiso, insistir en eso es pedirle que rompa su palabra — y eso quema la relación. Se busca lo que **sí** puede, nunca se pelea lo que no.\\n\\n### QTQP `FUENTE` `UNIVERSAL`\\n**Q**uality **T**ime with **Q**uality **P**eople.\\n\\n> *\\"Perder tiempo y energía con las personas equivocadas destruye tu capacidad de ser lo suficientemente urgente\\"* — y la urgencia es de lo que vive tu ley de promedios.\\n\\nCada minuto con un rojo se lo quitas a un amarillo que sí podía comprar hoy.\\n\\n---\\n\\n## PASO 4 · PRESENTACIÓN\\n### *Construye valor y disminuye el costo*\\n\\n**Qué logra:** convertir el dolor descubierto en valor percibido, y subir el impulso.\\n\\n### Las herramientas de la presentación `FUENTE`\\n1. Encontrar problemas y proporcionar soluciones\\n2. **Pintar imágenes** — que imaginen que ya lo tienen\\n3. Incorporar factores de impulso\\n4. **Triple desglose de precios**\\n5. Hacer el valor enorme: lenguaje expansivo, *\\"gran\\"*, *\\"masivo\\"* `PRESENCIAL`\\n6. Hacer el costo pequeño: *\\"solo\\"*, *\\"apenas\\"* `PRESENCIAL`\\n7. **Tren del Sí** — preguntas cuya respuesta natural es sí\\n8. **CPR sostenido** durante toda la presentación\\n\\n### Beneficio, no característica `CLOSER` `UNIVERSAL`\\nUna característica es lo que el producto **es**. Nadie compra lo que algo es: compran **lo que van a ganar**.\\n\\nToda característica se traduce a una de tres cosas: **dinero** (gana más o gasta menos), **clientes** (vende más o los conserva), o **tranquilidad** (menos problemas, menos tiempo perdido).\\n\\n> Si el cliente puede contestar *\\"¿y eso a mí de qué me sirve?\\"*, la traducción falló.\\n\\n### Teoría de las Balas `FUENTE` `UNIVERSAL`\\n> *\\"La persona con más balas claramente tiene el control, siempre y cuando conserve su munición.\\"*\\n\\n**Las balas son TUYAS.** Son hechos positivos y concretos sobre:\\n- **Ti / tu empresa** — experiencia, premios, casos de éxito, dedicación\\n- **El producto** — lo que lo diferencia, mejoras, datos, certificaciones\\n- **El precio** — propuesta de valor, descuentos, financiamiento, comparación\\n\\n**La prueba de si algo es bala:** si la competencia puede decir exactamente lo mismo, no era bala. *\\"Somos los mejores\\"* es aire; *\\"catorce años surtiendo esta zona sin fallar\\"* es bala.\\n\\n**La regla de dosificación:** *\\"no dispares todas las balas al principio. Reserva algunas para que no importe cuántas balas tenga tu cliente, tengas más con qué responder. Guarda balas para los pasos 4 y 5.\\"*\\n\\n> **Por qué se guardan:** más adelante el cliente va a poner razones para no comprar. Eso baja su impulso. Responderle bien solo **detiene la caída** — lo que vuelve a subirlo es **una bala nueva**. Si las gastaste presumiendo al principio, llegas a ese momento con la mano vacía.\\n\\n### FUJIES / FUJPIG — Factores de Impulso `FUENTE`\\n*\\"El impulso es otra palabra para la emoción.\\"*\\n\\n| | Factor | Físico `PRESENCIAL` | Verbal `UNIVERSAL` |\\n|---|---|---|---|\\n| **F** | Fear of Loss / Miedo a la pérdida | Producto en mano y quitarlo, retroceder un paso | *\\"solo hoy\\"*, *\\"tiempo limitado\\"*, *\\"quedan pocas\\"* |\\n| **U** | Urgency / Urgencia | Tic-tac con el bolígrafo, empezar a alejarse | *\\"ahora\\"*, *\\"rápido\\"*, *\\"solo toma un par de minutos\\"* |\\n| **G** | Greed / Avaricia | Manos mostrando altos y bajos | *\\"normalmente $100, con la promo queda en solo $59.99\\"* |\\n| **I** | Indifference / Indiferencia | Postura, lenguaje corporal | SW3 |\\n| **E** | Effect of Jones / Efecto Jones | — | *\\"tengo como 20 clientes en esta zona que...\\"* |\\n| **S** | Suggestive Language / Poder de sugestión | Manos altas precio alto, bajas precio bajo | Tren del sí, alternativas |\\n\\n**Miedo a la pérdida > necesidad de ganancia.** La gente dice que sí impulsivamente porque no quiere que algo se le vaya.\\n\\n**Urgencia:** *\\"motion creates emotion\\"*. Y además comunica que estás ocupado, o sea que tienes éxito.\\n\\n**Indiferencia:** *\\"be excited about the person and the product, but indifferent whether they buy.\\"* **SW3** — Some Will, Some Won''t, So What. *\\"Ellos solo tienen una oportunidad de comprarte; tú tienes más de cien clientes.\\"*\\n\\n**Efecto Jones:** de *\\"keeping up with the Joneses\\"*. La gente no confía naturalmente en un desconocido incentivado a vender — pero sí deja que sus vecinos, amigos y familia validen el producto por ella.\\n\\n**Poder de sugestión — tres niveles:**\\n- **Mental** — *\\"asumo que todos son un sí hasta que me digan que no\\"*\\n- **Físico** — lenguaje corporal `PRESENCIAL`\\n- **Verbal** — el tren del sí. **El cliente debería decir que sí al menos 6 veces durante el proceso.**\\n\\n> **Elimina cualquier opción que se pueda traducir en un no.** En vez de *\\"¿quiere algo de tomar?\\"* → *\\"¿té, café o jugo?\\"*\\n\\n### La Curva de Impulso `FUENTE` `UNIVERSAL`\\nEl impulso sube y baja durante la conversación, y hay que construirlo **gradualmente** para no abrumar.\\n\\n**Las tres reglas de oro:**\\n1. **Encuentra al cliente en un punto común de emoción** al inicio, y construye desde ahí\\n2. **Cierra en el momento correcto** — el pico\\n3. **Elimina el arrepentimiento con un rehash impulsivo** — porque después del sí, el impulso cae\\n\\n#### La presentación tiene dos mitades `CAMPO`\\n\\nY confundirlas es un error común, así que conviene tenerlas separadas.\\n\\n**PRIMERA MITAD — lo que vas a hacer por él.**\\nConectas con su dolor usando SUS palabras, y explicas cómo se lo resuelves. Aquí no hay producto todavía: hay un problema y una solución. *\\"Eso que me dice de quedarse sin producto cuando le entra movimiento — eso es venta que se le va.\\"*\\n\\n**SEGUNDA MITAD — el producto y el precio.**\\nUn resumen breve de qué es lo que le va a resolver eso, y el Triple Desglose de Precios. De ahí se pasa directo al cierre.\\n\\n> **El precio SÍ va en la presentación.** Lo que va en el cierre es el **resumen del pedido** — qué y cuánto lleva. Son dos cosas distintas:\\n>\\n> · **Presentación** → el precio en escalera con sus motivos. *\\"Normalmente le sale en X, como es primer pedido queda en Y, y de contado en Z.\\"*\\n> · **Cierre** → lo que lleva. *\\"Entonces le van dos cajas de esto y una de aquello. ¿Jueves o viernes?\\"*\\n>\\n> Enumerar SKUs con cantidades en la presentación es escribir el cierre en el lugar equivocado. Pero omitir el precio es dejar la presentación a medias — y el cliente se queda esperando el número que nunca llegó.\\n\\n### Triple Desglose de Precios `FUENTE (definido) + CAMPO (desarrollado)` `UNIVERSAL`\\n> **Valor menos costo es igual a ahorro.**\\n\\n**La escalera — tres cifras bajando:**\\n1. **Lo que normalmente cuesta** — hace match con lo que el cliente ya esperaba\\n2. **Con el primer descuento** — cliente nuevo, volumen, lo que aplique\\n3. **Con el segundo** — pago de contado, cerrar hoy, lo que corresponda\\n\\n**El ahorro dicho en voz alta.**\\n\\n> **La regla que lo hace funcionar: cada escalón necesita un motivo nombrado.**\\n>\\n> Un precio que baja **sin razón** le dice al cliente que el primero estaba inflado — y te vuelve regateable, porque si bajó dos veces solo, va a bajar otra si presiona.\\n>\\n> Un precio que baja **por razones nombradas** confirma que el primero era real, y cada escalón se vuelve una bala de precio.\\n\\n**Por qué se ve y no solo se escucha:** *\\"queda en ochenta\\"* se escucha como un gasto de ochenta. *\\"Normalmente cien, con su descuento noventa, de contado ochenta\\"* se ve como veinte de ahorro que antes no existían. Mismo número final, sensación opuesta.\\n\\n**Y como el último escalón depende de algo que puede hacer HOY, aparece solo el miedo a la pérdida.**\\n\\n> ⚠️ **Nunca un solo precio.** Un precio suelto es un gasto sin ahorro visible que lo compense.\\n\\n---\\n\\n## PASO 5 · CIERRE\\n### *Extrae eficientemente una decisión*\\n\\n### Qué es un cierre `FUENTE`\\n> *\\"Un cierre no es algo que le haces a alguien. Un cierre es un acuerdo, cuando el cliente se da cuenta de que el beneficio supera al costo y decide. El cierre se lo hace la gente a sí misma.\\"*\\n\\n**Un cierre no siempre es una venta.** Es pedir la decisión, sea cual sea. Asegúrate de que tus conversaciones avancen hacia una conclusión — un sí o un no.\\n\\n### Asumir la venta `FUENTE` `UNIVERSAL`\\nSi llegaste a este punto, **presume que tienes un comprador**.\\n\\n**Malos cierres** — todos invitan al no:\\n*¿Le gustaría comprar? · ¿Está interesado? · ¿Le gusta lo que oye? · ¿Qué le parece? · ¿Cómo lo ve?*\\n\\n**Buenos cierres** — alternativas donde ambas opciones sirven:\\n*¿Es su nombre el que va en la cuenta? · Las primeras fechas de entrega son jueves o viernes, ¿cuál le conviene? · ¿Visa o MasterCard? · ¿Contado o crédito?*\\n\\n> **El diagnóstico de la fuente:** *\\"la mayoría de las personas que batallan para cerrar simplemente no están rompiendo la zona de confort que viene con pedir algo.\\"*\\n>\\n> Y: *\\"aumentas la probabilidad de que compren mientras más confiadamente anuncies tu mensaje.\\"*\\n\\n### El silencio después del cierre `CAMPO` `UNIVERSAL`\\nNo llenes el silencio. Pediste la decisión: **aguanta**.\\n\\nEl vendedor que retira la pregunta, la suaviza o la contesta él mismo, pierde. El primero que habla después de un cierre, pierde.\\n\\n### FISHBBOD — Señales de Compra `FUENTE`\\nTambién llamadas **STOP signs**. En cuanto reconoces una, **DETIENES la presentación y CIERRAS**.\\n\\n**F** Future talk · **I** I want / I need · **S** Silence · **H** How much / How soon · **B** Body language `PRESENCIAL` · **B** Bashing competitor · **O** Offers of courtesy · **D** Deeper questions\\n\\n> **El error que cuesta más ventas de lo que nadie cree:** el cliente da la señal, el vendedor la ve, y como todavía le quedaban dos argumentos buenos, los suelta.\\n>\\n> **El impulso baja.** Porque el cliente ya estaba listo, y seguir vendiéndole le comunica que hay algo que convencerlo — o le da tiempo de encontrar una razón para no hacerlo.\\n>\\n> Señal de compra = deja de presentar y cierra. **Aunque te queden balas. De hecho, sobre todo si te quedan.**\\n\\n---\\n\\n## MANEJO DE OBJECIONES `FUENTE`\\n### *No son negativas: son preguntas que, bien respondidas, terminan en venta*\\n\\n**Objeción = señal de compra.** El que no tiene interés no objeta: se despide.\\n\\n### Las cuatro técnicas de overturn\\n\\n| Técnica | Cuándo | Cómo |\\n|---|---|---|\\n| **AIR** — Agree, Ignore, Resume | Bloqueos en la introducción | Reconoce, ignora, continúa |\\n| **Ataque Preventivo** | Intro o historia breve, negativos conocidos del territorio | Da el negativo antes que el cliente |\\n| **RRR** — Repeat, Reassure, Resume | Objeciones menores y comunes | Repite, responde, **continúa sin pausa** |\\n| **FFF** — Feel, Felt, Found | Preocupación seria o personal | Nunca discutas |\\n\\n### RRR de objeciones `FUENTE` `UNIVERSAL`\\n**R**epeat — repite la objeción en sus términos, para que vea que la escuchaste\\n**R**eassure — la respuesta concreta, con datos\\n**R**esume — **retoma sin pausa**\\n\\n> **La tercera R es la que falla.** El vendedor responde bien y se queda callado esperando a ver si convenció. En ese espacio el cliente encuentra la siguiente objeción, o dice que lo va a pensar.\\n\\n### FFF — el procedimiento completo `FUENTE` `UNIVERSAL`\\n**Nunca discutas con un cliente.** Ganar la discusión es perder la venta.\\n\\nEn español: **Entiendo · Sintió · Encontramos**\\n\\n1. **\\"Entiendo cómo se siente\\"** — estar de acuerdo te vuelve distinto del vendedor promedio, **y por eso te escuchan**\\n2. **\\"Mi último cliente sentía lo mismo\\"** — para que sepa que no está solo\\n3. **\\"Lo que encontramos fue...\\"** — por qué dejaron de pensar así. **Esto usa Efecto Jones**\\n4. **Inserta 3 balas** de la Teoría de las Balas\\n5. **Close With Action**\\n\\n> ⚠️ **FFF no termina en la tercera F.** El documento en español del sistema fuente está truncado y solo llega al paso 3 — por eso mucha gente aprendió un FFF incompleto, sin re-impulso y sin cierre. **Los pasos 4 y 5 son el Círculo de Cierre.**\\n\\n### El Círculo de Cierre `FUENTE (implícito) + CAMPO (nombrado)` `UNIVERSAL`\\n\\n```\\n   CLOSE WITH ACTION ←──────────────┐\\n            ↓                        │\\n   ¿Objeción? → el impulso baja      │\\n            ↓                        │\\n   Atraviesas (RRR o FFF)            │\\n            ↓                        │\\n   RE-IMPULSAS con una bala NUEVA ───┘\\n```\\n\\n> **El error más común: atravesar la objeción y cerrar de inmediato, saltándose la bala.**\\n>\\n> Técnicamente respondiste. Pero **atravesar solo detiene la caída del impulso** — no lo sube. Estás pidiendo una decisión en el punto más bajo de la conversación, y desde ahí la respuesta cómoda siempre es *\\"déjeme lo pienso\\"*.\\n\\n**Y la bala tiene que ser NUEVA.** Repetir un argumento ya usado no sube nada: comunica que ya no tienes más, y eso baja el impulso en lugar de subirlo.\\n\\n### La Regla de los No\\n- **Fuente:** *2 no''s and a go* — dos no seguidos, luz roja, sigue adelante\\n- **Campo `CAMPO`:** Emilio usa **3 no seguidos**, porque hay gente que deja ir un sí solo porque el cliente tuvo preguntas u objeciones\\n\\n> **Tienen que ser CONSECUTIVOS.** Un no, lo atraviesas, la conversación avanza, y más adelante otro no: **eso no es una racha**. Es una conversación normal con dos momentos de fricción. La racha se rompe en cuanto la conversación avanza.\\n\\n---\\n\\n## PASO 6 · CONSOLIDACIÓN / REHASH\\n### *El paso final y más importante*\\n\\n**REHASH** = **R**emember **E**veryone **H**as **A**nother **S**ale **H**idden\\n\\n**Dos propósitos** `FUENTE`:\\n1. **Capitalizar a un cliente ya positivo** — *\\"la gente compra de sus amigos mucho más fácil que de un desconocido\\"*\\n2. **Dejarlo positivo y entendiendo los siguientes pasos** — *\\"la causa número uno de cancelaciones es la falta de entendimiento\\"*\\n\\n### El arrepentimiento del comprador\\nApenas dice que sí, **el impulso cae**. El cerebro empieza a buscar razones por las que quizá no debió. Es automático y no es desconfianza hacia ti.\\n\\n### Cómo se disuelve `CAMPO`\\n> **El error que parece lo correcto: seguir vendiendo.**\\n>\\n> La reacción natural es reforzar la compra — recordarle lo bueno del producto, repetirle el ahorro, insistir en que tomó una gran decisión.\\n>\\n> **Y eso lo empeora.** Seguir vendiendo después del sí le dice al cliente que **necesitabas la venta**. Y si la necesitabas, entonces la indiferencia era actuada. Y si la indiferencia era actuada, también el interés por su negocio, también las preguntas, también la plática de su hijo.\\n>\\n> **Retroactivamente, toda la conversación se convierte en una técnica.**\\n\\n**Lo que sí funciona: demostrar que nada cambió en ti.**\\n\\nMisma indiferencia sobre la compra. Misma calidez sobre la relación. Cero producto. Y la confianza de que ahí vas a estar para lo que necesite.\\n\\n**Por qué funciona:** si tu actitud es idéntica antes y después de la firma, el cliente concluye solo lo que ninguna frase habría logrado convencerlo — **que no lo trataste así para venderle, sino porque así eres.** Y con esa conclusión, el arrepentimiento no tiene de qué agarrarse.\\n\\n**Y deja claro qué sigue.** La falta de entendimiento es la causa número uno de cancelaciones.\\n\\n---","is_active":true,"created_at":"2026-10-01T18:11:26.114188+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"0fd46a29-b9b5-4037-a2be-c9ba776d82d9","version":6,"section_key":"mentalidad","order_index":3,"title":"PARTE 3 · LA MENTALIDAD","body":"# PARTE 3 · LA MENTALIDAD\\n### *La segunda fundación*\\n\\n> *\\"No importa qué tan buenas sean tus habilidades conversacionales, nunca vas a tener 100% de éxito.\\"*\\n>\\n> Y: *\\"hay gente con mucha personalidad o experiencia que triunfa sin trabajar bien la ley de promedios — pero no puede replicar su éxito, porque depende demasiado de la habilidad.\\"*\\n\\n**La mentalidad no es motivación: es el sistema de control que hace replicable el resultado.**\\n\\n## Ley de Promedios (LDP) `FUENTE`\\n> *\\"Si repites una acción las veces suficientes, aparecerá una proporción.\\"*\\n\\nEs un sistema probado para **encontrar compradores entre los no compradores**.\\n\\n**La analogía de la moneda:** lanzas una vez, 50/50. Lanzas diez veces y raramente sale 5 y 5. Pero mientras más lanzas, más se acerca la muestra a la proporción real. **La ley necesita volumen para manifestarse.**\\n\\n## PPA — lo que afecta tu ley de promedios `FUENTE`\\n**P**itch / Conversación — preciso, conciso, impactante\\n**P**ace / Ritmo — con cuánta gente hablas\\n**A**ttitude / Actitud — consistentemente positiva\\n\\n> **La cadena causal, y por qué la mentalidad no es opcional:**\\n> La ley de promedios necesita volumen. El volumen desgasta la actitud. La actitud degrada el pitch. Y el pitch es la variable de entrada del sistema.\\n>\\n> **Por eso KILT, los 3 tipos de día, controlables y gumball existen: protegen la única variable que el vendedor controla.**\\n\\n## Los 3 Tipos de Día `FUENTE`\\n- **Día A** — las ventas llegan temprano, la actitud es fácil\\n- **Día B** — llegan esporádicamente, no te prueba del todo\\n- **Día C** — todas llegan en las últimas horas. **La verdadera prueba de quién cree en el sistema**\\n\\n*Ejemplo real: 3 ventas de 60 contactos es normal — 5% de éxito. Es normal no tener ningún cliente hasta el final del día y aun así cumplir.*\\n\\n## Teoría del Gumball `FUENTE`\\nTres máquinas, 100 dulces cada una, 97 rojos y 3 verdes. Cada intento cuesta un peso. Tienes 100 pesos y la meta de sacar 3 verdes.\\n\\n**Mantén tu pitch, ritmo y actitud iguales, para que cada \\"no\\" te acerque al \\"sí\\".**\\n\\n> **La dificultad real:** en el campo no puedes ver dónde están los verdes como en la máquina. Tienes que seguir girando a ciegas, sabiendo que tu proporción va a aparecer.\\n\\n## Controlables vs No Controlables `FUENTE`\\n> *\\"Si no podemos controlarlo, no lo pensamos ni lo hablamos. Es una pérdida de tiempo y energía.\\"*\\n\\nLa mayoría pasa el día culpando cosas que no controla. Concentrarse en lo controlable es mucho más productivo: ver más gente, tener mejores conversaciones, cuidar la actitud.\\n\\n## KILT `FUENTE`\\n**K**ill them with kindness — sé amable sin importar la actitud del otro\\n**I**ndifference — algunos comprarán, otros no, ¿y qué?\\n**L**aw of averages — confía en los números\\n**T**reat everyone like your first — nunca sabes cuándo aparece tu cliente\\n\\n**Aplicación:** si dejamos a cada persona mejor de como la encontramos, permanecemos indiferentes al sí o al no, y tratamos a cada quien como el primero, entonces protegemos la actitud.\\n\\n## Los 8 Grandes Hábitos `FUENTE`\\n*\\"Somos lo que hacemos repetidamente; el éxito es un hábito.\\"*\\n\\n1. **Tener gran actitud** — el negocio es 99% actitud y 1% habilidad\\n2. **Ser puntual** — si no llegas temprano, llegas tarde\\n3. **Estar preparado** — fallar en prepararse es prepararse para fallar\\n4. **Esfuerzo del 100%** — recibes lo que pones\\n5. **Maximizar tu territorio** — tu territorio no es el lugar, **son las personas**\\n6. **Proteger tu actitud** — cada \\"no\\" te acerca al \\"sí\\"\\n7. **Conocer tu porqué** — metas de corto, mediano y largo plazo\\n8. **Tomar el control** — de tu día, tu carrera y tu vida\\n\\n## Indicadores / Gauges `FUENTE`\\nMiden con cuánta gente hablas y qué tan lejos llegas en los pasos.\\n\\n**Puertas → Con cuántos hablaste → Presentaciones → Cierres**\\n\\n**Para qué sirven:**\\n1. Identificar dónde **podría** romperse el sistema en tus 6 pasos\\n2. Asegurar que trabajas el sistema\\n3. Marcarte el ritmo\\n\\n> ⚠️ **Los indicadores señalan DÓNDE MIRAR, no qué está mal.**\\n>\\n> Si presentas a muchos y cierras a pocos, el número te dice que algo pasa **entre la presentación y el cierre** — pero la causa puede estar mucho antes. Puede ser que el descubrimiento no encontró el dolor real, que no hubo suficiente CPR y el cliente nunca contestó de verdad, que la presentación se alargó y cayó en KILL, que el impulso se construyó mal, o que efectivamente el cierre es débil.\\n>\\n> **Un número no diagnostica una causa.** Diagnostica una zona.\\n\\n**El diagnóstico real requiere ver la conversación.** Como manager: acompañando al vendedor en campo, o pidiéndole una práctica en Closer sobre el paso donde sospechas.\\n\\n**Números + conversación observada = conclusión.** Cualquiera de los dos solo, es especulación.\\n\\n## Metas — SMART `FUENTE`\\n**S**pecific · **M**easurable · **A**ttainable · **R**ealistic · **T**imed\\n\\nTipos: de **resultado** · de **acción** · corto plazo (<2 meses) · mediano (2 meses–3 años) · largo (3+ años)\\n\\nEscríbelas, hazlas evaluar por alguien, y recompénsate al lograrlas.\\n\\n---","is_active":true,"created_at":"2026-10-01T18:11:26.114188+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"3179a61e-ae68-48f5-9f8b-8d21fdc1e619","version":6,"section_key":"aplicacion","order_index":4,"title":"PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE","body":"# PARTE 4 · APLICAR EL SISTEMA A CUALQUIER CLIENTE\\n\\n> **El sistema es el esqueleto. Si se entiende, se aplica a cualquier cliente, cualquier industria y cualquier producto.**\\n\\nEsta parte NO es un catálogo de casos. Es la demostración de cómo se deduce la ejecución correcta a partir de los principios — para que cualquier caso que no esté aquí se resuelva igual.\\n\\n## 4.0 El método de adaptación\\n\\nCada paso existe para lograr algo. **Lo que cambia entre clientes no es el objetivo del paso: es lo que hace falta para lograrlo.**\\n\\nEjemplo con la Historia Breve. Su objetivo es liberar el segundo tercio de atención — las dos preguntas que el cliente trae en la cabeza: *quién eres* y *por qué estás aquí*.\\n\\n- Con un desconocido, las dos están abiertas → contestas las dos\\n- Con alguien que te conoce hace años, la primera ya está contestada → **solo queda el porqué de hoy**, y a veces hasta eso es obvio\\n\\n**La conclusión operativa, dicha completa:** con un cliente que ya te conoce, la Historia Breve **NO incluye tu nombre ni el de tu empresa**. Nada de \\"Soy Juan, de [empresa]\\", ni \\"trabajamos con tal marca\\". Él ya lo sabe. Repetírselo le comunica que no lo reconoces o que estás recitando un guion — y en los dos casos daña la relación que llevas años construyendo.\\n\\nLo único que queda es **por qué viniste HOY**, en una o dos frases. Y a veces hasta eso es evidente.\\n\\nEse es el método. Ante cualquier cliente, en cualquier industria:\\n\\n1. ¿Qué **objetivo** tiene este paso?\\n2. ¿Qué de ese objetivo **ya está resuelto** con este cliente?\\n3. ¿Qué **falta** por resolver?\\n4. **Ejecuta solo eso, y escribe solo eso.**\\n\\n> ⚠️ **El paso 4 es donde más se falla.** Deducir correctamente qué falta y aun así escribir la versión completa por costumbre es el error más frecuente al aplicar este método. Si concluiste que algo ya está resuelto, **ese algo no aparece en el texto.** No basta con saberlo: hay que omitirlo.\\n\\n## 4.0b Autoconsumo y distribuidor NO son un tercer eje `CAMPO`\\n\\nHay una confusión fácil de cometer: tratar \\"autoconsumo\\" y \\"distribuidor\\" como si fueran alternativas a \\"nuevo\\" y \\"recurrente\\". No lo son. **Son ejes distintos.**\\n\\n**EJE 1 — ¿Ya te compra?** Nuevo o recurrente. Esto define **la relación**: si te conoces, si hay historial, si hay pedido base.\\n\\n**EJE 2 — ¿Qué hace con el producto?** Revende, consume o distribuye. Esto define **las preguntas**: qué se le pregunta en cada territorio.\\n\\n**Se cruzan.** Un cliente de autoconsumo puede ser nuevo (nunca te ha comprado) o recurrente (lleva años surtiéndose contigo). Y la ejecución cambia según el cruce:\\n\\n| | Nuevo | Recurrente |\\n|---|---|---|\\n| **Revende** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Consume** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n| **Distribuye** | Te presentas · buscas dolor | No te presentas · buscas hueco |\\n\\n> **Lo que cambia por el EJE 1** es si te presentas, si hay \\"lo de siempre\\", y si buscas dolor o hueco.\\n>\\n> **Lo que cambia por el EJE 2** es únicamente el vocabulario del descubrimiento: al que revende le preguntas qué maneja y qué le piden; al que consume, qué usa y cada cuánto repone; al que distribuye, sus líneas y a cuántos surte.\\n\\n**Error concreto que esto evita:** escribir la historia breve de un cliente de autoconsumo como si fuera recurrente — *\\"vine a ver cómo les funcionó lo que dejamos la vez pasada\\"* — cuando nunca ha habido una vez pasada. Autoconsumo no dice nada sobre si ya te compra o no.\\n\\n**Y una vez que un cliente de autoconsumo te compra, se vuelve recurrente**: el seguimiento y el crecimiento de esa cuenta funcionan igual que con cualquier otro recurrente. Buscas huecos, cierras el incremento, y no te vuelves a presentar.\\n\\n## 4.1 Lo que sí cambia sustancialmente\\n\\nHay dos diferencias que no son obvias y que sí conviene tener explícitas, porque cambian **qué se busca**, no solo cómo se dice.\\n\\n### Diferencia 1 — Qué buscas en el Descubrimiento\\n\\n**DOLOR** — algo anda mal. Tiene señal verbal: **el \\"aunque\\"**. Se busca con los 3 Territorios y la escalera de capas.\\n\\n**HUECO** — algo que podría comprarte y no te compra. **No tiene señal verbal: se ve, no se oye.**\\n\\n> Un cliente conforme no tiene dolor. **Por eso el vendedor que solo sabe buscar dolor visita durante años sin crecer una cuenta**: busca, no encuentra, y concluye correctamente que no hay nada.\\n\\n**Las tres herramientas del hueco:**\\n\\n**1 · Lee el lugar** — lo que ves te dice qué maneja y de quién. Un producto de otra marca es un espacio ocupado; un estante vacío es una familia que nadie cubre; algo empolvado no es hueco, **es dolor**.\\n\\n**2 · Pregunta por lo que le piden** — *\\"¿le ha tocado que le pidan algo que no maneje?\\"* Demanda que ya existe sin oferta que la cubra.\\n\\n**3 · Ancla en negocios como el suyo** — Efecto Jones aplicado. Solo si es verdad y lo puedes sostener.\\n\\n**Adaptación por canal:** presencial observas; a distancia preguntas por el catálogo. **Adaptación por giro:** si el cliente no revende, \\"lo que ves\\" no es un mostrador — son sus unidades, su patio, su operación.\\n\\n> **La línea que no se cruza:** un hueco tiene que ser real y verificable. **Descubrir un hueco es señalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.**\\n\\n### Diferencia 2 — Qué estás cerrando\\n\\nCon un cliente que ya compra, **el pedido base no está en duda: ya iba a existir.** Lo que se cierra es **lo que se agrega**.\\n\\nReabrir el pedido base al cerrar pone sobre la mesa algo que ya estaba resuelto, e invita al cliente a revisar toda la orden.\\n\\n## 4.1b La observación del recurrente no puede sonar a primera visita `CAMPO`\\n\\nEl SCE y el ice breaker siguen aplicando con un cliente de años. Lo que cambia es **de qué se observa**.\\n\\n**El error:** *\\"¿Siempre está así de lleno o hoy le tocó día pesado?\\"*\\n\\nEsa pregunta la hace alguien que no conoce el lugar. Y este vendedor lleva años pasando cada quincena — **ya sabe si el negocio es movido.** Preguntarlo le comunica al cliente que no lo tiene presente, que es lo contrario de lo que la relación construyó.\\n\\n**Lo correcto: observar lo que CAMBIÓ desde la última visita.**\\n\\n> *\\"Oiga, ¿ya le entró más gente que la vez pasada, verdad?\\"*\\n> *\\"Veo que le movió al acomodo desde que vine.\\"*\\n> *\\"¿Ya se compuso lo del clima o siguen igual de flojas las tardes?\\"*\\n\\nY también funciona lo personal, que con un desconocido no puedes usar:\\n\\n> *\\"¿Cómo salió su muchacho de lo que me contó?\\"*\\n> *\\"¿Le fue bien en el puente?\\"*\\n\\n> **La prueba:** si tu observación de apertura funcionaría igual con un cliente que ves por primera vez, no está aprovechando la relación. **Con un recurrente, la apertura demuestra memoria** — y esa memoria es el activo que llevas años construyendo.\\n\\n⚠️ **Y esto solo funciona si la memoria es real.** Inventar que recuerdas algo que no pasó es peor que no recordar nada. Si no tienes un dato de la visita anterior, observa el momento presente sin fingir historia: *\\"se ve movido hoy\\"* es honesto; *\\"¿siempre está así?\\"* no lo es.\\n\\n## 4.2 Lo que NO cambia nunca\\n\\n- El orden de los 6 pasos\\n- Que el descubrimiento va antes de la presentación\\n- Que el cierre asume en vez de pedir aprobación\\n- Que el precio va en escalera con motivo\\n- Que no hay frases neutras\\n- Toda la Parte 6 (jerarquía de reglas)\\n\\n## 4.3 Presentar un hueco `CAMPO`\\n\\nCuando lo que encontraste es un hueco, no hay nada que resolver: el cliente está conforme. Hay un espacio que ocupar.\\n\\n**La pregunta que define el argumento: ¿qué gana él con que tú se lo surtas?**\\n\\nY la respuesta depende del caso, no de una fórmula. Posibilidades reales:\\n\\n- **Consolidación** — si el cliente trata con muchos proveedores y eso le pesa, reducir el número tiene valor por sí mismo\\n- **Conveniencia** — te ve de todos modos; agregar una familia no le suma trabajo\\n- **Complementariedad** — lo que ofreces se usa junto con lo que ya te compra\\n- **Una condición concreta** — plazo, disponibilidad, presentación, tiempo de entrega\\n\\n> ⚠️ **La consolidación NO es un argumento universal.** Si tu producto es complementario y el cliente ya tiene cinco proveedores, con la familia nueva pasa a tener **seis, no cuatro**. Ahí *\\"menos proveedores que seguir\\"* es falso, y usarlo te desacredita.\\n>\\n> Antes de usarlo, verifica que el cliente **efectivamente vaya a reducir** su número de proveedores.\\n\\n⚠️ **Nunca ataques al proveedor actual.** Criticarlo es criticar la decisión del cliente, y la gente defiende sus decisiones.\\n\\n⚠️ **No afirmes ventajas que no puedes verificar.** *\\"El otro no maneja esta línea\\"*, *\\"nadie tiene nuestro catálogo\\"*, *\\"con nosotros le sale mejor\\"* — si no lo sabes de cierto, no lo digas. Puede ser falso, y en una cuenta de años se descubre siempre. **Habla de lo que TÚ ofreces, con hechos que puedas sostener.**\\n\\n## 4.4 Convicción sin garantía `CAMPO`\\n\\n> **Nunca le pidas que \\"pruebe\\".**\\n>\\n> *\\"Le pongo unas pocas para que lo pruebe\\"* suena humilde y es lo peor que puedes decir: **le pasas el riesgo a él.** La gente no quiere experimentar — está cómoda donde está, y probar algo nuevo es riesgo, incomodidad y la posibilidad de haberse equivocado.\\n\\n**El trabajo del vendedor no es pedir permiso para experimentar. Es hacer que el cliente se sienta seguro.** Dos movimientos:\\n\\n1. **Convicción, sin garantía** — *\\"no le puedo garantizar nada, pero estoy seguro de que le va a servir\\"*\\n   **Funciona precisamente porque reconoce el límite.** Admitir lo que no controlas hace creíble lo que sí afirmas.\\n\\n2. **La razón detrás** — *\\"se lo digo porque en negocios como el suyo es de lo que más sale\\"*\\n   Sin la razón, tu convicción es solo optimismo de vendedor.\\n\\n**Y ahí te callas.**\\n\\n⚠️ **No ofrezcas el plan B.** *\\"Y si no funciona lo ajustamos\\"* parece que baja el riesgo y hace lo contrario: **le mete una duda que no tenía**, y desmiente lo que acabas de afirmar. Si de verdad estás seguro, ¿para qué el paracaídas?\\n\\n*(Si después no funciona, ahí lo ajustas. Eso es Consolidación y se hace cuando pasa — no se anuncia por adelantado.)*\\n\\n## 4.5 El capital del récord `CAMPO`\\n\\n> **La primera vez que recomiendas algo, el cliente compra por la relación. La segunda vez, compra por tu récord.**\\n\\nY eso disciplina: si recomiendas algo que no funciona, **no perdiste una venta — gastaste crédito que te costó años juntar.** Por eso solo se recomienda lo que de verdad sirve a ese perfil, aunque haya cosas con mejor margen.\\n\\n## 4.6 Los dos juegos `CAMPO`\\n\\n**ADQUISICIÓN** — convertir a un desconocido en cliente.\\n**DESARROLLO** — convertir a un cliente en un cliente más grande.\\n\\n> **La asimetría que explica por qué el segundo se descuida:** adquisición da retroalimentación inmediata — vendes o no vendes. Desarrollo no. Puedes visitar cien veces, levantar el mismo pedido, sentir que hiciste bien tu trabajo, y nunca enterarte de lo que dejaste sobre la mesa.\\n>\\n> **El fracaso en desarrollo es invisible.**\\n\\n**El enemigo: la visita que se vuelve trámite.** El vendedor está haciendo adquisición con alguien que ya adquirió — y como no hay nada que adquirir, no hay nada que hacer.\\n\\n> **Al que solo toma pedidos lo reemplaza un formulario.**\\n\\n---","is_active":true,"created_at":"2026-10-01T18:11:26.114188+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"cbbc6310-2b28-4b04-9aac-d470f5d65651","version":6,"section_key":"canales","order_index":5,"title":"PARTE 5 · MODIFICADORES DE CANAL","body":"# PARTE 5 · MODIFICADORES DE CANAL\\n\\n| Canal | Qué se conserva | Qué se adapta |\\n|---|---|---|\\n| **Presencial** | Todo | — |\\n| **Teléfono** | Los 6 pasos, KISS, FORMS, las 4 técnicas de overturn, balas, FUJIES verbales, CWA, triple desglose, y el **entusiasmo del tono** | Contacto visual → pausas y ritmo. Todo lo físico se pierde |\\n| **WhatsApp / mensaje** | La estructura completa, balas, triple desglose, ataque preventivo | Mensajes cortos, uno por idea. Señales de compra → velocidad de respuesta, emojis, preguntas de precio. El cierre debe contestarse con una palabra |\\n| **Correo** | Estructura, KISS, balas, triple desglose | Todo lo interactivo se vuelve secuencia |\\n\\n> **El principio de adaptación: entender qué HACE cada técnica permite encontrar su equivalente en cualquier medio.**\\n>\\n> El miedo a la pérdida no es *\\"quitar el producto de la mano\\"* — es **crear la sensación de que algo se va**. Eso existe en los cuatro canales.\\n\\n---","is_active":true,"created_at":"2026-10-01T18:11:26.114188+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"908fd9cc-7c94-448b-9ae0-8d0afe7500d6","version":6,"section_key":"jerarquia","order_index":6,"title":"PARTE 6 · JERARQUÍA DE REGLAS","body":"# PARTE 6 · JERARQUÍA DE REGLAS\\n\\nCuando dos principios chocan, gana el de mayor jerarquía.\\n\\n## NIVEL 1 — Inviolables (ética y verdad)\\nNunca se rompen, en ningún contexto, por ninguna razón.\\n\\n1. **Impulso falso está prohibido.** Urgencia inventada, escasez que no existe, prueba social fabricada. *(Práctico, no solo moral: un impulso falso se derrumba cuando el cliente lo descubre, y se lleva la venta, la relación y tu reputación en la zona.)*\\n2. **No garantizar lo que no controlas.** Convicción sí; garantía no.\\n3. **No fabricar un hueco ni un dolor.** Descubrir es señalar lo que existe.\\n4. **No atacar al competidor ni al proveedor actual.**\\n5. **No afirmar ventajas que no puedes verificar.** *\\"Nadie más tiene esto\\"*, *\\"el otro no lo maneja\\"*, *\\"con nosotros sale mejor\\"* — si no lo sabes de cierto, no lo dices. Habla de lo que TÚ ofreces.\\n6. **Nunca discutir con un cliente.**\\n\\n## NIVEL 2 — Estructurales\\nSe rompen solo si el Nivel 1 lo exige.\\n\\n7. **El orden de los 6 pasos.** No se salta ninguno.\\n8. **Primero el examen, luego la receta.** No presentar sin diagnosticar.\\n9. **El cierre asume, no pide aprobación.** Toda pregunta que permita aprobar o posponer entrega el control.\\n10. **El precio va en escalera con motivo en cada escalón.** Nunca un solo número.\\n11. **No hay frases neutras.** Si algo resta valor y nadie lo preguntó, se omite.\\n12. **Señal de compra = detente y cierra.**\\n13. **Se sale de la línea, pero siempre se regresa.**\\n14. **Nunca pidas opinión ni aprobación sobre el precio.** Ni el tuyo ni el de la competencia. Preguntar *\\"¿cómo ve los precios?\\"* le pide al cliente que construya una posición contra ti antes de que exista valor, cede tu autoridad sobre el precio, y renuncia a tu ventaja — porque tú conoces el mercado y él muchas veces no. En el territorio PRECIO se investigan **hechos** (a cómo compra, qué plazo tiene, cada cuánto le suben), nunca opiniones.\\n\\n## NIVEL 3 — Contextuales\\nDependen del tipo de cliente, canal o situación. **Se deducen del método de la Parte 4.0, no se memorizan.**\\n\\n14. Qué parte de la Historia Breve hace falta — depende de qué ya sabe el cliente\\n15. Buscar dolor o buscar hueco — depende de si el cliente está conforme\\n16. Qué argumento usar al presentar un hueco — depende de qué gana él en ESE caso\\n17. Cerrar la venta o cerrar el incremento — depende de si hay un pedido base\\n18. SEE físico — solo presencial\\n\\n## NIVEL 4 — Estilo\\nAjustables al lenguaje del vendedor, la zona y la empresa.\\n\\nTono, vocabulario, longitud de frases, formalidad. **El manager conoce el lenguaje de su gente mejor que Closer.**\\n\\n---","is_active":true,"created_at":"2026-10-01T18:11:26.114188+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.doctrina SELECT * FROM json_populate_record(NULL::public.doctrina, E'{"id":"49929fa4-9d28-4322-8cca-6ea24cde4242","version":6,"section_key":"razonamiento","order_index":7,"title":"PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO","body":"# PARTE 7 · CÓMO RAZONAR CON ESTE DOCUMENTO\\n\\n## Ante un caso no cubierto\\n1. Identifica **qué paso** de la línea es\\n2. Pregunta **qué objetivo tiene ese paso**\\n3. Pregunta **qué de ese objetivo ya está resuelto** con este cliente, y qué falta\\n4. Verifica contra la **jerarquía**: ¿viola algo de Nivel 1 o 2?\\n5. Si sigue sin resolverse, **di que no lo sabes.** No inventes doctrina.\\n\\n## Ejemplos de deducción\\n\\n**Caso:** un vendedor pregunta si puede decir *\\"¿le late?\\"* al cerrar.\\n**Razonamiento:** es una pregunta que permite aprobar o posponer → viola la regla 9 (Nivel 2) → **no**. La alternativa es una pregunta donde ambas opciones sirvan.\\n\\n**Caso:** un manager quiere que el pitch mencione que un producto no trae promoción este mes.\\n**Razonamiento:** no hay frases neutras (1.3); esto baja el valor percibido; nadie lo preguntó → **se omite**. Regla 11, Nivel 2.\\n\\n**Caso:** un vendedor pregunta cómo abrir con un cliente que le compra desde hace cinco años.\\n**Razonamiento:** aplica el método 4.0. Objetivo de la Historia Breve = contestar *quién eres* y *por qué estás aquí*. Lo primero ya está resuelto → **solo queda el porqué de hoy**, y a veces hasta eso es evidente. No hace falta una regla especial: sale del objetivo del paso.\\n\\n**Caso:** vender un servicio de software por videollamada a una empresa que nunca lo ha usado.\\n**Razonamiento:** el sistema aplica igual. Cliente nuevo → doctrina de adquisición. Canal remoto → SEE físico no aplica, pero el entusiasmo del tono sí. \\"Lee el lugar\\" no existe, así que se pregunta. Los 3 Territorios se traducen: producto = qué usan hoy, servicio = cómo los atiende su proveedor, precio = qué pagan. **Nada del esqueleto cambia.**\\n\\n**Caso:** un vendedor dice que el cliente no le reconoce ningún problema, pero él ve claro que sí lo tiene.\\n**Razonamiento:** aplica 1.5. La confirmación explícita no es requisito. Si hay evidencia real — algo que dijo, algo que vio, algo propio de su giro — **avanza presentando la situación resuelta**, no el problema reconocido. Insistir en que lo admita lo pone a la defensiva y apaga lo emocional, que es donde está la venta. **El límite:** si el cliente ya negó explícitamente ese problema, insistir es fabricar, y eso es Nivel 1.\\n\\n**Caso:** un vendedor lleva tres días sin cerrar y está desanimado.\\n**Razonamiento:** esto es Parte 3, no Parte 2. Aplica Ley de Promedios, los 3 Tipos de Día (día C), gumball, y controlables vs no controlables. **No es un problema de técnica: es de protección de la actitud, que es la variable de entrada del sistema.**\\n\\n**Caso:** un manager ve que su vendedor presenta mucho y cierra poco, y quiere saber qué corregir.\\n**Razonamiento:** el indicador señala una zona, no una causa. Puede ser el cierre, pero también un descubrimiento que no encontró el dolor real, CPR insuficiente, o una presentación que se alargó y cayó en KILL. **Números + conversación observada.** Pídele una práctica o acompáñalo en campo antes de concluir.\\n\\n## Sobre la incertidumbre\\nEste documento tiene procedencia marcada por una razón: **lo que está como `CAMPO` no se puede verificar contra la fuente.** Si un caso depende de doctrina `CAMPO` y hay duda, la autoridad es Emilio, no la inferencia.\\n\\n**Nunca completes un hueco de doctrina inventando.** Di qué falta y pídelo.\\n\\n**Y nunca inventes un hecho comercial** — una ventaja, una comparación con la competencia, un dato de mercado. Eso no es doctrina: es información de la empresa, y si no está en su contexto, se pide.","is_active":true,"created_at":"2026-10-01T18:11:26.114188+00:00","created_by":"59940ac9-fc91-43b5-a7a5-9555953eb39b"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"0e4df73d-e681-48fc-bd8f-805b17ffa2b8","type":"red_light_recuperable","difficulty_base":4,"base_prompt":"Empiezas en Red Light claro: cerrado, frío, casi descartando la conversación. Pero si el vendedor aplica AIR correctamente puedes abrirte. Eres muy sensible a la actitud.","objection_patterns":{"orden": ["no_me_interesa", "ya_dije_que_no", "mejor_otro_dia"], "intensidad": "muy_alta"},"buying_signal_style":"casi_invisibles","variations":[{"señal_apertura": "empatia_real"}, {"señal_apertura": "silencio_respetuoso"}, {"señal_apertura": "pregunta_humana"}],"is_boss_eligible":true,"worlds_available":[6,7,8,9],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"457be922-9a38-4e19-9d0c-34ddf897c955","type":"ocupado","difficulty_base":2,"base_prompt":"Tienes muy poco tiempo. Respuestas cortas y secas. Te distraes con el celular o personas que pasan. Necesitas que el vendedor vaya al grano en menos de 30 segundos o pierdes interés.","objection_patterns":{"orden": ["sin_tiempo", "al_grano"], "intensidad": "media"},"buying_signal_style":"sutiles","variations":[{"contexto": "telefono_constante"}, {"contexto": "empleado_interrumpe"}, {"contexto": "prisa_real"}],"is_boss_eligible":false,"worlds_available":[0,2,3,4],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"49d6a2ca-8781-4fd5-b639-83a4fef38dd2","type":"necesita_consultar","difficulty_base":3,"base_prompt":"Te interesa pero nunca decides solo. Siempre hay alguien más: socio, esposa, jefe, contador. Aunque te convenzas, dirás que necesitas consultar antes de cerrar.","objection_patterns":{"orden": ["consulto", "no_decido_solo", "despues_de_hablar"], "intensidad": "media"},"buying_signal_style":"sutiles","variations":[{"figura": "esposa"}, {"figura": "socio"}, {"figura": "jefe"}],"is_boss_eligible":true,"worlds_available":[3,4,5,6],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"4eb69941-7de4-4fa4-9b06-a7128f0a4613","type":"desconfiado","difficulty_base":4,"base_prompt":"Eres escéptico ante cualquier argumento del vendedor. Cuestionas todo lo que dice. Necesitas prueba social fuerte (clientes reales, casos verificables) para considerar avanzar.","objection_patterns":{"orden": ["no_te_creo", "quien_mas", "pruebamelo"], "intensidad": "alta"},"buying_signal_style":"casi_invisibles","variations":[{"sospecha": "engano_pasado"}, {"sospecha": "reputacion_industria"}, {"sospecha": "vendedor_presionante"}],"is_boss_eligible":true,"worlds_available":[4,5,6,7],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"503d53f9-1d6e-4bb9-a739-d7fe2e2fe1bc","type":"cicatriz_emocional","difficulty_base":4,"base_prompt":"Tuviste una mala experiencia con un producto/proveedor similar. Estás cerrado emocionalmente al inicio. Solo si el vendedor hace FFF (Feel-Felt-Found) genuino te abres.","objection_patterns":{"orden": ["ya_me_paso", "perdi_dinero", "no_otra_vez"], "intensidad": "alta"},"buying_signal_style":"casi_invisibles","variations":[{"trauma": "producto_fallo"}, {"trauma": "servicio_postventa"}, {"trauma": "engano_comercial"}],"is_boss_eligible":true,"worlds_available":[5,6,7,8],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"5e45352e-a017-4587-8a89-d6031728e2f7","type":"corporativo_formal","difficulty_base":4,"base_prompt":"Operas con proceso formal de compra. Múltiples aprobaciones. Lenguaje corporativo y estructurado. Solicitas documentos, propuestas escritas, RFP, plazos formales.","objection_patterns":{"orden": ["procedimiento", "comite", "documentacion"], "intensidad": "media"},"buying_signal_style":"sutiles","variations":[{"rol": "compras"}, {"rol": "finanzas"}, {"rol": "director_area"}],"is_boss_eligible":true,"worlds_available":[5,6,7,8],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"7a05f8bd-4731-4e2c-9979-aaf64a7bf03e","type":"precio_obsesivo","difficulty_base":3,"base_prompt":"Todo lo evalúas por precio. Comparas constantemente con la competencia. Sin un triple desglose claro de valor vs precio no te mueves. Pides descuentos repetidamente.","objection_patterns":{"orden": ["caro", "mas_barato", "descuento"], "intensidad": "alta"},"buying_signal_style":"sutiles","variations":[{"comparativa": "online"}, {"comparativa": "competidor_directo"}, {"comparativa": "version_anterior"}],"is_boss_eligible":true,"worlds_available":[3,4,5,6],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"90b24e7a-2e39-469b-a99e-5f4609f288b3","type":"leal_proveedor","difficulty_base":3,"base_prompt":"Tienes un proveedor actual con el que estás razonablemente contento. No buscas cambiar. Solo te moverías si el vendedor diagnostica un hueco real que tu proveedor no cubre.","objection_patterns":{"orden": ["ya_tengo", "contento_actual", "no_busco"], "intensidad": "media_alta"},"buying_signal_style":"sutiles","variations":[{"hueco": "servicio"}, {"hueco": "precio_pequeno"}, {"hueco": "variedad"}],"is_boss_eligible":true,"worlds_available":[2,3,4,5],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"9550c91f-4460-4165-acd5-9cc48f584177","type":"amigable_no_compra","difficulty_base":2,"base_prompt":"Eres muy amigable y conversador. Te interesa platicar pero siempre encuentras una razón válida para no comprar HOY. Pides información, prometes pensarlo, vuelves al tema personal.","objection_patterns":{"orden": ["lo_pienso", "despues", "consulto"], "intensidad": "media"},"buying_signal_style":"sutiles","variations":[{"excusa": "economia"}, {"excusa": "tiempo"}, {"excusa": "familia"}],"is_boss_eligible":false,"worlds_available":[1,0,2,3],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"e8f96a46-4194-44ca-baaf-28c935235c4d","type":"analitico","difficulty_base":3,"base_prompt":"Pides datos concretos y verificables. Comparas características técnicas. No compras sin información dura. Cuestionas afirmaciones generales y pides especificaciones.","objection_patterns":{"orden": ["dame_datos", "fuente", "comparativa_tecnica"], "intensidad": "alta"},"buying_signal_style":"sutiles","variations":[{"foco": "specs"}, {"foco": "roi"}, {"foco": "garantias"}],"is_boss_eligible":true,"worlds_available":[4,5,6,7],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"eb8f25e5-6477-44c1-bc6e-fdd6b7c009df","type":"verde_facil","difficulty_base":1,"base_prompt":"Eres un cliente receptivo desde el primer momento. Das señales de compra claras y frecuentes. Lanzas pocas objeciones y son blandas. Si el vendedor hace su trabajo básico bien, compras.","objection_patterns":{"orden": ["interes_general"], "intensidad": "baja"},"buying_signal_style":"obvias","variations":[{"mood": "entusiasta"}, {"mood": "curioso"}, {"mood": "apurado_positivo"}],"is_boss_eligible":false,"worlds_available":[1,0,2],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
INSERT INTO public.client_archetypes SELECT * FROM json_populate_record(NULL::public.client_archetypes, '{"id":"ec22fc93-741b-48e8-98ab-20789c3f0e8d","type":"agresivo","difficulty_base":5,"base_prompt":"Eres hostil desde el primer segundo. Pones a prueba al vendedor con sarcasmo o desafío directo. Reaccionas mal a cualquier presión. Solo KILT y manejo emocional impecable te calman.","objection_patterns":{"orden": ["ataque_directo", "sarcasmo", "reto"], "intensidad": "muy_alta"},"buying_signal_style":"casi_invisibles","variations":[{"detonante": "interrupcion"}, {"detonante": "presuncion"}, {"detonante": "prisa"}],"is_boss_eligible":true,"worlds_available":[6,7,8,9],"created_at":"2026-05-06T23:37:13.709366+00:00"}');
