INSERT INTO public.archivo_mentalidad_nodes SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_nodes, '{"id":"1.0","world_id":1,"name":"La Ley de los Promedios","technique":null,"order_index":0,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":1,"description":"El fundamento mental de todo el sistema: el éxito no es magia ni talento. Es proporción más volumen.","node_type":"knowledge","conversation_scope":null,"engine_type":"classify","boss_goal":null,"field_mission":null,"practice_script":null}');
INSERT INTO public.archivo_mentalidad_nodes SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_nodes, '{"id":"1.1","world_id":1,"name":"Las Máquinas de Chicles","technique":"El rechazo como matemática, no como fracaso personal.","order_index":1,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":1,"description":"La persistencia no es terquedad — es método. Aprende por qué cambiar de estrategia a mitad del camino es el error más caro.","node_type":"knowledge","conversation_scope":null,"engine_type":"classify","boss_goal":null,"field_mission":null,"practice_script":null}');
INSERT INTO public.archivo_mentalidad_nodes SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_nodes, '{"id":"1.2","world_id":1,"name":"Los 3 Tipos de Día","technique":"Los 3 factores que determinan resultados. Actitud es el multiplicador.","order_index":2,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":1,"description":"Las ventas no avisan cuándo llegan. Aprende a reconocer los días A, B y C — y por qué el C es el que decide tu carrera.","node_type":"knowledge","conversation_scope":null,"engine_type":"classify","boss_goal":null,"field_mission":null,"practice_script":null}');
INSERT INTO public.archivo_mentalidad_nodes SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_nodes, '{"id":"1.3","world_id":1,"name":"KILT: Lógica Sobre Emoción","technique":"El día C (todo al final) es la prueba máxima del vendedor.","order_index":3,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":2,"description":"Todos pierden la actitud. Los grandes la protegen más tiempo y la recuperan más rápido. Este es el sistema para lograrlo.","node_type":"knowledge","conversation_scope":null,"engine_type":"swipe","boss_goal":null,"field_mission":null,"practice_script":null}');
INSERT INTO public.archivo_mentalidad_nodes SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_nodes, '{"id":"1.4","world_id":1,"name":"Controlables vs No Controlables","technique":"Sistema de gestión emocional para el campo.","order_index":4,"is_boss":false,"reps_required":3,"checkpoints":null,"difficulty_level":2,"description":"La energía que gastas en lo que no controlas es energía que le robas a lo que sí. Aprende a distinguirlos en un segundo.","node_type":"knowledge","conversation_scope":null,"engine_type":"classify","boss_goal":null,"field_mission":null,"practice_script":null}');
INSERT INTO public.archivo_mentalidad_nodes SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_nodes, '{"id":"1.5","world_id":1,"name":"BOSS: El Día Difícil","technique":"Energía mental solo en lo que se puede cambiar.","order_index":5,"is_boss":true,"reps_required":3,"checkpoints":null,"difficulty_level":3,"description":"Visita 14 de un día tipo C. El cliente es hielo. Tu única arma: la actitud que este mundo te enseñó a proteger.","node_type":"boss","conversation_scope":"first_impression","engine_type":null,"boss_goal":"Sostener una apertura completa, cálida y sin derrumbe ante un cliente frío y monosilábico — demostrando KILT en vivo: amabilidad constante, cero enganche, y tratar a este cliente como si fuera el primero del día.","field_mission":null,"practice_script":{"notes": "BOSS del Mundo 1. El examen no es técnico — es de temple: KILT pesa 35% y derrumbarse es critical. El Actor es hielo con ablandamiento LENTO (3+ turnos de calidez sostenida) y su techo es neutral-cooperativo, nunca amistoso: el vendedor debe ganar sin la recompensa emocional de un cliente encantado. min_turns 4 obliga a sostener, no solo abrir. Integra M0 completo (estructura, gasman, 10%) — retrieval practice.", "scope": {"skills_in_focus": ["mindset.kilt", "opening.sce", "opening.arranque_sin_disculpa", "opening.estructura_apertura", "mindset.regla_10_por_ciento"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 240, "min_turns_before_evaluation": 4}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio, y hoy estás FRÍO: cansado, desganado, con cero interés en socializar. NO bloqueas ni corres al vendedor (no dices no me interesa ni pides que se vaya) — simplemente eres hielo: respuestas monosilábicas (ajá, sí, puede ser, mmm), tono seco, no haces ninguna pregunta de vuelta, no le das NADA gratis. IMPORTANTE — tu regla de ablandamiento es LENTA: solo si el vendedor sostiene calidez genuina, amabilidad y seguridad durante AL MENOS 3 turnos consecutivos sin derrumbarse, sin volverse él también seco, y sin desesperarse, empiezas a dar respuestas apenas un poco más largas (una frase completa, quizá un dato del negocio). Si el vendedor se apaga, se pone nervioso, se disculpa o abandona la calidez, te mantienes hielo hasta el final. Nunca llegas a ser amistoso — el máximo que alcanzas es neutral cooperativo.", "objective": "El vendedor sostiene una apertura completa y una conversación inicial ante un cliente monosilábico y frío, manteniendo la calidez, amabilidad y seguridad en el texto durante TODOS sus turnos — sin derrumbarse, sin volverse seco él también, sin disculparse ni suplicar atención, y sin mencionar producto. El scope se cubre cuando el vendedor completó su apertura y sostuvo al menos 3-4 turnos de conversación con calidez constante pese a las respuestas mínimas del cliente, logrando que el cliente pase de monosílabos a al menos una respuesta de frase completa."}, "closing": {"message": "Ahí está. Cliente de hielo, visita 14, y tu actitud no se movió un milímetro. Eso es KILT — y eso no se puede fingir. Vamos al desglose."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "se_derrumba", "severity": "critical", "description": "Ante los monosílabos, pierde la actitud: se vuelve seco él también, muestra frustración o desesperación en el texto, reprocha al cliente su frialdad (veo que no está de humor), o abandona la conversación antes de completar su apertura. En este boss, derrumbarse es el fallo central — el examen ES la actitud."}, {"id": "disculpa_inicial", "severity": "major", "description": "Se disculpa o se minimiza, al abrir o durante: perdón por molestarlo, ya veo que anda ocupado, no le quito más tiempo."}, {"id": "pitch_prematuro", "severity": "major", "description": "Menciona producto, empresa o motivo de venta — típicamente como intento desesperado de generar interés ante el hielo."}, {"id": "energia_desalineada", "severity": "minor", "description": "Sobrecompensa el hielo con euforia: exceso de exclamaciones y entusiasmo desbordado ante un cliente visiblemente apagado."}, {"id": "monologo", "severity": "minor", "description": "Llena los silencios del cliente con turnos excesivamente largos."}], "success_criteria": [{"id": "mindset.kilt", "weight": 0.35, "description": "Sostiene amabilidad y calidez textual constante ante la frialdad: sus turnos mantienen tono positivo, cortesía y paciencia de principio a fin, sin volverse cortante, sin sarcasmo, sin reprochar la sequedad del cliente, y sin rendirse antes de tiempo. La consistencia entre TODOS sus turnos es el criterio — un solo turno donde se apaga o se enfría rompe el KILT."}, {"id": "opening.estructura_apertura", "weight": 0.2, "description": "Apertura con estructura completa: saludo + observación específica + inicio de conversación, sin producto ni motivo de venta."}, {"id": "opening.arranque_sin_disculpa", "weight": 0.2, "description": "Seguridad tipo gasman sostenida: sin disculpas ni permisos, ni al abrir ni DESPUÉS, cuando el cliente responde con monosílabos. No se minimiza ante el hielo."}, {"id": "opening.sce", "weight": 0.15, "description": "Energía y calidez en las palabras a lo largo de toda la conversación, no solo el primer turno."}, {"id": "mindset.regla_10_por_ciento", "weight": 0.1, "description": "Calibrado ante el cliente frío: cálido y presente pero SIN euforia — no intenta compensar el hielo del cliente con gritos de entusiasmo. Un paso arriba del cliente, no diez."}]}}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"0e882798-2f0f-4fbc-bb02-d70e5e8d4f00","node_id":"1.0","card_order":1,"card_type":"concept","title":"Lanza una moneda.","body":"¿Probabilidad de que caiga cara? 50%. Pero lánzala 10 veces — rara vez salen 5 y 5.\\n\\nAhora lánzala 1,000 veces. Te acercas muchísimo al 50%.\\n\\nLas ventas funcionan igual: entre más grande el tamaño de la muestra — más conversaciones con la actitud correcta — más aparece tu proporción.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"224802bc-b12a-4820-9675-079e40531508","node_id":"1.0","card_order":2,"card_type":"concept","title":"Tu proporción es personal.","body":"Un vendedor experimentado puede cerrar 1 de cada 5 conversaciones. Uno que empieza, 1 de cada 15. Las dos proporciones GANAN si hay volumen.\\n\\nY aquí está lo poderoso: tu proporción mejora conforme dominas el sistema. Pero solo trabaja para ti si sigues lanzando la moneda.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"4d70c5ec-55ce-4f20-8968-cee0c93ae751","node_id":"1.0","card_order":3,"card_type":"why_it_works","title":"Por qué el sistema le gana al talento","body":"Hay gente con tanta personalidad que vende sin sistema. Pero casi nunca puede REPLICAR su éxito — depende de su inspiración del día.\\n\\nLa habilidad no es confiable día con día. Un sistema es el plano de cada paso: fácil de copiar, fácil de repetir, y funciona aunque no sea tu mejor día. Por eso Closer te enseña sistema, no trucos.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"4bdb0724-ece0-44a0-84e4-1f40db95026e","node_id":"1.0","card_order":4,"card_type":"concept","title":"Cada \\"no\\" tiene precio — y te lo paga a ti.","body":"Si tu proporción es 1 de 10 y tu comisión promedio es $500, cada conversación vale $50 — la cierres o no.\\n\\nCuando entiendes esto, el \\"no\\" deja de doler: es un paso obligatorio del camino al \\"sí\\". No es tu enemigo. Es tu boleto.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, '{"id":"462fbeb0-ab47-4c63-bd5a-77bdab33a79d","node_id":"1.0","card_order":5,"card_type":"cta","title":null,"body":"La Ley de los Promedios solo tiene un requisito: que sigas apareciendo con la actitud correcta. Los siguientes nodos te enseñan exactamente cómo protegerla.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"f8fbc719-de75-4492-95a3-9204f224ace7","node_id":"1.1","card_order":1,"card_type":"concept","title":"Tres máquinas. 100 chicles cada una.","body":"En cada máquina: 97 chicles rojos y 3 verdes. Cada girada cuesta $1. Tienes 100 monedas. Tu misión: sacar los 3 verdes.\\n\\n¿Cuál es la jugada inteligente?","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"c54be27f-4127-450d-be9d-1f89fcd561af","node_id":"1.1","card_order":2,"card_type":"concept","title":"Quedarte en UNA máquina.","body":"Si giras 100 veces en la misma máquina, los 3 verdes salen garantizado. Cada rojo que sale te ACERCA matemáticamente al verde.\\n\\nPero si a la girada 40 te desesperas y cambias de máquina... reseteaste tu progreso. Los rojos que ya sacaste no cuentan en la máquina nueva. Puedes quedarte sin monedas antes de encontrar un solo verde.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"8bf31136-3ccd-40e5-8a3e-9802fc1df8ff","node_id":"1.1","card_order":3,"card_type":"why_it_works","title":"El campo es una máquina que no puedes ver por dentro.","body":"La diferencia cruel: en la máquina de chicles VES cuántos rojos van saliendo. En el campo, no. Debes seguir girando a ciegas, confiando en que tu proporción va a aparecer.\\n\\nPor eso cambiar de \\"máquina\\" — alterar tu discurso, tu ritmo o tu actitud a mitad del día porque \\"no está funcionando\\" — es resetear un progreso que no puedes ver pero que es real.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"155c8608-433f-4dce-87d9-3796cff647a4","node_id":"1.1","card_order":4,"card_type":"concept","title":"Qué significa \\"no cambiar de máquina\\"","body":"No es terquedad ciega. Es mantener las tres cosas que hacen funcionar tu proporción: tu discurso (el sistema que estás aprendiendo), tu ritmo (seguir tocando puertas) y tu actitud (la misma energía en la conversación 1 que en la 20).\\n\\nLos ajustes al sistema se hacen ENTRE días con datos — no a media tarde por frustración.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"e901f584-a243-4d6b-b1fb-181c774c92bd","node_id":"1.1","card_order":5,"card_type":"cta","title":null,"body":"Cada rojo te acerca al verde. La pregunta nunca es \\"¿funcionará?\\" — es \\"¿vas a seguir girando hasta que salga?\\"","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"01c0df64-592f-46e5-8dcf-178838073bf0","node_id":"1.2","card_order":1,"card_type":"concept","title":"La LDP te dice CUÁNTO. Nunca te dice CUÁNDO.","body":"La Ley de los Promedios garantiza que hablando con suficiente gente, con el discurso y la actitud correctos, los resultados llegan.\\n\\nLo que no te dice es en qué momento del día van a llegar. Y ahí es donde la mayoría pierde.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"13eaafc9-f4b3-491b-95d4-10d2c9ea367c","node_id":"1.2","card_order":2,"card_type":"concept","title":"Día tipo A","body":"X X O X O X X X O X X O X X X\\n\\nLas ventas llegan temprano y repartidas. Mantener la actitud es fácil — el día te la regala. Cualquiera es buen vendedor en un día A.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"d059e41e-640f-4387-91fe-be622e1a1af4","node_id":"1.2","card_order":3,"card_type":"concept","title":"Día tipo B","body":"X X X X X X O X X X O O X X O\\n\\nLas ventas llegan esporádicas. Hay rachas secas que incomodan, pero no te quiebran. El día B te prueba un poco — y la mayoría lo sobrevive.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"876277f2-a389-44e5-afe1-320d73e195da","node_id":"1.2","card_order":4,"card_type":"concept","title":"Día tipo C","body":"X X X X X X X X X X X O O O O\\n\\nTodo llega al FINAL. Once \\"no\\" seguidos antes del primer \\"sí\\".\\n\\nEste día es la verdadera prueba: ¿tienes fe en el sistema, en el producto y en ti mismo? El que se rinde a la visita 9 de un día C perdió TODAS las ventas del día — estaban en las últimas horas.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"8f5c452c-2600-4e43-a877-ae0be96b7668","node_id":"1.2","card_order":5,"card_type":"why_it_works","title":"Por eso tu actitud debe estar lista TODO el día.","body":"No sabes qué tipo de día es hoy hasta que termina. Tu cliente positivo puede aparecer en la conversación 2... o en la 14.\\n\\nSi llegas a la 14 con la energía apagada por los 13 \\"no\\" anteriores, vas a quemar el \\"sí\\" que el día te tenía guardado. Los resultados más replicables son de quien trata la conversación 14 exactamente como la 1.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, '{"id":"61850478-8a5b-42b5-b201-9e7f4b741189","node_id":"1.2","card_order":6,"card_type":"cta","title":null,"body":"No puedes elegir qué día te toca. Puedes elegir con qué actitud llegas a cada conversación. Eso es lo único que el día no controla.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"f85f050d-f1ab-498c-9ece-5fe0ac688b2d","node_id":"1.3","card_order":1,"card_type":"concept","title":"Perder la actitud es normal. Quedarte sin ella, no.","body":"A todos les pasa: el cliente grosero, la racha de puertas cerradas, el pedido cancelado. La diferencia entre los vendedores exitosos y el resto no es que nunca pierden la actitud — es que la protegen más tiempo y la recuperan más rápido.\\n\\nLa clave: volverse más lógico que emocional. Para eso existe KILT.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"325ac4fe-7fd2-4146-a4f0-5e313eee24f5","node_id":"1.3","card_order":2,"card_type":"concept","title":"K — Mátalos con Amabilidad","body":"Kill them with kindness. Siempre amable, sin importar la actitud del otro.\\n\\nNo es debilidad — es control. El que responde grosería con grosería le regaló el control de su día a un extraño. El que responde con amabilidad se queda con su energía intacta y sale de la conversación siendo el mismo que entró.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"ca3b505e-902b-49b5-b522-2ee2170d6d46","node_id":"1.3","card_order":3,"card_type":"concept","title":"I — Indiferencia · SW3","body":"Algunos comprarán. Algunos no. ¿Y qué?\\n\\nSome Will, Some Won''t, So What — SW3. Estás emocionado por tu producto y por la persona, pero indiferente a si esta persona en particular compra. Tienes cien clientes más por conocer. El resultado de UNA conversación no define nada.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"49ce5025-1b28-43ab-95f0-1d54fae3c89c","node_id":"1.3","card_order":4,"card_type":"concept","title":"L — Ley de los Promedios · T — Todos como el primero","body":"L: Confía en los números. Ya sabes que la proporción aparece si sigues girando.\\n\\nT: Trata a cada persona como si fuera tu primera del día. La señora de la visita 14 no tiene la culpa de los 13 \\"no\\" anteriores — y no sabes si ella es tu cliente positivo. Nunca sabes cuándo encontrarás a tu comprador.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"a0c75b24-cd2e-4074-852c-7696dbe9fa56","node_id":"1.3","card_order":5,"card_type":"why_it_works","title":"KILT saca la emoción de la ecuación.","body":"Si dejas a cada persona mejor de como la encontraste (K), permaneces indiferente al resultado individual (I), confías en los números (L) y tratas a todos como el primero (T) — eliminaste la emoción de la ecuación y pusiste lógica en su lugar.\\n\\nY la lógica no se cansa, no se ofende y no se desanima. Por eso protege tu actitud mejor que cualquier motivación.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, '{"id":"a93829ea-8de6-4da2-b5d8-531c1995d146","node_id":"1.3","card_order":6,"card_type":"cta","title":null,"body":"La motivación se acaba a media tarde. La lógica no. KILT es cómo conviertes tu actitud en un sistema — igual que todo lo demás en Closer.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"a8f06c05-8667-4f13-8cd3-a445c968013a","node_id":"1.4","card_order":1,"card_type":"concept","title":"El deporte favorito del vendedor promedio: las excusas.","body":"\\"Está lloviendo.\\" \\"Es quincena y no hay dinero.\\" \\"El territorio está quemado.\\" \\"Hoy la gente anda de malas.\\"\\n\\nTodas pueden ser ciertas. Y ninguna te sirve de nada — porque no controlas ni una sola.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"16b50bb2-f83e-47e9-bf9d-6431e544c658","node_id":"1.4","card_order":2,"card_type":"concept","title":"La regla es brutal y simple:","body":"Si no lo puedes controlar, no lo piensas ni hablas de ello.\\n\\nNo es negación — es administración de energía. Cada minuto quejándote del clima es un minuto de energía que le robaste a tu siguiente conversación. Y tu siguiente conversación SÍ la controlas.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"45fdb4a3-8f55-4160-ba8c-682eefa71639","node_id":"1.4","card_order":3,"card_type":"why_it_works","title":"Lo que SÍ controlas gana solito.","body":"Tres cosas están 100% en tus manos: a cuánta gente ves hoy, qué tan buena es cada conversación, y qué impresión dejas en cada persona.\\n\\nFíjate algo: esas tres cosas son exactamente las que hacen funcionar tu Ley de los Promedios. Todo lo que controlas alimenta tu proporción. Todo lo que no controlas... no la toca. La lluvia no cambia tu proporción — rendirte por la lluvia, sí.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"61b111b9-e9db-4796-a98c-34824d0c6629","node_id":"1.4","card_order":4,"card_type":"concept","title":"El test del segundo","body":"Ante cualquier situación del campo, pregúntate: \\"¿puedo cambiarlo?\\"\\n\\n¿El cliente canceló el pedido? No controlas su decisión — controlas cómo consolidas al siguiente. ¿Tráfico? No controlas el tráfico — controlas a qué hora saliste. ¿Se te olvidó el catálogo? Eso era 100% tuyo — corrígelo mañana y suéltalo hoy.\\n\\nCambiable → actúa. No cambiable → suéltalo. Un segundo, siguiente conversación.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, '{"id":"cd7adb64-d3d2-412c-b53b-ad8f16c15222","node_id":"1.4","card_order":5,"card_type":"cta","title":null,"body":"Tu energía es tu herramienta más cara. A partir de hoy, ni un peso de ella en cosas que no puedes cambiar.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_cards SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_cards, E'{"id":"6c4822ad-e125-4720-93d5-5dd2eecfd39c","node_id":"1.5","card_order":1,"card_type":"concept","title":"El segundo Boss.","body":"Es la visita 14 de un día tipo C. Llevas trece \\"no\\". Y este cliente es hielo puro: monosílabos, cero interés, nada gratis.\\n\\nNo te va a correr. Pero tampoco te va a ayudar.\\n\\nTu examen no es venderle — es que tu actitud no se mueva un milímetro. Amabilidad constante. Cero enganche. Como si fuera tu primera visita del día. Eso es KILT, y no se puede fingir.","flip_back_text":null,"created_at":"2026-07-03T21:23:19.900653+00:00","card_content_type":"static","audience":null,"skill_ids":[]}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, E'{"id":"66d24330-f8e9-4350-a7d2-df953e7b6fc5","node_id":"1.0","question_order":1,"question_text":"Marco lleva 8 conversaciones hoy y cero ventas. Está pensando: \\"hoy no es mi día, mejor me regreso.\\" ¿Qué diría la Ley de los Promedios?","option_a":"Tiene razón — cuando no fluye, no fluye.","option_b":"Sus 8 \\"no\\" lo tienen más cerca del \\"sí\\" que cuando empezó el día.","option_c":"Debería cambiar su discurso completamente — algo está fallando.","option_d":null,"correct_option":"B","explanation_correct":"Exacto. Si su proporción es 1:10, está a 2 conversaciones de su promedio. Regresarse ahora es lanzar la moneda 8 veces y rendirse antes de que caiga cara.","explanation_wrong":"Piénsalo con la moneda: ¿8 cruces seguidas significan que la moneda está rota? No — significan que la cara está cada vez más cerca. Rendirse a media muestra es el error más caro en ventas.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, '{"id":"44277a81-ad9c-4f6a-a854-82953abac1fb","node_id":"1.0","question_order":2,"question_text":"¿Por qué un vendedor con sistema le gana a largo plazo a uno con puro talento?","option_a":"Porque el talento no existe en ventas.","option_b":"Porque el sistema se puede repetir día con día, aunque no sea tu mejor día.","option_c":"Porque los clientes desconfían de los vendedores talentosos.","option_d":null,"correct_option":"B","explanation_correct":"Esa es la clave. El talento depende de la inspiración del día. El sistema es un plano: paso a paso, replicable, confiable. Funciona el lunes brillante y el jueves gris.","explanation_wrong":"El talento sí existe — el problema es que no es confiable ni replicable. El del sistema sabe exactamente qué hizo bien y puede repetirlo mañana. El del talento, cuando falla, no sabe por qué.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, E'{"id":"7a2dff31-c310-4319-82db-7f76cb850846","node_id":"1.0","question_order":3,"question_text":"Si tu proporción es 1 de cada 10 y tu comisión promedio es $500, ¿cuánto \\"vale\\" cada conversación — incluyendo las que terminan en no?","option_a":"Nada, si no cierras no ganas.","option_b":"$500 — solo la que cierra vale.","option_c":"$50 — cada conversación es un paso pagado hacia el cierre.","option_d":null,"correct_option":"C","explanation_correct":"Así se ve el campo con ojos de sistema: $500 entre 10 conversaciones = $50 cada una, la cierres o no. Cada \\"no\\" te está pagando. Solo tienes que cobrarlo completando el volumen.","explanation_wrong":"Haz la cuenta: 10 conversaciones producen 1 venta de $500. Eso significa que cada conversación — incluyendo los 9 \\"no\\" — aportó $50 a ese cierre. El \\"no\\" no es pérdida: es inversión.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, E'{"id":"a8e9f32e-32ef-453d-88aa-d96980ce673d","node_id":"1.1","question_order":1,"question_text":"Sandra lleva 15 visitas sin cerrar. Decide improvisar un discurso completamente nuevo para las últimas 5 visitas del día \\"a ver si así\\". ¿Qué acaba de hacer según la teoría?","option_a":"Adaptarse con inteligencia — hay que ser flexible.","option_b":"Cambiar de máquina a mitad del juego — reseteó un progreso que no puede ver.","option_c":"Nada grave — el discurso no afecta la proporción.","option_d":null,"correct_option":"B","explanation_correct":"Exacto. Sus 15 \\"rojos\\" la tenían cerca del verde — y con el cambio, su proporción se resetea con un discurso no probado. Los ajustes se hacen entre días con datos, no a media tarde por frustración.","explanation_wrong":"Cuidado: flexibilidad y frustración se parecen mucho a media tarde. Cambiar el sistema completo por 15 visitas sin cierre es abandonar la máquina justo cuando los verdes se acercan. Ajusta con datos, entre días — no con desesperación, entre visitas.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, '{"id":"f8d07d62-646d-40ba-a70e-8329f3c1a7d3","node_id":"1.1","question_order":2,"question_text":"¿Cuál es la diferencia más difícil entre la máquina de chicles y el campo real?","option_a":"Que en el campo las giradas no cuestan dinero.","option_b":"Que en el campo no puedes VER cuántos rojos van saliendo — giras a ciegas.","option_c":"Que en el campo no existen los chicles verdes.","option_d":null,"correct_option":"B","explanation_correct":"Esa es la parte que separa a los buenos de los grandes: seguir girando con la misma calidad sin poder ver el contador. La fe en el sistema sustituye al contador visible.","explanation_wrong":"Los verdes sí existen — tus clientes positivos están ahí. Y las giradas sí cuestan: tiempo y energía. Lo verdaderamente difícil es que giras sin ver el contador. Por eso este mundo entrena tu mentalidad antes que tu técnica.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, E'{"id":"de4a9c93-c899-4b8e-a220-cb040a60e00f","node_id":"1.1","question_order":3,"question_text":"\\"No cambiar de máquina\\" significa mantener 3 cosas iguales durante el día. ¿Cuáles?","option_a":"Tu ruta, tu horario y tu ropa.","option_b":"Tu discurso, tu ritmo y tu actitud.","option_c":"Tu producto, tu precio y tu territorio.","option_d":null,"correct_option":"B","explanation_correct":"Discurso, ritmo y actitud — las tres cosas que hacen funcionar tu proporción. Si las mantienes, cada \\"no\\" cuenta a tu favor. Si las alteras por frustración, reinicias el juego.","explanation_wrong":"Las tres que afectan tu proporción directamente: el discurso (qué dices), el ritmo (con cuánta gente hablas) y la actitud (con qué energía). Esas son tu máquina. Lo demás son detalles.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, '{"id":"c99c3e55-7512-4b6b-99d4-cbf4d7ddff88","node_id":"1.2","question_order":1,"question_text":"Son las 4pm. Roberto lleva 11 visitas y cero ventas. Le quedan 4 visitas en su ruta. Si hoy es un día tipo C, ¿dónde están sus ventas?","option_a":"Ya las perdió — un día así no se recupera.","option_b":"En las 4 visitas que le quedan.","option_c":"En el día de mañana.","option_d":null,"correct_option":"B","explanation_correct":"Exacto — así es el día C: todo llega al final. Sus 4 últimas visitas pueden traer las 4 ventas del día. La única forma de perderlas es llegar a ellas con la actitud quemada... o no llegar.","explanation_wrong":"Mira la secuencia del día C: X X X X X X X X X X X O O O O. Las ventas del día C existen — están amontonadas al final. Rendirse a las 4pm en un día C es dejar el dinero exactamente donde estaba a punto de aparecer.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, '{"id":"c4dc18cc-3bc8-4d7d-a03e-dda93ad7f1f3","node_id":"1.2","question_order":2,"question_text":"¿Por qué el día tipo C produce los vendedores con resultados más replicables?","option_a":"Porque tienen suerte al final del día.","option_b":"Porque quien sobrevive el día C demostró fe en el sistema cuando nada la justificaba — y esa actitud funciona en cualquier tipo de día.","option_c":"Porque los días C tienen más ventas totales que los A.","option_d":null,"correct_option":"B","explanation_correct":"Esa es la lección central. El día A cualquiera brilla. El que mantiene su energía intacta hasta la visita 14 de un día C tiene un temple que ningún tipo de día le puede quitar — por eso sus resultados se repiten.","explanation_wrong":"El día C no tiene más ventas ni más suerte — tiene la misma proporción, repartida cruel. Lo que produce es temple: quien lo sobrevive con actitud intacta ya no depende del tipo de día. Eso es replicabilidad.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, E'{"id":"d5ad45ca-03d3-49b4-be10-a582c269408e","node_id":"1.2","question_order":3,"question_text":"Un vendedor dice: \\"yo agarro el ritmo como a la tercera venta, las primeras visitas del día son de calentamiento.\\" ¿Cuál es el problema?","option_a":"Ninguno — todos necesitan calentar.","option_b":"Que si hoy es día C, sus ventas están al final y su \\"calentamiento\\" va a quemar visitas reales toda la mañana.","option_c":"Que debería calentar antes de salir de casa.","option_d":null,"correct_option":"B","explanation_correct":"Exacto. Cada visita \\"de calentamiento\\" es una moneda gastada con actitud a medias — y no sabes si la visita 3 de hoy era tu cliente positivo. La actitud lista desde la conversación 1 no es perfeccionismo: es matemáticas.","explanation_wrong":"El problema es que las visitas no saben que son \\"de calentamiento\\". Si su cliente positivo aparece a las 9am y él anda a media energía, lo quemó. La actitud debe estar lista desde la primera — porque la LDP no avisa cuándo.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, E'{"id":"2c220bed-9b40-4b4c-a48b-6add943a3bbb","node_id":"1.3","question_order":1,"question_text":"Un cliente le grita a Paola: \\"¡Ya les dije mil veces que no vengan!\\" Paola sonríe y responde: \\"Tiene toda la razón, disculpe. Que tenga excelente día.\\" y sigue su ruta tranquila. ¿Qué acaba de hacer?","option_a":"Perdió la venta por rendirse tan rápido.","option_b":"Aplicó K: respondió con amabilidad, conservó SU energía y siguió con su día intacta.","option_c":"Se dejó humillar — debió defenderse.","option_d":null,"correct_option":"B","explanation_correct":"Eso es matar con amabilidad. Nota lo importante: no lo hizo por el cliente — lo hizo por ELLA. Su energía sigue intacta para las visitas que quedan. El grosero se quedó con su enojo; Paola se llevó su día.","explanation_wrong":"Ese cliente era una luz roja gritando — no había venta que perder. Lo único en juego era la energía de Paola para el resto de su día. Defenderse o engancharse se lo habría costado. Amabilidad + salida rápida = victoria.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, E'{"id":"41cd0163-b66f-4515-8cb1-382b18245b0e","node_id":"1.3","question_order":2,"question_text":"¿Qué significa SW3?","option_a":"Sell With 3 Words — vende con tres palabras.","option_b":"Some Will, Some Won''t, So What — algunos sí, algunos no, ¿y qué?","option_c":"Smile, Wave, Walk — sonríe, saluda y camina.","option_d":null,"correct_option":"B","explanation_correct":"Algunos comprarán, algunos no — ¿y qué? Es la indiferencia sana: emocionado por tu producto, indiferente al resultado de UNA conversación. Tienes cien clientes más por conocer.","explanation_wrong":"SW3 = Some Will, Some Won''t, So What. Es la I de KILT en tres letras: el resultado de una conversación individual no define tu día, tu proporción ni tu carrera. Libérate de cada \\"no\\" en el momento en que lo escuchas.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, E'{"id":"83d919af-f022-4aba-89ee-e0ac1343f628","node_id":"1.3","question_order":3,"question_text":"Es la visita 14. Diego lleva 13 \\"no\\". Toca la puerta pensando \\"seguro este también me bate.\\" ¿Qué letra de KILT está rompiendo?","option_a":"La K — está siendo grosero.","option_b":"La T — no está tratando a esta persona como si fuera su primera del día.","option_c":"La L — dejó de confiar en los números.","option_d":null,"correct_option":"B","explanation_correct":"Exacto — la T. Esta persona no tiene la culpa de los 13 anteriores, y estadísticamente podría ser SU cliente del día. Si Diego entra derrotado, va a quemar al positivo que la LDP le tenía guardado.","explanation_wrong":"Fíjate en el detalle: Diego no fue grosero (K intacta) y sigue tocando puertas (L más o menos viva). Lo que rompió es la T — cargarle a la visita 14 el peso de las 13 anteriores. Cada persona merece tu primera versión, no la 14ª.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, E'{"id":"272675f9-75e2-46de-8f93-a8631f0aa489","node_id":"1.4","question_order":1,"question_text":"Empieza a llover fuerte a media ruta. Luis piensa: \\"con esta lluvia nadie compra, mejor lo dejo para mañana.\\" ¿Qué está haciendo?","option_a":"Siendo realista — la lluvia sí afecta las ventas.","option_b":"Gastando su energía y su día en algo que no controla, en lugar de enfocarse en lo que sí: seguir viendo gente.","option_c":"Protegiendo su salud, que es lo primero.","option_d":null,"correct_option":"B","explanation_correct":"La lluvia no la controla — su ritmo sí. Puede ajustar la ruta, visitar negocios techados, seguir girando la manivela. La lluvia no cambia su proporción; rendirse por la lluvia la destruye completa.","explanation_wrong":"Puede que la lluvia afecte algo — pero ese \\"algo\\" no está en sus manos, y su ritmo sí. El vendedor de sistema ajusta (negocios techados, ruta distinta) y sigue sumando conversaciones. El de excusas pierde el día entero por algo que ni piensa cambiar.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, '{"id":"a514d4c8-634a-45a9-965f-f0952cef6a8b","node_id":"1.4","question_order":2,"question_text":"¿Cuáles son las tres cosas que un vendedor SÍ controla completamente?","option_a":"El clima, la economía y el humor de los clientes.","option_b":"Cuánta gente ve, qué tan buenas son sus conversaciones y qué impresión deja.","option_c":"Su territorio, sus precios y la competencia.","option_d":null,"correct_option":"B","explanation_correct":"Esas tres — y no es casualidad que sean exactamente las que alimentan la Ley de los Promedios. Volumen, calidad e impresión: todo tu éxito vive en cosas que están 100% en tus manos.","explanation_wrong":"Clima, economía, humor ajeno, precios, competencia — nada de eso está en tus manos. Lo que sí: a cuánta gente ves, qué tan bien conversas y qué impresión dejas. Y con esas tres, la LDP hace el resto.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
INSERT INTO public.archivo_mentalidad_quiz SELECT * FROM json_populate_record(NULL::public.archivo_mentalidad_quiz, '{"id":"9861127b-d4e3-4031-a051-52670518ff20","node_id":"1.4","question_order":3,"question_text":"A Carmen se le canceló un pedido grande que ya daba por cerrado. ¿Cuál es la respuesta de sistema?","option_a":"Llamar al cliente tres veces para insistir y reclamar qué pasó.","option_b":"Analizar si algo de SU proceso fue mejorable (¿consolidó bien?), corregirlo, y soltar lo que no dependía de ella — siguiente conversación.","option_c":"Contárselo a todos sus compañeros para desahogarse el resto del día.","option_d":null,"correct_option":"B","explanation_correct":"Exactamente. La decisión final del cliente no la controla — pero su consolidación sí. Extrae la lección de lo controlable, corrige, y suelta el resto en un segundo. Su energía la necesitan las visitas que siguen.","explanation_wrong":"Insistir con reclamos o rumiar la cancelación todo el día son energía en lo incambiable. Lo de sistema: ¿hubo algo mejorable en MI proceso? Si sí, se corrige. Lo demás se suelta — la energía la necesitan las conversaciones que vienen.","created_at":"2026-07-03T21:23:19.900653+00:00"}');
